import { Component, OnInit, Output, EventEmitter } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { FieldDefinition, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { IItemId } from '../../core/itemActionHandler';

import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-admin-update-user-properties',
  templateUrl: './admin-update-user-properties.component.html',
  styleUrls: ['./admin-update-user-properties.component.scss'],
})
export class AdminUpdateUserPropertiesComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  fieldName: FieldDefinition;
  fieldEmail: FieldDefinition;

  name = '';
  email = '';

  importErrors = [];

  constructor(
    public sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private translateService: TranslateService,
    private toastr: ToastrService
  ) {}

  ngOnInit(): void {
    this.createFields();
  }

  createFields = (): void => {
    this.fieldName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('update-name-email.name'),
      placeholder: this.translateService.instant('update-name-email.email'),
      required: true,
    });

    this.fieldEmail = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('update-name-email.email'),
      placeholder: this.translateService.instant('update-name-email.email'),
      datasource: this.sharedDataService.extraParameters['email'],
      required: true,
    });

    this.name = this.sharedDataService.extraParameters['name'];
    this.email = this.sharedDataService.extraParameters['email'];
  };

  close = (): void => {
    this.closeModal.emit();
    this.spinnerService.hide();
  };

  onSubmit = () => {
    this.spinnerService.show(
      this.translateService.instant('update-name-email.Updating-name-email'),
      this.getSpinnerElement()
    );

    this.importErrors = [];

    const items: IItemId[] = [];

    const args = new MetaDataCollection();

    args.set('userId', this.sharedDataService.extraParameters['userId']);
    args.set('name', this.name);
    args.set('email', this.email);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      items,
      args,
      this.onSucceeded,
      this.onFail
    );
  };

  onSucceeded = () => {
    this.close();
    this.sharedDataService.actionHandler.reload.emit(false);
  };

  onFail = (err) => {
    this.importErrors.push(err);
  };

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.update-name-email .nsm-content') as HTMLElement;
  }
}
