type FontSize = { key: string; value: string };
export abstract class FontSizes {
  static readonly defaultSizePx = '18px';
  static readonly legacySizes: FontSize[] = [
    { key: '10', value: '10px' },
    { key: '14', value: '14px' },
    { key: '18', value: '18px' },
    { key: '22', value: '22px' },
    { key: '26', value: '26px' },
    { key: '32', value: '32px' },
  ];
  static readonly supportedSizes: FontSize[] = [
    { key: '8', value: '8px' },
    { key: '9', value: '9px' },
    { key: '10', value: '10px' },
    { key: '11', value: '11px' },
    { key: '12', value: '12px' },
    { key: '14', value: '14px' },
    { key: '16', value: '16px' },
    { key: '18', value: '18px' },
    { key: '20', value: '20px' },
    { key: '22', value: '22px' },
    { key: '24', value: '24px' },
    { key: '26', value: '26px' },
    { key: '28', value: '28px' },
    { key: '32', value: '32px' },
    { key: '36', value: '36px' },
    { key: '48', value: '48px' },
    { key: '72', value: '72px' },
  ];

  static legacyToModern = (legacy: FontSize): FontSize => {
    let modern =
      this.supportedSizes.find((fontSize) => fontSize.value === legacy.value) ??
      this.supportedSizes.find((fontSize) => fontSize.value === this.defaultSizePx);

    return modern;
  };
}

