import { Injectable, EventEmitter } from '@angular/core';
import { Location } from '@angular/common';
import { HydraApiService } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';
import { SessionStorageService } from './session-storage.service';

export enum HelpType {
  Url = 0,
  UplandAssist = 1,
}

export class BrandDetails {
  public loginLogoUrl: string;
  public titleLogoUrl: string;
  public primaryColor: string;
  public secondaryColor: string;
  public favIconUrl: string;
  public titleText: string;
  public description: string;
  public privacyPolicyURL: string;
  public countryCode: string;
  public contactUsUrl: string;
}

export class RedirectToLegacy {
  public url: string;
}

@Injectable({
  providedIn: 'root',
})
export class BrandingService {
  private brand = '';
  public onBrandingChanged = new EventEmitter<string>();

  private brandDetails: BrandDetails;
  public onBrandDetailsUpdated = new EventEmitter<BrandDetails>();

  constructor(
    private hydraApi: HydraApiService,
    private sessionStorageService: SessionStorageService,
    private location: Location
  ) {}

  public initializeBrandDetails = (): Promise<void> => {
    return this.hydraApi.getBrandingDetails(this.getDomain(), (bd: BrandDetails) => {
      this.brandDetails = bd;
      this.setBrandColors();
      this.onBrandDetailsUpdated.next(bd);

      document.title = bd.titleText;
      if (bd?.favIconUrl) this.changeFavIcon(bd.favIconUrl);
    });
  };

  private setBrandColors = (): void => {
    if (this.brandDetails?.primaryColor) {
      document.documentElement.style.setProperty('--brand-primary-color', this.brandDetails.primaryColor);
    }

    if (this.brandDetails?.secondaryColor) {
      document.documentElement.style.setProperty('--brand-secondary-color', this.brandDetails.secondaryColor);
    }
  };

  changeFavIcon = (url: string): void => {
    const favIconId = 'dynamic-favicon';

    const link = document.createElement('link');
    link.id = favIconId;
    link.rel = 'shortcut icon';
    link.href = url;

    const oldLink = document.getElementById(favIconId);
    if (oldLink) document.head.removeChild(oldLink);

    document.head.appendChild(link);
  };

  public getBrandDetails = (): BrandDetails => this.brandDetails;

  private getDomain = (): string => {
    if (this.isBranded()) return `${this.get()}.mobile.uplandcapture.com`;

    const domain = this.sessionStorageService.getLandingDomain();
    if (domain) return domain;

    return 'uplandcapture.com';
  };

  public set = (brand: string): void => {
    this.brand = brand;
    this.onBrandingChanged.emit(this.brand);
  };

  public setBrandFromUrl = (url: string): void => {
    url = url.replace('/mobile', '');
    if (
      (url == '/accuroute' || decodeURIComponent(url).startsWith('/login?returnUrl=/mobile/accuroute')) &&
      this.brand != 'ar'
    ) {
      this.set('ar');
      return;
    }

    if (
      (url == '/hpcr' || decodeURIComponent(url).startsWith('/login?returnUrl=/mobile/hpcr')) &&
      this.brand != 'hpcr'
    ) {
      this.set('hpcr');
      return;
    }

    if (!this.brand) this.set('');
  };

  public get = (): string => this.brand;

  public isBranded = (): boolean => this.brand != '';

  private setManifestJSON() {
    let manifestData;

    if (this.brand === '') {
      manifestData = this.getManifest();
    } else if (this.brand === 'ar') {
      manifestData = this.arManifest;
    } else if (this.brand === 'hpcr') {
      manifestData = this.hpcrManifest;
    }

    const stringManifest = JSON.stringify(manifestData);
    const blob = new Blob([stringManifest], { type: 'application/json' });
    const manifestURL = URL.createObjectURL(blob);
    const manifestLinkTag = document.getElementById('manifest-placeholder');
    manifestLinkTag.setAttribute('href', manifestURL);
    const themeTag = document.getElementById('theme-color');
    themeTag.setAttribute('content', manifestData.theme_color);
  }

  getManifest = () => {
    if (!this.brandDetails) return;

    const favIcon =
      this.brandDetails.favIconUrl && this.brandDetails.favIconUrl != '/favicon.png?v1.0'
        ? encodeURIComponent(this.brandDetails.favIconUrl)
        : '';

    return {
      name: this.brandDetails.titleText,
      short_name: this.brandDetails.titleText,
      description: this.brandDetails.description,
      orientation: 'portrait',
      icons: [
        {
          src: favIcon
            ? `${origin}/api/brand/GetIcon?size=72&iconUrl=${favIcon}`
            : `${origin}/assets/pwa-icons/Artboard-72x72-ic.png`,
          sizes: '72x72',
          type: 'image/png',
        },
        {
          src: favIcon
            ? `${origin}/api/brand/GetIcon?size=96&iconUrl=${favIcon}`
            : `${origin}/assets/pwa-icons/Artboard-96x96-ic.png`,
          sizes: '96x96',
          type: 'image/png',
        },
        {
          src: favIcon
            ? `${origin}/api/brand/GetIcon?size=144&iconUrl=${favIcon}`
            : `${origin}/assets/pwa-icons/Artboard-144x144-ic.png`,
          sizes: '144x144',
          type: 'image/png',
        },
        {
          src: favIcon
            ? `${origin}/api/brand/GetIcon?size=152&iconUrl=${favIcon}`
            : `${origin}/assets/pwa-icons/Artboard-152x152-ic.png`,
          sizes: '152x152',
          type: 'image/png',
          purpose: 'maskable',
        },
        {
          src: favIcon
            ? `${origin}/api/brand/GetIcon?size=192&iconUrl=${favIcon}`
            : `${origin}/assets/pwa-icons/Artboard-192x192-ic.png`,
          sizes: '192x192',
          type: 'image/png',
        },
        {
          src: favIcon
            ? `${origin}/api/brand/GetIcon?size=512&iconUrl=${favIcon}`
            : `${origin}/assets/pwa-icons/Artboard-512x512-ic.png`,
          sizes: '512x512',
          type: 'image/png',
        },
      ],
      start_url: origin + (this.isInterFaxMobileLogin() ? '/fax-mobile' : '/mobile'),
      display: 'standalone',
      background_color: this.brandDetails.primaryColor ? this.brandDetails.primaryColor : '#ffffff',
      theme_color: this.brandDetails.secondaryColor ? this.brandDetails.secondaryColor : 'rgb(0,144,202)',
    };
  };

  get hpcrManifest() {
    return {
      name: 'HPCR',
      short_name: 'HPCR',
      description: 'Upland HP Capture And Route Mobile',
      orientation: 'portrait',
      icons: [
        {
          src: origin + '/assets/pwa-icons/Artboard-72x72-hpcr.png',
          sizes: '72x72',
          type: 'image/png',
        },
        {
          src: origin + '/assets/pwa-icons/Artboard-96x96-hpcr.png',
          sizes: '96x96',
          type: 'image/png',
        },
        {
          src: origin + '/assets/pwa-icons/Artboard-144x144-hpcr.png',
          sizes: '144x144',
          type: 'image/png',
        },
        {
          src: origin + '/assets/pwa-icons/Artboard-152x152-hpcr.png',
          sizes: '152x152',
          type: 'image/png',
        },
      ],
      start_url: origin + '/hpcr',
      display: 'standalone',
      background_color: '#ffffff',
      theme_color: 'rgb(0,144,202)',
    };
  }

  get arManifest() {
    return {
      name: 'AccuRoute Capture',
      short_name: 'AccuRoute Capture',
      description: 'Upland AccuRoute Capture',
      orientation: 'portrait',
      icons: [
        {
          src: origin + '/assets/pwa-icons/Artboard-72x72-ar.png',
          sizes: '72x72',
          type: 'image/png',
        },
        {
          src: origin + '/assets/pwa-icons/Artboard-96x96-ar.png',
          sizes: '96x96',
          type: 'image/png',
        },
        {
          src: origin + '/assets/pwa-icons/Artboard-144x144-ar.png',
          sizes: '144x144',
          type: 'image/png',
        },
        {
          src: origin + '/assets/pwa-icons/Artboard-152x152-ar.png',
          sizes: '152x152',
          type: 'image/png',
        },
      ],
      start_url: origin + '/accuroute',
      display: 'standalone',
      background_color: '#ffffff',
      theme_color: 'rgb(0,144,202)',
    };
  }

  private setTouchAndSplashScreenIconsForIos() {
    let origin = location.origin;
    let brandId: string;

    if (this.brand === '') {
      if (!this.brandDetails.favIconUrl || this.brandDetails.favIconUrl == '/favicon.png?v1.0') brandId = 'ic';
    } else if (this.brand === 'ar') {
      brandId = 'ar';
    } else if (this.brand === 'hpcr') {
      brandId = 'hpcr';
    }

    const favIcon = encodeURIComponent(this.brandDetails.favIconUrl);

    let href = brandId
      ? `/assets/pwa-icons/touch-icon-iphone-${brandId}.png`
      : `/api/brand/GetIcon?size=72x72&iconUrl=${favIcon}`;
    const defaultTouchIconLinkTag = document.getElementById('pwa-icon-ios-default-placeholder');
    defaultTouchIconLinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/Artboard-72x72-${brandId}.png`
      : `/api/brand/GetIcon?size=72x72&iconUrl=${favIcon}`;
    const TouchIcon72x72LinkTag = document.getElementById('pwa-icon-ios-72x72-placeholder');
    TouchIcon72x72LinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/Artboard-96x96-${brandId}.png`
      : `/api/brand/GetIcon?size=96x96&iconUrl=${favIcon}`;
    const TouchIcon96x96LinkTag = document.getElementById('pwa-icon-ios-96x96-placeholder');
    TouchIcon96x96LinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/Artboard-144x144-${brandId}.png`
      : `/api/brand/GetIcon?size=144x144&iconUrl=${favIcon}`;
    const TouchIcon144x144LinkTag = document.getElementById('pwa-icon-ios-144x144-placeholder');
    TouchIcon144x144LinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/Artboard-152x152-${brandId}.png`
      : `/api/brand/GetIcon?size=152x152&iconUrl=${favIcon}`;
    const TouchIcon152x152LinkTag = document.getElementById('pwa-icon-ios-152x152-placeholder');
    TouchIcon152x152LinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/iphone5_splash-${brandId}.png`
      : `/api/brand/GetSplashScreen?size=640x1136&iconUrl=${favIcon}`;
    const iphone5SplashScreenLinkTag = document.getElementById('iphone5-splash-screen-placeholder');
    iphone5SplashScreenLinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/iphone6_splash-${brandId}.png`
      : `/api/brand/GetSplashScreen?size=750x1334&iconUrl=${favIcon}`;
    const iphone6SplashScreenLinkTag = document.getElementById('iphone6-splash-screen-placeholder');
    iphone6SplashScreenLinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/iphoneplus_splash-${brandId}.png`
      : `/api/brand/GetSplashScreen?size=1863x3312&iconUrl=${favIcon}`;
    const iphoneplusSplashScreenLinkTag = document.getElementById('iphoneplus-splash-screen-placeholder');
    iphoneplusSplashScreenLinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/iphonex_splash-${brandId}.png`
      : `/api/brand/GetSplashScreen?size=1125x2436&iconUrl=${favIcon}`;
    const iphonexSplashScreenLinkTag = document.getElementById('iphonex-splash-screen-placeholder');
    iphonexSplashScreenLinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/iphonexr_splash-${brandId}.png`
      : `/api/brand/GetSplashScreen?size=828x1792&iconUrl=${favIcon}`;
    const iphonexrSplashScreenLinkTag = document.getElementById('iphonexr-splash-screen-placeholder');
    iphonexrSplashScreenLinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/iphonexsmax_splash-${brandId}.png`
      : `/api/brand/GetSplashScreen?size=1242x2688&iconUrl=${favIcon}`;
    const iphonexsmaxSplashScreenLinkTag = document.getElementById('iphonexsmax-splash-screen-placeholder');
    iphonexsmaxSplashScreenLinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/ipad_splash-${brandId}.png`
      : `/api/brand/GetSplashScreen?size=1536x2048&iconUrl=${favIcon}`;
    const ipadSplashScreenLinkTag = document.getElementById('ipad-splash-screen-placeholder');
    ipadSplashScreenLinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/ipadpro1_splash-${brandId}.png`
      : `/api/brand/GetSplashScreen?size=1668x2224&iconUrl=${favIcon}`;
    const ipadpro1SplashScreenLinkTag = document.getElementById('ipadpro1-splash-screen-placeholder');
    ipadpro1SplashScreenLinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/ipadpro2_splash-${brandId}.png`
      : `/api/brand/GetSplashScreen?size=2048x2732&iconUrl=${favIcon}`;
    const ipadpro2SplashScreenLinkTag = document.getElementById('ipadpro2-splash-screen-placeholder');
    ipadpro2SplashScreenLinkTag.setAttribute('href', origin + href);

    href = brandId
      ? `/assets/pwa-icons/ipadpro3_splash-${brandId}.png`
      : `/api/brand/GetSplashScreen?size=1668x2388&iconUrl=${favIcon}`;
    const ipadpro3SplashScreenLinkTag = document.getElementById('ipadpro3-splash-screen-placeholder');
    ipadpro3SplashScreenLinkTag.setAttribute('href', origin + href);
  }

  public setPWAData() {
    this.setManifestJSON();
    this.setTouchAndSplashScreenIconsForIos();
  }

  isMobileLogin = (): boolean => {
    return this.location.path().includes('mobile/login') && !this.location.path().includes('fax-mobile');
  };

  isInterFaxMobileLogin = (): boolean => {
    return this.location.path().includes('fax-mobile');
  };
}
