import { EventEmitter } from '@angular/core';

import { IFilterValue } from '../../../Bamba.Web/ClientApp/src/app/blocks/models/filter';
import { IItemsDataService } from './../interop/ItemsDataService';
import { ICrumb } from './crumb';
import { TableItem } from './table';

export enum SortDirection {
  Ascending = 0,
  Descending = 1,
}
export class ItemsRequest {
  pageNumber: number;
  pageSize: number;
  sortBy: string;
  sortByDirection: SortDirection;
  filters: Array<IFilterValue>;
}

export class ChartRequest {
  filters: Array<IFilterValue>;
}

export class ItemsFilter {
  constructor(productId: string, folderId: string, request: ItemsRequest) {
    this.product = productId;
    this.folder = folderId;

    if (request) {
      this.pageNumber = request.pageNumber;
      this.pageSize = request.pageSize;
      this.sortBy = request.sortBy;
      this.sortByDirection = request.sortByDirection;
      this.filters = request.filters;
    }
  }

  product: string;
  folder: string;
  pageNumber: number;
  pageSize: number;
  count: number;
  sortBy: string;
  sortByDirection: SortDirection;
  filters: Array<IFilterValue>;
}

export class ItemsResult {
  success: boolean;
  errors: Array<string>;
  items: Array<any>;
  filter: ItemsFilter;
  total: number;
  crumbs: Array<ICrumb>;
  folderData: Array<any>;
}

export class PageResult {
  success: boolean;
  errors: Array<string>;
  page: any;
}

export interface ITableDatasource {
  loadItems(request: ItemsRequest, successCallBack: (result: ItemsResult) => void, failureCallBack: (err: any) => void);

  getPage(
    item: any,
    pageNumber: number,
    successCallBack: (pageData: Blob) => void,
    failureCallBack: (err: any) => void
  );
}

export class ItemTableDataSource implements ITableDatasource {
  private readonly subUrl = 'items/items';

  onItemsLoaded = new EventEmitter<ItemsResult>();

  constructor(public product: string, public folder: string, private apiService: IItemsDataService) {}

  loadItems(
    request: ItemsRequest,
    successCallBack: (result: ItemsResult) => void,
    failureCallBack: (err: any) => void
  ): Promise<void> {
    const itemsFilter = new ItemsFilter(this.product, this.folder, request);
    return this.apiService
      .postItemtoServer(this.subUrl, itemsFilter)
      .toPromise()
      .then((r: ItemsResult) => {
        this.proxySuccessCallback(r, successCallBack);
      })
      .catch(failureCallBack);
  }

  proxySuccessCallback = (result: ItemsResult, successCallBack: (result: ItemsResult) => void): void => {
    this.onItemsLoaded.emit(result);
    successCallBack(result);
  };

  getPage = (
    item: TableItem,
    pageNumber: number,
    successCallBack: (pageData: Blob) => void,
    failureCallBack: (err: any) => void
  ): void => {
    this.apiService.getItemPageStream(
      item.data.id,
      pageNumber,
      (f: Blob) => {
        successCallBack(f);
      },
      failureCallBack
    );
  };
}
