import {
  Directive,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  SimpleChanges,
} from '@angular/core';
import { Subscription } from 'rxjs';

import { DelayService, RepeatedService } from 'shared-code-lib';
import { Document } from '../../blocks/models/document';
import { DragData } from '../../views/document-capture/capture-models';
import { DragDropService } from '../services/drag-drop.service';

declare const $: any;

@Directive({
  selector: '[appDragNDrop]',
})
export class DragDropDirective implements OnInit, OnChanges, OnDestroy {
  @Input() isSortable: boolean;
  @Input() sortableList: Array<any>;
  @Input() sortableListLength: number;
  @Input() sortableElementType: string;
  @Input() sortableParentStepId: string;
  @Input() element: any;
  @Input() elementParentId: string;
  @Input() elementType: string;
  @Input() document: Document;
  @Input() isDraggable: boolean;
  @Input() isDroppable: boolean;
  @Input() autoScroll: boolean;
  @Input() autoScrollStep: number;
  @Input() wrapper: ElementRef;
  @Input() scrollableWrapper: ElementRef;
  @Output() dragStarted = new EventEmitter();
  @Output() dragEnd = new EventEmitter();
  @Output() dragOver = new EventEmitter<DragData>();
  @Output() dragLeave = new EventEmitter<DragData>();
  @Output() drop = new EventEmitter<DragData>();
  @Output() sort = new EventEmitter<DragData>();
  @Output() scrollToTop = new EventEmitter<number>();
  @Output() scrollToBottom = new EventEmitter<number>();
  private _element: any;
  private isSorting: boolean;
  private intTopHandler: any;
  private intBottomHandler: any;
  private subscriptions: Subscription;

  constructor(
    private dragDropService: DragDropService,
    private el: ElementRef,
    private delay: DelayService,
    private repeat: RepeatedService
  ) {
    this.subscriptions = new Subscription();
  }

  ngOnInit() {
    this.delay.execute(this.init, 1000);
  }

  ngOnChanges(changes: SimpleChanges) {
    if (!this._element) {
      return;
    }

    if (changes.isSortable || changes.sortableList || changes.sortableListLength) {
      if (this.isSortable) {
        this.delay.execute(this.initSorting, 500);
      } else {
        this.delay.execute(this.destroySorting, 500);
      }
    }

    if (changes.isDraggable) {
      this.delay.execute(() => {
        if (this.isDraggable) {
          this.enableDragging();
        } else {
          this.disableDragging();
        }
      }, 500);
    }
  }

  ngOnDestroy() {
    this.subscriptions.unsubscribe();
    this.clearIntervals();
    this.disableDragging();
  }

  init = () => {
    const element = $(this.el.nativeElement);
    const parentLi = this.isDraggable ? $(element.parents('li')[0]) : element;
    this._element = element;
    if (this.isDraggable) {
      this.enableDragging();
    }
    if (this.isDroppable) {
      parentLi.on('drop', (ev: DragEvent) => {
        ev.preventDefault();
        ev.stopPropagation();
        this.onDrop();
      });
      parentLi.on('dragover', (ev: DragEvent) => {
        ev.preventDefault();
        ev.stopPropagation();
        this.onDragOver(ev);
      });
      parentLi.on('dragleave', (ev: DragEvent) => {
        ev.preventDefault();
        ev.stopPropagation();
        this.onDragLeave(parentLi);
      });
    }

    if (this.isSortable) {
      this.initSorting();
    }

    if (this.autoScroll) {
      this._element.on('dragover', (e: DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        this.handleAutoScroll(e);
      });

      this.subscriptions.add(
        this.dragDropService.onDragOverElement.subscribe((event) => {
          this.handleAutoScroll(event);
        })
      );

      this._element.on('drop', (e: DragEvent) => {
        e.stopPropagation();
        e.preventDefault();
        this.clearIntervals();
      });

      this.subscriptions.add(
        this.dragDropService.onDropElement.subscribe(() => {
          this.clearIntervals();
        })
      );
    }
  };

  enableDragging = () => {
    const parentLi = $(this._element.parents('li')[0]);

    const dragHandler = parentLi.find('.drag-handler');
    if (dragHandler.length) {
      dragHandler.mousedown((ev: DragEvent) => {
        parentLi.attr({ draggable: 'true' });
        ev.stopPropagation();
        parentLi.addClass('draggable');
      });

      dragHandler.mouseup((ev: DragEvent) => parentLi.removeAttr('draggable'));
    } else {
      parentLi.addClass('draggable');
    }
    parentLi.on('dragstart', (ev: DragEvent) => {
      this.handleFireFoxDnDRequirements(ev);
      ev.stopPropagation();
      this.onDrag(ev, parentLi);
    });
    parentLi.on('dragend', (ev: DragEvent) => {
      ev.preventDefault();
      ev.stopPropagation();
      this.onDragEnd(parentLi, dragHandler);
    });
  };

  disableDragging = () => {
    if (!this._element) return;
    const parentLi = $(this._element.parents('li')[0]);

    parentLi.attr({ draggable: false });
    parentLi.off('dragend');
    parentLi.off('dragstart');
  };

  handleFireFoxDnDRequirements(event: DragEvent): void {
    const firefoxEvent = <any>event;
    if (firefoxEvent.originalEvent && firefoxEvent.originalEvent.dataTransfer) {
      firefoxEvent.originalEvent.dataTransfer.setData('text', '');
    }
  }

  initSorting = () => {
    const that = this;
    this._element.children().each(function (i: number) {
      const element = $(this);
      element.unbind('dragstart');
      element.unbind('dragover');
      element.unbind('dragend');
      element.unbind('drop');
      element.attr({ draggable: 'true' });
      element.attr({ 'data-index': i });
      that.assignUniqueId(element, i, 'page');
      element.on('dragstart', function (ev: DragEvent) {
        that.handleFireFoxDnDRequirements(ev);
        ev.stopPropagation();
        $(this).addClass('drag-started');
        const dragData: DragData = {
          element: that.sortableList[i],
          elementParentId: that.sortableList[i].parentDocumentId,
          elementType: that.sortableElementType,
          elementParentStepId: that.sortableParentStepId,
          elementHTMLId: element.attr('id'),
          elementPosition: parseInt(element.attr('data-index'), 10) + 1,
          document: that.document,
        };
        that.dragDropService.pushDragData(dragData);
      });
      element.on('dragover', function (ev: DragEvent) {
        ev.preventDefault();
        ev.stopPropagation();
        that.dragDropService.autoScroll(ev);
        const dragData: DragData = that.dragDropService.dragDataArray[0];
        if (dragData) {
          const source = $(`#${dragData.elementHTMLId}`);
          const target = $(element);
          const sourceIndex = source.attr('data-index');
          const targetIndex = target.attr('data-index');
          if (sourceIndex === targetIndex) {
            return;
          }
          dragData.target = that.sortableList[i];
          dragData.targetType = that.sortableElementType;
          if (that.isEqual(dragData.elementType, dragData.targetType)) {
            that.isSorting = true;
            if (that.isBefore(sourceIndex, targetIndex)) {
              source.insertAfter(target);
            } else {
              source.insertBefore(target);
            }
            source.attr({ 'data-index': targetIndex });
            target.attr({ 'data-index': sourceIndex });
            that.swapElements(sourceIndex, targetIndex);
          }
        }
      });
      element.on('dragleave', function (ev: DragEvent) {
        ev.preventDefault();
        ev.stopPropagation();
      });
      element.on('dragend', function (ev: DragEvent) {
        ev.preventDefault();
        ev.stopPropagation();
        $(this).removeClass('drag-started');
        that.isSorting = false;
        that.clearIntervals();
      });
      element.on('drop', function (ev: DragEvent) {
        ev.preventDefault();
        ev.stopPropagation();

        const dragData: DragData = that.dragDropService.dragDataArray[0];
        if (that.isSorting && dragData.elementPosition !== dragData.targetPosition) {
          that.sort.emit(dragData);
          that.dragDropService.clearDragData();
          that.destroySorting();
          that.initSorting();
        }
      });
    });
  };

  destroySorting = () => {
    const that = this;
    this._element.children().each(function (i: number) {
      const element = $(this);
      element.unbind('dragstart');
      element.unbind('dragover');
      element.unbind('dragend');
      element.unbind('drop');
      element.attr({ draggable: 'false' });
      that.dragDropService.clearDragData();
    });
  };

  private onDrag(ev: DragEvent, element: any): void {
    ev.stopPropagation();
    if (!element.hasClass('draggable')) {
      ev.preventDefault();
      return;
    }
    const dragData: DragData = {
      element: this.element,
      elementParentId: this.elementParentId,
      elementParentStepId: this.sortableParentStepId,
      elementType: this.elementType,
      document: this.document,
    };
    this.dragDropService.pushDragData(dragData);
    this.dragStarted.emit();
  }

  private onDragOver(ev: DragEvent): void {
    const dragData: DragData = this.dragDropService.dragDataArray[0];
    this.dragDropService.autoScroll(ev);
    if (dragData) {
      dragData.targetType = this.elementType;
      dragData.target = this.element;
    }
    this.dragOver.emit(this.dragDropService.dragDataArray[0]);
  }

  private onDragLeave(element: any) {
    const target = $(element);
    target.removeClass('droppable');
    this.dragLeave.emit(this.dragDropService.dragDataArray[0]);
  }

  private onDragEnd(element: any, dragHandler: any): void {
    if (dragHandler.length) {
      $(element).removeClass('draggable');
    }
    this.dragDropService.clearDragData();
    this.dragEnd.emit();
  }

  private onDrop(): void {
    const dragData: DragData = this.dragDropService.dragDataArray[0];
    this.dragDropService.stopAutoScroll();
    if (dragData) {
      dragData.targetType = 'batch';
      dragData.target = this.element;
      this.drop.emit(dragData);
    }
  }

  private assignUniqueId(element: any, i: number, className: string): void {
    element.attr({ id: `${className}-${i}` });
  }

  private isBefore(element1: any, element2: any): boolean {
    return element1 < element2;
  }

  private isEqual(element1: any, element2: any): boolean {
    return element1 === element2;
  }

  private swapElements(index1: string, index2: string): void {
    const element1 = this.sortableList[index1];
    this.sortableList[index1] = this.sortableList[index2];
    this.sortableList[index2] = element1;

    const dragData = this.dragDropService.dragDataArray[0];
    if (dragData) {
      dragData.targetPosition = parseInt(index2, 10) + 1;
    }
  }

  private handleAutoScroll(event: DragEvent) {
    const div = $(this.wrapper);
    const offset = div.offset();
    const offsetHeight = offset.top + div.height();
    const offsetWidth = offset.left + $(this.scrollableWrapper).width();
    const distance = 70;
    const repeatTime = 5;
    const step = this.autoScrollStep || 20;
    this._element.addClass('auto-scroll');
    if (event.pageX - offset.left <= 25 || event.pageX >= offsetWidth - 25 || event.pageY - offset.top <= 35) {
      this.clearIntervals();
    } else if (event.pageY - offset.top <= distance) {
      if (!this.intTopHandler) {
        this.intTopHandler = this.repeat.start(repeatTime).subscribe(() => {
          this.scrollToTop.emit($(this.scrollableWrapper).scrollTop() - step);
        });
      }
    } else if (event.pageY >= offsetHeight - distance && event.pageY <= offsetHeight - 10) {
      if (!this.intBottomHandler) {
        this.intBottomHandler = this.repeat.start(repeatTime).subscribe(() => {
          this.scrollToBottom.emit($(this.scrollableWrapper).scrollTop() + step);
        });
      }
    } else {
      this.clearIntervals();
    }
  }

  clearIntervals() {
    if (this._element) {
      this._element.removeClass('auto-scroll');
    }

    if (this.intBottomHandler) {
      this.intBottomHandler = this.repeat.stop(this.intBottomHandler);
    }

    if (this.intTopHandler) {
      this.intTopHandler = this.repeat.stop(this.intTopHandler);
    }
  }
}
