import { Action } from './metadata-formatting-action';
import { Criteria } from './metadata-formatting-criteria';

export class Formatter {
  public name: string;
  public criteria: Criteria;
  public action: Action;
  public doNotApplyFurtherFormatting: boolean;

  constructor(initializer: any) {
    if (initializer) {
      if (!initializer.criteria) throw new Error('Invalid initializer.criteria');
      if (!initializer.action) throw new Error('Invalid initializer.action');

      this.name = initializer.name;
      this.criteria = Criteria.create(initializer.criteria);
      this.action = Action.create(initializer.action);
      this.doNotApplyFurtherFormatting = initializer.doNotApplyFurtherFormatting;
    }
  }

  public serializable(): any {
    return {
      name: this.name,
      criteria: this.criteria.serializable(),
      action: this.action.serializable(),
      doNotApplyFurtherFormatting: this.doNotApplyFurtherFormatting,
    };
  }
}
