import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Feedback } from './../models/feedback';
import { ApiResult, IFolder } from './models';

import { IItemsDataService, URLs } from 'shared-code-lib';

@Injectable({
  providedIn: 'root',
})
export class ApiService implements IItemsDataService {
  baseUrl = '';
  constructor(private http: HttpClient) {}

  setBaseUrl(url: string) {
    this.baseUrl = url;
  }

  queryServer(url: string) {
    return this.http.get(this.baseUrl + 'api/' + url);
  }

  loadLookUps(url: string) {
    return this.http.get(this.baseUrl + 'api/' + url);
  }

  loadItemById(url: string) {
    return this.http.get(this.baseUrl + 'api/' + url);
  }

  postItemtoServer(url: string, data: any) {
    return this.http.post(this.baseUrl + 'api/' + url, data);
  }

  postItemtoServerWithOptions(url: string, data: any, options?: any) {
    return this.http.post(this.baseUrl + 'api/' + url, data, options);
  }

  patchItemOnServer(url: string, data: any) {
    return this.http.patch(this.baseUrl + 'api/' + url, data);
  }

  deleteItemOnServer(url: string) {
    return this.http.delete(this.baseUrl + 'api/' + url);
  }

  putItemtoServer(url: string, data: any) {
    const httpOptions = {
      headers: new HttpHeaders({
        'Content-Type': 'application/json',
      }),
    };
    return this.http.put(this.baseUrl + 'api/' + url, data, httpOptions);
  }

  getItemPageStream(
    id: string,
    pageNumber: number,
    successCallBack: (file: Blob) => void,
    failureCallBack: (err: any) => void
  ) {
    this.http
      .get(this.baseUrl + `api/items/getpagestream/${id}/${pageNumber}`, { responseType: 'blob' })
      .subscribe((file: File) => {
        successCallBack(file);
      }, failureCallBack);
  }

  getFolderById(id: string, success: (f: IFolder) => void, failed: (e: any) => void) {
    this.http.get(this.baseUrl + `api/folders/${id}`).subscribe((f: IFolder) => success(f), failed);
  }

  getFolderDetailsData(id: string, success: (d: any) => void, failed: (e: any) => void) {
    this.http.get(this.baseUrl + `api/items/GetFolderDetails/${id}`).subscribe((r: ApiResult) => {
      if (r.success) {
        success(r.object);
      } else {
        failed(r.errors);
      }
    }, failed);
  }

  getItemStream(id: string, successCallBack: (file: Blob) => void, failureCallBack: (err: any) => void) {
    this.http.get(this.baseUrl + `api/items/getstream/${id}`, { responseType: 'blob' }).subscribe((file: File) => {
      successCallBack(file);
    }, failureCallBack);
  }
  getItemStreamAsPDF(
    id: string,
    format: string,
    successCallBack: (file: Blob) => void,
    failureCallBack: (err: any) => void
  ) {
    this.http
      .get(this.baseUrl + `api/items/getstreamaspdf/${id}/${format}`, { responseType: 'blob' })
      .subscribe((file: File) => {
        successCallBack(file);
      }, failureCallBack);
  }

  renameItem(
    id: string,
    name: string,
    successCallback: (newName: string) => void,
    failureCallBack: (err: any) => void
  ): void {
    this.postItemtoServer(`items/renameitem/${id}/${URLs.encodeUrl(name)}`, null).subscribe(
      (o: ApiResult) => {
        if (o.success) successCallback(o.object);
        else failureCallBack(o.errors);
      },
      (e) => {
        if (e.message) failureCallBack([e.message]);
        else failureCallBack(e);
      }
    );
  }

  postFeedback(data: Feedback, successCallBack: () => void, failureCallBack: (err: any) => void) {
    return this.http.post(this.baseUrl + 'api/feedback', data).subscribe((r: ApiResult) => {
      if (r.success) {
        successCallBack();
      } else {
        failureCallBack(r.errors);
      }
    }, failureCallBack);
  }
}
