import { Component, Input, OnInit, Renderer2, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { TextComponent } from '../text/text.component';

@Component({
  selector: 'app-password',
  templateUrl: './password.component.html',
  styleUrls: ['./password.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class PasswordComponent extends TextComponent implements OnInit {
  @Input() fieldId: string = '';

  showPassword = false;
  showPasswordText: string = '';
  hidePasswordText: string = '';

  constructor(private renderer: Renderer2, private translate: TranslateService) {
    super(translate);
  }

  ngOnInit() {
    this.showPasswordText = this.translate.instant('Common.ShowPassword');
    this.hidePasswordText = this.translate.instant('Common.HidePassword');
  }

  toggleShowPassword() {
    this.showPassword = !this.showPassword;

    this.renderer.setAttribute(this.input.nativeElement, 'type', this.showPassword ? 'text' : 'password');
  }
}
