import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class MetaDataFilterByProperty extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByMetaDataPropertyComponent';
  }
}

class MetaDataFilterByType extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByMetaDataTypeComponent';
  }
}

class MetaDataFilterByReference extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByMetaDataReferenceComponent';
  }
}

export class MetaDataFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('MetaDataFilters.Create', filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.MetaDataFields.Filters.FilterByMetaDataProperty')
      return new MetaDataFilterByProperty(filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.MetaDataFields.Filters.FilterByMetaDataType')
      return new MetaDataFilterByType(filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.MetaDataFields.Filters.FilterByMetaDataReference')
      return new MetaDataFilterByReference(filter);

    return null;
  };
}
