import { Injectable } from '@angular/core';
import { ICapture, IContourPoints, IExtractDocumentResult, IPoint, ScanResult } from '../models/scanner';

declare let cv: any;

@Injectable({
  providedIn: 'root',
})
export class WebScannerService {
  cv;

  private _circleRadius = 45;

  get circleRadius() {
    return this._circleRadius;
  }

  set circleRadius(radius: number) {
    this._circleRadius = radius;
  }

  get cropCanvasPadding() {
    return this._circleRadius;
  }

  private _lineThickness = 1;

  get lineThickness() {
    return this._lineThickness;
  }

  set lineThickness(thickness: number) {
    this._lineThickness = thickness;
  }

  async initScanner() {
    this.cv = await cv;
  }

  renderOriginalVideo(capture: typeof this.cv.VideoCapture) {
    const { width, height } = capture.video;
    const img = new this.cv.Mat(height, width, this.cv.CV_8UC4);
    capture.read(img);
    this.cv.imshow('result', img);
    this.deleteCVObject(img);
  }

  highlightDocument(capture: typeof this.cv.VideoCapture) {
    const { width, height } = capture.video;
    const img = new this.cv.Mat(height, width, this.cv.CV_8UC4);
    const maxContour = new this.cv.Mat();

    capture.read(img);

    const contourExists = this.findDocumentContour(img, maxContour);

    let scanResult = ScanResult.NoDocument;

    if (contourExists) {
      const points = this.getContourCornerPoints(maxContour);
      this.drawContourInImage(img, points);

      const hasFourPoints = !!(points.topLeft && points.topRight && points.bottomLeft && points.bottomRight);
      const { width: boundingRectWidth, height: boundingRectHeight } = this.cv.boundingRect(maxContour);
      const readyContour = hasFourPoints && (boundingRectWidth >= 0.8 * width || boundingRectHeight >= 0.8 * height);
      scanResult = readyContour ? ScanResult.ReadyDocument : ScanResult.NotReadyDocument;
    }

    this.cv.imshow('result', img);

    this.deleteCVObject(maxContour);
    this.deleteCVObject(img);

    return scanResult;
  }

  extractOriginalAndDefaultCroppedDocuments(capture: typeof this.cv.VideoCapture): ICapture {
    const originalDocumentResult = this.extractOriginalDocument(capture);
    const capturedDocumentResult = this.extractDefaultCroppedDocument(capture);

    return {
      originalImage: originalDocumentResult.image,
      originalImageBoundaries: originalDocumentResult.imageBoundaries,
      capturedImage: capturedDocumentResult.image,
      capturedImageBoundaries: capturedDocumentResult.imageBoundaries,
    };
  }

  async renderImageToCrop(imageURL: string, contourPoints: IContourPoints) {
    const img = this.cv.imread(await this.getImageFromURL(imageURL));
    const paddedWidth = img.cols + 2 * this.cropCanvasPadding;
    const paddedHeight = img.rows + 2 * this.cropCanvasPadding;

    const paddedImg = new this.cv.Mat(paddedHeight, paddedWidth, img.type());

    const whiteRectangle = this.cv.rectangle(
      paddedImg,
      { x: 0, y: 0 },
      { x: paddedWidth, y: paddedHeight },
      [255, 255, 255, 255],
      -1
    );

    const roi = paddedImg.roi(new this.cv.Rect(this.cropCanvasPadding, this.cropCanvasPadding, img.cols, img.rows));
    img.copyTo(roi);

    const paddedContourPoints = {
      topLeft: {
        x: contourPoints.topLeft.x + this.cropCanvasPadding,
        y: contourPoints.topLeft.y + this.cropCanvasPadding,
      },
      topRight: {
        x: contourPoints.topRight.x + this.cropCanvasPadding,
        y: contourPoints.topRight.y + this.cropCanvasPadding,
      },
      bottomRight: {
        x: contourPoints.bottomRight.x + this.cropCanvasPadding,
        y: contourPoints.bottomRight.y + this.cropCanvasPadding,
      },
      bottomLeft: {
        x: contourPoints.bottomLeft.x + this.cropCanvasPadding,
        y: contourPoints.bottomLeft.y + this.cropCanvasPadding,
      },
    };

    this.drawContourInImage(paddedImg, paddedContourPoints, true);
    this.cv.imshow('crop-canvas', paddedImg);

    this.deleteCVObject(img);
    this.deleteCVObject(paddedImg);
    this.deleteCVObject(whiteRectangle);
    this.deleteCVObject(roi);
  }

  async extractCroppedDocument(
    imageUrl: string,
    resultDocumentCorners: IContourPoints
  ): Promise<IExtractDocumentResult> {
    const src = new this.cv.imread(await this.getImageFromURL(imageUrl));

    const points = [
      resultDocumentCorners.topLeft,
      resultDocumentCorners.topRight,
      resultDocumentCorners.bottomRight,
      resultDocumentCorners.bottomLeft,
    ];

    const contour = new this.cv.Mat(points.length, 1, this.cv.CV_32SC2);
    const contourDataPtr = contour.data32S;
    for (let i = 0; i < points.length; i++) {
      contourDataPtr[i * 2] = points[i].x;
      contourDataPtr[i * 2 + 1] = points[i].y;
    }

    const { width, height } = this.cv.boundingRect(contour);
    const croppedDocument = this.extractDocument(src, resultDocumentCorners, width, height);

    this.deleteCVObject(contour);
    this.deleteCVObject(src);

    return {
      image: croppedDocument,
      imageBoundaries: resultDocumentCorners,
    };
  }

  private extractOriginalDocument(capture: typeof this.cv.VideoCapture): IExtractDocumentResult {
    const { width, height } = capture.video;
    const src = new this.cv.Mat(height, width, this.cv.CV_8UC4);
    capture.read(src);

    const imageWidth = src.cols;
    const imageHeight = src.rows;

    this.deleteCVObject(src);

    const originalImageBoundaries: IContourPoints = {
      topLeft: { x: 0, y: 0 },
      topRight: { x: imageWidth, y: 0 },
      bottomLeft: { x: 0, y: imageHeight },
      bottomRight: { x: imageWidth, y: imageHeight },
    };

    return {
      image: this.extractDocumentFromCapture(capture, width, height, originalImageBoundaries, imageWidth, imageHeight),
      imageBoundaries: originalImageBoundaries,
    };
  }

  private extractDefaultCroppedDocument(capture: typeof this.cv.VideoCapture): IExtractDocumentResult {
    const { width, height } = capture.video;
    const src = new this.cv.Mat(height, width, this.cv.CV_8UC4);
    capture.read(src);

    const imageWidth = src.cols;
    const imageHeight = src.rows;

    let resultWidth;
    let resultHeight;

    const resultDocumentCorners: IContourPoints = {
      topLeft: undefined,
      topRight: undefined,
      bottomLeft: undefined,
      bottomRight: undefined,
    } as any;

    const contour = new this.cv.Mat();
    const contourExists = this.findDocumentContour(src, contour);

    if (!contourExists) {
      resultDocumentCorners.topLeft = { x: 0, y: 0 };
      resultDocumentCorners.topRight = { x: imageWidth, y: 0 };
      resultDocumentCorners.bottomLeft = { x: 0, y: imageHeight };
      resultDocumentCorners.bottomRight = { x: imageWidth, y: imageHeight };
      resultWidth = imageWidth;
      resultHeight = imageHeight;
    } else {
      const contourPoints = this.getContourCornerPoints(contour);

      if (
        !contourPoints.topLeft ||
        !contourPoints.topRight ||
        !contourPoints.bottomLeft ||
        !contourPoints.bottomRight
      ) {
        resultDocumentCorners.topLeft = { x: 0, y: 0 };
        resultDocumentCorners.topRight = { x: imageWidth, y: 0 };
        resultDocumentCorners.bottomLeft = { x: 0, y: imageHeight };
        resultDocumentCorners.bottomRight = { x: imageWidth, y: imageHeight };
        resultWidth = imageWidth;
        resultHeight = imageHeight;
      } else {
        resultDocumentCorners.topLeft = contourPoints.topLeft;
        resultDocumentCorners.topRight = contourPoints.topRight;
        resultDocumentCorners.bottomLeft = contourPoints.bottomLeft;
        resultDocumentCorners.bottomRight = contourPoints.bottomRight;
        const rect = this.cv.boundingRect(contour);
        resultWidth = rect.width;
        resultHeight = rect.height;
      }
    }

    this.deleteCVObject(contour);
    this.deleteCVObject(src);

    return {
      image: this.extractDocumentFromCapture(capture, width, height, resultDocumentCorners, resultWidth, resultHeight),
      imageBoundaries: resultDocumentCorners,
    };
  }

  private extractDocumentFromCapture(
    capture: typeof this.cv.VideoCapture,
    width: number,
    height: number,
    resultDocumentCorners: IContourPoints,
    resultWidth: number,
    resultHeight: number
  ) {
    const src = new this.cv.Mat(height, width, this.cv.CV_8UC4);
    capture.read(src);
    const result = this.extractDocument(src, resultDocumentCorners, resultWidth, resultHeight);
    this.deleteCVObject(src);
    return result;
  }

  private extractDocument(
    src: typeof this.cv.Mat,
    resultDocumentCorners: IContourPoints,
    resultWidth: number,
    resultHeight: number
  ): string {
    const dsize = new this.cv.Size(resultWidth, resultHeight);
    const srcTri = this.cv.matFromArray(4, 1, this.cv.CV_32FC2, [
      resultDocumentCorners.topLeft.x,
      resultDocumentCorners.topLeft.y,
      resultDocumentCorners.topRight.x,
      resultDocumentCorners.topRight.y,
      resultDocumentCorners.bottomLeft.x,
      resultDocumentCorners.bottomLeft.y,
      resultDocumentCorners.bottomRight.x,
      resultDocumentCorners.bottomRight.y,
    ]);

    const dstTri = this.cv.matFromArray(4, 1, this.cv.CV_32FC2, [
      0,
      0,
      resultWidth,
      0,
      0,
      resultHeight,
      resultWidth,
      resultHeight,
    ]);

    const M = this.cv.getPerspectiveTransform(srcTri, dstTri);

    const dst = new this.cv.Mat(resultHeight, resultWidth, this.cv.CV_8UC4);
    this.cv.warpPerspective(src, dst, M, dsize, this.cv.INTER_LINEAR, this.cv.BORDER_CONSTANT, new this.cv.Scalar());

    const canvas = document.createElement('canvas');
    this.cv.imshow(canvas, dst);

    this.deleteCVObject(dst);
    this.deleteCVObject(srcTri);
    this.deleteCVObject(dstTri);
    this.deleteCVObject(M);

    return canvas.toDataURL('image/png');
  }

  private async getImageFromURL(url: string): Promise<HTMLImageElement> {
    return new Promise((resolve) => {
      const image = new Image();
      image.onload = () => {
        resolve(image);
      };
      image.src = url;
    });
  }

  private findDocumentContour(img: typeof this.cv.Mat, contour: typeof this.cv.Mat) {
    let contourExists = false;
    const imgGray = new this.cv.Mat();
    const imgBlur = new this.cv.Mat();
    const imgThresh = new this.cv.Mat();
    const contours = new this.cv.MatVector();
    const hierarchy = new this.cv.Mat();

    this.cv.cvtColor(img, imgGray, this.cv.COLOR_RGBA2GRAY);
    this.cv.GaussianBlur(imgGray, imgBlur, new this.cv.Size(5, 5), 0, 0, this.cv.BORDER_DEFAULT);
    this.cv.threshold(imgBlur, imgThresh, 0, 255, this.cv.THRESH_BINARY + this.cv.THRESH_OTSU);
    this.cv.findContours(imgThresh, contours, hierarchy, this.cv.RETR_CCOMP, this.cv.CHAIN_APPROX_SIMPLE);

    let maxArea = 0.2 * img.rows * img.cols;
    let maxContourIndex = -1;

    for (let i = 0; i < contours.size(); ++i) {
      const c = contours.get(i);
      const contourArea = this.cv.contourArea(c);
      if (contourArea > maxArea) {
        maxArea = contourArea;
        maxContourIndex = i;
      }
      this.deleteCVObject(c);
    }

    if (maxContourIndex !== -1) {
      contourExists = true;
      const c = contours.get(maxContourIndex);
      c.copyTo(contour);
      this.deleteCVObject(c);
    }

    this.deleteCVObject(imgGray);
    this.deleteCVObject(imgBlur);
    this.deleteCVObject(imgThresh);
    this.deleteCVObject(contours);
    this.deleteCVObject(hierarchy);

    return contourExists;
  }

  private drawContourInImage(img: typeof this.cv.Mat, points: IContourPoints, drawCorners = false) {
    const { topLeft, topRight, bottomLeft, bottomRight } = points;

    if (!topLeft || !topRight || !bottomLeft || !bottomRight) return;

    const color = new this.cv.Scalar(255, 255, 0, 255);

    const line1 = this.cv.line(
      img,
      new this.cv.Point(topLeft.x, topLeft.y),
      new this.cv.Point(topRight.x, topRight.y),
      color,
      this.lineThickness
    );

    const line2 = this.cv.line(
      img,
      new this.cv.Point(topRight.x, topRight.y),
      new this.cv.Point(bottomRight.x, bottomRight.y),
      color,
      this.lineThickness
    );

    const line3 = this.cv.line(
      img,
      new this.cv.Point(bottomRight.x, bottomRight.y),
      new this.cv.Point(bottomLeft.x, bottomLeft.y),
      color,
      this.lineThickness
    );

    const line4 = this.cv.line(
      img,
      new this.cv.Point(bottomLeft.x, bottomLeft.y),
      new this.cv.Point(topLeft.x, topLeft.y),
      color,
      this.lineThickness
    );

    this.deleteCVObject(line1);
    this.deleteCVObject(line2);
    this.deleteCVObject(line3);
    this.deleteCVObject(line4);

    if (!drawCorners) return;

    const topLeftCircle = this.cv.circle(
      img,
      new this.cv.Point(topLeft.x, topLeft.y),
      this.circleRadius,
      color,
      this.lineThickness
    );

    const topRightCircle = this.cv.circle(
      img,
      new this.cv.Point(topRight.x, topRight.y),
      this.circleRadius,
      color,
      this.lineThickness
    );

    const bottomLeftCircle = this.cv.circle(
      img,
      new this.cv.Point(bottomLeft.x, bottomLeft.y),
      this.circleRadius,
      color,
      this.lineThickness
    );

    const bottomRightCircle = this.cv.circle(
      img,
      new this.cv.Point(bottomRight.x, bottomRight.y),
      this.circleRadius,
      color,
      this.lineThickness
    );

    this.deleteCVObject(topLeftCircle);
    this.deleteCVObject(topRightCircle);
    this.deleteCVObject(bottomLeftCircle);
    this.deleteCVObject(bottomRightCircle);
  }

  private getContourCornerPoints(contour: typeof this.cv.Mat): IContourPoints {
    const rect = this.cv.minAreaRect(contour);

    const center = rect.center;
    let topLeft;
    let topLeftCornerDist = 0;
    let topRight;
    let topRightCornerDist = 0;
    let bottomLeft;
    let bottomLeftCornerDist = 0;
    let bottomRight;
    let bottomRightCornerDist = 0;

    for (let i = 0; i < contour.data32S.length; i += 2) {
      const point = { x: contour.data32S[i], y: contour.data32S[i + 1] };
      const dist = this.distance(point, center);
      if (point.x < center.x && point.y < center.y) {
        if (dist > topLeftCornerDist) {
          topLeft = point;
          topLeftCornerDist = dist;
        }
      } else if (point.x > center.x && point.y < center.y) {
        if (dist > topRightCornerDist) {
          topRight = point;
          topRightCornerDist = dist;
        }
      } else if (point.x < center.x && point.y > center.y) {
        if (dist > bottomLeftCornerDist) {
          bottomLeft = point;
          bottomLeftCornerDist = dist;
        }
      } else if (point.x > center.x && point.y > center.y) {
        if (dist > bottomRightCornerDist) {
          bottomRight = point;
          bottomRightCornerDist = dist;
        }
      }
    }

    return {
      topLeft,
      topRight,
      bottomLeft,
      bottomRight,
    };
  }

  private distance(p1: IPoint, p2: IPoint) {
    return Math.hypot(p1.x - p2.x, p1.y - p2.y);
  }

  private deleteCVObject(obj: any) {
    if (!obj || obj._deleted) return;
    obj.delete();
    obj._deleted = true;
  }
}
