import { Component, EventEmitter, OnDestroy, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import { ProductItemRefreshService } from '../../../../../blocks/services/product-item-refresh.service';
import { HydraApiService } from './../../../../../blocks/services/hydra-api.service';
import { ApiResult } from './../../../../../blocks/services/models';
import { SelectFilesService } from './../../../../../blocks/services/select-files.service';
import { SharedDataService } from './../../../../../blocks/services/shared-data.service';
import { SpinnerStateService } from './../../../../../blocks/services/spinner-state.service';
import { UploadConfigService } from './../../../shared/services/upload-config.service';

@Component({
  selector: 'app-replace-olc-template-package-modal',
  templateUrl: './replace-template-package-modal.component.html',
  styleUrls: ['./replace-template-package-modal.component.scss'],
})
export class ReplaceOLCTemplateModalComponent implements OnInit, OnDestroy {
  @Output() closeModal = new EventEmitter();
  uploadTooltip: string;
  supportedFileTypes: string;
  templateId: string;
  warningMessage: string;
  isTEDPackage: boolean;
  type: string;
  subscriptions = new Subscription();

  constructor(
    private translateService: TranslateService,
    private spinnerService: SpinnerStateService,
    public selectFilesService: SelectFilesService,
    private hydraApiService: HydraApiService,
    private toastr: ToastrService,
    private translate: TranslateService,
    private productItemRefreshService: ProductItemRefreshService,
    public sharedDataService: SharedDataService,
    private uploadConfigService: UploadConfigService,
    private ngxSmartModalService: NgxSmartModalService
  ) {}

  ngOnInit(): void {
    this.templateId = this.sharedDataService.extraParameters?.templateId;
    this.warningMessage = this.sharedDataService.extraParameters?.warningMessage;
    this.isTEDPackage = this.sharedDataService.extraParameters?.isTEDPackage;
    this.type = this.isTEDPackage ? 'package' : 'template';

    const config = this.uploadConfigService.getReplaceConfig(this.isTEDPackage);
    this.supportedFileTypes = config.supportedFileTypes;
    this.uploadTooltip = config.uploadTooltip;

    this.subscriptions.add(
      this.ngxSmartModalService.getModal('replaceOLCTemplatePackage').onAnyCloseEvent.subscribe(() => {
        this.selectFilesService.clear();
      })
    );
  }

  close = () => {
    this.selectFilesService.clear();
    this.closeModal.emit();
  };

  replaceTemplatePackage(): void {
    this.spinnerService.show(
      this.translateService.instant(`admin-olc-templates.replacing-${this.type}`),
      document.querySelector('.olc-replace-template-package-modal .nsm-content')! as HTMLElement
    );

    this.hydraApiService.replaceOLCTemplatePackage(
      this.templateId,
      this.selectFilesService.files,
      this.replacePackageSucceeded,
      this.replacePackageFailed
    );
  }

  replacePackageSucceeded = (result: ApiResult) => {
    if (result.success) {
      this.toastr.success(this.translate.instant(`admin-olc-templates.${this.type}-replaced`));
      this.close();
      this.productItemRefreshService.onRefresh.next();
    } else {
      const error = result.errors[0];
      this.toastr.error(error);
    }

    this.spinnerService.hide();
  };

  replacePackageFailed = () => {
    this.toastr.error(this.translate.instant(`admin-olc-templates.replace-${this.type}-failed`));
    this.spinnerService.hide();
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
