import {
  Directive,
  ElementRef,
  Input,
  HostListener,
  AfterViewInit,
  Output,
  EventEmitter,
  OnChanges,
  SimpleChanges,
} from '@angular/core';

import { CaptureUpdateService } from '../../../Bamba.Web/ClientApp/src/app/views/document-capture/capture-services/capture-update.service';
import { Languages } from '../utils/languages';

declare const $: any;

@Directive({
  selector: '[appResizable]',
})
export class ResizableDirective implements AfterViewInit, OnChanges {
  @Input() appResizable: string;
  @Input() disabled: boolean;
  @Input() preferenceName: string;
  private _preferenceValue: string;
  @Input() preferenceValue: string;
  @Input() handles: string;
  @Input() width: string;
  @Input() height: string;
  @Input() maxWidth: string;
  @Input() minWidth: string;
  @Input() maxHeight: string;
  @Input() minHeight: string;
  @Input() isRelativeToWindow: boolean = false;
  @Output() widthResized = new EventEmitter();
  @Output() resize = new EventEmitter<any>();
  @Output() resized = new EventEmitter<any>();
  @Output() heightResized = new EventEmitter<number>();
  private _element: any;
  private _maxWidth: string;
  private _minWidth: string;
  private _maxHeight: string;
  private _minHeight: string;

  @HostListener('window:load') onload() {
    this.init(true);
  }

  @HostListener('window:resize') onResize() {
    this.init(true);
  }

  constructor(private el: ElementRef, private captureUpdate: CaptureUpdateService) {}

  ngOnChanges(changes: SimpleChanges) {
    this._preferenceValue = changes?.preferenceValue?.currentValue;

    if (changes.preferenceValue && this._element) {
      this.setElementDimensions();
    }

    if (changes.disabled && !this.disabled) {
      this.init(false);
    } else if (changes.disabled && this.disabled && this._element) {
      this._element.width('auto');
      this._element.resizable('destroy');
    }
  }

  ngAfterViewInit() {
    this.handleRTLMode();
    this.init();
  }

  handleRTLMode = (): void => {
    if (Languages.isRTLLanguage()) {
      if (this.handles == 'e') {
        this.handles = 'w';
      } else if (this.handles == 'w') {
        this.handles = 'e';
      }
    }
  };

  init(destroyFirst?: boolean) {
    if (this.disabled) {
      return;
    }

    this._element = $(this.el.nativeElement);
    if (destroyFirst && this._element) {
      this._element.resizable('destroy');
    }

    if (this.appResizable === 'simple') {
      this._element.resizable({
        handles: this.handles,
        minHeight: this.minHeight,
        start: () => {
          this._element.addClass('resizing');
        },
        resize: () => {
          this.handleOnResizing();
        },
        stop: () => {
          this._element.removeClass('resizing');
          this.handleOnResizing(true);
          this.resized.emit();
        },
      });
    } else {
      this.setElementDimensions();
      this._maxWidth = this.maxWidth || `${this.getElementContainer().width() - 5}`;
      this._minWidth = this.minWidth || '2';
      this._maxHeight = this.maxHeight || `${this.getElementContainer().height() - 5}`;
      this._minHeight = this.minHeight || '2';

      this._element.resizable({
        handles: this.handles,
        maxWidth: this._maxWidth,
        minWidth: this._minWidth,
        maxHeight: this._maxHeight,
        minHeight: this._minHeight,
        start: () => {
          switch (this.handles) {
            case 'e':
            case 'w':
              this._element.resizable('option', 'maxWidth', this.getElementContainer().width() - 5);
              break;
            case 'n':
            case 's':
              this._element.resizable('option', 'maxHeight', this.getElementContainer().height() - 5);
          }
        },
        resize: () => {
          this.handleOnResizing();
        },
        stop: () => {
          this.handleOnResizing(true);
          this.resized.emit();
        },
      });

      this._element.children('.ui-resizable-' + this.handles).append(this.getResizableHandler(this.handles));
    }
  }

  handleOnResizing(isStop: boolean = false) {
    let value: string;
    const name = this.preferenceName;

    switch (this.handles) {
      case 'e':
      case 'w':
      case 'e, w':
      case 'w, e':
        value = `${this.getWidthInPercent()}`;
        this.widthResized.emit();
        break;
      case 'n':
      case 's':
      case 'n, s':
      case 's, n':
        value = `${this.getHeightInPercent()}`;
        this.heightResized.emit(this._element.outerHeight());
    }
    this._preferenceValue = value;

    if (isStop) {
      this.resize.emit({ name, value });
    }
    this.captureUpdate.panelResized();
  }

  setElementDimensions() {
    switch (this.handles) {
      case 'e':
      case 'w':
        if (!this.width) {
          throw new Error('Default width is missing.');
        }

        if (this._preferenceValue != null) {
          this._element.width(this.getWidthInPixels(Number(this._preferenceValue)));
        } else {
          this._element.width(this.width);
        }

        break;
      case 'n':
      case 's':
        if (!this.height) {
          throw new Error('Default height is missing.');
        }

        if (this._preferenceValue != null) {
          this._element.height(this.getHeightInPixels(Number(this._preferenceValue)));
        } else {
          if (typeof this.height === 'number') {
            this._element.height(this.height);
          } else if (typeof this.height === 'string') {
            const percentage = parseInt(this.height.split('%')[0], 10) / 100;
            this._element.height(this.getElementContainer().height() * percentage);
          }
        }

        break;
    }
  }

  getResizableHandler(handle: string) {
    return `
     <div class="resize-custom-handler ${handle} d-flex align-items-center h-100">
      <ul>
        <li></li>
        <li></li>
        <li></li>
      </ul>
     </div>
    `;
  }

  getWidthInPixels(percent: number) {
    return this.getElementContainer().width() * (percent / 100);
  }

  getHeightInPixels(percent: number) {
    return this.getElementContainer().height() * (percent / 100);
  }

  getWidthInPercent() {
    return (this._element.width() / this.getElementContainer().width()) * 100;
  }

  getHeightInPercent() {
    return (this._element.height() / this.getElementContainer().height()) * 100;
  }

  getElementContainer() {
    return this.isRelativeToWindow ? $(window) : this._element.parent();
  }

  getElement() {
    return this.el.nativeElement;
  }
}
