import { CapturedDocument } from './document';
import { BasicObject } from './capture-basic-object';

export class Batch extends BasicObject {
  name: string;
  children: Array<CapturedDocument>;
  constructor(id: string, name: string, children?: Array<CapturedDocument>) {
    super(id);
    this.name = name;
    this.children = children || [];
  }

  addDocument(doc: CapturedDocument): void {
    this.children.push(doc);
  }

  removeDocument(doc: CapturedDocument) {
    this.children.splice(this.children.indexOf(doc), 1);
  }

  getDoc(id: string): CapturedDocument {
    return this.children.filter((doc) => doc.id === id)[0];
  }

  getCurrentDocument(id?: string): CapturedDocument {
    if (!id) {
      return this.children[this.children.length - 1];
    } else {
      return this.getDoc(id);
    }
  }

  getDocumentIndex(doc: CapturedDocument): number {
    return this.children.indexOf(doc);
  }

  getDocumentByIndex(index: number): CapturedDocument {
    return this.children[index];
  }
}
