export interface IApprovalSelection {
  approvalId: string | null;
  templateId: string;
  versionId: string;
}

export class ApprovalSelection implements IApprovalSelection {
  approvalId: string | null;
  templateId: string;
  versionId: string;

  constructor(initializer: IApprovalSelection | null = null) {
    if (initializer) {
      if (initializer.approvalId === undefined) throw new Error('Invalid initializer.approvalId');
      if (initializer.templateId === undefined) throw new Error('Invalid initializer.templateId');
      if (initializer.versionId === undefined) throw new Error('Invalid initializer.versionId');

      this.approvalId = initializer.approvalId;
      this.templateId = initializer.templateId;
      this.versionId = initializer.versionId;
    }
  }

  public serializable(): IApprovalSelection {
    return {
      approvalId: this.approvalId,
      templateId: this.templateId,
      versionId: this.versionId,
    };
  }
}
