import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';
import { AuthService } from './auth/auth.service';

type Preference = { key: string; value: string };

@Injectable({
  providedIn: 'root',
})
export class UserPreferencesService {
  url: string = '';
  public preferencesChanged = new Subject<Array<Preference>>();
  public preferences = Array<Preference>();

  constructor(private http: HttpClient, private authService: AuthService) {}

  loadPreferences(successCallBack: () => void, failureCallBack: (err: any) => void): void {
    this.http.get(`${this.url}api/user/preferences`).subscribe((preferences: Preference[]) => {
      this.preferences = preferences;
      this.preferencesChanged.next(preferences);

      successCallBack();
    }, failureCallBack);
  }

  setPreference(key: string, data: any) {
    if (!key) return;

    let isKeyExisting = false;
    for (let y = 0; y < this.preferences.length; y++) {
      if (this.preferences[y].key === key) {
        isKeyExisting = true;
        this.preferences[y].value = JSON.stringify(data);
      }
    }

    let dataString = JSON.stringify(data);
    if (!isKeyExisting) {
      this.preferences.push({ key: key, value: dataString });
    }

    this.preferencesChanged.next(this.preferences);

    if (this.authService.isLoggedIn()) {
      const httpOptions = {
        headers: new HttpHeaders({
          'Content-Type': 'application/json',
        }),
      };

      this.http.put(`${this.url}api/user/preferences/${key}`, dataString, httpOptions).subscribe(
        (res) => {},
        (err) => {
          throw err;
        }
      );
    }
  }

  getPreference<T>(value: string, defaultValue: T = null): T | any {
    const preference = this.preferences.find((preferenceItem) => preferenceItem.key === value);
    if (preference && preference.value !== undefined) {
      return JSON.parse(preference.value);
    } else {
      return defaultValue;
    }
  }
}
