export interface IImporterAgent {
  agentType: string;
}

export class ImporterAgent implements IImporterAgent {
  public agentType: string;

  public constructor(agentType: string) {
    this.agentType = agentType;
  }

  public static Create(type: string, initializer?): ImporterAgent {
    if (type == 'Upland.Hydra.Importers.Email.Pop3') return new Pop3Agent(initializer);
    if (type == 'Upland.Hydra.Importers.Email.IMap') return new IMapAgent(initializer);
    if (type == 'Upland.Hydra.Importers.Email.Office365') return new Office365Agent(initializer);
    if (type == 'Upland.Hydra.Importers.Fax.InterFAX') return new InterFAXAgent(initializer);

    throw new Error(`Invalidate ImporterAgent Type ${type}`);
  }

  public serializable(): any {
    return {
      agentType: this.agentType,
    };
  }
}

export interface IImporter {
  id: string;
  tenantId: string;
  workflowId: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  name: string;
  type: string;
  agent: IImporterAgent;
  enabled: boolean;
}

export class Importer implements IImporter {
  public id: string;
  public tenantId: string;
  public workflowId: string;
  public dateCreatedUTC: Date;
  public dateModifiedUTC: Date;
  public name: string;
  public type: string;
  public agent: ImporterAgent;
  public enabled: boolean;

  public constructor(initializer?: IImporter) {
    this.dateModifiedUTC = initializer ? initializer.dateModifiedUTC : new Date();
    this.dateCreatedUTC = initializer ? initializer.dateCreatedUTC : new Date();
    this.name = initializer ? initializer.name : '';
    this.id = initializer ? initializer.id : '';
    this.workflowId = initializer ? initializer.workflowId : '';
    this.tenantId = initializer ? initializer.tenantId : '';
    this.type = initializer ? initializer.type : '';
    this.enabled = initializer ? initializer.enabled : true;
    this.agent = initializer ? ImporterAgent.Create(initializer.agent.agentType, initializer.agent) : null;
  }

  public serializable(): IImporter {
    return {
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      name: this.name,
      id: this.id,
      tenantId: this.id,
      workflowId: this.workflowId,
      type: this.type,
      agent: this.agent.serializable(),
      enabled: this.enabled,
    };
  }
}

export class Pop3Agent extends ImporterAgent {
  public host: string;
  public port: number;
  public username: string;
  public password: string;
  public attachmentFilter: string;

  public constructor(initializer?: any) {
    super('Upland.Hydra.Importers.Email.Pop3');

    if (initializer && initializer.host == null) throw new Error('Invalid Pop3 Initializer');
    if (initializer && initializer.port == null) throw new Error('Invalid Pop3 Initializer');
    if (initializer && initializer.username == null) throw new Error('Invalid Pop3 Initializer');
    if (initializer && initializer.password == null) throw new Error('Invalid Pop3 Initializer');

    this.host = initializer ? initializer.host : '';
    this.port = initializer ? initializer.port : '110';
    this.username = initializer ? initializer.username : '';
    this.password = initializer ? initializer.password : '';
    this.attachmentFilter = initializer ? initializer.attachmentFilter : '';
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      host: this.host,
      port: this.port,
      username: this.username,
      password: this.password,
      attachmentFilter: this.attachmentFilter,
    };
  }
}

