import { EmbeddedViewRef, Injectable, ViewContainerRef } from '@angular/core';
import { Subject } from 'rxjs';

import { DropDownDirection } from '../../../models/drop-down';
import { DropDownComponent } from './drop-down.component';
import { DropDownList } from './drop-down.model';

@Injectable({
  providedIn: 'root',
})
export class DropDownService {
  componentRef: any;
  viewContainerRef: ViewContainerRef;

  private _select = new Subject<any>();
  onSelect = this._select.asObservable();
  private _selectViaClick = new Subject<any>();
  onSelectViaClick = this._selectViaClick.asObservable();
  private _tab = new Subject<KeyboardEvent>();
  onTab = this._tab.asObservable();
  private _arrowUpDown = new Subject();
  onArrowUpDown = this._arrowUpDown.asObservable();
  private _scrollUpOrDown = new Subject<void>();
  onScrollUpOrDown = this._scrollUpOrDown.asObservable();
  private _keydown = new Subject<KeyboardEvent>();
  onKeydown = this._keydown.asObservable();
  private _hide = new Subject<KeyboardEvent>();
  onHide = this._hide.asObservable();
  private _clickOutside = new Subject<void>();
  onClickOutside = this._clickOutside.asObservable();
  private _directionChanged = new Subject<DropDownDirection>();
  onDirectionChanged = this._directionChanged.asObservable();
  inProgress = false;
  isLookup = false;

  constructor() {}

  show(dropDown: DropDownList, viewContainerRef: ViewContainerRef) {
    if (this.componentRef) {
      this.hide();
    }

    this.viewContainerRef = viewContainerRef;

    this.componentRef = viewContainerRef.createComponent(DropDownComponent);
    (<DropDownComponent>this.componentRef.instance).data = dropDown.data;

    (<DropDownComponent>this.componentRef.instance)._dropDown = this;

    const domElem = (this.componentRef.hostView as EmbeddedViewRef<any>).rootNodes[0] as HTMLElement;

    document.body.appendChild(domElem);
  }

  hide() {
    if (this.componentRef) {
      this.viewContainerRef.detach();
      this.viewContainerRef.clear();

      this.componentRef.destroy();

      this.componentRef = null;
      this.viewContainerRef = null;

      this._hide.next(undefined);
    }
  }

  update(dropDown: DropDownList) {
    if (!this.componentRef) return;
    (<DropDownComponent>this.componentRef.instance).data = dropDown.data;
  }

  select(value: any): void {
    this._select.next(value);
  }

  selectViaClick(value: any): void {
    this._selectViaClick.next(value);
  }

  tab(event: KeyboardEvent) {
    this._tab.next(event);
  }

  arrowUpDown(event: KeyboardEvent) {
    this._arrowUpDown.next(event);
  }

  scrolled() {
    this._scrollUpOrDown.next();
  }

  keydown(event: KeyboardEvent): void {
    this._keydown.next(event);
  }

  clickOutside(): void {
    this._clickOutside.next();
  }

  directionChanged(direction: DropDownDirection): void {
    this._directionChanged.next(direction);
  }
}
