import { Injectable, ElementRef } from '@angular/core';
import { DropDownDirection } from '../models/drop-down';

declare const $: any;

@Injectable({
  providedIn: 'root',
})
export class CalculationsService {
  constructor() {}

  distanceBetweenElementAndWindowBottom(element: HTMLElement): number {
    const spaceFromTopToElement = element.getBoundingClientRect().bottom;
    const availableSpace = window.innerHeight - spaceFromTopToElement;

    return availableSpace;
  }

  isVisibleInScrollableElement(elem: any, container: any, partial: boolean) {
    const _container = container ? $(container) : $($(elem).closest('.ps')[0]);
    if (!_container) throw new Error('container element is required');
    const _contHeight = _container.height();
    const _contTop = _container.scrollTop();
    const _contBottom = _contTop + _contHeight;

    const _elemTop = $(elem).offset().top - _container.offset().top;
    const _elemBottom = _elemTop + $(elem).height();

    const _isTotal = _elemTop >= 0 && _elemBottom <= _contHeight;
    const _isPart = ((_elemTop < 0 && _elemBottom > 0) || (_elemTop > 0 && _elemTop <= _container.height())) && partial;

    return _isTotal || _isPart;
  }

  isVisibleInHorizontalScrollableElement(elem: any, container: any, partial: boolean) {
    const _container = $(container);
    const _contWidth = _container.width();
    const _contLeft = _container.scrollLeft();
    const _contRight = _contLeft + _contWidth;

    const _elemLeft = $(elem).offset().left - _container.offset().left;
    const _elemRight = _elemLeft + $(elem).width();

    const _isTotal = _elemLeft >= 0 && _elemRight <= _contWidth;
    const _isPart =
      ((_elemLeft < 0 && _elemRight > 0) || (_elemLeft > 0 && _elemLeft <= _container.width())) && partial;

    return _isTotal || _isPart;
  }

  hasEnoughBottomSpace(element: any, parent: ElementRef) {
    const spaceBelow = $(window).height() - $(parent)[0].getBoundingClientRect().bottom;

    return element.height() <= spaceBelow;
  }

  hasEnoughTopSpace(element: any, parent: any) {
    const spaceAbove = parent.offset().top - $(window).scrollTop();

    return element.height() <= spaceAbove;
  }

  getDropDownHeightAndDirection(
    element: any,
    parent: any,
    maxDropdownHeight: number
  ): { top: number; height: number; direction?: DropDownDirection } {
    let top = parent.offset().top;
    const items = element.find('.drop-down-list-item');

    let height = 8;
    for (let i = 0; i < items.length; i++) {
      height += $(items[i]).height();
    }

    let direction: DropDownDirection = DropDownDirection.ToBottom;
    const _window = $(window);
    const spaceAbove = top - _window.scrollTop();
    const spaceBelow = _window.height() - $(parent)[0].getBoundingClientRect().bottom;

    if (height > maxDropdownHeight) {
      height = maxDropdownHeight;
    }

    if (height > spaceAbove && height > spaceBelow) {
      if (spaceAbove > spaceBelow) direction = DropDownDirection.ToTop;
      height = (direction == DropDownDirection.ToTop ? spaceAbove : spaceBelow) - 20;
      top = direction == DropDownDirection.ToTop ? top - height : top + parent.height();
    } else if (height < spaceBelow) {
      top += parent.height();
    } else {
      top -= height;
      direction = DropDownDirection.ToTop;
    }

    return { top, height, direction };
  }
}
