import { HttpErrorResponse, HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { DeviceDetectorService } from 'ngx-device-detector';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { AuthService, PrintToService, SessionStorageService } from 'shared-code-lib';
import { ErrorsService } from '../services/errors.service';
import { SpinnerStateService } from '../services/spinner-state.service';
import { UserStateService } from './../services/user-state.service';

@Injectable()
export class AuthInterceptor implements HttpInterceptor {
  constructor(
    private auth: AuthService,
    private userService: UserStateService,
    private sessionStorageService: SessionStorageService,
    private errorService: ErrorsService,
    private translate: TranslateService,
    private spinner: SpinnerStateService,
    private printToService: PrintToService,
    private deviceDetector: DeviceDetectorService
  ) {}

  intercept(request: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    if (!request.url.startsWith('http')) {
      const locale: any = this.userService.getLocale();
      const token: any = this.auth.getToken();
      const header = {};

      const url = request.url.replace(/\/\//g, '/');

      request = request.clone({ url: url });

      if (token) {
        header['Authorization'] = `Bearer ${token}`;
        header['Mode'] = this.sessionStorageService.getLoginMode();
        header['TimeZone'] = this.getTimeZone();
      }

      const landingdomain = this.sessionStorageService.getLandingDomain();
      if (landingdomain) header['LandingDomain'] = landingdomain;
      header['Browser'] = this.getBrowserName();
      header['OS'] = this.getOs();

      if (locale) header['Accept-Language'] = locale;

      if (header) request = request.clone({ setHeaders: header });
    }

    return next.handle(request).pipe(
      catchError((err: HttpErrorResponse) => {
        if (err.status === 401) {
          this.spinner.hide();
          if (err.error) {
            this.errorService.showErrorsModal(err.error, this.translate.instant('Common.unauthorized-access'));
            return;
          }

          if (request.url.indexOf('user/logout') == -1 && request.url.indexOf('api/locks/unlock') == -1) {
            this.auth.sessionExpired();
          }
        }

        return throwError(err);
      })
    );
  }

  getTimeZone() {
    const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return timeZone;
  }

  getBrowserName(): string {
    if (this.printToService.isPrintToMode) return 'PrintToFax';

    let browserName = this.deviceDetector.browser;
    if (browserName == 'MS-Edge-Chromium' || browserName == 'MS-Edge') browserName = 'Edge';

    if (this.sessionStorageService.getIsMobile() || this.sessionStorageService.getIsInterFaxMobile()) {
      browserName = 'Mobile' + browserName;
    }

    return browserName;
  }

  getOs(): string {
    return this.deviceDetector.os;
  }
}
