import { Component, Input, ViewEncapsulation } from '@angular/core';
import { TextComponent } from '../text/text.component';

import { FieldDefinition } from './../../models/field-definition';

@Component({
  selector: 'app-large-text',
  templateUrl: './large-text.component.html',
  styleUrls: ['./large-text.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class LargeTextComponent extends TextComponent {
  @Input() field: FieldDefinition = undefined;
  @Input() fieldId: string = '';

  private _autosizeMinRows: number;
  get autosizeMinRows() {
    return this._autosizeMinRows;
  }
  @Input() set autosizeMinRows(value: number) {
    this._autosizeMinRows = !value || value <= 0 ? 4 : value;
  }

  private _scrollHeight: string;
  get scrollHeight() {
    return this._scrollHeight;
  }
  @Input() set scrollHeight(value: string) {
    this._scrollHeight = !value ? '84px' : value;
  }

  @Input() autocomplete: string = 'on';

  get textareaContainerHeight() {
    return parseFloat(this.scrollHeight) + 10 + 'px';
  }

  isFocused = false;

  onFocused = (event) => {
    this.onFocus(event);
    this.isFocused = true;
  };

  onBlurred = (event) => {
    this.onBlur(event);
    this.isFocused = false;
  };
}
