import { Injectable } from '@angular/core';
import { ActivatedRouteSnapshot, Router, RouterStateSnapshot } from '@angular/router';
import { AuthService, BrandingService, SessionStorageService } from 'shared-code-lib';

import { UserStateService } from '../services/user-state.service';

@Injectable({
  providedIn: 'root',
})
export class AuthGuard {
  constructor(
    private router: Router,
    private auth: AuthService,
    private userState: UserStateService,
    private brandingService: BrandingService,
    private sessionStorageService: SessionStorageService
  ) {}

  canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot) {
    if (this.auth.isLoggedIn() && !this.isPageRefresh()) {
      return true;
    }

    // not logged in so redirect to login page with the return url
    const loc = this.userState.getLocale();
    this.router.navigate(['/login'], { queryParams: { returnUrl: state.url, locale: loc } });
    return false;
  }

  private isPageRefresh(): boolean {
    return !this.router.navigated;
  }
}
