import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';

@Component({
  selector: 'app-wizard-buttons',
  templateUrl: './wizard-buttons.component.html',
  styleUrls: ['./wizard-buttons.component.scss'],
})
export class WizardButtonsComponent implements OnInit {
  @Input() backEnabled: boolean;
  @Input() showBack: boolean = true;
  @Input() nextEnabled: boolean;
  @Input() nextButtonText: string;
  @Input() displayCancel: boolean = true;

  @Output() onCancel = new EventEmitter<void>();
  @Output() onBack = new EventEmitter<void>();
  @Output() onNext = new EventEmitter<void>();

  constructor() {}

  ngOnInit(): void {
    if (!this.nextButtonText) this.nextButtonText = 'App.next';
  }

  cancel = (): void => {
    this.onCancel.next();
  };

  back = (): void => {
    this.onBack.next();
  };

  next = (): void => {
    this.onNext.next();
  };
}
