import { Point } from '../models/annotation';

export class Graphics {
  static stampImages = new Object();
  public static drawLine = (
    ctx: any,
    xStart: number,
    yStart: number,
    xEnd: number,
    yEnd: number,
    color: string = 'black',
    lineWidth: number = 1
  ): void => {
    ctx.save();
    ctx.lineWidth = lineWidth;
    ctx.strokeStyle = color;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(xStart, yStart);
    ctx.lineTo(xEnd, yEnd);
    ctx.stroke();
    ctx.restore();
  };

  public static drawText = (
    ctx: any,
    text,
    x: number,
    y: number,
    width: number,
    color: string,
    fontSize: number = 16,
    fontName: string = 'Arial'
  ): void => {
    ctx.save();
    ctx.beginPath();
    ctx.font = `$${fontSize}px ${fontName}`;
    ctx.fillStyle = color;
    ctx.textBaseline = 'top';
    ctx.textAlign = 'start';
    ctx.fillText(text, x, y, width);
    ctx.stroke();
    ctx.restore();
  };

  public static drawTextMultiLine = (
    ctx: any,
    text,
    x: number,
    y: number,
    width: number,
    color: string,
    fontSize: number = 16,
    fontName: string = 'Arial',
    topPadding: number = 0,
    leftPadding: number = 0,
    rightPadding: number = 0
  ): void => {
    let lastPhrase: string = '';
    let lineWidth: number = 0;
    let lineHeight: number = 0;
    let lineNumber = 0;

    y += topPadding;
    ctx.font = `${fontSize}px ${fontName}`;
    ctx.fillStyle = color;
    for (var i = 0; i < text.length; i++) {
      let metrics = ctx.measureText(lastPhrase + text[i]);
      lineWidth = metrics.width;
      lineHeight = metrics.fontBoundingBoxAscent + metrics.fontBoundingBoxDescent;

      if (lineWidth < width + leftPadding + rightPadding && i != text.length - 1 && text[i] != '\n') {
        lastPhrase += text[i];
        continue;
      }

      lastPhrase += text[i];
      Graphics.drawText(
        ctx,
        lastPhrase,
        x + rightPadding,
        y + lineNumber++ * lineHeight,
        width,
        color,
        fontSize,
        fontName
      );
      lastPhrase = '';
    }
  };

  public static drawRectangle = (
    ctx,
    x: number,
    y: number,
    width: number,
    height: number,
    color: string = 'black',
    lineWidth: number = 1
  ): void => {
    ctx.save();
    ctx.lineWidth = lineWidth;
    ctx.strokeStyle = color;
    ctx.beginPath();
    ctx.rect(x, y, width, height);
    ctx.stroke();
    ctx.restore();
  };

  public static fillRectangle = (
    ctx,
    x: number,
    y: number,
    width: number,
    height: number,
    color: string = 'black',
    opacity: number = 1
  ): void => {
    ctx.save();
    ctx.fillStyle = color;
    ctx.globalAlpha = opacity;
    ctx.beginPath();
    ctx.fillRect(x, y, width, height);
    ctx.stroke();
    ctx.restore();
  };

  public static drawDottedRectangle = (ctx, x: number, y: number, width: number, height: number): void => {
    ctx.save();
    ctx.beginPath();
    ctx.setLineDash([20, 3, 3, 3, 3, 3, 3, 3]);
    ctx.rect(x, y, width, height);
    ctx.stroke();
    ctx.restore();
  };

  public static drawCircle = (ctx, x, y, width, height, color: string = 'black', lineWidth: number = 1): void => {
    const r = Math.max(width, height) / 2;
    const centerX = x + width / 2;
    const centerY = y + height / 2;
    const scaleX = width >= height ? 1 : width / height;
    const scaleY = height >= width ? 1 : height / width;

    ctx.save();
    ctx.lineWidth = lineWidth;
    ctx.strokeStyle = color;
    ctx.translate(centerX, centerY);
    ctx.scale(scaleX, scaleY);
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, 2 * Math.PI, false);
    ctx.stroke();
    ctx.closePath();
    ctx.restore();
  };

  public static drawArrow = (
    ctx,
    xStart: number,
    yStart: number,
    xEnd: number,
    yEnd: number,
    color: string = 'black',
    lineWidth: number = 1
  ): void => {
    const headLength = Math.max(10, Math.min(25, lineWidth * 5));
    let dx = xEnd - xStart;
    let dy = yEnd - yStart;
    const angle = Math.atan2(dy, dx);
    const arrow1X1 = xEnd - headLength * Math.cos(angle - Math.PI / 4);
    const arrow1Y1 = yEnd - headLength * Math.sin(angle - Math.PI / 4);
    const arrow2X1 = xEnd - headLength * Math.cos(angle + Math.PI / 4);
    const arrow2Y1 = yEnd - headLength * Math.sin(angle + Math.PI / 4);

    let d = Math.sqrt(Math.pow(xStart - xEnd, 2) + Math.pow(yStart - yEnd, 2));
    let t = lineWidth / 2 / d;
    const xEnd2 = (1 - t) * xEnd + t * xStart;
    const yEnd2 = (1 - t) * yEnd + t * yStart;

    const arrowShift = lineWidth / 7;
    d = Math.sqrt(Math.pow(arrow1X1 - xEnd2, 2) + Math.pow(arrow1Y1 - yEnd2, 2)) + arrowShift;
    t = arrowShift / d;
    const arrow1X2 = (xEnd2 - t * arrow1X1) / (1 - t);
    const arrow1Y2 = (yEnd2 - t * arrow1Y1) / (1 - t);

    d = Math.sqrt(Math.pow(arrow2X1 - xEnd2, 2) + Math.pow(arrow2Y1 - yEnd2, 2)) + arrowShift;
    t = arrowShift / d;
    const arrow2X2 = (xEnd2 - t * arrow2X1) / (1 - t);
    const arrow2Y2 = (yEnd2 - t * arrow2Y1) / (1 - t);

    ctx.save();
    Graphics.drawLine(ctx, xStart, yStart, xEnd2, yEnd2, color, lineWidth);
    Graphics.drawLine(ctx, arrow1X2, arrow1Y2, arrow1X1, arrow1Y1, color, lineWidth);
    Graphics.drawLine(ctx, arrow2X2, arrow2Y2, arrow2X1, arrow2Y1, color, lineWidth);

    ctx.restore();
  };

  public static loadStamp = (stamp: string, callBack: (img: any) => void = null) => {
    const img = new Image();
    img.src = `api/user/annotations/stamps/${stamp}`;
    img.addEventListener('load', (e) => {
      if (callBack) callBack(img);
    });
  };

  public static drawStamp = (
    ctx,
    stamp,
    x: number,
    y: number,
    width: number,
    height: number,
    degrees: number = -25
  ): void => {
    if (!Graphics.stampImages[stamp]) {
      Graphics.loadStamp(stamp, (img) => {
        Graphics.stampImages[stamp] = img;
        Graphics.drawStamp(ctx, stamp, x, y, width, height, degrees);
      });
      return;
    }

    ctx.save();
    ctx.beginPath();

    if (degrees != 0) {
      ctx.translate(x, y);
      ctx.rotate((degrees * Math.PI) / 180);
      ctx.translate(-x, -y);
    }

    ctx.drawImage(Graphics.stampImages[stamp], x, y, width, height);
    ctx.stroke();
    ctx.restore();
  };

  public static drawFreeHand = (
    ctx,
    points: Point[],
    width: number,
    height: number,
    color: string = 'black',
    lineWidth: number = 1
  ): void => {
    ctx.save();
    ctx.lineWidth = lineWidth;
    ctx.strokeStyle = color;
    ctx.beginPath();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    for (let i = 0; i < points.length - 1; i++) {
      ctx.moveTo(points[i].x * width, points[i].y * height);
      ctx.lineTo(points[i + 1].x * width, points[i + 1].y * height);
    }
    ctx.stroke();
    ctx.restore();
  };
}
