
export interface IDocument {
  id: string;
  tenantId: string;
  ownerId: string;
  filename: string;
  fileType: string;
  size: number;
  pageCount: number;
}

export class Document implements IDocument {
  constructor(
    public id: string,
    public tenantId: string,
    public ownerId: string,
    public filename: string,
    public fileType: string,
    public size: number,
    public pageCount: number,
  ) {}
}
