import { Component, EventEmitter, Input, OnDestroy, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Subscription } from 'rxjs';
import { FieldDefinition, FixedDataSource, IFieldOptions, MetaDataType } from 'shared-code-lib';
import { Filter } from '../../models/filter';
import { FilterBaseComponent } from '../filter-base.component';

@Component({
  selector: 'app-filter-by-time-period',
  templateUrl: './filter-by-time-period.component.html',
  styleUrls: ['./filter-by-time-period.component.scss'],
})
export class FilterByTimePeriodComponent extends FilterBaseComponent implements OnInit, OnDestroy {
  @Input() filter: Filter;
  @Input() layoutVertically: boolean;
  @Output() selected = new EventEmitter<string>();

  fieldPeriod: FieldDefinition;

  value: string;

  periodsPropertyDataSource = new FixedDataSource(new Array<IFieldOptions>());

  subscriptions = new Subscription();

  constructor(private translate: TranslateService) {
    super();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  ngOnInit(): void {
    this.createFields();

    this.initializeFilter();
    this.subscriptions.add(this.filter.clearFilter.subscribe(this.clearFilter));

    this.periodsPropertyDataSource.options.push(
      {
        name: this.translate.instant('time-period-filter.Day'),
        value: Periods.Day,
      },
      {
        name: this.translate.instant('time-period-filter.Week'),
        value: Periods.Week,
      },
      {
        name: this.translate.instant('time-period-filter.Month'),
        value: Periods.Month,
      },
      {
        name: this.translate.instant('time-period-filter.Quarter'),
        value: Periods.Quarter,
      }
    );

    if (this.filter && !this.filter.value) this.filter.value = this.filter.defaultValue ?? Periods.Week;
    this.value = this.filter?.value ? this.filter.value : Periods.Week;
  }

  clearFilter = (): void => this.setValue(this.filter.defaultValue ?? Periods.Week);

  setValue = (val: string): void => void (this.value = val);

  createFields = (): void => {
    this.fieldPeriod = new FieldDefinition({
      type: MetaDataType.List,
      label: '',
      placeholder: '',
      required: false,
      smallLabel: this.filter.label,
      datasource: this.periodsPropertyDataSource,
    });
  };

  onFieldChanged = (value: string): void => {
    this.filter.value = value;
    this.selected.emit(value);
  };
}

export enum Periods {
  Day = '0',
  Week = '1',
  Month = '2',
  Quarter = '3',
}
