import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';
import { MetaDataDefinition } from 'shared-code-lib';

@Injectable({
  providedIn: 'root',
})
export class HydraApiEventService {
  private _addMetaDataSubject = new Subject<MetaDataDefinition>();
  private _updateMetaDataSubject = new Subject<MetaDataDefinition>();
  private _deleteMetaDataSubject = new Subject<string>();

  onAddMetaData = this._addMetaDataSubject.asObservable();
  onUpdateMetaData = this._updateMetaDataSubject.asObservable();
  onDeleteMetaData = this._deleteMetaDataSubject.asObservable();

  metaDataAdded(metaData: MetaDataDefinition) {
    this._addMetaDataSubject.next(metaData);
  }

  metaDataUpdated(metaData: MetaDataDefinition) {
    this._updateMetaDataSubject.next(metaData);
  }

  metaDataDeleted(id: string) {
    this._deleteMetaDataSubject.next(id);
  }
}
