export interface IPermissionSet {
  name: string;
  primaryPermission: string;
  permissions: Array<string>;
}

export class PermissionSet {
  public name: string;
  public primaryPermission: string;
  public permissions: Array<string>;

  constructor(initializer: IPermissionSet) {
    this.name = initializer.name;
    this.primaryPermission = initializer.primaryPermission;
    this.permissions = initializer.permissions;
  }
}

export interface IRole {
  id: string;
  tenantId: string;
  name: string;
  permissions: Array<string>;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
}

export class Role implements IRole {
  public id: string;
  public tenantId: string;
  public name: string;
  public permissions: Array<string>;
  public dateCreatedUTC: Date;
  public dateModifiedUTC: Date;

  constructor(initializer: IRole) {
    this.id = initializer.id;
    this.tenantId = initializer.tenantId;
    this.name = initializer.name;
    this.permissions = initializer.permissions;
    this.dateCreatedUTC = initializer.dateCreatedUTC;
    this.dateModifiedUTC = initializer.dateModifiedUTC;
  }

  addPermission = (permission: string): boolean => {
    if (!this.permissions.find((p) => p == permission)) {
      this.permissions.push(permission);

      return true;
    }

    return false;
  };

  serializable = (): IRole => {
    return {
      id: this.id,
      tenantId: this.tenantId,
      name: this.name,
      permissions: this.permissions,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
    };
  };
}
