import { Directive, ElementRef, Renderer2, AfterViewInit } from "@angular/core";

@Directive({
  selector: "[appPreventParentScroll]",
})
export class PreventParentScrollDirective implements AfterViewInit {
  lastScrollTop = -1;

  constructor(private el: ElementRef, private renderer: Renderer2) {}

  ngAfterViewInit() {
    this.renderer.listen(this.el.nativeElement, "wheel", (e) => {
      let el = this.el.nativeElement;
      let conditions =
        (el.scrollTop + el.offsetHeight > el.scrollHeight && e.deltaY > 0) ||
        (el.scrollTop === 0 && e.deltaY < 0);
      if (conditions) {
        e = e || window.event;
        e.returnValue = false;
        e.stopPropagation();
      }
    });
  }
}
