export class Arrays {
  public static isSubsetOf = (subsetArray: Array<any>, mainArray: Array<any>): boolean => {
    if (mainArray.length < subsetArray.length) return false;

    for (let i = 0; i < subsetArray.length; i++) {
      if (mainArray[i] != subsetArray[i]) return false;
    }

    return true;
  };
}
