import { Component, OnInit, Input } from '@angular/core';
import { ToastrService } from 'ngx-toastr';
import { TranslateService } from '@ngx-translate/core';
import { DateTimeFormat } from '../../../../../../../Bamba.Web/ClientApp/src/app/blocks/core/dateTimeFormat';
import { ClipboardService } from 'shared-code-lib';

@Component({
  selector: 'app-workitem-properties-journal',
  templateUrl: './workitem-properties-journal.component.html',
  styleUrls: ['./workitem-properties-journal.component.scss'],
})
export class WorkitemPropertiesJournalComponent implements OnInit {
  @Input() details: any;

  constructor(private toastr: ToastrService, private translate: TranslateService) {}

  ngOnInit() {}

  onCopyToClipboard = (): void => {
    let journalText = `ID: ${this.details.id}\n\n`;

    for (const je of this.details.journalEntries) {
      journalText = journalText + `${DateTimeFormat.getLocalDateTimeWithSeconds(je.dateCreatedUTC)} ${je.summary}\n`;
    }

    ClipboardService.copyToClipboard(journalText);

    this.toastr.info(this.translate.instant('general.copied-to-clipboard'));
  };
}
