import { Injectable } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivate, CanActivateChild, Router, RouterStateSnapshot } from '@angular/router';
import { BrandingService } from '../services/branding.service';
import { SessionStorageService } from '../services/session-storage.service';

@Injectable({
  providedIn: 'root',
})
export class BrandGuard implements CanActivate, CanActivateChild {
  constructor(
    protected router: Router,
    private brandService: BrandingService,
    private sessionStorageService: SessionStorageService
  ) {}

  canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean | Promise<boolean> {
    this.brandService.setBrandFromUrl(state.url);

    return this.activationIsAllowed(route);
  }

  canActivateChild(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean | Promise<boolean> {
    this.brandService.setBrandFromUrl(state.url);

    return this.activationIsAllowed(route);
  }

  activationIsAllowed(route: ActivatedRouteSnapshot): boolean | Promise<boolean> {
    if (this.brandService.getBrandDetails()) return true;

    const domain = route.queryParams['domain'];
    this.sessionStorageService.setLandingDomain(domain ? domain : window.location.hostname);

    return this.brandService
      .initializeBrandDetails()
      .then(() => true)
      .catch(() => false);
  }
}
