import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class FilterByOneDriveQuery extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOneDriveQuery';
  }
}

export class OneDriveFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('OneDriveFilters.Create', filter);

    if (filter.id == 'OneDrive-Upland.Bamba.OneDrive.FilterByOneDriveQuery') return new FilterByOneDriveQuery(filter);

    return null;
  };
}
