import {
  Component,
  ElementRef,
  EventEmitter,
  HostListener,
  Input,
  OnChanges,
  OnInit,
  Output,
  Renderer2,
  ViewChild,
  ViewEncapsulation,
} from "@angular/core";

import { Crumb } from "./../models/crumb";
import { DelayService } from "./../utils/delay.service";

@Component({
  selector: "app-breadcrumb",
  templateUrl: "./breadcrumb.component.html",
  styleUrls: ["./breadcrumb.component.scss"],
  encapsulation: ViewEncapsulation.None,
})
export class BreadcrumbComponent implements OnInit, OnChanges {
  @ViewChild("pathsEl") pathsEl: ElementRef;
  @ViewChild("wrapperEl") wrapperEl: ElementRef;

  @Input() crumbs = new Array<Crumb>();

  @Output() onClicked = new EventEmitter<Crumb>();

  readonly dotsWidth = 32;
  hiddenCrumbs: Array<Crumb> = [];
  constructor(private renderer: Renderer2, private delay: DelayService) {}

  ngOnInit(): void {
    this.onClicked.emit(null);
  }

  ngOnChanges(): void {
    this.handlePathsWidth();
  }

  @HostListener("window:resize")
  onResize() {
    this.handlePathsWidth();
  }

  onPathClick(index: number): void {
    if (index === this.crumbs.length - 1) return;

    this.onClicked.emit(this.crumbs[index]);
  }

  private handlePathsWidth(): void {
    this.delay.execute(() => {
      const pathElement = this.pathsEl.nativeElement as HTMLElement;
      const availableWidth = pathElement.offsetWidth;
      const wrapperWidth = this.wrapperEl.nativeElement.offsetWidth;
      const paths: Array<HTMLElement> = this.wrapperEl.nativeElement.querySelectorAll(
        ".path"
      );
      let diff = wrapperWidth - (availableWidth - this.dotsWidth);

      if (wrapperWidth > availableWidth) {
        this.hiddenCrumbs = [];
        let spaceToRemove = paths[0].offsetWidth;
        paths[0].classList.add("hide");
        this.hiddenCrumbs.push(this.crumbs[0]);

        for (let i = 1; i < paths.length; i++) {
          if (diff > spaceToRemove) {
            spaceToRemove += paths[i].offsetWidth;
            this.renderer.addClass(paths[i], "hide");
            this.hiddenCrumbs.push(this.crumbs[i]);
          } else {
            break;
          }
        }

        this.renderer.addClass(pathElement, "has-long-path");
      } else {
        const hasLongPath = pathElement.classList.contains("has-long-path");
        if (hasLongPath) {
          this.handleShowingHiddenElements(
            paths,
            pathElement,
            availableWidth,
            wrapperWidth
          );
        }
      }
    });
  }

  private handleShowingHiddenElements(
    paths: Array<HTMLElement>,
    pathElement: HTMLElement,
    availableWidth: number,
    wrapperWidth: number
  ): void {
    let hiddenElementsWidth = 0;
    const diff = availableWidth - wrapperWidth;
    paths.forEach((path) => {
      if (path.classList.contains("hide")) {
        hiddenElementsWidth += path.offsetWidth;
      }
    });
    if (diff >= hiddenElementsWidth) {
      paths.forEach((path) => {
        this.renderer.removeClass(path, "hide");
        this.hiddenCrumbs = [];
      });
      this.renderer.removeClass(pathElement, "has-long-path");
    } else {
      for (let i = paths.length - 1; i < 0; i--) {
        if (paths[i].classList.contains("hide")) {
          this.renderer.removeClass(paths[i], "hide");
          this.hiddenCrumbs.splice(i, 1);
          hiddenElementsWidth -= paths[i].offsetWidth;

          if (diff - this.dotsWidth >= hiddenElementsWidth && i !== 0) {
            break;
          }

          if (i === 0) {
            this.renderer.removeClass(pathElement, "has-long-path");
          }
        }
      }
    }
  }
}
