export enum DeviceAuthenticationMode {
  Generic = 0,
  User = 1,
}

export interface IDevice {
  id: string;
  tenantId: string;
  name: string;
  serialNumber: string;
  tag: string;
  authenticationMode: DeviceAuthenticationMode;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  enabled: boolean;
  genericUserId: string;
  genericUserEmail: string;
  enableAutomaticIdentityMapping: boolean;
}

export class Device implements IDevice {
  public id: string;
  public tenantId: string;
  public name: string;
  public serialNumber: string;
  public tag: string;
  public authenticationMode: DeviceAuthenticationMode;
  public dateCreatedUTC: Date;
  public dateModifiedUTC: Date;
  enabled: boolean;
  genericUserId: string;
  genericUserEmail: string;
  enableAutomaticIdentityMapping: boolean;

  constructor(initializer: IDevice) {
    this.id = initializer.id;
    this.tenantId = initializer.tenantId;
    this.name = initializer.name;
    this.serialNumber = initializer.serialNumber;
    this.tag = initializer.tag;
    this.authenticationMode = initializer.authenticationMode;
    this.dateCreatedUTC = initializer.dateCreatedUTC;
    this.dateModifiedUTC = initializer.dateModifiedUTC;
    this.enabled = initializer.enabled;
    this.genericUserId = initializer.genericUserId;
    this.genericUserEmail = initializer.genericUserEmail;
    this.enableAutomaticIdentityMapping = initializer.enableAutomaticIdentityMapping;
  }

  serializable = (): IDevice => {
    return {
      id: this.id,
      tenantId: this.tenantId,
      name: this.name,
      serialNumber: this.serialNumber,
      tag: this.tag,
      authenticationMode: this.authenticationMode,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      enabled: this.enabled,
      genericUserId: this.genericUserId,
      genericUserEmail: this.genericUserEmail,
      enableAutomaticIdentityMapping: this.enableAutomaticIdentityMapping,
    };
  };
}
