export interface IClassifierTrainingDocument {
  name: string;
  size: number;
  pageCount: number;
  fileBase64: string;
  dateAddedUTC: Date;
}

export class ClassifierTrainingDocument implements IClassifierTrainingDocument {
  public name: string;
  public size: number;
  public pageCount: number;
  public fileBase64: string;
  public dateAddedUTC: Date;
}

export interface IClassifierFormType {
  id: string;
  tenantId: string;
  workflowId: string;
  workflowStepId: string;
  name: string;
  documents: Array<ClassifierTrainingDocument>;
}

export class ClassifierFormType implements IClassifierFormType {
  public id: string;
  public tenantId: string;
  public workflowId: string;
  public workflowStepId: string;
  public name: string;
  public documents: Array<ClassifierTrainingDocument>;

  constructor(initializer?: IClassifierFormType) {
    this.id = initializer ? initializer.id : '';
    this.tenantId = initializer ? initializer.tenantId : '';
    this.workflowId = initializer ? initializer.workflowId : '';
    this.workflowStepId = initializer ? initializer.workflowStepId : '';
    this.name = initializer ? initializer.name : '';
    this.documents = initializer ? initializer.documents : [];
  }

  public serializable = (): IClassifierFormType => {
    return {
      id: this.id,
      tenantId: this.tenantId,
      workflowId: this.workflowId,
      workflowStepId: this.workflowStepId,
      name: this.name,
      documents: this.documents,
    };
  };
}
