import {
  ContactListRecipient,
  Individual,
  MetaDataCollection,
  MetaDataCollectionDictionary,
  Recipient,
} from 'shared-code-lib';

export interface IMobileActionData {
  dataType: string;
  id: string;
  filename: string;
  metaData: MetaDataCollectionDictionary;
}

export type RecipientTypes = Individual | ContactListRecipient | Recipient;
export interface RecipientContainer<T = RecipientTypes> {
  display: string;
  value: T;
}

export interface IFaxMobileActionData extends IMobileActionData {
  recipients: RecipientContainer[];
  subject: string;
  message: string;
}

export interface IScanToFolderMobileActionData extends IMobileActionData {
  folderId: string;
  format: string;
}

export class MobileActionData {
  metadata = new MetaDataCollection();
  dataType = 'Upland.Bamba.Core.MobileActionData';
  id = '';
  filename = '';

  constructor(initializer: IMobileActionData = null) {
    if (initializer) {
      this.id = initializer.id;
      this.filename = initializer.filename;
      this.metadata = new MetaDataCollection(initializer.metaData);
    }
  }

  public serializable(): any {
    return {
      dataType: this.dataType,
      id: this.id,
      filename: this.filename,
      metaData: this.metadata.serializable(),
    };
  }
}

export class FaxMobileActionData extends MobileActionData {
  dataType = 'Upland.Bamba.Core.FaxMobileActionData';

  recipients: RecipientContainer[] = [];
  subject = '';
  message = '';

  constructor(initializer: IFaxMobileActionData = null) {
    super(initializer);

    if (initializer) {
      this.recipients = initializer.recipients;
      this.subject = initializer.subject;
      this.message = initializer.message;
    }
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,

      recipients: this.recipients,
      subject: this.subject,
      message: this.message,
    };
  }
}

export class ScanToFolderMobileActionData extends MobileActionData {
  dataType = 'Upland.Bamba.Core.ScanToFolderMobileActionData';

  folderId = '';
  format = 'pdf';

  constructor(initializer: IScanToFolderMobileActionData = null) {
    super(initializer);

    if (initializer) {
      this.folderId = initializer.folderId;
      this.format = initializer.format;
    }
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,

      folderId: this.folderId,
      format: this.format,
    };
  }
}

export class MobileUpload {
  public actionData: MobileActionData;
  public pages: Array<File>;
}
