import { Directive, ElementRef, AfterViewInit, Input, Output, EventEmitter, OnChanges } from '@angular/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';

import { CalculationsService } from 'shared-code-lib';

declare const $: any;

export interface ListHeaderOptions {
  scrollbar: PerfectScrollbarDirective;
  listWrapper: ElementRef;
  disabled: boolean;
}

@Directive({
  selector: '[appListHeader]',
})
export class ListHeaderDirective implements AfterViewInit, OnChanges {
  @Output() changeListHeader = new EventEmitter<{ state: boolean; width: number }>();
  @Input() options: ListHeaderOptions;

  private isEnabled = false;
  private subscribed = false;

  constructor(private el: ElementRef, private calc: CalculationsService) {}

  ngAfterViewInit() {
    if (this.options.scrollbar && !this.subscribed) {
      this.options.scrollbar.psScrollY.subscribe(() => {
        this.checkIsEnabled();
      });

      this.subscribed = true;
      this.checkIsEnabled();
    }
  }

  ngOnChanges() {
    if (this.options.scrollbar && !this.subscribed) {
      this.options.scrollbar.psScrollY.subscribe(() => {
        this.checkIsEnabled();
      });

      this.subscribed = true;
      this.checkIsEnabled();
    } else if (this.subscribed) {
      this.checkIsEnabled();
    }
  }

  private checkIsEnabled(): void {
    if (!this.options.disabled) {
      this.init();
    } else {
      if (this.isEnabled) {
        this.isEnabled = false;
      }
    }
  }

  private init(): void {
    const folderContent = $(this.el.nativeElement).find('.folder-content-wrapper').eq(0);
    const folderHeader = $(this.el.nativeElement).find('.grid-header').eq(0);
    const fakeHeaderClass = 'fake-grid-header';
    let fakeFolderHeader = $(this.el.nativeElement).find(`.${fakeHeaderClass}`).eq(0);

    if (!folderHeader.length || !folderContent.length) {
      return;
    }

    const isHeaderVisible = this.calc.isVisibleInScrollableElement(
      fakeFolderHeader.length ? fakeFolderHeader : folderHeader,
      $(this.options.listWrapper.nativeElement),
      false
    );
    const isPartOfContentVisible = this.calc.isVisibleInScrollableElement(
      folderContent,
      $(this.options.listWrapper.nativeElement),
      true
    );

    if (!isHeaderVisible && isPartOfContentVisible) {
      if (!fakeFolderHeader.length) {
        fakeFolderHeader = document.createElement('div');
        fakeFolderHeader.classList.add(fakeHeaderClass);
        fakeFolderHeader.style.height = folderHeader.height() + 'px';
        folderHeader.after(fakeFolderHeader);
        folderHeader.css({
          position: 'absolute',
          width: folderContent.width() + 'px',
          'z-index': 10,
        });
      }

      folderHeader.css({ top: this.options.listWrapper.nativeElement.scrollTop });
    } else {
      folderHeader.css({ position: 'static', top: 'auto' });
      if (fakeFolderHeader.length) {
        fakeFolderHeader.remove();
      }
    }

    this.isEnabled = true;
  }
}
