import { Component, EventEmitter, Input, OnChanges, OnInit, Output, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import moment from 'moment';

import { DateTime } from '../../../utils/date-time.service';
import { Strings } from '../../../utils/strings.service';
import { UserStateService } from './../../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { UtilityService } from './../../../../../Bamba.Web/ClientApp/src/app/blocks/services/utility.service';
import { ICombinedColumn } from './../../../models/column';
import { InvokeAction } from './../../../models/table';
import { ColumnDisplayType } from './../../../utils/enums';

@Component({
  selector: 'app-selection-table-cell',
  templateUrl: './selection-table-cell.component.html',
  styleUrls: ['./selection-table-cell.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class SelectionTableCellComponent implements OnInit, OnChanges {
  @Input() item: any;
  @Input() column: ICombinedColumn;
  @Input() index: number;

  @Output() onDefaultAction = new EventEmitter<InvokeAction>();
  @Output() onShowFileVersions = new EventEmitter();

  classes = '';
  alertText = '';
  value: string;
  formattedValue: string;

  ColumnDisplayType = ColumnDisplayType;

  datelocaleFormat: string = '';
  timelocaleFormat: string = '';

  get valueWithHeaderParameter() {
    return {
      column: this.column,
      item: this.item,
    };
  }

  constructor(
    private userService: UserStateService,
    private utility: UtilityService,
    private translate: TranslateService
  ) {}

  ngOnInit() {
    this.datelocaleFormat = this.userService.getLocalDateFormat();
    this.timelocaleFormat = this.userService.getLocalTimeFormat();

    this.init();
  }

  ngOnChanges() {
    this.init();
  }

  init() {
    this.classes = '';
    this.alertText = '';
    this.value = this.item.values[this.column.id];
    this.formattedValue = this.getFormattedValue(this.value);

    if (this.item.classes && (!this.item.classesColumnId || this.item.classesColumnId == this.column.id)) {
      this.classes = this.item.classes;
      this.alertText = this.item.alertText;
    }
  }

  getFormattedValue(value: any): string {
    if (!value) return '';

    if (this.column.displayType === ColumnDisplayType.DateTime || this.column.displayType === ColumnDisplayType.Date) {
      if (DateTime.isMinimumDateValue(value)) {
        return this.translate.instant('general.date-not-applicable');
      }

      if (this.column.displayType === ColumnDisplayType.DateTime) {
        return this.formatValue(value, this.datelocaleFormat) + ' ' + this.formatValue(value, this.timelocaleFormat);
      }

      if (this.column.displayType === ColumnDisplayType.Date) {
        return this.formatValue(value, this.datelocaleFormat);
      }
    }

    if (this.column.displayType === ColumnDisplayType.Time) {
      return this.formatValue(value, this.timelocaleFormat);
    }

    if (this.column.displayType === ColumnDisplayType.Number) {
      return this.utility.localizeNumber(value);
    }

    if (this.column.displayType === ColumnDisplayType.FileVersions) {
      if (!this.item.versions || this.item.versions.length == 0) return '';

      this.alertText = `${this.item.versions.length} this.translate.instant('general.file-versions-available')`;

      return `+${this.item.versions.length}`;
    }

    if (this.column.displayType === ColumnDisplayType.Html) return Strings.HtmlToText(value);

    return value;
  }

  formatValue(value: any, formater: string): string {
    return moment(value).local().format(formater);
  }

  onDefaultActionClicked = (): void => {
    this.onDefaultAction.emit({
      action: this.item.defaultAction,
      item: this.item,
      index: this.index,
    });
  };

  onFileVersionsClicked = (): void => {
    this.onShowFileVersions.emit();
  };
}
