import {
  Directive,
  ElementRef,
  HostBinding,
  ChangeDetectorRef,
  Output,
  EventEmitter,
  Renderer2,
  Input,
  AfterViewInit,
  OnInit,
  OnDestroy,
  HostListener,
} from '@angular/core';
import { Subscription } from 'rxjs';
import { filter } from 'rxjs/operators';

import { CalculationsService } from './../utils/calculations.service';
import { DocumentEventsService } from '../../../Bamba.Web/ClientApp/src/app/views/document-capture/capture-services/document-events.service';
import { Key } from './../utils/key-enum';
import { DropDownService } from '../fields/list/drop-down/drop-down.service';
declare const $: any;

@Directive({
  selector: '[appOpenDropdown]',
})
export class OpenDropdownDirective implements OnInit, AfterViewInit, OnDestroy {
  bodyElement: HTMLElement;
  private dropdownElement: HTMLElement;
  private isOpened = false;
  @Input() openOnSearch: boolean;
  @Input() ignoreDocumentClick: boolean = false;
  @Input() hideOnSelectViaClick = false;

  _dropdownService: DropDownService;
  @Input() set dropdownService(value: DropDownService) {
    this._dropdownService = value;
    this.subscriptions.add(this.dropdownService.onClickOutside.subscribe(() => this.hide()));
    this.subscriptions.add(
      this._dropdownService.onSelectViaClick.subscribe(() => {
        if (this.hideOnSelectViaClick) {
          this.hide();
        }
      })
    );
  }

  get dropdownService(): DropDownService {
    return this._dropdownService;
  }

  @Output() onSearchStarted = new EventEmitter<KeyboardEvent>();
  @Output() onHideMenu: EventEmitter<any>;
  @Output() onShowMenu: EventEmitter<any>;

  @HostBinding('class.is-open') toggleDropDownOpen: boolean;
  @HostBinding('class.active') toggleActive: boolean;
  @HostBinding('class.to-top') positionToTop: boolean;
  @HostBinding('class.to-bottom') positionToBottom: boolean;

  @HostListener('document:keydown.escape', ['$event'])
  onEscapeKeyDown(event: KeyboardEvent) {
    this.onKeyDown(event);
  }

  subscriptions: Subscription;

  constructor(
    private elementRef: ElementRef,
    private cdr: ChangeDetectorRef,
    private renderer: Renderer2,
    private calculations: CalculationsService,
    private documentEventsService: DocumentEventsService
  ) {
    this.toggleDropDownOpen = false;
    this.toggleActive = false;
    this.onHideMenu = new EventEmitter();
    this.onShowMenu = new EventEmitter();
    this.subscriptions = new Subscription();
  }

  ngOnInit() {
    this.subscriptions.add(
      this.documentEventsService.onDocumentClick
        .pipe(
          filter((event) => {
            const target = event?.target as any;
            return !(this.ignoreDocumentClick && target?.closest('.dropdown-menu') != null);
          })
        )
        .subscribe((event) => this.onClick(event))
    );

    this.subscriptions.add(
      this.documentEventsService.onDocumentKeyDownSubject.subscribe((event) => this.onKeyDown(event))
    );
  }

  ngAfterViewInit() {
    this.dropdownElement = $(this.elementRef.nativeElement).children('.dropdown-menu');
  }

  onClick(event: MouseEvent): void {
    const targetElement = event.target;
    if (!targetElement) return;

    if (this.elementRef.nativeElement.contains(targetElement)) {
      this.toggleDropDownOpen = !this.toggleDropDownOpen;
      this.toggleActive = !this.toggleActive;
    } else {
      this.toggleDropDownOpen = false;
      this.toggleActive = false;
      this.resetDropDownPositioning();
    }

    if (this.toggleDropDownOpen === false) {
      this.emitHideEvent();
    } else {
      this.isOpened = true;
      this.onShowMenu.emit();
      this.handlePositioning();
    }

    this.cdr.detectChanges();

    if ((targetElement as any).tagName == 'INPUT') (targetElement as any).focus();
  }

  onKeyDown(event: KeyboardEvent): void {
    if ((event.shiftKey && event.key === Key.Tab) || event.key === Key.Tab || event.key === Key.Escape) this.hide();

    const targetElement = event.target;
    if (!targetElement) return;

    if (!this.elementRef.nativeElement.contains(targetElement)) {
      return;
    }

    if (event.key === Key.Enter || event.key === Key.ArrowDown) {
      this.toggleDropDownOpen = !this.toggleDropDownOpen;
      this.toggleActive = !this.toggleActive;
      if (this.toggleDropDownOpen === false) {
        this.emitHideEvent();
      } else {
        this.isOpened = true;
        this.onShowMenu.emit();
        this.handlePositioning();
      }
    } else if (this.openOnSearch && !this.toggleDropDownOpen) {
      const isLetter = /^[a-z]$/i.test(event.key);
      const isNumber = /^[0-9]$/i.test(event.key);
      if (isLetter || isNumber) {
        this.toggleDropDownOpen = this.toggleActive = true;
        this.isOpened = true;
        this.onShowMenu.emit();
        this.handlePositioning();
        this.onSearchStarted.emit(event);
      }
    }
  }

  handlePositioning() {
    if (this.dropdownElement) {
      const parent = this.elementRef.nativeElement;
      const hasEnoughBottomSpace = this.calculations.hasEnoughBottomSpace(this.dropdownElement, parent);
      if (hasEnoughBottomSpace) {
        this.positionToBottom = true;
        this.positionToTop = false;
      } else {
        this.positionToBottom = false;
        this.positionToTop = true;
      }
    }
  }

  resetDropDownPositioning() {
    if (!this.bodyElement) {
      this.bodyElement = document.querySelector('body');
    }

    this.positionToTop = false;
    this.positionToBottom = false;
    this.renderer.removeClass(this.bodyElement, 'top-drop-down');
  }

  emitHideEvent(): void {
    if (this.isOpened) {
      this.isOpened = false;
      this.onHideMenu.emit();
    }
  }

  hide = (): void => {
    this.toggleDropDownOpen = false;
    this.toggleActive = false;
    this.emitHideEvent();
    this.resetDropDownPositioning();
  };

  ngOnDestroy() {
    this.subscriptions.unsubscribe();
  }
}
