import { EditorComponent, EditorView, Transaction } from '@progress/kendo-angular-editor';
import { domToPmDoc, htmlToFragment, pmDocToFragment } from '@progress/kendo-editor-common';
import { Node, ResolvedPos, Schema } from 'prosemirror-model';
import { Selection } from 'prosemirror-state';
import {
  goToNextCell,
  addColumnAfter as pmAddColumnAfter,
  addColumnBefore as pmAddColumnBefore,
  TableMap,
} from 'prosemirror-tables';
import { domAttributes } from '../editor-schema/utills';
import { NavigationDirection } from '../models';

interface ITablePositionInfo {
  pos: number;
  node: Node;
}

interface ITableData {
  node: Node;
  depth: number;
  resolvedPosition: ResolvedPos;
}

const colgroupAttr = 'k-colgroup-data';
const reTable = /^table$/;
const reCell = /^table_cell|table_header$/;

const closest = (selection: Selection, name: RegExp): ITablePositionInfo => {
  const pos = selection.$head;
  for (let i = pos.depth; i > 0; i--) {
    const node = pos.node(i);
    if (name.test(node.type.name)) {
      return {
        pos: pos.before(i),
        node,
      };
    }
  }
  return null;
};

const columnIndex = (table: ITablePositionInfo, selection: Selection) => {
  if (!table) {
    return -1;
  }
  const map = TableMap.get(table.node);
  const tableCell = closest(selection, reCell);
  const idx = map.map.indexOf(tableCell.pos - table.pos - 1);
  let colIndex = -1;
  if (idx !== -1) {
    colIndex = idx % map.width;
  }
  return colIndex;
};

const addCol = (tr: Transaction, table: ITablePositionInfo, to: number) => {
  const colIndex = columnIndex(table, tr.selection);
  const colgroup: any = parseStrColgroup(table.node.attrs[colgroupAttr]);

  const focusedCol = colgroup.children[colIndex - 1];

  const newCol = colgroup.ownerDocument.createElement('col');
  newCol.style = focusedCol.attributes.style.value;

  colgroup.insertBefore(newCol, colgroup.children[colIndex + to]);

  tr.setNodeMarkup(
    table.pos,
    null,
    Object.assign(Object.assign({}, table.node.attrs), { [colgroupAttr]: colgroup.outerHTML })
  );
};

const defaultAttrs = (attrs: string[]) => {
  const nodeAttrs = {};
  attrs.forEach((attr) => {
    nodeAttrs[attr] = { default: null };
  });
  return nodeAttrs;
};

const colgroupNodes = {
  doc: { content: 'colgroup*' },
  col: {
    attrs: defaultAttrs(['id', 'class', 'style', 'span']),
    parseDOM: [{ getAttrs: domAttributes, tag: 'col' }],
    toDOM: function (node) {
      return ['col', node.attrs];
    },
  },
  colgroup: {
    attrs: defaultAttrs(['id', 'class', 'style', 'span']),
    content: 'col*',
    parseDOM: [{ getAttrs: domAttributes, tag: 'colgroup' }],
    toDOM: function (node) {
      return ['colgroup', node.attrs, 0];
    },
  },
  text: { inline: true, group: 'inline' },
};

const colgroupSchema = new Schema({ nodes: colgroupNodes as any, marks: {} });

const parseStrColgroup = (colgroup: string) => {
  const doc = domToPmDoc(htmlToFragment(colgroup), colgroupSchema, { preserveWhitespace: false });
  const fragment = pmDocToFragment(doc);
  const colgroupEl = fragment.firstChild;
  return colgroupEl;
};

const addColumnBefore = (view: EditorView) => {
  const { state, dispatch } = view;

  const cmdDispatch =
    dispatch &&
    ((tr) => {
      const table = closest(tr.selection, reTable);
      if (!table.node.attrs[colgroupAttr]) {
        dispatch(tr);
        view.focus();
        return;
      }

      addCol(tr, table, -1);
      dispatch(tr);
      view.focus();
      return;
    });
  return pmAddColumnBefore(state, cmdDispatch);
};

const addColumnAfter = (view: EditorView) => {
  const { state, dispatch } = view;

  const cmdDispatch =
    dispatch &&
    ((tr) => {
      const table = closest(tr.selection, reTable);
      if (!table.node.attrs[colgroupAttr]) {
        dispatch(tr);
        view.focus();
        return;
      }

      addCol(tr, table, 1);
      dispatch(tr);
      view.focus();
      return;
    });
  return pmAddColumnAfter(state, cmdDispatch);
};

const removeTable = (view: EditorView) => {
  const { state, dispatch } = view;

  const { node, depth, resolvedPosition } = getNearestTableNodeData(view);

  if (!node) return false;

  const parentDepth = depth - 1;
  const isNestedTable = parentDepth >= 1;

  if (isNestedTable) {
    const parentPos = resolvedPosition.before(parentDepth);
    const $parentPos = state.doc.resolve(parentPos);

    const selection = Selection.near($parentPos);
    dispatch(state.tr.setSelection(selection));
  } else {
    const tablePos = resolvedPosition.before(depth);
    const $tablePos = state.doc.resolve(tablePos);

    if ($tablePos.nodeBefore) {
      const previousSiblingPos = $tablePos.pos - $tablePos.nodeBefore.nodeSize;
      const $previousSiblingPos = state.doc.resolve(previousSiblingPos);

      const previousSiblingNode = $previousSiblingPos.nodeAfter;

      if (previousSiblingNode.type.spec.tableRole == 'table') {
        const selection = Selection.findFrom($previousSiblingPos, 1);
        dispatch(state.tr.setSelection(selection));
      }
    }
  }

  view.dispatch(view.state.tr.delete(resolvedPosition.before(depth), resolvedPosition.after(depth)).scrollIntoView());

  view.focus();

  return true;
};

const removeRow = (editor: EditorComponent) => {
  const { node } = getNearestTableNodeData(editor.view);
  const hasOneRow = tableHasOneRow(node);

  if (hasOneRow) {
    removeTable(editor.view);
    return;
  }

  editor.exec('deleteRow');
  editor.focus();
};

const removeColumn = (editor: EditorComponent) => {
  const { node } = getNearestTableNodeData(editor.view);
  const hasOneColumn = tableHasOneColumn(node);

  if (hasOneColumn) {
    removeTable(editor.view);
    return;
  }

  editor.exec('deleteColumn');
  editor.focus();
};

const tableHasOneRow = (node: Node) => {
  validateTableNode(node);
  return node.content.childCount === 1;
};

const tableHasOneColumn = (node: Node) => {
  validateTableNode(node);

  let hasOneColumn = true;

  node.content.forEach((row: Node) => {
    hasOneColumn = hasOneColumn && row.content.childCount === 1;
  });

  return hasOneColumn;
};

const validateTableNode = (node: Node) => {
  if (node.type.spec.tableRole !== 'table') throw new Error('Node should be a table node.');
};

const getNearestTableNodeData = (view: EditorView): ITableData => {
  const { state } = view;
  const $pos = state.selection.$anchor;

  for (let d = $pos.depth; d > 0; d--) {
    const node = $pos.node(d);

    if (node.type.spec.tableRole == 'table') {
      return { node, depth: d, resolvedPosition: $pos };
    }
  }

  return null;
};

const cursorIsInsideTable = (view: EditorView) => {
  const tableData = getNearestTableNodeData(view);
  return !!tableData?.node;
};

const goToNextTableCell = (view: EditorView, direction: NavigationDirection) => {
  const { state, dispatch } = view;
  const moved = goToNextCell(direction)(state, dispatch);
  if (!moved) return;

  const selection = Selection.findFrom(
    direction === NavigationDirection.Forward ? view.state.selection.$from : view.state.selection.$to,
    direction
  );

  view.dispatch(view.state.tr.setSelection(selection));
};

export {
  addColumnAfter,
  addColumnBefore,
  cursorIsInsideTable,
  goToNextTableCell,
  removeColumn,
  removeRow,
  removeTable,
};
