import { MetaDataCollection, MetaDataCollectionDictionary } from 'shared-code-lib';

export interface IIntegratedApplication {
  id: string;
  application: string;
  roleIds: Array<string>;
  enabled: boolean;
  data: MetaDataCollectionDictionary;
  applicationDisplayName: string;
}

export class IntegratedApplication {
  public id: string;
  public application: string;
  public roleIds: Array<string>;
  public enabled: boolean;
  public data: MetaDataCollection;
  public applicationDisplayName: string;

  public constructor(initializer: IIntegratedApplication) {
    this.id = initializer.id;
    this.application = initializer.application;
    this.enabled = initializer.enabled;
    this.roleIds = initializer.roleIds.map(x => x);
    this.data = new MetaDataCollection(initializer.data);
    this.applicationDisplayName = initializer.applicationDisplayName;
  }

  public serializable(): IIntegratedApplication {
    return {
      id: this.id,
      application: this.application,
      roleIds: this.roleIds.map(x => x),
      enabled: this.enabled,
      data: this.data.serializable(),
      applicationDisplayName: this.applicationDisplayName,
    };
  }
}

export interface IIntegratedApplicationSettings {
  application: string;
  username: string;
  secret: string;
}

export class IntegratedApplicationSettings {
  application: string;
  username: string;
  secret: string;

  public constructor(initializer: IIntegratedApplicationSettings) {
    if (initializer.application == null) throw new Error('Invalid IntegratedApplicationSettings Initializer');
    if (initializer.username == null) throw new Error('Invalid IntegratedApplicationSettings Initializer');
    if (initializer.secret == null) throw new Error('Invalid IntegratedApplicationSettings Initializer');

    this.application = initializer.application;
    this.username = initializer.username;
    this.secret = initializer.secret;
  }

  public serializable(): IIntegratedApplicationSettings {
    return {
      application: this.application,
      username: this.username,
      secret: this.secret,
    };
  }
}
