import { Injectable, OnDestroy } from '@angular/core';
import { User, UserManager, UserManagerSettings } from 'oidc-client';
import { Subscription } from 'rxjs';
import { AuthService, SessionStorageService } from 'shared-code-lib';

const AUTHORITY = 'sso-authority';
const CLIENTID = 'sso-client-id';

@Injectable({
  providedIn: 'root',
})
export class SsoManagerService implements OnDestroy {
  subscriptions = new Subscription();
  private _manager: UserManager;

  private get manager() {
    if (this._manager == null) {
      this._manager = this.createUserManager();
    }
    return this._manager;
  }

  constructor(private ss: SessionStorageService, authService: AuthService) {
    this.subscriptions.add(authService.onLogout.subscribe(this.logout));
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  startSignin = (authority: string, clientid: string): void => {
    this.storeDetails(authority, clientid);
    this.manager.signinRedirect();
  };

  completeSignin = (): Promise<User> => {
    return this.manager.signinRedirectCallback();
  };

  storeDetails = (authority: string, clientid: string): void => {
    sessionStorage.setItem(AUTHORITY, authority);
    sessionStorage.setItem(CLIENTID, clientid);
  };

  createUserManager = (): UserManager => {
    const isMobile = this.ss.getIsMobile();
    const isInterFaxMobile = this.ss.getIsInterFaxMobile();

    const postLogoutRedirectURI =
      !isMobile && !isInterFaxMobile
        ? `${window.location.origin}/login`
        : !isInterFaxMobile
        ? `${window.location.origin}/mobile/login`
        : `${window.location.origin}/fax-mobile/login`;

    const ums: UserManagerSettings = {
      authority: sessionStorage.getItem(AUTHORITY),
      client_id: sessionStorage.getItem(CLIENTID),
      redirect_uri: `${window.location.origin}/sso-callback`,
      post_logout_redirect_uri: postLogoutRedirectURI,
      response_type: 'id_token',
      scope: 'openid profile email',
      filterProtocolClaims: true,
      loadUserInfo: true,
    };

    return new UserManager(ums);
  };

  logout = (): void => {
    if (!this.isLoggedInViaSSO()) return;

    sessionStorage.removeItem(AUTHORITY);
    sessionStorage.removeItem(CLIENTID);

    this.manager.signoutRedirect();
  };

  private isLoggedInViaSSO = (): boolean => !!sessionStorage.getItem(AUTHORITY);
}
