import { Component, Input, ViewChild, ElementRef, ViewEncapsulation } from '@angular/core';
import { Dictionary, Control } from '../../services/models';

declare const $: any;
@Component({
  selector: 'app-secondary-header',
  templateUrl: './secondary-header.component.html',
  styleUrls: ['./secondary-header.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class SecondaryHeaderComponent {
  @Input() headerText: string;
  @Input() icon: string;
  @Input() isConfigPage: boolean;
  @Input() routes: { url: string; name: string }[];
  @Input() isHomePage: boolean;
  @Input() breadCrumbs: Array<Dictionary>;
  @Input() rightControls: Array<Control>;
  @ViewChild('menu') menu: ElementRef;
}
