export const showOrHidePageBreaks = (text: string, show: boolean) => {
  const domParser = new DOMParser();
  const textDomNode = domParser.parseFromString(text, 'text/html');
  const hrElements = textDomNode.querySelectorAll(`hr`);

  hrElements.forEach((hr) => {
    const newStyle = show
      ? `border-top: ${hr.style.borderTop};`
      : hr.getAttribute('style') + ' page-break-after: always; visibility: hidden;';
    hr.setAttribute('style', newStyle);
  });

  return textDomNode.body.innerHTML;
};
