import { AfterViewInit, Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';

import { SsoManagerService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/auth/sso-manager.service';
import { UserSignOnType } from '../../../../Bamba.Web/ClientApp/src/app/blocks/models/user-profile';
import { BackButtonService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/back-button.service';
import { BambaDetailsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/bamba-details.service';
import { HydraApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { IDPSettings } from '../../models/sso';
import { AuthService } from '../../services/auth/auth.service';
import { BrandingService } from '../../services/branding.service';
import { PrintToService } from '../../services/print-to.service';
import { SessionStorageService } from '../../services/session-storage.service';
import { DelayService } from '../../utils/delay.service';
import { LoginBaseComponent, LoginModes } from '../login-base/login-base.component';
import { FieldDefinition } from './../../models/field-definition';
import { MetaDataType } from './../../models/metadata-definition';

export class SignOnDetailsResult {
  id: string;
  userSignOnType: UserSignOnType;
  ssoAuthority: string;
  ssoClientId: string;
  idp: IDPSettings;
}

declare const $: any;

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
})
export class LoginComponent extends LoginBaseComponent implements OnInit, AfterViewInit {
  fieldUsername: FieldDefinition;
  username = '';

  showRegistrationOptions = false;

  isModuleLoading: boolean = false;
  isFirst: boolean = true;
  deviceMode = false;
  printToFaxMode = false;

  constructor(
    hydraApi: HydraApiService,
    private route: ActivatedRoute,
    private backButtonService: BackButtonService,
    private ssoManagerService: SsoManagerService,
    authService: AuthService,
    spinnerStateService: SpinnerStateService,
    translateService: TranslateService,
    bds: BambaDetailsService,
    userState: UserStateService,
    sss: SessionStorageService,
    bs: BrandingService,
    r: Router,
    private delay: DelayService,
    private printToService: PrintToService
  ) {
    super(hydraApi, spinnerStateService, translateService, authService, bds, userState, sss, bs, r);
  }

  ngOnInit(): void {
    this.authService.logout();
    this.userStateService.clearIdleTimeOut();

    super.ngOnInit();

    this.backButtonService.moduleLoadingChanged.subscribe((isModuleLoading) => {
      this.isModuleLoading = isModuleLoading;
    });

    this.backButtonService.preventBackButton(this.handleBackButton);

    this.sessionStorageService.setReturnUrl(this.route.snapshot.queryParams['returnUrl']);
    this.sessionStorageService.setLoginMode(this.route.snapshot.queryParams['mode']);
    this.sessionStorageService.setIsMobile(this.brandingService.isMobileLogin());
    this.sessionStorageService.setIsInterFaxMobile(this.brandingService.isInterFaxMobileLogin());
    if (this.sessionStorageService.getIsMobile() || this.sessionStorageService.getIsInterFaxMobile()) {
      this.brandingService.setPWAData();
    }

    this.deviceMode = this.sessionStorageService.getLoginMode() == LoginModes.Device;
    this.printToFaxMode = this.printToService.isPrintToMode;

    if (this.authService.isLoggedIn() || (!this.deviceMode && this.authService.restartSharedSessionForTabs())) {
      this.router.navigateByUrl('complete-user-info');
    }

    this.subscriptions.add(
      this.route.params.subscribe((params) => {
        if (params && params.locale) {
          this.userStateService.setNewLocal(params.locale);
        }
      })
    );

    this.translateService.get('Login.Username').subscribe((text) => {
      this.fieldUsername = new FieldDefinition({
        type: MetaDataType.Text,
        label: this.translateService.instant(text),
        placeholder: '',
        required: false,
      });
    });

    this.showRegistrationOptions = this.brandingService.isBranded();

    this.username = this.sessionStorageService.getUsername() || '';
  }

  ngAfterViewInit() {
    this.delay.execute(this.handleAutoFill, 2000);
  }

  handleAutoFill = (): void => {
    const elements = $('input:-webkit-autofill');
    if (elements.length > 0) {
      for (let i = 0; i < elements.length; i++) {
        if ($(elements[i]).attr('id') == 'field-text-Username') $('#btn-login-next').prop('disabled', false);
      }
    }
  };

  handleBackButton = () => {
    if (!this.isModuleLoading) {
      if (this.isSubmitted || (!this.isSubmitted && this.backButtonService.previousURL !== '')) return;
      history.go(-2);
    } else {
      if (!this.isFirst) return;

      this.isFirst = false;
      setTimeout(() => {
        this.router.navigateByUrl(this.userStateService.getUserHomePage());
      }, 3000);
    }
  };

  ngOnDestroy() {
    this.backButtonService.removeBackButtonListener();
  }

  getUserSignOnDetails(e) {
    e.preventDefault && e.preventDefault();

    if (!this.username.trim()) return;

    this.translateService.get('Login.Verify-Username-Message').subscribe((res) => {
      this.spinnerStateService.show(res, this.loginDivElement);
      this.authService.getUserSignOnDetails(
        this.username,
        this.getUserSignOnDetailsSuccess,
        this.getUserSignOnDetailsFailure
      );
    });
  }

  getUserSignOnDetailsSuccess = (sr: SignOnDetailsResult) => {
    this.spinnerStateService.hide();
    this.isSubmitted = false;

    if (sr.userSignOnType === UserSignOnType.Password) {
      this.sessionStorageService.setUsername(this.username);
      this.router.navigate(['/login-password']);
    } else if (sr.userSignOnType == UserSignOnType.SSO) {
      this.printToService.setCredentials(this.username, '#SSO#');
      this.translateService.get('Login.transferring-to-sso').subscribe((res) => {
        this.spinnerStateService.show(res, this.loginDivElement);
        this.ssoManagerService.startSignin(sr.ssoAuthority, sr.ssoClientId);
      });
    } else if (sr.userSignOnType == UserSignOnType.SAML) {
      this.printToService.setCredentials(this.username, '#SAML');
      this.translateService.get('Login.transferring-to-sso').subscribe((res) => {
        this.spinnerStateService.show(res, this.loginDivElement);
        const url = `${window.location.protocol}//${window.location.host}/api/saml/InitiateSingleSignOn?id=${sr.id}&returnUrl=${window.location.origin}/saml-callback`;
        window.location.href = url;
      });
    }
  };

  getUserSignOnDetailsFailure = (error: any) => {
    this.spinnerStateService.hide();
    this.isSubmitted = false;

    this.errorOccurred = true;
    this.loginErrorText = this.translateService.instant('Login.Verify-Username-Failed');
  };

  forceBinding() {
    const inputs = this.loginDiv.nativeElement.querySelectorAll('input');
    if (inputs.length) {
      for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];
        if (input.id === `field-text-${this.fieldUsername.label}` && input.value !== this.username) {
          this.username = input.value;
        }
      }
    }
  }
}
