import { Component, OnInit, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastrService } from 'ngx-toastr';
import { TranslateService } from '@ngx-translate/core';
import { BambaDetailsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/bamba-details.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { AuthService } from '../../services/auth/auth.service';
import { BrandingService } from '../../services/branding.service';
import { SessionStorageService } from '../../services/session-storage.service';
import { LoginBaseComponent } from '../login-base/login-base.component';
import { ErrorsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/errors.service';
import { InterFAXService } from '../../../../Bamba.Web//ClientApp/src/app/blocks/services/interfax.service';
import { ApiResult } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/models';
import { HydraApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';

@Component({
  selector: 'app-3ds-callback',
  templateUrl: './3ds-callback.component.html',
  styleUrls: ['./3ds-callback.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class ThreeDSCallbackComponent extends LoginBaseComponent implements OnInit {
  constructor(
    hydraApi: HydraApiService,
    protected sessionStorageService: SessionStorageService,
    authService: AuthService,
    userStateService: UserStateService,
    spinnerStateService: SpinnerStateService,
    translateService: TranslateService,
    bds: BambaDetailsService,
    bs: BrandingService,
    router: Router,
    private interFAXService: InterFAXService,
    private toastr: ToastrService,
    private errorService: ErrorsService,
    private route: ActivatedRoute
  ) {
    super(
      hydraApi,
      spinnerStateService,
      translateService,
      authService,
      bds,
      userStateService,
      sessionStorageService,
      bs,
      router
    );
  }

  ngOnInit(): void {
    this.spinnerStateService.show(
      this.translateService.instant('fax-user-create.complete-3ds-process'),
      document.documentElement
    );

    this.interFAXService.complete3DsProcess(this.get3DSParams(), this.on3DSProcessSucceeded, this.on3DSProcessFailed);
  }

  on3DSProcessSucceeded = (result: ApiResult): void => {
    this.spinnerStateService.hide();
    this.toastr.success(this.translateService.instant('fax-user-create.3ds-process-succeeded'));

    this.goHome(true);

    this.userStateService.accountchanged.next();
  };

  on3DSProcessFailed = (err: any): void => {
    this.spinnerStateService.hide();
    this.errorService.showErrorsModal([err], this.translateService.instant('fax-user-create.3ds-process-failed'));
    this.subscriptions.add(this.errorService.closed.subscribe(this.goHome));
  };

  goHome = (succeeded: boolean = false): void => {
    let returnUrl = this.route.snapshot.queryParamMap.get(succeeded ? 'successCallbackUrl' : 'failureCallbackUrl');
    if (!returnUrl) returnUrl = this.route.snapshot.queryParamMap.get('callbackUrl');
    if (!returnUrl) returnUrl = '/home';
    this.router.navigateByUrl(returnUrl);
  };

  identifyFlow = (): string => {
    if (!this.route.snapshot.params || !Object.keys(this.route.snapshot.params).length)
      return ThreeDSFlows.GatewayHosted;

    if (this.route.snapshot.params['THREEDSMETHODDATA']) return ThreeDSFlows.MethodUrl;
    if (this.route.snapshot.params['CRES']) return ThreeDSFlows.FormAction;

    return ThreeDSFlows.ACSURL;
  };

  get3DSParams = (): string => {
    const flow = this.identifyFlow();

    if (flow == ThreeDSFlows.GatewayHosted) {
      const ref = this.route.snapshot.queryParamMap.get('REF');
      const returnMAC = this.route.snapshot.queryParamMap.get('RETURNMAC');
      const method = this.route.snapshot.queryParamMap.get('Method');

      return `REF=${ref}&RETURNMAC=${returnMAC}&Flow=${flow}&Method=${method}`;
    }

    throw new Error(`Unsupported 3DS flow ${flow}`);
  };
}

export enum ThreeDSFlows {
  GatewayHosted = 'GatewayHosted',
  MethodUrl = 'MethodUrl',
  FormAction = 'FormAction',
  ACSURL = 'ACSURL',
}
