import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  OnInit,
  Output,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { DataOperations, FieldDefinition, MetaDataCollection, MetaDataType, Strings } from 'shared-code-lib';
import { Log } from '../../../blocks/core/log';
import {
  DataSourceCell,
  DataSourceRow,
  IDataSourceCell,
  IDataSourceRow,
  IDBColumn,
} from '../../../blocks/models/datasource';
import { ErrorsService } from '../../../blocks/services/errors.service';
import { HydraApiService } from '../../../blocks/services/hydra-api.service';
import { ApiResult, Control, IFolder } from '../../../blocks/services/models';
import { SharedDataService } from '../../../blocks/services/shared-data.service';
import { SpinnerStateService } from '../../../blocks/services/spinner-state.service';
import { UserStateService } from '../../../blocks/services/user-state.service';

@Component({
  selector: 'app-admin-datasource-row',
  templateUrl: './admin-datasource-row.component.html',
  styleUrls: ['./admin-datasource-row.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class AdminDataSourceRowComponent implements OnInit, AfterViewInit {
  @ViewChild('columnsList') columnsList: ElementRef;
  columns: IDBColumn[];
  row: DataSourceRow;
  rowId: string;
  folderId: string;
  datasourceId: string;
  operation: DataOperations;

  @Output() onRowSaved = new EventEmitter<IDataSourceRow>();
  @Output() OnCancel = new EventEmitter();

  fields: FieldDefinition[];
  values: string[];

  saveButton: Control;
  cancelButton: Control;

  editMode: boolean;

  constructor(
    public sharedDataService: SharedDataService,
    private hydraApi: HydraApiService,
    private errorsService: ErrorsService,
    private spinner: SpinnerStateService,
    private userState: UserStateService
  ) {
    this.operation = this.sharedDataService.extraParameters.operation;
    this.rowId = this.sharedDataService.extraParameters.rowId;
    this.folderId = this.sharedDataService.folderId;
  }

  ngOnInit() {
    const folder = this.userState.findFolderById(this.folderId);
    if (folder) {
      this.datasourceId = folder.parentFolderId;
      this.row = new DataSourceRow({ id: '', datasourceId: this.datasourceId, cells: [] } as IDataSourceRow);
      this.prepareColumns(folder);
      this.createFields();

      if (this.operation == DataOperations.Modify) {
        this.spinner.show('Common.LoadingData');
        this.editMode = true;
        this.hydraApi.getDataSourceRow(this.rowId, this.rowLoadSucceeded, this.rowLoadFailed);
      }
    } else {
      this.errorsService.showError('admin-datasource.invalid-datasource', '');
    }
  }

  ngAfterViewInit() {
    this.setupMaxHeight();
  }

  prepareColumns = (folder: IFolder): void => {
    this.columns = [];
    folder.columns
      .filter((x) => x.itemProperty.indexOf('extendedDetails.metaData') != -1)
      .forEach((c) => {
        this.columns.push({
          id: c.id.replace('col_', ''),
          name: c.headerText,
        } as IDBColumn);
      });
  };

  setupMaxHeight = (): void => {
    this.columnsList.nativeElement.style.maxHeight = `${window.innerHeight - 250}px`;
  };

  rowLoadSucceeded = (row: DataSourceRow): void => {
    this.row = row;
    this.createFields();
    this.spinner.hide();
  };

  rowLoadFailed = (error: any): void => {
    Log.error('admin-datasource.load-failed', error);
    this.spinner.hide();
  };

  private createFields = () => {
    if (!this.columns || !this.row) return;
    this.fields = [];
    this.values = [];
    for (var i = 0; i < this.columns.length; i++) {
      this.fields.push(
        new FieldDefinition({
          type: MetaDataType.Text,
          label: this.columns[i].name,
          placeholder: this.columns[i].name,
          required: false,
        })
      );

      if (i < this.row.cells.length) {
        this.values.push(this.row.cells[i].value);
      } else {
        this.values.push('');
      }
    }
  };

  setRowValues = (): void => {
    for (var i = 0; i < this.columns.length; i++) {
      if (i < this.row.cells.length) {
        this.row.cells[i].value = this.values[i];
      } else {
        this.row.cells.push(
          new DataSourceCell({
            columnId: this.columns[i].id,
            value: this.values[i],
          } as IDataSourceCell)
        );
      }
    }
  };

  onValueChanged = (index: number, value: string): void => {
    this.values[index] = value;
  };

  canSave = () => {
    if (!this.fields || !this.row || !this.values) return false;

    for (var i = 0; i < this.values.length; i++) {
      if (Strings.notEmptyOrWhiteSpace(this.values[i])) return true;
    }

    return false;
  };

  save = () => {
    if (!this.canSave()) return;
    this.spinner.show('admin-datasource.saving-row');
    this.setRowValues();
    if (this.editMode) {
      this.hydraApi.updateDataSourceRow(this.row, this.onSaveSucceeded, this.onSaveFailed);
    } else {
      this.hydraApi.createDataSourceRow(this.row, this.onSaveSucceeded, this.onSaveFailed);
    }
  };

  onSaveSucceeded = (result: ApiResult): void => {
    this.spinner.hide();
    if (result.success) {
      if (this.onRowSaved) this.onRowSaved.emit(result.object);
      this.sharedDataService.actionHandler.invokeEx(
        this.sharedDataService.folderId,
        this.sharedDataService.action,
        [],
        new MetaDataCollection(),
        () => {}
      );
    } else {
      this.errorsService.showError('admin-datasource.save-failed', result.object);
      Log.error('admin-datasource.save-failed', result.object);
    }
  };

  onSaveFailed = (error: any): void => {
    this.spinner.hide();
    this.errorsService.showError('admin-datasource.save-failed', error);
    Log.error('admin-datasource.save-failed', error);
  };

  close = () => {
    this.OnCancel.emit();
  };
}
