import { Directive, AfterViewInit, ElementRef, Input, OnDestroy } from '@angular/core';

import { DelayService } from './../utils/delay.service';
import { Observable, Subscription } from 'rxjs';

@Directive({
  selector: '[appAutoFocusFirstInput]',
})
export class AutoFocusFirstInputDirective implements AfterViewInit, OnDestroy {
  @Input() focusDelay: number;
  @Input() triggerRefocus: Observable<void>;
  @Input() focusEnabled = true;
  private readonly minimumDelay = 500;
  private subscriptions = new Subscription();

  constructor(private elementRef: ElementRef, private delay: DelayService) {}

  ngAfterViewInit() {
    this.delay.execute(this.focusFirstInput, this.focusDelay ? this.focusDelay : this.minimumDelay);

    if (this.triggerRefocus) {
      let subscription = this.triggerRefocus.subscribe(() => {
        this.delay.execute(this.focusFirstInput, this.focusDelay ? this.focusDelay : this.minimumDelay);
      });

      this.subscriptions.add(subscription);
    }
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  focusFirstInput = () => {
    if (!this.focusEnabled) return;

    const firstInput: HTMLElement = this.elementRef.nativeElement.querySelector(
      'input.form-control,textarea.form-control'
    );
    const firstContenteditable: HTMLElement = this.elementRef.nativeElement.querySelector('[contenteditable]');

    if (firstInput && firstContenteditable) {
      const position = firstInput.compareDocumentPosition(firstContenteditable);
      if (position === Node.DOCUMENT_POSITION_PRECEDING) {
        this.placeCaretAtEnd(firstContenteditable);
      } else {
        firstInput.focus();
      }
    } else if (firstInput) {
      firstInput.focus();
    } else if (firstContenteditable) {
      this.placeCaretAtEnd(firstContenteditable);
    } else {
      console.warn('There are no child elements that can be focused');
    }
  };

  placeCaretAtEnd(el: any) {
    el.focus();
    if (typeof window.getSelection != 'undefined' && typeof document.createRange != 'undefined') {
      var range = document.createRange();
      range.selectNodeContents(el);
      range.collapse(false);
      var sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
    } else if (typeof (document.body as any).createTextRange != 'undefined') {
      var textRange = (document.body as any).createTextRange();
      textRange.moveToElementText(el);
      textRange.collapse(false);
      textRange.select();
    }
  }
}
