import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { MetaDataCollection } from '../../../../../../../Bamba.Shared';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-interfax-start-qa-regression-modal',
  templateUrl: './interfax-start-qa-regression-modal.component.html',
  styleUrls: ['./interfax-start-qa-regression-modal.component.scss'],
})
export class InterfaxStartQaRegressionModalComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  componentName: string = '';
  componentIds = [];
  errors = [];
  id = '';

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private ngxSmartModalService: NgxSmartModalService
  ) { }

  ngOnInit(): void {
    this.id = this.sharedDataService.extraParameters.id;
    this.componentName = this.sharedDataService.extraParameters.componentVersionName;
    this.componentIds = [this.id];

    this.createFields();
  }

  startQARegression = () => {
    this.errors = [];

    this.spinnerService.show(this.translateService.instant('start-qa-regression.starting'), this.getSpinnerElement());

    const args = new MetaDataCollection();

    args.set('start-date', '');
    args.set('estimated-completion-date', '');

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.componentIds,
      args,
      this.onSucceeded,
      this.onFailed
    );

    return false;
  };

  onSucceeded = (result): void => {
    this.spinnerService.hide();

    this.close();
  };

  onFailed = (errors: any[]): void => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  close = (): void => this.closeModal.emit();

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.start-qa-regression-modal .nsm-content') as HTMLElement;
  }

  createFields = () => { };
}
