import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';

import { HttpClient } from '@angular/common/http';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { AuthService } from 'shared-code-lib';
import { ItemActionHandler } from './../../blocks/core/itemActionHandler';
import { ApiService } from './../../blocks/services/api.service';
import { ErrorsService } from './../../blocks/services/errors.service';
import { SharedDataService } from './../../blocks/services/shared-data.service';
import { SpinnerStateService } from './../../blocks/services/spinner-state.service';
import { UserStateService } from './../../blocks/services/user-state.service';

import { ActionEvent } from '../core/actions';
import { PrintPdfFileService } from './print-pdf-file.service';
import { HydraApiEventService } from './hydra-api-event.service';
import { LoadAppStateService } from './load-app-state.service';

@Injectable({
  providedIn: 'root',
})
export class ActionService {
  private _activateActionSubject = new Subject<ActionEvent>();
  onActivateAction = this._activateActionSubject.asObservable();

  private _openContextMenuSubject = new Subject<void>();
  onOpenContextMenu = this._openContextMenuSubject.asObservable();

  constructor(
    private ngxSmartModalService: NgxSmartModalService,
    private translateService: TranslateService,
    private apiService: ApiService,
    private errorsService: ErrorsService,
    private sharedDataService: SharedDataService,
    private toastrService: ToastrService,
    private http: HttpClient,
    private router: Router,
    private authService: AuthService,
    private spinnerService: SpinnerStateService,
    private userStateService: UserStateService,
    private printPdfFileService: PrintPdfFileService,
    private hydraApiEventService: HydraApiEventService,
    private appState: LoadAppStateService
  ) {}

  createItemActionHandler = () => {
    return new ItemActionHandler(
      this.ngxSmartModalService,
      this.translateService,
      this.apiService,
      this.errorsService,
      this.sharedDataService,
      this.toastrService,
      this.http,
      this.router,
      this.authService,
      this.printPdfFileService,
      this.appState,
      this.spinnerService,
      this.userStateService,
      this.hydraApiEventService
    );
  };

  activateAction(event: ActionEvent) {
    this._activateActionSubject.next(event);
  }

  openContextMenu() {
    this._openContextMenuSubject.next();
  }
}
