import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { TranslateService } from '@ngx-translate/core';
import { Log } from '../../core/log';
import { Router } from '@angular/router';
import { HydraApiService } from '../../services/hydra-api.service';
import { UserStateService } from '../../services/user-state.service';
import { ToastrService } from 'ngx-toastr';
import { SessionStorageService } from 'shared-code-lib';

@Component({
  selector: 'app-oauth-capture-code',
  templateUrl: './oauth-capture-code.component.html',
  styleUrls: ['./oauth-capture-code.component.scss'],
})
export class OauthCaptureCodeComponent implements OnInit {
  @ViewChild('spinnerWrapper', { static: true })
  spinnerWrapper: ElementRef;

  constructor(
    private spinnerService: SpinnerStateService,
    private translateService: TranslateService,
    private hydraApi: HydraApiService,
    private userStateService: UserStateService,
    private sessionStorageService: SessionStorageService,
    private router: Router,
    private toastrService: ToastrService
  ) {}

  ngOnInit(): void {
    this.spinnerService.show(
      this.translateService.instant('step-delivery-to-netdocs.exchanging-code'),
      this.spinnerWrapper.nativeElement
    );

    const oauthState = this.sessionStorageService.getOAuthState();

    const stateObj = JSON.parse(atob(oauthState.state));

    const app = stateObj.a;

    const ias = this.userStateService.getIntegratedApplicationSettingsFor(app);
    ias.secret = oauthState.code;

    this.hydraApi.updateIntegratedApplicationSettings(ias, this.exchangeSucceeded, this.exchangeFailed);
  }

  exchangeSucceeded = (): void => {
    this.spinnerService.hide();

    this.toastrService.success(this.translateService.instant('MainHeader.saved-integrated-app-settings'));

    this.gotoHome();
  };

  exchangeFailed = (e): void => {
    Log.error('exchangeFailed', e);

    //todo: REPORT ERROR - toast?

    this.spinnerService.hide();

    this.gotoHome();
  };

  gotoHome = (): void => {
    this.router.navigateByUrl(this.userStateService.getUserHomePage());
  };
}
