import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class FilterByCheckBox extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByCheckBox';
  }
}

class FilterByHistoryUser extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByHistoryUser';
  }
}

class FilterByOptions extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOptionsComponent';
  }
}

class FilterByComponent extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByDwfHistoryComponents';
  }
}

class FilterByGrouping extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByGrouping';
  }
}

class FilterByEnvironment extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByEnvironment';
  }
}

export class DWFToolsItemsFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('WorkItemFilters.Create', filter);

    if (
      filter.id ==
        'BambaDWFToolsApplication-Upland.Bamba.DWFTools.IFXReleaseManager.History.Filtering.FilterByEntryType' ||
      filter.id ==
        'BambaDWFToolsApplication-Upland.Bamba.DWFTools.IFXReleaseManager.ReleasedToSm.Filtering.FilterByInstalledStatus' ||
      filter.id == 'BambaDWFToolsApplication-Upland.Bamba.DWFTools.UIC.Widgets.FilterByBrand'
    )
      return new FilterByOptions(filter);
    else if (
      filter.id == 'BambaDWFToolsApplication-Upland.Bamba.DWFTools.IFXReleaseManager.History.Filtering.FilterByUser'
    )
      return new FilterByHistoryUser(filter);
    else if (
      filter.id ==
      'BambaDWFToolsApplication-Upland.Bamba.DWFTools.IFXReleaseManager.History.Filtering.FilterByComponent'
    )
      return new FilterByComponent(filter);
    else if (
      filter.id ==
      'BambaDWFToolsApplication-Upland.Bamba.DWFTools.IFXReleaseManager.Machines.Filtering.FilterByGrouping'
    ) {
      return new FilterByGrouping(filter);
    } else if (
      filter.id ==
        'BambaDWFToolsApplication-Upland.Bamba.DWFTools.IFXReleaseManager.Machines.Filtering.FilterByEnvironment' ||
      filter.id ==
        'BambaDWFToolsApplication-Upland.Bamba.DWFTools.IFXReleaseManager.Groupings.Filtering.FilterByEnvironment'
    ) {
      return new FilterByEnvironment(filter);
    } else if (filter.id == 'BambaDWFToolsApplication-Upland.Bamba.DWFTools.UIC.Widgets.FilterByUniqueLogins') {
      return new FilterByOptions(filter);
    }

    return null;
  };
}
