import { Component, Input, OnInit, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { saveAs } from 'file-saver/FileSaver';
import { ToastrService } from 'ngx-toastr';
import { HydraApiService } from '../../../../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';
import { InProgressService } from '../../../../../../../Bamba.Web/ClientApp/src/app/blocks/services/in-progress.service';

@Component({
  selector: 'app-workitem-properties-general',
  templateUrl: './workitem-properties-general.component.html',
  styleUrls: ['./workitem-properties-general.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class WorkitemPropertiesGeneralComponent implements OnInit {
  @Input() details: any;

  constructor(
    private translate: TranslateService,
    private hydraApi: HydraApiService,
    private toastr: ToastrService,
    private inProgress: InProgressService
  ) {}

  ngOnInit() {}

  getPageCountText = (pageCount: number): string => {
    if (pageCount == 1) return this.translate.instant('workitem-properties.page-count-one');

    return this.translate.instant('workitem-properties.page-count-notone');
  };

  getFileSizeText = (bytes: number): string => {
    var thresh = 1024;

    if (Math.abs(bytes) < thresh) {
      return bytes + ' B';
    }
    var units = ['KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];

    var u = -1;
    do {
      bytes /= thresh;
      ++u;
    } while (Math.abs(bytes) >= thresh && u < units.length - 1);

    return bytes.toFixed(2) + ' ' + units[u];
  };

  downloadFile(file: any) {
    this.inProgress.open(this.translate.instant('workitem-properties.downloading-file'));

    this.hydraApi.getWorkItemDocumentStream(
      this.details.id,
      file.id,
      (blob) => {
        this.inProgress.close();
        saveAs(blob, `${file.pathname}.${file.fileType}`);
      },
      (err) => {
        this.inProgress.close();
        this.toastr.error(this.translate.instant('workitem-properties.download-file-error'));
      }
    );
  }
}
