export interface IMoveDocuments {
  sourceWorkitemIds: string[];
  sourceDocumentIds: string[];
}

export class MoveDocuments {
  constructor(public sourceWorkitemIds: string[], public sourceDocumentIds: string[]) {}

  serializable = (): IMoveDocuments => {
    return {
      sourceWorkitemIds: this.sourceWorkitemIds,
      sourceDocumentIds: this.sourceDocumentIds,
    };
  };
}
