import { Directive, ElementRef, EventEmitter, HostListener, Input, OnDestroy, OnInit, Output } from '@angular/core';
import { of, Subject, timer, Subscription } from 'rxjs';
import { throttleTime, takeUntil, tap, map, switchMap } from 'rxjs/operators';

@Directive({
  selector: '[appClickOnce]',
})
export class ClickOnceDirective implements OnInit, OnDestroy {
  @Input() clickLockTime = 700; // ms
  @Output() appClickOnce = new EventEmitter<MouseEvent>();

  private clicks$ = new Subject<MouseEvent>();
  private destroyed$ = new Subject<void>();

  subscriptions = new Subscription();

  constructor(private elementRef: ElementRef) {}

  ngOnInit() {
    this.subscriptions.add(
      this.clicks$
        .pipe(
          throttleTime(this.clickLockTime),
          tap((event: MouseEvent) => this.appClickOnce.emit(event)),
          map(() => {
            if ((this.elementRef?.nativeElement as HTMLElement)?.tagName === 'BUTTON') {
              const button = this.elementRef?.nativeElement as HTMLButtonElement;
              if (button.disabled) {
                return false;
              }
              button.disabled = true;
              return true;
            } else {
              return false;
            }
          }),
          switchMap((needToEnableButton: boolean) =>
            !needToEnableButton
              ? of()
              : timer(0).pipe(
                  tap(() => {
                    if (needToEnableButton && (this.elementRef?.nativeElement as HTMLElement)?.tagName === 'BUTTON') {
                      if (this.elementRef) (this.elementRef.nativeElement as HTMLButtonElement).disabled = false;
                    }
                  })
                )
          ),
          takeUntil(this.destroyed$)
        )
        .subscribe()
    );
  }

  ngOnDestroy() {
    this.destroyed$.next();
    this.destroyed$.complete();

    this.subscriptions.unsubscribe();
  }

  @HostListener('click', ['$event'])
  clickEvent(event: MouseEvent) {
    this.clicks$.next(event);
  }
}
