export class DateTime {
  public static NormalizedDateFormat = 'YYYY-MM-DD';

  public static daysBetween = (firstDate: Date, secondDate: Date): number => {
    const date1 = new Date(firstDate);
    const date2 = new Date(secondDate);
    date1.setHours(0, 0, 0, 0);
    date2.setHours(0, 0, 0, 0);

    return (date1.getTime() - date2.getTime()) / 1000 / 3600 / 24;
  };

  public static isMinimumDateValue(value: string): boolean {
    return new Date(value).getUTCFullYear() <= 1;
  }

  public static isToday(date: Date): boolean {
    const currentDate = new Date();

    if (date.getDate() != currentDate.getDate()) return false;
    if (date.getMonth() != currentDate.getMonth()) return false;
    if (date.getFullYear() != currentDate.getFullYear()) return false;

    return true;
  }

  public static toUTCDateString(date: Date): string {
    const year = date.getUTCFullYear();
    const month = date.getUTCMonth() + 1;
    const day = date.getUTCDate();

    return `${year}-${month > 9 ? month : '0' + month}-${day > 9 ? day : '0' + day}`;
  }
}
