import { Component, OnInit, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastrService } from 'ngx-toastr';
import { TranslateService } from '@ngx-translate/core';
import { BambaDetailsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/bamba-details.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { AuthService } from '../../services/auth/auth.service';
import { BrandingService } from '../../services/branding.service';
import { SessionStorageService } from '../../services/session-storage.service';
import { LoginBaseComponent } from '../login-base/login-base.component';
import { HydraApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';
import { PaymentMethodConfigurations } from '../../../../Bamba.Web/ClientApp/src/app/blocks/InterFAX/Models/payment-methods';
import { InterFAXService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/interfax.service';
import { ErrorsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/errors.service';

@Component({
  selector: 'app-payment-method-callback',
  templateUrl: './payment-method-callback.component.html',
  styleUrls: ['./payment-method-callback.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class PaymentMethodCallbackComponent extends LoginBaseComponent implements OnInit {
  loginErrorText: string;
  paymentMethod: string;

  constructor(
    hydraApi: HydraApiService,
    sessionStorageService: SessionStorageService,
    authService: AuthService,
    userStateService: UserStateService,
    spinnerStateService: SpinnerStateService,
    translateService: TranslateService,
    bds: BambaDetailsService,
    bs: BrandingService,
    router: Router,
    private route: ActivatedRoute,
    private toastr: ToastrService,
    private interFAXService: InterFAXService,
    private errorService: ErrorsService
  ) {
    super(
      hydraApi,
      spinnerStateService,
      translateService,
      authService,
      bds,
      userStateService,
      sessionStorageService,
      bs,
      router
    );
  }

  ngOnInit(): void {
    this.authService.removeSessionForTabs();

    this.paymentMethod = this.route.snapshot.queryParamMap.get('payment-method');
    const config: PaymentMethodConfigurations = new PaymentMethodConfigurations(this.paymentMethod);

    this.route.snapshot.queryParamMap.keys.forEach((x) => {
      config.configurations.push({ key: x, value: this.route.snapshot.queryParamMap.get(x) });
    });

    this.completeSetup(config);
  }

  completeSetup = (config: PaymentMethodConfigurations): void => {
    this.spinnerStateService.show(
      this.translateService.instant('payment-method.completing-setup'),
      document.documentElement
    );

    this.interFAXService.completePaymentMethodSetup(
      config,
      this.paymentMethodSetupCompleted,
      this.paymentMethodSetupFailed
    );
  };

  paymentMethodSetupCompleted = (): void => {
    this.spinnerStateService.hide();
    this.toastr.success(this.translateService.instant('payment-method.setup-completed'));

    if (this.route.snapshot.queryParamMap.get('complete-registration') === 'true') {
      this.spinnerStateService.show(
        this.translateService.instant('account-register.complete-account-registration'),
        document.documentElement
      );

      this.interFAXService.completeRegistrationPayment(
        this.onRegistrationPaymentSucceeded,
        this.onRegistrationPaymentFailed
      );

      return;
    }

    this.router.navigate(['/fax-account-payment-method']);
  };

  paymentMethodSetupFailed = (): void => {
    this.spinnerStateService.hide();
    this.toastr.error(this.translateService.instant('payment-method.complete-setup-failed'));
    this.router.navigate(['/fax-account-payment-method'], { queryParams: { 'payment-method': this.paymentMethod } });
  };

  onRegistrationPaymentSucceeded = (): void => {
    this.spinnerStateService.hide();
    this.router.navigate(['/account-register'], { queryParams: { page: 'finish' } });
  };

  onRegistrationPaymentFailed = (err: any): void => {
    this.spinnerStateService.hide();
    this.errorService.showErrorsModal(err, this.translateService.instant('account-register.registration-failed'));
    this.router.navigate(['/fax-account-payment-method'], { queryParams: { 'payment-method': this.paymentMethod } });
  };
}
