import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { FixedDataSource, IFieldOptions } from 'shared-code-lib';
import { FaxUserStatus, IFaxUserSelect } from '../../InterFAX/Models/admin';
import { Filter } from '../../models/filter';
import { InterFAXService } from '../../services/interfax.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-filter-by-interfax-username',
  templateUrl: './filter-by-interfax-username.component.html',
  styleUrls: ['./filter-by-interfax-username.component.scss'],
})
export class FilterByInterfaxUsernameComponent implements OnInit {
  @Input() filter: Filter;
  @Input() layoutVertically: boolean;
  @Output() selected = new EventEmitter<string>();

  dataSource: FixedDataSource;

  constructor(
    private interfaxService: InterFAXService,
    private translateService: TranslateService,
    private userStateService: UserStateService
  ) {}

  ngOnInit(): void {
    this.dataSource = new InterFAXUsernameDataSource(
      this.interfaxService,
      this.translateService,
      this.userStateService
    );
  }

  onFilterSelected = (value: string) => this.selected.emit(value);
}

export class InterFAXUsernameDataSource extends FixedDataSource {
  addAllUsers: boolean;
  userStatus: FaxUserStatus;

  constructor(
    private interfaxService: InterFAXService,
    private translateService: TranslateService,
    private userStateService: UserStateService,
    userStatus: FaxUserStatus = FaxUserStatus.All,
    addAllUsers: boolean = true
  ) {
    super();
    this.addAllUsers = addAllUsers;
    this.userStatus = userStatus;
  }

  successCallBack: (items: IFieldOptions[]) => void;
  failureCallBack: (err: any) => void;

  getItems(
    startsWith: string,
    currentValue: string,
    successCallBack: (items: IFieldOptions[]) => void,
    failureCallBack: (err: any) => void
  ): void {
    this.successCallBack = successCallBack;
    this.failureCallBack = failureCallBack;

    this.interfaxService.getUsersSelect(this.usersLoaded, this.failed, startsWith, this.userStatus, currentValue);
  }

  usersLoaded = (users: Array<IFaxUserSelect>): void => {
    const options = new Array<IFieldOptions>();

    users.forEach((u: IFaxUserSelect) => {
      const option = { name: u.userId, value: u.userId.toLocaleLowerCase(), style: '', isInputStyled: false };

      if (u.closed) {
        option.isInputStyled = true;
        option.style = 'color: #acb0b3';
      }

      options.push(option);
    });

    if (this.addAllUsers) {
      options.push({ name: this.translateService.instant('interfax-queue.all-users'), value: '*' });
      options.push({
        name: this.translateService.instant('interfax-queue.loggedin-user'),
        value: this.userStateService.interFAXUsername,
      });
    }

    options.sort((x, y) => x.name.localeCompare(y.name));

    this.successCallBack(options);
  };

  failed = (err: any): void => {
    this.failureCallBack(err);
  };
}
