import { Component, EventEmitter, Input, OnChanges, Output, SimpleChanges } from '@angular/core';
import { ActionTypes, IAction, IFolder } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/models';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { TableItem } from '../../models/table';
import { selectionTypes } from '../../utils/enums';
import { ContextMenuComponent } from '../context-menu/context-menu.component';

export type ToolbarActionsWidth = number | 'max';

@Component({
  selector: 'app-toolbar-actions',
  templateUrl: './toolbar-actions.component.html',
  styleUrls: ['./toolbar-actions.component.scss'],
})
export class ToolbarActionsComponent implements OnChanges {
  @Input() folder: IFolder;
  @Input() selectedItems: TableItem[] = [];
  @Input() forceSingleRow = false;
  @Input() maxWidth: ToolbarActionsWidth = 'max';
  @Output() onActionClick = new EventEmitter<IAction>();

  contextMenu: ContextMenuComponent;

  toolbarActions: IAction[] = [];
  hiddenActions: IAction[] = [];

  constructor(private userStateService: UserStateService) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.selectedItems) {
      this.onSelectionChanged();
    }

    if (changes.maxWidth) {
      this.setActionSplit();
    }
  }

  setActionSplit = () => {
    this.toolbarActions = [...this.toolbarActions, ...this.hiddenActions];
    this.hiddenActions = [];

    if (this.toolbarActions.length <= 1) return;
    if (this.maxWidth === 'max') return;
    if (this.maxWidth < 0) this.maxWidth = 0;

    const actionWidth = 25 + 6 + 6; // (padding l & r = 6px, action size = 25px)
    const actionsWidth = actionWidth * this.toolbarActions.length + (this.forceSingleRow ? 16 : 0);

    if (actionsWidth <= this.maxWidth) return;

    let maxDisplayItems = Math.floor(this.maxWidth / actionWidth) - 1;
    if (maxDisplayItems === this.toolbarActions.length - 1) maxDisplayItems = this.toolbarActions.length;
    maxDisplayItems = maxDisplayItems < 0 ? 0 : maxDisplayItems;

    this.hiddenActions = this.toolbarActions.splice(maxDisplayItems);
  };

  onClick = (action: IAction) => {
    this.onActionClick.emit(action);
  };

  onContextMenuClick = (e: Event) => {
    if (!this.contextMenu) return;

    this.contextMenu.open(
      e,
      null,
      null,
      this.hiddenActions.map((a) => ({
        name: a.name,
        action: () => this.onClick(a),
        disabled: false,
      }))
    );
  };

  onSelectionChanged = () => {
    this.toolbarActions = [];
    this.hiddenActions = [];
    this.populateToolbarActionsForSelection();

    this.setActionSplit();
  };

  populateToolbarActionsForSelection = (): void => {
    if (!this.folder) return;

    this.folder.product.actions.forEach(this.addActionIfApplicable);
    this.folder.actions.filter((a) => a.selectionType === selectionTypes.None).forEach(this.addActionIfApplicable);
    this.folder.actions.forEach(this.addActionIfApplicable);
    this.userStateService.user.products.forEach((p) =>
      p.actions.filter((a) => a.selectionType !== selectionTypes.None).forEach(this.addActionIfApplicable)
    );

    if (this.toolbarActions.some((a) => a.order != 0)) {
      this.toolbarActions.sort(this.sortAction);
    }
  };

  addActionIfApplicable = (action: IAction) => {
    if (this.toolbarActions.find((a) => a.id === action.id)) return;
    if (!this.isToolbarAction(action)) return;

    if (action.selectionType === selectionTypes.One && this.selectedItems.length !== 1) return;
    if (action.selectionType === selectionTypes.OneOrMore && this.selectedItems.length < 1) return;

    if (!this.isActionAllowed(action)) return;

    this.toolbarActions.push(action);
  };

  isToolbarAction = (a: IAction): boolean => (a.type & ActionTypes.Toolbar) != 0;
  isActionAllowed = (a: IAction): boolean =>
    this.selectedItems.every((i) => (i.data.allowedActions as IAction[]).find((itemAction) => itemAction.id === a.id));

  sortAction = (x: IAction, y: IAction): number =>
    x.order == y.order ? x.name.localeCompare(y.name) : x.order - y.order;

  onRenderContextMenu = (menu: ContextMenuComponent) => (this.contextMenu = menu);
}
