import { ImageItem, TextItem } from './ted-state';

export enum ShapeType {
  Text = 'texts',
  Image = 'images',
}

export enum JsTreeNodeType {
  Root = 'root',
  Text = 'text',
  Image = 'image',
  Page = 'page',
  Section = 'section',
  SectionOpened = 'section-open',
}

export enum ShapeDimension {
  Left = 0,
  Top = 1,
  Width = 2,
  Height = 3,
}

export class ShapeInitializer {
  id: string;
  title: string;
  x: number;
  y: number;
  w: number;
  h: number;
  rotate: number;
  page: number;
  section: number;
  class: string;
  type: ShapeType;
  texts: TextItem[];
  images: ImageItem[];
}
export class Shape {
  id: string;
  title: string;
  x: number;
  y: number;
  w: number;
  h: number;
  rotate: number;
  page: number;
  section: number;
  class: string;
  type: ShapeType;
  texts: TextItem[];
  images: ImageItem[];
  fillStyle = '';
  strokeStyle = '';

  constructor(initializer: ShapeInitializer) {
    this.id = initializer.id;
    this.title = initializer.title;
    this.x = initializer.x || 0;
    this.y = initializer.y || 0;
    this.w = initializer.w || 10;
    this.h = initializer.h || 10;
    this.rotate = initializer.rotate || 0;
    this.page = initializer.page || 0;
    this.section = initializer.section || 0;
    this.class = initializer.class || '';
    this.type = initializer.type;
    this.texts = initializer.texts || [];
    this.images = initializer.images || [];
  }
}
