import { Input, Component, OnInit, Output, EventEmitter } from '@angular/core';
import { Address, AddressValidationResult } from '../../InterFAX/Models/admin';

@Component({
  selector: 'app-interfax-address-validation',
  templateUrl: './interfax-address-validation.component.html',
  styleUrls: ['./interfax-address-validation.component.scss'],
})
export class InterfaxAddressValidationComponent implements OnInit {
  @Input() addressValidationResults: AddressValidationResult;
  @Input() billingAddress: Address;
  @Input() shippingAddress: Address;
  @Output() accept = new EventEmitter<void>();
  @Output() reject = new EventEmitter<void>();

  constructor() {}

  ngOnInit(): void {}

  rejectAddressValidationResults = (): void => {
    this.reject.next();
  };

  acceptAddressValidationResults = (): void => {
    this.accept.next();
  };
}
