import { DataState } from 'shared-code-lib';

export interface IDataSource {
  id: string;
  tenantId: string;
  name: string;
  columns: IDBColumn[];
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
}

export interface IDBColumn {
  id: string;
  name: string;
  type: number;
  state: DataState;
}

export interface IDataSourceCell {
  id: string;
  columnId: string;
  value: string;
}

export interface IDataSourceRow {
  id: string;
  datasourceId: string;
  cells: IDataSourceCell[];
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
}

export class DataSource implements IDataSource {
  public id: string;
  public tenantId: string;
  public name: string;
  public columns: IDBColumn[];
  public dateCreatedUTC: Date;
  public dateModifiedUTC: Date;

  constructor(initializer: IDataSource) {
    this.id = initializer.id;
    this.tenantId = initializer.tenantId;
    this.name = initializer.name;
    this.columns = initializer.columns;
    this.dateCreatedUTC = initializer.dateCreatedUTC;
    this.dateModifiedUTC = initializer.dateModifiedUTC;
  }

  serializable = (): IDataSource => {
    return {
      id: this.id,
      tenantId: this.tenantId,
      name: this.name,
      columns: this.columns,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
    };
  };
}

export class DataSourceCell implements IDataSourceCell {
  public id: string;
  public columnId: string;
  public value: string;

  constructor(initializer: IDataSourceCell) {
    this.id = initializer.id;
    this.columnId = initializer.columnId;
    this.value = initializer.value;
  }

  serializable = (): IDataSourceCell => {
    return {
      id: this.id,
      columnId: this.columnId,
      value: this.value,
    };
  };
}

export class DBColumn implements IDBColumn {
  public id: string;
  public name: string;
  public type: number;
  public state: DataState;

  constructor(initializer: IDBColumn) {
    this.id = initializer.id;
    this.name = initializer.name;
    this.type = initializer.type;
  }

  serializable = (): IDBColumn => {
    return {
      id: this.id,
      name: this.name,
      type: this.type,
      state: this.state,
    };
  };
}

export class DataSourceRow implements IDataSourceRow {
  public id: string;
  public datasourceId: string;
  public cells: IDataSourceCell[];
  public dateCreatedUTC: Date;
  public dateModifiedUTC: Date;

  constructor(initializer: IDataSourceRow) {
    this.id = initializer.id;
    this.datasourceId = initializer.datasourceId;
    this.cells = initializer.cells;
    this.dateCreatedUTC = initializer.dateCreatedUTC;
    this.dateModifiedUTC = initializer.dateModifiedUTC;
  }

  serializable = (): IDataSourceRow => {
    return {
      id: this.id,
      datasourceId: this.datasourceId,
      cells: this.cells,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
    };
  };
}

export interface ICSVColumnMapping {
  dataSourceColumnId: string;
  cSVColumnIndex: number;
}

export interface IImportCSVData {
  content: string;
  firstRowIsColumnHeaders: boolean;
  replaceExistingRows: boolean;
  columnsMapping: Array<ICSVColumnMapping>;
}

export class CSVColumnMapping implements ICSVColumnMapping {
  public dataSourceColumnId: string;
  public cSVColumnIndex: number;

  constructor(initializer: ICSVColumnMapping) {
    this.dataSourceColumnId = initializer.dataSourceColumnId;
    this.cSVColumnIndex = initializer.cSVColumnIndex;
  }

  serializable = (): ICSVColumnMapping => {
    return {
      dataSourceColumnId: this.dataSourceColumnId,
      cSVColumnIndex: this.cSVColumnIndex,
    };
  };
}

export class ImportCSVData implements IImportCSVData {
  public content: string;
  public firstRowIsColumnHeaders: boolean;
  public replaceExistingRows: boolean;
  public columnsMapping: Array<ICSVColumnMapping>;

  constructor(initializer: IImportCSVData) {
    this.content = initializer.content;
    this.firstRowIsColumnHeaders = initializer.firstRowIsColumnHeaders;
    this.replaceExistingRows = initializer.replaceExistingRows;
    this.columnsMapping = initializer.columnsMapping;
  }

  serializable = (): IImportCSVData => {
    return {
      content: this.content,
      firstRowIsColumnHeaders: this.firstRowIsColumnHeaders,
      replaceExistingRows: this.replaceExistingRows,
      columnsMapping: this.columnsMapping,
    };
  };
}
