import {
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import moment from 'moment';

import { Subject, Subscription } from 'rxjs';
import { delay, distinctUntilChanged } from 'rxjs/operators';
import { DateTime } from '../../utils/date-time.service';
import { Languages } from '../../utils/languages';
import { Log } from './../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { FieldDefinition } from './../../models/field-definition';
import { MetaDataValidity } from './../../models/metadata';
import { DelayService } from './../../utils/delay.service';
import { Key } from './../../utils/key-enum';

declare var Pikaday;

//
// BEWARE
//
// This code is trying to keep the Date in a "normalized" format (YYYY-MM-DD) treating it as timezone *agnostic*
// it has to fight pikaday and javascript because they both feel strongly that dates should be UTC or Local
//
// The goal being to store the exact date specified by the user without adjusting for TimeZone in any manner
//
// Besure you know what you are doing before changing anything - it ripples.
//
// TESTING
//   User can select a date from the calendar
//   User can type in a date (full or partial, in locale specific format or YYYY-MM-DD)
//   User can PnC/RubberBand a date (full or partial, in locale specific format or YYYY-MM-DD)
//
// VERIFY
//    That we always use the actual date specified and not some timezone skewed version,
//    Test in multiple Client TimeZones to be sure, positive & negative offsets
//
//   Invalid dates are replaced with EMPTY string
//

@Component({
  selector: 'app-date',
  templateUrl: './date.component.html',
  styleUrls: ['./date.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class DateComponent implements OnInit, OnChanges, OnDestroy {
  @ViewChild('dateTextField', { static: true })
  dateTextField: ElementRef;
  @ViewChild('calendarButton')
  calendarButton: ElementRef;

  pikaday: any;

  dateTextValue = '';

  isCurrentField: boolean;
  metaDataValidity = MetaDataValidity;

  @Input() fieldId: string = '';

  @Input() field: FieldDefinition;
  _value = '';
  @Input() set value(value: string) {
    if (this._value == value) {
      this.originalValue = this._value;
      return;
    }

    this._value = value;
    if (this.minValue && moment(this._value) < moment(this.minValue)) {
      this._value = this.minValue;
      this.fireBlur();
      return;
    }

    if (this.maxValue && moment(this._value) > moment(this.maxValue)) {
      this._value = this.maxValue;
      this.fireBlur();
      return;
    }

    if (this.originalValue == this._value) return;
    this.originalValue = this._value;

    this.syncToValue();
  }

  get value() {
    return this._value;
  }

  @Input() disabled: boolean;
  @Input() validity: number;

  @Input() minValue: string;
  @Input() maxValue: string;

  @Input() fieldTabIndex = 0;

  @Input()
  set focused(isFocused: boolean) {
    if (isFocused) {
      this.dateTextField?.nativeElement?.focus();
      this.isCurrentField = true;
    } else if (!isFocused) {
      this.dateTextField?.nativeElement?.blur();
      this.isCurrentField = false;
    }
  }

  @Input()
  set setValue(value: string) {
    Log.enter('DateComponent.setValue', value);

    if (!value) return;

    this._value = value;

    this.syncToValue();
  }

  @Output() fieldFocus = new EventEmitter();
  @Output() fieldBlur = new EventEmitter<string>();
  valueChange = new Subject<string>();

  valueChangeObservable = this.valueChange.asObservable();

  @Output() fieldOnTab = new EventEmitter<string>();
  @Output() fieldOnShiftTab = new EventEmitter<string>();

  subscriptions = new Subscription();

  format: string;
  private originalValue: string = '';

  scrollParent: HTMLElement;

  constructor(private delayService: DelayService, private languages: Languages) {}

  ngOnInit(): void {
    this.format = this.field.dateFieldExpectedFormat;

    this.subscriptions.add(
      this.valueChangeObservable.pipe(delay(10), distinctUntilChanged()).subscribe((value) => {
        this.fieldBlur.emit(value);
      })
    );
  }

  ngAfterViewInit() {
    this.initializePikaday();

    this.dateTextField.nativeElement.removeEventListener('focus', this.pikaday._onInputFocus);
    this.dateTextField.nativeElement.removeEventListener('click', this.pikaday._onInputClick);
  }

  /// https://stackoverflow.com/a/42543908
  private findScrollParent = (element, includeHidden = false): HTMLElement => {
    let style = getComputedStyle(element);
    let excludeStaticParent = style.position === 'absolute';
    let overflowRegex = includeHidden ? /(auto|scroll|hidden)/ : /(auto|scroll)/;

    if (style.position === 'fixed') return document.body;
    for (let parent = element; (parent = parent.parentElement); ) {
      style = getComputedStyle(parent);
      if (excludeStaticParent && style.position === 'static') {
        continue;
      }
      if (overflowRegex.test(style.overflow + style.overflowY + style.overflowX)) return parent;

      // compatibility for perfect scrollbar
      if (parent.classList.contains('ps')) return parent;
    }

    return document.body;
  };

  initializePikaday(): void {
    this.pikaday = new Pikaday({
      field: this.dateTextField.nativeElement,
      trigger: this.calendarButton.nativeElement,
      position: 'bottom right',
      blurFieldOnSelect: false,
      format: this.format,
      defaultDate: this.value,

      i18n: this.languages.getLocalizedDate(),

      toString: (date: Date, format: string): string => {
        Log.enter('DateComponent.initializePickaday.toString', date, format);

        return moment(date).format(format);
      },

      parse: (date: string, format: string): Date | string => {
        Log.enter('DateComponent.initializePickaday.parse', date, format);

        const dateValue = moment(date, format).toDate();
        if (moment(dateValue).isValid()) {
          return dateValue;
        } else {
          this.pikaday.setDate('');
          return '';
        }
      },
      onSelect: (date: Date): void => {
        Log.enter('DateComponent.initializePickaday.onSelect', date);

        this.onSelect(moment(date));
        this.pikaday.hide();
      },

      onOpen: () => {
        if ((event as any)?.target?.localName == 'input') this.pikaday.hide();

        this.scrollParent = this.findScrollParent(this.calendarButton.nativeElement);
        this.scrollParent?.addEventListener('scroll', this.onScrollParent, { once: true });

        const momentDate = this.convertValueToMoment(this.value);
        this.pikaday.gotoDate(this.value ? momentDate.toDate() : moment().toDate());
      },
    });

    this.setSelectedDate();
    this.setMinAndMaxValues();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.value !== undefined) this.setSelectedDate();
    if (changes.minValue !== undefined || changes.maxValue !== undefined) this.setMinAndMaxValues();
  }

  onScrollParent = () => this.pikaday?.hide();

  setSelectedDate() {
    const momentDate = this.convertValueToMoment(this.value);
    this.pikaday?.setDate(this.value ? momentDate.toDate() : '');
  }

  setMinAndMaxValues = (): void => {
    const momentMinValue = this.convertValueToMoment(this.minValue);
    const momentMaxValue = this.convertValueToMoment(this.maxValue);

    this.pikaday?.setMinDate(this.minValue ? momentMinValue.toDate() : '');
    this.pikaday?.setMaxDate(this.maxValue ? momentMaxValue.toDate() : '');
  };

  // check ds meets YYYY-MM-DD format
  isNormalizedDateString = (ds: string): boolean => {
    if (typeof ds !== 'string') return false;

    const parts = ds.split('-');
    if (parts.length != 3) return false;

    if (parts[0].length != 4) return false;
    if (parts[1].length != 2) return false;
    if (parts[2].length != 2) return false;

    if (!this.isDigits(parts[0])) return false;
    if (!this.isDigits(parts[1])) return false;
    if (!this.isDigits(parts[2])) return false;

    return true;
  };

  isDigits = (s: string): boolean => {
    return !isNaN(parseInt(s, 10));
  };

  syncToValue = () => {
    Log.enter('DateComponent.syncToValue', this._value, this.originalValue);

    if (!this._value) return;

    if (this.isNormalizedDateString(this._value)) {
      this.setIncomingDate(moment(this._value, DateTime.NormalizedDateFormat));
    } else {
      const normalizedDateValue = this._value.split('-').join('/').split('.').join('/').split(' ').join('');

      const date = moment(normalizedDateValue, this.field.dateFieldExpectedFormat);

      if (date.isValid()) {
        this.setIncomingDate(date);
      } else {
        Log.info(`Invalid Date: ${this._value}`);

        this._value = '';
        this.dateTextValue = '';
        this.fireBlur();
      }
    }

    this.originalValue = this._value;
  };

  private setIncomingDate = (date: moment.Moment) => {
    Log.enter('DateComponent.setIncomingDate', date);

    if (this.field) {
      this.format = this.field.dateFieldExpectedFormat;
      this.setDateValue(date);
    } else {
      this.delayService.execute(() => {
        this.setDateValue(date);
      }, 0);
    }
  };

  setDateValue(date: moment.Moment) {
    this.value = date.format(DateTime.NormalizedDateFormat);
    this.dateTextValue = date.format(this.format);
    this.fireBlur();

    this.pikaday?.setDate(date.toDate(), true);
  }

  onDateTextKeyDown = (e: any): void => {
    const dateTextReturnKeys = [8, 46, 13, 27, 109, 110, 111, 189, 190, 191]
      .concat(this.getRange(35, 40))
      .concat(this.getRange(48, 58))
      .concat(this.getRange(96, 106));

    if (dateTextReturnKeys.includes(e.keyCode) && e.shiftKey === false) {
      return;
    }

    if (e.key === Key.KeyA && e.ctrlKey === true) {
      return;
    }

    if (e.key === Key.Tab) {
      this.blurValueHandler();

      if (e.shiftKey) {
        this.fieldOnShiftTab.emit(this._value);
        return;
      }

      this.fieldOnTab.emit(this._value);
      return;
    }

    e.preventDefault();
  };

  private getRange(min: number, max: number) {
    const rangeArray: number[] = [];
    for (let i = min; i < max; i++) {
      rangeArray.push(i);
    }

    return rangeArray;
  }

  onDateTextFocus = (): void => {
    Log.enter('onDateTextFocus', this._value);

    this.fieldFocus.emit();
  };

  fireBlur = (): void => {
    Log.enter('DateComponent.fireBlur', this._value, this.originalValue, this.validity);

    if (this._value == 'Invalid date') this._value = '';

    if (this._value != this.originalValue || this.validity === MetaDataValidity.suspicious) {
      let date = '';

      if (this.isNormalizedDateString(this._value)) {
        date = moment(this._value, DateTime.NormalizedDateFormat).format(DateTime.NormalizedDateFormat);
      } else if (this._value == '') {
        date = '';
      } else {
        const normalizedDateValue = this._value.split('-').join('/').split('.').join('/').split(' ').join('');

        date = moment(normalizedDateValue, this.field.dateFieldExpectedFormat).format(DateTime.NormalizedDateFormat);
      }

      this.valueChange.next(date.substr(0, 10));
      Log.var(this._value);
    }

    this.originalValue = this._value;
  };

  onDateTextBlur = (): void => {
    Log.enter('DateComponent.onDateTextBlur', this._value, this.originalValue, this.dateTextValue);

    this.blurValueHandler();
  };

  private blurValueHandler() {
    const normalizedDate = moment(this.dateTextValue, this.format).format(DateTime.NormalizedDateFormat);
    if (normalizedDate == this._value) return;

    this._value = normalizedDate;
    this.fireBlur();
    this.pikaday?.hide();
  }

  onSelect(selectedDate: moment.Moment) {
    Log.enter('DateComponent.onSelect', selectedDate);

    if (!selectedDate) return;

    this.dateTextValue = selectedDate.format(this.format);
    this._value = selectedDate.format(DateTime.NormalizedDateFormat);
    this.fireBlur();
  }

  convertValueToMoment(value: string): moment.Moment {
    return moment(value, DateTime.NormalizedDateFormat);
  }

  ngOnDestroy() {
    this.pikaday?.hide();
    this.subscriptions.unsubscribe();
    this.scrollParent?.removeEventListener('scroll', this.onScrollParent);
  }
}
