  searchContactLists(
    searchQuery: string,
    searchType: ContactListSearchType,
    contactListId: ContactListIds | string,
    successCallback: (c: any) => void,
    failureCallBack: (err: any) => void
  ): Subscription {
    return this.http
      .get(`api/interfax/admin/searchcontactlists/${searchQuery}`, {
        params: {
          searchType,
          contactListId,
        },
      })
      .subscribe(
        (result: ApiResult) => {
          if (!result.success) {
            failureCallBack(result.errors);
            return;
          }
          successCallback((result.object as IContact[]).map((c) => new Contact(c)));
        },
        (err) => {
          failureCallBack(err);
        }
      );
  }

