import { CurrencyPipe } from '@angular/common';
import { DEFAULT_LOCALE } from './locales';

interface ICurrencyOptions {
  currencyDisplay?: string;
  digitsInfo?: string;
}

export function localizeNumberToCurrency(
  value: number,
  currencyCode: string,
  userLocale: string,
  options: ICurrencyOptions = null
): string {
  currencyCode = currencyCode.toUpperCase();
  let localizedPositiveValue = '';

  try {
    localizedPositiveValue = transform(value, currencyCode, userLocale, options);
  } catch (err) {
    localizedPositiveValue = transform(value, currencyCode, DEFAULT_LOCALE, options);
  }

  const roundedValue = +value.toFixed(currencyCode == 'JP' ? 0 : 2);
  return roundedValue >= 0 ? localizedPositiveValue : '(' + localizedPositiveValue + ')';
}

function transform(value: number, currencyCode: string, locale: string, options: ICurrencyOptions = null): string {
  return new CurrencyPipe(locale).transform(
    Math.abs(value),
    currencyCode,
    options?.currencyDisplay || 'symbol',
    options?.digitsInfo || (currencyCode == 'JP' ? '1.0-0' : '1.2-2'),
    locale
  );
}

export function getLocalizedCurrencyName(currencyCode: string, userLocale: string): string {
  const options = {
    style: 'currency',
    currency: currencyCode,
    currencyDisplay: 'name',
  };
  const parts = new Intl.NumberFormat(userLocale, options).formatToParts(0).map((p) => p.value);
  return parts?.length ? parts[parts.length - 1] : currencyCode;
}
