import { AfterViewInit, Component, EventEmitter, OnInit, Output, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { FieldDefinition } from '../../../../../../../Bamba.Shared/src/models/field-definition';
import { MetaDataCollection } from '../../../../../../../Bamba.Shared/src/models/metadata';
import { MetaDataType } from '../../../../../../../Bamba.Shared/src/models/metadata-definition';
import {
  IRadioButtonOption,
  RadioButtonsLayout,
} from '../../../../../../../Bamba.Shared/src/models/radio-buttons-group';
import { RolePermissions } from '../../../../../../../Bamba.Shared/src/models/role';
import { IResendFaxParameters } from '../../InterFAX/Models/outbound';
import { ProductItemRefreshService } from '../../services/product-item-refresh.service';
import { SharedDataService } from '../../services/shared-data.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-resend-fax-modal',
  templateUrl: './resend-fax-modal.component.html',
  styleUrls: ['./resend-fax-modal.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class ResendFaxModalComponent implements OnInit, AfterViewInit {
  @Output() closeModal = new EventEmitter();

  modalData: IResendFaxParameters;
  resendFaxModal: NgxSmartModalComponent;
  faxNumberField: FieldDefinition;
  faxNumber = '';
  changeFaxNumber = false;
  hideOriginalFax = false;
  sendErrorsOnly = false;
  showResendOptions = false;
  showChangeFaxNumberCheckbox = false;
  userHasDeleteFaxPermissions = false;

  sendFailedFaxesOptions: IRadioButtonOption<boolean>[] = [];
  horizontalRadioButtons = RadioButtonsLayout.Horizontal;

  get isBroadcast() {
    return this.modalData?.isBroadcast;
  }

  get shouldDisableResendButton() {
    return (
      ((!this.isBroadcast && !this.showChangeFaxNumberCheckbox) ||
        (this.showChangeFaxNumberCheckbox && this.changeFaxNumber)) &&
      !this.faxNumber
    );
  }

  constructor(
    private sharedDataService: SharedDataService,
    private ngxSmartModalService: NgxSmartModalService,
    private translateService: TranslateService,
    private toastr: ToastrService,
    private productItemRefreshService: ProductItemRefreshService,
    private userStateService: UserStateService
  ) {}

  ngOnInit() {
    this.modalData = this.sharedDataService.extraParameters;

    const totalFaxesCount = this.modalData?.selectedItems[0]?.totalFaxesCount;
    const failedFaxesCount = this.modalData?.selectedItems[0]?.failedFaxesCount;
    this.showResendOptions = failedFaxesCount > 0 && failedFaxesCount < totalFaxesCount;
    if (this.showResendOptions) this.sendErrorsOnly = true;

    this.faxNumber = this.getInitialFaxNumberValue();
    this.showChangeFaxNumberCheckbox = this.getInitialUniqueFaxNumbers().length > 1;
    this.userHasDeleteFaxPermissions = this.userStateService.hasRolePermission(
      RolePermissions.INTERFAX_PERMISSIONS_ALLOWDELETING
    );
    this.createFields();
  }

  ngAfterViewInit(): void {
    this.resendFaxModal = this.ngxSmartModalService.get('resendFaxModal');
  }

  createFields = () => {
    this.faxNumberField = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('resend-fax-modal.fax-number-label'),
      placeholder: this.translateService.instant('resend-fax-modal.fax-number-placeholder'),
      required: true,
    });

    this.sendFailedFaxesOptions = [
      {
        label: this.translateService.instant('resend-fax-modal.resend-all-label'),
        value: false,
      },
      { label: this.translateService.instant('resend-fax-modal.resend-failed-only-label'), value: true },
    ];
  };

  getInitialUniqueFaxNumbers = (): string[] => {
    return [...new Set(this.modalData?.selectedItems.map((item) => item?.faxNumber).filter((faxNumber) => faxNumber))];
  };

  getInitialFaxNumberValue = () => {
    const uniqueFaxNumbers = this.getInitialUniqueFaxNumbers();
    if (uniqueFaxNumbers.length !== 1) return '';
    return uniqueFaxNumbers[0];
  };

  updateFaxNumber = (faxNumber: string) => {
    this.faxNumber = faxNumber;
  };

  closeResendFaxModal = () => {
    this.closeModal.emit();
    this.resendFaxModal.close();
  };

  resendFax = () => {
    if (this.shouldDisableResendButton) return;

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.modalData?.selectedItems.map((item) => item.id) as any,
      this.getRequestArgs(),
      this.faxesSentSuccessfully,
      this.faxesSendingFailed
    );
  };

  faxesSentSuccessfully = () => {
    this.closeResendFaxModal();
    this.productItemRefreshService.onRefresh.next();
    this.toastr.success(this.translateService.instant('resend-fax-modal.faxes-resent-successfully'));
  };

  faxesSendingFailed = (err: any) => {
    this.closeResendFaxModal();
    this.productItemRefreshService.onRefresh.next();
    this.toastr.error(err);
  };

  getRequestArgs() {
    const args = new MetaDataCollection();
    args.set('hideOriginalFax', this.hideOriginalFax + '');
    args.set('sendErrorsOnly', this.sendErrorsOnly + '');
    if (this.modalData?.isBroadcast) return args;

    args.set('faxNumber', this.faxNumber);
    args.set('changeFaxNumber', this.changeFaxNumber + '');
    args.set('oldMultipleFaxNumbers', this.showChangeFaxNumberCheckbox + '');
    return args;
  }
}
