export class Files {
  static toBase64String = (file: File, trimPrefix = false) => {
    return new Promise<string>((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = (event) => {
        if (event.target.result instanceof ArrayBuffer) return;

        const base64 = trimPrefix ? event.target.result.split(',')[1] : event.target.result;

        resolve(base64);
      };

      reader.onerror = (err) => {
        reject(`error reading file, ${err}`);
      };

      reader.readAsDataURL(file);
    });
  };
}
