import {
  Component,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  Output,
  SimpleChanges,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import { SessionStorageService, Tab, TableItem } from 'shared-code-lib';
import { HydraApiService } from '../../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';
import { SystemMetaData } from '../../../../../Bamba.Web/ClientApp/src/app/blocks/core/systemMetaData';

@Component({
  selector: '[appProductDetail]',
  templateUrl: './product-detail.component.html',
  styleUrls: ['./product-detail.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class ProductDetailComponent implements OnChanges, OnDestroy {
  @Input() dataItem: TableItem;
  @Output() reload = new EventEmitter();

  displayVersions = false;

  data: any;

  details: any;
  loading = true;

  tabs = new Array<Tab>();

  isFaxMobile = false;
  private subscriptions = new Subscription();

  constructor(
    private hydraApi: HydraApiService,
    private toastr: ToastrService,
    private translateService: TranslateService,
    private sessionStorageService: SessionStorageService
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (!changes.dataItem || !changes.dataItem.currentValue) return;

    this.data = changes.dataItem.currentValue.data;
    this.displayVersions = this.data.versions && this.data.versions.length;
    this.isFaxMobile = this.sessionStorageService.getIsInterFaxMobile();
    this.subscriptions.add(
      this.sessionStorageService.onIsInterFaxMobileChanged.subscribe((x) => (this.isFaxMobile = x))
    );

    this.loadExtendedDetails();
    this.createTabs();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  createTabs = (): void => {
    this.tabs = [];

    if (this.data.extendedDetails?.type === 'BroadcastFaxDetails') return;

    if (this.isFaxMobile && this.data.extendedDetails?.type === 'ExtendedDetailsInterFAXInboundFax') {
      this.tabs.push(
        new Tab('ExtendedDetailsInterFAXInboundFax', this.translateService.instant('product-details.preview'))
      );

      if (!this.dataItem.detailsTab) this.dataItem.detailsTab = 'ExtendedDetailsInterFAXInboundFax';
    }

    if (this.data.extendedDetails?.type === 'OLCTemplateVersionDetails') {
      this.tabs.push(
        new Tab('OLCTemplateVersionDetails', this.translateService.instant('admin-olc-templates.version-details'))
      );
      if (!this.dataItem.detailsTab) this.dataItem.detailsTab = 'OLCTemplateVersionDetails';
    }

    if (this.displayVersions) {
      this.tabs.push(new Tab('versions', this.translateService.instant('product-details.versions')));
      if (!this.dataItem.detailsTab) this.dataItem.detailsTab = 'versions';
    }

    if (this.data.showDetailsTab) {
      this.tabs.push(new Tab('details', this.translateService.instant('product-details.details')));
      if (!this.dataItem.detailsTab) this.dataItem.detailsTab = 'details';
    }

    if (this.data.extendedDetails?.type === 'WorkItemExtendedDetails') {
      this.tabs.push(
        new Tab('dataFields', this.translateService.instant('product-details.data-fields')),
        new Tab('journal', this.translateService.instant('product-details.journal'))
      );

      this.addExtractedDataTab();
    }

    if (
      this.data.extendedDetails?.type === 'ExtendedDetailsInterFAXInboundFax' &&
      this.data.extendedDetails?.barcodes?.length
    ) {
      this.tabs.push(new Tab('barcodes', this.translateService.instant('product-details.barcodes.title')));
      if (!this.dataItem.detailsTab) this.dataItem.detailsTab = 'barcodes';
    }
  };

  loadExtendedDetails = (): void => {
    if (this.data === null || this.data === undefined) return;

    if (this.data.extendedDetails == null || this.data.extendedDetails.forceLoadExtendedDetails) {
      this.hydraApi.getItemDetails(this.data.id, this.detailsLoaded, this.detailsLoadFailed);
    } else {
      this.details = this.data && this.data.extendedDetails;
      this.loading = false;
    }
  };

  detailsLoaded = (result: any): void => {
    const permissions = this.data.extendedDetails?.permissions;
    this.details = this.data.extendedDetails = result.extendedDetails;
    if (this.details) this.details.permissions = permissions;

    this.addExtractedDataTab();
    this.loading = false;
  };

  detailsLoadFailed = (err: any): void => {
    this.toastr.error(this.translateService.instant('Common.LoadingDataError'));
    this.loading = false;
  };

  onTabSelected = (tab: string): void => {
    this.dataItem.detailsTab = tab;
  };

  onReloadItem = (): void => {
    this.reload.emit();
  };

  addExtractedDataTab = (): void => {
    if (!this.details) return;
    const extractedDataFieldNames = [SystemMetaData.ExtractedDocumentData, SystemMetaData.ExtractedInvoiceData];

    for (const key in this.details.metaData) {
      const md = this.details.metaData[key];
      if (
        extractedDataFieldNames.findIndex(
          (extractedFieldName) => extractedFieldName.toLowerCase() === md.name.toLowerCase()
        ) !== -1
      ) {
        this.tabs.splice(
          2,
          0,
          new Tab('extracteddata', this.translateService.instant('workitem-properties.extracted-data'))
        );
        break;
      }
    }
  };
}
