import moment from 'moment';

export class DateTimeFormat {
  static getLocalDateTime(value: Date, locale: string): string {
    return moment(value).locale(locale).format('L LT');
  }

  static getLocalDateTimeWithSeconds(value: Date): string {
    return moment(value).local().format('L LTS');
  }

  static getCompactDateTime(value: Date): string {
    const formatted_date =
      value.getFullYear() +
      '-' +
      this.appendLeadingZeroes(value.getMonth() + 1) +
      '-' +
      this.appendLeadingZeroes(value.getDate()) +
      'T' +
      this.appendLeadingZeroes(value.getHours()) +
      ':' +
      this.appendLeadingZeroes(value.getMinutes()) +
      ':' +
      this.appendLeadingZeroes(value.getSeconds());

    return formatted_date;
  }

  private static appendLeadingZeroes(n) {
    if (n <= 9) {
      return '0' + n;
    }
    return n;
  }
}
