import {
  AfterViewInit,
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  ViewChild,
} from '@angular/core';
import { ResizeObserver as ResizeObserverPonyfill } from '@juggle/resize-observer';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { take, takeWhile, timer } from 'rxjs';
import { Key, Pagination, TableItem, ToolbarActionsWidth } from 'shared-code-lib';
import { IAction, IFolder } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/models';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { UtilityService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/utility.service';
import { ListItem } from '../action-dropdown/action-dropdown.component';

const ResizeObserver = window.ResizeObserver || ResizeObserverPonyfill;

@Component({
  selector: 'pagination',
  templateUrl: './pagination.component.html',
  styleUrls: ['./pagination.component.scss'],
})
export class PaginationComponent implements OnInit, AfterViewInit, OnChanges, OnDestroy {
  @Input() currentPage: number;
  @Input() pageSize: number = 25;
  @Input() itemsTotal: number;
  @Input() itemsPageCount: number;
  @Input() showItemsPageCount: boolean = true;
  @Input() canChangePageSize: boolean = false;
  @Input() canReload: boolean = true;
  @Input() folder: IFolder;
  @Input() selectedItems: TableItem[];
  @Input() showActions = false;
  @Input() inputBlurDelay = 0;

  @Output() onLoadPage = new EventEmitter<Pagination>();
  @Output() onPageSizeChanged = new EventEmitter<number>();
  @Output() onToolbarActionClick = new EventEmitter<IAction>();

  @ViewChild('paginationContainer') container: ElementRef;
  @ViewChild('pagination') paginationElement: ElementRef;

  totalPages = 0;
  currentPageNo = 0;
  pageSizes: ListItem[];
  invalidPageTitle = '';

  private resizeObserver = new ResizeObserver(() => this.setActionToolbarWidth());

  actionsMaxWidth: ToolbarActionsWidth = 'max';

  pageSizesExtraClasses: string;

  componentDestroyed = false;

  get isInvalidCurrentPage(): boolean {
    if (this.totalPages <= 0) return false;

    return this.currentPage <= 0 || this.currentPage > this.totalPages;
  }

  constructor(
    private translate: TranslateService,
    public utility: UtilityService,
    private toastr: ToastrService,
    public userState: UserStateService,
    private cdk: ChangeDetectorRef
  ) {}

  ngOnInit() {
    this.pageSizes = [
      { name: this.utility.localizeNumber(10), value: 10 },
      { name: this.utility.localizeNumber(25), value: 25 },
      { name: this.utility.localizeNumber(50), value: 50 },
      { name: this.utility.localizeNumber(100), value: 100 },
      { name: this.utility.localizeNumber(150), value: 150 },
      { name: this.utility.localizeNumber(200), value: 200 },
    ];

    this.pageSizesExtraClasses = 'pagination__results-quantity';
    this.resetTotalPagesNumber();
  }

  ngAfterViewInit(): void {
    this.setActionToolbarWidth();
    this.resizeObserver.observe(this.container.nativeElement);
  }

  ngOnChanges() {
    this.resetTotalPagesNumber();
    this.invalidPageTitle = '';

    this.setActionToolbarWidth();

    this.cdk.detectChanges();
  }

  setActionToolbarWidth = () => {
    this.actionsMaxWidth =
      this.container?.nativeElement?.offsetWidth - this.paginationElement?.nativeElement?.offsetWidth;

    if (Number.isNaN(this.actionsMaxWidth)) {
      this.actionsMaxWidth = 'max';
    } else if (this.actionsMaxWidth <= 0) {
      this.actionsMaxWidth = 0;
    }
  };

  resetTotalPagesNumber(): void {
    this.totalPages = Math.ceil(this.itemsTotal / this.pageSize);
    if (!this.totalPages) {
      this.currentPageNo = 0;
    } else {
      this.currentPageNo = this.currentPage;
    }
  }

  loadCurrentPage = () => {
    if (this.isInvalidCurrentPage) {
      this.toastr.error(this.translate.instant('Pagination.invalid-page-number'));
      return;
    }

    this.loadItems();
  };

  loadItems() {
    this.onLoadPage.emit({ pageNumber: this.currentPage, pageSize: this.pageSize });
  }

  onPageSizeChange = (value) => {
    this.pageSize = value.value;
    this.totalPages = Math.ceil(this.itemsTotal / this.pageSize);
    if (this.currentPage > this.totalPages && this.totalPages > 0) this.currentPage = this.totalPages;

    this.onPageSizeChanged.emit(this.pageSize);
    this.loadCurrentPage();
  };

  nextPage() {
    if (this.currentPage <= 0) this.currentPageNo = this.currentPage = 1;
    else this.currentPage += 1;

    this.loadCurrentPage();
  }

  previousPage() {
    if (this.currentPage > this.totalPages) this.currentPage = this.totalPages;
    else this.currentPage -= 1;

    this.loadCurrentPage();
  }

  onPressEnter() {
    this.currentPage = this.currentPageNo;
    this.loadCurrentPage();
  }

  validateNumericOnly(event: any): boolean {
    return !(
      event.key === Key.NumpadSubtract ||
      event.key === Key.NumpadAdd ||
      event.key === Key.NumpadDecimal ||
      event.key === Key.KeyE ||
      event.key === Key.KeyE.toUpperCase()
    );
  }

  onBlur(event: any) {
    timer(this.inputBlurDelay)
      .pipe(
        takeWhile(() => !this.componentDestroyed),
        take(1)
      )
      .subscribe(() => this.handleChangePage(event));
  }

  onActionClicked = (action: IAction) => {
    this.onToolbarActionClick.emit(action);
  };

  private handleChangePage(event: any) {
    if (event.target.value && parseInt(event.target.value, 10) !== this.currentPage) {
      this.currentPage = +event.target.value;

      this.loadCurrentPage();

      if (parseInt(event.target.value, 10) > this.totalPages) {
        this.invalidPageTitle = this.translate.instant('Pagination.invalid-page-number-title') + ' ' + this.totalPages;
      } else {
        this.invalidPageTitle = '';
      }
    } else {
      event.target.value = this.currentPage;
    }
  }

  ngOnDestroy(): void {
    this.resizeObserver.disconnect();
    this.componentDestroyed = true;
  }
}
