import { TenantAuthenticationType } from 'shared-code-lib';

export interface IAdvancedSetting {
  name: string;
  value: string;
  optionalValues: Array<string>;
}

export interface ISendFAXProfile {
  endPointUrl: string;
  enablePostponed: boolean;
  enableLists: boolean;

  fileTypes: Array<string>;

  advancePageSetting: Array<IAdvancedSetting>;
}

export enum TenantType {
  Normal = 0,
  Partner = 1,
}

export enum UserSignOnType {
  Password = 0,
  SSO = 1,
  SAML = 2,
}

export interface ITenantOptions {
  confirmLogout: boolean;
  name: string;
  tenantType: TenantType;
  authenticationType: TenantAuthenticationType;
}

export interface IUserProfile {
  url: string;
  fax: ISendFAXProfile;
  fonts: Array<string>;
  tenantOptions: ITenantOptions;
  minimumVersion: string;
  tenantName: string;
  signOnType: UserSignOnType;
  useDefaultReplyAddress: boolean;
  mobileBrand: string;
  sessionTimeInMinutes: number;
}
