import { Component, ElementRef, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import moment from 'moment';
import { ToastrService } from 'ngx-toastr';

import { DateTime, FieldDefinition, FixedDataSource, MetaDataType } from 'shared-code-lib';
import { Component as BambaComponent } from '../../models/component';
import { IComponentVersion } from '../../models/component-version';
import { Grouping } from '../../models/deployments';
import { ErrorsService } from '../../services/errors.service';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResult, User } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

type RecordType<T> = { date: T; assignee: T; comment: T };

@Component({
  selector: 'app-component-deployment-scheduling',
  templateUrl: './component-deployment-scheduling.component.html',
  styleUrl: './component-deployment-scheduling.component.scss',
})
export class ComponentDeploymentSchedulingComponent implements OnInit {
  @ViewChild('spinnerElement', { static: true }) spinnerElement: ElementRef;

  @Output() closeModal = new EventEmitter<void>();

  extraParams: IExtraParameters;

  fields: Record<string, RecordType<FieldDefinition>>;
  values: Record<string, RecordType<string>>;

  constructor(
    private sharedDataService: SharedDataService,
    private hydraApiService: HydraApiService,
    private errorsService: ErrorsService,
    private toastr: ToastrService,
    private translate: TranslateService,
    private spinnerService: SpinnerStateService
  ) {}

  ngOnInit(): void {
    this.extraParams = this.sharedDataService.extraParameters as IExtraParameters;

    this.createFields();
  }

  getDeploymentDateForGrouping = (groupingId: string) => {
    if (!this.values[groupingId].date) return '';

    return moment.utc(this.values[groupingId].date).format(DateTime.NormalizedDateFormat);
  };

  setDeploymentDateForGrouping = (groupingId: string, date: string) => {
    this.values[groupingId].date = `${moment.utc(date, DateTime.NormalizedDateFormat).toISOString()}`;
  };

  createFields = () => {
    const assigneesDataSource = new FixedDataSource(
      this.extraParams.assignees.map((user) => ({ name: user.name, value: user.id }))
    );

    this.fields = this.extraParams.groupings.reduce(
      (fields, grouping) => {
        fields[grouping.id] = {
          date: new FieldDefinition({
            type: MetaDataType.Date,
            placeholder: this.translate.instant('component-deployment-scheduling-modal.date'),
            required: true,
          }),
          assignee: new FieldDefinition({
            type: MetaDataType.List,
            placeholder: this.translate.instant('component-deployment-scheduling-modal.assignee'),
            datasource: assigneesDataSource,
            required: true,
          }),
          comment: new FieldDefinition({
            type: MetaDataType.Text,
            placeholder: this.translate.instant('component-deployment-scheduling-modal.comments'),
            required: false,
          }),
        };
        return fields;
      },
      {} as Record<string, RecordType<FieldDefinition>>
    );

    this.values = this.extraParams.groupings.reduce(
      (values, grouping) => {
        const schedule = this.extraParams?.componentVersion?.deploymentSchedules?.find(
          (s) => s.groupingId === grouping.id
        );

        values[grouping.id] = {
          date: schedule?.dateDeploymentUTC ?? '',
          assignee: schedule?.assigneeId ?? '',
          comment: schedule?.comments ?? '',
        };

        return values;
      },
      {} as Record<string, RecordType<string>>
    );
  };

  onClose = (): void => this.closeModal.emit();

  onSave = () => {
    this.spinnerService.show(this.translate.instant('Common.Saving'), this.spinnerElement.nativeElement);

    const updatedDeploymentSchedules = Object.entries(this.values).map(([k, v]) => ({
      groupingId: k,
      assigneeId: v.assignee,
      dateDeploymentUTC: v.date,
      comments: v.comment,
    }));

    this.hydraApiService.updateDeploymentSchedules(
      this.extraParams.componentVersion.id,
      updatedDeploymentSchedules,
      this.onSaveSuccessful,
      this.onSaveFailed
    );
  };

  onSaveSuccessful = (result: ApiResult) => {
    this.spinnerService.hide();
        this.toastr.success(this.translate.instant('component-deployment-scheduling-modal.saved-successfully'));
this.onClose();
  };

  onSaveFailed = (errors: any) => {
    this.spinnerService.hide();
    this.errorsService.showErrorsModal(errors, this.translate.instant('Common.Failed'));
  };
}

interface IExtraParameters {
  component: BambaComponent;
  componentVersion: IComponentVersion;
  groupings: Grouping[];
  assignees: User[];
}
