import { Component, EventEmitter, Input, Output, ViewEncapsulation } from '@angular/core';
import { MobileAction } from 'shared-code-lib';

@Component({
  selector: 'app-select-action',
  templateUrl: './select-action.component.html',
  styleUrls: ['./select-action.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class SelectActionComponent {
  @Input() actions: MobileAction[] = [];
  @Output() actionSelected = new EventEmitter<MobileAction>();

  onSelectAction(actionSelected: MobileAction) {
    this.actionSelected.emit(actionSelected);
  }
}
