import { HttpClient } from '@angular/common/http';
import { EventEmitter } from '@angular/core';
import { Router } from '@angular/router';

import { TranslateService } from '@ngx-translate/core';
import { saveAs } from 'file-saver/FileSaver';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';

import { take } from 'rxjs/operators';
import { AuthService, MetaDataCollection, TableItem } from 'shared-code-lib';
import { IFilterValue } from '../models/filter';
import { GridItem } from '../models/grid-item';
import { ApiService } from '../services/api.service';
import { ErrorsService } from '../services/errors.service';
import { HydraApiEventService } from '../services/hydra-api-event.service';
import { LoadAppStateService } from '../services/load-app-state.service';
import { ExecuteCriteria, IAction, SpinnerState } from '../services/models';
import { PrintPdfFileService } from '../services/print-pdf-file.service';
import { SharedDataService } from '../services/shared-data.service';
import { SpinnerStateService } from '../services/spinner-state.service';
import { UserStateService } from '../services/user-state.service';
import { ActionFileExtraParameters } from './actions';

declare const UES: any;

export enum InterFaxActions {
  MarkRead = 'InterFAX-Upland.Bamba.InterFAX.Inbox.Actions.MarkRead',
}

export class UpdateResults {
  updated: Array<any>;
  deleted: Array<any>;
  errors: Array<string>;
  silent: boolean;
  isServerData: boolean;
  inflater: (data: any) => any;
}

export interface IItemId {
  id: string;
}

interface AutoExecuteActionDescriptor {
  id: string;
  executeWhen: ExecuteCriteria;
}

export interface AutoExecuteResult {
  actions: AutoExecuteActionDescriptor[];
}

interface AutoExecuteConfig {
  handleServerResult: boolean;
}

export interface SilentUpdateResult {
  tableItems: Array<TableItem>;
  selectedItems: Array<TableItem>;
}

interface RequestBody {
  folderID: string;
  actionID: string;
  itemIDs: string[];
  filters: IFilterValue[];
}

interface ActionExecuteResult {
  type: string;
  result: any;
}

export class ItemActionHandler {
  toggleLoading = new EventEmitter<SpinnerState>();
  reload = new EventEmitter<boolean>();
  update = new EventEmitter<UpdateResults>();
  openFolder = new EventEmitter<string>();
  openFolderEX = new EventEmitter<string>();
  onAutoExecuteResult = new EventEmitter<AutoExecuteResult>();

  closeFolder = new EventEmitter<string>();

  actionCompleted = new EventEmitter<string>();

  constructor(
    private ngxSmartModalService: NgxSmartModalService,
    private translate: TranslateService,
    private apiService: ApiService,
    private errorsService: ErrorsService,
    private sharedData: SharedDataService,
    private toastr: ToastrService,
    private http: HttpClient,
    private router: Router,
    protected authService: AuthService,
    private printPdfFileService: PrintPdfFileService,
    private appState: LoadAppStateService,
    private spinnerState?: SpinnerStateService,
    private userState?: UserStateService,
    private hydraApiEventService?: HydraApiEventService
  ) {}

  invoke = (
    folderId: string,
    action: IAction,
    items: Array<any>,
    filters: IFilterValue[],
    silent: boolean = false,
    isAuto: boolean = false
  ): void => {
    if (action.confirmationText && action.confirmationText.length) {
      this.ngxSmartModalService.setModalData(
        {
          title: 'MainHeader.ActionConfirmation',
          text: action.confirmationText,
          buttonText: action.confirmationButtonText ? action.confirmationButtonText : action.name,
          confirm: () => this.executeAction(folderId, action, items, filters),
          cancel: () => this.cancelAction(),
        },
        'actionConfirmModal',
        true
      );
      this.ngxSmartModalService.getModal('actionConfirmModal').open();
    } else {
      this.executeAction(folderId, action, items, filters, silent, isAuto);
    }
  };

  CloseBrowserTab = (): void => {
    window.self.close();
  };

  invokeEx = (
    folderId: string,
    action: IAction,
    itemIds: IItemId[],
    args: MetaDataCollection,
    successCallBack: (result: any) => void,
    failureCallback: (errors: any[]) => void = null,
    displayLoadingMessage = true,
    filters: IFilterValue[] = []
  ): void => {
    if (displayLoadingMessage)
      this.toggleLoadingState({ state: true, message: this.translate.instant('Common.ExecutingAction') });

    const reqBody = {
      folderID: folderId,
      actionID: action.id,
      itemIDs: itemIds,
      args: args.serializable(),
      filters: filters,
    };

    this.apiService.postItemtoServer('action/executeEx', reqBody).subscribe(
      (executeResult: ActionExecuteResult) => {
        if (this.processActionResult(folderId, action, executeResult, failureCallback)) {
          successCallBack(executeResult);
        }
      },
      (err) => {
        if (failureCallback) {
          failureCallback([err]);
        } else {
          this.processActionFailure(err);
        }
      }
    );
  };

  private executeAction = (
    folderId: string,
    action: IAction,
    items: Array<any>,
    filters: IFilterValue[],
    silent: boolean = false,
    isAuto: boolean = false
  ): void => {
    this.ngxSmartModalService.getModal('actionConfirmModal').close();

    if (!silent) {
      this.toggleLoadingState({ state: true, message: this.translate.instant('Common.ExecutingAction') });
    }

    const reqBody: RequestBody = {
      folderID: folderId,
      actionID: action.id,
      itemIDs: items.map((i) => i.id),
      filters: filters,
    };

    let autoExecuteActionConfig: AutoExecuteConfig = isAuto
      ? this.handleAutoAction(reqBody, silent)
      : { handleServerResult: true };

    this.apiService.postItemtoServer('action/execute', reqBody).subscribe({
      next: (executeResult: ActionExecuteResult) => {
        this.processActionResult(
          folderId,
          action,
          executeResult,
          null,
          silent,
          autoExecuteActionConfig.handleServerResult
        );
      },
      error: (err) => {
        this.processActionFailure(err, silent);
      },
    });
  };

  private handleAutoAction = (req: RequestBody, silent = true): AutoExecuteConfig => {
    switch (req.actionID) {
      case InterFaxActions.MarkRead:
        let actionData = {
          type: 'UpdateItems',
          result: {
            updated: req.itemIDs.map((id) => ({ id })),
            inflater: (data: any) => ({
              ...data,
              isRead: true,
              classes: `${data.classes}`.replace('item-unread', 'item-read'),
            }),
          },
        };
        this.applyAction(actionData, silent, false);
        return { handleServerResult: true };
      default:
        return { handleServerResult: true };
    }
  };

  private cancelAction = (): void => {
    this.ngxSmartModalService.getModal('actionConfirmModal').close();
  };

  private processActionResult = (
    folderId: string,
    action: IAction,
    executeResult: ActionExecuteResult,
    failureCallback: (errors: any[]) => void = null,
    silent: boolean = false,
    handleServerResult: boolean = true
  ): boolean => {
    if (!silent) this.toggleLoadingState({ state: false, message: this.translate.instant('Common.ExecutingAction') });

    const actionExecuteResults = this.getExecuteResults(executeResult);

    const executionErrors = actionExecuteResults.flatMap((item) => item?.result?.errors || []);
    const hasErrors = executionErrors?.length;

    if (hasErrors) {
      this.showErrors(executionErrors, failureCallback, silent, handleServerResult);
    } else {
      this.sharedData.extraParameters = executeResult.result.extraParameters;
      this.sharedData.action = action;
      this.sharedData.folderId = folderId;
      this.sharedData.actionHandler = this;

      if (!handleServerResult) return true;
    }

    actionExecuteResults.forEach((executeResult) => {
      if (!hasErrors || executeResult.result.forceApply) {
        this.applyAction(executeResult, silent);
      }
    });

    if (hasErrors) return false;

    this.actionCompleted.emit();

    actionExecuteResults.forEach((executeResult) => {
      if (this.userState && executeResult.result.responsibleFoldersIds) {
        this.userState.addToForceReloadFoldersIds(executeResult.result.responsibleFoldersIds);
      }
    });

    return true;
  };

  private showErrors(
    errors: any[],
    failureCallback: (errors: any[]) => void = null,
    silent: boolean = false,
    handleServerResult: boolean = true
  ) {
    if (failureCallback) {
      failureCallback(errors);
    } else if (!silent) {
      this.reload.emit(false);
      this.errorsService.showErrorsModal(errors, 'Common.ActionFailed');
    } else if (!handleServerResult) {
      this.toastr.error(this.translate.instant('Common.ActionFailed'));
    }
  }

  private getExecuteResults(actionData: ActionExecuteResult): ActionExecuteResult[] {
    const results: ActionExecuteResult[] = [];

    if (actionData.type === 'MultiActionResult') {
      actionData.result.results.forEach((result: any) => results.push({ type: result.type, result: result }));
    } else {
      results.push(actionData);
    }

    return results;
  }

  private applyAction = (actionData: ActionExecuteResult, silent = false, isServerData = true): void => {
    switch (actionData.type) {
      case 'CloseBrowserTab':
        this.closeFolder.emit(actionData.result.folderId);
        break;

      case 'ToggleUES':
        try {
          UES.toggle();
        } catch (e) {
          console.error(e);
        }

        break;

      case 'GotoTab':
        const { includeAuthorization, noOpener, noReferrer, uri, target } = actionData.result;

        if (includeAuthorization) {
          this.authService.shareSessionForTabs();
        }

        let newTabFeatures: string = undefined;

        if (noOpener && noReferrer) {
          newTabFeatures = 'noopener,noreferrer';
        } else if (noOpener) {
          newTabFeatures = 'noopener';
        } else if (noReferrer) {
          newTabFeatures = 'noreferrer';
        }

        window.open(uri, target, newTabFeatures);
        break;

      case 'Toast':
        this.toastr.success(actionData.result.message);
        break;

      case 'Goto':
        this.router.navigateByUrl(actionData.result.uri);
        break;

      case 'GotoCurrentPage':
        this.reload.emit(false);
        break;

      case 'ReloadState':
        this.appState.reloadState();
        break;

      case 'DownloadFile':
      case 'ActionFile':
        this.toggleLoadingState({ state: true, message: this.translate.instant('Common.ExecutingAction') });

        this.http.get(encodeURI(actionData.result.uri), { responseType: 'blob' }).subscribe(
          (blob) => {
            saveAs(blob, actionData.result.filename);
            this.toggleLoadingState({ state: false });
          },
          (err) => {
            this.toggleLoadingState({ state: false });
            this.processActionFailure(err);
          }
        );
        break;

      case 'ActionFileEx':
        this.toggleLoadingState({ state: true, message: this.translate.instant('Common.ExecutingAction') });

        this.http
          .post(
            encodeURI(actionData.result.uri),
            new ActionFileExtraParameters(actionData.result.extraParameters).serializable(),
            { responseType: 'blob' }
          )
          .subscribe(
            (blob) => {
              saveAs(blob, actionData.result.filename);
              this.toggleLoadingState({ state: false });
            },
            (err) => {
              this.processActionFailure(err);
              this.toggleLoadingState({ state: false });
            }
          );
        break;

      case 'PrintFile':
        this.toggleLoadingState({ state: true, message: this.translate.instant('Common.ExecutingAction') });

        this.http
          .post(
            encodeURI(actionData.result.uri),
            new ActionFileExtraParameters(actionData.result.extraParameters).serializable(),
            { responseType: 'blob' }
          )
          .pipe(take(1))
          .subscribe(
            (blob) => {
              this.printPdfFileService.printFile(URL.createObjectURL(blob), () => {
                this.toggleLoadingState({ state: false });
              });
            },
            (err) => {
              this.processActionFailure(err);
              this.toggleLoadingState({ state: false });
            }
          );

        break;

      case 'UpdateItems':
        this.update.emit({ silent, isServerData, ...actionData.result });
        break;

      case 'DeletedMetaDataItems':
        actionData.result.items.forEach((item: any) =>
          this.hydraApiEventService.metaDataDeleted(new GridItem(item.id).id)
        );
        break;

      case 'GotoModal':
        this.ngxSmartModalService.getModal(actionData.result.modal).open();
        break;

      case 'GotoMessageModal':
        this.ngxSmartModalService.setModalData(
          {
            title: actionData.result.modalTitle,
            text: actionData.result.message,
            confirm: () => this.ngxSmartModalService.getModal(actionData.result.modal).close(),
          },
          actionData.result.modal,
          true
        );

        this.ngxSmartModalService.getModal(actionData.result.modal).open();
        if (actionData.result.updateItems) this.update.emit(<UpdateResults>actionData.result.updateItems);
        break;

      case 'OpenFolder':
        this.openFolder.emit(actionData.result.folderId);
        break;

      case 'OpenFolderEX':
        this.openFolderEX.emit(actionData.result.folderId);
        break;

      case 'ActionConfirmationModal':
        const args = new MetaDataCollection();

        for (const key in actionData.result.metaDataCollection) {
          args.set(key, actionData.result.metaDataCollection[key]?.value?.toString());
        }

        this.ngxSmartModalService.setModalData(
          {
            title: actionData.result.title ? actionData.result.title : 'MainHeader.ActionConfirmation',
            text: actionData.result.message,
            buttonText: actionData.result.buttonText ? actionData.result.buttonText : actionData.result.action.name,
            confirm: () =>
              this.invokeEx(
                actionData.result.folderId,
                actionData.result.action,
                actionData.result.items.map((a) => a.id),
                args,
                (result) => {},
                (errors: any[]) => {
                  errors.forEach((e) => this.toastr.error(e));
                },
                true
              ),

            cancel: () => this.cancelAction(),
          },
          'actionConfirmModal',
          true
        );

        this.ngxSmartModalService.getModal('actionConfirmModal').open();
        break;

      case 'ResendFaxResult':
        this.ngxSmartModalService.setModalData(
          {
            ...actionData.result,
          },
          'resendFaxModal',
          true
        );

        this.ngxSmartModalService.getModal('resendFaxModal').open();
        break;

      case 'ChangePasswordToHighResult':
        this.ngxSmartModalService.setModalData(
          {
            ...actionData.result,
          },
          'changeSecureUserPasswordModal',
          true
        );

        this.ngxSmartModalService.getModal('changeSecureUserPasswordModal').open();
        break;

      case 'SelectOptionActionResult':
        this.ngxSmartModalService.setModalData(
          {
            ...actionData.result,
          },
          'selectOptionModal',
          true
        );

        this.ngxSmartModalService.getModal('selectOptionModal').open();
        break;

      case 'AutoExecuteActionResult':
        this.onAutoExecuteResult.emit(actionData.result);
        break;

      case 'MultiSelectOptionActionResult':
        this.ngxSmartModalService.setModalData(
          {
            ...actionData.result,
          },
          'multiSelectOptionModal',
          true
        );

        this.ngxSmartModalService.getModal('multiSelectOptionModal').open();
        break;

      case 'ActionResult':
      default:
        break;
    }
  };

  private processActionFailure = (err: any, silent = false): void => {
    if (silent) return;

    this.toggleLoadingState({ state: false });
    this.toastr.error(this.translate.instant('Common.ActionFailed'));
  };

  toggleLoadingState = (ss: SpinnerState): void => {
    if (!this.spinnerState) return;

    if (ss.state) {
      this.spinnerState.show(
        ss.message ? ss.message : this.translate.instant('Common.ExecutingAction'),
        document.documentElement
      );
    } else {
      this.spinnerState.hide(ss.message ? ss.message : this.translate.instant('Common.ExecutingAction'));
    }
  };
}
