import { Component, OnInit, Output, EventEmitter, ViewEncapsulation, Input, OnDestroy } from '@angular/core';

import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { DomSanitizer } from '@angular/platform-browser';

@Component({
  selector: 'qr-code-viewer',
  templateUrl: './qr-code-viewer.component.html',
  styleUrls: ['./qr-code-viewer.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class QRCodeViewerComponent implements OnInit, OnDestroy {
  @Input() title: string;
  @Input() imageUrl: any;
  @Input() modalId: string = 'qrCodeModal';
  @Output() closeModal = new EventEmitter();

  modal: NgxSmartModalComponent;
  trustedImageUrl: any;

  constructor(public ngxSmartModalService: NgxSmartModalService, private sanitizer: DomSanitizer) {
    this.modal = this.ngxSmartModalService.getModal(this.modalId);
  }

  ngOnInit(): void {
    this.trustedImageUrl = this.sanitizer.bypassSecurityTrustUrl(this.imageUrl);
  }

  ngOnDestroy(): void {}

  close = (): void => {
    this.modal?.close();
    this.closeModal.emit();
  };
}
