import { Component, EventEmitter, Input, OnDestroy, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { SortDescriptor } from '@progress/kendo-data-query';

import { Subscription } from 'rxjs';
import { ColumnDisplayType, ICombinedColumn, InvokeAction, TableItem } from 'shared-code-lib';
import { ItemActionHandler } from '../../../../../../Bamba.Web/ClientApp/src/app/blocks/core/itemActionHandler';
import { ActionService } from '../../../../../../Bamba.Web/ClientApp/src/app/blocks/services/action.service';

@Component({
  selector: 'app-file-versions',
  templateUrl: './file-versions.component.html',
  styleUrls: ['./file-versions.component.scss'],
})
export class FileVersionsComponent implements OnInit, OnDestroy {
  @Input() versions: any;
  @Output() reload = new EventEmitter();

  versionsItems: TableItem[] = [];
  versionsColumns: ICombinedColumn[];
  versionsSort: SortDescriptor;

  itemActionHandler: ItemActionHandler;

  subscriptions = new Subscription();

  constructor(private translateService: TranslateService, private actionService: ActionService) {}

  ngOnInit(): void {
    this.itemActionHandler = this.actionService.createItemActionHandler();

    this.subscriptions.add(this.itemActionHandler.actionCompleted.subscribe(this.reloadItem));

    this.versionsColumns = this.getColumns();
    this.versionsSort = { field: '1', dir: 'desc' };
    this.versionsItems = this.versions.map((i) => new TableItem(i, this.versionsColumns, this.translateService));
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  onInvokeAction = (ia: InvokeAction): void => {
    this.itemActionHandler.invoke('', ia.action, [ia.item], []);
  };

  reloadItem = (): void => {
    this.reload.emit();
  };

  getColumns(): Array<ICombinedColumn> {
    const columns: Array<ICombinedColumn> = [];

    columns.push(this.createColumn('FOLDER.ITEMTYPE', ColumnDisplayType.Image, '', 'iconUrl', 32));

    columns.push(
      this.createColumn(
        'FOLDER.DATETIME',
        ColumnDisplayType.DateTime,
        this.translateService.instant('product-details.date-created'),
        'date',
        175
      )
    );

    columns.push(
      this.createColumn(
        'FOLDER.DETAILS',
        ColumnDisplayType.Text,
        this.translateService.instant('product-details.item-details'),
        'details',
        -1
      )
    );

    return columns;
  }

  createColumn(id: string, displayType: number, columnName: string, itemProperty: string, width: number) {
    return {
      id: 'column_' + id,
      width: width != -1 ? width : 200,
      stretch: width == -1,
      displayType: displayType,
      headerImage: '',
      headerText: columnName,
      itemProperty: itemProperty,
      columnName: columnName,
      sortable: false,
      sortByFieldName: '',
      invertBooleanValue: false,
    };
  }
}
