import { Subject } from 'rxjs';
import { TranslateService } from '@ngx-translate/core';
import { IFieldDataSource, IFieldOptions } from './field-definition';

export class FixedDataSource implements IFieldDataSource {
  changed = new Subject<void>();

  constructor(options?: IFieldOptions[], sort: boolean = false) {
    this.options = options || new Array<IFieldOptions>();
    if (sort) this.options = this.options.sort((x, y) => x.name.localeCompare(y.name));
  }

  options: IFieldOptions[] = null;

  updateOptions(options: IFieldOptions[]) {
    this.options = options;
    this.changed.next();
  }

  getItems(
    startsWith: string,
    currentValue: string,
    successCallBack: (items: IFieldOptions[]) => void,
    failureCallBack: (err: any) => void
  ): void {
    successCallBack(this.options);
  }
}

export class EnumDataSource extends FixedDataSource {
  constructor(enumType: any, enumResourceName: string, translate: TranslateService) {
    const options = [];

    for (let item in enumType) {
      if (isNaN(Number(item))) {
        options.push({
          name: translate.instant(`${enumResourceName}.${item}`),
          value: enumType[item],
        });
      }
    }

    super(options);
  }
}
