export interface IPackage {
  id: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  code: string;
  name: string;
  description: string;
  features: Array<string>;
}

export class Package {
  id: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  code: string;
  name: string;
  description: string;
  features: Array<string>;

  constructor(initializer: IPackage) {
    this.id = initializer ? initializer.id : '';
    this.dateCreatedUTC = initializer ? initializer.dateCreatedUTC : new Date();
    this.dateModifiedUTC = initializer ? initializer.dateModifiedUTC : new Date();
    this.code = initializer ? initializer.code : '';
    this.name = initializer ? initializer.name : '';
    this.description = initializer ? initializer.description : '';
    this.features = initializer ? initializer.features.map((f) => f) : new Array<string>();
  }

  public serializable(): IPackage {
    return {
      id: this.id,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      code: this.code,
      name: this.name,
      description: this.description,
      features: this.features,
    };
  }
}
