import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { PreviewDocument } from '../../../Bamba.Web/ClientApp/src/app/views/product-item/document-preview/document-preview.component';

@Injectable({
  providedIn: 'root',
})
export class CurrentSelectedDocumentService {
  private _currentDocumentSource = new BehaviorSubject<PreviewDocument>(null);
  currentDocument$ = this._currentDocumentSource.asObservable();

  setCurrentDocument = (doc?: PreviewDocument) => {
    this._currentDocumentSource.next(doc);
  };
}
