import { Component, EventEmitter, OnInit, Output, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { FieldDefinition, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { SharedDataService } from '../../services/shared-data.service';
import { ApiResult } from '../../services/models';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-remove-jira-ticket',
  templateUrl: './remove-jira-ticket.component.html',
  styleUrls: ['./remove-jira-ticket.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class RemoveJiraTicketComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  errors: string[] = [];
  componentVersionId: string;
  componentVersionPackageName: string;
  comment = '';
  installedTickets: Ticket[] = [];
  removedTickets: Ticket[] = [];

  commentField: FieldDefinition;

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService
  ) {}

  ngOnInit(): void {
    this.componentVersionId = this.sharedDataService.extraParameters.componentVersionId;
    this.componentVersionPackageName = this.sharedDataService.extraParameters.componentVersionPackageName;

    this.sharedDataService.extraParameters.tickets.forEach((t: any) => {
      this.installedTickets.push({
        jiraId: t.jiraId,
        jiraTitle: t.jiraTitle,
        jiraIdWithTitle: t.jiraId + ' - ' + t.jiraTitle,
      });
    });

    this.commentField = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('remove-jira-ticket.comment-label'),
      placeholder: this.translateService.instant('remove-jira-ticket.comment-placeholder'),
      required: false,
    });
  }

  ticketsSelected = (selected: Ticket[]): void => {
    this.removedTickets = selected;
  };

  removeTicket(): void {
    const args = new MetaDataCollection();

    args.set('componentVersionId', this.componentVersionId);
    args.set('selectedJiraIds', this.removedTickets.map((t) => t.jiraId).join(','));
    args.set('comment', this.comment);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      [],
      args,
      this.onRemoveTicketSucceeded,
      this.onRemoveTicketFailed
    );
  }

  onRemoveTicketSucceeded = (result: ApiResult): void => {
    this.spinnerService.hide();
    this.close();
  };

  onRemoveTicketFailed = (errors: any[]): void => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  close = (): void => this.closeModal.emit();
}

interface Ticket {
  jiraId: string;
  jiraTitle: string;
  jiraIdWithTitle: string;
}
