export interface IExportMetaData {
  enabled: boolean;
  type: ExportMetaDataType;
  metaDataFields: string[];
  encodingType: ExportMetaDataEncoding;
  includeBOM: boolean;
  filename: string;
}

export class ExportMetaData implements IExportMetaData {
  enabled: boolean;
  type: ExportMetaDataType;
  metaDataFields: string[];
  encodingType: ExportMetaDataEncoding;
  includeBOM: boolean;
  filename: string;

  constructor(initializer: IExportMetaData) {
    if (!initializer) throw new Error('Invalid initializer ExportMetaData');
    if (initializer.enabled === undefined) throw new Error('Invalid initializer ExportMetaData.enabled');
    if (initializer.type === undefined) throw new Error('Invalid initializer ExportMetaData.type');
    if (initializer.metaDataFields === undefined) throw new Error('Invalid initializer ExportMetaData.metaDataFields');
    if (initializer.encodingType === undefined) throw new Error('Invalid initializer ExportMetaData.encodingType');
    if (initializer.includeBOM === undefined) throw new Error('Invalid initializer ExportMetaData.includeBOM');
    if (initializer.filename === undefined) throw new Error('Invalid initializer ExportMetaData.filename');

    this.enabled = initializer.enabled;
    this.type = initializer.type;
    this.metaDataFields = initializer.metaDataFields.map((md) => md);
    this.encodingType = initializer.encodingType;
    this.includeBOM = initializer.includeBOM;
    this.filename = initializer.filename;
  }

  static create = (initializer: IExportMetaData): ExportMetaData => {
    if (!initializer) throw new Error('Invalid initializer Create ExportMetaData');
    if (initializer.type === undefined) throw new Error('Invalid initializer Create ExportMetaData.type');

    if (initializer.type === ExportMetaDataType.CSV) return new ExportMetaDataCSV(<IExportMetaDataCSV>initializer);
    if (initializer.type === ExportMetaDataType.JSON) return new ExportMetaDataJSON(<IExportMetaDataJSON>initializer);
    if (initializer.type === ExportMetaDataType.XML) return new ExportMetaDataXML(<IExportMetaDataXML>initializer);

    return new ExportMetaData(initializer);
  };

  serializable(): IExportMetaData {
    return {
      enabled: this.enabled,
      type: this.type,
      metaDataFields: this.metaDataFields,
      encodingType: this.encodingType,
      includeBOM: this.includeBOM,
      filename: this.filename,
    };
  }
}

export interface IExportMetaDataCSV extends IExportMetaData {
  includeHeaderRow: boolean;
  delimiter: string;
}

export class ExportMetaDataCSV extends ExportMetaData implements IExportMetaDataCSV {
  includeHeaderRow: boolean;
  delimiter: string;

  constructor(initializer: IExportMetaDataCSV) {
    super(<IExportMetaData>initializer);

    this.includeHeaderRow = !!initializer.includeHeaderRow;
    this.delimiter = initializer.delimiter || ',';
  }

  serializable(): IExportMetaDataCSV {
    return {
      ...super.serializable(),
      includeHeaderRow: this.includeHeaderRow,
      delimiter: this.delimiter,
    };
  }
}

export interface IExportMetaDataJSON extends IExportMetaData {}

export class ExportMetaDataJSON extends ExportMetaData implements IExportMetaDataJSON {
  constructor(initializer: IExportMetaDataJSON) {
    super(<IExportMetaData>initializer);
  }
}

export interface IExportMetaDataXML extends IExportMetaData {
  applyXLT: boolean;
  xltContent: string;
  xltFilename: string;
}

export class ExportMetaDataXML extends ExportMetaData implements IExportMetaDataXML {
  applyXLT: boolean;
  xltContent: string;
  xltFilename: string;

  constructor(initializer: Partial<ExportMetaDataXML>) {
    super(<IExportMetaData>initializer);

    this.applyXLT = initializer.applyXLT || false;
    this.xltContent = initializer.xltContent || '';
    this.xltFilename = initializer.xltFilename || '';
  }

  serializable(): IExportMetaDataXML {
    return {
      ...super.serializable(),
      applyXLT: this.applyXLT,
      xltContent: this.xltContent,
      xltFilename: this.xltFilename,
    };
  }
}

export enum ExportMetaDataType {
  CSV = 0,
  JSON = 1,
  XML = 2,
}

export enum ExportMetaDataEncoding {
  ASCII = 0,
  UTF8 = 1,
  UTF16 = 2,
  UTF32 = 3,
}
