import { Injectable, Inject } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';

declare var gtag: any;

@Injectable()
export class Analytics {
  private trackingId: string;

  constructor(private router: Router) { }

  initialize = (trackingId: string): void => {
    if (!trackingId) return;

    this.trackingId = trackingId;
    this.config({ send_page_view: false });

    gtag('config', this.trackingId);

    this.router.events.subscribe(event => {
      if (event instanceof NavigationEnd) this.pageview(event);
    });
  };

  event(action: string, params = {}) {
    if (!this.trackingId) return;

    try {
      gtag('event', action, params);
    } catch (err) {
      console.error('Google Analytics event error', err);
    }
  }

  modal = (modalId: string): void => {
    const params = {
      page_title: `modal-${modalId}`,
      page_location: window.location.href,
    };

    this.event('page_view', params);
  };

  pageview(event: NavigationEnd) {
    try {
      const params = {
        page_path: event.urlAfterRedirects,
        page_title: this.getPageTitle(window.location.href),
        page_location: window.location.href,
      };

      this.event('page_view', params);
    } catch (err) {
      console.error('Google Analytics pageview error', err);
    }
  }

  private config(params: any) {
    try {
      gtag('config', this.trackingId, params);
    } catch (err) {
      console.error('Google Analytics config error', err);
    }
  }

  private set(params: any) {
    try {
      gtag('set', params);
    } catch (err) {
      console.error('Google Analytics set error', err);
    }
  }

  getPageTitle = (url: string): string => {
    try {
      const uri = new URL(url);

      const path = uri.pathname;
      if (!path) return url;

      if (path.startsWith('/product/')) {
        const parts = path.split('/');

        if (parts.length < 3) {
          return parts.join('-');
        }

        const classnameParts = parts[parts.length - 1].split('.');
        if (classnameParts.length < 2) {
          return parts.join('-');
        }

        let classname = classnameParts[classnameParts.length - 1];
        if (classname == 'Folder') classname = classnameParts[classnameParts.length - 2];

        return `${parts[1]}-${classname}`;
      } else if (path.startsWith('/admin/')) {
        const parts = path.split('/');

        if (parts.length < 3) {
          return parts.join('-');
        }

        return `admin-${parts[2]}`;
      }

      const parts = path.split('/');

      return parts[parts.length - 1];
    } catch (e) {
      console.error(e.toString());

      return url;
    }
  };
}