import { Injectable } from '@angular/core';
import { DateRangeKeys, DecimalKeys, IntegerKeys, Key } from './key-enum';

@Injectable()
export class CharactersValidator {
  private _digitsRegex: RegExp = /^\d*$/;

  get digitsRegex(): RegExp {
    return this._digitsRegex;
  }

  constructor() {}

  allowIntegerOnly = (event: any, allowNegativeNumbers: boolean = true): void => {
    if ((event.key === Key.NumpadSubtract || event.key === Key.Subtract) && allowNegativeNumbers) {
      if (event.target.value === '' || event.target.selectionStart === 0) return;
      else this.cancelKeyPressEvent(event);
    }
    if (!this.isKeyDownAllowed(event, IntegerKeys)) {
      this.cancelKeyPressEvent(event);
    }
  };

  allowDecimalOnly = (event: any, allowNegativeNumbers: boolean = true): void => {
    if ((event.key === Key.NumpadSubtract || event.key === Key.Subtract) && allowNegativeNumbers) {
      if (event.target.value === '' || event.target.selectionStart === 0) return;
      else this.cancelKeyPressEvent(event);
    }

    if (event.key === Key.NumpadDecimal || event.key === Key.Decimal) {
      if (event.target.value.includes('.') || event.target.value.includes(',')) this.cancelKeyPressEvent(event);
    }

    if (!this.isKeyDownAllowed(event, DecimalKeys)) {
      this.cancelKeyPressEvent(event);
    }
  };

  allowDateRangeOnly = (event: any): void => {
    if (!this.isKeyDownAllowed(event, DateRangeKeys)) {
      this.cancelKeyPressEvent(event);
    }
  };

  private cancelKeyPressEvent = (event: any): void => {
    if (event) {
      if (event.preventDefault) event.preventDefault();
      if (event.stopPropagation) event.stopPropagation();
    }
  };

  private isKeyDownAllowed = (event: any, allowedKeys): boolean => {
    if (allowedKeys.includes(event.key) && !event.shiftKey) return true;
    if (event.shiftKey && event.key === Key.Tab) return true;
    if (event.ctrlKey && event.key === Key.KeyA) return true;
    if (event.ctrlKey && event.key === Key.KeyC) return true;
    if (event.ctrlKey && event.key === Key.KeyX) return true;
    if (event.ctrlKey && event.key === Key.KeyV) return true;

    return false;
  };
}
