import { TranslateService } from '@ngx-translate/core';
import { IFieldOptions } from 'shared-code-lib';
import { IWebIntegrationOutbound, WebIntegrationOutbound } from './webintegration';

export interface IOutbound {
  faxHeader: string;
  attempts: number;
  attemptIntervalInMinutes: number;
  includeMessage: boolean;
  renderBackground: boolean;
  deleteAfter: boolean;
  rejectUnsupportedFiles: boolean;
  isPCI: boolean;
  defaults: IDefaults;
  notification: INotification;
  smtp: ISMTP;
  webIntegration: IWebIntegrationOutbound;
}

export class Outbound implements IOutbound {
  public faxHeader: string;
  public defaultCountry: string;
  public defaultAreaCode: string;
  public attempts: number;
  public attemptIntervalInMinutes: number;
  public includeMessage: boolean;
  public renderBackground: boolean;
  public deleteAfter: boolean;
  public rejectUnsupportedFiles: boolean;
  public isPCI: boolean;
  public defaults: Defaults;
  public notification: Notification;
  public smtp: SMTP;
  public webIntegration: WebIntegrationOutbound;

  constructor(o: IOutbound) {
    this.faxHeader = o ? o.faxHeader : '';
    this.attempts = o ? o.attempts : 3;
    this.attemptIntervalInMinutes = o ? o.attemptIntervalInMinutes : 5;
    this.includeMessage = o ? o.includeMessage : false;
    this.renderBackground = o ? o.renderBackground : false;
    this.deleteAfter = o ? o.deleteAfter : false;
    this.rejectUnsupportedFiles = o ? o.rejectUnsupportedFiles : true;
    this.notification = o ? new Notification(o.notification) : new Notification();
    this.smtp = o ? new SMTP(o.smtp) : new SMTP();
    this.webIntegration = o ? new WebIntegrationOutbound(o.webIntegration) : new WebIntegrationOutbound();
    this.defaults = o ? new Defaults(o.defaults) : new Defaults();
    this.isPCI = o ? o.isPCI : false;
  }

  serializable(): IOutbound {
    return {
      faxHeader: this.faxHeader,
      attempts: this.attempts,
      attemptIntervalInMinutes: this.attemptIntervalInMinutes,
      includeMessage: this.includeMessage,
      renderBackground: this.renderBackground,
      deleteAfter: this.deleteAfter,
      rejectUnsupportedFiles: this.rejectUnsupportedFiles,
      notification: this.notification.serializable(),
      smtp: this.smtp.serializable(),
      webIntegration: this.webIntegration.serializable(),
      defaults: this.defaults.serializable(),
      isPCI: this.isPCI,
    };
  }
}

export interface IDefaults {
  countryCode: string;
  areaCode: string;
  textCharsetEncoding: string;
  textFontType: string;
  textFontSize: number;
  pageSize: string;
  pageOrientation: string;
  pageResolution: string;
  pageRenderingQuality: string;
  pageScaling: string;
  renderingQuality: string;
  coverPageId: number;
}

export class Defaults {
  public countryCode: string;
  public areaCode: string;
  public textCharsetEncoding: string;
  public textFontType: string;
  public textFontSize: number;
  public pageSize: string;
  public pageOrientation: string;
  public pageResolution: string;
  public pageRenderingQuality: string;
  public pageScaling: string;
  public renderingQuality: string;
  public coverPageId: number;

  constructor(d: IDefaults = null) {
    this.countryCode = d ? d.countryCode : 'us';
    this.areaCode = d ? d.areaCode : '';
    this.textCharsetEncoding = d ? d.textCharsetEncoding : '';
    this.textFontType = d ? d.textFontType : '';
    this.textFontSize = d ? d.textFontSize : 2;
    this.pageSize = d ? d.pageSize : '';
    this.pageOrientation = d ? d.pageOrientation : '';
    this.pageResolution = d ? d.pageResolution : '';
    this.pageRenderingQuality = d ? d.pageRenderingQuality : '';
    this.pageScaling = d ? d.pageScaling : '';
    this.renderingQuality = d ? d.renderingQuality : '';
    this.coverPageId = d?.coverPageId;
  }

  serializable(): IDefaults {
    return {
      countryCode: this.countryCode,
      areaCode: this.areaCode,
      textCharsetEncoding: this.textCharsetEncoding,
      textFontType: this.textFontType,
      textFontSize: this.textFontSize,
      pageSize: this.pageSize,
      pageOrientation: this.pageOrientation,
      pageResolution: this.pageResolution,
      pageRenderingQuality: this.pageRenderingQuality,
      pageScaling: this.pageScaling,
      renderingQuality: this.renderingQuality,
      coverPageId: this.coverPageId,
    };
  }
}

export enum NotificationType {
  Never = 0,
  OnSuccessOnly = 1,
  OnFailureOnly = 2,
  Always = 3,
}
export enum Format {
  PlainText = 0,
  HtmlLocal = 1,
  HtmlEnglish = 2,
  XML = 3,
  CSV = 4,
  NEC = 5,
  HtmlLocalPlusStamped = 6,
}

export interface INotification {
  notificationType: NotificationType;
  format: Format;
  defaultReplyEmail: string;
  alwaysUseDefaultReplyEmail: boolean;
  includeAttachment: boolean;
}
export class Notification {
  public notificationType: NotificationType;
  public format: Format;
  public defaultReplyEmail: string;
  public alwaysUseDefaultReplyEmail: boolean;
  public includeAttachment: boolean;

  constructor(n: INotification = null) {
    this.notificationType = n ? n.notificationType : NotificationType.Never;
    this.format = n ? n.format : Format.HtmlLocal;
    this.defaultReplyEmail = n ? n.defaultReplyEmail : '';
    this.alwaysUseDefaultReplyEmail = n ? n.alwaysUseDefaultReplyEmail : false;
    this.includeAttachment = n ? n.includeAttachment : false;
  }

  serializable(): INotification {
    return {
      notificationType: this.notificationType,
      format: this.format,
      defaultReplyEmail: this.defaultReplyEmail,
      alwaysUseDefaultReplyEmail: this.alwaysUseDefaultReplyEmail,
      includeAttachment: this.includeAttachment,
    };
  }
}

export interface ISMTP {
  allowedSenders: Array<string>;
  authenticateBySMIME: boolean;
  authenticateByPassword: boolean;
}

export class SMTP {
  public allowedSenders: Array<string>;
  public authenticateBySMIME: boolean;
  public authenticateByPassword: boolean;

  constructor(s: ISMTP = null) {
    this.allowedSenders = s ? s.allowedSenders.map((as) => as) : [];
    this.authenticateByPassword = s ? s.authenticateByPassword : false;
    this.authenticateBySMIME = s ? s.authenticateBySMIME : false;
  }

  serializable(): ISMTP {
    return {
      allowedSenders: this.allowedSenders.map((as) => as),
      authenticateBySMIME: this.authenticateBySMIME,
      authenticateByPassword: this.authenticateByPassword,
    };
  }
}

export interface ICountry {
  code: string;
  name: string;
  timeZones: Array<string>;
}

export class Countries {
  public static getAsFieldOptions = (
    countries: Array<Country>,
    translateService: TranslateService
  ): IFieldOptions[] => {
    const options = new Array<IFieldOptions>();

    for (const c of countries) {
      options.push({
        name: translateService.instant(`Countries.${c.name.replace(/[^a-zA-Z0-9]/g, '')}`),
        value: c.code,
      });
    }

    options.sort((x, y) => x.name.localeCompare(y.name));
    return options;
  };
}

export class Country {
  public code: string;
  public name: string;
  public timeZones: Array<string>;

  constructor(c: ICountry) {
    this.code = c.code;
    this.name = c.name;
    this.timeZones = c.timeZones.map((tz) => tz);
  }
}

export interface ISupportedValues {
  countries: Array<Country>;

  defaultCountryCode: string;
  defaultCountryLocation: string;

  fonts: Array<string>;
  charsetEncodings: Array<string>;

  timeZones: Array<string>;
}

export class SupportedValues {
  public countries: Array<Country>;
  public fonts: Array<string>;
  public charsetEncodings: Array<string>;
  public defaultCountryCode: string;
  public defaultCountryLocation: string;
  public timeZones: Array<string>;

  constructor(sv: ISupportedValues = null) {
    this.countries = sv != null ? sv.countries.map((c) => new Country(c)) : [];
    this.fonts = sv != null ? sv.fonts.map((f) => f) : [];
    this.charsetEncodings = sv != null ? sv.charsetEncodings.map((ce) => ce) : [];
    this.defaultCountryCode = sv != null ? sv.defaultCountryCode : '';
    this.defaultCountryLocation = sv != null ? sv.defaultCountryLocation : '';
    this.timeZones = sv != null ? sv.timeZones.map((tz) => tz) : [];
  }
}

export interface ISelectedItemData {
  id: string;
  faxNumber: string;
  totalFaxesCount: number;
  failedFaxesCount: number;
}

export interface IResendFaxParameters {
  selectedItems: ISelectedItemData[];
  isBroadcast: boolean;
}
