import { Directive, ElementRef, Input } from '@angular/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { ResizeObserver as ResizeObserverPolyfill } from '@juggle/resize-observer';

const ResizeObserver = window.ResizeObserver || ResizeObserverPolyfill;

@Directive({
  selector: '[autoUpdatePerfectScroll]',
})
export class AutoUpdatePerfectScrollDirective {
  constructor(private _elementRef: ElementRef) {
    this.initEvents();
  }

  observer;

  @Input('autoUpdatePerfectScroll') perfectScroll: PerfectScrollbarDirective;

  initEvents = (): void => {
    const elements = this._elementRef.nativeElement.getElementsByTagName('*');
    const resizeObserver = new ResizeObserver(this.onResize);
    for (const element of elements) {
      resizeObserver.observe(element);
    }

    this.observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        if (!mutation.addedNodes.length && !mutation.removedNodes.length) continue;

        this.perfectScroll?.update();

        for (let i = 0; i < mutation.addedNodes.length; i++) {
          const node = mutation.addedNodes.item(i);
          if (!(node instanceof Element)) continue;
          resizeObserver.observe(node);
        }

        for (let i = 0; i < mutation.removedNodes.length; i++) {
          const node = mutation.removedNodes.item(i);
          if (!(node instanceof Element)) continue;
          resizeObserver.unobserve(node);
        }
      }
    });

    this.observer.observe(this._elementRef.nativeElement, {
      childList: true,
      subtree: true,
    });
  };

  onResize = (entries) => {
    for (const entry of entries) {
      if (!this._elementRef.nativeElement.contains(entry.target)) continue;

      this.perfectScroll?.update();
      break;
    }
  };

  ngOnDestroy() {
    this.observer?.disconnect();
  }
}
