import { AfterViewInit, Component, ElementRef, EventEmitter, Input, OnDestroy, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { cloneDeep, isEqual } from 'lodash';
import { DeviceDetectorService } from 'ngx-device-detector';
import { ToastrService } from 'ngx-toastr';
import { Subscription, fromEvent } from 'rxjs';
import { ICapture, IContourPoints, IPoint } from '../../models/scanner';
import { WebScannerService } from './../../services/web-scanner.service';

@Component({
  selector: 'app-crop-capture',
  templateUrl: './crop-capture.component.html',
  styleUrls: ['./crop-capture.component.scss'],
})
export class CropCaptureComponent implements OnInit, AfterViewInit, OnDestroy {
  private _capture: ICapture;

  @Input()
  get capture(): ICapture {
    return this._capture;
  }
  set capture(capture: ICapture) {
    this._capture = cloneDeep(capture);
  }

  @Output() cancel = new EventEmitter<void>();
  @Output() done = new EventEmitter<ICapture>();

  cropCanvas: HTMLCanvasElement;

  isPointDragging = {
    topLeft: false,
    topRight: false,
    bottomRight: false,
    bottomLeft: false,
  };

  capturedImageBoundaries: IContourPoints;

  get originalCaptureWidth() {
    return this.capture.originalImageBoundaries.topRight.x;
  }

  get originalCaptureHeight() {
    return this.capture.originalImageBoundaries.bottomRight.y;
  }

  get cropCanvasRectangleInUI() {
    return this.cropCanvas.getBoundingClientRect();
  }

  subscription = new Subscription();

  constructor(
    private scanner: WebScannerService,
    private elementRef: ElementRef,
    private deviceDetectorService: DeviceDetectorService,
    private toastr: ToastrService,
    private translate: TranslateService
  ) {}

  ngOnInit() {
    this.capturedImageBoundaries = cloneDeep(this.capture.capturedImageBoundaries);
  }

  ngAfterViewInit(): void {
    this.cropCanvas = this.elementRef.nativeElement.querySelector('canvas#crop-canvas');
    this.renderCropCanvas();
  }

  async renderCropCanvas() {
    await this.initScanner();
    const isTouchDevice = this.deviceDetectorService.isMobile() || this.deviceDetectorService.isTablet();
    this.addResizeCroppedAreaEvents(isTouchDevice);
    await this.scanner.renderImageToCrop(this.capture.originalImage, this.capturedImageBoundaries);
  }

  async initScanner() {
    await this.scanner.initScanner();
  }

  addResizeCroppedAreaEvents(isTouchDevice: boolean) {
    const cropCanvasContainer = this.elementRef.nativeElement.querySelector('.crop-canvas-container');
    if (!cropCanvasContainer || !this.cropCanvas) return;

    this.subscription.add(
      fromEvent(cropCanvasContainer, isTouchDevice ? 'touchstart' : 'mousedown').subscribe(
        (e: MouseEvent | TouchEvent) => {
          this.startDragging(e);
        }
      )
    );

    this.subscription.add(
      fromEvent(cropCanvasContainer, isTouchDevice ? 'touchmove' : 'mousemove').subscribe(
        (e: MouseEvent | TouchEvent) => {
          this.drag(e);
        }
      )
    );

    this.subscription.add(
      fromEvent(cropCanvasContainer, isTouchDevice ? 'touchend' : 'mouseup').subscribe((e: MouseEvent | TouchEvent) => {
        this.endDragging(e);
      })
    );
  }

  startDragging(event: MouseEvent | TouchEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.startPointDragging(this.getPositionRelativeToOriginalImage(event));
  }

  startPointDragging(newPosition: IPoint) {
    this.isPointDragging = {
      topLeft: false,
      topRight: false,
      bottomRight: false,
      bottomLeft: false,
    };

    const cropContext = this.cropCanvas.getContext('2d');

    cropContext.beginPath();
    cropContext.rect(
      this.capturedImageBoundaries.topLeft.x - this.scanner.circleRadius,
      this.capturedImageBoundaries.topLeft.y - this.scanner.circleRadius,
      this.scanner.circleRadius * 2,
      this.scanner.circleRadius * 2
    );

    if (cropContext.isPointInPath(newPosition.x, newPosition.y)) {
      this.isPointDragging.topLeft = true;
      return;
    }

    cropContext.beginPath();
    cropContext.rect(
      this.capturedImageBoundaries.topRight.x - this.scanner.circleRadius,
      this.capturedImageBoundaries.topRight.y - this.scanner.circleRadius,
      this.scanner.circleRadius * 2,
      this.scanner.circleRadius * 2
    );

    if (cropContext.isPointInPath(newPosition.x, newPosition.y)) {
      this.isPointDragging.topRight = true;
      return;
    }

    cropContext.beginPath();
    cropContext.rect(
      this.capturedImageBoundaries.bottomRight.x - this.scanner.circleRadius,
      this.capturedImageBoundaries.bottomRight.y - this.scanner.circleRadius,
      this.scanner.circleRadius * 2,
      this.scanner.circleRadius * 2
    );

    if (cropContext.isPointInPath(newPosition.x, newPosition.y)) {
      this.isPointDragging.bottomRight = true;
      return;
    }

    cropContext.beginPath();
    cropContext.rect(
      this.capturedImageBoundaries.bottomLeft.x - this.scanner.circleRadius,
      this.capturedImageBoundaries.bottomLeft.y - this.scanner.circleRadius,
      this.scanner.circleRadius * 2,
      this.scanner.circleRadius * 2
    );

    if (cropContext.isPointInPath(newPosition.x, newPosition.y)) {
      this.isPointDragging.bottomLeft = true;
    }
  }

  async drag(event: MouseEvent | TouchEvent) {
    event.preventDefault();
    event.stopPropagation();
    const position = this.getPositionRelativeToOriginalImage(event);

    if (
      !this.isPointDragging.topLeft &&
      !this.isPointDragging.topRight &&
      !this.isPointDragging.bottomRight &&
      !this.isPointDragging.bottomLeft
    )
      return;

    this.keepPositionInsideImage(position);
    this.updateBoundaries(position);
    await this.scanner.renderImageToCrop(this.capture.originalImage, this.capturedImageBoundaries);
  }

  keepPositionInsideImage(position: IPoint) {
    if (position.x < 0) position.x = 0;
    if (position.x > this.originalCaptureWidth) position.x = this.originalCaptureWidth;
    if (position.y < 0) position.y = 0;
    if (position.y > this.originalCaptureHeight) position.y = this.originalCaptureHeight;
  }

  updateBoundaries(newPosition: IPoint): void {
    if (this.isPointDragging.topLeft) {
      this.capturedImageBoundaries.topLeft = newPosition;
      return;
    }

    if (this.isPointDragging.topRight) {
      this.capturedImageBoundaries.topRight = newPosition;
      return;
    }

    if (this.isPointDragging.bottomRight) {
      this.capturedImageBoundaries.bottomRight = newPosition;
      return;
    }

    if (this.isPointDragging.bottomLeft) {
      this.capturedImageBoundaries.bottomLeft = newPosition;
    }
  }

  getPositionRelativeToOriginalImage(event: MouseEvent | TouchEvent): IPoint {
    const position =
      (event as TouchEvent).touches !== undefined
        ? this.getTouchPos(event as TouchEvent)
        : this.getMousePos(event as MouseEvent);

    const scale = (this.originalCaptureWidth + 2 * this.scanner.cropCanvasPadding) / this.cropCanvasRectangleInUI.width;
    position.x = position.x * scale - this.scanner.cropCanvasPadding;
    position.y = position.y * scale - this.scanner.cropCanvasPadding;

    return position;
  }

  getMousePos(event: MouseEvent): IPoint {
    return {
      x: event.pageX - this.cropCanvasRectangleInUI.left,
      y: event.pageY - this.cropCanvasRectangleInUI.top,
    };
  }

  getTouchPos(event: TouchEvent): IPoint {
    return {
      x: event.touches[0].pageX - this.cropCanvasRectangleInUI.left,
      y: event.touches[0].pageY - this.cropCanvasRectangleInUI.top,
    };
  }

  endDragging(event: MouseEvent | TouchEvent) {
    event.preventDefault();
    event.stopPropagation();

    this.isPointDragging = {
      topLeft: false,
      topRight: false,
      bottomRight: false,
      bottomLeft: false,
    };
  }

  onCancel() {
    this.cancel.emit();
  }

  async selectFullImage() {
    this.capturedImageBoundaries = cloneDeep(this.capture.originalImageBoundaries);
    await this.scanner.renderImageToCrop(this.capture.originalImage, this.capturedImageBoundaries);
  }

  async onConfirm() {
    const updatedCapture = cloneDeep(this.capture);

    if (isEqual(this.capturedImageBoundaries, this.capture.capturedImageBoundaries)) {
      this.done.emit(updatedCapture);
      return;
    }

    if (isEqual(this.capturedImageBoundaries, this.capture.originalImageBoundaries)) {
      updatedCapture.capturedImage = updatedCapture.originalImage;
      updatedCapture.capturedImageBoundaries = updatedCapture.originalImageBoundaries;
      this.done.emit(updatedCapture);
      return;
    }

    if (this.detectShapeLinesIntersections(this.capturedImageBoundaries) !== 4) {
      this.toastr.error(this.translate.instant('mobile-capture.edit-view.invalid-cropping'));
      return;
    }

    updatedCapture.capturedImageBoundaries = cloneDeep(this.capturedImageBoundaries);
    updatedCapture.capturedImage = (
      await this.scanner.extractCroppedDocument(this.capture.originalImage, updatedCapture.capturedImageBoundaries)
    ).image;
    this.done.emit(updatedCapture);
  }

  detectShapeLinesIntersections(points: IContourPoints): number {
    const lines = [
      [points.topLeft, points.topRight],
      [points.topRight, points.bottomRight],
      [points.bottomRight, points.bottomLeft],
      [points.bottomLeft, points.topLeft],
    ];

    const intersectionPoints = [];

    for (let i = 0; i < lines.length; i++) {
      for (let j = i + 1; j < lines.length; j++) {
        const intersectionResult = this.getLinesIntersection(lines[i][0], lines[i][1], lines[j][0], lines[j][1]);
        if (intersectionResult.linesOverlap) return Infinity;
        if (!intersectionResult.intersectionPoint) continue;

        intersectionPoints.push(intersectionResult.intersectionPoint);
      }
    }

    return intersectionPoints.length;
  }

  getLinesIntersection(
    p1: IPoint,
    p2: IPoint,
    p3: IPoint,
    p4: IPoint
  ): { intersectionPoint: IPoint; linesOverlap: boolean } {
    const denominator = (p4.y - p3.y) * (p2.x - p1.x) - (p4.x - p3.x) * (p2.y - p1.y);

    if (denominator === 0) {
      const isCollinear = (p2.x - p1.x) * (p3.y - p1.y) === (p3.x - p1.x) * (p2.y - p1.y);
      if (!isCollinear) {
        return {
          linesOverlap: false,
          intersectionPoint: null,
        };
      }

      const isBetween = (a, b, c) => Math.min(a, b) <= c && c <= Math.max(a, b);

      if (
        (isBetween(p1.x, p2.x, p3.x) && isBetween(p1.y, p2.y, p3.y)) ||
        (isBetween(p1.x, p2.x, p4.x) && isBetween(p1.y, p2.y, p4.y)) ||
        (isBetween(p3.x, p4.x, p1.x) && isBetween(p3.y, p4.y, p1.y)) ||
        (isBetween(p3.x, p4.x, p2.x) && isBetween(p3.y, p4.y, p2.y))
      ) {
        return {
          linesOverlap: true,
          intersectionPoint: null,
        };
      }

      return {
        linesOverlap: false,
        intersectionPoint: null,
      };
    }

    const ua = ((p4.x - p3.x) * (p1.y - p3.y) - (p4.y - p3.y) * (p1.x - p3.x)) / denominator;
    const ub = ((p2.x - p1.x) * (p1.y - p3.y) - (p2.y - p1.y) * (p1.x - p3.x)) / denominator;

    if (ua < 0 || ua > 1 || ub < 0 || ub > 1) {
      return {
        linesOverlap: false,
        intersectionPoint: null,
      };
    }

    return {
      linesOverlap: false,
      intersectionPoint: { x: p1.x + ua * (p2.x - p1.x), y: p1.y + ua * (p2.y - p1.y) },
    };
  }

  ngOnDestroy(): void {
    this.subscription.unsubscribe();
  }
}
