import { Component, Input, ViewEncapsulation, AfterViewInit, OnChanges } from '@angular/core';

@Component({
  selector: 'app-modal-default',
  templateUrl: './alert-default.component.html',
  styleUrls: ['./alert-default.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class AlertDefaultComponent implements AfterViewInit, OnChanges {
  @Input() title: string;
  @Input() message: string;
  @Input() autoClose: boolean = true;
  @Input() timeoutInSeconds: number = 10;
  @Input() onClose: Function;
  @Input() customClass: string = 'success-modal';
  @Input() identifier: string = 'successModal';
  @Input() buttonClass: string = 'btn-primary';
  @Input() buttonText: string;
  @Input() showIcon: Icons = Icons.None;
  autoCloseTimerInSeconds: number;
  autoCloseTimeString: string;
  modalInterval: any;
  timerIsRunning: boolean = false;

  Icons = Icons;

  get isIconRendered() {
    return this.showIcon !== Icons.None;
  }

  ngAfterViewInit() {
    if (this.autoClose) this.startTimer();
  }

  ngOnChanges(changes) {
    if (this.autoClose) this.startTimer();
  }

  startTimer = (): void => {
    if (this.timerIsRunning) return;
    this.timerIsRunning = true;
    if (this.autoClose) {
      this.autoCloseTimerInSeconds = this.timeoutInSeconds;
      this.setAutoCloseTimeString(this.autoCloseTimerInSeconds);
      this.autoCloseModal();
    }
  };

  close = (): void => {
    if (this.modalInterval) clearInterval(this.modalInterval);
    this.timerIsRunning = false;
  };

  dismissModalHandler = (): void => {
    this.close();
    this.autoCloseTimerInSeconds = this.timeoutInSeconds;
    this.setAutoCloseTimeString(this.autoCloseTimerInSeconds);
    if (this.onClose) this.onClose();
  };

  autoCloseModal() {
    if (this.modalInterval) clearInterval(this.modalInterval);
    this.modalInterval = setInterval(() => {
      if (this.autoCloseTimerInSeconds > 0) {
        this.autoCloseTimerInSeconds--;
        this.setAutoCloseTimeString(this.autoCloseTimerInSeconds);
      } else {
        this.dismissModalHandler();
      }
    }, 1000);
  }

  setAutoCloseTimeString(autoCloseTime: number) {
    if (autoCloseTime < 10) {
      this.autoCloseTimeString = '00:0' + autoCloseTime;
    } else {
      this.autoCloseTimeString = '00:' + autoCloseTime;
    }
  }
}

export enum Icons {
  None = 0,
  GreenTick = 1,
}
