import { AfterViewInit, Component, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { EnumDataSource, FieldDefinition, MetaDataType } from 'shared-code-lib';
import { CustomProperty, DocumentPropertyDataType } from '../../InterFAX/Models/admin';
import { InterFAXService } from '../../services/interfax.service';
import { ApiResultsResponsibleFolders } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-interfax-customproperty-modal',
  templateUrl: './interfax-customproperty-modal.component.html',
  styleUrls: ['./interfax-customproperty-modal.component.scss'],
})
export class InterfaxCustompropertyModalComponent implements OnInit, AfterViewInit {
  @ViewChild('spinnerElement', { static: true }) spinnerElement;
  @Output() closeModal = new EventEmitter();

  fieldType: FieldDefinition;
  fieldName: FieldDefinition;

  title: string;
  property: CustomProperty;

  show = false;
  errors = new Array<string>();
  isNewCustomProperty: boolean;

  get propertyType(): string {
    return `${this.property.type}`;
  }
  set propertyType(val: string) {
    this.property.type = Number(val);
  }
  get isDisabled(): boolean {
    return Boolean(this.property.id);
  }

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private interfaxService: InterFAXService,
    private toastrService: ToastrService,
    private userState: UserStateService
  ) {}

  ngOnInit(): void {
    this.createFields();

    const id = this.sharedDataService.extraParameters ? this.sharedDataService.extraParameters.id : '';

    if (id) {
      this.title = this.translateService.instant('custom-property.title-existing');
      this.spinnerService.show(this.translateService.instant('Common.Loading'), this.spinnerElement.nativeElement);
      this.interfaxService.getCustomProperty(id, this.propertyLoaded, this.propertyLoadFailed);
    } else {
      this.title = this.translateService.instant('custom-property.title-new');
      this.property = new CustomProperty();
      this.isNewCustomProperty = true;
    }
  }

  ngAfterViewInit() {
    if (this.isNewCustomProperty) this.show = true;
  }

  propertyLoaded = (cp: CustomProperty): void => {
    this.spinnerService.hide();
    this.property = cp;
    this.show = true;
  };

  propertyLoadFailed = (err: Error): void => {
    this.spinnerService.hide();
  };

  save = (): void => {
    if (!this.property.name.trim()) return;
    this.spinnerService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);
    this.interfaxService.setCustomProperty(this.property, this.saved, this.saveFailed);
  };

  saved = (r: ApiResultsResponsibleFolders): void => {
    this.spinnerService.hide();

    if (r.success) {
      this.toastrService.success(
        this.translateService.instant(
          this.property.id ? 'custom-property.update-success' : 'custom-property.saved-success'
        )
      );
      this.close();
      this.sharedDataService.actionHandler.reload.emit(false);
      this.userState.addToForceReloadFoldersIds(r.responsibleFoldersIds);
    } else {
      this.errors = r.errors;
    }
  };

  saveFailed = (err: Error): void => {
    this.spinnerService.hide();
    this.errors.push(err.message);
  };

  close = (): void => {
    this.show = false;
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  createFields = (): void => {
    const typeDataSource = new EnumDataSource(
      DocumentPropertyDataType,
      'DocumentPropertyDataTypeEnum',
      this.translateService
    );

    this.fieldType = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('custom-property.type'),
      required: true,
      datasource: typeDataSource,
    });

    this.fieldName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('custom-property.name'),
      placeholder: this.translateService.instant('custom-property.name-placeholder'),
      required: true,
    });
  };
}
