import {
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  OnInit,
  Output,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ParseResult } from 'ngx-papaparse';
import { ToastrService } from 'ngx-toastr';
import { FieldDefinition, FixedDataSource, IFieldOptions, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { CSVService } from '../../services/csv.service';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { Log } from '../../core/log';

@Component({
  selector: 'app-interfax-contactimport-modal',
  templateUrl: './interfax-contactimport-modal.component.html',
  styleUrls: ['./interfax-contactimport-modal.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class InterfaxContactimportModalComponent implements OnInit {
  @ViewChild('spinnerElement', { static: true })
  spinnerElement;
  @ViewChild('csvImportInput', { static: true })
  fileInputRef: ElementRef;

  fileInput: HTMLInputElement;

  base64FileData: string;
  containsHeader = false;
  replaceExisting = false;
  ignoreDuplicates = false;
  isPrivate = false;
  contactListName: string;

  fieldContactListName: FieldDefinition;
  fieldFaxNumber: FieldDefinition;
  fieldContactName: FieldDefinition;
  fieldCompany: FieldDefinition;
  fieldPhoneNumber: FieldDefinition;

  faxNumberDataSource: FixedDataSource;
  contactNameDataSource: FixedDataSource;
  companyDataSource: FixedDataSource;
  phoneNumberDataSource: FixedDataSource;

  indexFaxNumber = '-1';
  indexContactName = '-1';
  indexCompany = '-1';
  indexPhoneNumber = '-1';

  csvFile: File;
  csvParseResult: ParseResult;

  @Output() closeModal = new EventEmitter();

  isCreate = false;

  title: string;

  importErrors: string[] = [];
  parseErrors: string[] = [];

  get allErrors() {
    return [...this.parseErrors, ...this.importErrors];
  }

  get disableImport() {
    return !this.csvFile?.name || !!this.parseErrors?.length;
  }

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private toastr: ToastrService,
    private csvService: CSVService,
    private change: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.fileInput = this.fileInputRef.nativeElement;
    this.title = this.sharedDataService.action.name;
    this.faxNumberDataSource = new FixedDataSource();
    this.contactNameDataSource = new FixedDataSource();
    this.companyDataSource = new FixedDataSource();
    this.phoneNumberDataSource = new FixedDataSource();

    this.isCreate = '0' == this.sharedDataService.extraParameters.id;

    this.createFields();
  }

  save = (): void => {
    this.spinnerService.show(
      this.translateService.instant('contact-import-modal.importing'),
      this.spinnerElement.nativeElement
    );

    const items = [];
    const args = new MetaDataCollection();

    args.set('file', this.base64FileData);
    args.set('id', this.sharedDataService.extraParameters.id);
    args.set('indexFaxNumber', this.indexFaxNumber);
    args.set('indexContactName', this.indexContactName);
    args.set('indexCompany', this.indexCompany);
    args.set('indexPhoneNumber', this.indexPhoneNumber);
    args.set('containsHeader', this.containsHeader.toString());
    args.set('replaceExisting', this.replaceExisting.toString());
    args.set('ignoreDuplicates', this.ignoreDuplicates.toString());
    args.set('isPrivate', this.isPrivate.toString());
    args.set('contactListName', this.contactListName);

    this.importErrors = [];

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      items,
      args,
      this.onImportSucceeded,
      this.onImportFailed
    );
  };

  onImportFailed = (errors: any[]): void => {
    this.spinnerService.hide();
    console.log('onImportFailed', errors);

    this.importErrors = errors.map((e) => e);
  };

  onImportSucceeded = (): void => {
    this.spinnerService.hide();
    this.close();
    this.toastr.success(this.translateService.instant('csv.contact-list-imported-successfully'));
  };

  handleFileSelect = (evt: any): void => {
    if (this.fileInput.files.length == 0) return;

    this.readFile(this.fileInput.files[0]);

    this.csvFile = this.fileInput.files[0];
    this.parseCsvFile();
  };

  parseCsvFile() {
    if (!this.csvFile) return;

    this.parseErrors = [];
    this.csvService.parse(this.csvFile, this.containsHeader, this.onCSVParseSuccess, this.onCSVParseFailure);
  }

  onCSVParseSuccess = (result: ParseResult): void => {
    this.csvParseResult = result;
    this.parseErrors = result.errors.map((e) => e.message);

    if (!this.parseErrors.length && !this.csvParseResult.data.length) {
      this.parseErrors.push(this.translateService.instant('csv.invalid-empty-file'));
    }

    if (this.parseErrors.length) return;

    const importColumns = this.csvService.getColumns(this.csvParseResult, this.containsHeader);
    this.adjustSelectedColumns();
    this.updateColumnsDataSource(importColumns);
  };

  onCSVParseFailure = (err): void => {
    Log.error('InterfaxContactimportModalComponent.onCSVParseFailure', err);
    this.parseErrors = [this.translateService.instant('csv.parse-file-error')];
  };

  updateColumnsDataSource(importColumns: IFieldOptions[]) {
    const options = importColumns.map((o) => o);
    options.unshift({ name: this.translateService.instant('contact-import-modal.not-mapped'), value: '-1' });

    this.faxNumberDataSource.updateOptions(importColumns);
    this.companyDataSource.updateOptions(options);
    this.contactNameDataSource.updateOptions(options);
    this.phoneNumberDataSource.updateOptions(options);
  }

  onContainsHeaderChecked() {
    this.containsHeader = !this.containsHeader;
    this.parseCsvFile();
  }

  adjustSelectedColumns = (): void => {
    const firstRow = this.csvParseResult.data[0];
    const columnCount = Object.keys(firstRow).length;

    this.indexFaxNumber = this.indexFaxNumber || '0';
    this.indexContactName = this.indexContactName || columnCount > 1 ? '1' : '-1';
    this.indexCompany = this.indexCompany || columnCount > 2 ? '2' : '-1';
    this.indexPhoneNumber = this.indexPhoneNumber || columnCount > 3 ? '3' : '-1';

    this.change.detectChanges();
  };

  readFile = (file: File): void => {
    const reader = new FileReader();
    reader.onload = (event: any) => {
      this.base64FileData = event.target.result.split(',')[1];
    };

    reader.readAsDataURL(file);
  };

  close = (): void => {
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.close();
  };

  createFields = (): void => {
    this.fieldContactListName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('contact-import-modal.contact-list-name'),
      placeholder: this.translateService.instant('contact-import-modal.contact-list-name-placeholder'),
      required: true,
    });

    this.fieldFaxNumber = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('contact-import-modal.fax-number'),
      placeholder: '',
      datasource: this.faxNumberDataSource,
      required: true,
    });

    this.fieldContactName = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('contact-import-modal.contact-name'),
      placeholder: '',
      datasource: this.contactNameDataSource,
      required: false,
    });

    this.fieldCompany = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('contact-import-modal.company'),
      placeholder: '',
      datasource: this.companyDataSource,
      required: false,
    });

    this.fieldPhoneNumber = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('contact-import-modal.phone-number'),
      placeholder: '',
      datasource: this.phoneNumberDataSource,
      required: false,
    });
  };
}
