import { Subject } from 'rxjs';

import { MetaDataDefinition } from './../models/metadata-definition';
import { IFieldDataSource, IFieldOptions } from './field-definition';
import { IMetaDataService } from '../interop/MetaDataService';

export class MetaDataListDataSource implements IFieldDataSource {
  changed = new Subject<void>();
  itemsLoaded = new Subject<void>();

  getItemsRequestSent = false;
  loaded = false;
  loadedSuccessfully = false;
  loadingFailureError: any;
  items: Array<IFieldOptions> = [];

  constructor(private mdd: MetaDataDefinition, private metaDataService: IMetaDataService) {
    //TODO: terrible no good hack way to prepopluate - needs re-evaluation, there has to be a typesave way to do it
    const ds = <any>mdd.dataSource;
    if (ds.dataSet && ds.dataSet.length) {
      this.loaded = true;
      this.loadedSuccessfully = true;
      this.items = ds.dataSet;
    }
  }

  getItems(
    searchTerm: string,
    currentValue: string,
    successCallBack: (items: Array<IFieldOptions>) => void,
    failureCallBack: (err: any) => void
  ): void {
    if (this.loaded) {
      this.getLoadedItems(searchTerm, successCallBack, failureCallBack);
      return;
    }

    if (!this.getItemsRequestSent) {
      this.getItemsRequestSent = true;
      this.loadItems(searchTerm, successCallBack, failureCallBack);
    } else {
      this.itemsLoaded.subscribe(() => {
        this.getLoadedItems(searchTerm, successCallBack, failureCallBack);
        this.itemsLoaded.unsubscribe();
      });
    }
  }

  loadItems(
    searchTerm: string,
    successCallBack: (items: Array<IFieldOptions>) => void,
    failureCallBack: (err: any) => void
  ) {
    this.metaDataService.getMetaDataListItems(
      this.mdd.id,
      searchTerm,
      (items: Array<IFieldOptions>) => {
        this.items = items;
        this.loaded = true;
        this.loadedSuccessfully = true;
        this.itemsLoaded.next();
        successCallBack(this.getFilteredItems(searchTerm));
      },
      (err: any) => {
        this.loaded = true;
        this.loadedSuccessfully = false;
        this.loadingFailureError = err;
        this.itemsLoaded.next();
        failureCallBack(this.loadingFailureError);
      }
    );
  }

  getLoadedItems(
    searchTerm: string,
    successCallBack: (items: Array<IFieldOptions>) => void,
    failureCallBack: (err: any) => void
  ) {
    if (this.loadedSuccessfully) {
      successCallBack(this.getFilteredItems(searchTerm));
      return;
    }

    failureCallBack(this.loadingFailureError);
  }

  getFilteredItems(searchTerm: string): Array<IFieldOptions> {
    return this.items.filter((item) => item.name.toLocaleLowerCase().includes(searchTerm.toLocaleLowerCase()));
  }
}
