import { Component, OnInit, Input } from '@angular/core';
import { KeyboardActionMapping } from '../../core/keyboardActionMapping';
import { ActionService } from '../../services/action.service';
import { Action, ActionEvent } from '../../core/actions';
import { TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'app-action-button',
  templateUrl: './action-button.component.html',
  styleUrls: ['./action-button.component.scss'],
})
export class ActionButtonComponent implements OnInit {
  @Input() disabled = false;
  @Input() title = '';
  @Input() action: Action;
  @Input() image = '';
  @Input() extraClasses: string = '';

  constructor(private actionService: ActionService, private translate: TranslateService) {}

  ngOnInit() {}

  getKeyboardTip = (): string => {
    return KeyboardActionMapping.getTooltipFor(this.action, this.translate);
  };

  fireAction = (): void => {
    this.actionService.activateAction(new ActionEvent(this.action));
  };
}
