import { Component, OnInit, Input, Output, EventEmitter, AfterViewInit, OnDestroy } from '@angular/core';
import { NgxSmartModalService, NgxSmartModalComponent } from 'ngx-smart-modal';

@Component({
  selector: 'app-oauth-authorization-modal',
  templateUrl: './oauth-authorization-modal.component.html',
  styleUrls: ['./oauth-authorization-modal.component.scss'],
})
export class OauthAuthorizationModalComponent implements OnInit, AfterViewInit, OnDestroy {
  @Input() authorizationUrl: string;
  @Input() titleId: string;
  @Input() resourceName: string;
  @Output() onUpdated = new EventEmitter<URL>();
  @Output() onCancelled = new EventEmitter();

  private authorizationModal: NgxSmartModalComponent;

  constructor(
    private ngxSmartModal: NgxSmartModalService
  ) { }

  ngOnInit(): void { }

  ngAfterViewInit() {
    this.authorizationModal = this.ngxSmartModal.get('authorizationModal');
    this.authorizationModal.onClose.subscribe(() => {
      this.cancelAuthorizing();
    });

    this.authorizationModal.open();
  }

  ngOnDestroy() {
    this.authorizationModal.onClose.unsubscribe();
  }

  cancelAuthorizing = () => {
    this.onCancelled.emit();

    this.authorizationModal.close();
  };

  authorizeResource = () => {
    window.location.href = this.authorizationUrl;
  };
}
