import { Component, ElementRef, Input, OnDestroy, OnInit, ViewChild, ViewEncapsulation } from '@angular/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { Observable } from 'rxjs';

import { DelayService } from 'shared-code-lib';
import { Workflow } from '../../models/workflow';
import { WorkflowFolder } from '../../models/workflow-folder';
import { ActivityEventsService } from '../../services/activity-events-service';

declare const $: any;

class FolderSummary {
  public name: string;
  public total: number;
}

@Component({
  selector: 'app-capture-status',
  templateUrl: './capture-status.component.html',
  styleUrls: ['./capture-status.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class CaptureStatusComponent implements OnInit, OnDestroy {
  private onOpenDropDownSubscription: any;

  @Input() onOpenDropDown: Observable<void>;
  @Input() activityService: ActivityEventsService;
  @Input() headerText: string;
  @ViewChild('dropDownWrapper', { static: true }) dropDownWrapper: ElementRef;
  @ViewChild(PerfectScrollbarDirective, { static: true }) directiveRef?: PerfectScrollbarDirective;

  constructor(private delay: DelayService) {}

  ngOnInit() {
    this.onOpenDropDownSubscription = this.onOpenDropDown.subscribe(() => {
      this.delay.execute(() => {
        this.directiveRef.scrollToTop();
      }, 0);
    });
  }

  ngOnDestroy() {
    this.onOpenDropDownSubscription.unsubscribe();
  }

  getFolderSummaries = (workflow: Workflow): FolderSummary[] => {
    const summaries = [];

    const folders: WorkflowFolder[] = this.activityService.folders[workflow.id];
    if (folders == null) return summaries;

    for (const folder of folders) {
      const fs = new FolderSummary();

      fs.name = this.getName(workflow, folder.workflowStepId);
      fs.total = this.getTotal(folder.folders) + folder.itemCount;

      summaries.push(fs);
    }

    return summaries;
  };

  getTotalForWorkflow = (workflow: Workflow): number => {
    const folders: WorkflowFolder[] = this.activityService.folders[workflow.id];
    if (!folders) return 0;

    return this.getTotal(folders);
  };

  getName = (workflow: Workflow, id: string): string => {
    for (const step of workflow.workflowSteps) {
      if (step.id == id) return step.name;
    }

    return id;
  };

  getTotal = (folders: WorkflowFolder[]): number => {
    let total = 0;

    for (const folder of folders) {
      total += folder.itemCount;
      total += this.getTotal(folder.folders);
    }

    return total;
  };
}
