import { Component, OnInit, Output, EventEmitter } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { IItemId } from '../../core/itemActionHandler';
import { DeliveryFormat, DeliveryFormats, MetaDataCollection } from 'shared-code-lib';

@Component({
  selector: 'app-document-conversion',
  templateUrl: './document-conversion.component.html',
  styleUrls: ['./document-conversion.component.scss'],
})
export class DocumentConversionComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  formats: Array<Array<DeliveryFormat>>;

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService
  ) {}

  ngOnInit(): void {
    this.formats = DeliveryFormats.Categorized();
  }

  onFormatSelected = (selected: DeliveryFormat): boolean => {
    this.spinnerService.show(
      this.translateService.instant('document-conversion.submitting-conversion-request'),
      this.getSpinnerElement()
    );

    const items: IItemId[] = this.sharedDataService.extraParameters.items.map((i) => i.id);

    const args = new MetaDataCollection();
    args.set('final_form_code', selected.finalformcode);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      items,
      args,
      this.onDocumentConversionRequestSucceeded
    );

    return false;
  };

  onDocumentConversionRequestSucceeded = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  close = (): void => this.closeModal.emit();

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.accuroute-document-conversion-modal .nsm-content') as HTMLElement;
  }
}
