export class MongoObjectId {
  private static increment: number = 0;

  public static generate = (): string => {
    let t = Math.floor(new Date().valueOf() / 1000);
    let m = Math.floor(Math.random() * 16777216);
    let p = Math.floor(Math.random() * 65536);

    MongoObjectId.increment = MongoObjectId.increment++;
    if (MongoObjectId.increment > 0xffffff) {
      MongoObjectId.increment = 0;
    }

    var timestamp = t.toString(16);
    var machine = m.toString(16);
    var pid = p.toString(16);
    var increment = MongoObjectId.increment.toString(16);

    return (
      '00000000'.substr(0, 8 - timestamp.length) +
      timestamp +
      '000000'.substr(0, 6 - machine.length) +
      machine +
      '0000'.substr(0, 4 - pid.length) +
      pid +
      '000000'.substr(0, 6 - increment.length) +
      increment
    );
  };
}
