import { Injectable, ElementRef } from '@angular/core';
import { Strings } from './strings.service';

@Injectable({
  providedIn: 'root',
})
export class PathsService {
  constructor() {}

  public getFileExtension = (filePath: string): string => {
    if (Strings.isNullOrUndefined(filePath)) return '';
    if (filePath.indexOf('.') == -1) return '';

    const fileExtension = filePath.split('.').pop().toLocaleLowerCase();

    return fileExtension;
  };

  public getFileNameWithoutExtension = (filePath: string): string => {
    if (Strings.isNullOrUndefined(filePath)) return '';
    if (filePath.indexOf('.') == -1) return filePath;

    return filePath.split('.').slice(0, -1).join('.');
  };

  public changeFileExtension = (filePath: string, extension: string): string => {
    if (!extension.startsWith('.')) extension = '.' + extension;

    const updateFilePath = this.getFileNameWithoutExtension(filePath) + extension;

    return updateFilePath;
  };
}
