import { CapturedDocument } from '.';
import { WorkflowFolder } from '../../../blocks/models/workflow-folder';

export class SelectedItem {
  item: any;
  id: string;
  parentId: string;
  workflowStepId: string;
  type: SelectedItemType;
  pagesCount: number;

  constructor(
    item: any,
    id: string,
    parentId: string,
    workflowStepId: string,
    type: SelectedItemType,
    pagesCount: number
  ) {
    this.item = item;
    this.id = id;
    this.parentId = parentId;
    this.workflowStepId = workflowStepId;
    this.type = type;
    this.pagesCount = pagesCount;
  }

  static CreateFolderSelectedItem(folder: WorkflowFolder): SelectedItem {
    return this.Create(folder, folder.id, folder.parentID, folder.workflowStepId, SelectedItemType.Folder);
  }

  static CreateDocumentSelectedItem(document: CapturedDocument, pagesCount: number): SelectedItem {
    return this.Create(
      document,
      document.workitem.id,
      document.parentFolderId,
      document.parentStepId,
      SelectedItemType.Document,
      pagesCount
    );
  }

  private static Create(
    item: any,
    id: string,
    parentId: string,
    workflowStepId: string,
    type: SelectedItemType,
    pagesCount: number = 0
  ): SelectedItem {
    return new SelectedItem(item, id, parentId, workflowStepId, type, pagesCount);
  }
}

export enum SelectedItemType {
  Folder = 0,
  Document = 1,
}
