import { Attrs } from 'prosemirror-model';

export const commonAttributes = {
  id: { default: null },
  class: { default: null },
  style: { default: null },
};

export const domAttributes = (dom: HTMLElement): Attrs => {
  const result = {};
  const attributes = dom.attributes;

  for (let i = 0; i < attributes.length; i++) {
    result[attributes[i].name] = attributes[i].value;
  }

  return result;
};

export const hasAttrs = (attrs: Attrs, exclude?: any): boolean => {
  for (let attr in attrs) {
    if (attr && attrs[attr] !== null && attr !== exclude) return true;
  }

  return false;
};

export const pmAttributes = (attrs: Attrs, exclude = []): Attrs => {
  const result = {};

  for (let attr in attrs) {
    if (attr && attrs[attr] !== null && !exclude.find((e) => e === attr)) result[attr] = attrs[attr];
  }

  return result;
};
