import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root',
})
export class DocumentLastTouchedService {
  private _lastTouchedWorkItemId: string;
  private _lastTouchedRefCount: number = 0;
  private _lastTouchedFieldId: string;
  private _lastTouchedDocumentId: string;

  setLastTouchedWorkItem(workItemId: string) {
    if (!this._lastTouchedWorkItemId || this._lastTouchedWorkItemId !== workItemId) {
      this._lastTouchedWorkItemId = workItemId;
      this._lastTouchedRefCount = 0;
    }

    this._lastTouchedRefCount += 1;
  }

  resetLastTouchedWorkItem() {
    this._lastTouchedRefCount -= 1;
    if (this._lastTouchedRefCount <= 0) {
      this.clearLastTouchedWorkItem();
    }
  }

  clearLastTouchedWorkItem() {
    this._lastTouchedRefCount = 0;
    this._lastTouchedWorkItemId = null;
  }

  getLastTouchedWorkItemId(): string {
    return this._lastTouchedWorkItemId;
  }

  setLastTouchedField(fieldId: string) {
    if (!this._lastTouchedFieldId || this._lastTouchedFieldId !== fieldId) {
      this._lastTouchedFieldId = fieldId;
    }
  }

  clearLastTouchedField() {
    this._lastTouchedFieldId = null;
  }

  getLastTouchedField() {
    return this._lastTouchedFieldId;
  }

  setLastTouchedDocumentId(documentId: string) {
    if (!this._lastTouchedDocumentId || this._lastTouchedDocumentId !== documentId) {
      this._lastTouchedDocumentId = documentId;
    }
  }

  clearLastTouchedDocumentId() {
    this._lastTouchedDocumentId = null;
  }

  getLastTouchedDocumentId() {
    return this._lastTouchedDocumentId;
  }
}
