import { HubConnection } from '@microsoft/signalr';

export class HubConnectionOperations {
  private static tenMinutesInMilliseconds = 1000 * 60 * 10;

  static setTimeout(hubConnection: HubConnection) {
    hubConnection.serverTimeoutInMilliseconds = HubConnectionOperations.tenMinutesInMilliseconds;
  }

  static executeOnClose(hubConnection: HubConnection, func: Function) {
    hubConnection.onclose(() => {
      func();
    });
  }
}
