import { Component, OnInit, Output, EventEmitter, ViewEncapsulation } from '@angular/core';
import { SharedDataService } from '../../services/shared-data.service';
import { ApiService } from '../../services/api.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { TranslateService } from '@ngx-translate/core';
import { IItemId } from '../../core/itemActionHandler';
import { SpinnerState } from '../../services/models';
import { MetaDataCollection, ScanToFolderMobileAction } from 'shared-code-lib';

@Component({
  selector: 'app-onedrive-copyto',
  templateUrl: './onedrive-copyto.component.html',
  styleUrls: ['./onedrive-copyto.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class OnedriveCopytoComponent implements OnInit {
  action: ScanToFolderMobileAction;
  @Output() closeModal = new EventEmitter();

  folderId: string;

  constructor(
    public api: ApiService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private translateService: TranslateService
  ) {}

  ngOnInit(): void {
    this.action = this.sharedDataService.extraParameters.action;
  }

  onFolderSelected = (folderId: string): void => {
    this.folderId = folderId;
  };

  onFolderToggleBusy = (ss: SpinnerState): void => {
    if (ss.state) {
      this.spinnerService.show(this.translateService.instant('copy-to-onedrive.loading'), this.getSpinnerElement());
    } else {
      this.spinnerService.hide();
    }
  };

  close = (): void => {
    this.closeModal.emit();
  };

  copyto = (): void => {
    this.spinnerService.show(this.translateService.instant('copy-to-onedrive.copying'), this.getSpinnerElement());

    const items: IItemId[] = this.sharedDataService.extraParameters.items.map((i) => i.id);

    const args = new MetaDataCollection();
    args.set('folder-id', this.folderId);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      items,
      args,
      this.onCopyToSucceeded
    );
  };

  onCopyToSucceeded = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.onedrive-copyto-modal .nsm-content') as HTMLElement;
  }
}
