import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { SharedDataService } from '../../services/shared-data.service';

@Component({
  selector: 'app-interfax-contactus-modal',
  templateUrl: './interfax-contactus-modal.component.html',
  styleUrls: ['./interfax-contactus-modal.component.scss']
})
export class InterfaxContactusModalComponent implements OnInit {
  constructor(private sharedDataService: SharedDataService) { }

  @Output() closeModal = new EventEmitter();

  email = '';
  phone = '';

  ngOnInit(): void {
    this.email = this.sharedDataService.extraParameters.email;
    this.phone = this.sharedDataService.extraParameters.phone;
  }

  close = (): void => {
    this.closeModal.emit();
  };
}
