import { AfterViewInit, Component, EventEmitter, OnDestroy, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import { MetaDataType } from '../../../../../../../../../Bamba.Shared/src/models/metadata-definition';
import { ProductItemRefreshService } from '../../../../../blocks/services/product-item-refresh.service';
import { Template, VersionStatus } from '../../../models/template';
import { FieldDefinition } from './../../../../../../../../../Bamba.Shared/src/models/field-definition';
import { HydraApiService } from './../../../../../blocks/services/hydra-api.service';
import { ApiResult } from './../../../../../blocks/services/models';
import { SharedDataService } from './../../../../../blocks/services/shared-data.service';
import { SpinnerStateService } from './../../../../../blocks/services/spinner-state.service';
import { OlcTedPublicTemplateEditorService } from './../../template-editor/services/olc-ted-public-template-editor.service';

@Component({
  selector: 'app-request-approval-modal',
  templateUrl: './request-approval-modal.component.html',
  styleUrls: ['./request-approval-modal.component.scss'],
})
export class RequestApprovalModalComponent implements OnInit, AfterViewInit, OnDestroy {
  @Output() closeModal = new EventEmitter();

  createApprovalCommentField: FieldDefinition = new FieldDefinition();
  createApprovalComment = '';

  createApprovalModal: NgxSmartModalComponent;

  template: Template;

  templateId = '';
  versionId = '';

  subscriptions: Subscription[] = [];

  constructor(
    private translateService: TranslateService,
    private hydraApiService: HydraApiService,
    private templateEditorService: OlcTedPublicTemplateEditorService,
    private spinnerService: SpinnerStateService,
    private toastr: ToastrService,
    private ngxSmartModalService: NgxSmartModalService,
    private productItemRefreshService: ProductItemRefreshService,
    private sharedDataService: SharedDataService
  ) {}

  ngOnInit() {
    this.subscriptions.push(
      this.templateEditorService.template$.subscribe((template) => {
        this.template = template;
      })
    );

    this.createFields();

    this.templateId = this.sharedDataService.extraParameters?.templateId;
    this.versionId = this.sharedDataService.extraParameters?.versionId;
  }

  ngAfterViewInit(): void {
    this.createApprovalModal = this.ngxSmartModalService.get('createApprovalModal');
  }

  createFields() {
    this.createApprovalCommentField = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('admin-olc-menu.create-approval-comment-label'),
      placeholder: this.translateService.instant('admin-olc-menu.create-approval-comment-placeholder'),
      required: false,
    });
  }

  close = () => {
    this.closeModal.emit();
  };

  updateCreateApprovalComment(comment: string) {
    this.createApprovalComment = comment;
  }

  closeCreateApprovalModal = () => {
    this.close();
    this.createApprovalModal.close();
    this.createApprovalComment = '';
  };

  createApproval() {
    this.spinnerService.show(this.translateService.instant('admin-olc-menu.requesting-approval'), document.body);

    this.hydraApiService.requestApproval(
      this.templateId ? this.templateId : this.templateEditorService.templateID,
      this.versionId ? this.versionId : this.templateEditorService.versionId,
      { comment: this.createApprovalComment },
      this.createApprovalSuccess,
      this.createApprovalFailure
    );
  }

  createApprovalSuccess = (result: ApiResult) => {
    this.spinnerService.hide();

    if (!result.success) {
      this.toastr.error(result.errors[0]);
      return;
    }

    this.toastr.success(this.translateService.instant('admin-olc-menu.requesting-approval-succeeded'));

    this.closeCreateApprovalModal();

    this.productItemRefreshService.onRefresh.next();

    if (this.template) {
      const versionIndex = this.template.versions.findIndex(
        (v) => v.versionId === this.templateEditorService.versionId
      );

      if (versionIndex !== 1) this.template.versions[versionIndex].status = VersionStatus.PendingApproval;

      this.templateEditorService.setCurrentTemplate(this.template);
    }
  };

  createApprovalFailure = () => {
    this.spinnerService.hide();
    this.toastr.error(this.translateService.instant('admin-olc-menu.requesting-approval-failed'));
  };

  ngOnDestroy(): void {
    this.subscriptions.forEach((s) => s.unsubscribe());
  }
}
