import { AfterViewInit, Component, OnInit, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Params } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import {
  ImanageItem,
  IManageImportDocumentRequest,
  IMetaDataDefinition,
  MetaDataCollection,
  MetaDataValidity,
  MobileAction,
  MobileActionData,
  OverallValidityStatusChangedData,
  ValidationInProgressChangedData,
  WorkflowMobileAction,
} from 'shared-code-lib';
import { DocumentCaptureService } from '../../../views/document-capture/capture-services';
import { ErrorsService } from '../../services/errors.service';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResults } from '../../services/models';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { UserStateService } from '../../services/user-state.service';
declare var imanage: any;

@Component({
  selector: 'app-send-to-workflow',
  templateUrl: './send-to-workflow.component.html',
  styleUrls: ['./send-to-workflow.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class IManageSendToWorkflowComponent implements OnInit, AfterViewInit {
  actions: Array<MobileAction>;

  selectedDocument: ImanageItem;
  documentImported: boolean;

  metaDataModal: NgxSmartModalComponent;
  selectedAction: MobileAction;

  overallValidityStatus: MetaDataValidity = MetaDataValidity.unknown;
  metaDataCollection: MetaDataCollection = new MetaDataCollection();
  validationInprogress: boolean = false;
  waitForValidation: boolean = false;
  metadata: Array<IMetaDataDefinition> = [];

  workflowId: string;

  constructor(
    public userStateService: UserStateService,
    public hydraApi: HydraApiService,
    private errorService: ErrorsService,
    private translate: TranslateService,
    private spinner: SpinnerStateService,
    private ngxSmartModalService: NgxSmartModalService,
    public capture: DocumentCaptureService,
    private route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    const that = this;
    this.metadata = this.userStateService.user.metaData;
    imanage.ready().then(function (context) {
      const selectedEntity = context.selectedItems[0];
      that.selectedDocument = new ImanageItem(selectedEntity);
      if (that.workflowId) that.checkAutoSubmit();
    });

    this.getAvailableActionsForUser();

    this.route.params.subscribe((routeParams: Params) => {
      this.workflowId = routeParams.workflowid;
      if (this.workflowId) this.checkAutoSubmit();
    });
  }

  ngAfterViewInit(): void {
    this.metaDataModal = this.ngxSmartModalService.get('metaDataModal');
  }

  getAvailableActionsForUser = (): void => {
    this.actions = [];

    for (const product of this.userStateService.user.products) {
      for (const mobileAction of product.mobileActions) {
        if (!(mobileAction instanceof WorkflowMobileAction)) continue;

        this.actions.push(mobileAction);
      }
    }
  };

  checkAutoSubmit = (): void => {
    if (!this.selectedDocument || !this.workflowId) return;

    const action = this.actions.find((x) => x.id.endsWith(`@${this.workflowId}`));
    if (!action) return;

    this.onSubmitActionSelected(action);
  };

  onSubmitActionSelected = (action): void => {
    this.selectedAction = action;

    if (this.selectedAction.prompts.length > 0) {
      this.metaDataModal.open();
      return;
    }

    this.submitToWorkflow();
  };

  submitToWorkflow = (): void => {
    const actionData: MobileActionData = new MobileActionData();
    actionData.id = this.selectedAction.id;
    actionData.filename = this.selectedDocument.name;
    actionData.metadata = this.metaDataCollection;

    const importRequest = new IManageImportDocumentRequest(this.selectedDocument, actionData.serializable());

    this.spinner.show(this.translate.instant('imanage.importing-document'), document.documentElement);
    this.hydraApi.importIManageDocument(importRequest, this.importedSuccessfully, this.importFailed);
  };

  importedSuccessfully = (result: ApiResults) => {
    if (!result.success) {
      this.importFailed(result.errors);
      return;
    }

    this.documentImported = true;
    this.spinner.hide();
    if (this.metaDataModal.openedClass) this.metaDataModal.close();
  };

  importFailed = (err) => {
    this.errorService.showErrorsModal([err], this.translate.instant('imanage.import-failed'));
    this.spinner.hide();
  };

  close = (): void => {
    imanage.save({
      nextSteps: 'close',
    });
  };

  closeAndResetMetaDataModal() {
    this.resetMetaDataModal();
    this.metaDataModal.close();
  }

  resetMetaDataModal() {
    this.selectedAction = null;
    this.metaDataCollection = new MetaDataCollection();
    this.overallValidityStatus = MetaDataValidity.unknown;
  }

  setOverallValidityStatus(event: OverallValidityStatusChangedData) {
    this.overallValidityStatus = event.overallValidity;
    this.metaDataCollection = event.metaDataCollection;
  }

  updateValidationInProgressState(event: ValidationInProgressChangedData) {
    this.validationInprogress = event.inProgress;
    let isInitialValidation = event.isInitial;

    if (isInitialValidation) {
      if (this.validationInprogress) {
        this.spinner.show(this.translate.instant('workflow-indexing-panel.loading-defaults'), document.documentElement);
        return;
      } else {
        this.spinner.hide();
        return;
      }
    }

    if (!this.waitForValidation || this.validationInprogress) return;

    this.waitForValidation = false;
    this.spinner.hide();
    this.submitToWorkflow();
  }
}
