import { EventEmitter, Injectable } from '@angular/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { TranslateService } from '@ngx-translate/core';

@Injectable({
  providedIn: 'root',
})
export class ErrorsService {
  constructor(
    private ngxSmartModalService: NgxSmartModalService,
    private toastrService: ToastrService,
    private translate: TranslateService
  ) {}

  public closed = new EventEmitter<void>();

  showErrorsModal(errors: any, title: string): void {
    const data = {
      title: title,
      close: this.closeErrorsModal,
      errors,
    };
    this.ngxSmartModalService.setModalData(data, 'errorsModal', true);
    this.ngxSmartModalService.getModal('errorsModal').open();
  }

  closeErrorsModal = () => {
    this.ngxSmartModalService.getModal('errorsModal').close();
    this.ngxSmartModalService.resetModalData('errorsModal');

    this.closed.next();
  };

  showError(baseMessage: string, details: string) {
    this.toastrService.error(this.translate.instant(baseMessage) + details);
  }
}
