import { Component, EventEmitter, Input, Output, ViewEncapsulation } from '@angular/core';
import { cloneDeep } from 'lodash';
import { ICapture, IEditCapturesData } from './models/scanner';

@Component({
  selector: 'app-document-scanner-and-editor',
  templateUrl: './document-scanner-and-editor.component.html',
  styleUrls: ['./document-scanner-and-editor.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class DocumentScannerAndEditorComponent {
  private _captures: ICapture[] = [];

  @Input()
  get captures(): ICapture[] {
    return this._captures;
  }
  set captures(captures: ICapture[]) {
    this._captures = captures?.length ? cloneDeep(captures) : [];
  }

  @Output() close = new EventEmitter<void>();
  @Output() done = new EventEmitter<ICapture[]>();

  showDocumentScanner = true;
  showDocumentScannerEditor = false;

  captureIndexToEdit = 0;

  constructor() {}

  onClose() {
    this.close.emit();
  }

  onDone(captures: ICapture[]) {
    this.done.emit(captures);
  }

  onEditCapture(editCapturesData: IEditCapturesData) {
    this.captures = editCapturesData.captures;
    this.captureIndexToEdit = editCapturesData.indexToEdit;
    this.openDocumentScannerEditor();
  }

  openDocumentScanner() {
    this.showDocumentScanner = true;
    this.showDocumentScannerEditor = false;
  }

  openDocumentScannerEditor() {
    this.showDocumentScannerEditor = true;
    this.showDocumentScanner = false;
  }

  finishEditingCaptures(captures: ICapture[]) {
    this.captures = captures;
    this.openDocumentScanner();
  }
}
