import { Component, Input, OnInit } from '@angular/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { MetaDataCollection } from '../../../../../../../Bamba.Shared/src/models/metadata';
import { Filter } from '../../models/filter';
import { MultiSelectOptionActionResult } from '../../models/multi-select-option-action-result';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-multi-options-modal',
  templateUrl: './multi-options-modal.component.html',
  styleUrls: ['./multi-options-modal.component.scss'],
})
export class MultiOptionsModalComponent implements OnInit {
  @Input() data: MultiSelectOptionActionResult;
  modal: any;
  downloadAll: boolean;
  nothingSelected: boolean;

  constructor(
    private spinnerService: SpinnerStateService,
    private sharedDataService: SharedDataService,
    public ngxSmartModalService: NgxSmartModalService
  ) {}

  ngOnInit() {
    this.modal = this.ngxSmartModalService.getModal('multiSelectOptionModal');
    this.downloadAll = this.data.options.every((o) => o.selected);
  }

  close = () => {
    this.modal?.close();
  };

  selectAllChanged() {
    this.data.options.forEach((o) => (o.selected = this.downloadAll));
    this.nothingSelected = !this.downloadAll;
  }

  optionChanged() {
    this.downloadAll = this.data.options.every((o) => o.selected);
    this.nothingSelected = this.data.options.every((o) => !o.selected);
  }

  getSpinnerElement(): HTMLElement {
    return document.querySelector('.options .nsm-content') as HTMLElement;
  }

  download() {
    const args = new MetaDataCollection();
    for (let option of this.data.options) {
      args.set(option.id, option.selected.toString());
    }

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.data.extraParameters.ids,
      args,
      this.close,
      this.close,
      true,
      this.data.extraParameters.filters.map((x) => new Filter({ id: x.id, value: x.value }))
    );
  }
}
