import { Component, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { FieldDefinition, FixedDataSource, IFieldOptions, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { InterFAXUsernameDataSource } from '../../filters/filter-by-interfax-username/filter-by-interfax-username.component';
import { FaxUserStatus } from '../../InterFAX/Models/admin';
import { InterfaxDocumentSharingService } from '../../services/interfax-document-sharing.service';
import { InterFAXService } from '../../services/interfax.service';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-interfax-transfer-owner-modal',
  templateUrl: './interfax-transfer-owner-modal.component.html',
  styleUrls: ['./interfax-transfer-owner-modal.component.scss'],
})
export class InterfaxTransferOwnerModalComponent implements OnInit {
  @ViewChild('spinnerElement', { static: true })
  spinnerElement;

  @Output() closeModal = new EventEmitter();

  title: string;

  fieldUsers: FieldDefinition;
  transferToUser = '';

  fieldMessage: FieldDefinition;
  includeMessage = false;
  message = '';

  fieldRetainedAccess: FieldDefinition;
  retainAccessDataSource: FixedDataSource;
  retainedAccess = '-1';

  show = false;
  errors = new Array<string>();
  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private interfaxService: InterFAXService,
    private toastrService: ToastrService,
    private userStateService: UserStateService,
    private interfaxDocumentSharingService: InterfaxDocumentSharingService
  ) {}

  ngOnInit(): void {
    this.title = this.translateService.instant('interfax-queue.transfer-owner-title');

    this.createRetainAccessDataSource();

    this.show = true;
    this.createFields();
  }

  createRetainAccessDataSource = (): void => {
    const permissionTypes: IFieldOptions[] = [
      {
        name: this.translateService.instant('interfax-queue.transfer-owner-retain-access-none'),
        value: '-1',
      },
      ...this.interfaxDocumentSharingService.options,
    ];

    this.retainAccessDataSource = new FixedDataSource(permissionTypes);
  };

  save = (): void => {
    const mdc = new MetaDataCollection();

    mdc.set('owner', this.transferToUser);
    mdc.set('retainaccess', this.retainedAccess);
    if (this.includeMessage) mdc.set('message', this.message);

    this.spinnerService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.sharedDataService.extraParameters.ids,
      mdc,
      this.saved,
      this.saveFailed
    );
  };

  saved = (): void => {
    this.spinnerService.hide();
    this.toastrService.success(this.translateService.instant('interfax-queue.transfer-owner-success'));

    this.close();
  };

  saveFailed = (errs: any[]): void => {
    this.spinnerService.hide();
    this.errors = errs;
  };

  close = (): void => {
    this.show = false;
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  createFields = (): void => {
    this.fieldUsers = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('interfax-queue.transfer-owner-to-user'),
      placeholder: '',
      required: true,
      datasource: new InterFAXUsernameDataSource(
        this.interfaxService,
        this.translateService,
        this.userStateService,
        FaxUserStatus.Open,
        false
      ),
    });

    this.fieldMessage = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('interfax-queue.transfer-owner-message'),
      placeholder: '',
      required: false,
    });

    this.fieldRetainedAccess = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('interfax-queue.transfer-owner-retain-access'),
      placeholder: '',
      required: true,
      datasource: this.retainAccessDataSource,
    });
  };
}
