import { Injectable, isDevMode } from '@angular/core';

import { Subject } from 'rxjs';

import { ScanAppConnectionStatus } from '../capture-models';
import { InProgressService } from '../../../blocks/services/in-progress.service';
import { UserStateService } from '../../../blocks/services/user-state.service';
import {
  Command,
  ScanVersion,
  CancelResult,
  StatusResult,
  VersionResult,
  ProgressOpen,
  ScanPages,
  ScanPagesResult,
  ScanOptions,
  ActivateScanApp,
} from '../capture-models/scan-commands';
import { Log } from '../../../blocks/core/log';
import { TranslateService } from '@ngx-translate/core';
import { BrandingService } from 'shared-code-lib';
import { SpinnerStateService } from '../../../blocks/services/spinner-state.service';

@Injectable({
  providedIn: 'root',
})
export class ScanAppService {
  private _ws: WebSocket;
  private _connectionStatus: number;
  private documentScanned = new Subject<ScanPagesResult>();
  private scanCancelled = new Subject<CancelResult>();
  private _connectionChange = new Subject<string>();
  private transferDocument = new Subject<void>();
  private versionSectionCount: number = 4;

  onDocumentScanned = this.documentScanned.asObservable();
  onScanCancelled = this.scanCancelled.asObservable();
  onConnectionStatusChange = this._connectionChange.asObservable();
  onTransferDocument = this.transferDocument.asObservable();

  constructor(
    private inProgress: InProgressService,
    private userState: UserStateService,
    private translate: TranslateService,
    private brandingService: BrandingService,
    private spinner: SpinnerStateService
  ) {
    this._connectionStatus = ScanAppConnectionStatus.disconnected;
  }

  get connectionStatus() {
    return this._connectionStatus;
  }

  start(): void {
    Log.enter('ScanAppService.start', this._connectionStatus, isDevMode());

    try {
      if (this._connectionStatus === ScanAppConnectionStatus.disconnected) {
        this._connectionStatus = ScanAppConnectionStatus.connecting;

        const websocketAddress = 'ws://localhost:8181/';
        Log.var(websocketAddress);

        this._ws = new WebSocket(websocketAddress);

        this._ws.onmessage = (e) => {
          Log.enter('ws.onmessage');

          this.spinner.hide();

          const command = Command.create(JSON.parse(e.data));
          if (command == null) return;

          if (command instanceof CancelResult) {
            this.inProgress.close();
            this.scanCancelled.next(<CancelResult>command);
            return;
          }

          if (command instanceof ProgressOpen) {
            this.inProgress.open('app-scan.title-scan');
            this.inProgress.display(`app-scan.${(<ProgressOpen>command).status}`);
            this.transferDocument.next();
            return;
          }

          if (command instanceof StatusResult) {
            this.inProgress.display(`app-scan.${(<StatusResult>command).status}`);
            return;
          }

          if (command instanceof VersionResult) {
            if (this.isVersionCorrect((<VersionResult>command).version)) {
              this._connectionStatus = ScanAppConnectionStatus.connected;
            } else {
              this._connectionStatus = ScanAppConnectionStatus.needUpdate;
            }
            this._connectionChange.next(ScanAppConnectionStatus[this._connectionStatus]);
          }

          if (command instanceof ScanPagesResult) {
            this.inProgress.display('app-scan.scan-data-received');
            this.documentScanned.next(<ScanPagesResult>command);
          }
        };

        this._ws.onopen = () => {
          Log.enter('ws.onopen');

          this._connectionStatus = ScanAppConnectionStatus.checkingVersion;
          this.checkAppVersion();
          this._connectionChange.next(ScanAppConnectionStatus[this._connectionStatus]);
        };

        this._ws.onclose = () => {
          Log.enter('ws.onclose');

          this._connectionStatus = ScanAppConnectionStatus.disconnected;
          this._connectionChange.next(ScanAppConnectionStatus[this._connectionStatus]);
          this.spinner.hide(this.translate.instant('Common.ExecutingAction'));
        };

        this._ws.onerror = (ev: Event) => {
          this.spinner.hide(this.translate.instant('Common.ExecutingAction'));
          Log.enter('ws.onerror');
          Log.var(ev);

          Log.var(JSON.stringify(ev, ['message', 'arguments', 'type', 'name']));
        };
      }
    } catch (e) {
      this._connectionStatus = ScanAppConnectionStatus.disconnected;
      this.spinner.hide(this.translate.instant('Common.ExecutingAction'));
      Log.error('ScanAppService.start', e);
    }
  }

  private send = (command: Command, waitingResponse = true): void => {
    this._ws.send(JSON.stringify(command));

    if (waitingResponse) this.spinner.show(this.translate.instant('Common.ExecutingAction'), document.documentElement);
  };

  checkAppVersion(): void {
    if (this._connectionStatus === ScanAppConnectionStatus.checkingVersion) {
      this.send(new ScanVersion());
    }
  }

  scan(startscan: ScanPages): void {
    if (!startscan.scanOptions) startscan.scanOptions = new ScanOptions(this.translate.currentLang, true);
    startscan.brandDetails = this.brandingService.getBrandDetails();
    this.send(startscan);
  }

  activate = (): void => {
    this.send(new ActivateScanApp());
  };

  isVersionCorrect(version: string): boolean {
    if (isDevMode()) {
      return true;
    }

    const scanAppVersion = version.split('.');
    const minimumScanAppVersion = this.userState.userProfile.minimumVersion.split('.');

    return this.versionMeetsMinimum(scanAppVersion, minimumScanAppVersion);
  }

  versionMeetsMinimum(versionA: Array<string>, versionB: Array<string>): boolean {
    if (!this.verifyVersionFormat(versionA) || !this.verifyVersionFormat(versionB)) {
      return false;
    }

    for (let i = 0; i < this.versionSectionCount - 1; i++) {
      if (parseInt(versionA[i]) < parseInt(versionB[i])) {
        return false;
      } else if (parseInt(versionA[i]) > parseInt(versionB[i])) {
        return true;
      }
    }

    return true;
  }

  verifyVersionFormat(version: Array<string>): boolean {
    return version && version.length === this.versionSectionCount;
  }

  closeInProgress() {
    this.inProgress.close();
  }
}
