import { Node, NodeSpec } from '@progress/kendo-angular-editor';

import { commonAttributes, domAttributes, hasAttrs, pmAttributes } from './utills';
import { TemplateStyle } from './../../../../views/admin-olc/models/template';

export const createBlockStyleNode = (style: TemplateStyle): NodeSpec => {
  return {
    content: 'inline*',
    group: 'block',
    attrs: commonAttributes,
    parseDOM: [
      {
        tag: `${style.element.trim()}${style.inlineStyles.length ? `[style]` : ''}${
          style.classes?.trim() ? `[class]` : ''
        }`,
        getAttrs: domAttributes,
        priority: 0,
      },
    ],
    toDOM: (node: Node) =>
      hasAttrs(node.attrs) ? [style.element.trim(), pmAttributes(node.attrs), 0] : [style.element.trim(), 0],
  };
};

export const createOlcVariableNode = (): NodeSpec => {
  return {
    content: 'text{0,1}',
    group: 'inline',
    marks: '',
    inline: true,
    atom: true,
    selectable: true,
    attrs: {
      ...commonAttributes,
      'data-variable': { default: null },
      contenteditable: { default: null },
    },
    parseDOM: [
      {
        tag: 'span[data-variable]',
        getAttrs: domAttributes,
        priority: 200,
      },
    ],
    toDOM: (node: Node) => (hasAttrs(node.attrs) ? ['span', pmAttributes(node.attrs), 0] : ['span', 0]),
  };
};

export const createOlcConditionalContentNode = (className): NodeSpec => {
  return {
    content: 'text{0,1}',
    group: 'block',
    marks: '',
    atom: true,
    selectable: true,
    isolating: true,
    isConditionalContent: true,
    attrs: {
      id: { default: null },
      class: { default: className },
      style: { default: 'user-select: all;' },
      contenteditable: { default: 'false' },
    },
    parseDOM: [
      {
        tag: `p.${className}[contenteditable="false"]`,
        getAttrs: () => ({ class: className, style: 'user-select: all;', contenteditable: 'false' }),
        priority: 200,
      },
    ],
    toDOM: (node: Node) => (hasAttrs(node.attrs) ? ['p', pmAttributes(node.attrs), 0] : ['p', 0]),
  };
};

export const updatedListItem: NodeSpec = {
  content: `block*`,
  attrs: commonAttributes,
  parseDOM: [
    {
      tag: 'li',
      getAttrs: domAttributes,
    },
  ],
  toDOM: (node: Node) => (hasAttrs(node.attrs) ? ['li', pmAttributes(node.attrs), 0] : ['li', 0]),
  defining: true,
};

