export const updatedImageNode: NodeSpec = {
  inline: true,
  attrs: Object.assign(
    {
      src: { default: null },
      alt: { default: null },
      title: { default: null },
      width: { default: null },
      height: { default: null },
      pdfurl: { default: null },
    },
    commonAttributes
  ),
  group: 'inline',
  draggable: true,
  parseDOM: [
    {
      tag: 'img',
      getAttrs: domAttributes,
    },
  ],
  toDOM: (node) => (hasAttrs(node.attrs) ? ['img', pmAttributes(node.attrs)] : ['img']),
};
