export interface IBrand {
  id: string;
  tenantId: string;
  siteName: string;
  description: string;
  primaryLogoUrl: string;
  secondaryLogoUrl: string;
  favIconUrl: string;
  primaryColor: string;
  replyEmail: string;
  helpURL: string;
  privacyPolicyURL: string;
  domains: Array<string>;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
}

export class Brand implements IBrand {
  public id: string;
  public tenantId: string;
  public siteName: string;
  public description: string;
  public primaryLogoUrl: string;
  public secondaryLogoUrl: string;
  public favIconUrl: string;
  public primaryColor: string;
  public replyEmail: string;
  public helpURL: string;
  public privacyPolicyURL: string;
  public domains: Array<string>;
  public dateCreatedUTC: Date;
  public dateModifiedUTC: Date;

  constructor(initializer: IBrand) {
    this.id = initializer.id;
    this.tenantId = initializer.tenantId;
    this.siteName = initializer.siteName;
    this.description = initializer.description;
    this.primaryLogoUrl = initializer.primaryLogoUrl;
    this.secondaryLogoUrl = initializer.secondaryLogoUrl;
    this.favIconUrl = initializer.favIconUrl;
    this.primaryColor = initializer.primaryColor;
    this.replyEmail = initializer.replyEmail;
    this.helpURL = initializer.helpURL;
    this.privacyPolicyURL = initializer.privacyPolicyURL;
    this.domains = initializer.domains;
    this.dateCreatedUTC = initializer.dateCreatedUTC;
    this.dateModifiedUTC = initializer.dateModifiedUTC;
  }

  serializable = (): IBrand => {
    return {
      id: this.id,
      tenantId: this.tenantId,
      siteName: this.siteName,
      description: this.description,
      primaryLogoUrl: this.primaryLogoUrl,
      secondaryLogoUrl: this.secondaryLogoUrl,
      favIconUrl: this.favIconUrl,
      primaryColor: this.primaryColor,
      replyEmail: this.replyEmail,
      helpURL: this.helpURL,
      privacyPolicyURL: this.privacyPolicyURL,
      domains: this.domains,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
    };
  };
}
