import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { IFieldOptions } from 'shared-code-lib';
import { SharePermissions } from '../InterFAX/Models/inbound';

@Injectable({
  providedIn: 'root',
})
export class InterfaxDocumentSharingService {
  get options(): IFieldOptions[] {
    return [
      {
        name: this.translateService.instant('admin-inbound-fax-settings.permission-view'),
        value: `${SharePermissions.View}`,
      },
      {
        name: this.translateService.instant('admin-inbound-fax-settings.permission-view-edit'),
        value: `${SharePermissions.View | SharePermissions.Edit}`,
      },
      {
        name: this.translateService.instant('admin-inbound-fax-settings.permission-view-share'),
        value: `${SharePermissions.View | SharePermissions.Share}`,
      },
      {
        name: this.translateService.instant('admin-inbound-fax-settings.permission-view-edit-share'),
        value: `${SharePermissions.View | SharePermissions.Edit | SharePermissions.Share}`,
      },
    ];
  }

  constructor(private translateService: TranslateService) {}
}
