import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class DeviceFilterByColumn extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByDeviceColumnComponent';
  }
}

export class DeviceFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('DeviceFilters.Create', filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.Devices.Filters.FilterByDeviceColumn')
      return new DeviceFilterByColumn(filter);

    return null;
  };
}
