import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  HostListener,
  Input,
  OnDestroy,
  OnInit,
  Output,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { TagInputComponent } from 'ngx-chips';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { Observable, Subscription, delay } from 'rxjs';
import {
  ContactList,
  ContactListIds,
  ContactListRecipient,
  ContactListSearchType,
  FieldDefinition,
  FixedDataSource,
  IFieldOptions,
  IInterFAXService,
  ISpinnerService,
  Individual,
  Key,
  MetaDataType,
  OpenDropdownDirective,
  Recipient,
  RecipientContainer,
  RecipientTypes,
  RolePermissions,
  SendFaxRecipientType,
  SessionStorageService,
  recipientDialogState,
} from 'shared-code-lib';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';

@Component({
  selector: 'app-fax-recipients',
  templateUrl: './fax-recipients.component.html',
  styleUrls: ['./fax-recipients.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class FaxRecipientsComponent implements OnInit, AfterViewInit, OnDestroy {
  @Input() validateForm: () => void;
  @Input() chipText: string;
  @Input() recipients: RecipientContainer<Recipient>[];
  @Input() title: string = 'fax-action.label-faxnumber';
  @Input() spinnerService: ISpinnerService;
  @Input() interfaxService: IInterFAXService;
  @Input() allowModals: boolean = true;
  @Input() contactLists: Array<ContactList>;
  @Input() showSendAfterContactListsWarningToast: boolean = true;

  @Output() onRecipientAdded = new EventEmitter<Recipient>();
  @Output() onRecipientRemoved = new EventEmitter<Recipient>();
  @Output() onChanged = new EventEmitter<RecipientContainer[]>();

  @ViewChild(TagInputComponent) tagInput: TagInputComponent;
  @ViewChild(OpenDropdownDirective) openDropdownDirective: OpenDropdownDirective;

  recipient: RecipientTypes | any = new Individual('', '', '', '');

  individualRecipientModalInstance: NgxSmartModalComponent;
  recipientModalErrors: string[] = [];

  interfaxContactListModal: NgxSmartModalComponent;
  searchContactsModal: NgxSmartModalComponent;

  showIndividualRecipientModalBody = false;

  fieldContactName: FieldDefinition;
  fieldFaxNumber: FieldDefinition;
  fieldSaveToContactList: FieldDefinition;

  dialogState = recipientDialogState.New;
  selectedContactLists: Array<ContactList> = [];
  supportContactLists = false;

  showContactListModal = false;
  showSearchContactsModal = false;

  dropdownSelectedItemIndex = -1;
  dropdownListItems = [
    {
      text: 'SendFax-Details-Form.Recipient',
      onClick: () => this.onAddIndividual(),
    },
    {
      text: 'SendFax-Details-Form.ContactList',
      onClick: () => this.onAddContactList(),
    },
  ];

  individualRecipientModalTitle: string;

  allMembers: RecipientContainer<Individual>[];
  filteredMembers: RecipientContainer<Individual>[];
  autoCompleteItems: RecipientContainer<Individual>[] = [];

  isFaxMobile = false;

  firstAutoCompleteSuggestion: RecipientContainer<Individual> = null;
  ngTagTextInput: HTMLInputElement;
  tagInputMaxLength = 20;

  private subscriptions = new Subscription();

  constructor(
    private translate: TranslateService,
    private ngxSmartModalService: NgxSmartModalService,
    private userStateService: UserStateService,
    private toastr: ToastrService,
    private sessionStorageService: SessionStorageService,
    private elementRef: ElementRef
  ) {}

  getAutoCompleteSuggestionsObservable = (searchQuery: string): Observable<RecipientContainer<Individual>[]> => {
    return new Observable<RecipientContainer<Individual>[]>((subscriber) => {
      searchQuery = searchQuery.trim();
      if (!searchQuery) {
        this.firstAutoCompleteSuggestion = null;
        subscriber.next([]);
        subscriber.complete();
        return;
      }

      this.interfaxService.searchContactLists(
        searchQuery,
        ContactListSearchType.Auto,
        ContactListIds.Any,
        (contacts) => {
          const mapped: RecipientContainer<Individual>[] = contacts.map((c) => {
            const individual = new Individual(
              c.name,
              c.faxNumber,
              c.company,
              c.phoneNumber,
              c.contactListId,
              c.id,
              c.contactListId
            );
            return { display: individual.getDisplayName(), value: individual };
          });

          this.firstAutoCompleteSuggestion = mapped[0] || null;
          subscriber.next(mapped);
          subscriber.complete();
        },
        (err) => {
          subscriber.next([]);
          subscriber.error(err);
          subscriber.complete();
        }
      );
    });
  };

  matchingFn = (val: string, target: { display: string; value: Individual }) => true;

  ngOnInit(): void {
    this.isFaxMobile = this.sessionStorageService.getIsInterFaxMobile();
    this.subscriptions.add(
      this.sessionStorageService.onIsInterFaxMobileChanged.subscribe((x) => (this.isFaxMobile = x))
    );
    this.createFields();

    this.supportContactLists =
      !this.userStateService.hasRolePermission(RolePermissions.INTERFAX_PCI) &&
      this.userStateService.hasRolePermission(RolePermissions.INTERFAX_PERMISSIONS_ALLOWCONTACTLISTS);
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  @HostListener('document:click', ['$event'])
  onDocumentClick(event: PointerEvent) {
    if (event?.target === this.ngTagTextInput) return;

    this.addNewRecipientTag();
  }

  addNewRecipientTag(): void {
    const value = (this.tagInput.inputForm as any).item.value;
    if (!value?.trim()) return;

    const newRecipient = new Individual('', value, '', '', '');
    this.recipients.push({ display: value, value: newRecipient });
    this.tagInput.setInputValue('');

    this.onRecipientAdded.emit(newRecipient);
    this.changed();
  }

  tabHandler(): void {
    this.hideTagInputDropdown();
  }

  hideTagInputDropdown = () => {
    if (!this.tagInput.dropdown.isVisible) return;

    const ng2DropdownBackdrop = document.querySelector('.ng2-dropdown-backdrop') as HTMLElement;
    if (!ng2DropdownBackdrop) return;

    ng2DropdownBackdrop.click();
  };

  onButtonKeyDown = (e: KeyboardEvent): void => {
    if (e.key == Key.ArrowUp) {
      this.dropdownSelectedItemIndex--;
      if (this.dropdownSelectedItemIndex < 0) this.dropdownSelectedItemIndex = this.dropdownListItems.length - 1;
    } else if (e.key == Key.ArrowDown) {
      this.dropdownSelectedItemIndex++;
      if (this.dropdownSelectedItemIndex == this.dropdownListItems.length) this.dropdownSelectedItemIndex = 0;
    } else if (e.key == Key.Enter) {
      this.dropdownListItems[this.dropdownSelectedItemIndex].onClick();
      this.openDropdownDirective.hide();
    }
  };

  onMouseOver = (itemIndex: number): void => {
    this.dropdownSelectedItemIndex = itemIndex;
  };

  resetDropdownSelectedItem(): void {
    this.dropdownSelectedItemIndex = -1;
  }

  createFields = (): void => {
    this.fieldFaxNumber = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('SendFax-Details-Form.FaxNumber'),
      placeholder: this.translate.instant('SendFax-Details-Form.EnterNumber'),
      required: true,
    });

    this.fieldContactName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('SendFax-Details-Form.ContactName'),
      placeholder: this.translate.instant('SendFax-Details-Form.EnterName'),
      required: false,
    });
  };

  setupSaveToContactListField = (): void => {
    const { recipient } = this;
    if (!(recipient instanceof Individual)) return;

    const contactListOptions = new Array<IFieldOptions>();
    contactListOptions.push({ name: this.translate.instant('SendFax-Details-Form.contact-list-none'), value: '' });

    this.contactLists
      .filter((cl) => cl.id == recipient.contactListId)
      .forEach((cl) =>
        contactListOptions.push({
          name: `${this.translate.instant('SendFax-Details-Form.update-contact-in-list')}`.replace(
            '{contactListName}',
            cl.name
          ),
          value: cl.id,
        })
      );

    this.contactLists
      .filter((cl) => cl.id != recipient.contactListId)
      .sort((a, b) => a.name.localeCompare(b.name))
      .forEach((cl) => contactListOptions.push({ name: cl.name, value: cl.id }));

    this.fieldSaveToContactList = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translate.instant('SendFax-Details-Form.SaveToContactList'),
      placeholder: '',
      required: false,
      datasource: new FixedDataSource(contactListOptions),
    });
  };

  ngAfterViewInit(): void {
    this.individualRecipientModalInstance = this.ngxSmartModalService.getModal('individualRecipientModal');
    this.subscriptions.add(
      this.individualRecipientModalInstance.onClose.subscribe(() => {
        this.showIndividualRecipientModalBody = false;
      })
    );

    this.interfaxContactListModal = this.ngxSmartModalService.getModal('interfaxContactListModal');
    this.subscriptions.add(this.interfaxContactListModal.onClose.subscribe(() => (this.showContactListModal = false)));

    this.searchContactsModal = this.ngxSmartModalService.getModal('searchContactsModal');
    this.subscriptions.add(this.searchContactsModal.onClose.subscribe(() => (this.showSearchContactsModal = false)));

    this.subscriptions.add(
      this.tagInput.dropdown.dropdown.onShow.pipe(delay(50)).subscribe(() => {
        const firstDropdownMenuItem = document.querySelector('.ng2-menu-item') as HTMLDivElement;
        if (!firstDropdownMenuItem) return;

        firstDropdownMenuItem.classList.add('ng2-menu-item--selected');
      })
    );

    this.ngTagTextInput = this.elementRef.nativeElement.querySelector('.ng2-tag-input__text-input') as HTMLInputElement;
    this.ngTagTextInput.maxLength = this.tagInputMaxLength;
  }

  addRecipient = (recipient: Recipient): void => {
    this.recipients.push({ display: recipient.getDisplayName(), value: recipient });
    this.onRecipientAdded.emit(recipient);
    this.changed();
  };

  onAddRecipient = (recipientType: SendFaxRecipientType): void => {
    this.dialogState = recipientDialogState.New;

    switch (recipientType) {
      case SendFaxRecipientType.ContactList:
        this.recipient = new ContactListRecipient('', '');
        this.openRecipientListModal();
        break;

      case SendFaxRecipientType.Recipient:
        this.recipient = new Individual('', '', '', '', '');
        this.openIndividualRecipientModal();
        break;
    }
  };

  onAddIndividual(): void {
    this.onAddRecipient(SendFaxRecipientType.Recipient);
  }

  onAddContactList(): void {
    this.onAddRecipient(SendFaxRecipientType.ContactList);
  }

  openSearchContactsModal = (): void => {
    this.searchContactsModal.open();
    this.showSearchContactsModal = true;
  };

  openIndividualRecipientModal(): void {
    this.recipientModalErrors = [];
    this.setupSaveToContactListField();

    if (this.dialogState == recipientDialogState.New) {
      this.individualRecipientModalTitle = this.translate.instant('SendFax-Details-Form.AddRecipient');
    } else {
      this.individualRecipientModalTitle = this.translate.instant('SendFax-Details-Form.RecipientProperties');
    }

    this.showIndividualRecipientModalBody = true;
    this.individualRecipientModalInstance.open();
  }

  closeIndividualRecipientModal = (): void => {
    this.individualRecipientModalInstance.close();
  };

  openRecipientListModal(): void {
    this.showContactListModal = true;
    this.selectedContactLists = new Array<ContactList>();
    this.interfaxContactListModal.open();
  }

  closeContactListModal(): void {
    this.interfaxContactListModal.close();
  }

  saveContactListModal(contacts: Array<ContactList>): void {
    this.closeContactListModal();

    contacts.forEach((contactList) => {
      const cl = new ContactListRecipient(contactList.name, contactList.id);
      this.addRecipient(cl);
    });

    if (this.showSendAfterContactListsWarningToast) {
      this.toastr.warning(this.translate.instant('SendFax.SendFaxAfterDisabled'));
    }
  }

  onCloseSearchContactsModal = (): void => {
    this.searchContactsModal.close();
  };

  onSaveSearchContactsModal = (newRecipients: RecipientContainer<Individual>[]): void => {
    this.searchContactsModal.close();
    this.showSearchContactsModal = false;

    this.recipients = [...this.recipients, ...newRecipients];

    this.changed();
  };

  validateRecipientModal = (): string[] => {
    const errors: string[] = [];

    if (this.recipient?.faxnumber?.trim() == '') {
      errors.push(this.translate.instant('contact-list.faxNumber-placeholder'));
    }

    return errors;
  };

  onSaveRecipient = (): void => {
    this.recipientModalErrors = this.validateRecipientModal();
    if (this.recipientModalErrors.length) return;

    if (this.dialogState === recipientDialogState.New) {
      this.addRecipient(this.recipient);
    } else {
      this.recipients.forEach((recipient) => {
        if (recipient.value.id === this.recipient.id) {
          if (recipient.value instanceof ContactList) return;
          recipient.value.copyFrom(this.recipient);
        }
      });
    }

    this.closeIndividualRecipientModal();
    this.closeContactListModal();
    if (this.validateForm) this.validateForm();
  };

  onIndividualReturn(): void {
    if (!(this.recipient instanceof Individual)) return;

    this.recipient.faxnumber = this.recipient.faxnumber.trim();
    if (this.recipient.faxnumber) this.onSaveRecipient();
  }

  onAddingNewTag = (item: any): boolean => {
    if (!this.tagInput.dropdown.isVisible) {
      item.value = new Individual('', item.value, '', '', '');
    } else {
      const isNgTagTextInputFocused = this.ngTagTextInput === document.activeElement;

      if (isNgTagTextInputFocused && this.firstAutoCompleteSuggestion) {
        this.recipients[this.recipients.length - 1] = this.firstAutoCompleteSuggestion;
        item = this.firstAutoCompleteSuggestion.value;
      }
    }

    this.chipText = '';

    this.onRecipientAdded.emit(item);
    this.changed();

    return true;
  };

  onRemovingTag = (item: any): void => {
    this.onRecipientRemoved.emit(item);
    this.changed();
    this.addNewRecipientTag();
  };

  changed = (): void => {
    this.onChanged.emit(this.recipients);
    if (this.validateForm) this.validateForm();
  };

  editChipItem = (chipItem: RecipientContainer): void => {
    if (!chipItem) return;

    this.dialogState = recipientDialogState.Edit;

    this.recipient = chipItem.value.clone();

    if (chipItem.value instanceof ContactListRecipient) {
      this.closeContactListModal();
    } else {
      this.openIndividualRecipientModal();
    }
  };
}
