import { Injectable } from '@angular/core';
import {
    PasswordPolicy,
    IPasswordPolicy,
} from 'shared-code-lib';
import { ApiService } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/api.service';

@Injectable({
    providedIn: 'root',
})
export class HydraApiService {
    constructor(private apiService: ApiService) { }

    public getPasswordPolicy(successCallBack: (pp: PasswordPolicy) => void, failureCallBack: (err: any) => void): void {
        this.apiService.queryServer(`Tenants/passwordPolicy`).subscribe((pp: IPasswordPolicy) => {
            successCallBack(new PasswordPolicy(pp));
        }, failureCallBack);
    }
}
