import { CdkDragDrop, moveItemInArray } from '@angular/cdk/drag-drop';
import {
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  OnDestroy,
  OnInit,
  Output,
  ViewEncapsulation,
} from '@angular/core';
import { FileSystemFileEntry, NgxFileDropEntry } from 'ngx-file-drop';

import { Subscription } from 'rxjs';
import { AttachedItemTypes, SessionStorageService } from 'shared-code-lib';
import { DateTimeFormat } from '../../core/dateTimeFormat';
import { SharedDataService } from '../../services/shared-data.service';
import { ICapture } from '../document-scanner/models/scanner';
import { createPDFFromImages } from '../document-scanner/utils/pdf';

@Component({
  selector: '[appFileUpload]',
  templateUrl: './file-upload.component.html',
  styleUrls: ['./file-upload.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class FileUploadComponent implements OnInit, OnDestroy {
  @Input() uploadControlLabel;
  @Input() isRequired;

  isFaxMobile = false;

  _supportedFiles: string;

  acceptedExtensions: string;

  @Input() set supportedFiles(value: string) {
    this._supportedFiles = value;

    const tokens = value.split(', ');
    this.acceptedExtensions = tokens
      .map((token) => {
        return '.' + token.toLowerCase();
      })
      .join(', ');
  }

  get supportedFiles(): string {
    return this._supportedFiles;
  }

  @Input() formData;
  @Input() field;
  @Input() validateForm;
  @Output() filesChanged = new EventEmitter();
  formFiles: File[] = [];
  public files: NgxFileDropEntry[] = [];
  public items: any[] = [];

  showDocumentScanner = false;

  subscriptions = new Subscription();

  constructor(
    private cd: ChangeDetectorRef,
    private sharedData: SharedDataService,
    private sessionStorageService: SessionStorageService
  ) {}

  ngOnInit() {
    this.isFaxMobile = this.sessionStorageService.getIsInterFaxMobile();
    this.subscriptions.add(
      this.sessionStorageService.onIsInterFaxMobileChanged.subscribe((x) => (this.isFaxMobile = x))
    );

    if (this.sharedData.extraParameters && this.sharedData.extraParameters.items) {
      for (const item of this.sharedData.extraParameters.items) {
        this.items.push({ id: item.id, name: item.name, type: AttachedItemTypes.ItemId, args: item });
      }

      this.sharedData.extraParameters = null;
    }

    if (this.sharedData.files) {
      for (const file of this.sharedData.files) {
        this.formData[this.field] = this.formData[this.field].concat([file]);
      }

      this.sharedData.files = null;
    }

    this.formData[this.field] = this.formData[this.field].concat(this.items);
    this.validateForm();
  }

  addFile(event) {
    this.handleAddedFiles(event.target.files);
    event.target.value = null;
  }

  handleAddedFiles(files: File[]) {
    if (!files.length) return;

    for (const file of files) {
      if (!file) continue;

      this.formData[this.field] = this.formData[this.field].concat(file);
      this.validateForm();
      this.cd.detectChanges();
    }

    this.filesChanged.emit();
  }

  filesDropped = (files: NgxFileDropEntry[]) => {
    this.files = files;
    for (const droppedFile of this.files) {
      // Is it a file?
      if (droppedFile.fileEntry.isFile) {
        const fileEntry = droppedFile.fileEntry as FileSystemFileEntry;
        fileEntry.file((file: File) => {
          this.formData[this.field] = this.formData[this.field].concat([file]);
          this.validateForm();
          this.cd.detectChanges();
        });
      }
    }
  };

  deleteItem(itemIndex: number) {
    this.formData[this.field].splice(itemIndex, 1);
    this.validateForm();
    this.filesChanged.emit();
  }

  dropped(event: CdkDragDrop<string[]>) {
    moveItemInArray(this.formData[this.field], event.previousIndex, event.currentIndex);
  }

  handleCapturedDocument(captures: ICapture[]) {
    this.handleAddedFiles([
      createPDFFromImages(
        captures.map((c) => c.capturedImage),
        `document-${DateTimeFormat.getCompactDateTime(new Date()).replace(/:/g, '_')}.pdf`,
        true
      ),
    ]);
  }

  onCloseScanner() {
    this.showDocumentScanner = false;
  }

  ngOnDestroy() {
    this.subscriptions.unsubscribe();
  }
}
