import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { IOutcome, Outcome } from '../../../blocks/models/outcome';
import { TransitionResult } from '../../../blocks/models/transition-result';
import { ErrorsService } from '../../../blocks/services/errors.service';
import { HydraApiService } from '../../../blocks/services/hydra-api.service';
import { SpinnerStateService } from '../../../blocks/services/spinner-state.service';
import { DocumentLastTouchedService } from './document-last-touched.service';

@Injectable({
  providedIn: 'root',
})
export class OutcomesService {
  constructor(
    private ngxSmartModalService: NgxSmartModalService,
    private translate: TranslateService,
    private hydraApi: HydraApiService,
    private toastr: ToastrService,
    private errors: ErrorsService,
    private documentLastTouchedService: DocumentLastTouchedService,
    private spinnerService: SpinnerStateService,
    private translateService: TranslateService
  ) {}

  confirmOutcome = (outcome: IOutcome, confirmedOutcome: (data: any) => void): void => {
    const data = {
      title: 'MainHeader.ActionConfirmation',
      text: this.translate
        .instant('Document_Capture.confirm-outcome')
        .replace('{outcome}', outcome.label.toLowerCase()),
      buttonText: outcome.label,
      confirm: (_data: any) => {
        this.ngxSmartModalService.getModal('actionConfirmModal').close();
        confirmedOutcome(_data);
      },
      cancel: this.cancelOutcome,
      id: outcome.id,
    };
    this.ngxSmartModalService.setModalData(data, 'actionConfirmModal', true);
    this.ngxSmartModalService.getModal('actionConfirmModal').open();
  };

  cancelOutcome = () => {
    this.ngxSmartModalService.getModal('actionConfirmModal').close();
  };

  confirmDeleteSelectedItems(confirmedDeleteOutcome: (data: any) => void) {
    const discardOutcome = {
      id: Outcome.SendToDoneId,
      outcomeType: '',
      text: this.translate.instant('Scanning.Discard'),
      label: this.translate.instant('Scanning.Discard'),
      enabled: true,
      requiresConfirmation: true,
      requiresValidMetaData: false,
      nextId: '',
    };

    this.confirmOutcome(discardOutcome, confirmedDeleteOutcome);
  }

  transitionWorkItem(outcomeId: string, workItemId: string, successCallBack?: Function) {
    this.spinnerService.show(this.translateService.instant('App.executing-action'), document.documentElement);
    this.documentLastTouchedService.setLastTouchedWorkItem(workItemId);
    this.hydraApi.transitionWorkItem(
      workItemId,
      outcomeId,
      (transitionResult: TransitionResult) => {
        this.spinnerService.hide();
        if (!transitionResult.result) {
          this.toastr.error(transitionResult.errorText);
        } else {
          if (successCallBack) successCallBack();
        }
      },
      (err) => {
        this.spinnerService.hide();
        this.errors.showError('Scanning.ApplyDocumentFailed', err.error);
      }
    );
  }

  transitionFolder(outcomeId: string, folderId: string, successCallBack?: Function) {
    this.spinnerService.show(this.translateService.instant('App.executing-action'), document.documentElement);
    this.hydraApi.transitionFolder(
      folderId,
      outcomeId,
      (transitionResult: TransitionResult) => {
        this.spinnerService.hide();
        if (!transitionResult.result) {
          this.toastr.error(transitionResult.errorText);
        } else {
          if (successCallBack) successCallBack();
        }
      },
      (err) => {
        this.spinnerService.hide();
        this.errors.showError('Scanning.ApplyFolderFailed', err.error);
      }
    );
  }
}
