import { DOMSerializer } from 'prosemirror-model';
import { EditorState, blockNodes, getActiveMarks } from '@progress/kendo-editor-common';
import { mapInlineStylesToString } from '../styles-utils/inline-styles';
import { TemplateStyle } from './../../../../views/admin-olc/models/template';

export const convertNodeToHtmlElement = (schema, node) => {
  const serializer = DOMSerializer.fromSchema(schema);
  return serializer.serializeNode(node) as HTMLElement;
};

export const getActiveBlockStyle = (state: EditorState, olcTedBlockStyles: TemplateStyle[]) => {
  const nodes = blockNodes(state);

  const activeBlockStyles: string[] = [];

  olcTedBlockStyles.forEach((s) => {
    const hasOlcBlockStyle = nodes.some((n) => {
      const htmlElement = convertNodeToHtmlElement(state.schema, n);

      return styleMatches(s, {
        tag: htmlElement.tagName,
        class: htmlElement.getAttribute('class'),
        style: htmlElement.getAttribute('style'),
      });
    });

    if (hasOlcBlockStyle) activeBlockStyles.push(s.id);
  });

  const uniqueActiveBlockStyles = [...new Set(activeBlockStyles)];

  if (uniqueActiveBlockStyles.length !== 1) return null;

  return uniqueActiveBlockStyles[0];
};

export const hasDefaultParagraphOnly = (state: EditorState, blockStyles: TemplateStyle[]) => {
  const activeBlockStyleId = getActiveBlockStyle(state, blockStyles);
  return activeBlockStyleId === blockStyles[0].id;
};

export const getActiveInlineStyle = (state: EditorState, olcTedInlineStyles: TemplateStyle[]) => {
  const activeInlineStyles: string[] = [];

  olcTedInlineStyles.forEach((s) => {
    const activeMarks = getActiveMarks(state, state.schema.marks[s.element]);

    const hasOlcInlineStyle = activeMarks.marks.some((m) => {
      return styleMatches(s, { tag: m.type.name, class: m.attrs.class, style: m.attrs.style });
    });

    if (hasOlcInlineStyle) activeInlineStyles.push(s.id);
  });

  if (activeInlineStyles.length !== 1) return null;

  return activeInlineStyles[0];
};

const styleMatches = (s: TemplateStyle, elementToCompare: { tag: string; class: string; style: string }) => {
  const tagName = elementToCompare.tag.toLocaleLowerCase();
  const classes = elementToCompare.class?.replace(/\s/g, '').toLocaleLowerCase();
  const style = elementToCompare.style
    ?.replace(/\s/g, '')
    .toLocaleLowerCase()
    .split(';')
    .filter((str) => !str.includes('text-align'))
    .join(';');

  const styleTagName = s.element.replace(/\s/g, '').toLocaleLowerCase();
  const styleClasses = s.classes?.replace(/\s/g, '').toLocaleLowerCase();
  const inlineStylesString = mapInlineStylesToString(s.inlineStyles).replace(/\s/g, '').toLocaleLowerCase();

  const equalTagName = (!tagName && !styleTagName) || tagName === styleTagName;
  const equalClasses = (!classes && !styleClasses) || classes === styleClasses;
  const equalStyles = (!style && !inlineStylesString) || style === inlineStylesString;

  return equalTagName && equalClasses && equalStyles;
};

export const getSelectedFontProperty = (
  state: EditorState,
  property: 'font-family' | 'font-size',
  currentValue: string
) => {
  const uniqueFontMarks = getUniqueFontMarks(state, property);
  if (uniqueFontMarks.length === 0) return currentValue;
  if (uniqueFontMarks.length === 1) return uniqueFontMarks[0];
  return null;
};

export const oneOrMoreFontProperty = (state: EditorState, property: 'font-family' | 'font-size') => {
  const uniqueFontMarks = getUniqueFontMarks(state, property);
  return !!uniqueFontMarks.length;
};

const getUniqueFontMarks = (state: EditorState, property: 'font-family' | 'font-size') => {
  const selectedStyleState = getActiveMarks(state, state.schema.marks['style']);
  const fontMarks: string[] =
    selectedStyleState?.marks
      ?.filter((m) => !!m?.attrs?.style && m.attrs.style.toLowerCase().includes(property + ':'))
      .map((mark) =>
        mark.attrs.style
          .split(property + ':')[1]
          .split(';')[0]
          .trim()
      ) || [];

  return [...new Set(fontMarks)];
};
