import { IMetaDataDefinition, MetaDataLineItems } from 'shared-code-lib';

export class LineItemHeader {
  id: string;
  name: string;
  label: string;
  columns: Array<IMetaDataDefinition>;

  constructor(id: string, name: string, label: string, columns: Array<IMetaDataDefinition>) {
    this.id = id;
    this.name = name;
    this.label = label;
    this.columns = columns;
  }
}

export class UpdateLineItemsEvent {
  body: MetaDataLineItems;
}
