import { Directive, HostListener } from '@angular/core';

@Directive({
  selector: '[appPreventImageDrag]',
})
export class PreventDragDirective {
  constructor() {}

  @HostListener('document:mousedown', ['$event'])
  onClick(event) {
    const tags = ['a', 'img'];

    if (
      (tags.findIndex((x) => x == `${event.target.tagName}`.toLowerCase()) == -1 &&
        !event.target.closest('.not-draggable')) ||
      event.target.hasAttribute('draggable')
    )
      return;

    event.stopPropagation();
    event.preventDefault();
    return false;
  }
}
