import { EventEmitter } from '@angular/core';
import { Dictionary } from '../services/models';

export interface IFilterValue {
  id: string;
  value: string;
  label?: string;
}

export interface IFilter {
  id: string;
  label?: string;
  value?: string;
  defaultValue?: string;
  minValue?: string;
  maxValue?: string;
  hasUI?: boolean;
  options?: Array<Dictionary>;
}

export class Filter implements IFilter, IFilterValue {
  public id: string = '';
  public label: string = '';
  public value: string = '';
  public defaultValue?: string;
  public minValue: string = '';
  public maxValue: string = '';
  public hasUI: boolean = true;
  public options?: Array<Dictionary>;

  private _clearFilterSubject = new EventEmitter<void>();
  clearFilter = this._clearFilterSubject.asObservable();

  constructor(initializer: IFilter) {
    this.id = initializer.id;
    this.label = initializer.label;
    this.value = initializer.value ? initializer.value : '';
    this.defaultValue = initializer.defaultValue;
    this.minValue = initializer.minValue;
    this.maxValue = initializer.maxValue;
    this.hasUI = initializer.hasUI != false;
    this.options = initializer.options;
  }

  public getComponent(): string {
    throw new Error('getComponent not implemented');
  }

  public clear = (): void => {
    this._clearFilterSubject.next();
  };
}
