import { IScanSetting, ScanSetting } from 'shared-code-lib';
import { IWorkflowStep, WorkflowStep } from './workflow-step';

export interface IWorkflow {
  id: string;
  tenantId: string;
  name: string;
  workflowSteps: Array<IWorkflowStep>;
  scanSettings: Array<IScanSetting>;
  description: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  designerProperties: IWorfklowDesignerProperties;
  allowRoutingSheetGeneration: boolean;
  rolesAllowedToSubmitFrom: Array<string>;
  prompts: Array<string>;
}

export interface IWorfklowDesignerProperties {
  translateX: number;
  translateY: number;
}

export class WorfklowDesignerProperties implements IWorfklowDesignerProperties {
  public translateX: number;
  public translateY: number;

  constructor(initializer: IWorfklowDesignerProperties) {
    this.translateX = initializer.translateX;
    this.translateY = initializer.translateY;
  }

  public serializable = (): IWorfklowDesignerProperties => {
    return {
      translateX: this.translateX,
      translateY: this.translateY,
    };
  };
}

export class Workflow implements IWorkflow {
  public workflowSteps: Array<IWorkflowStep>;
  public scanSettings: Array<ScanSetting>;
  public designerProperties: WorfklowDesignerProperties;

  constructor(
    public id: string,
    public tenantId: string,
    public name: string,
    steps: Array<IWorkflowStep>,
    scanSettings: Array<IScanSetting>,
    public description: string,
    public dateCreatedUTC: Date,
    public dateModifiedUTC: Date,
    designerProperties: IWorfklowDesignerProperties,
    public allowRoutingSheetGeneration: boolean,
    public rolesAllowedToSubmitFrom: Array<string>,
    public prompts: Array<string>
  ) {
    this.workflowSteps = steps.map((s) => WorkflowStep.create(s));
    this.scanSettings = scanSettings ? scanSettings.map((ss) => new ScanSetting(ss)) : [];
    this.designerProperties = new WorfklowDesignerProperties(designerProperties);
  }

  public clone = (): Workflow => {
    const wf = this.serializable();

    return new Workflow(
      wf.id,
      wf.tenantId,
      wf.name,
      wf.workflowSteps,
      wf.scanSettings,
      wf.description,
      wf.dateCreatedUTC,
      wf.dateModifiedUTC,
      wf.designerProperties,
      wf.allowRoutingSheetGeneration,
      wf.rolesAllowedToSubmitFrom,
      wf.prompts
    );
  };

  public serializable = (): IWorkflow => {
    const s = {
      id: this.id,
      tenantId: this.tenantId,
      name: this.name,
      description: this.description,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      workflowSteps: [],
      scanSettings: this.scanSettings.map((s) => s.serializable()),
      designerProperties: this.designerProperties.serializable(),
      allowRoutingSheetGeneration: this.allowRoutingSheetGeneration,
      rolesAllowedToSubmitFrom: this.rolesAllowedToSubmitFrom.map((r) => r),
      prompts: this.prompts.map((s) => s),
    };

    for (let step of this.workflowSteps) {
      s.workflowSteps.push(step.serializable());
    }

    return s;
  };
}
