export interface IAPIKey {
  id: string;
  name: string;
  userId: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  dateLastUsedUTC: Date;
}

export class APIKey implements IAPIKey {
  id: string;
  name: string;
  userId: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  dateLastUsedUTC: Date;

  constructor(initializer: IAPIKey | null = null) {
    if (initializer) {
      if (initializer.id === undefined) throw new Error('Invalid initializer.id');
      if (initializer.name === undefined) throw new Error('Invalid initializer.name');
      if (initializer.userId === undefined) throw new Error('Invalid initializer.userId');
      if (initializer.dateCreatedUTC === undefined) throw new Error('Invalid initializer.dateCreatedUTC');
      if (initializer.dateModifiedUTC === undefined) throw new Error('Invalid initializer.dateModifiedUTC');
      if (initializer.dateLastUsedUTC === undefined) throw new Error('Invalid initializer.dateLastUsedUTC');

      this.id = initializer.id;
      this.name = initializer.name;
      this.userId = initializer.userId;
      this.dateCreatedUTC = initializer.dateCreatedUTC;
      this.dateModifiedUTC = initializer.dateModifiedUTC;
      this.dateLastUsedUTC = initializer.dateLastUsedUTC;
    }
  }

  public serializable(): IAPIKey {
    return {
      id: this.id,
      name: this.name,
      userId: this.userId,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      dateLastUsedUTC: this.dateLastUsedUTC,
    };
  }
}
