import { Component, ViewEncapsulation, ViewChild, Output, EventEmitter, ElementRef, Input } from '@angular/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { NgxFileDropEntry, FileSystemFileEntry, FileSystemDirectoryEntry } from 'ngx-file-drop';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';

import { SelectFilesService } from '../../services/select-files.service';

@Component({
  selector: 'app-myfiles-upload',
  templateUrl: './myfiles-upload.component.html',
  styleUrls: ['./myfiles-upload.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class MyfilesUploadComponent {
  @ViewChild(PerfectScrollbarDirective, { static: true }) directiveRef?: PerfectScrollbarDirective;
  @ViewChild('input') input: ElementRef;

  @Input() supportedFileTypes = '';
  @Input() multiple = false;
  @Input() uploadText = '';

  constructor(public ngxSmartModalService: NgxSmartModalService, public selectFiles: SelectFilesService) {}

  onFileSelected = (event: any): void => {
    if (!event.target.files || !event.target.files.length) return;

    for (const file of event.target.files) {
      if (this.isValidFile(file)) this.selectFiles.add(file);
    }

    event.target.value = null;
  };

  deleteItem = (file: File): void => {
    this.selectFiles.remove(file);
    this.directiveRef.update();
  };

  public dropped(files: NgxFileDropEntry[]) {
    if (!this.multiple && files.length > 1) return;
    if (!this.multiple && this.selectFiles.files.length) return;

    for (const droppedFile of files) {
      // Is it a file?
      if (droppedFile.fileEntry.isFile) {
        const fileEntry = droppedFile.fileEntry as FileSystemFileEntry;
        fileEntry.file((file: File) => {
          if (this.isValidFile(file)) this.selectFiles.add(file);
        });
      }
    }
  }

  onRender() {
    this.directiveRef.scrollToBottom(0, 300);
  }

  isValidFile(file) {
    const fileExtension = '.' + file.name.split('.').at(-1);
    return this.supportedFileTypes.split(',').includes(fileExtension.toLowerCase());
  }
}
