import { Component, Input, OnDestroy, OnInit, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PdfViewerComponent } from 'ng2-pdf-viewer';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import { ClipboardService, InboundLogBarcode } from 'shared-code-lib';

declare const $: any;

@Component({
  selector: 'app-preview-barcodes',
  templateUrl: './preview-barcodes.component.html',
  styleUrls: ['./preview-barcodes.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class BarcodesPreviewComponent implements OnInit, OnDestroy {
  @Input() viewer: PdfViewerComponent;
  @Input() barcodes: InboundLogBarcode[] = [];
  pdfViewerPage;

  subscriptions: Subscription = new Subscription();

  constructor(private toastrService: ToastrService, private translateService: TranslateService) {}

  ngOnInit(): void {
    this.subscriptions.add(this.viewer.pageRendered.subscribe(this.renderBarcodes));
  }

  renderBarcodes = (): void => {
    if (!this.barcodes?.length) return;

    $('.barcode-preview').remove();

    this.pdfViewerPage = $('.pdfViewer .page');
    if (!this.pdfViewerPage) return;

    this.barcodes.forEach((barcode) => {
      const el = $(`<div class="barcode-preview" barcodevalue="${barcode.value}"></div>`);
      $(el).css('left', `${barcode.x * 100}%`);
      $(el).css('top', `${barcode.y * 100}%`);
      $(el).css('width', `${barcode.width * 100}%`);
      $(el).css('height', `${barcode.height * 100}%`);
      this.pdfViewerPage.append(el);
    });

    $(this.pdfViewerPage).click(this.onClickPdfViewerPage);
  };

  onClickPdfViewerPage = (event) => {
    const eventTarget = event.target as HTMLDivElement;
    const isBarcodeDiv = eventTarget.className.toLowerCase().includes('barcode-preview');
    if (!isBarcodeDiv) return;

    const barcodeValue = eventTarget.getAttribute('barcodevalue');
    if (!barcodeValue) return;

    this.onCopyToClipboard(barcodeValue);
  };

  onCopyToClipboard = (value: string): void => {
    ClipboardService.copyToClipboard(value);

    this.toastrService.info(this.translateService.instant('general.copied-to-clipboard'));
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    $(this.pdfViewerPage).off('click', this.onClickPdfViewerPage);
  }
}
