import { Annotation } from 'shared-code-lib';
import { Document } from '../../../blocks/models/document';
import { WorkItem } from '../../../blocks/models/work-item';
import { BasicObject } from './capture-basic-object';
import { Page } from './page';

export class CapturedDocument extends BasicObject {
  private _pages: Array<Page>;
  private _document: Document;
  private _parentFolderId: string;
  private _parentStepId: string;

  private _workitem: WorkItem;
  workItemId: string;

  constructor(doc: Document, wi: WorkItem, folderId: string) {
    super(doc.id);
    this._document = doc;
    this._parentFolderId = folderId;
    this._workitem = wi;
    this._parentStepId = wi.workflowStepId;
    this._pages = [];
    this.workItemId = wi?.id;
  }

  get workitem(): WorkItem {
    return this._workitem;
  }

  get document(): Document {
    return this._document;
  }

  get pageCount(): number {
    return this._document.pageCount;
  }

  get name(): string {
    return this._document.filename;
  }

  set name(value: string) {
    this._document.filename = value;
  }

  get pages(): Array<Page> {
    return this._pages;
  }

  get pagesLoaded(): boolean {
    return this._pages.length === this._document.pageCount;
  }

  get parentFolderId(): string {
    return this._parentFolderId;
  }

  get parentStepId(): string {
    return this._parentStepId;
  }

  changeName(newName: string): void {
    this._document.filename = newName;
  }

  addPage(page: Page): void {
    this._pages.push(page);
  }

  sortPages(): void {
    this._pages.sort((a, b) => {
      return a.order - b.order;
    });
  }

  shiftPages(start: number, shiftCount: number) {
    this._pages.filter((p) => p.order >= start).map((page, i) => (page.order = page.order + shiftCount));
  }

  removePage(page: Page): void {
    this._pages = this._pages.filter((p) => p.order !== page.order);
    this._document.pageCount -= 1;
    this.reorderPages();
  }

  reorderPages(): void {
    this._pages.map((page, i) => (page.order = i + 1));
  }

  getPageByOrder(order: number): Page {
    return this._pages.find((page) => page.order === order);
  }

  getCurrentPage(order?: number): Page {
    if (!order) {
      return this._pages[this._pages.length - 1];
    } else {
      return this.getPageByOrder(order);
    }
  }

  getPageIndex(page: Page): number {
    return this._pages.indexOf(page);
  }

  getPageByIndex(index: number): Page {
    if (index < 0) {
      throw new Error('Page Index cannot be lower than 0');
    }
    return this._pages[index];
  }

  updatePageCount() {
    this._document.pageCount = this._pages.length;
  }

  updatePageAnnotations(pageOrder: number, documentWorkItemAnnotations: Annotation[]) {
    const pageAnnotations = documentWorkItemAnnotations.filter((a) => a.pageNumber === pageOrder);
    const pageIndex = this._pages.findIndex((p) => p.order === pageOrder);
    if (pageIndex === -1) return;

    this._pages[pageIndex].annotations = pageAnnotations;
    this._workitem.annotations = documentWorkItemAnnotations;
  }
}
