import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class TenantFilterByName extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByTenantNameComponent';
  }
}

export class TenantFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('TenantFilters.Create', filter);

    if (filter.id == 'BambaAdministratorApplication-Upland.Bamba.Application.Tenants.Filters.FilterByTenantName')
      return new TenantFilterByName(filter);

    return null;
  };
}
