import { IAction } from '../services/models';

export enum AlertType {
  Informational = 1,
  Critical = 2,
}

export interface IAlert {
  type: AlertType;
  text: string;
  action: IAction;
}

export class Alert implements IAlert {
  type: AlertType;
  text: string;
  action: IAction;

  constructor(initializer: IAlert) {
    this.action = initializer.action;
    this.text = initializer.text;
    this.type = initializer.type;
  }

  static ConstructFrom(initializer: IAlert[]): Alert[] {
    return initializer.map((iAlert) => {
      return new Alert(iAlert);
    });
  }

  serializable = (): IAlert => {
    return {
      action: this.action,
      text: this.text,
      type: this.type,
    };
  };

  textHasActionablePart = (): boolean => {
    return (
      this.text.indexOf('|#') != -1 &&
      this.text.indexOf('#|') != -1 &&
      this.text.indexOf('#|') > this.text.indexOf('|#')
    );
  };
  textBeforeActionableText = (): string => {
    return this.textHasActionablePart() ? this.text.split('|#')[0] : this.text;
  };
  actionableText = (): string => {
    return this.textHasActionablePart() ? this.text.split('|#')[1].split('#|')[0].trim() : '';
  };
  textAfterActionableText = (): string => {
    return this.textHasActionablePart() ? this.text.split('#|')[1] : '';
  };
}
