import { Component, EventEmitter, Input, OnDestroy, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Subscription } from 'rxjs';
import { FieldDefinition } from '../../..';
import { IInterFAXService } from '../../interop/IInterFAXService';
import { ISpinnerService } from '../../interop/ISpinnerService';
import { ContactList } from '../../models/interfax/contactlist';

@Component({
  selector: 'app-interfax-contactlist-modal',
  templateUrl: './interfax-contactlist-modal.component.html',
  styleUrls: ['./interfax-contactlist-modal.component.scss'],
})
export class InterfaxContactlistModalComponent implements OnInit, OnDestroy {
  @ViewChild('spinnerElement', { static: true })
  spinnerElement;
  @Input() current: Array<ContactList>;
  @Input() spinnerService: ISpinnerService;
  @Input() interfaxService: IInterFAXService;
  @Output() closeModal = new EventEmitter();
  @Output() saveModal = new EventEmitter<Array<ContactList>>();

  fieldName: FieldDefinition;
  title: string;
  show = false;
  errors: Array<string> = [];
  available: Array<ContactList> = [];

  subscriptions = new Subscription();

  constructor(private translateService: TranslateService) {}

  ngOnInit(): void {
    this.title = this.translateService.instant('contact-list.add');
    this.available = [];
    this.show = true;
    this.loadContactLists();
  }

  currentChanged = (current: Array<ContactList>): void => {
    this.current = current;
    if (this.current.length === 0) this.errors = [];
  };

  private loadContactLists = () => {
    this.spinnerService.show(this.translateService.instant('Common.LoadingData'), document.documentElement);
    this.subscriptions.add(this.interfaxService.getContactLists(this.contactListsLoaded, this.contactListsLoadFailed));
  };

  contactListsLoaded = (contactLists: Array<ContactList>): void => {
    this.available = contactLists.map((cl) => {
      let contactList = new ContactList(cl);
      contactList['icon'] = 'fa-address-book';
      return contactList;
    });

    this.spinnerService.hide();
  };

  contactListsLoadFailed = (): void => {
    this.spinnerService.hide();
  };

  save = (): void => {
    this.spinnerService.hide();
    this.errors = [];
    this.current.forEach((contactList) => {
      if (!contactList.hasContacts) {
        this.errors.push(contactList.name + ' : ' + this.translateService.instant('SendFax.EmptyContactList'));
      }
    });

    if (this.errors.length === 0) this.saveModal.emit(this.current);
  };

  close = (): void => {
    this.spinnerService.hide();
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.close();
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.spinnerService.hide();
  }
}
