import { PreviewDocument } from '../../../Bamba.Web/ClientApp/src/app/views/product-item/document-preview/document-preview.component';

export interface IPrintItem {
  id: string;
  documentFilename: string;
}

export class PrintItem {
  static fromPreviewDocument = (document: PreviewDocument): IPrintItem | null => {
    if (document)
      return {
        id: document.item.data.id,
        documentFilename: document.item.data.documentFilename,
      };
    else return null;
  };
}
