export interface ITermsOfService {
  id: string;
  tenantId: string;
  url: string;
  versionNumber: string;
  active: boolean;
  notes: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
}

export class TermsOfService implements ITermsOfService {
  public id: string;
  public tenantId: string;
  public url: string;
  public versionNumber: string;
  public active: boolean;
  public notes: string;
  public dateCreatedUTC: Date;
  public dateModifiedUTC: Date;

  constructor(initializer: ITermsOfService) {
    this.id = initializer.id;
    this.tenantId = initializer.tenantId;
    this.url = initializer.url;
    this.versionNumber = initializer.versionNumber;
    this.active = initializer.active;
    this.notes = initializer.notes;
    this.dateCreatedUTC = initializer.dateCreatedUTC;
    this.dateModifiedUTC = initializer.dateModifiedUTC;
  }

  serializable = (): ITermsOfService => {
    return {
      id: this.id,
      tenantId: this.tenantId,
      url: this.url,
      versionNumber: this.versionNumber,
      active: this.active,
      notes: this.notes,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
    };
  };
}
