import { Component, OnInit, ViewEncapsulation } from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';

import { LoginBaseComponent } from '../login-base/login-base.component';
import { LoadAppStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/load-app-state.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { Log } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { AuthService } from '../../services/auth/auth.service';
import { BambaDetailsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/bamba-details.service';
import { BrandingService } from '../../services/branding.service';
import { DelayService } from './../../utils/delay.service';
import { SessionStorageService } from '../../services/session-storage.service';
import { HydraApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';

@Component({
  selector: 'app-login-complete',
  templateUrl: './login-complete.component.html',
  styleUrls: ['./login-complete.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class LoginCompleteComponent extends LoginBaseComponent implements OnInit {
  constructor(
    hydraApi: HydraApiService,
    private appState: LoadAppStateService,
    userState: UserStateService,
    auth: AuthService,
    spinnerState: SpinnerStateService,
    translate: TranslateService,
    bds: BambaDetailsService,
    sss: SessionStorageService,
    bs: BrandingService,
    r: Router,
    private delay: DelayService
  ) {
    super(hydraApi, spinnerState, translate, auth, bds, userState, sss, bs, r);
  }

  ngOnInit(): void {
    super.ngOnInit();

    if (this.restartLoginProcess()) return;

    this.userStateService.startIdle();
    this.delay.execute(() => this.completeLogin());
  }

  completeLogin = (): void => {
    this.translateService.get('User.LoadingUser').subscribe((res) => {
      this.spinnerStateService.show(res, this.loginDivElement);
    });

    this.appState.load(
      this.loginDivElement,
      this.loginCompleted,
      this.appLoadFailureCallback,
      this.metaDataLoadFailureCallback
    );
  };

  loginCompleted = () => {
    Log.enter('login-component.loginCompleted');

    this.spinnerStateService.hide();

    this.authService.setUserStateLoaded(true);
    this.router.navigateByUrl(this.sessionStorageService.getReturnUrl() || this.userStateService.getUserHomePage());
  };

  appLoadFailureCallback = (err) => {
    Log.error('login-component.appLoadFailureCallback', err);

    this.loginFailure('Login.ApplicationLoadFailure');
  };

  metaDataLoadFailureCallback = (err) => {
    Log.error('login-component.metaDataLoadFailureCallback', err);

    this.loginFailure('Login.MetaDataLoadFailure');
  };
}
