import { Component, OnInit, Input } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ICombinedColumn } from 'shared-code-lib';
import { TableItem } from 'shared-code-lib';
import { ColumnDisplayType } from 'shared-code-lib';

@Component({
  selector: '[appMachineAggregateDetail]',
  templateUrl: './machine-aggregate-detail.component.html',
  styleUrls: ['./machine-aggregate-detail.component.scss'],
})
export class MachineAggregateDetailComponent implements OnInit {
  @Input() details: any;
  items: TableItem[];
  columns: Array<ICombinedColumn>;

  constructor(private translate: TranslateService) {}

  ngOnInit(): void {
    this.columns = this.getColumns();
    this.items = this.createItems();
  }

  createItems = (): Array<TableItem> => {
    const items = new Array<TableItem>();

    this.details.installedComponents.forEach((element) => {
      const tableItem = new TableItem(element, this.columns, this.translate);

      items.push(tableItem);
    });

    return items;
  };
  getColumns(): Array<ICombinedColumn> {
    const columns: Array<ICombinedColumn> = [];

    columns.push(this.createColumn('componentName', ColumnDisplayType.Text, 200, false));
    columns.push(this.createColumn('version', ColumnDisplayType.Text, 200, false));

    return columns;
  }

  createColumn(field: string, displayType: number, width: number, stretch: boolean) {
    return {
      id: 'column_' + field,
      width: width,
      stretch: stretch,
      displayType: displayType,
      headerImage: '',
      headerText: this.translate.instant(`machine-aggregate.${field}`),
      itemProperty: field,
      columnName: field,
      sortable: false,
      sortByFieldName: '',
      invertBooleanValue: false,
    };
  }
}
