import { ClearZoneType } from '../templates/template-editor/models/clear-zone';
import { ITEDCondition, ITEDItem, ITEDSection } from '../templates/template-editor/models/ted-state';

export enum VersionStatus {
  Draft = 0,
  PendingApproval = 1,
  Approved = 2,
  Rejected = 3,
  PendingProduction = 4,
  InProduction = 5,
  WasInProduction = 6,
}

export interface ITemplateVersion {
  versionId: string;
  versionNumber: number;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  uploadUserId: string;
  uploadUsername: string;
  comment: string;
  status: VersionStatus;
  sections: ITEDSection[];
  items: ITEDItem[];
  approval: any;
}

export interface ITemplateVariable {
  name: string;
  content: string;
  find: string;
  replace: string;
}

export interface ITemplateVariablesHighlight {
  outline: string;
  backgroundColor: string;
  color: string;
}

export interface ITemplateCondition {
  group: string;
  fields: ITemplateConditionField[];
}

export interface ITemplateConditionField {
  name: string;
  connect_script: string;
}

export interface ITemplateClearZone {
  title: string;
  class: string;
  type: ClearZoneType;
  top: string;
  left: string;
  width: string;
  height: string;
  borderWidth: string;
  rotate: number;
  sections: string[];
  pages: number[];
}

export interface IConditionalField {
  name: string;
  values: string[];
}
export interface IGroupOption {
  name: string;
  value: string;
}
export interface ITemplateConditionalContent {
  group: string;
  fields: IConditionalField[];
  groupOptions: IGroupOption[];
}

export interface ITemplateStyle {
  id: string;
  name: string;
  element: string | null;
  elementType: StyleType;
  classes: string | null;
  inlineStyles: IInlineStyle[];
}

export class IInlineStyle {
  property: string;
  value: string;
}

export enum StyleType {
  None = 0,
  Inline = 1,
  Block = 2,
  Selector = 3,
}

export interface ITemplate {
  id: string;
  name: string;
  description: string;
  productionVersionId: string;
  productionDateUTC: Date;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  snippets: string[];
  templateStyles: ITemplateStyle[];
  customStyles: string[];
  versions: ITemplateVersion[];
  templateIdInOLConnectServer: string;
  indexJSON: string;
  optionsJSON: string;
  recordsCount: number;
  bigJSON: string;
  smallJSON: string;
  variables: ITemplateVariable[];
  variablesHighlight: ITemplateVariablesHighlight;
  conditions: ITemplateCondition[];
  clearZones: ITemplateClearZone[];
  conditionalContents: ITemplateConditionalContent[];
  templateType: TemplateType;
}

export class Template implements ITemplate {
  id: string;
  name: string;
  description: string;
  productionVersionId: string;
  productionDateUTC: Date;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  snippets: string[];
  templateStyles: TemplateStyle[];
  customStyles: string[];
  versions: ITemplateVersion[];
  templateIdInOLConnectServer: string;
  indexJSON: string;
  optionsJSON: string;
  recordsCount: number;
  bigJSON: string;
  smallJSON: string;
  variables: ITemplateVariable[];
  variablesHighlight: ITemplateVariablesHighlight;
  conditions: ITemplateCondition[];
  clearZones: ITemplateClearZone[];
  conditionalContents: ITemplateConditionalContent[];
  templateType: TemplateType;

  constructor(initializer: ITemplate | null = null) {
    if (initializer) {
      if (initializer.id === undefined) throw new Error('Invalid initializer.id');
      if (initializer.name === undefined) throw new Error('Invalid initializer.name');
      if (initializer.description === undefined) throw new Error('Invalid initializer.description');
      if (initializer.productionVersionId === undefined) throw new Error('Invalid initializer.productionVersionId');
      if (initializer.productionDateUTC === undefined) throw new Error('Invalid initializer.productionDateUTC');
      if (initializer.dateCreatedUTC === undefined) throw new Error('Invalid initializer.dateCreatedUTC');
      if (initializer.dateModifiedUTC === undefined) throw new Error('Invalid initializer.dateModifiedUTC');
      if (initializer.snippets === undefined) throw new Error('Invalid initializer.snippets');
      if (initializer.templateStyles === undefined) throw new Error('Invalid initializer.templateStyles');
      if (initializer.customStyles === undefined) throw new Error('Invalid initializer.customStyles');
      if (initializer.versions === undefined) throw new Error('Invalid initializer.versions');
      if (initializer.templateIdInOLConnectServer === undefined)
        throw new Error('Invalid initializer.templateIdInOLConnectServer');
      if (initializer.indexJSON === undefined) throw new Error('Invalid initializer.indexJSON');
      if (initializer.optionsJSON === undefined) throw new Error('Invalid initializer.optionsJSON');
      if (initializer.recordsCount === undefined) throw new Error('Invalid initializer.recordsCount');
      if (initializer.bigJSON === undefined) throw new Error('Invalid initializer.bigJSON');
      if (initializer.smallJSON === undefined) throw new Error('Invalid initializer.smallJSON');
      if (initializer.variables === undefined) throw new Error('Invalid initializer.variables');
      if (initializer.variablesHighlight === undefined) throw new Error('Invalid initializer.variablesHighlight');
      if (initializer.conditions === undefined) throw new Error('Invalid initializer.conditions');
      if (initializer.clearZones === undefined) throw new Error('Invalid initializer.clearZones');
      if (initializer.conditionalContents === undefined) throw new Error('Invalid initializer.conditionalContents');
      if (initializer.templateType === undefined) throw new Error('Invalid initializer.templateType');

      this.id = initializer.id;
      this.name = initializer.name;
      this.description = initializer.description;
      this.productionVersionId = initializer.productionVersionId;
      this.productionDateUTC = initializer.productionDateUTC;
      this.dateCreatedUTC = initializer.dateCreatedUTC;
      this.dateModifiedUTC = initializer.dateModifiedUTC;
      this.snippets = initializer.snippets.map((s) => s);
      this.templateStyles = initializer.templateStyles.map((s) => new TemplateStyle(s));
      this.customStyles = initializer.customStyles.map((s) => s);
      this.versions = initializer.versions.map((v) => v);
      this.templateIdInOLConnectServer = initializer.templateIdInOLConnectServer;
      this.indexJSON = initializer.indexJSON;
      this.optionsJSON = initializer.optionsJSON;
      this.recordsCount = initializer.recordsCount;
      this.bigJSON = initializer.bigJSON;
      this.smallJSON = initializer.smallJSON;
      this.variables = initializer.variables.map((v) => new TemplateVariable(v));
      this.variablesHighlight = new TemplateVariablesHighlight(initializer.variablesHighlight);
      this.conditions = initializer.conditions.map((c) => new TemplateCondition(c));
      this.clearZones = initializer.clearZones;
      this.conditionalContents = initializer.conditionalContents;
      this.templateType = initializer.templateType;
    }
  }

  public serializable(): ITemplate {
    return {
      id: this.id,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      name: this.name,
      description: this.description,
      productionVersionId: this.productionVersionId,
      productionDateUTC: this.productionDateUTC,
      snippets: this.snippets,
      templateStyles: this.templateStyles.map((s) => s.serializable()),
      customStyles: this.customStyles,
      versions: this.versions,
      templateIdInOLConnectServer: this.templateIdInOLConnectServer,
      indexJSON: this.indexJSON,
      optionsJSON: this.optionsJSON,
      recordsCount: this.recordsCount,
      bigJSON: this.bigJSON,
      smallJSON: this.smallJSON,
      variables: this.variables,
      variablesHighlight: this.variablesHighlight,
      conditions: this.conditions,
      clearZones: this.clearZones,
      conditionalContents: this.conditionalContents,
      templateType: this.templateType,
    };
  }
}

