      if (initializer.dateCreatedUTC === undefined) throw new Error('Invalid initializer.dateCreatedUTC');
      if (initializer.dateModifiedUTC === undefined) throw new Error('Invalid initializer.dateModifiedUTC');
      if (initializer.uploadUserId === undefined) throw new Error('Invalid initializer.uploadUserId');
      if (initializer.uploadUsername === undefined) throw new Error('Invalid initializer.uploadUsername');
      if (initializer.comment === undefined) throw new Error('Invalid initializer.comment');
      if (initializer.status === undefined) throw new Error('Invalid initializer.status');
