export class TemplateStyle implements ITemplateStyle {
  id: string;
  name: string;
  element: string;
  elementType: StyleType;
  classes: string;
  inlineStyles: InlineStyle[];

  constructor(initializer: ITemplateStyle | null = null) {
    if (initializer) {
      if (initializer.name === undefined) throw new Error('Invalid initializer.name');
      if (initializer.element === undefined) throw new Error('Invalid initializer.element');
      if (initializer.elementType === undefined) throw new Error('Invalid initializer.elementType');
      if (initializer.classes === undefined) throw new Error('Invalid initializer.classes');
      if (initializer.inlineStyles === undefined) throw new Error('Invalid initializer.inlineStyles');

      this.id = initializer.id || '';
      this.name = initializer.name;
      this.element = initializer.element;
      this.elementType = initializer.elementType;
      this.classes = initializer.classes;
      this.inlineStyles = initializer.inlineStyles.map((i) => new InlineStyle(i));
    }
  }

  public serializable(): ITemplateStyle {
    return {
      id: this.id,
      name: this.name,
      element: this.element,
      elementType: this.elementType,
      classes: this.classes,
      inlineStyles: this.inlineStyles.map((s) => s.serializable()),
    };
  }
}

export class InlineStyle implements IInlineStyle {
  property: string;
  value: string;

  constructor(initializer: IInlineStyle | null = null) {
    if (initializer) {
      if (initializer.property === undefined) throw new Error('Invalid initializer.property');
      if (initializer.value === undefined) throw new Error('Invalid initializer.value');

      this.property = initializer.property;
      this.value = initializer.value;
    }
  }

  public serializable(): IInlineStyle {
    return {
      property: this.property,
      value: this.value,
    };
  }
}

export enum TemplateType {
  TED = 0,
  OLTemplate = 1,
}
