import { Action, ActionEvent } from './actions';
import { Key } from 'shared-code-lib';
import { TranslateService } from '@ngx-translate/core';

enum KeyModifier {
  None = 0,
  Alt = 1 << 0,
  Ctrl = 1 << 1,
  Shift = 1 << 2,
}

class KeyboardActionMap {
  public constructor(
    public keyName: string,
    public keyCode: Key,
    public action: Action,
    public modifiers: KeyModifier = KeyModifier.None,
    public allowedWhenTextBoxFocused: boolean = true
  ) {}

  public matches = (keyEvent: KeyboardEvent): boolean => {
    if (keyEvent.key !== this.keyCode) return false;

    if (this.modifiers & KeyModifier.Alt && !keyEvent.altKey) return false;
    if (this.modifiers & KeyModifier.Ctrl && !keyEvent.ctrlKey) return false;
    if (this.modifiers & KeyModifier.Shift && !keyEvent.shiftKey) return false;

    if (keyEvent.altKey && !(this.modifiers & KeyModifier.Alt)) return false;
    if (keyEvent.ctrlKey && !(this.modifiers & KeyModifier.Ctrl)) return false;
    if (keyEvent.shiftKey && !(this.modifiers & KeyModifier.Shift)) return false;

    if (this.allowedWhenTextBoxFocused) return true;

    if (this.inputElementHasFocus()) return false;

    return true;
  };

  private inputElementHasFocus(): boolean {
    if (!document || !document.activeElement) return false;

    const inputTagNames = ['INPUT', 'TEXTAREA'];
    if (inputTagNames.includes(document.activeElement.tagName)) return true;

    return false;
  }
}

export class KeyboardActionMapping {
  //
  // NOTE: do not globally map "common" keys unless you purposely set allowedWhenTextBoxFocused and understand the impact
  //       for instance: "Delete" as this will break normal usage of Delete in a text box
  //       It can be mapped when using modifiers (shift, ctrl, alt)
  //
  private static keyMap: Array<KeyboardActionMap> = [
    new KeyboardActionMap('F2', Key.F2, Action.EditSelection),
    new KeyboardActionMap('F6', Key.F6, Action.SetFocusTreePanel),

    new KeyboardActionMap('ArrowRight', Key.ArrowRight, Action.RotateRight, KeyModifier.Ctrl),
    new KeyboardActionMap('ArrowLeft', Key.ArrowLeft, Action.RotateLeft, KeyModifier.Ctrl),

    new KeyboardActionMap('-', Key.NumpadSubtract, Action.ZoomOut, KeyModifier.Ctrl),
    new KeyboardActionMap('-', Key.NumpadSubtract, Action.ZoomOut, KeyModifier.Shift | KeyModifier.Ctrl),

    new KeyboardActionMap('+', Key.NumpadAdd, Action.ZoomIn, KeyModifier.Ctrl),
    new KeyboardActionMap('=', Key.Equal, Action.ZoomIn, KeyModifier.Ctrl),
    new KeyboardActionMap('+', Key.NumpadAdd, Action.ZoomIn, KeyModifier.Shift | KeyModifier.Ctrl),

    new KeyboardActionMap('ArrowUp', Key.ArrowUp, Action.FitToHeight, KeyModifier.Ctrl | KeyModifier.Shift),
    new KeyboardActionMap('ArrowRight', Key.ArrowRight, Action.FitToWidth, KeyModifier.Ctrl | KeyModifier.Shift),

    new KeyboardActionMap('Del', Key.Delete, Action.DeleteSelectedItem, KeyModifier.None, false),
    new KeyboardActionMap('Del', Key.Delete, Action.CtrlDeleteSelectedItem, KeyModifier.Ctrl),

    new KeyboardActionMap('F7', Key.F7, Action.ScanToFolder),
    new KeyboardActionMap('F7', Key.F7, Action.ScanNew, KeyModifier.Ctrl),
    new KeyboardActionMap('F8', Key.F8, Action.ImportToFolder),
    new KeyboardActionMap('F8', Key.F8, Action.ImportNew, KeyModifier.Ctrl),

    new KeyboardActionMap('NextPage', Key.ArrowDown, Action.NextPage, KeyModifier.Ctrl),
    new KeyboardActionMap('PreviousPage', Key.ArrowUp, Action.PreviousPage, KeyModifier.Ctrl),

    new KeyboardActionMap('F9', Key.F9, Action.Outcome4, KeyModifier.None),
    new KeyboardActionMap('F10', Key.F10, Action.Outcome3, KeyModifier.None),
    new KeyboardActionMap('F11', Key.F11, Action.Outcome2, KeyModifier.None),
    new KeyboardActionMap('F12', Key.F12, Action.Outcome1, KeyModifier.None),

    new KeyboardActionMap('Enter', Key.Enter, Action.BreakDocument, KeyModifier.Ctrl),

    new KeyboardActionMap('Escape', Key.Escape, Action.CloseLatestEscapableModal),
  ];

  public static getFor = (keyEvent: KeyboardEvent): ActionEvent => {
    for (const kap of KeyboardActionMapping.keyMap) {
      if (kap.matches(keyEvent)) {
        return new ActionEvent(kap.action);
      }
    }

    return null;
  };

  public static getTooltipFor = (action: Action, translateService: TranslateService): string => {
    for (const kap of KeyboardActionMapping.keyMap) {
      if (kap.action === action) {
        const modifiers: Array<string> = [];

        if (kap.modifiers & KeyModifier.Alt) modifiers.push(translateService.instant('KeyboardMappings.modifier-Alt'));
        if (kap.modifiers & KeyModifier.Ctrl) modifiers.push(translateService.instant('KeyboardMappings.modifier-Ctrl'));
        if (kap.modifiers & KeyModifier.Shift) modifiers.push(translateService.instant('KeyboardMappings.modifier-Shift'));

        const translationId = `KeyboardMappings.key-${kap.keyName}`;
        let translatedKeyName = translateService.instant(translationId);
        if (translatedKeyName == translationId) translatedKeyName = kap.keyName;
        if (!modifiers.length) return ` (${translatedKeyName})`;
        
        return ` (${modifiers.join('+')} ${translatedKeyName})`;
      }
    }
    
    return '';
  };
}

