import { AfterViewInit, Component, EventEmitter, OnInit, Output, ViewChild, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';

import { HydraApiService } from '../../../../../../../blocks/services/hydra-api.service';
import { Media, MediaFileType } from '../../../../../models/media';
import { SpinnerStateService } from '../../../../../../../blocks/services/spinner-state.service';
import { Tab, TabBarComponent } from '../../../../../../../../../../../Bamba.Shared/src/form/tab-bar/tab-bar.component';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ItemToAddOrEdit, MediaPreviewData, MediaType } from '../../../models/ted-state';

@Component({
  selector: 'app-select-media-modal',
  templateUrl: './select-media-modal.component.html',
  styleUrls: ['./select-media-modal.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class SelectMediaModalComponent implements OnInit, AfterViewInit {
  @ViewChild(TabBarComponent) tabBarComponent: TabBarComponent;
  @Output() select = new EventEmitter<MediaPreviewData>();
  @Output() cancel = new EventEmitter();

  selectMediaModal: NgxSmartModalComponent;

  medias: Media[] = [];
  currentMediaIndex = 0;

  currentMediaPreviewData: MediaPreviewData = null;

  tabs: Tab[] = [];
  activeTab = 'resources';

  selectedItemType = ItemToAddOrEdit.Image;

  supportedFileTypes = '';

  pdfType = MediaFileType.PDF;

  loading = true;
  mediaSelected = false;

  constructor(
    private hydraApiService: HydraApiService,
    private ngxSmartModalService: NgxSmartModalService,
    private translateService: TranslateService,
    private spinnerService: SpinnerStateService,
    private toastr: ToastrService
  ) {}

  ngOnInit() {}

  ngAfterViewInit(): void {
    try {
      this.selectMediaModal = this.ngxSmartModalService.get('selectMediaModal');
      const itemType = (this.selectMediaModal?.getData() as any)?.itemType;
      if (itemType) this.selectedItemType = itemType;
    } catch (err) {}

    this.supportedFileTypes = this.selectedItemType === ItemToAddOrEdit.Image ? '.jpeg,.jpg,.png,.bmp,.pdf' : '.pdf';

    this.createTabs();
    this.getMedia();

    this.spinnerService.visibilityChanged.subscribe((visible) => (this.loading = visible));
  }

  createTabs() {
    this.tabs.push(new Tab('resources', this.translateService.instant('admin-olc-media.select-media-modal-resources')));
    this.tabs.push(new Tab('disk', this.translateService.instant('admin-olc-media.select-media-modal-disk')));
  }

  activateTab = (tab) => {
    this.activeTab = tab;
  };

  getMedia() {
    this.spinnerService.show(
      this.translateService.instant('admin-olc-media.loading-media'),
      document.querySelector('.olc-add-or-edit-item-modal')
    );

    this.hydraApiService.getAllowedMedia(
      this.selectedItemType === ItemToAddOrEdit.Image ? MediaType.All : MediaType.PDF,
      this.mediaLoaded,
      this.mediaLoadFailed
    );
  }

  mediaLoaded = (medias: Media[]) => {
    this.medias = medias;
    this.spinnerService.hide();

    if (!this.medias.length) return;

    this.previewMedia(this.currentMediaIndex);
  };

  mediaLoadFailed = () => {
    this.spinnerService.hide();
    this.toastr.error(this.translateService.instant('admin-olc-media.media-load-failed'));
  };

  onClose = () => {
    this.activateTab('resources');
    this.tabBarComponent.activateTab('resources');
    this.getMedia();
  };

  setAndPreviewCurrentMedia(index: number) {
    this.currentMediaIndex = index;
    this.previewMedia(this.currentMediaIndex);
  }

  previewMedia = (index: number) => {
    const baseUrl = window.location.origin;
    const currentMedia = this.medias[index];

    const isPdf = currentMedia.fileType === MediaFileType.PDF;

    this.currentMediaPreviewData = {
      url: `${baseUrl}/api/preview/media/${currentMedia.id}${
        this.selectedItemType === ItemToAddOrEdit.Image && isPdf ? '?filetype=pdf' : ''
      }`,
      name: currentMedia.name,
      type: currentMedia.fileType,
    };
  };

  cancelHandler = () => {
    this.selectMediaModal?.close();
    this.cancel.emit();
  };

  selectMedia() {
    this.mediaSelected = true;
    this.select.emit(this.currentMediaPreviewData);
    this.selectMediaModal?.close();
  }
}
