import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class DataSourceFilterByColumn extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByDataSourceColumnComponent';
  }
}

export class DataSourceFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('DataSourceFilters.Create', filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.WorkItems.Filtering.FilterByDataSourceColumn')
      return new DataSourceFilterByColumn(filter);

    return null;
  };
}
