import { NotificationType } from './outbound';

export enum WebIntegrationType {
  HTTPPost = 0,
  XMLWebService = 1,
  Extended = 2,
}

export interface IWebIntegration {
  webIntegrationType: WebIntegrationType;
  url: string;
}

export interface IWebIntegrationOutbound extends IWebIntegration {
  notificationType: NotificationType;
}

export interface IExtendedConfiguration {
  type: string;
}

export interface IWebIntegrationInbound extends IWebIntegration {
  enabled: boolean;
  extendedConfiguration: IExtendedConfiguration;
}

export class WebIntegration {
  public webIntegrationType: WebIntegrationType;
  public url: string;

  constructor(wi: IWebIntegration) {
    this.webIntegrationType = wi ? wi.webIntegrationType : WebIntegrationType.HTTPPost;
    this.url = wi ? wi.url : '';
  }

  serializable(): IWebIntegration {
    return {
      webIntegrationType: this.webIntegrationType,
      url: this.url,
    };
  }
}

export class WebIntegrationInbound extends WebIntegration {
  public enabled: boolean;
  public extendedConfiguration: ExtendedConfiguration;

  constructor(wio: IWebIntegrationInbound = null) {
    super(wio);

    this.enabled = wio ? wio.enabled : false;
    if (this.webIntegrationType == WebIntegrationType.Extended)
      this.extendedConfiguration = ExtendedConfiguration.createFrom(wio.extendedConfiguration);
  }

  serializable(): IWebIntegrationInbound {
    return {
      ...super.serializable(),
      enabled: this.enabled,
      extendedConfiguration: this.extendedConfiguration,
    };
  }
}

export class ExtendedConfiguration implements IExtendedConfiguration {
  type: string;

  static createFrom(ec: IExtendedConfiguration): ExtendedConfiguration {
    if (ec.type == 'EFax') return new EFAXConfiguration(ec);
    if (ec.type == 'Http') return new HttpConfiguration(ec);

    throw new Error(`Unknown ExtendedConfiguration.type = '${ec.type}'`);
  }
}

export class EFAXConfiguration extends ExtendedConfiguration {
  fileType: string;
  contentType: string;
  userName: string;
  password: string;

  constructor(i: any) {
    super();

    this.type = 'EFax';
    this.fileType = i.fileType;
    this.contentType = i.contentType;
    this.userName = i.userName;
    this.password = i.password;
  }
}

export interface IHTTPHeader {
  name: string;
  value: string;
}

export enum HTTPBodyPartTypes {
  TextASCII = 0,
  TextUTF8 = 1,
  TextUTF16 = 2,
  DocumentPDF = 3,
  DocumentTIF = 4,

  Multipart = 255,
}

export interface IHTTPBodyPart {
  type: HTTPBodyPartTypes;
  headers: Array<IHTTPHeader>;
  bodyText: string;
}

export class HTTPHeader implements IHTTPHeader {
  name: string;
  value: string;

  constructor(i: IHTTPHeader = null) {
    this.name = i?.name || '';
    this.value = i?.value || '';
  }
}

export class HTTPBodyPart implements IHTTPBodyPart {
  type: HTTPBodyPartTypes;
  headers: HTTPHeader[];
  bodyText: string;

  constructor(i: IHTTPBodyPart = null) {
    this.type = i ? i.type : HTTPBodyPartTypes.DocumentPDF;
    this.headers = i?.headers?.map((h) => new HTTPHeader(h)) || new Array<HTTPHeader>();
    this.bodyText = i?.bodyText || '';
  }
}

export class HttpConfiguration extends ExtendedConfiguration {
  timeoutSeconds: number;
  httpMethod: string;
  main: IHTTPBodyPart;
  bodyParts: Array<IHTTPBodyPart>;

  constructor(i: any) {
    super();

    this.type = 'Http';
    this.timeoutSeconds = i?.timeoutSeconds || '60';
    this.httpMethod = i?.httpMethod || 'Post';
    this.main = new HTTPBodyPart(i?.main);
    this.bodyParts = i?.bodyParts?.map((bp) => new HTTPBodyPart(bp)) || new Array<HTTPBodyPart>();
  }
}

export class WebIntegrationOutbound extends WebIntegration {
  public notificationType: NotificationType;

  constructor(wio: IWebIntegrationOutbound = null) {
    super(wio);

    this.notificationType = wio ? wio.notificationType : NotificationType.Never;
  }

  serializable(): IWebIntegrationOutbound {
    return {
      ...super.serializable(),
      notificationType: this.notificationType,
    };
  }
}
