import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { FieldDefinition, FixedDataSource, IFieldOptions, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

class PushTarget {
  public displayText: string;
  public environmentId: string;
  public groupingId: string;
}

@Component({
  selector: 'app-sm-push-modal',
  templateUrl: './sm-push-modal.component.html',
  styleUrls: ['./sm-push-modal.component.scss'],
})
export class SmPushModalComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  componentName: string = '';
  componentVersion: string = '';
  componentIds = [];

  jiraCommentField: FieldDefinition;
  jiraComment: string = '';

  pushTarget: FieldDefinition;
  pushTargets: PushTarget[];
  selectedPushTarget: string = '';

  prerequisiteJiraItems: string;
  confirmPrerequisites: boolean = false;

  errors = [];
  id = '';
  modalTitle: string;
  actionLabel: string;

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private ngxSmartModalService: NgxSmartModalService
  ) {}

  ngOnInit(): void {
    this.id = this.sharedDataService.extraParameters.id;
    this.componentName = this.sharedDataService.extraParameters.componentName;
    this.componentVersion = this.sharedDataService.extraParameters.componentVersion;
    this.pushTargets = this.sharedDataService.extraParameters.pushTargets;
    this.componentIds = [this.id];
    this.prerequisiteJiraItems = this.sharedDataService.extraParameters.prerequisiteJiraItems;

    this.createFields();
  }

  canPush = (): boolean => {
    if (!this.selectedPushTarget) return false;

    if (!this.prerequisiteJiraItems) return true;
    return this.confirmPrerequisites;
  };

  createFields = () => {
    this.jiraCommentField = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('sm-push-modal.notes'),
      placeholder: this.translateService.instant('sm-push-modal.notes-placeholder'),
      required: true,
    });

    const options = new Array<IFieldOptions>();
    this.pushTargets.forEach((x) => options.push({ value: x.groupingId, name: x.displayText }));
    const datasource = new FixedDataSource(options);

    this.pushTarget = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('sm-push-modal.push-target'),
      placeholder: '',
      required: true,
      datasource: datasource,
    });
  };

  addNotes = () => {
    this.errors = [];

    this.showSpinner();

    const args = new MetaDataCollection();
    args.set('comment', this.jiraComment);
    args.set('push-target', this.selectedPushTarget);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.componentIds,
      args,
      this.onSMPushSucceeded,
      this.onSMPushFailed
    );

    return false;
  };

  onSMPushSucceeded = (result): void => {
    this.spinnerService.hide();

    this.close();
  };

  onSMPushFailed = (errors: any[]): void => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  close = (): void => this.closeModal.emit();

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.sm-push-modal .nsm-content') as HTMLElement;
  }

  showSpinner = (): void => {
    this.spinnerService.show(this.translateService.instant('sm-push-modal.loading'), this.getSpinnerElement());
  };
}
