export class Strings {
  public static isNullOrUndefined = (value): boolean => value === null || value === undefined;

  public static isEmpty = (value: string): boolean => {
    if (Strings.isNullOrUndefined(value)) return true;
    if (value == '') return true;

    return false;
  };

  public static isEmptyOrWhiteSpace = (value: string): boolean => {
    if (Strings.isEmpty(value)) return true;

    return value.trim() == '';
  };

  public static notEmpty = (value: string): boolean => {
    return !Strings.isEmpty(value);
  };

  public static notEmptyOrWhiteSpace = (value: string): boolean => {
    if (Strings.isEmpty(value)) return false;

    return !Strings.isEmpty(value.trim());
  };

  public static getEOLCharacters = (value: string): string => {
    return value.indexOf('\r\n') == -1 ? '\n' : '\r\n';
  };

  public static containsTag = (html: string, tag: string): boolean => {
    if (html.indexOf(tag) != -1) return true;
  };

  public static isEmptyHtml = (html: string): boolean => {
    if (Strings.isEmpty(html)) return true;

    html = html.toLowerCase();
    if (Strings.containsTag(html, '<img')) return false;
    if (Strings.containsTag(html, '<li')) return false;
    if (Strings.containsTag(html, '<blockquote')) return false;

    let plainText = html.replace(/<[^>]+>/g, '');
    if (Strings.isEmpty(plainText)) return true;

    plainText = plainText.replace(/\s/g, '');
    return Strings.isEmpty(plainText);
  };

  public static HtmlToText = (html: string): string => {
    const span = document.createElement('span');
    span.innerHTML = html;
    return span.textContent || span.innerText;
  };

  public static generateUniqueString = (length = 8) => {
    const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';

    if (length > characters.length) {
      throw new Error(`Maximum length is ${characters.length}`);
    }

    let uniqueString = '';

    for (let i = 0; i < length; i++) {
      const randomIndex = Math.floor(Math.random() * characters.length);
      uniqueString += characters.charAt(randomIndex);
    }

    return uniqueString;
  };

  public static truncate(text: string, maxLength: number) {
    if (!text || text.length < maxLength) return text;
    return `${text.slice(0, maxLength - 1)}…`;
  }

  public static getTextWidthPx(text: string, fontSize = '12px') {
    const tempSpan = document.createElement('span');
    const textNode = document.createTextNode(text);

    tempSpan.style.display = 'hidden';
    tempSpan.style.fontSize = fontSize;
    tempSpan.appendChild(textNode);

    document.body.appendChild(tempSpan);
    let width = tempSpan.getBoundingClientRect().width;
    document.body.removeChild(tempSpan);

    return width;
  }

  public static toStartCase = (text: string, spaceSeparator = ' '): string => {
    return text
      .split(spaceSeparator)
      .map((t) => `${t.charAt(0).toUpperCase()}${t.substring(1)}`)
      .join(' ');
  };
}
