export enum PageSelectionCriteria {
  First = 0,
  Last = 1,
  Range = 2,
}

export interface IContentCriteria {
  contentCriteriaType: string;
  pageSelection: PageSelectionCriteria;
  pageRange: string;
  onlyIfOnSpecificPages: boolean;
}

export class ContentCriteria implements IContentCriteria {
  public contentCriteriaType: string;
  public pageSelection: PageSelectionCriteria;
  public pageRange: string;
  public onlyIfOnSpecificPages: boolean;

  public constructor(initializer: IContentCriteria) {
    this.contentCriteriaType = initializer?.contentCriteriaType ?? null;
    this.pageSelection = initializer?.pageSelection ?? PageSelectionCriteria.First;
    this.pageRange = initializer?.pageRange ?? '';
    this.onlyIfOnSpecificPages = initializer?.onlyIfOnSpecificPages ?? false;
  }

  public serializable() {
    return {
      contentCriteriaType: this.contentCriteriaType,
      pageSelection: this.pageSelection,
      pageRange: this.pageRange,
      onlyIfOnSpecificPages: this.onlyIfOnSpecificPages,
    };
  }

  public static create(cc: IContentCriteria): ContentCriteria {
    if (cc.contentCriteriaType == 'RegexContentCriteria') return new RegexContentCriteria(cc);
    if (cc.contentCriteriaType == 'LiteralContentCriteria') return new LiteralContentCriteria(cc);
    if (cc.contentCriteriaType == 'WildcardContentCriteria') return new WildcardContentCriteria(cc);

    throw new Error(`Unsupported ContentCriteriaType ${cc.contentCriteriaType}`);
  }
}

export enum ContentCriteriaType {
  RegexContentCriteria = 'RegexContentCriteria',
  LiteralContentCriteria = 'LiteralContentCriteria',
  WildcardContentCriteria = 'WildcardContentCriteria',
}

