interface IContent {
  type: 'BarcodeContent' | 'StampContent' | 'TextContent' | 'ImageContent';
}

interface ITextContent extends IContent {
  fontFamily: string;
  fontSize: number;
  mode: ContentTextModes;
  color: string;
  text: string;
}

interface IStampContent extends IContent {
  stamp: string;
}

interface IBarcodeContent extends IContent {
  barcodeType: string;
  barcodeValue: string;
}

interface IImageContent extends IContent {
  base64: string;
}

interface ILocation {
  type: 'RelativeLocation' | 'SpecificLocation' | 'StretchLocation';
}

interface IRelativeLocation {
  horizontal: HorizontalLocations;
  vertical: VerticalLocations;
}

interface ISpecificLocation {
  top: number;
  topUnits: LengthUnits;
  left: number;
  leftUnits: LengthUnits;
}

interface IStretchLocation {
  insertAt: VerticalLocations;
  horizontalAlignment: HorizontalLocations;
}

export class DocumentStampWorkflowStep extends WorkflowStep {
  content: IContent & IStampContent & IBarcodeContent & IImageContent & ITextContent;
  location: ILocation & IRelativeLocation & ISpecificLocation & IStretchLocation;
  options: {
    rotationDegrees: number;
    applyToPages: ApplyToPages;
  };

  constructor(initializer: any) {
    super(initializer);

    if (!initializer.content) throw new Error('Invalid stamp content');
    if (!initializer.location) throw new Error('Invalid stamp location');
    if (!initializer.options) throw new Error('Invalid stamp options');

    this.content = cloneDeep(initializer.content);
    this.location = cloneDeep(initializer.location);
    this.options = cloneDeep(initializer.options);
  }

  clone = (): WorkflowStep => new DocumentStampWorkflowStep(this);

  serializable = (): any => ({
    ...super.serializable(),
    content: this.content,
    location: this.location,
    options: this.options,
  });
}
