import { Subject } from 'rxjs';

import { IMetaDataService } from '../interop/MetaDataService';
import { LookupMatch, MetaDataLookupDataSource } from './lookup-models';
import { CascadingOptionsFieldDataSource } from './metadata-cascading-options-datasource';
import { MetaDataDefinition, MetaDataType } from './metadata-definition';
import { MetaDataListDataSource } from './metadata-list-datasource';

export interface IFieldOptions {
  name: string;
  value: string;
  disabled?: boolean;
  isSeparator?: boolean;
  style?: string;
  isInputStyled?: boolean;
  useValueForSubstitution?: boolean;
}

export interface ICascadingFieldOptions extends IFieldOptions {
  metaDataId: string;
}

export class CascadingFieldOptions implements ICascadingFieldOptions {
  constructor(
    public name: string,
    public value: string,
    public metaDataId: string
  ) {}

  public serializable(): any {
    return { name: this.name, value: this.value, metaDataId: this.metaDataId };
  }
}

export interface ICascadingOptionsFilter {
  datasourceId: string;
  displayColumnId: string;
  valueColumnId: string;
  filters: ColumnValue[];
}

export class CascadingOptionsFilter implements ICascadingOptionsFilter {
  constructor(
    public datasourceId: string,
    public displayColumnId: string,
    public valueColumnId: string,
    public filters: ColumnValue[]
  ) {}
}

export class ColumnValue {
  constructor(
    public columnId: string,
    public value: string
  ) {}
}

export interface IFieldDataSource {
  changed: Subject<any>;

  getItems(
    startsWith: string,
    currentValue: string,
    successCallBack: (items: Array<IFieldOptions>, matches?: Array<LookupMatch>) => void,
    failureCallBack: (err: any) => void
  ): void;
}

export class FieldDataSource {
  static create = (mdd: MetaDataDefinition, metaDataService: IMetaDataService): IFieldDataSource => {
    if (mdd.type == MetaDataType.Lookup) return new MetaDataLookupDataSource(mdd, metaDataService);
    if (mdd.type == MetaDataType.CascadingOptions) return new CascadingOptionsFieldDataSource(mdd, metaDataService);

    return new MetaDataListDataSource(mdd, metaDataService);
  };
}

class NoopFieldDataSource implements IFieldDataSource {
  changed = new Subject<void>();

  getItems(startsWith: string, currentValue: string): Array<IFieldOptions> {
    return new Array<IFieldOptions>();
  }
}

export enum FieldDisplayMode {
  vertical = 0,
  horizontal = 1,
  grid = 2,
}

export class FieldDefinition {
  label = '';
  smallLabel = '';
  type: MetaDataType = MetaDataType.Text;
  searchable: boolean = false;
  allowNoSelection: boolean;
  placeholder = '';
  datasource: IFieldDataSource = new NoopFieldDataSource();
  required: boolean = false;
  hasValidation: boolean = false;
  tooltip: string = '';
  dateFieldExpectedFormat = 'MM/DD/YYYY';
  substitutable: boolean;
  displayMode: FieldDisplayMode = FieldDisplayMode.vertical;
  hideLabel = false;
  allowNegativeNumbers: boolean = true;
  stickyHeader: string;
  fireChangeEventIfSameValue: boolean = false;
  defaultValue: string = '';
  id: string = '';
  autosizeMinRows: number;
  scrollHeight: string;
  infoText: string = '';
  canShowPassword: boolean = true;

  constructor(initializer?: Partial<FieldDefinition>) {
    if (initializer) {
      this.label = initializer.label || this.label;
      this.smallLabel = initializer.smallLabel || this.smallLabel;
      this.type = initializer.type || this.type;
      this.searchable = initializer.searchable || this.searchable;
      this.placeholder = initializer.placeholder || this.placeholder;
      this.datasource = initializer.datasource || this.datasource;
      this.required = initializer.required || this.required;
      this.hasValidation = initializer.hasValidation || this.hasValidation;
      this.tooltip = initializer.tooltip || this.tooltip;
      this.substitutable = initializer.substitutable || this.substitutable;
      this.hideLabel = initializer.hideLabel || this.hideLabel;
      this.allowNegativeNumbers =
        typeof initializer.allowNegativeNumbers === 'undefined' ? true : initializer.allowNegativeNumbers;
      this.stickyHeader = initializer.stickyHeader || this.stickyHeader;
      this.fireChangeEventIfSameValue = initializer.fireChangeEventIfSameValue || this.fireChangeEventIfSameValue;
      this.defaultValue = initializer.defaultValue;
      this.dateFieldExpectedFormat = initializer.dateFieldExpectedFormat || this.dateFieldExpectedFormat;
      this.id = initializer.id || this.id;
      this.autosizeMinRows = initializer.autosizeMinRows;
      this.scrollHeight = initializer.scrollHeight;
      this.infoText = initializer.infoText || this.infoText;
      this.canShowPassword = typeof initializer.canShowPassword === 'undefined' ? true : initializer.canShowPassword;
    }
  }
}
