import { TranslateService } from '@ngx-translate/core';
import { FixedDataSource, MetaDataType } from '../..';
import { UserStateService } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { IFieldOptions } from './field-definition';
import { SystemMetaData } from '../../../Bamba.Web/ClientApp/src/app/blocks/core/systemMetaData';

export class MetadataIntellisenseDatasource extends FixedDataSource {
  constructor(userStateService: UserStateService) {
    const metadata: Array<IFieldOptions> = [];

    for (const mdd of userStateService.user.metaData) {
      if (mdd.type === MetaDataType.LineItems) continue;

      metadata.push({ name: mdd.name, value: mdd.id });
    }

    super(metadata);
  }
}

export class MetadataWithDocumentNameDatasource extends MetadataIntellisenseDatasource {
  constructor(userStateService: UserStateService, translateService: TranslateService) {
    super(userStateService);

    this.options.push({
      name: translateService.instant('metadata-datasource.document-name'),
      value: SystemMetaData.OriginalDocumentName,
      useValueForSubstitution: true,
    });
  }
}
