import { EditorState, blockNodes, changeTextBlock } from '@progress/kendo-editor-common';
import { InlineStyle, TemplateStyle } from './../../.../../../../views/admin-olc/models/template';
import { Transaction, Node } from '@progress/kendo-angular-editor';
import { mapInlineStylesToString } from './inline-styles';

export type AlignmentType = 'left' | 'right' | 'center' | 'justify' | null;

export const applyBlockStyleFormat =
  (style: TemplateStyle = null, alignment: AlignmentType = null) =>
  (state: EditorState, dispatch: (tr: Transaction) => void) => {
    const blocks = blockNodes(state);
    const tr = state.tr;
    const nodes = state.schema.nodes;

    blocks.forEach((block: Node) => {
      if (block.type.isTextblock && !block.type.spec.isConditionalContent) {
        let newAttrs = {};

        newAttrs = addClassAndStyles(block, style?.classes?.trim(), style?.inlineStyles, alignment);

        if (!style?.element || alignment) {
          // add styles without changing tag name
          changeTextBlock(tr, block, block.type, newAttrs);
        } else if (/^h[1-6]$/i.test(style.element)) {
          const level = parseInt(style.element.substr(1), 10);
          changeTextBlock(tr, block, nodes.heading, { ...newAttrs, level });
        } else if (/^p$/i.test(style.element)) {
          changeTextBlock(tr, block, nodes.paragraph, newAttrs);
        } else if (/^div$/i.test(style.element)) {
          changeTextBlock(tr, block, nodes.div, newAttrs);
        } else if (/^pre$/i.test(style.element)) {
          changeTextBlock(tr, block, nodes.pre, newAttrs);
        } else {
          changeTextBlock(tr, block, nodes[style.id], newAttrs);
        }
      }
    });

    const result = tr.docChanged;

    if (result) dispatch(tr.scrollIntoView());

    return result;
  };

const addClassAndStyles = (node: Node, classes: string, styles: InlineStyle[], alignment: AlignmentType = null) => {
  let style;
  let classAttribute;

  if (!alignment) {
    style = mapInlineStylesToString(styles) || null;
    classAttribute = classes || null;
  } else {
    if (node.attrs.style) {
      style =
        `text-align: ${alignment};` +
        node.attrs.style
          .split(';')
          .filter((str) => !str.toLowerCase().includes('text-align'))
          .join(';');
    } else {
      style = `text-align: ${alignment};`;
    }

    classAttribute = node.attrs.class;
  }

  return {
    ...node.attrs,
    style,
    class: classAttribute,
  };
};
