import {
  AfterViewInit,
  ChangeDetectorRef,
  Component,
  ElementRef,
  HostListener,
  isDevMode,
  OnDestroy,
  OnInit,
  Pipe,
  PipeTransform,
  Renderer2,
  ViewChild,
  ViewContainerRef,
  ViewEncapsulation,
} from '@angular/core';

import { merge, Subscription } from 'rxjs';
import { take } from 'rxjs/operators';
import { UserStateService } from './blocks/services/user-state.service';

import { DomSanitizer } from '@angular/platform-browser';
import { NavigationCancel, NavigationEnd, NavigationError, NavigationStart, Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { Action, ActionEvent } from './blocks/core/actions';
import { KeyboardActionMapping } from './blocks/core/keyboardActionMapping';
import { NgxSpinnerService } from './blocks/ngx-spinner/src/public_api';
import { ActionService } from './blocks/services/action.service';
import { BackButtonService } from './blocks/services/back-button.service';
import { InProgressService, ProgressData } from './blocks/services/in-progress.service';
import { LoadAppStateService } from './blocks/services/load-app-state.service';
import { MyfilesService } from './blocks/services/myfiles.service';
import { SpinnerStateService } from './blocks/services/spinner-state.service';
import { DocumentCaptureService } from './views/document-capture/capture-services';

import { DeviceDetectorService } from 'ngx-device-detector';
import { filter } from 'rxjs/operators';
import {
  Analytics,
  AuthService,
  BrandDetails,
  BrandingService,
  DEFAULT_LOCALE,
  DelayService,
  Languages,
  PrintToService,
  SessionStorageService,
  StickyFieldsService,
  UserPreferencesService,
} from 'shared-code-lib';
import { LookupModalService } from '../../../../Bamba.Shared/src/fields/lookup/lookup-modal/lookup-modal.service';
import { Filename } from './blocks/core/fileName';
import { PrintPdfFileService } from './blocks/services/print-pdf-file.service';
import { SelectFilesService } from './blocks/services/select-files.service';
import { VerticalNavService } from './blocks/services/vertical-nav.service';

declare const _google_analytics_id: string;
declare var CefSharp: any;

@Pipe({ name: 'safe' })
export class SafePipe implements PipeTransform {
  constructor(private sanitizer: DomSanitizer) {}
  transform(url) {
    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }
}

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class AppComponent implements OnInit, OnDestroy, AfterViewInit {
  title = 'Bamba';
  iframeUri = '';
  locale;
  spinnerText = 'Working on it';
  spinnerLeft = 0;
  spinnerTop = 0;
  spinnerRight = 0;
  spinnerBottom = 0;
  spinnerHeight = 0;
  spinnerWidth = 0;
  logoutCountdownFormatted = { countdownTime: '' };

  subscriptions = new Subscription();

  idleTimeModalInstance: NgxSmartModalComponent;
  timeOutModalInstance: NgxSmartModalComponent;

  inProgressModal: NgxSmartModalComponent;
  inProgressState: ProgressData;
  inProgressTitle = '';

  documentConversionModal: NgxSmartModalComponent;
  submitToWorkflowModal: NgxSmartModalComponent;
  showSubmitToWorkflowComponent = false;
  workitemPropertiesModal: NgxSmartModalComponent;
  deviceCSVImportModal: NgxSmartModalComponent;
  datasourceCSVImportModal: NgxSmartModalComponent;
  datasourceRowModal: NgxSmartModalComponent;
  qrCodeModal: NgxSmartModalComponent;
  updateUserProperties: NgxSmartModalComponent;

  showWorkitemPropertiesComponent = false;
  currentWorkitemId: string;

  showModalUpdateItegratedAppSettings = false;

  showModal = {};

  isPrintTo: boolean;
  isRegistering: boolean;
  isAuthenticated: boolean;
  isMobileView = false;
  isFaxMobile = false;
  spinnerElement: any;
  readonly OneMinuteInSeconds = 60;
  readonly TenSeconds = 1000 * 10;
  readonly FiveMinutesInSeconds = this.OneMinuteInSeconds * 5;

  addToHomeScreenPrompt: boolean = false;

  @ViewChild('loaderDiv', { static: true })
  loaderDivRef: ElementRef;
  isModuleLoading: boolean;

  brand: string = '';

  sessionExpired: boolean = false;
  navExpanded = false;
  navHidden = false;
  keepSessionAliveCallBack: any;

  bodyObserver: MutationObserver;
  supportedFileTypes = Filename.supportedFileTypes;

  addToHomeScreenLogo: string;
  addToHomeScreenText: string;
  pwaPopupEvent: any;

  showPrintPdf = false;

  get isIos(): boolean {
    return this.deviceDetector?.os == 'iOS';
  }

  get isAndroid(): boolean {
    return this.deviceDetector?.os == 'Android';
  }

  get isMobileOrFaxMobile() {
    return this.isMobileView || this.isFaxMobile;
  }

  constructor(
    public ngxSmartModalService: NgxSmartModalService,
    private userService: UserStateService,
    public auth: AuthService,
    private spinnerState: SpinnerStateService,
    private spinner: NgxSpinnerService,
    private translate: TranslateService,
    private router: Router,
    private renderer: Renderer2,
    private appState: LoadAppStateService,
    private inProgress: InProgressService,
    private cdr: ChangeDetectorRef,
    private actionService: ActionService,
    private myfiles: MyfilesService,
    public selectFiles: SelectFilesService,
    private capture: DocumentCaptureService,
    private ss: SessionStorageService,
    private brandingService: BrandingService,
    private backButtonService: BackButtonService,
    private analytics: Analytics,
    private stickyFieldService: StickyFieldsService,
    private printToService: PrintToService,
    private elementRef: ElementRef,
    private delayService: DelayService,
    private userPreferencesService: UserPreferencesService,
    public viewContainerRef: ViewContainerRef,
    private verticalNavService: VerticalNavService,
    private deviceDetector: DeviceDetectorService,
    private printPdfFileService: PrintPdfFileService,
    private lookupModalService: LookupModalService
  ) {
    this.analytics.initialize(_google_analytics_id);

    this.subscriptions.add(
      this.userService.localeChanged.subscribe((newLocale) => {
        console.log('localeChanged', newLocale);

        if (newLocale) {
          this.translate.use(newLocale);
        }
      })
    );

    this.subscriptions.add(
      this.userService.userChanged.subscribe((user) => {
        if (!user) return;

        this.sessionExpired = false;
      })
    );

    translate.setDefaultLang(DEFAULT_LOCALE);
    this.translate.addLangs(['en-US', 'es', 'de', 'fr', 'it', 'pt', 'pt', 'zh-CN', 'ru', 'sq', 'he', 'ar', 'da']);

    this.userService.setNewLocal(this.translate.getBrowserCultureLang());

    this.backButtonService.setListenerForPreviousURLChanging();

    this.subscriptions.add(
      this.router.events.subscribe((event) => {
        if (event instanceof NavigationStart) {
          this.isModuleLoading = true;
          this.backButtonService.setModuleLoading(true);

          const activeElement = document.activeElement as HTMLElement;
          if (activeElement) activeElement.blur();

          this.translate
            .get('Common.LoadingModule')
            .pipe(take(1))
            .subscribe((message) => this.spinnerState.show(message, this.loaderDivRef.nativeElement));

          this.routeAuthentication();
          this.routeLanguageDirection();
          if (event.navigationTrigger === 'popstate') {
            this.ngxSmartModalService.closeAll();
          }
        } else if (
          event instanceof NavigationEnd ||
          event instanceof NavigationCancel ||
          event instanceof NavigationError
        ) {
          if (this.isModuleLoading) {
            this.isModuleLoading = false;

            this.translate
              .get('Common.LoadingModule')
              .pipe(take(1))
              .subscribe((message) => this.spinnerState.hide(message));
          }

          this.backButtonService.setModuleLoading(false);
          this.isRegistering = event.url && event.url.indexOf('/account-register') != -1;
        }
      })
    );

    this.subscriptions.add(
      this.brandingService.onBrandingChanged.subscribe((brand) => {
        this.brand = brand;
      })
    );

    if (this.shouldPwaPromptBeDisplayed()) this.addToHomeScreenPrompt = true;

    this.subscriptions.add(this.inProgress.onClose.subscribe(this.onCloseProgress));
    this.subscriptions.add(this.inProgress.onOpen.subscribe(this.onOpenProgress));
    this.subscriptions.add(this.inProgress.onDisplay.subscribe(this.onDisplayProgress));
    this.subscriptions.add(this.actionService.onActivateAction.subscribe(this.invokeAction));
    this.subscriptions.add(this.auth.onSessionExpired.subscribe(this.onSessionExpired));
    this.subscriptions.add(this.auth.onLogout.subscribe(this.onLogOut));
    this.subscriptions.add(this.userService.userProfileLoaded.subscribe(this.onUserProfileLoaded));
    this.subscriptions.add(this.brandingService.onBrandDetailsUpdated.subscribe(this.onBrandDetailsUpdated));

    if (typeof CefSharp != 'undefined')
      this.delayService.execute(() => {
        CefSharp.BindObjectAsync().then(() => {
          this.isPrintTo = this.printToService.isPrintToMode;
          if (this.isPrintTo) this.elementRef.nativeElement.style.setProperty('--header-height', '0px');
        });
      }, 0);
  }

  onLogOut = (): void => {
    this.stickyFieldService.clear();
  };

  invokeAction = (event: ActionEvent): void => {
    if (event.action !== Action.CloseLatestEscapableModal) return;

    try {
      const latestOpenedModal = this.ngxSmartModalService.getTopOpenedModal();

      if (!latestOpenedModal || !latestOpenedModal.escapable) return;

      latestOpenedModal.close();
    } catch (error) {}
  };

  private onSessionExpired = (): void => {
    this.sessionExpired = true;

    const openedModals = this.ngxSmartModalService.getOpenedModals();
    const timeoutModalIndex = openedModals.findIndex((modal) => modal.id === 'timeOutModal');

    if (timeoutModalIndex === -1) {
      this.timeOutModalInstance.open();
    }
  };

  installApp() {
    if (!this.isAndroid) return;
    if (!this.pwaPopupEvent) return;

    this.addToHomeScreenPrompt = false;

    this.pwaPopupEvent.prompt();
    this.pwaPopupEvent.userChoice.then((choice) => {
      if (choice.outcome !== 'accepted') this.addToHomeScreenPrompt = true;
    });
  }

  @HostListener('window:beforeinstallprompt', ['$event'])
  onBeforeinstallprompt(event): void {
    event.preventDefault();
    this.pwaPopupEvent = event;

    if (this.shouldPwaPromptBeDisplayed()) this.addToHomeScreenPrompt = true;
  }

  @HostListener('window:appinstalled', ['$event'])
  onInstallApp(event): void {
    localStorage.setItem('appInstalled', 'true');
  }

  @HostListener('document:keydown', ['$event'])
  onKeydown(event: KeyboardEvent): void {
    if (!event) return;

    const actionEvent = KeyboardActionMapping.getFor(event);
    if (!actionEvent) return;

    this.disableEventPropagation(event);
    this.actionService.activateAction(actionEvent);
  }

  isDragSourceExternalFile(dataTransfer: any): boolean {
    if (typeof Clipboard != 'undefined') {
      if (dataTransfer.constructor == Clipboard) {
        if ((dataTransfer as any).files.length > 0) return true;
        else return false;
      }
    }

    if (typeof DOMStringList != 'undefined') {
      const DragDataType = dataTransfer.types;
      if (DragDataType.constructor == DOMStringList) {
        if (DragDataType.contains('Files')) return true;
        else return false;
      }
    }

    if (typeof Array != 'undefined') {
      const DragDataType = dataTransfer.types;
      if (DragDataType.constructor == Array) {
        if (DragDataType.indexOf('Files') != -1) return true;
        else return false;
      }
    }

    return false;
  }

  onBrandDetailsUpdated = (brandDetails: BrandDetails): void => {
    let brandName = brandDetails.titleText;
    let logoUrl = brandDetails.favIconUrl;

    if (this.brand == 'ar') {
      brandName = this.translate.instant('mobile-capture.accuRoute-capture');
      logoUrl = 'assets/pwa-icons/Artboard-152x152-ar.png';
    }

    if (this.brand == 'hpcr') {
      brandName = this.translate.instant('mobile-capture.hp-capture');
      logoUrl = 'assets/pwa-icons/Artboard-152x152-hpcr.png';
    }

    this.addToHomeScreenText = `${this.translate.instant(
      'mobile-capture.install'
    )} ${brandName} ${this.translate.instant('mobile-capture.on-your-device')}`;

    this.addToHomeScreenLogo = logoUrl;
    this.updateIosPwaTitle(brandName);
  };

  updateIosPwaTitle(title: string) {
    const appleTitleMetaTag = document.getElementById('apple-mobile-web-app-title-meta');
    appleTitleMetaTag?.setAttribute('content', title);
  }

  disableEventPropagation = (e: KeyboardEvent): void => {
    if (e) {
      if (e.stopPropagation) {
        e.stopPropagation();
      } else if (window.event) {
        window.event.cancelBubble = true;
      }
    }

    event.preventDefault();
  };

  onCloseProgress = (): void => {
    this.inProgressModal.close();
    this.inProgressState = null;
  };

  onOpenProgress = (text: string): void => {
    if (!this.inProgressModal) return;

    this.inProgressTitle = `${text}`;
    this.inProgressState = null;

    this.inProgressModal.open();
  };

  onDisplayProgress = (progress: ProgressData): void => {
    if (!this.inProgressModal) return;

    this.inProgressState = progress;

    this.cdr.detectChanges();
  };

  onUserProfileLoaded = (): void => {
    this.userService.setIdleTimeOut(this.onStartIdle);
  };

  onStartIdle = () => {
    if (this.userService.auth.isLoggedOut() || this.sessionExpired) {
      return;
    }

    this.userService.clearIdleTimeOut();

    this.userService.logout(
      this.idleTimeModalInstance,
      this.logoutCountdownFormatted,
      this.FiveMinutesInSeconds,
      this.timeOutModalInstance
    );
  };

  ngOnInit() {
    window.addEventListener(
      'dragover',
      (e) => {
        if (e) {
          if (this.isDragSourceExternalFile(e.dataTransfer)) {
            e.preventDefault();
          }
        }
      },
      false
    );
    window.addEventListener(
      'drop',
      (e) => {
        if (e) {
          if (this.isDragSourceExternalFile(e.dataTransfer)) {
            e.preventDefault();
          }
        }
      },
      false
    );

    this.configureSpinner();

    // load global data from server
    this.isAuthenticated = this.auth.isLoggedIn();
    this.isMobileView = this.ss.getIsMobile();
    this.isFaxMobile = this.ss.getIsInterFaxMobile();

    if (this.spinnerElement == null) {
      this.spinnerElement = document.getElementById('appview');
    }

    if (this.isAuthenticated && isDevMode()) {
      this.loadState();
    }

    this.userService.setupLocale();

    this.subscriptions.add(
      merge(
        this.router.events.pipe(filter((event) => event instanceof NavigationEnd)),
        this.userPreferencesService.preferencesChanged
      ).subscribe(this.updateNav)
    );

    this.subscriptions.add(this.printPdfFileService.show$.subscribe((show) => (this.showPrintPdf = show)));

    this.lookupModalService.setRootViewContainer(this.viewContainerRef);
  }

  updateNav = (): void => {
    this.isAuthenticated = this.auth.isLoggedIn();
    this.isMobileView = this.ss.getIsMobile();
    this.isFaxMobile = this.ss.getIsInterFaxMobile();

    this.navHidden =
      !this.isAuthenticated || this.isRegistering || this.isMobileView || this.isFaxMobile || this.isPrintTo;

    this.verticalNavService.onToggleVerticalNav$
      .pipe(take(1))
      .subscribe((isExpanded) => (this.navExpanded = isExpanded));
  };

  routeAuthentication() {
    this.isAuthenticated = this.auth.isLoggedIn();
    this.isMobileView = this.ss.getIsMobile();
    this.isFaxMobile = this.ss.getIsInterFaxMobile();

    if (!this.isAuthenticated) {
      this.renderer.addClass(document.body, 'login');
    } else {
      this.renderer.removeClass(document.body, 'login');
    }
  }

  routeLanguageDirection() {
    if (Languages.isRTLLanguage()) {
      this.renderer.addClass(document.body, 'rtl');
    } else {
      this.renderer.removeClass(document.body, 'rtl');
    }
  }

  expiredSessionCallBack = () => {
    const isMobileView = this.ss.getIsMobile();
    const isFaxMobile = this.ss.getIsInterFaxMobile();

    this.timeOutModalInstance.close();
    this.auth.logout();
    this.userService.clearUser();

    if (isFaxMobile) {
      this.router.navigateByUrl('/fax-mobile/login');
      return;
    }

    if (isMobileView) {
      this.router.navigateByUrl('/mobile/login');
      return;
    }

    this.router.navigateByUrl('/login');
  };

  private configureSpinner() {
    this.spinner.hide();

    this.subscriptions.add(this.spinnerState.visibilityChanged.subscribe(this.spinnerVisibilityChanged));
  }

  private spinnerVisibilityChanged = (request: any) => {
    if (request.visible === true) {
      let height: number = request.height;
      if (height < 50 && !this.isMobileView) height = window.innerHeight - (request.top + 20);

      this.spinnerText = request.text;
      this.spinnerTop = request.top;
      this.spinnerLeft = request.left;
      this.spinnerHeight = height;
      this.spinnerWidth = request.width;

      this.spinner.show();
      this.cdr.detectChanges();
    } else {
      this.spinner.hide();
    }
  };

  ngOnDestroy() {
    this.subscriptions.unsubscribe();
  }

  ngAfterViewInit() {
    this.idleTimeModalInstance = this.ngxSmartModalService.getModal('idleTimeModal');
    this.timeOutModalInstance = this.ngxSmartModalService.getModal('timeOutModal');
    this.inProgressModal = this.ngxSmartModalService.getModal('inProgressDialog');
    this.submitToWorkflowModal = this.ngxSmartModalService.getModal('submitToWorkflow');
    this.workitemPropertiesModal = this.ngxSmartModalService.getModal('workitemProperties');
    this.documentConversionModal = this.ngxSmartModalService.getModal('AccuRouteDocumentConversion');

    this.connectModalEvents('OneDriveCopyToModal');
    this.connectModalEvents('ScanToModal');
    this.connectModalEvents('CreateRoutingSheet');
    this.connectModalEvents('interfaxResetUserPassword');
    this.connectModalEvents('interfaxRepeatOrder');
    this.connectModalEvents('interfaxResendNotificationsModal');
    this.connectModalEvents('interfaxTransferOwnerModal');
    this.connectModalEvents('interfaxShareModal');
    this.connectModalEvents('interfaxDocumentPropertiesModal');
    this.connectModalEvents('interfaxCostCenterModal');
    this.connectModalEvents('interfaxCustomPropertyModal');
    this.connectModalEvents('interfaxGroupModal');
    this.connectModalEvents('interfaxAppPasswordModal');
    this.connectModalEvents('interfaxIPRangeModal');
    this.connectModalEvents('interfaxContactImportModal');
    this.connectModalEvents('interfaxContactModal');
    this.connectModalEvents('AccuRouteDocumentConversion');
    this.connectModalEvents('interfaxContactImportModal');
    this.connectModalEvents('interfaxContactImportModal');
    this.connectModalEvents('deviceCSVImportModal');
    this.connectModalEvents('datasourceCSVImportModal');
    this.connectModalEvents('datasourceRowModal');
    this.connectModalEvents('qrCodeModal');
    this.connectModalEvents('updateUserProperties');
    this.connectModalEvents('ImportWorkflowModal');
    this.connectModalEvents('addResolvedTicketModal');
    this.connectModalEvents('componentDeploymentSchedulingModal');
    this.connectModalEvents('removeJiraTicketModal');
    this.connectModalEvents('addDatabaseResolvedTicketModal');
    this.connectModalEvents('addExternalResolvedTicketModal');
    this.connectModalEvents('addJiraNotesModal');
    this.connectModalEvents('setComponentVersion');
    this.connectModalEvents('ViewWorkflowPermissions');
    this.connectModalEvents('interfaxContactUsModal');
    this.connectModalEvents('uploadOLCTemplate');
    this.connectModalEvents('replaceOLCTemplatePackage');
    this.connectModalEvents('uploadOLCMedia');
    this.connectModalEvents('RollBackModal');
    this.connectModalEvents('SMPushModal');
    this.connectModalEvents('createApprovalModal');
    this.connectModalEvents('approveTemplateModal');
    this.connectModalEvents('rejectTemplateModal');
    this.connectModalEvents('submitTemplateToProductionModal');
    this.connectModalEvents('resendFaxModal');
    this.connectModalEvents('startQARegressionModal');
    this.connectModalEvents('DeleteTenantDataModal');

    this.subscriptions.add(
      this.idleTimeModalInstance.onOpen.subscribe((modal: NgxSmartModalComponent) => {
        modal.removeData();
      })
    );

    this.subscriptions.add(
      this.timeOutModalInstance.onAnyCloseEvent.subscribe((modal: NgxSmartModalComponent) => {
        modal.removeData();
      })
    );

    this.subscriptions.add(
      this.submitToWorkflowModal.onOpen.subscribe(() => {
        this.showSubmitToWorkflowComponent = true;
      })
    );

    this.subscriptions.add(
      this.submitToWorkflowModal.onClose.subscribe(() => {
        this.showSubmitToWorkflowComponent = false;
      })
    );

    this.subscriptions.add(
      this.workitemPropertiesModal.onOpen.subscribe(() => {
        this.showWorkitemPropertiesComponent = true;

        this.currentWorkitemId = this.capture.getCurrentWorkItem().id;
      })
    );

    this.subscriptions.add(
      this.workitemPropertiesModal.onClose.subscribe(() => {
        this.showWorkitemPropertiesComponent = false;
      })
    );

    this.subscriptions.add(
      this.ngxSmartModalService
        .getModal('modalUpdateItegratedAppSettings')
        .onOpen.subscribe(() => (this.showModalUpdateItegratedAppSettings = true))
    );
    this.subscriptions.add(
      this.ngxSmartModalService
        .getModal('modalUpdateItegratedAppSettings')
        .onClose.subscribe(() => (this.showModalUpdateItegratedAppSettings = false))
    );

    this.addBodyObserver();
  }

  connectModalEvents = (modalId: string): void => {
    const modal = this.ngxSmartModalService.getModal(modalId);

    this.subscriptions.add(modal.onOpen.subscribe((modal: NgxSmartModalComponent) => (this.showModal[modalId] = true)));
    this.subscriptions.add(
      modal.onClose.subscribe((modal: NgxSmartModalComponent) => {
        this.spinnerState.hide();

        if (modal.hideDelay == 0 || modal.hideDelay == 500) {
          this.showModal[modalId] = false;
        } else {
          this.delayService.execute(() => (this.showModal[modalId] = false), modal.hideDelay);
        }
      })
    );
  };

  closeIdleTimeModal = () => {
    this.idleTimeModalInstance.close();
    this.userService.clearIdleTimeOut();
    this.userService.startIdle();
    this.userService.keepSessionAlive();
  };

  loadState = () => {
    this.appState.load(this.spinnerElement, this.stateLoadCompleted, this.stateLoadFailed, this.stateLoadFailed);
  };

  stateLoadCompleted = () => {
    this.spinnerState.hide();
  };

  stateLoadFailed = (err) => {
    this.spinnerState.hide();
  };

  cancelUploadToMyFiles = (): void => {
    this.selectFiles.clear();
    this.ngxSmartModalService.getModal('myfilesupload').close();
  };

  closeWorkitemPropertiesModal = (): void => {
    this.closeModal('workitemProperties');
  };

  uploadToMyFiles = (): void => {
    this.ngxSmartModalService.getModal('myfilesupload').close();
    this.myfiles.upload();
  };

  closeModal = (modalId: string, resetData: boolean = false): void => {
    if (!modalId) return;

    this.ngxSmartModalService.getModal(modalId).close();
    if (resetData) this.ngxSmartModalService.setModalData({}, modalId, true);
  };

  shouldPwaPromptBeDisplayed() {
    const isInStandaloneMode = 'standalone' in window.navigator && (window.navigator as any).standalone;

    const appInstalled = localStorage.getItem('appInstalled') === 'true';
    const isPromptDismissed = localStorage.getItem('PwaPromptDismissed') === 'true';

    return (
      (this.isIos || (this.isAndroid && this.pwaPopupEvent)) &&
      !isInStandaloneMode &&
      !appInstalled &&
      !isPromptDismissed
    );
  }

  closePwaPrompt() {
    this.addToHomeScreenPrompt = false;
    localStorage.setItem('PwaPromptDismissed', 'true');
  }

  addBodyObserver() {
    this.bodyObserver = new MutationObserver((m) => {
      if (document.body.classList.contains('dialog-open')) {
        document.querySelectorAll('#app-spinner-panel .ps').forEach((e) => {
          if (!e.closest('ngx-smart-modal')) {
            e.classList.add('ps-disabled');
            e.classList.remove('ps');
          }
        });
      } else {
        document.querySelectorAll('#app-spinner-panel .ps-disabled').forEach((e) => {
          e.classList.remove('ps-disabled');
          e.classList.add('ps');
        });
      }
    });
    this.bodyObserver.observe(document.body, {
      attributes: true,
    });
  }
}
