import { Component, OnInit, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';

import { Log } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { BambaDetailsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/bamba-details.service';
import { HydraApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';
import { SharedDataService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/shared-data.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { AuthService } from '../../services/auth/auth.service';
import { BrandingService } from '../../services/branding.service';
import { PrintToService } from '../../services/print-to.service';
import { SessionStorageService } from '../../services/session-storage.service';
import { AuthorizationResult, LoginBaseComponent, LoginModes } from '../login-base/login-base.component';
import { FieldDefinition } from './../../models/field-definition';
import { MetaDataType } from './../../models/metadata-definition';
import { DelayService } from './../../utils/delay.service';

@Component({
  selector: 'app-login-password',
  templateUrl: './login-password.component.html',
  styleUrls: ['./login-password.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class LoginPasswordComponent extends LoginBaseComponent implements OnInit {
  fieldPassword: FieldDefinition;
  password = '';
  username = '';

  deviceMode = false;
  printToFaxMode = false;

  constructor(
    private delayService: DelayService,
    private delay: DelayService,
    userStateService: UserStateService,
    authService: AuthService,
    spinnerStateService: SpinnerStateService,
    translateService: TranslateService,
    bds: BambaDetailsService,
    sss: SessionStorageService,
    bs: BrandingService,
    r: Router,
    private printToService: PrintToService,
    private sharedDataService: SharedDataService,
    private route: ActivatedRoute,
    hydraApi: HydraApiService
  ) {
    super(hydraApi, spinnerStateService, translateService, authService, bds, userStateService, sss, bs, r);
  }

  ngOnInit(): void {
    super.ngOnInit();

    this.deviceMode = this.sessionStorageService.getLoginMode() == LoginModes.Device;
    this.printToFaxMode = this.printToService.isPrintToMode;

    if (this.restartLoginProcess()) return;

    this.username = this.sessionStorageService.getUsername();

    this.fieldPassword = new FieldDefinition({
      type: MetaDataType.Password,
      label: this.translateService.instant('Login.Password'),
      placeholder: '',
      required: false,
    });

    if (this.route.snapshot.queryParamMap.get('auto') == 'true') this.autoLogin();
  }

  autoLogin = (): void => {
    this.password = this.sharedDataService.extraParameters;
    this.login();
  };

  onLogin(e) {
    if (!this.password.trim()) return;
    e.preventDefault && e.preventDefault();
    this.login();
  }

  login() {
    this.errorOccurred = false;
    this.isSubmitted = true;

    this.forceBinding();

    this.delayService.execute(() => {
      this.spinnerStateService.show(this.translateService.instant('Login.Sign-In-Message'), this.loginDivElement);

      this.authService.login(
        this.sessionStorageService.getUsername(),
        this.password,
        this.sessionStorageService.getIsMobile(),
        this.loginSuccessCallBack,
        this.loginFailureCallBack
      );
    }, 100);
  }

  loginSuccessCallBack = (ar: AuthorizationResult, username: string) => {
    if (!ar.succeeded) {
      this.spinnerStateService.hide();
      this.isSubmitted = false;

      this.errorOccurred = true;
      this.loginErrorText = ar.errorText || this.translateService.instant('Login.InvalidLoginData');

      this.setFocusToPassword();

      return;
    }

    this.authService.loginPasswordSuccess(ar, username, this.password, this.printToService);
  };

  loginFailureCallBack = (err) => {
    Log.error('login-password.loginFailureCallBack', err);

    this.loginFailure('Login.InvalidLoginData');

    this.setFocusToPassword();
  };

  setFocusToPassword = (): void => {
    this.delay.execute(() => {
      const passwordInput = document.getElementsByClassName('input-cont')[0].querySelector('input');

      if (passwordInput) {
        passwordInput.focus();
        passwordInput.select();
      }
    }, 100);
  };

  forceBinding() {
    const inputs = this.loginDiv.nativeElement.querySelectorAll('input');
    if (inputs.length) {
      for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];
        if (input.id === `field-text-${this.fieldPassword.label}` && input.value !== this.password) {
          this.password = input.value;
        }
      }
    }
  }

  canShowBackButton = (): boolean => this.printToService.isPrintToMode || this.deviceMode;

  goBack = (): void => {
    if (this.deviceMode) {
      this.router.navigate(['/'], { queryParams: { mode: 'device' } });
      return;
    }

    this.router.navigate(['/login'], { queryParams: { returnUrl: '/bamba-sendfax' } });
  };
}
