import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { GridComponent } from '@progress/kendo-angular-grid';
import { SortDescriptor } from '@progress/kendo-data-query';
import { Subscription } from 'rxjs';
import { ItemTableDataSource, ItemsRequest, ItemsResult, SortDirection } from './../models/table-data-source';

import { IFilterValue } from '../../../Bamba.Web/ClientApp/src/app/blocks/models/filter';
import { IAction, SpinnerState } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/models';
import { IItemsDataService } from '../interop/ItemsDataService';
import { ICombinedColumn, IDefaultColumn } from '../models/column';
import { ScanToFolderMobileAction } from '../models/mobile-action';
import { InvokeAction, TableItem } from '../models/table';
import { DelayService } from '../utils/delay.service';
import { Crumb } from './../models/crumb';
import { Pagination } from './../models/pagination';
import { UserPreferencesService } from './../services/user-preferences.service';

enum SelectionMode {
  Folder = 0,
  File = 1,
}

@Component({
  selector: 'app-selection',
  templateUrl: './selection.component.html',
  styleUrls: ['./selection.component.scss'],
})
export class SelectionComponent implements OnInit {
  @Input() action: ScanToFolderMobileAction;
  @Input() mode: SelectionMode = 0;
  @Input() api: IItemsDataService;
  @Input() showBreadcrumb: boolean = true;

  @Output() onFileSelected = new EventEmitter<string>();
  @Output() onFolderSelected = new EventEmitter<string>();
  @Output() onToggleBusy = new EventEmitter<SpinnerState>();
  @Output() onCellClick = new EventEmitter<any>();

  tableItems: Array<TableItem>;
  columns: Array<ICombinedColumn>;
  datasource: ItemTableDataSource;
  sort: SortDescriptor;

  crumbs = new Array<Crumb>();

  currentPage = 1;
  itemsPageCount = 0;
  itemsTotal = 0;
  pageSize = 5;

  loading: boolean = false;
  spinnerMessage: string = '';
  errors: Array<string>;
  loadingFailed: boolean;

  private grid: GridComponent;
  loadItemCount = 25;

  subscriptions = new Subscription();
  datasourceSubscription: Subscription;

  constructor(
    private delay: DelayService,
    private translate: TranslateService,
    private userPreferencesService: UserPreferencesService
  ) {}

  ngOnInit() {
    this.onOpenFolder();
  }

  loadItems = (minNumberToLoad = 0): void => {
    this.tableItems = [];
    this.createDataSource();

    const request = new ItemsRequest();
    const sortColumn = this.columns.find((c) => c.id === this.sort.field);
    const sortByField = sortColumn ? sortColumn.sortByFieldName : '';
    const sortByDirection = this.sort.dir === 'asc' ? SortDirection.Ascending : SortDirection.Descending;

    if (this.currentPage === 0) {
      this.currentPage = 1;
    }

    request.pageNumber = this.currentPage;
    request.pageSize = Math.max(this.pageSize, minNumberToLoad);
    request.sortBy = sortByField;
    request.sortByDirection = sortByDirection;
    request.filters = this.getFilters();

    this.toggleLoadingState({ state: true });

    this.datasource.loadItems(request, (results) => this.itemsLoad(results), this.hideSpinner);
  };

  itemsLoad = (results: ItemsResult): void => {
    this.errors = [];
    this.hideSpinner();

    this.loadingFailed = !results.success;

    if (results.success) {
      this.tableItems = results.items.map((i) => new TableItem(i, this.columns, this.translate));
      this.itemsPageCount = results.items.length;
      this.itemsTotal = results.total;
      if (this.itemsTotal === 0) {
        this.currentPage = 0;
      }

      this.delay.execute(() => this.handleViewingRecords(true));
    } else {
      this.errors = results.errors;
    }
  };

  onRender = (grid: GridComponent): void => {
    this.grid = grid;
    this.handleViewingRecords();
  };

  onInvokeAction = (invokeAction: InvokeAction): void => {
    this.toggleLoadingState({
      state: true,
      message: this.translate.instant('selection-component.executing-action'),
    });

    const reqBody = {
      folderID: this.action.view.folderId,
      actionID: invokeAction.action.id,
      itemIDs: [invokeAction.item.id],
    };

    this.api.postItemtoServer('action/execute', reqBody).subscribe(
      (data) => {
        this.processActionResult(invokeAction.action, data);
      },
      (err) => {
        this.hideSpinner();
        //todo:
      }
    );
  };

  private processActionResult = (action: IAction, data: any): void => {
    this.hideSpinner();

    if (data.result.errors && data.result.errors.length) {
      //todo:
      return;
    }

    switch (data.type) {
      case 'OpenFolder':
        this.onOpenFolder(data.result.folderId);
        break;
    }
  };

  handleViewingRecords = (noreload = false): void => {
    const row = this.grid.ariaRoot.nativeElement.querySelectorAll('tr')[0];
    if (!row) return;

    const rowHeight = row.offsetHeight;

    const availableHeight = this.grid.ariaRoot.nativeElement.offsetHeight - rowHeight;
    let maxHeightOfRows = 0;
    let maxNumberOfRows = 0;
    let maxNumberOfPages = 0;

    for (maxHeightOfRows; availableHeight >= maxHeightOfRows + rowHeight; maxHeightOfRows += rowHeight) {
      maxNumberOfRows++;
    }

    this.pageSize = maxNumberOfRows;
    maxNumberOfPages = Math.ceil(this.itemsTotal / this.pageSize);
    if (maxNumberOfPages < this.currentPage) {
      this.currentPage = maxNumberOfPages;
    }

    if (maxNumberOfRows <= this.tableItems.length) {
      const tis = [];

      for (let row = 0; row < maxNumberOfRows; row++) {
        tis.push(this.tableItems[row]);
      }

      this.tableItems = tis;
      this.itemsPageCount = tis.length;

      return;
    }

    if (!noreload) this.loadItems();
  };

  hideSpinner = (): void => {
    this.toggleLoadingState({ state: false });
  };

  getFilters(): Array<IFilterValue> {
    return this.action.view.filterValues;
  }

  toggleLoadingState = (state: SpinnerState): void => {
    this.onToggleBusy.emit(state);
  };

  createDataSource = (): void => {
    this.datasource = new ItemTableDataSource(this.action.productId, this.action.view.folderId, this.api);
    this.columns = this.getColumns();

    if (this.datasourceSubscription) this.datasourceSubscription.unsubscribe();
    this.datasourceSubscription = this.datasource.onItemsLoaded.subscribe(this.onDataSourceItemsLoaded);

    const defaultSort: SortDescriptor = {
      field: this.action.view.defaultSortByColumn.columnId,
      dir: this.action.view.defaultSortByColumn.direction == SortDirection.Ascending ? 'asc' : 'desc',
    };
    this.sort = this.userPreferencesService.getPreference(`widget-sort-${this.action.view.id}`, defaultSort);
  };

  getColumns(): Array<ICombinedColumn> {
    const columnPreferences: IDefaultColumn[] = this.userPreferencesService.getPreference(
      `widget-${this.action.view.id}`,
      this.action.view.defaultColumns
    );

    const columns: Array<ICombinedColumn> = [];

    for (const column of this.action.view.columns) {
      const columnPreference = columnPreferences.find((c) => c.id == column.id);
      const defaultPreference = this.action.view.defaultColumns.find((c) => c.id == column.id);

      const width = columnPreference ? columnPreference.width : defaultPreference.width;
      const stretch = defaultPreference ? defaultPreference.stretch : false;

      columns.push({
        ...column,
        ...{ id: column.id, width: width, stretch: stretch },
      });
    }

    return columns;
  }

  onDataSourceItemsLoaded = (results: ItemsResult): void => {
    this.crumbs = results.crumbs ? results.crumbs.map((c) => new Crumb(c)).slice() : [];
  };

  onCrumbClicked = (crumb: Crumb): void => {
    this.onOpenFolder(crumb ? crumb.folderId : null);
  };

  onOpenFolder = (folderId: string = null): void => {
    this.currentPage = 1;
    this.itemsPageCount = this.itemsTotal = 0;

    this.action.view.folderId = folderId || this.action.view.folderId;

    this.loadItems(this.loadItemCount);
    this.loadItemCount = this.pageSize;

    this.onFolderSelected.emit(this.action.view.folderId);
  };

  onSaveColumnWidths = (columns: Array<IDefaultColumn>): void => {
    this.userPreferencesService.setPreference(`widget-${this.action.view.id}`, columns);
  };

  onLoadPage = (pagination: Pagination): void => {
    this.currentPage = pagination.pageNumber;
    this.loadItems();
  };

  onSort = (sd: SortDescriptor): void => {
    this.sort = sd;
    this.userPreferencesService.setPreference(`widget-sort-${this.action.view.id}`, this.sort);

    this.loadItems();
  };

  cellClick = (event: any): void => {
    this.onCellClick.emit(event);
  };

  ngOnDestroy(): void {
    if (this.datasourceSubscription) this.datasourceSubscription.unsubscribe();
  }
}
