import { Injectable } from '@angular/core';
import { CanvasState } from '../models/canvas-state';
import {
  IConditionalContentSelection,
  IConnectTemplate,
  ITEDCondition,
  ITEDPayloadState,
  ItemToAddOrEdit,
  LengthUnit,
  MousePosition,
} from '../models/ted-state';
import { ClearZone } from '../models/clear-zone';
import { ITemplateVariable, ITemplateVariablesHighlight, Template } from '../../../models/template';
import { BehaviorSubject, Subject } from 'rxjs';
import { Style } from '../../../models/style';
import { Snippet } from '../../../models/snippet';
import { OlcTedPublicTemplateRefreshService } from './olc-ted-public-template-refresh.service';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { MeasurementUnit } from '../../../../../../../../../Bamba.Shared/src/models/tenant';

@Injectable({
  providedIn: 'root',
})
export class OlcTedPublicTemplateEditorService {
  mmToPxScale = 3.77952;
  cmToPxScale = 37.79527;
  inToPxScale = 96;
  ptToPxScale = 1.33333;
  defaultUnit: LengthUnit;

  onEditText = new Subject<void>();
  onEditImage = new Subject<void>();
  onEditBodyText = new Subject<void>();
  onEditBackground = new Subject<void>();

  onReset = new Subject<void>();

  private templateBehaviorSubject = new BehaviorSubject<Template>(null);
  template$ = this.templateBehaviorSubject.asObservable();

  private templateCustomStylesBehaviorSubject = new BehaviorSubject<Style[]>([]);
  templateCustomStyles$ = this.templateCustomStylesBehaviorSubject.asObservable();

  private templateSnippetsBehaviorSubject = new BehaviorSubject<Snippet[]>([]);
  templateSnippet$ = this.templateSnippetsBehaviorSubject.asObservable();

  private canvasStateBehaviorSubject = new BehaviorSubject<CanvasState>(new CanvasState());
  canvasState$ = this.canvasStateBehaviorSubject.asObservable();

  templateID: string = ''; // current template id
  versionId: string = ''; // current version id
  templateConditions: ITEDCondition[] = []; // conditions from the Connect  (orphaned)
  templateName = ''; // current template name
  templateVariables: ITemplateVariable[] = []; // variables from the template
  templateVariablesHighlight: ITemplateVariablesHighlight; // variables_highlight from the template
  templateClearZones: ClearZone[] = []; // clear areas where object shouldn't be added over (orphaned)
  templateCustomerName; // Current template sub customer name if any

  // TODO: define types for connect template data
  connectTemplate: IConnectTemplate = {
    options: null,
    package: null,
    recordCount: 0,
  }; // JSON object containing the index.xml of the connect template

  currentDisplayPage = 0; //which page are we displaying
  currentRecord = 0; // data record for preview
  currentSection = 0;

  isPageSelected = true;
  isSectionSelected = false;

  payload: ITEDPayloadState;
  conditionalContentSelections: IConditionalContentSelection[];

  inMediaSelection = false;
  mediaPDF: any = [];

  mouse: MousePosition = null; // mouse position on the canvas

  snippetCache: any = {}; // cache for snippet
  snippetGroupMenu: any = '';
  snippetMenu: any = '';
  snippetPendingRequest = 0; // pending snippet request to WP
  styleList: any[] = []; // list of custom styles to be added to TinyMCE
  OrStyle = false; //
  // @see no global for group list.

  tree: any = null; // sidebar tree instance

  saveToHistory = true;
  undo: ITEDPayloadState[] = [];
  undoIndex = -1;

  constructor(private ngxSmartModalService: NgxSmartModalService) {}

  setCurrentTemplate(template: Template) {
    this.templateBehaviorSubject.next(template);
  }

  setTemplateCustomStyles(styles: Style[]) {
    this.templateCustomStylesBehaviorSubject.next(styles);
  }

  setTemplateSnippets(snippets: Snippet[]) {
    this.templateSnippetsBehaviorSubject.next(snippets);
  }

  setCanvasState(canvasState: CanvasState, shouldRedrawCanvas = false) {
    canvasState.isClean = !shouldRedrawCanvas;
    this.canvasStateBehaviorSubject.next(canvasState);
  }

  resetUndoState() {
    this.saveToHistory = true;
    this.undo = [];
    this.undoIndex = -1;
  }

  convertPixelTo = (value: number, unit: LengthUnit = this.defaultUnit) => {
    if (value == 0) return '0';

    return (value / this.getScale(unit)).toFixed(2);
  };

  zoomIn() {
    const canvasState = this.canvasStateBehaviorSubject.getValue();

    if (canvasState.scale >= 2) return;

    canvasState.scale += 0.25;

    this.setCanvasState(canvasState, true);
  }

  zoomOut() {
    const canvasState = this.canvasStateBehaviorSubject.getValue();

    if (canvasState.scale <= 0.5) return;

    canvasState.scale -= 0.25;

    this.setCanvasState(canvasState, true);
  }

  deleteSelection(templateRefreshService: OlcTedPublicTemplateRefreshService) {
    const canvasState = this.canvasStateBehaviorSubject.getValue();

    if (!canvasState.selection) return;

    this.tree.delete_node(canvasState.selection.id);

    canvasState.shapes.splice(canvasState.shapes.indexOf(canvasState.selection), 1);
    canvasState.selection = null;

    templateRefreshService.refreshBackground(canvasState);
  }

  openAddOrEditItemModal(itemType: ItemToAddOrEdit, edit: boolean) {
    this.ngxSmartModalService.setModalData({ itemType, edit }, 'addOrEditItemModal', true);
    const addOrEditItemModal = this.ngxSmartModalService.get('addOrEditItemModal');
    addOrEditItemModal.open();
  }

  setDefaultUnit(measurementUnit: MeasurementUnit) {
    this.defaultUnit = this.getDefaultUnit(measurementUnit);
  }

  private getDefaultUnit(measurementUnit: MeasurementUnit): LengthUnit {
    switch (measurementUnit) {
      case MeasurementUnit.MM:
        return LengthUnit.MM;
      case MeasurementUnit.CM:
        return LengthUnit.CM;
      case MeasurementUnit.IN:
        return LengthUnit.IN;
      case MeasurementUnit.PT:
        return LengthUnit.PT;
      default:
        return LengthUnit.CM;
    }
  }

  getScale(unit: LengthUnit): number {
    switch (unit) {
      case LengthUnit.MM:
        return this.mmToPxScale;
      case LengthUnit.CM:
        return this.cmToPxScale;
      case LengthUnit.IN:
        return this.inToPxScale;
      case LengthUnit.PT:
        return this.ptToPxScale;
    }
  }
}
