import { MongoObjectId } from '../../../Bamba.Web/ClientApp/src/app/blocks/models/mongo-object-id';

export type MetaDataCollectionDictionary = Record<string, IMetaData>;

export enum MetaDataValidity {
  unknown = 0,
  valid = 1,
  suspicious = 2,
  notValid = 3,
  none = 4,
}

export enum MetaDataPreviewHilight {
  None = 0,
  Signature = 1,
  PII = 2,
}

export enum MetaDataValueType {
  String = 0,
  LineItems = 1,
}

export interface ILocation {
  valid: boolean;
  top: number;
  bottom: number;
  left: number;
  right: number;
  page: number;
}

export class Location implements ILocation {
  valid: boolean;
  top: number;
  bottom: number;
  left: number;
  right: number;
  page: number;

  constructor(initializer?: ILocation) {
    if (initializer) {
      this.valid = initializer.valid;
      this.top = initializer.top;
      this.bottom = initializer.bottom;
      this.left = initializer.left;
      this.right = initializer.right;
      this.page = initializer.page;
    }
  }

  serializable(): ILocation {
    return {
      valid: this.valid,
      top: this.top,
      bottom: this.bottom,
      left: this.left,
      right: this.right,
      page: this.page,
    };
  }
}
export interface IMetaData {
  name: string;
  value: string | MetaDataLineItems;
  validity: MetaDataValidity;
  valueType: MetaDataValueType;
  location: ILocation;
  previewHilight: MetaDataPreviewHilight;
}

export class MetaDataCollection {
  id: string = MongoObjectId.generate();
  placeholder: boolean = false;
  metadata: Array<MetaData> = [];

  constructor(mdcd?: MetaDataCollectionDictionary) {
    if (mdcd) {
      for (const key in mdcd) {
        this.metadata.push(new MetaData(mdcd[key]));
      }
    }
  }

  public clear = (): void => {
    this.metadata = [];
  };

  public merge = (mdc: MetaDataCollection): void => {
    for (const md of mdc.metadata) {
      if (md.valueType === MetaDataValueType.LineItems) {
        this.setLineItems(md.name, md.value as MetaDataLineItems);
      } else {
        this.set(md.name, md.value.toString(), md.validity, md.location);
      }
    }
  };

  public getOverallValidity = (): MetaDataValidity => {
    if (this.hasValidity(MetaDataValidity.notValid)) return MetaDataValidity.notValid;
    if (this.hasValidity(MetaDataValidity.suspicious)) return MetaDataValidity.suspicious;
    if (this.hasValidity(MetaDataValidity.unknown)) return MetaDataValidity.unknown;

    return MetaDataValidity.valid;
  };

  private hasValidity = (v: MetaDataValidity): boolean => {
    for (let md of this.metadata) {
      if (md.validity === v) return true;
    }

    return false;
  };

  public set(name: string, value: string, v?: MetaDataValidity, location?: Location) {
    const key = name.toLowerCase();
    const validity = v ? v : MetaDataValidity.unknown;
    const valueType = MetaDataValueType.String;
    this.placeholder = false;

    const md = this.metadata.find((md) => md.name == key);
    if (md == null) {
      this.metadata.push(
        new MetaData({
          name: key,
          value,
          validity,
          valueType,
          location: location != null ? location : new Location(),
          previewHilight: MetaDataPreviewHilight.None,
        })
      );
    } else {
      if (value == '' || (value && (md.value as string).replace(/\n/g, '') !== value.replace(/\n/g, ''))) {
      }

      md.value = value;
      md.validity = v;
      md.valueType = valueType;
      md.location = location != null ? location : new Location();
    }
  }

  public remove(name: string) {
    this.metadata = this.metadata.filter((md) => md.name != name.toLowerCase());
  }

  public get(name: string): IMetaData {
    const key = name.toLowerCase();

    return this.metadata.find((md) => md.name == key);
  }

  public setLineItems(name: string, value: MetaDataLineItems) {
    const key = name.toLowerCase();

    const md = this.metadata.find((md) => md.name == key);
    if (md == null) {
      this.metadata.push(
        new MetaData({
          name: key,
          value,
          validity: MetaDataValidity.unknown,
          valueType: MetaDataValueType.LineItems,
          location: new Location(),
          previewHilight: MetaDataPreviewHilight.None,
        })
      );
    } else {
      md.value = value;
      md.validity = MetaDataValidity.unknown;
      md.valueType = MetaDataValueType.LineItems;
    }
  }

  public serializable = (): MetaDataCollectionDictionary => {
    const dictionary = {};

    for (let md of this.metadata) {
      dictionary[md.name] = md.serializable();
    }

    return dictionary;
  };
}

export class MetaDataLineItems extends Array<MetaDataCollection> {
  public constructor(initializer?: any) {
    super();

    if (initializer && Array.isArray(initializer)) {
      for (const item of initializer) {
        this.push(new MetaDataCollection(item));
      }
    }
  }

  public serializable = (): MetaDataLineItems => {
    let metaDataLineItems = [];

    const editedLineItems = this.filter((md) => !md.placeholder);
    for (const mdc of editedLineItems) {
      metaDataLineItems.push(mdc.serializable());
    }

    return <MetaDataLineItems>metaDataLineItems;
  };
}

export class MetaData implements IMetaData {
  public name: string;
  public value: string | MetaDataLineItems;
  public validity: MetaDataValidity;
  public valueType: MetaDataValueType;
  public location: Location;
  public previewHilight: MetaDataPreviewHilight;

  constructor(initializer: IMetaData) {
    this.name = initializer.name ? initializer.name.toLowerCase() : '';
    this.validity = initializer.validity;
    this.valueType = initializer.valueType;
    this.location = new Location(initializer.location);
    this.previewHilight = initializer.previewHilight;

    if (this.valueType == MetaDataValueType.String) {
      this.value = initializer.value;
    } else if (this.valueType == MetaDataValueType.LineItems) {
      this.value = new MetaDataLineItems(initializer.value);
    } else {
      throw new Error(`unknown value type ${this.valueType}`);
    }
  }

  public serializable = (): IMetaData => {
    let value: string | MetaDataLineItems;

    if (this.valueType == MetaDataValueType.String) {
      value = this.value;
    } else if (this.valueType == MetaDataValueType.LineItems) {
      value = (<MetaDataLineItems>this.value).serializable();
    }

    return {
      name: this.name,
      value: value,
      validity: this.validity,
      valueType: this.valueType,
      location: this.location.serializable(),
      previewHilight: this.previewHilight,
    };
  };
}
