import { Component, ElementRef, HostListener, OnDestroy, ViewChild, ViewEncapsulation } from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { Subscription } from 'rxjs';

import { BambaDetailsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/bamba-details.service';
import { HydraApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';
import { BambaDetails } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/models';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { ITenant } from '../../models/tenant';
import { TermsOfService } from '../../models/terms-of-service';
import { AuthService } from '../../services/auth/auth.service';
import { BrandDetails, BrandingService, RedirectToLegacy } from '../../services/branding.service';
import { SessionStorageService } from '../../services/session-storage.service';

export class AuthorizationResult {
  succeeded: boolean;
  errorText: string;
  passwordExpired: boolean;
  token: string;
  tenants: Array<ITenant>;
  notAcceptedTermsOfService: TermsOfService;
}

export enum LoginModes {
  Web = 'web',
  Mobile = 'mobile',
  Device = 'device',
}

declare const _upland_build_number: string;
declare const _upland_version: string;

@Component({
  selector: 'app-login-base',
  template: '',
  styles: [],
  encapsulation: ViewEncapsulation.None,
})
export class LoginBaseComponent implements OnDestroy {
  @ViewChild('loginComponent', { static: true })
  loginDiv: ElementRef;

  public loginDivElement: HTMLElement;

  public errorOccurred: boolean = false;
  public isSubmitted: boolean = false;
  public version: string = '';
  public loginErrorText: string = '';
  public logoColor: string;
  public privacyPolicyURL: string = '';

  subscriptions = new Subscription();

  constructor(
    protected hydraApi: HydraApiService,
    protected spinnerStateService: SpinnerStateService,
    protected translateService: TranslateService,
    protected authService: AuthService,
    protected bambaDetailsService: BambaDetailsService,
    protected userStateService: UserStateService,
    protected sessionStorageService: SessionStorageService,
    protected brandingService: BrandingService,
    protected router: Router
  ) {}

  ngOnInit(): void {
    this.clear();

    this.loginDivElement = this.loginDiv.nativeElement;

    this.bambaDetailsService.load();
    this.subscriptions.add(
      this.bambaDetailsService.changed.subscribe((details: BambaDetails) => {
        const versionParts = details.version.split('.');

        const backendBuildNumber = versionParts.length == 4 ? versionParts[3] : '0';
        const frontendBuildNumber = this.getUplandBuildNumber();

        this.version = this.getUplandVersion();

        if (frontendBuildNumber != backendBuildNumber) {
          this.version += '**';
        }
      })
    );

    this.updateBrandDetails(this.brandingService.getBrandDetails());
    this.subscriptions.add(this.brandingService.onBrandDetailsUpdated.subscribe(this.updateBrandDetails));
  }

  isRedirectAllowed = (): boolean => {
    const urlParams = new URLSearchParams(window.location.search);

    const noredirect = urlParams.get('noredirect');
    if (noredirect) {
      console.log('set noredirect');
      sessionStorage.setItem('noredirect', 'true');
      localStorage.removeItem('redirectForPCI');

      return false;
    }

    if (sessionStorage.getItem('noredirect') == 'true') return false;

    return true;
  };

  updateBrandDetails = (bd: BrandDetails): void => {
    // HACK: redirect for JA
    if (bd?.countryCode == 'JP' && this.isRedirectAllowed()) {
      this.hydraApi.getLegacyRedirect((lr: RedirectToLegacy) => {
        location.href = lr.url;
      });

      return;
    }

    this.logoColor = bd?.loginLogoUrl;
    this.privacyPolicyURL = bd?.privacyPolicyURL;

    if (bd?.primaryColor) document.documentElement.style.setProperty('--brand-primary-color', bd.primaryColor);

    if (bd?.secondaryColor) document.documentElement.style.setProperty('--brand-secondary-color', bd.secondaryColor);
  };

  getUplandBuildNumber = (): string => {
    if (_upland_build_number === null || _upland_build_number === undefined) return '0';

    return _upland_build_number;
  };

  getUplandVersion = (): string => {
    if (_upland_version === null || _upland_version === undefined) return 'V9999R0.0';

    return _upland_version + ' b' + this.getUplandBuildNumber();
  };

  restartLoginProcess = (): boolean => {
    const isFaxMobile = this.sessionStorageService.getIsInterFaxMobile();
    const isMobile = this.sessionStorageService.getIsMobile();

    if (!this.authService.isLoggedIn()) return false;

    this.authService.logout();

    if (isFaxMobile) {
      this.router.navigateByUrl('/fax-mobile/login');
      return true;
    }

    if (isMobile) {
      this.router.navigateByUrl('/mobile/login');
      return true;
    }

    this.router.navigateByUrl('/login');
    return true;
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  loginFailure = (errorResourceId: string): void => {
    this.spinnerStateService.hide();
    this.isSubmitted = false;

    this.errorOccurred = true;
    this.loginErrorText = this.translateService.instant(errorResourceId);

    this.authService.logout();
  };

  clear = (): void => {
    this.spinnerStateService.hide();
    this.isSubmitted = false;
    this.version = '';
    this.logoColor = '';

    this.resetErrors();
  };

  resetErrors = (): void => {
    this.errorOccurred = false;
    this.loginErrorText = '';
  };

  @HostListener('window:orientationchange', ['$event'])
  onOrientationChange(event): void {
    setTimeout(() => {
      this.scrollToTop();
    }, 50);
  }

  scrollToTop() {
    document.body.scrollTop = 0;
    document.documentElement.scrollTop = 0;
  }
}
