export enum MediaFileType {
  JPG = 'jpg',
  JPEG = 'jpeg',
  PNG = 'png',
  BMP = 'bmp',
  PDF = 'pdf',
}

export interface IMedia {
  id: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  name: string;
  slug: string;
  fileType: MediaFileType;
  roleBasedAccess: boolean;
  roles: string[];
  pageCount: number;
}

export class Media implements IMedia {
  id: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  name: string;
  slug: string;
  fileType: MediaFileType;
  roleBasedAccess: boolean;
  roles: string[];
  pageCount: number;

  constructor(initializer: IMedia | null = null) {
    if (initializer) {
      if (initializer.id === undefined) throw new Error('Invalid initializer.id');
      if (initializer.dateCreatedUTC === undefined) throw new Error('Invalid initializer.dateCreatedUTC');
      if (initializer.dateModifiedUTC === undefined) throw new Error('Invalid initializer.dateModifiedUTC');
      if (initializer.name === undefined) throw new Error('Invalid initializer.name');
      if (initializer.slug === undefined) throw new Error('Invalid initializer.slug');
      if (initializer.fileType === undefined) throw new Error('Invalid initializer.fileType');
      if (initializer.roleBasedAccess === undefined) throw new Error('Invalid initializer.roleBasedAccess');
      if (initializer.roles === undefined) throw new Error('Invalid initializer.roles');
      if (initializer.pageCount === undefined) throw new Error('Invalid initializer.pageCount');

      this.id = initializer.id;
      this.dateCreatedUTC = initializer.dateCreatedUTC;
      this.dateModifiedUTC = initializer.dateModifiedUTC;
      this.name = initializer.name;
      this.slug = initializer.slug;
      this.fileType = initializer.fileType;
      this.roleBasedAccess = initializer.roleBasedAccess;
      this.roles = initializer.roles.map((r) => r);
      this.pageCount = initializer.pageCount;
    }
  }

  public serializable(): IMedia {
    return {
      id: this.id,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      name: this.name,
      slug: this.slug,
      fileType: this.fileType,
      roleBasedAccess: this.roleBasedAccess,
      roles: this.roles,
      pageCount: this.pageCount,
    };
  }
}
