export interface ICapture {
  capturedImage: string;
  originalImage: string;
  originalImageBoundaries: IContourPoints;
  capturedImageBoundaries: IContourPoints;
}

export class Capture implements ICapture {
  capturedImage: string;
  originalImage: string;
  originalImageBoundaries: IContourPoints;
  capturedImageBoundaries: IContourPoints;

  constructor(initializer: ICapture = null) {
    if (initializer) {
      if (initializer.capturedImage === undefined) throw new Error('invalid initializer.capturedImage');
      if (initializer.originalImage === undefined) throw new Error('invalid initializer.originalImage');
      if (initializer.originalImageBoundaries === undefined)
        throw new Error('invalid initializer.originalImageBoundary');
      if (initializer.capturedImageBoundaries === undefined)
        throw new Error('invalid initializer.capturedImageBoundary');

      this.capturedImage = initializer.capturedImage;
      this.originalImage = initializer.originalImage;
      this.originalImageBoundaries = initializer.originalImageBoundaries;
      this.capturedImageBoundaries = initializer.capturedImageBoundaries;
    }
  }
}

export enum ScanResult {
  NoDocument = 0,
  NotReadyDocument = 1,
  ReadyDocument = 2,
}

export interface IPoint {
  x: number;
  y: number;
}

export interface IContourPoints {
  topLeft: IPoint;
  topRight: IPoint;
  bottomLeft: IPoint;
  bottomRight: IPoint;
}

export interface IExtractDocumentResult {
  image: string;
  imageBoundaries: IContourPoints;
}

export interface IEditCapturesData {
  captures: ICapture[];
  indexToEdit: number;
}
