import { EventEmitter, Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { MetaDataCollection } from 'shared-code-lib';
import { Widget } from '../../../../blocks/models/home-page-tab';
import { ErrorsService } from '../../../../blocks/services/errors.service';
import { HydraApiService } from '../../../../blocks/services/hydra-api.service';
import { ApiResults, SpinnerState } from '../../../../blocks/services/models';
import { WidgetsService } from '../../../../blocks/services/widgets.service';

@Injectable({
  providedIn: 'root',
})
export class FileDropService {
  constructor(
    private toastr: ToastrService,
    private translate: TranslateService,
    private errorService: ErrorsService,
    private hydraApi: HydraApiService,
    private widgetsService: WidgetsService
  ) {}

  submitFilesToWidget(
    widget: Widget,
    filesToSubmit: Array<File>,
    metaDataCollection: MetaDataCollection,
    toggleSpinner: EventEmitter<SpinnerState>
  ) {
    toggleSpinner.emit({ state: true, message: this.translate.instant('dashboard.uploading') });

    this.hydraApi.submitFilesToWidget(
      widget.id,
      filesToSubmit,
      metaDataCollection,
      (result: ApiResults) => {
        if (!result.errors.length) {
          this.toastr.success(
            this.translate.instant('dashboard.upload-message', {
              widgetTitle: widget.title,
              status: this.translate.instant('Common.Succeeded'),
            })
          );

          toggleSpinner.emit({ state: false });

          this.widgetsService.reloadData(widget.relatedWidgetTopics);
        } else {
          this.showErrorMessage(widget.title, result.errors, toggleSpinner);
        }
      },
      (err) => {
        this.showErrorMessage(widget.title, err, toggleSpinner);
      }
    );
  }

  showErrorMessage(widgetTitle: string, errors: any, toggleSpinner: EventEmitter<SpinnerState>) {
    this.errorService.showErrorsModal(
      errors,
      this.translate.instant('dashboard.upload-message', {
        widgetTitle: widgetTitle,
        status: this.translate.instant('Common.Failed'),
      })
    );

    toggleSpinner.emit({ state: false });
  }
}
