export class Email {
  static isValid(value: string): boolean {
    if (!value) return false;

    const emailPattern = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@\w+([\.-]?\w+)*(\.\w{2,})+$/;
    return emailPattern.test(value.trim().toLowerCase());
  }

  static isValidDelimited(value: string, delimiter: Delimiters): boolean {
    if (!value) return false;

    const emails = value.split(delimiter);

    for (const mail of emails) {
      if (!this.isValid(mail)) return false;
    }

    return true;
  }
}

export enum Delimiters {
  Semicolon = ';',
  Comma = ',',
  Dash = '-',
}
