import { Log } from './../../../../blocks/core/log';
import { Filter, IFilter } from './../../../../blocks/models/filter';

class OLCTemplateVersionsFilterByComment extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCTemplateVersionCommentComponent';
  }
}

class OLCTemplateVersionsFilterByCreatorUser extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCUserComponent';
  }
}

class OLCTemplateVersionsFilterByStatus extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCTemplateVersionStatusComponent';
  }
}

class OLCTemplateVersionsFilterByCreationDate extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCDateComponent';
  }
}

export class OLCTemplateVersionsFilters {
  public static Create = (filter: IFilter): Filter | null => {
    Log.enter('OLCTemplateVersionsFilters.Create', filter);

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Templates.Filters.FilterByComment')
      return new OLCTemplateVersionsFilterByComment(filter);

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Templates.Filters.FilterByCreatorUser')
      return new OLCTemplateVersionsFilterByCreatorUser(filter);

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Templates.Filters.FilterByStatus')
      return new OLCTemplateVersionsFilterByStatus(filter);

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Templates.Filters.FilterByCreationDate')
      return new OLCTemplateVersionsFilterByCreationDate(filter);

    return null;
  };
}
