import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';
import { ApiService } from './api.service';
import { BambaDetails } from './models';

@Injectable({
  providedIn: 'root',
})
export class BambaDetailsService {
  details: BambaDetails = null;
  changed = new Subject<any>();

  constructor(private api: ApiService) {}

  load = () => {
    this.api.queryServer('bamba/details').subscribe(
      (details: any) => {
        this.details = details;
        this.changed.next(details);
      },
      (err) => {
        console.log('failed get details', err);
        this.details = { version: '??.??.??' };
        this.changed.next(this.details);
      }
    );
  };
}
