import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';

import { DragData } from '../../views/document-capture/capture-models';

@Injectable({
  providedIn: 'root',
})
export class DragDropService {
  private _dragDataArray: DragData[] = [];
  private _autoScrollSubject = new Subject<DragEvent>();
  private _stoppingAutoScrollSubject = new Subject<void>();
  private _dragStartedSubject = new Subject<void>();
  private _dragEndedSubject = new Subject<void>();

  onDragOverElement = this._autoScrollSubject.asObservable();
  onDropElement = this._stoppingAutoScrollSubject.asObservable();

  onElementDragStarted = this._dragStartedSubject.asObservable();
  onElementDragEnded = this._dragEndedSubject.asObservable();

  elementDragStarted() {
    this._dragStartedSubject.next();
  }

  elementDragEnded() {
    this._dragEndedSubject.next();
  }

  pushDragData(value: DragData) {
    this._dragDataArray.push(value);
  }

  clearDragData() {
    this._dragDataArray = [];
  }

  get dragDataArray(): DragData[] {
    return this._dragDataArray;
  }

  isItemDragged(id: string): boolean {
    return this._dragDataArray.some((dragData) => dragData.element.id === id);
  }

  autoScroll(event: DragEvent) {
    this._autoScrollSubject.next(event);
  }

  stopAutoScroll() {
    this._stoppingAutoScrollSubject.next();
  }
}
