import { Injectable, EventEmitter } from '@angular/core';
import { HydraApiService } from './hydra-api.service';
import { ToastrService } from 'ngx-toastr';
import { TranslateService } from '@ngx-translate/core';
import { InProgressService } from './in-progress.service';
import { SelectFilesService } from './select-files.service';

@Injectable({
  providedIn: 'root',
})
export class MyfilesService {
  public filesUploaded = new EventEmitter();

  constructor(
    private selectFiles: SelectFilesService,
    private hydraApi: HydraApiService,
    private inProgress: InProgressService,
    private toastr: ToastrService,
    private translate: TranslateService
  ) {}

  public upload = (): void => {
    this.inProgress.open(this.translate.instant('myfiles.uploading'));

    this.hydraApi.uploadToMyFiles(this.selectFiles.files, this.uploadSucceeded, this.uploadFailed);

    this.selectFiles.clear();
  };

  private uploadSucceeded = (errors: Array<string>): void => {
    this.inProgress.close();

    this.filesUploaded.emit();

    if (errors.length == 0) {
      this.toastr.success(this.translate.instant('myfiles.upload-succeeded'));
    } else {
      for (const error of errors) {
        this.toastr.error(`${this.translate.instant('Common.upload-failed')}: ${error}`);
      }
    }
  };

  private uploadFailed = (err: any): void => {
    this.inProgress.close();

    const error =
      err && err.error
        ? `${this.translate.instant('Common.upload-failed')}: ${err.error}`
        : this.translate.instant('Common.upload-failed');
    this.toastr.error(error);
  };
}
