import { Pipe, PipeTransform } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { DateTimeFormat } from '../../../Bamba.Web/ClientApp/src/app/blocks/core/dateTimeFormat';
import { UserStateService } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { DateTime } from '../utils/date-time.service';

@Pipe({
  name: 'localDateTimeFormat',
})
export class LocalDateTimeFormatPipe implements PipeTransform {
  constructor(private translateService: TranslateService, private userStateService: UserStateService) {}

  transform(value: any, ...args: any[]) {
    if (!value || DateTime.isMinimumDateValue(value)) {
      return this.translateService.instant('general.date-not-applicable');
    }

    return DateTimeFormat.getLocalDateTime(value, this.userStateService.getLocale());
  }
}

@Pipe({
  name: 'localDateTimeFormatWithSeconds',
})
export class LocalDateTimeFormatWithSecondsPipe implements PipeTransform {
  transform(value: any, ...args: any[]) {
    return DateTimeFormat.getLocalDateTimeWithSeconds(value);
  }
}
