import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { FieldDefinition, FixedDataSource, IFieldOptions, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { RollBack, RollBackType } from '../../../blocks/models/dwf-tools-roll-back';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResult } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { IComponent, ComponentType } from '../../models/component';

@Component({
  selector: 'app-roll-back-modal',
  templateUrl: './roll-back-modal.component.html',
  styleUrls: ['./roll-back-modal.component.scss'],
})
export class RollBackModalComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  componentField: FieldDefinition;
  versionField: FieldDefinition;
  groupingField: FieldDefinition;
  commentField: FieldDefinition;

  rollBack = new RollBack();
  rollBackType: RollBackType;

  componentsDataSource = new FixedDataSource([]);
  versionsDataSource = new FixedDataSource([]);
  groupingsDataSource = new FixedDataSource([]);

  isRollBackForSM = false;
  errors = [];

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private hydraApi: HydraApiService
  ) {}

  ngOnInit(): void {
    this.rollBackType = this.sharedDataService.extraParameters.rollBackType;
    this.isRollBackForSM = this.rollBackType === RollBackType.SM;

    this.createFields();
    this.loadComponents();
  }

  createFields = (): void => {
    this.componentField = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('roll-back-modal.component'),
      required: true,
      datasource: this.componentsDataSource,
    });

    this.versionField = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('roll-back-modal.version'),
      required: true,
      datasource: this.versionsDataSource,
    });

    this.groupingField = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('roll-back-modal.environment'),
      required: true,
      datasource: this.groupingsDataSource,
    });

    this.commentField = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('roll-back-modal.comment'),
      placeholder: this.translateService.instant('roll-back-modal.comment-placeholder'),
      required: false,
    });
  };

  loadComponents() {
    this.hydraApi.getComponents(this.componentsLoadSucceeded, this.loadFailed);
  }

  componentsLoadSucceeded = (apiResult: ApiResult): void => {
    if (apiResult.success) {
      const options: IFieldOptions[] = apiResult.object
        .filter((c: IComponent) => c.componentType !== ComponentType.Database)
        .map((c: IComponent) => ({
          value: c.id,
          name: c.name,
        }));

      this.componentsDataSource.updateOptions(options);
    } else {
      this.errors = apiResult.errors.map((e: any) => e);
    }

    this.spinnerService.hide();
  };

  onComponentSelected(componentId: string): void {
    this.showSpinner();

    this.rollBack.versionId = '';
    this.hydraApi.getComponentVersions(componentId, this.rollBackType, this.versionsLoadSucceeded, this.loadFailed);

    if (this.rollBackType === RollBackType.SM) {
      this.rollBack.groupingId = '';
      this.hydraApi.getComponentGroupings(componentId, this.rollBackType, this.groupingsLoadSucceeded, this.loadFailed);
    }
  }

  versionsLoadSucceeded = (apiResult: ApiResult): void => {
    if (apiResult.success) {
      const options: IFieldOptions[] = apiResult.object.map((v: { versionId: string; versionName: string }) => ({
        value: v.versionId,
        name: v.versionName,
      }));

      this.versionsDataSource.updateOptions(options);
    } else {
      this.errors = apiResult.errors.map((e: any) => e);
    }

    this.spinnerService.hide();
  };

  groupingsLoadSucceeded = (apiResult: ApiResult) => {
    if (apiResult.success) {
      const options: IFieldOptions[] = apiResult.object.map((g: { groupingId: string; groupingName: string }) => ({
        value: g.groupingId,
        name: g.groupingName,
      }));

      this.groupingsDataSource.updateOptions(options);
    } else {
      this.errors = apiResult.errors.map((e: any) => e);
    }

    this.spinnerService.hide();
  };

  loadFailed = (errors: any): void => {
    this.spinnerService.hide();
    this.errors = errors.map((e: any) => e);
  };

  isActionBtnEnabled(): boolean {
    if (this.rollBackType === RollBackType.QA) {
      return !!this.rollBack.componentId && !!this.rollBack.versionId;
    } else {
      return !!this.rollBack.componentId && !!this.rollBack.versionId && !!this.rollBack.groupingId;
    }
  }

  onRollBack = (): void => {
    this.errors = [];
    this.showSpinner();

    const args = new MetaDataCollection();
    args.set('componentId', this.rollBack.componentId);
    args.set('componentVersionId', this.rollBack.versionId.split('-')[0]);
    args.set('buildRequestId', this.rollBack.versionId.split('-')[1]);
    args.set('groupingId', this.rollBack.groupingId);
    args.set('comment', this.rollBack.comment);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      [],
      args,
      this.onRollBackSucceeded,
      this.onRollBackFailed
    );
  };

  onRollBackSucceeded = (result: ApiResult): void => {
    this.spinnerService.hide();
    this.close();
  };

  onRollBackFailed = (errors: any[]): void => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  close = (): void => this.closeModal.emit();

  getSpinnerElement(): HTMLElement {
    return document.querySelector('.roll-back-modal .nsm-content') as HTMLElement;
  }

  showSpinner = (): void => {
    this.spinnerService.show(this.translateService.instant('roll-back-modal.loading'), this.getSpinnerElement());
  };
}
