export interface IMultiSelectOptionActionResult {
  title: string;
  description: string;
  options: IMultiSelectOption[];
  extraParameters: any;
}

export class MultiSelectOptionActionResult implements IMultiSelectOptionActionResult {
  title: string;
  description: string;
  options: IMultiSelectOption[];
  extraParameters: any;

  constructor(multiSelectOptionActionResult: IMultiSelectOptionActionResult) {
    this.title = multiSelectOptionActionResult?.title;
    this.description = multiSelectOptionActionResult?.description;
    this.options = multiSelectOptionActionResult?.options?.map((o) => new MultiSelectOption(o)) ?? [];
    this.extraParameters = multiSelectOptionActionResult?.extraParameters;
  }
}

export interface IMultiSelectOption {
  id: string;
  title: string;
  selected: boolean;
}

export class MultiSelectOption implements IMultiSelectOption {
  id: string;
  title: string;
  selected: boolean;

  constructor(option: IMultiSelectOption) {
    this.id = option?.id;
    this.title = option?.title;
    this.selected = option?.selected;
  }
}
