import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { HydraApiService } from './../../../../../blocks/services/hydra-api.service';
import { ApiResult } from './../../../../../blocks/services/models';
import { ProductItemRefreshService } from './../../../../../blocks/services/product-item-refresh.service';
import { SelectFilesService } from './../../../../../blocks/services/select-files.service';
import { SpinnerStateService } from './../../../../../blocks/services/spinner-state.service';
import { UploadConfigService } from './../../../shared/services/upload-config.service';

@Component({
  selector: 'app-upload-olc-template-modal',
  templateUrl: './upload-template-modal.component.html',
  styleUrls: ['./upload-template-modal.component.scss'],
})
export class UploadOLCTemplateModalComponent implements OnInit {
  @Output() closeModal = new EventEmitter();
  supportedFileTypes = '';
  uploadTooltip = '';

  constructor(
    private translateService: TranslateService,
    private spinnerService: SpinnerStateService,
    public selectFilesService: SelectFilesService,
    private hydraApiService: HydraApiService,
    private toastr: ToastrService,
    private translate: TranslateService,
    private productItemRefreshService: ProductItemRefreshService,
    private uploadConfigService: UploadConfigService
  ) {}

  ngOnInit() {
    const config = this.uploadConfigService.getUploadConfig();
    this.supportedFileTypes = config.supportedFileTypes;
    this.uploadTooltip = config.uploadTooltip;
  }

  close = () => {
    this.selectFilesService.clear();
    this.closeModal.emit();
  };

  uploadTemplate() {
    this.spinnerService.show(
      this.translateService.instant('admin-olc-templates.uploading'),
      document.querySelector('.olc-upload-template-modal .nsm-content')
    );

    this.hydraApiService.uploadOLCTemplate(this.selectFilesService.files, this.uploadSucceeded, this.uploadFailed);
  }

  uploadSucceeded = (result: ApiResult) => {
    if (result.success) {
      this.toastr.success(this.translate.instant('admin-olc-templates.template-uploaded'));
      this.close();
      this.productItemRefreshService.onRefresh.next();
    } else {
      const error = result.errors[0];
      this.toastr.error(error);
    }

    this.spinnerService.hide();
  };

  uploadFailed = () => {
    this.toastr.error(this.translate.instant('admin-olc-templates.upload-template-failed'));
    this.spinnerService.hide();
  };
}
