import { Component, OnInit, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { saveAs } from 'file-saver';
import { IManageDocumentProfile } from 'shared-code-lib';
import { DocumentCaptureService } from '../../../views/document-capture/capture-services';
import { Filename } from '../../core/fileName';
import { ErrorsService } from '../../services/errors.service';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResult, ApiResults } from '../../services/models';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { UserStateService } from '../../services/user-state.service';

declare var imanage: any;

@Component({
  selector: 'app-upload-scan',
  templateUrl: './upload-scan.component.html',
  styleUrls: ['./upload-scan.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class IManageUploadScanComponent implements OnInit {
  succeeded: boolean;
  folderId: string;
  dialogUrl: string;
  profile: IManageDocumentProfile;

  constructor(
    public userStateService: UserStateService,
    public hydraApi: HydraApiService,
    private translate: TranslateService,
    private spinner: SpinnerStateService,
    public capture: DocumentCaptureService,
    private errorService: ErrorsService
  ) {}

  ngOnInit(): void {
    const that = this;
    imanage.ready().then(function (context) {
      that.folderId = context.selectedItems[0].id;
      that.openDialog();
    });

    imanage.dialogs.handler(function (message) {
      switch (message.type) {
        case 'select':
          that.profile = message.data.output_data.profile;
          that.profile.parent_id = message.data.output_data.loc.id;
          that.importWithCopiedProfile(that.profile);
          break;
        case 'cancel':
          that.close();
      }
    });
  }

  openDialog = (): void => {
    this.spinner.show(this.translate.instant('Common.Loading'), document.documentElement);
    this.hydraApi.getIManageDialogUrl(this.folderId, 'new', this.onDialogUrlSucceeded, this.onFailure);
  };

  onDialogUrlSucceeded = (result: ApiResult): void => {
    this.dialogUrl = result.object;
    this.spinner.hide();
  };

  onDialogTokenFailed = (err: any): void => {
    this.errorService.showErrorsModal([err], this.translate.instant('imanage.routing-sheet-failed'));
    this.spinner.hide();
  };

  importWithCopiedProfile = (profile: IManageDocumentProfile): void => {
    this.spinner.show(this.translate.instant('imanage.generating-routing-sheet'), document.documentElement);
    this.hydraApi.generateIManageRoutingSheet(profile, this.onSuccess, this.onFailure);
  };

  onSuccess = (file: Blob) => {
    if (file.type == 'application/json') {
      this.onError(file);
      return;
    }

    const fileName = `${Filename.getFileNameWithoutExtension(this.profile.name)}-routingsheet.pdf`;
    saveAs(file, fileName);
    this.succeeded = true;

    this.spinner.hide();
  };

  onFailure = (err) => {
    this.errorService.showErrorsModal([err], this.translate.instant('imanage.routing-sheet-failed'));
    this.spinner.hide();
  };

  onError = (blob: Blob): void => {
    const file: File = new File([blob], 'result');
    var reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const json: string = reader.result.toString();
      const apiResults: ApiResults = JSON.parse(atob(json.substring(json.indexOf('base64') + 7))) as ApiResults;
      this.onFailure(apiResults?.errors);
    };
  };

  close = (): void => {
    imanage.cancel({
      nextSteps: 'close',
    });
  };
}
