import {
  Component,
  Input,
  ViewEncapsulation,
  Output,
  EventEmitter,
  ViewChild,
  AfterViewInit,
  OnChanges,
  SimpleChanges,
} from '@angular/core';
import { SortDescriptor } from '@progress/kendo-data-query';
import { GridComponent, RowArgs } from '@progress/kendo-angular-grid';
import { TranslateService } from '@ngx-translate/core';

import { ICombinedColumn, IDefaultColumn } from './../../models/column';
import { ColumnDisplayType } from './../../utils/enums';
import { InvokeAction, TableItem } from './../../models/table';

declare const $: any;

@Component({
  selector: 'app-selection-table',
  templateUrl: './selection-table.component.html',
  styleUrls: ['./selection-table.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class SelectionTableComponent implements AfterViewInit, OnChanges {
  @ViewChild('grid', { static: true })
  grid: GridComponent;

  @Output() onRender = new EventEmitter<GridComponent>();
  @Output() onSelectionChanged = new EventEmitter();
  @Output() onCellClick = new EventEmitter<any>();
  @Output() onInvokeAction = new EventEmitter<InvokeAction>();
  @Output() onSort = new EventEmitter<SortDescriptor>();
  @Output() onSaveColumns = new EventEmitter<Array<IDefaultColumn>>();
  @Output() onDeleteIconClicked = new EventEmitter<InvokeAction>();
  @Output() reload = new EventEmitter();

  @Input() items: Array<TableItem>;
  _columns: Array<ICombinedColumn> = [];
  @Input() set columns(value: Array<ICombinedColumn>) {
    this._columns = value;
    this.handleStretchableColumns();
  }
  get columns(): Array<ICombinedColumn> {
    return this._columns;
  }
  @Input() expandableDetail: boolean = false;
  @Input() multiselect: boolean = false;
  @Input() sort: SortDescriptor[];
  @Input() scrollable = 'scrollable';
  @Input() deleteIcon: boolean = false;
  @Input() deleteIconTooltip: string = '';
  allItemsSelected = false;
  showSelectAllCheckbox: boolean = false;

  actionsColumnWidth = 50;
  selectionColumnWidth: 40 | 68 = 40;
  stretchableColumnMinimumWidth: number = 50;
  constructor(private translate: TranslateService) {}

  ngAfterViewInit() {
    const that = this;
    this.onRender.emit(this.grid);

    $(this.grid.wrapper.nativeElement).on('mouseenter', 'tr[role="row"]', function (e) {
      const isExpanded = that.isExpandedRow(this);

      const isNested = !!$(this).parents('.k-detail-row').length;

      if (isExpanded || isNested) {
        e.stopPropagation();
        return;
      }

      const index = $(this).attr('data-kendo-grid-item-index');
      if (!index) {
        that.showSelectAllCheckbox = true;
        return;
      }

      const isVisibleCheckbox = that.items[index].showCheckbox;
      if (isVisibleCheckbox) return;

      that.items[index].showCheckbox = true;
    });

    $(this.grid.wrapper.nativeElement).on('mouseleave', 'tr[role="row"]', function (e) {
      const index = $(this).attr('data-kendo-grid-item-index');

      if (!index && that.allItemsSelected) return;

      if (!index && !that.allItemsSelected) {
        that.showSelectAllCheckbox = false;
        return;
      }

      const isSelected = that.items[index].selected;

      if (isSelected) return;

      that.items[index].showCheckbox = false;
    });

    this.handleStretchableColumns();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.items && changes.items.previousValue) {
      this.allItemsSelected = this.items.length !== 0 && this.items.every((i) => i.selected);
      this.showSelectAllCheckbox = this.allItemsSelected;
    }

    if (changes.columns && changes.columns.previousValue) {
      this.items = this.items.map((i) => new TableItem(i.data, this.columns, this.translate));
    }

    this.handleStretchableColumns();
  }

  handleStretchableColumns(): void {
    if (!this.grid || !this.grid.header) return;
    if (this.multiselect && this.expandableDetail) this.selectionColumnWidth = 68;

    let availableWidth =
      this.grid.header.nativeElement.offsetWidth - (this.actionsColumnWidth + this.selectionColumnWidth);

    this.columns.forEach((c) => {
      if (!c.stretch) {
        availableWidth -= c.width;
      }
    });

    const stretchedColumns = this.columns.filter((x) => x.stretch);
    stretchedColumns.forEach(
      (c) => (c.width = Math.max(availableWidth / stretchedColumns.length, this.stretchableColumnMinimumWidth))
    );
  }

  onColumnResize(event: any): void {
    event.forEach((item) => {
      this.columns.find((col) => col.id === item.column.field).width = item.newWidth;
    });

    this.adjustLastColumn();

    this.onSaveColumns.emit(
      this.columns.map<IDefaultColumn>((c) => {
        return { id: c.id, width: c.width, stretch: c.stretch };
      })
    );
  }

  onSorting(sd: SortDescriptor[]): void {
    this.onSort.emit(sd[0]);
  }

  onActionInvoked = (action: any, item: TableItem, index: number): void => {
    this.onInvokeAction.emit({ action, item: item.data, index: index });
  };

  onDefaultAction = (ia: InvokeAction): void => {
    this.onInvokeAction.emit(ia);
  };

  selectAll = (selected: boolean): void => {
    this.items.forEach((item, index) => {
      item.selected = selected;
      item.showCheckbox = selected;

      if (selected) {
        this.addRowBackground(index);
      } else {
        this.removeRowBackground(index);
      }
    });

    this.onSelectionChanged.emit();
  };

  itemSelected = (rowIndex: number): void => {
    this.allItemsSelected = this.items.every((i) => i.selected);
    this.showSelectAllCheckbox = this.allItemsSelected;
    this.toggleRowBackground(rowIndex);
    this.onSelectionChanged.emit();
  };

  toggleRowBackground(index) {
    const row = $(`tr[data-kendo-grid-item-index="${index}"]:not(.k-detail-row):not(.k-detail-row tr)`)[0];
    if (row) row.classList.toggle('selected-row');
  }

  addRowBackground(index) {
    const row = $(`tr[data-kendo-grid-item-index="${index}"]:not(.k-detail-row):not(.k-detail-row tr)`)[0];
    if (row) row.classList.add('selected-row');
  }

  removeRowBackground(index) {
    const row = $(`tr[data-kendo-grid-item-index="${index}"]:not(.k-detail-row):not(.k-detail-row tr)`)[0];
    if (row) row.classList.remove('selected-row');
  }

  selectedOneRow = (rowIndex: number) => {
    this.items.forEach((item, i) => {
      if (i === rowIndex) {
        item.selected = true;
        item.showCheckbox = true;
        this.addRowBackground(i);
      } else {
        item.selected = false;
        item.showCheckbox = false;
        this.removeRowBackground(i);
      }
    });

    this.allItemsSelected = false;
    this.showSelectAllCheckbox = false;
    this.onSelectionChanged.emit();
  };

  isExpandedRow = (row) => {
    const rowClass = $(row).attr('class');
    const isExpanded = rowClass && rowClass.includes('k-detail-row');
    return isExpanded;
  };

  onClickDetails = (item: TableItem, rowIndex: number, tab = ''): void => {
    item.detailsTab = tab;
    item.expanded = !item.expanded;
  };

  adjustLastColumn() {
    const headerWidth = this.grid.header.nativeElement.offsetWidth;
    const lastColumn = this.grid.columns.last;
    const headerColGroup = $('.k-grid-header-wrap colgroup');
    const dataColGroup = $('.k-grid-table colgroup');
    const lastHeaderColElement = headerColGroup.find('col').last();
    const lastDataColElement = dataColGroup.find('col').last();
    const contentDiv = $('.k-grid-content');
    const masterHeaderTable = $('.k-grid-header-wrap table');
    const masterBodyTable = $('.k-grid-table');
    let columnsWidthWithoutLast = 0;

    masterHeaderTable.width('');
    masterBodyTable.width('');

    headerColGroup
      .find('col')
      .not(':last')
      .each(function (idx, element) {
        columnsWidthWithoutLast += parseInt($(element).outerWidth() || 0, 10);
      });

    if (headerWidth - columnsWidthWithoutLast > lastColumn.minResizableWidth) {
      lastHeaderColElement.width(headerWidth - columnsWidthWithoutLast);
      lastDataColElement.width(headerWidth - columnsWidthWithoutLast);
    } else {
      lastHeaderColElement.width(lastColumn.minResizableWidth);
      lastDataColElement.width(lastColumn.minResizableWidth);
    }

    contentDiv.scrollLeft(contentDiv.scrollLeft() - 1);
    contentDiv.scrollLeft(contentDiv.scrollLeft() + 1);
  }

  getDataItemId = (dataItem: any): string => {
    for (const c of this.columns) {
      if (c.displayType == ColumnDisplayType.ActionLink) {
        return dataItem.data.values[c.id];
      }
    }

    return '';
  };

  deleteIconClicked(item: TableItem, index: number) {
    this.onDeleteIconClicked.emit({
      action: 'delete',
      item: item,
      index: index,
    });
  }

  onReload = (): void => {
    this.reload.emit();
  };

  isDetailsExpanded = (args: RowArgs) => Boolean(args.dataItem.expanded);

  cellClick = (event: any): void => {
    this.onCellClick.emit(event);
  };
}
