import {
  AfterViewInit,
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnDestroy,
  OnInit,
  Output,
  Renderer2,
  ViewChild,
} from '@angular/core';

import { Subscription, fromEvent } from 'rxjs';
import { DelayService, FolderTreeAction, InvokeAction, TableItem, WindowRef } from 'shared-code-lib';
import { ActionService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/action.service';

@Component({
  selector: 'app-context-menu',
  templateUrl: './context-menu.component.html',
  styleUrls: ['./context-menu.component.scss'],
})
export class ContextMenuComponent implements OnInit, AfterViewInit, OnDestroy {
  @ViewChild('menu', { static: false }) menu: ElementRef;
  @Output() rendered = new EventEmitter<ContextMenuComponent>();
  @Output() selectAction = new EventEmitter<InvokeAction>();
  @Input() idPrefix: string;
  actions: Array<any>;
  isOpened: boolean;
  subscriptions = new Subscription();
  private item: any;
  private index: number;

  constructor(
    private renderer: Renderer2,
    public el: ElementRef,
    private windowRef: WindowRef,
    private cdr: ChangeDetectorRef,
    private delay: DelayService,
    private actionService: ActionService
  ) {}

  ngOnInit() {
    this.subscriptions.add(this.actionService.onOpenContextMenu.subscribe(() => this.close()));
  }

  ngAfterViewInit(): void {
    this.renderer.appendChild(document.body, this.el.nativeElement);
    this.rendered.emit(this);
    this.renderer.setStyle(this.menu.nativeElement, 'visibility', 'hidden');

    this.subscriptions.add(
      fromEvent(this.menu.nativeElement, 'contextmenu').subscribe((event: Event) => {
        event.preventDefault();
      })
    );

    this.subscriptions.add(
      fromEvent(window, 'click').subscribe((e: Event) => {
        if (this.isOpened) {
          this.close();
        }
      })
    );
  }

  public open(
    e: any,
    item?: TableItem,
    index?: number,
    actions?: Array<FolderTreeAction>,
    idPrefix: string = 'action-dropdown'
  ): void {
    this.actionService.openContextMenu();
    this.delay.execute(() => this.doOpen(e, item, index, actions, idPrefix), 50);
  }

  private doOpen = (
    e: any,
    item?: TableItem,
    index?: number,
    actions?: Array<FolderTreeAction>,
    idPrefix: string = 'action-dropdown'
  ) => {
    this.idPrefix = idPrefix;
    if (this.isOpened) {
      this.close();
    }

    if (item) {
      this.actions = item?.data?.allowedActions;
      this.item = item;
      this.index = index;
    } else {
      this.actions = actions;
    }

    if (!this.actions?.length) return;
    this.cdr.detectChanges();

    e.preventDefault();
    this.isOpened = true;
    this.renderer.setStyle(this.menu.nativeElement, 'top', 0);
    this.renderer.setStyle(this.menu.nativeElement, 'left', 0);
    this.renderer.setStyle(this.menu.nativeElement, 'visibility', 'hidden');
    let topPosition = e.pageY;
    let leftPosition = e.pageX;
    const menuWidth = this.menu.nativeElement.offsetWidth;
    const menuHeight = this.menu.nativeElement.offsetHeight;

    const marginBuffer = 5;

    leftPosition = this.keepValueBetweenMinAndMax(
      leftPosition,
      marginBuffer,
      this.windowRef.nativeWindow.innerWidth - menuWidth - marginBuffer
    );

    topPosition = this.keepValueBetweenMinAndMax(
      topPosition,
      marginBuffer,
      this.windowRef.nativeWindow.innerHeight - menuHeight - marginBuffer
    );

    this.renderer.setStyle(this.menu.nativeElement, 'top', `${topPosition}px`);
    this.renderer.setStyle(this.menu.nativeElement, 'left', `${leftPosition}px`);
    this.renderer.setStyle(this.menu.nativeElement, 'visibility', 'visible');
  };

  keepValueBetweenMinAndMax(value: number, min: number, max: number): number {
    return Math.max(min, Math.min(value, max));
  }

  close(): void {
    this.isOpened = false;
    this.actions = [];
    this.item = null;
    this.index = null;
    this.renderer.setStyle(this.menu.nativeElement, 'visibility', 'hidden');
  }

  onSelectAction(action: any): void {
    if (action.action) {
      action.action();
    } else {
      this.selectAction.emit({ action, item: this.item, index: this.index });
    }

    this.close();
  }

  ngOnDestroy(): void {
    this.renderer.removeChild(document.body, this.el.nativeElement);
    this.subscriptions.unsubscribe();
  }
}
