import { ApplyToWordOptions } from '@progress/kendo-angular-editor';
import { ActiveMarks } from '@progress/kendo-angular-editor/common/active-marks';
import {
  EditorState,
  activeNode,
  addColumnAfter,
  addColumnBefore,
  addRowAfter,
  addRowBefore,
  blockquote,
  bold,
  canBeIndented,
  canIndentAsListItem,
  canOutdentAsListItem,
  cleanFormatting,
  deleteColumn,
  deleteRow,
  deleteTable,
  expandSelection,
  getActiveMarks,
  hasMark,
  hasNode,
  indentRules,
  isAligned,
  isIndented,
  italic,
  link,
  mergeCells,
  outdentRules,
  redo,
  splitCell,
  strikethrough,
  subscript,
  superscript,
  underline,
  undo,
} from '@progress/kendo-editor-common';
import { StyleType, TemplateStyle } from './../../../../views/admin-olc/models/template';
import {
  getActiveBlockStyle,
  getActiveInlineStyle,
  getSelectedFontProperty,
  hasDefaultParagraphOnly,
  oneOrMoreFontProperty,
} from './utils';

interface IRequiredItemState<T = boolean> {
  selected: T;
}
interface IItemState<T = boolean> extends IRequiredItemState<T> {
  disabled: boolean;
}
export interface IToolbarState {
  alignCenter: IItemState;
  alignJustify: IItemState;
  alignLeft: IItemState;
  alignRight: IItemState;
  bold: IItemState;
  format: IItemState<{ tag: string }>;
  blockStyle: IItemState<string>;
  inlineStyle: IItemState<string>;
  blockquote: IItemState;
  indent: IItemState;
  insertOrderedList: IItemState;
  insertUnorderedList: IItemState;
  italic: IItemState;
  unlink: IItemState;
  outdent: IItemState;
  redo: IItemState;
  selectAll: IItemState;
  strikethrough: IItemState;
  style: IItemState<ActiveMarks>;
  fontFamily: IItemState<string>;
  fontSize: IItemState<string>;
  oneOrMoreFontFamily: IRequiredItemState;
  oneOrMoreFontSize: IRequiredItemState;
  subscript: IItemState;
  superscript: IItemState;
  underline: IItemState;
  undo: IItemState;
  createLink: IItemState;
  insertFile: IItemState;
  insertImage: IItemState;
  viewSource: IItemState;
  print: IItemState;
  insertTable: IItemState;
  addColumnBefore: IItemState;
  addColumnAfter: IItemState;
  addRowBefore: IItemState;
  addRowAfter: IItemState;
  deleteRow: IItemState;
  deleteColumn: IItemState;
  mergeCells: IItemState;
  splitCell: IItemState;
  deleteTable: IItemState;
  cleanFormatting: IItemState;
}

export const getToolbarState = (
  state: EditorState,
  fontType: string,
  fontSize: string,
  olcTedStyles: TemplateStyle[] = [],
  isOlcTed = false,
  options?: {
    applyToWord: boolean | ApplyToWordOptions;
  }
): IToolbarState => {
  const blockStyles = olcTedStyles.filter((s) => s.elementType === StyleType.Block);
  const inlineStyles = olcTedStyles.filter((s) => s.elementType === StyleType.Inline);

  const toolbarState: IToolbarState = {
    alignCenter: {
      selected: isAligned(state, alignCenterRules),
      disabled: false,
    },
    alignJustify: {
      selected: isAligned(state, alignJustifyRules),
      disabled: false,
    },
    alignLeft: {
      selected: isAligned(state, alignLeftRules),
      disabled: false,
    },
    alignRight: {
      selected: isAligned(state, alignRightRules),
      disabled: false,
    },
    bold: {
      selected: hasMark(state, bold),
      disabled: hasNode(state, state.schema.nodes['image']),
    },
    format: {
      selected: activeNode(state),
      disabled: false,
    },
    blockStyle: {
      selected: getActiveBlockStyle(state, blockStyles),
      disabled: false,
    },
    inlineStyle: {
      selected: getActiveInlineStyle(state, inlineStyles),
      disabled: hasNode(state, state.schema.nodes['image']),
    },
    blockquote: {
      selected: false,
      disabled: !blockquote(state),
    },
    indent: {
      selected: false,
      disabled: !(canIndentAsListItem(state, state.schema.nodes['list_item']) || canBeIndented(state, indentRules)),
    },
    insertOrderedList: {
      selected: hasNode(state, state.schema.nodes['ordered_list']),
      disabled: false,
    },
    insertUnorderedList: {
      selected: hasNode(state, state.schema.nodes['bullet_list']),
      disabled: false,
    },
    italic: {
      selected: hasMark(state, italic),
      disabled: hasNode(state, state.schema.nodes['image']),
    },
    unlink: {
      selected: false,
      disabled: !hasMark(state, link),
    },
    outdent: {
      selected: false,
      get disabled() {
        return !(
          hasNode(state, state.schema.nodes['blockquote']) ||
          canOutdentAsListItem(state, outdentRules) ||
          isIndented(state, outdentRules.nodes)
        );
      },
    },
    redo: {
      selected: false,
      disabled: !redo(state),
    },
    selectAll: {
      selected: false,
      disabled: false,
    },
    strikethrough: {
      selected: hasMark(state, strikethrough),
      disabled: hasNode(state, state.schema.nodes['image']),
    },
    style: {
      selected: getActiveMarks(state, state.schema.marks['style']),
      disabled: false,
    },
    fontFamily: {
      selected: getSelectedFontProperty(state, 'font-family', fontType),
      disabled: false,
    },
    fontSize: {
      selected: getSelectedFontProperty(state, 'font-size', fontSize),
      disabled: false,
    },
    oneOrMoreFontFamily: {
      selected: oneOrMoreFontProperty(state, 'font-family'),
    },
    oneOrMoreFontSize: {
      selected: oneOrMoreFontProperty(state, 'font-size'),
    },
    subscript: {
      selected: hasMark(state, subscript),
      disabled: false,
    },
    superscript: {
      selected: hasMark(state, superscript),
      disabled: false,
    },
    underline: {
      selected: hasMark(state, underline),
      disabled: hasNode(state, state.schema.nodes['image']),
    },
    undo: {
      selected: false,
      disabled: !undo(state),
    },
    createLink: {
      selected: false,
      get disabled() {
        const empty = state.selection.empty;
        const applyToWord = options && options.applyToWord;
        if (applyToWord && empty) {
          const extendedState = expandSelection(state, () => {}, options).state;
          return extendedState.selection.empty;
        }
        return empty;
      },
    },
    insertFile: {
      selected: false,
      disabled: state.selection.empty,
    },
    insertImage: {
      selected: false,
      disabled: false,
    },
    viewSource: {
      selected: false,
      disabled: false,
    },
    print: {
      selected: false,
      disabled: false,
    },
    insertTable: {
      selected: false,
      disabled: false,
    },
    addColumnBefore: {
      selected: false,
      disabled: !addColumnBefore(state),
    },
    addColumnAfter: {
      selected: false,
      disabled: !addColumnAfter(state),
    },
    addRowBefore: {
      selected: false,
      disabled: !addRowBefore(state),
    },
    addRowAfter: {
      selected: false,
      disabled: !addRowAfter(state),
    },
    deleteRow: {
      selected: false,
      disabled: !deleteRow(state),
    },
    deleteColumn: {
      selected: false,
      disabled: !deleteColumn(state),
    },
    mergeCells: {
      selected: false,
      disabled: !mergeCells(state),
    },
    splitCell: {
      selected: false,
      disabled: !splitCell(state),
    },
    deleteTable: {
      selected: false,
      disabled: !deleteTable(state),
    },
    cleanFormatting: {
      selected: false,
      disabled:
        (isOlcTed && !cleanFormatting()(state) && hasDefaultParagraphOnly(state, blockStyles)) ||
        (!isOlcTed &&
          !hasMark(state, bold) &&
          !hasMark(state, italic) &&
          !hasMark(state, underline) &&
          !hasMark(state, strikethrough)),
    },
  };

  return toolbarState;
};

const style = (name, value) => ({ name: name, value: value });

const alignLeftRules = [
  { node: 'paragraph', style: [style('text-align', 'left')] },
  { node: 'heading', style: [style('text-align', 'left')] },
  { node: 'div', style: [style('text-align', 'left')] },
  { node: 'pre', style: [style('text-align', 'left')] },
];

const alignRightRules = [
  { node: 'paragraph', style: [style('text-align', 'right')] },
  { node: 'heading', style: [style('text-align', 'right')] },
  { node: 'div', style: [style('text-align', 'right')] },
  { node: 'pre', style: [style('text-align', 'right')] },
];

const alignCenterRules = [
  { node: 'paragraph', style: [style('text-align', 'center')] },
  { node: 'heading', style: [style('text-align', 'center')] },
  { node: 'div', style: [style('text-align', 'center')] },
  { node: 'pre', style: [style('text-align', 'center')] },
];

const alignJustifyRules = [
  { node: 'paragraph', style: [style('text-align', 'justify')] },
  { node: 'heading', style: [style('text-align', 'justify')] },
  { node: 'div', style: [style('text-align', 'justify')] },
  { node: 'pre', style: [style('text-align', 'justify')] },
];
