import { ComponentRef, Injectable, ViewContainerRef } from '@angular/core';
import { LookupModalComponent } from './lookup-modal.component';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { LookupMatch } from '../../../models/lookup-models';
import { DelayService } from '../../../utils/delay.service';
import { IFindMetaDataById } from '../../../interop/MetaDataService';

@Injectable({
  providedIn: 'root',
})
export class LookupModalService {
  private componentRef: ComponentRef<LookupModalComponent>;
  viewContainerRef: ViewContainerRef;

  set loading(value: boolean) {
    if (!this.componentRef) return;

    this.componentRef.setInput(`loading`, value);
  }

  set matches(value: Array<LookupMatch>) {
    if (!this.componentRef) return;

    this.componentRef.setInput(`matches`, value);
  }

  get visible(): boolean {
    if (!this.componentRef) return false;

    return this.componentRef.instance.visible;
  }

  constructor(public ngxSmartModalService: NgxSmartModalService, private delay: DelayService) {}

  setRootViewContainer = (viewContainerRef: ViewContainerRef): void => {
    this.viewContainerRef = viewContainerRef;
  };

  show(
    value: string,
    matches: Array<LookupMatch>,
    placeholder: string,
    lookupModalKey: string,
    findMetaDataService: IFindMetaDataById,
    onSelectValueHandler?: (rowIndex: number) => void,
    onSearchHandler?: (searchText: string) => void,
    onCloseHandler?: () => void
  ) {
    this.componentRef = this.viewContainerRef.createComponent(LookupModalComponent);

    this.componentRef.instance.onClose.subscribe(() => {
      this.close();
      onCloseHandler?.();
    });

    if (onSelectValueHandler) this.componentRef.instance.onSelectValue.subscribe(onSelectValueHandler);
    if (onSearchHandler) this.componentRef.instance.onSearch.subscribe(onSearchHandler);

    this.componentRef.setInput(`value`, value ?? '');
    this.componentRef.setInput(`matches`, matches);
    this.componentRef.setInput(`placeholder`, placeholder);
    this.componentRef.setInput(`lookupModalKey`, lookupModalKey);
    this.componentRef.setInput(`findMetaDataService`, findMetaDataService);

    this.delay.execute(this.componentRef.instance.show, 100);
  }

  close = (): void => {
    if (!this.componentRef) return;

    this.viewContainerRef.clear();
    this.componentRef.destroy();
    this.componentRef = null;
  };
}
