import { Component, EventEmitter, OnDestroy, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { IPrePaidPart, OutboundPricing, PrePaidPart } from '../../InterFAX/Models/admin';
import { InterFAXService } from '../../services/interfax.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-interfax-repeat-order',
  templateUrl: './interfax-repeat-order.component.html',
  styleUrls: ['./interfax-repeat-order.component.scss'],
})
export class InterfaxRepeatOrderComponent implements OnInit, OnDestroy {
  @ViewChild('spinnerElement', { static: true })
  spinnerElement;

  @Output() closeModal = new EventEmitter();

  title: string;
  noRepeatOrderText: string;

  show = false;
  errors = new Array<string>();

  prePaidParts: Array<IPrePaidPart>;
  selected: IPrePaidPart;

  outboundPricing: OutboundPricing;
  subscriptions = new Subscription();

  constructor(
    private translateService: TranslateService,
    private spinnerService: SpinnerStateService,
    private interfaxService: InterFAXService,
    private toastrService: ToastrService
  ) {}

  ngOnInit(): void {
    this.noRepeatOrderText = this.translateService.instant('interfax-repeat-order.no-repeat-order');
    this.title = this.translateService.instant('interfax-repeat-order.title');

    this.load();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  load = (): void => {
    this.spinnerService.show(this.translateService.instant('Common.Loading'), this.spinnerElement.nativeElement);
    this.subscriptions.add(this.interfaxService.getAccountOutboundPricing('', this.pricingLoaded, this.loadFailed));
  };

  pricingLoaded = (op: OutboundPricing): void => {
    this.outboundPricing = op;
    this.prePaidParts = this.outboundPricing.prePaidParts;

    this.subscriptions.add(this.interfaxService.getAccountRepeatOrder(this.repeatOrderLoaded, this.loadFailed));
  };

  repeatOrderLoaded = (rp: PrePaidPart): void => {
    this.selected = rp;

    this.spinnerService.hide();
    this.show = true;
  };

  loadFailed = (): void => {
    //tbd
  };

  save = (): void => {
    this.spinnerService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);

    const partNumber = this.selected == null ? -1 : this.selected.basePart.number;
    this.interfaxService.setAccountRepeatOrder(partNumber, this.saved, this.saveFailed);
  };

  saved = (): void => {
    this.toastrService.success(this.translateService.instant('interfax-repeat-order.saved-successfully'));
    this.spinnerService.hide();
    this.close();
  };

  saveFailed = (errs): void => {
    this.spinnerService.hide();
    this.errors = errs;
  };

  onSelectPart = (part: IPrePaidPart): void => {
    this.selected = part;
  };

  close = (): void => {
    this.spinnerService.hide();
    this.show = false;
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.close();
  };
}
