import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { FieldDefinition } from 'shared-code-lib';
import { CustomProperty } from '../../../InterFAX/Models/admin';
import { InboundDocument } from '../../../InterFAX/Models/inbound';

@Component({
  selector: 'app-document-properties-custom-properties',
  templateUrl: './document-properties-custom-properties.component.html',
  styleUrls: ['./document-properties-custom-properties.component.scss'],
})
export class DocumentPropertiesCustomPropertiesComponent implements OnInit {
  @Input() document: InboundDocument;
  @Input() customProperties: CustomProperty[];
  @Output() scrollEnded = new EventEmitter<'start' | 'end'>();

  fields: FieldDefinition[];

  constructor() {}

  ngOnInit(): void {
    this.createFields();
  }

  createFields = (): void => {
    this.fields = [];

    for (const cp of this.customProperties) {
      const fd = new FieldDefinition({
        type: cp.getMetaDataType(),
        label: cp.name,
        placeholder: '',
        required: false,
      });

      this.fields.push(fd);
    }
  };

  getFieldValue = (cp: CustomProperty): string => {
    if (!this.document || !this.document.metaData) return '';

    const md = this.document.metaData.get(cp.name);
    if (!md) return '';

    return md.value.toString();
  };

  setFieldValue = (cp: CustomProperty, value: string): void => {
    this.document.metaData.set(cp.name, value);
  };

  onScrollReachStart() {
    this.scrollEnded.emit('start');
  }

  onScrollReachEnd() {
    this.scrollEnded.emit('end');
  }
}
