import { Component, ElementRef, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { ActivatedRoute, Params } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { Subscription } from 'rxjs';
import { BrandDetails, BrandingService, DelayService, PrintToService } from 'shared-code-lib';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-print-to',
  templateUrl: './print-to.component.html',
  styleUrls: ['./print-to.component.scss'],
})
export class PrintToComponent implements OnInit, OnDestroy {
  @ViewChild('loginComponent', { static: true })
  loginDiv: ElementRef;

  logoColor: string;

  subscriptions = new Subscription();

  constructor(
    private printToService: PrintToService,
    private route: ActivatedRoute,
    private spinnerState: SpinnerStateService,
    private translate: TranslateService,
    private brandingService: BrandingService,
    private delayService: DelayService
  ) {
    this.updateBrandDetails(this.brandingService.getBrandDetails());
  }

  ngOnInit(): void {
    this.subscriptions.add(
      this.route.params.subscribe((p: Params) => {
        this.printToService.start(p.type);
      })
    );

    this.subscriptions.add(
      this.brandingService.onBrandDetailsUpdated.subscribe((bd) => {
        this.updateBrandDetails(bd);

        this.delayService.execute(() => {
          this.spinnerState.show(this.translate.instant('print-to.logging-in'), this.loginDiv.nativeElement);
        });
      })
    );
  }

  updateBrandDetails = (bd: BrandDetails): void => {
    this.logoColor = bd?.loginLogoUrl;
    if (bd?.primaryColor) {
      document.documentElement.style.setProperty('--brand-primary-color', bd.primaryColor);
    }

    if (bd?.secondaryColor) {
      document.documentElement.style.setProperty('--brand-secondary-color', bd.secondaryColor);
    }

    if (bd?.favIconUrl) {
      this.changeFavIcon(bd.favIconUrl);
    }
  };

  changeFavIcon = (url: string): void => {
    const favIconId = 'dynamic-favicon';

    const link = document.createElement('link');
    link.id = favIconId;
    link.rel = 'shortcut icon';
    link.href = url;

    const oldLink = document.getElementById(favIconId);
    if (oldLink) {
      document.head.removeChild(oldLink);
    }

    document.head.appendChild(link);
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
