import { HTTP_INTERCEPTORS, HttpBackend, provideHttpClient, withInterceptorsFromDi } from '@angular/common/http';
import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';
import { RTL } from '@progress/kendo-angular-l10n';

import { NgIdleKeepaliveModule } from '@ng-idle/keepalive';
import { TranslateLoader, TranslateModule } from '@ngx-translate/core';
import { NgxSmartModalModule } from 'ngx-smart-modal';
import { ToastrModule } from 'ngx-toastr';
import { MultiTranslateHttpLoader } from 'ngx-translate-multi-http-loader';

import { PERFECT_SCROLLBAR_CONFIG, PerfectScrollbarConfigInterface } from 'ngx-perfect-scrollbar-portable';

import { registerLocaleData } from '@angular/common';
import localeAr from '@angular/common/locales/ar';
import localeDa from '@angular/common/locales/da';
import localeDe from '@angular/common/locales/de';
import localeEs from '@angular/common/locales/es';
import localeFr from '@angular/common/locales/fr';
import localeHe from '@angular/common/locales/he';
import localeIt from '@angular/common/locales/it';
import localeJa from '@angular/common/locales/ja';
import localePt from '@angular/common/locales/pt';
import localeRu from '@angular/common/locales/ru';
import localeSq from '@angular/common/locales/sq';
import localeTr from '@angular/common/locales/tr';
import localeZh from '@angular/common/locales/zh';
import { ServiceWorkerModule } from '@angular/service-worker';
import {
  AlertsModule,
  Analytics,
  CharactersValidator,
  CompleteInfoModule,
  ErrorPageModule,
  Languages,
  LoginCompleteModule,
  LoginModule,
  LoginPasswordModule,
  LoginTenantsModule,
  LoginTermsOfServiceModule,
  ModalHeaderModule,
  PasswordHelpModule,
  PreventDragModule,
  ResetPasswordModule,
  SsoCallbackModule,
  ThreeDSCallbackModule,
} from 'shared-code-lib';
import { UserActivationModule } from '../../../../Bamba.Shared/src/auth/user-activation/user-activation.module';
import { environment } from '../environments/environment';
import { AppRoutingModule } from './app-routing.module';
import { AppComponent, SafePipe } from './app.component';
import { APP_CONFIG, AppConfig } from './app.config';
import { AuthInterceptor } from './blocks/auth/auth.interceptor';
import { MobileRegistrationModule } from './blocks/auth/mobile-registration/mobile-registration.module';
import { ComponentsModule } from './blocks/components/components.module';
import { IManageModule } from './blocks/imanage/imanage.module';
import { ModalsModule } from './blocks/modals/modals.module';
import { NgxSpinnerModule } from './blocks/ngx-spinner/src/public_api';
import { PageModule } from './blocks/page/page.module';
import { NoCacheInterceptorService } from './blocks/services/no-cache-interceptor.service';

function registerLocalesData() {
  registerLocaleData(localeAr);
  registerLocaleData(localeDa);
  registerLocaleData(localeDe);
  registerLocaleData(localeEs);
  registerLocaleData(localeFr);
  registerLocaleData(localeHe);
  registerLocaleData(localeIt);
  registerLocaleData(localeJa);
  registerLocaleData(localePt);
  registerLocaleData(localeRu);
  registerLocaleData(localeSq);
  registerLocaleData(localeTr);
  registerLocaleData(localeZh);
}

registerLocalesData();

export function HttpLoaderFactory(http: HttpBackend) {
  return new MultiTranslateHttpLoader(http, [
    { prefix: './assets/i18n/', suffix: '.json' },
    { prefix: './assets/shared/i18n/', suffix: '.json' },
  ]);
}

const DEFAULT_PERFECT_SCROLLBAR_CONFIG: PerfectScrollbarConfigInterface = {
  wheelSpeed: 0.5,
  minScrollbarLength: 30,
};

@NgModule({
  declarations: [AppComponent, SafePipe],
  bootstrap: [AppComponent],
  imports: [
    LoginModule,
    LoginPasswordModule,
    LoginTenantsModule,
    LoginCompleteModule,
    LoginTermsOfServiceModule,
    PasswordHelpModule,
    CompleteInfoModule,
    SsoCallbackModule,
    ResetPasswordModule,
    ErrorPageModule,
    ThreeDSCallbackModule,
    UserActivationModule,
    IManageModule,
    BrowserModule,
    BrowserAnimationsModule,
    AppRoutingModule,
    NgxSmartModalModule.forRoot(),
    NgIdleKeepaliveModule.forRoot(),
    ToastrModule.forRoot({
      timeOut: 10000,
      positionClass: 'toast-top-center',
      preventDuplicates: true,
    }),
    TranslateModule.forRoot({
      loader: {
        provide: TranslateLoader,
        useFactory: HttpLoaderFactory,
        deps: [HttpBackend],
      },
    }),
    MobileRegistrationModule,
    PageModule,
    ModalsModule,
    ComponentsModule,
    NgxSpinnerModule,
    ModalHeaderModule,
    PreventDragModule,
    AlertsModule,
    environment.production ? ServiceWorkerModule.register('ngsw-worker.js') : [],
  ],
  providers: [
    { provide: APP_CONFIG, useValue: AppConfig },
    {
      provide: PERFECT_SCROLLBAR_CONFIG,
      useValue: DEFAULT_PERFECT_SCROLLBAR_CONFIG,
    },
    { provide: HTTP_INTERCEPTORS, useClass: NoCacheInterceptorService, multi: true },
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AuthInterceptor,
      multi: true,
    },
    {
      provide: RTL,
      useFactory: Languages.isRTLLanguage,
    },
    { provide: Analytics, useClass: Analytics },
    { provide: CharactersValidator, useClass: CharactersValidator },
    provideHttpClient(withInterceptorsFromDi()),
  ],
})
export class AppModule {}
