import { TranslateService } from '@ngx-translate/core';
import { ICombinedColumn } from './column';
import { ColumnDisplayType } from '../utils/enums';

export class InvokeAction {
  action: any;
  item: any;
  index: number;
}

export class TableItem {
  expanded = false;
  selected = false;
  showCheckbox = false;
  detailsTab = '';
  data: any;

  constructor(item: any, private columns: Array<ICombinedColumn>, translate: TranslateService) {
    this.data = item;
    this.data.values = {};

    this.buildColumnValues(this.columns, translate);
  }

  buildColumnValues = (columns: Array<ICombinedColumn>, translate: TranslateService): void => {
    this.columns = columns;

    for (const c of this.columns) {
      this.data.values[c.id] = this.getItemValue(c, translate);
    }
  };

  getItemValue = (column: ICombinedColumn, translate: TranslateService): string | Date | boolean => {
    if (!this.data) return '';

    let value: any;
    const metadataPrefix = 'extendedDetails.metaData.';

    if (column.itemProperty.startsWith(metadataPrefix)) {
      if (!this.data.extendedDetails.metaData) return '';

      const md = column.itemProperty.substring(metadataPrefix.length).toLowerCase();
      value =
        this.data.extendedDetails.metaData[md] && this.data.extendedDetails.metaData[md].value != ''
          ? column.displayType == ColumnDisplayType.Date
            ? new Date(this.data.extendedDetails.metaData[md].value)
            : this.data.extendedDetails.metaData[md].value
          : '';
    } else {
      const properties = column.itemProperty.split('.');

      let current = this.data;
      for (let prop of properties) {
        current = value = current[prop];
        if (!current) break;
      }
    }

    if (value instanceof Array) {
      if (column.displayArrayContent) {
        return (value as Array<any>).map((x) => (typeof x === 'object' ? x.name || x.value : x)).join(', ');
      } else {
        return `${value.length.toString()} ${translate.instant('general.line-items-row-count')}`;
      }
    }

    if (typeof value !== 'boolean') return value;

    value = column.invertBooleanValue ? !value : value;
    return value ? translate.instant('general.yes') : translate.instant('general.no');
  };
}
