import { Subject } from 'rxjs';
import { TranslateService } from '@ngx-translate/core';
import { IFieldOptions, IFieldDataSource } from './field-definition';
import { IFeatureAvailableService } from '../interop/IFeatureAvailableService';

export class DeliveryFormat {
  public nameId: string;
  public finalformcode: string;
  public ocr: boolean;
  public singlePage: boolean;

  public constructor(nameId: string, ffc: string, ocr: boolean, singlePage: boolean) {
    this.nameId = nameId;
    this.finalformcode = ffc;
    this.ocr = ocr;
    this.singlePage = singlePage;
  }
}

export class DeliveryFormats {
  private static all: Array<DeliveryFormat> = null;
  private static categorized: Array<Array<DeliveryFormat>> = [];

  public static All = (): DeliveryFormat[] => {
    if (DeliveryFormats.all == null) {
      DeliveryFormats.all = new Array<DeliveryFormat>();

      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-pdf', 'pdf', false, false));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-tif', 'tif', false, false));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-s-tif', 's.tif', true, true));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-s-jpg', 's.jpg', true, true));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-ocr-pdf', 'ocr.pdf', true, false));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-ocr-rtf', 'ocr.rtf', true, false));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-ocr-txt', 'ocr.txt', true, false));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-ocr-doc', 'ocr.doc', true, false));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-ocr-docx', 'ocr.docx', true, false));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-ocr-xls', 'ocr.xls', true, false));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-ocr-xlsx', 'ocr.xlsx', true, false));
      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-arc-pdf', 'arc.pdf', false, false));

      DeliveryFormats.all.push(
        new DeliveryFormat('workflow-step.delivery-format-arc-ocr-pdf', 'arc.ocr.pdf', true, false)
      );

      DeliveryFormats.all.push(
        new DeliveryFormat('workflow-step.delivery-format-arc-txt-pdf', 'arc.txt.pdf', true, false)
      );

      DeliveryFormats.all.push(new DeliveryFormat('workflow-step.delivery-format-txt-pdf', 'txt.pdf', true, false));
    }

    return DeliveryFormats.all;
  };

  public static Categorized = (): Array<Array<DeliveryFormat>> => {
    if (!DeliveryFormats.categorized.length) {
      DeliveryFormats.categorized.push([
        new DeliveryFormat('workflow-step.delivery-format-ocr-pdf', 'ocr.pdf', true, false),
        new DeliveryFormat('workflow-step.delivery-format-txt-pdf', 'txt.pdf', true, false),
        new DeliveryFormat('workflow-step.delivery-format-arc-ocr-pdf', 'arc.ocr.pdf', true, false),
        new DeliveryFormat('workflow-step.delivery-format-arc-txt-pdf', 'arc.txt.pdf', true, false),
      ]);

      DeliveryFormats.categorized.push([
        new DeliveryFormat('workflow-step.delivery-format-ocr-doc', 'ocr.doc', true, false),
        new DeliveryFormat('workflow-step.delivery-format-ocr-docx', 'ocr.docx', true, false),
        new DeliveryFormat('workflow-step.delivery-format-ocr-xls', 'ocr.xls', true, false),
        new DeliveryFormat('workflow-step.delivery-format-ocr-xlsx', 'ocr.xlsx', true, false),
      ]);

      DeliveryFormats.categorized.push([
        new DeliveryFormat('workflow-step.delivery-format-tif', 'tif', false, false),
        new DeliveryFormat('workflow-step.delivery-format-ocr-rtf', 'ocr.rtf', true, false),
        new DeliveryFormat('workflow-step.delivery-format-ocr-txt', 'ocr.txt', true, false),
      ]);
    }

    return DeliveryFormats.categorized;
  };
}

export class DeliveryFormatsDataSource implements IFieldDataSource {
  changed = new Subject<void>();

  constructor(
    private translate: TranslateService,
    private featureAvailableService: IFeatureAvailableService,
    private stepAllowedformats: string[] = null
  ) {}

  getItems(
    startsWith: string,
    currentValue: string,
    successCallBack: (items: IFieldOptions[]) => void,
    failureCallBack: (err: any) => void
  ): void {
    const items: IFieldOptions[] = [];

    this.addDeliveryFormats(items);

    successCallBack(items.sort((a, b) => a.name.localeCompare(b.name)));
  }

  getItemsEx = (): IFieldOptions[] => {
    const items: IFieldOptions[] = [];

    this.addDeliveryFormats(items);

    return items.sort((a, b) => a.name.localeCompare(b.name));
  };

  protected addDeliveryFormats(items: IFieldOptions[]) {
    this.addDeliveryFormat('workflow-step.delivery-format-pdf', 'pdf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-tif', 'tif', items);
    this.addDeliveryFormat('workflow-step.delivery-format-s-tif', 's.tif', items);
    this.addDeliveryFormat('workflow-step.delivery-format-s-jpg', 's.jpg', items);
    this.addDeliveryFormat('workflow-step.delivery-format-ocr-pdf', 'ocr.pdf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-ocr-rtf', 'ocr.rtf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-ocr-txt', 'ocr.txt', items);
    this.addDeliveryFormat('workflow-step.delivery-format-ocr-doc', 'ocr.doc', items);
    this.addDeliveryFormat('workflow-step.delivery-format-ocr-docx', 'ocr.docx', items);
    this.addDeliveryFormat('workflow-step.delivery-format-ocr-xls', 'ocr.xls', items);
    this.addDeliveryFormat('workflow-step.delivery-format-ocr-xlsx', 'ocr.xlsx', items);
    this.addDeliveryFormat('workflow-step.delivery-format-arc-pdf', 'arc.pdf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-arc-ocr-pdf', 'arc.ocr.pdf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-arc-txt-pdf', 'arc.txt.pdf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-txt-pdf', 'txt.pdf', items);
  }

  protected addDeliveryFormat(nameId: string, format: string, items: IFieldOptions[]): void {
    if (!this.featureAvailableService.hasFeature(`DeliveryFormat_${format}`)) return;

    if (this.stepAllowedformats && this.stepAllowedformats.length && !this.stepAllowedformats.includes(format)) return;

    items.push({ name: this.translate.instant(nameId), value: format });
  }
}

export class SplittableDeliveryFormatsDataSource extends DeliveryFormatsDataSource {
  protected addDeliveryFormats(items: IFieldOptions[]) {
    this.addDeliveryFormat('workflow-step.delivery-format-pdf', 'pdf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-ocr-pdf', 'ocr.pdf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-arc-pdf', 'arc.pdf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-arc-ocr-pdf', 'arc.ocr.pdf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-arc-txt-pdf', 'arc.txt.pdf', items);
    this.addDeliveryFormat('workflow-step.delivery-format-txt-pdf', 'txt.pdf', items);
  }
}
