import { AfterViewInit, Component, EventEmitter, Input, OnDestroy, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { SpinnerStateService } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { ISpinnerService } from '../interop/ISpinnerService';

import { Subscription } from 'rxjs';
import { IInterFAXService } from '../interop/IInterFAXService';
import { ContactList } from '../models/interfax/contactlist';
import { FieldDefinition } from './../models/field-definition';
import { MetaDataType } from './../models/metadata-definition';
import { FaxMobileActionData } from './../models/mobile-action-data';

@Component({
  selector: 'app-fax-submission-ui',
  templateUrl: './fax-submission-ui.component.html',
  styleUrls: ['./fax-submission-ui.component.scss'],
})
export class FaxSubmissionUiComponent implements OnInit, AfterViewInit, OnDestroy {
  @Input() actionData: FaxMobileActionData;
  @Input() isFormSubmitted = false;
  @Input() spinnerService: ISpinnerService;
  @Input() interfaxService: IInterFAXService;
  @Input() allowRecipientsModals: boolean = true;
  @Input() allowSaveToContactList: boolean = false;

  @Output() onValidationChange = new EventEmitter<boolean>();

  uiReady = false;

  contactLists: Array<ContactList>;

  fieldFaxNumber: FieldDefinition;
  fieldSubject: FieldDefinition;
  fieldMessage: FieldDefinition;
  isFaxFormValid: boolean;
  faxFormErrors = '';

  subscriptions = new Subscription();

  constructor(private translateService: TranslateService, private spinnerState: SpinnerStateService) {}

  ngOnInit(): void {
    this.createFields();

    if (this.allowSaveToContactList) {
      this.spinnerState.show(this.translateService.instant('mobile-capture.loading-contact-lists'), document.body);
      this.subscriptions.add(
        this.interfaxService.getContactLists(this.contactListsLoaded, this.contactListsLoadFailed)
      );
    }

    this.uiReady = !this.allowSaveToContactList;
  }

  contactListsLoaded = (cls: ContactList[]): void => {
    this.spinnerState.hide();
    this.contactLists = cls;
    this.uiReady = true;
  };

  contactListsLoadFailed = (): void => {
    this.spinnerState.hide();

    this.contactLists = [];
    this.uiReady = true;
  };

  ngAfterViewInit(): void {
    this.checkFaxFormValidity();
  }

  createFields() {
    this.fieldFaxNumber = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('fax-action.label-faxnumber'),
      placeholder: '',
      required: true,
    });

    this.fieldSubject = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('fax-action.label-subject'),
      placeholder: this.translateService.instant('fax-action.label-subject-hint'),
      required: false,
    });

    this.fieldMessage = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('fax-action.label-message'),
      placeholder: this.translateService.instant('fax-action.label-message-hint'),
      required: false,
    });

    this.isFaxFormValid = false;
  }

  onRecipientsChanged = (recipients: any[]): void => {
    this.actionData.recipients = recipients;
    this.checkFaxFormValidity();
  };

  checkFaxFormValidity(): boolean {
    this.isFaxFormValid = true;
    this.faxFormErrors = '';

    if (!this.actionData.recipients || this.actionData.recipients.length == 0) {
      this.isFaxFormValid = false;
      this.faxFormErrors = this.translateService.instant('fax-action.fax-number-required-error');
    }

    this.onValidationChange.emit(this.isFaxFormValid);

    return this.isFaxFormValid;
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
