export class UserDocumentLimits implements IUserDocumentLimits {
  overrideTenantLimits: boolean;
  monthlyPageLimit: number;
  documentPageLimit: number;
  constructor(initializer?: IUserDocumentLimits) {
    this.overrideTenantLimits = initializer ? initializer.overrideTenantLimits : false;
    this.monthlyPageLimit = initializer ? initializer.monthlyPageLimit : 250;
    this.documentPageLimit = initializer ? initializer.documentPageLimit : 100;
  }

  public serializable(): IUserDocumentLimits {
    return {
      overrideTenantLimits: this.overrideTenantLimits,
      monthlyPageLimit: this.monthlyPageLimit,
      documentPageLimit: this.documentPageLimit,
    };
  }
}

