export class Folder implements IFolder {
  pageUrl: string;
  public id: string;
  public name: string;
  public columns: Array<IColumn>;
  public includeMetaDataAsColumns: boolean;
  public defaultColumns: Array<IDefaultColumn>;
  public defaultAction: IDefaultAction;
  public actions: Array<IAction>;
  public product: Product;
  public displayMode: FolderDisplayMode;
  public icon: string;
  public folderType: FolderType;
  public supportsDetailsExpansion: boolean;
  public supportsCheckboxSelection: boolean;
  public supportActions: boolean;
  public supportsVersions: boolean;
  public filters: Array<Filter>;
  public defaultSortByColumn: SortBy;
  public crumbs: Array<Crumb>;
  public showPreview: boolean;
  public allowDocumentNameEditing: boolean;
  public showViewDropList: boolean;
  public forceReload: boolean;
  public parentFolderId: string;
  public details: Array<IFolderDetails>;
  public headerText: string;
  public simplifiedColumnsArrangement: string[][];

  constructor(initializer: IFolder, p: Product) {
    if (initializer == null) throw new Error('Invalid folder initializer');

    this.headerText = initializer.headerText;
    this.product = p;
    this.id = initializer.id;
    this.name = initializer.name;
    this.displayMode = initializer.displayMode;
    this.supportsDetailsExpansion = initializer.supportsDetailsExpansion;
    this.supportsCheckboxSelection = initializer.supportsCheckboxSelection;
    this.supportActions = initializer.supportActions;
    this.supportsVersions = initializer.supportsVersions;
    this.icon = initializer.icon;
    this.folderType = initializer.folderType;
    this.defaultSortByColumn = initializer.defaultSortByColumn;
    this.showPreview = initializer.showPreview;
    this.allowDocumentNameEditing = initializer.allowDocumentNameEditing;
    this.showViewDropList = initializer.showViewDropList;
    this.forceReload = initializer.forceReload;
    this.parentFolderId = initializer.parentFolderId;

    this.details = initializer.details.map((d) => new FolderDetails(d));

    this.includeMetaDataAsColumns = initializer.includeMetaDataAsColumns;

    this.crumbs = initializer.crumbs.map((c) => new Crumb(c));

    this.columns = initializer.columns.map((item) => {
      return new Column(
        item.displayType,
        item.headerImage,
        item.headerText,
        item.id,
        item.itemProperty,
        item.columnName,
        item.width,
        item.sortable,
        item.stretch,
        item.sortByFieldName,
        item.invertBooleanValue,
        item.displayArrayContent,
        item.groupingFormat,
        item.dynamicHeaderTexts || [],
        item.shouldAppendHeaderToValue,
        item.ignoreHeaderForEmptyValue
      );
    });

    this.defaultColumns = initializer.defaultColumns.map((item) => {
      return new DefaultColumn(item.id, item.width, item.stretch);
    });

    this.simplifiedColumnsArrangement = initializer.simplifiedColumnsArrangement;

    this.actions = initializer.actions.map((item) => {
      return new Action(
        item.id,
        item.name,
        item.url,
        item.icon,
        item.iconSelected,
        item.selectionType,
        item.type,
        item.confirmationText,
        item.confirmationButtonText,
        item.leftNavRoute,
        item.order,
        item.settingsCategory,
        item.executeWhen
      );
    });

    this.filters = initializer.filters.map((f) => FilterFactory.Create(f));

    this.pageUrl = `/${this.product.id}/${this.id}`;
  }
}

