export class Action implements IAction {
  iconUrl: string;
  iconSelectedUrl: string;

  constructor(
    public id: string,
    public name: string,
    public url: string,
    public icon: string,
    public iconSelected: string,
    public selectionType: number,
    public type: number,
    public confirmationText: string,
    public confirmationButtonText: string,
    public leftNavRoute: string,
    public order: number,
    public settingsCategory: string,
    public executeWhen: ExecuteCriteria
  ) {
    this.iconUrl = this.getIconUrl(icon);

    if (!iconSelected) {
      this.iconSelected = this.icon;
      this.iconSelectedUrl = this.iconUrl;
    } else {
      this.iconSelectedUrl = this.getIconUrl(iconSelected);
    }
  }

  getIconUrl(icon: string) {
    return `assets/img/${icon}`;
  }
}

