export class IDictionary {
  key: string;
  value: string;
}

export class Dictionary implements IDictionary {
  key = '';
  value = '';
  constructor(key: string, value: string) {
    this.key = key ? key : this.key;
    this.value = value ? value : this.value;
  }
  updateValue(value: string): void {
    this.value = value ? value : this.value;
  }
  updateKey(key: string): void {
    this.key = key ? key : this.key;
  }
}

export class IControl {
  action: () => void;
  label: string;
  cssClass: string;
  imageUrl: string;
  title: string;
  type: string;
  isDisabled: boolean;
  isVisible: boolean;
  actionConfirmation: () => boolean;
  show: () => void;
  hide: () => void;
}

export class Control implements IControl {
  action: any;
  label: string;
  cssClass: string;
  imageUrl: string;
  title: string;
  type: string;
  isDisabled: boolean;
  isVisible: boolean;
  actionConfirmation: any;
  data: any;

  constructor(
    action: any,
    label: string,
    cssClass: string,
    imageUrl: string,
    title: string,
    type: string,
    isDisabled: boolean,
    actionConfirmation?: any,
    data?: any,
    isVisible?: boolean
  ) {
    this.action = action;
    this.label = label;
    this.cssClass = cssClass || '';
    this.imageUrl = imageUrl || '';
    this.title = title;
    this.type = type || '';
    this.isDisabled = isDisabled;
    this.actionConfirmation = actionConfirmation;
    this.data = data;
    this.isVisible = isVisible == null ? true : isVisible;
  }

  setTranslation(newLabel: string, newTitle?: string) {
    this.updateLabel(newLabel);
    this.updateTitle(newTitle ? newTitle : newLabel);
  }

  updateLabel(newLabel) {
    this.label = newLabel;
  }

  updateTitle(newTitle) {
    this.title = newTitle;
  }

  disableControl(isDisabled) {
    this.isDisabled = isDisabled;
  }

  show() {
    this.isVisible = true;
  }

  hide() {
    this.isVisible = false;
  }
}

