import { Injectable } from '@angular/core';

import { Subject } from 'rxjs';

import { Annotation, MetaDataCollection, MetaDataValueType } from 'shared-code-lib';
import { IOutcome } from '../../../blocks/models/outcome';
import { WorkItem } from '../../../blocks/models/work-item';
import { Workflow } from '../../../blocks/models/workflow';
import { WorkflowFolder } from '../../../blocks/models/workflow-folder';
import { CapturedDocument, LineItemHeader, Page, UpdateLineItemsEvent, ValueLocation } from '../capture-models';
@Injectable({
  providedIn: 'root',
})
export class CaptureUpdateService {
  private _workflowSubject = new Subject<Workflow>();
  private _folderSubject = new Subject<WorkflowFolder>();
  private _folderSelectionSubject = new Subject<boolean>();
  private _documentSubject = new Subject<CapturedDocument>();
  private _annotationSubject = new Subject<Annotation[]>();
  private _scrollToDocument = new Subject<string>();
  private _documentPageSubject = new Subject<Page>();
  private _outcomeButtonsSubject = new Subject<Array<IOutcome>>();
  private _lineItemTableHeadSubject = new Subject<LineItemHeader>();
  private _lineItemTableBodySubject = new Subject<UpdateLineItemsEvent>();

  private _expandFolder = new Subject<WorkflowFolder>();
  private _collapseFolder = new Subject<WorkflowFolder>();
  onExpandFolder = this._expandFolder.asObservable();
  onCollapseFolder = this._collapseFolder.asObservable();

  private _selectNextDocument = new Subject<void>();
  onSelectNextDocument = this._selectNextDocument.asObservable();

  private _indexValueLocationSubject = new Subject<string>();
  onFocusOnIndexValueValidLocation = this._indexValueLocationSubject.asObservable();

  private _valuesLocationSubject = new Subject<Array<ValueLocation>>();
  onGetValuesValidLocation = this._valuesLocationSubject.asObservable();

  private _valuesValidityValidLocationSubject = new Subject<any>();
  onChangeValueValidLocation = this._valuesValidityValidLocationSubject.asObservable();

  private _valuesValidityInValidLocationSubject = new Subject<any>();
  onChangeValueInValidLocation = this._valuesValidityInValidLocationSubject.asObservable();

  private _resizePanelsSubject = new Subject<void>();
  onPanelsResize = this._resizePanelsSubject.asObservable();

  private _rotatePageSubject = new Subject<void>();
  onRotatePage = this._rotatePageSubject.asObservable();

  private _metaDataUpdateSubject = new Subject<MetaDataCollection>();
  onWorkitemMetadataUpdated = this._metaDataUpdateSubject.asObservable();

  onChangeWorkflow = this._workflowSubject.asObservable();
  onChangeFolder = this._folderSubject.asObservable();
  onToggleEnableTransitionForFolders = this._folderSelectionSubject.asObservable();
  onChangeDocument = this._documentSubject.asObservable();
  onScrollToDocument = this._scrollToDocument.asObservable();
  onChangeDocumentPage = this._documentPageSubject.asObservable();
  onChangeOutcomeButtons = this._outcomeButtonsSubject.asObservable();
  onUpdateLineItemTableHead = this._lineItemTableHeadSubject.asObservable();
  onUpdateLineItemTableBody = this._lineItemTableBodySubject.asObservable();
  onChangeAnnotation = this._annotationSubject.asObservable();

  private _parentFolderChanged = new Subject<CapturedDocument>();
  onParentFolderChanged = this._parentFolderChanged.asObservable();

  constructor() {}

  updateWorkflow(currentWorkflow: Workflow) {
    this._workflowSubject.next(currentWorkflow);
    this._documentSubject.next(null);
  }

  updateFolder(folder: WorkflowFolder) {
    this._folderSubject.next(folder);
  }

  updateEnableOutcomeButtonsForFolders(status: boolean) {
    this._folderSelectionSubject.next(status);
  }

  updateDocument(currentDocument: CapturedDocument) {
    this._documentSubject.next(currentDocument);
  }

  updateParentFolder(currentDocument: CapturedDocument) {
    this._parentFolderChanged.next(currentDocument);
  }

  updateDocumentPage(page: Page) {
    this._documentPageSubject.next(page);
  }

  updateOutcomeButtons(outcomeButtons: Array<IOutcome>) {
    this._outcomeButtonsSubject.next(outcomeButtons);
  }

  expandFolder(folder: WorkflowFolder) {
    this._expandFolder.next(folder);
  }

  collapseFolder(folder: WorkflowFolder) {
    this._collapseFolder.next(folder);
  }

  selectNextDocument = () => {
    this._selectNextDocument.next();
  };

  updateLineItemTableHead(header: LineItemHeader) {
    this._lineItemTableHeadSubject.next(header);
  }

  updateLineItemTableBody(body: any) {
    this._lineItemTableBodySubject.next({ body });
  }

  scrollToDocument(id: string) {
    this._scrollToDocument.next(id);
  }

  zoomIntoValue(fieldId: string) {
    this._indexValueLocationSubject.next(fieldId);
  }

  hasValuesWithValidLocation(values: Array<ValueLocation>) {
    this._valuesLocationSubject.next(values);
  }

  changeValueValidity(object) {
    if (!object) return;

    if (object.location?.valid) {
      this._valuesValidityValidLocationSubject.next(object);
    } else {
      this._valuesValidityInValidLocationSubject.next(object);
    }
  }

  panelResized() {
    this._resizePanelsSubject.next();
  }

  reloadCurrentPage() {
    this._rotatePageSubject.next();
  }

  updateWorkitemMetadata(workItem: WorkItem, currentWorkItem: WorkItem) {
    this._metaDataUpdateSubject.next(workItem.metadata);

    if (currentWorkItem && workItem.id === currentWorkItem.id) {
      this.checkLineItemsUpdate(workItem.metadata);
    }
  }

  checkLineItemsUpdate = (metadata: MetaDataCollection): void => {
    const lineItemsMetaData = metadata.metadata?.filter((md) => md.valueType == MetaDataValueType.LineItems)?.pop();
    if (!lineItemsMetaData) return;

    this.updateLineItemTableBody(lineItemsMetaData.value);
  };

  changeAnnotation(annotation: Annotation[]) {
    this._annotationSubject.next(annotation);
  }
}
