import { EventEmitter, Injectable } from '@angular/core';
import { NgxSmartModalService } from 'ngx-smart-modal';

import { Router } from '@angular/router';
import { Idle } from '@ng-idle/core';
import { ApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/api.service';
import { SharedDataService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/shared-data.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { AuthorizationResult } from '../../auth/login-base/login-base.component';
import { ApiResult } from '../../models/ApiResult';
import { Strings } from '../../utils/strings.service';
import { BrandingService } from '../branding.service';
import { PrintToService } from '../print-to.service';
import { SessionStorageService } from '../session-storage.service';

declare const UES: any;

export class PasswordResetResult {
  promptForEmail: boolean;
}

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  private userStateLoaded = false;

  public onLogout = new EventEmitter();

  public onSessionExpired = new EventEmitter();

  private readonly uicTabSharingId = 'uic-tab-sharing-id';

  constructor(
    private apiService: ApiService,
    private ngxSmartModalService: NgxSmartModalService,
    private brandingService: BrandingService,
    private sessionStorageService: SessionStorageService,
    private idle: Idle,
    private sharedDataService: SharedDataService,
    private router: Router,
    private spinnerStateService: SpinnerStateService
  ) {}

  public sessionExpired = (): void => {
    this.onSessionExpired.emit();
  };

  public getUserSignOnDetails(username: string, successCallBack, failureCallBack) {
    this.apiService.postItemtoServer(`user/signondetails`, { username }).subscribe(
      (res) => {
        successCallBack(res);
      },
      (err) => {
        failureCallBack(err);
      }
    );
  }

  public login(username: string, password: string, mobileLogin: boolean, successCallBack, failureCallBack) {
    console.log(
      `${sessionStorage.getItem('noredirect')} != 'true' - ${sessionStorage.getItem('noredirect') != 'true'}`
    );

    this.apiService
      .postItemtoServer(`user/authenticate`, {
        username,
        password,
        mobileLogin,
        brand: this.brandingService.get(),
        domain: this.sessionStorageService.getLandingDomain(),
        flags: 1 << 24,
        allowRedirects: sessionStorage.getItem('noredirect') != 'true',
      })
      .subscribe(
        (res) => {
          successCallBack(res, username);
        },
        (err) => {
          failureCallBack(err);
        }
      );
  }

  public renewInterFaxUserSessionToken(
    successCallBack: (result: ApiResult) => void,
    failureCallBack: (err: any) => void
  ) {
    this.apiService.queryServer('user/renew-interFax-user-session-token').subscribe((result: ApiResult) => {
      if (result.success) {
        successCallBack(result);
      } else {
        failureCallBack(result.errors[0]);
      }
    }, failureCallBack);
  }

  public ssoAuthenticate = (ssoJwt: string, successCallback, failureCallback): void => {
    this.apiService
      .postItemtoServer(`user/ssoAuthenticate`, {
        token: ssoJwt,
        domain: this.sessionStorageService.getLandingDomain(),
      })
      .subscribe(
        (res) => {
          successCallback(res);
        },
        (err) => {
          failureCallback(err);
        }
      );
  };

  public samlAuthenticate = (ssoJwt: string, successCallback, failureCallback): void => {
    this.apiService
      .postItemtoServer(`user/samlAuthenticate`, {
        token: ssoJwt,
        domain: this.sessionStorageService.getLandingDomain(),
      })
      .subscribe(
        (res) => {
          successCallback(res);
        },
        (err) => {
          failureCallback(err);
        }
      );
  };

  public selectTenant = (tenantId: string, successCallback, failureCallback): void => {
    this.apiService.postItemtoServer(`user/AuthorizeAsTenant`, { tenantId }).subscribe(
      (res) => {
        successCallback(res);
      },
      (err) => {
        failureCallback(err);
      }
    );
  };

  public shareSessionForPrintReload = () => {
    this.sessionStorageService.setIsPrintReload(true);

    this.shareSessionForTabs();
  };

  public shareSessionForTabs(timeout: number = 30 * 1000) {
    console.log('shareSesionForTabs');

    const token = this.sessionStorageService.getToken();

    localStorage.setItem(this.uicTabSharingId, token);

    setTimeout(() => {
      localStorage.removeItem(this.uicTabSharingId);
    }, timeout);
  }

  public removeSessionForTabs() {
    console.log('removeSessionForTabs');

    const token = localStorage.getItem(this.uicTabSharingId);
    if (!token) return;

    localStorage.removeItem(this.uicTabSharingId);
  }

  public restartSharedSessionOnPrintReload = () => {
    const isPrintReload = this.sessionStorageService.getIsPrintReload();
    const isAppReload = this.sessionStorageService.getIsAppReload();

    this.sessionStorageService.setIsPrintReload(null);
    this.sessionStorageService.setIsAppReload(null);

    if (!isAppReload) return false;
    if (!isPrintReload) return false;

    return this.restartSharedSessionForTabs();
  };

  public restartSharedSessionForTabs = (): boolean => {
    console.log('restartSharedSessionForTabs');

    const token = localStorage.getItem(this.uicTabSharingId);
    if (!token) return false;

    localStorage.removeItem(this.uicTabSharingId);

    this.startSession(token);

    return true;
  };

  public setSession(authResult) {
    this.startSession(authResult.token);
  }

  public startSession(token: string) {
    this.sessionStorageService.setToken(token);

    this.idle.onIdleStart.subscribe(() => this.onIdle);
  }

  public onIdle = (): void => {};

  public logoutBackend = (): void => {
    this.apiService.postItemtoServer(`user/logout`, {}).subscribe();
  };

  public logout() {
    if (!this.isLoggedIn()) return;

    this.onLogout.emit();

    this.logoutBackend();

    this.ngxSmartModalService.closeAll();
    this.userStateLoaded = false;

    this.sessionStorageService.logoutSession();

    try {
      if (typeof UES !== 'undefined') UES.destroy();
    } catch (e) {
      console.error(e);
    }
  }

  public setUserStateLoaded = (state: boolean) => (this.userStateLoaded = state);
  public getUserStateLoaded = (): boolean => this.userStateLoaded;

  public hasLoginToken = (): boolean => !Strings.isNullOrUndefined(this.getToken());

  public isLoggedIn() {
    return this.getUserStateLoaded() && this.hasLoginToken();
  }

  public isLoggedOut() {
    return !this.isLoggedIn();
  }

  public getToken() {
    return this.sessionStorageService.getToken();
  }

  public getUserName() {
    return localStorage.getItem('user_name');
  }

  public requestPasswordReset = (username: string, email: string, successCallback, failureCallback): void => {
    this.apiService.postItemtoServer(`user/requestpasswordreset`, { username, email }).subscribe(
      (res) => {
        successCallback(res);
      },
      (err) => {
        failureCallback(err);
      }
    );
  };

  public resetPassword = (resetCode: string, password: string, successCallback, failureCallback): void => {
    this.apiService.postItemtoServer(`user/resetpassword`, { resetCode, password }).subscribe(
      (res) => {
        successCallback(res);
      },
      (err) => {
        failureCallback(err);
      }
    );
  };

  public activateUser = (hashKey: string, mobileLogin, successCallback, failureCallback): void => {
    this.apiService
      .postItemtoServer(`user/activate/${hashKey}`, {
        username: '',
        password: '',
        mobileLogin,
        brand: this.brandingService.get(),
        domain: this.sessionStorageService.getLandingDomain(),
        flags: 1 << 24,
      })
      .subscribe(
        (res) => {
          successCallback(res);
        },
        (err) => {
          failureCallback(err);
        }
      );
  };

  loginPasswordSuccess = (
    ar: AuthorizationResult,
    username: string,
    password: string,
    printToService: PrintToService
  ) => {
    printToService.setCredentials(username, password);

    this.setSession(ar);

    if (ar.passwordExpired) {
      this.spinnerStateService.hide();
      this.router.navigate(['/password-expired']);
      return;
    }

    if (ar.notAcceptedTermsOfService) {
      this.sharedDataService.extraParameters = ar;
      this.router.navigate(['/login-terms-of-service']);
      return;
    }

    if (ar.tenants && ar.tenants.length > 0) {
      this.sessionStorageService.setTenantsList(ar.tenants);
      this.router.navigateByUrl('/login-tenants');
    } else {
      this.router.navigate(['/login-complete']);
    }
  };
}
