import { Node } from '@progress/kendo-angular-editor';

import { commonAttributes, domAttributes, hasAttrs, pmAttributes } from './utills';
import { TemplateStyle } from './../../../../views/admin-olc/models/template';

export const createInlineStyleMark = (style: TemplateStyle) => {
  return {
    [style.element]: {
      name: style.element,
      inclusive: true,
      attrs: commonAttributes,
      parseDOM: [
        {
          tag: style.element,
          getAttrs: domAttributes,
        },
      ],
      toDOM: (node: Node) => {
        return hasAttrs(node.attrs) ? [style.element, pmAttributes(node.attrs), 0] : [style.element, 0];
      },
    },
  };
};
