import { Pipe, PipeTransform } from '@angular/core';

export type direction = 'asc' | 'desc';

@Pipe({
  name: 'sort',
})
export class ArraySortPipe implements PipeTransform {
  transform(array: any, field: string, direction: direction = 'asc'): any[] {
    if (!Array.isArray(array)) {
      return;
    }

    return array.sort((a: any, b: any) => {
      let currentA = a;
      let currentB = b;

      // parse field using \.\w+|\[\w\] regex
      const fieldParts = field.split(/\.|\[|\]/g);
      for (const part of fieldParts) {
        if (part) {
          currentA = currentA[part];
          currentB = currentB[part];
        }
      }

      return this.compare(currentA, currentB, direction === 'asc');
    });
  }

  compare(a: any, b: any, isAsc: boolean) {
    let modifier = isAsc ? 1 : -1;

    if (a < b) {
      return -1 * modifier;
    }

    if (a > b) {
      return 1 * modifier;
    }

    return 0;
  }
}
