import { BrandDetails, ScanSetting } from 'shared-code-lib';
import { Filename } from '../../../blocks/core/fileName';
import { CreateDocument } from '../../../blocks/models/create-document';
import { WorkItem } from '../../../blocks/models/work-item';
import { DocumentCaptureService } from '../capture-services';

export class Command {
  constructor(public type: string) {}

  static create = (o: any): Command => {
    if (o.type === 'ScanVersion') return new ScanVersion();
    if (o.type === 'ScanToWorkflow')
      return new ScanToWorkflow(o.workflowId, o.scanSettings, o.scanOptions, o.documentProperties);
    if (o.type === 'ScanToFolder')
      return new ScanToFolder(o.workflowId, o.folderId, o.scanSettings, o.scanOptions, o.documentProperties);
    if (o.type === 'ScanAdditionalPages')
      return new ScanAdditionalPages(
        o.workflowId,
        o.documentId,
        o.documentParentFolderId,
        o.scanSettings,
        o.scanOptions,
        o.documentProperties
      );
    if (o.type === 'RescanPage')
      return new RescanPage(
        o.workflowId,
        o.documentId,
        o.documentParentFolderId,
        o.pageNumber,
        o.scanSettings,
        o.scanOptions,
        o.documentProperties
      );
    if (o.type === 'RescanDocument')
      return new RescanDocument(o.workItemId, o.documentId, o.scanSettings, o.scanOptions, o.documentProperties);
    if (o.type === 'VersionResult') return new VersionResult(o.version);
    if (o.type === 'CancelResult') return new CancelResult();
    if (o.type === 'StatusResult') return new StatusResult(o.status);
    if (o.type === 'ScanPagesResult') return new ScanPagesResult(o.data, <ScanPages>Command.create(o.scanPages));
    if (o.type === 'ProgressOpen') return new ProgressOpen(o.status);
    if (o.type === 'ScanTo') return new ScanTo(o.scanOptions, o.documentProperties);

    return null;
  };
}

export class ScanVersion extends Command {
  constructor() {
    super('ScanVersion');
  }
}

export class ActivateScanApp extends Command {
  constructor() {
    super('ActivateScanApp');
  }
}

export class ScanPages extends Command {
  constructor(
    type: string,
    public scanSettings: Array<ScanSetting>,
    public scanOptions?: ScanOptions,
    public documentProperties?: DocumentProperties,
    public brandDetails?: BrandDetails
  ) {
    super(type);
  }

  process(capture: DocumentCaptureService, data: Blob) {
    throw new Error(`${this.type} must implement process`);
  }
}

export class ScanToWorkflow extends ScanPages {
  constructor(
    public workflowId: string,
    scanSettings: Array<ScanSetting>,
    scanOptions: ScanOptions,
    documentProperties: DocumentProperties
  ) {
    super('ScanToWorkflow', scanSettings, scanOptions, documentProperties);
    this.scanSettings = scanSettings;
    this.scanOptions = scanOptions;
    this.documentProperties = documentProperties;
  }

  process(capture: DocumentCaptureService, data: Blob) {
    const workItem = WorkItem.create(this.workflowId);
    if (!this.scanOptions.allowDocumentName)
      this.documentProperties.documentName = Filename.getDefaultScannedDocumentName();
    const doc = new CreateDocument(data, this.documentProperties.documentName, 'pdf');

    capture.createNewWorkItem(workItem, doc);
  }
}

export class ScanToFolder extends ScanPages {
  constructor(
    public workflowId: string,
    public folderId: string,
    scanSettings: Array<ScanSetting>,
    scanOptions?: ScanOptions,
    documentProperties?: DocumentProperties
  ) {
    super('ScanToFolder', scanSettings, scanOptions, documentProperties);
  }

  process(capture: DocumentCaptureService, data: Blob) {
    const folder = capture.findFolder(this.folderId);

    if (!folder) {
      capture.closeScanInProgress();
      capture.showNoScanFolderError();
      return;
    }

    let fileName = Filename.getScannedDocumentName(this);
    capture.addFiletoFolder(data, fileName, 'pdf', folder);
  }
}

export class ScanTo extends ScanPages {
  constructor(scanOptions: ScanOptions, documentProperties: DocumentProperties) {
    super('ScanTo', new Array<ScanSetting>(), scanOptions, documentProperties);
  }

  process(capture: DocumentCaptureService, data: Blob) {}
}

export class ScanAdditionalPages extends ScanPages {
  constructor(
    public workflowId: string,
    public documentId: string,
    public documentParentFolderId: string,
    scanSettings: Array<ScanSetting>,
    scanOptions: ScanOptions,
    documentProperties: DocumentProperties
  ) {
    super('ScanAdditionalPages', scanSettings, scanOptions, documentProperties);
  }

  process(capture: DocumentCaptureService, data: File) {
    const folder = capture.findFolder(this.documentParentFolderId);
    const result = folder.findDocument(this.documentId);

    capture.appendPagesToDocument(result.workItem, result.document, data, 'pdf');
  }
}

export class RescanPage extends ScanPages {
  constructor(
    public workflowId: string,
    public documentId: string,
    public documentParentFolderId: string,
    public pageNumber: number,
    scanSettings: Array<ScanSetting>,
    scanOptions: ScanOptions,
    documentProperties: DocumentProperties
  ) {
    super('RescanPage', scanSettings, scanOptions, documentProperties);
  }

  process(capture: DocumentCaptureService, data: File) {
    const folder = capture.findFolder(this.documentParentFolderId);
    const result = folder.findDocument(this.documentId);

    const pageCount = result.document.pageCount;

    capture.deleteDocumentPage(
      result.workItem.id,
      result.document.id,
      this.pageNumber,
      () => {
        capture.addPagesToDocument(result.workItem, result.document, data, this.pageNumber, 'pdf', true, false);
      },
      (err) => {
        capture.showFailedToDeletePageFromDocumentError();
        capture.closeScanInProgress();
      }
    );
  }
}

export class RescanDocument extends ScanPages {
  constructor(
    public workItemId: string,
    public documentId: string,
    scanSettings: Array<ScanSetting>,
    scanOptions: ScanOptions,
    documentProperties: DocumentProperties
  ) {
    super('RescanDocument', scanSettings, scanOptions, documentProperties);
  }

  process(capture: DocumentCaptureService, data: File) {
    capture.replaceDocument(this.workItemId, this.documentId, data, 'pdf');
  }
}

