import { Component, EventEmitter, Input, OnDestroy, OnInit, Output, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PdfViewerComponent } from 'ng2-pdf-viewer';
import { Subscription } from 'rxjs';
import {
  Annotation,
  AnnotationConfiguration,
  AnnotationTypes,
  Graphics,
  ListItem,
  ObjectIdGenerator,
  Point,
  Region,
  TextAnnotation,
} from 'shared-code-lib';
import { Action, ActionEvent } from '../../../../blocks/core/actions';
import { ActionService } from '../../../../blocks/services/action.service';
import { ErrorsService } from '../../../../blocks/services/errors.service';
import { HydraApiService } from '../../../../blocks/services/hydra-api.service';
import { CaptureUpdateService } from '../../../document-capture/capture-services/capture-update.service';

declare const $: any;

@Component({
  selector: 'app-annotations',
  templateUrl: './annotations.component.html',
  styleUrls: ['./annotations.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class AnnotationsComponent implements OnInit, OnDestroy {
  @Input() viewer: PdfViewerComponent;
  @Input() id: string;
  @Input() pageNumber: number;
  @Input() annotations: Annotation[] = [];
  @Input() showApplyButton: boolean = false;
  @Output() reload = new EventEmitter();
  @Output() annotationAdded = new EventEmitter<Annotation>();
  @Output() annotationRemoved = new EventEmitter<Annotation>();
  @Output() annotationUpdated = new EventEmitter<Annotation>();
  @Output() applyAnnotations = new EventEmitter();

  annotating = false;
  drawing = false;
  annotationBorder: number = 3;
  currentAction: Action;
  stamp: string = 'approved-green.jpg';
  lineWidth: number = 1;
  color: string = '#ff0000';
  fontSize: number = 16;
  fontName: string = 'Arial';
  isItalic: boolean = false;
  isBold: boolean = false;
  highlightColor: string = 'yellow';
  highlighLineWidth: number = 20;
  currentAnnotation: Annotation;
  changed: boolean = false;
  subscriptions: Subscription = new Subscription();
  configuration: AnnotationConfiguration;

  fontNames: any[];
  fontSizes: any[];
  lineWidths: any[];
  highlightColors: any[];
  stamps: ListItem[];

  nonAsciiFonts: string[] = ['Webdings', 'Wingdings'];

  onClickX: number;
  onClickY: number;
  onMoveX: number;
  onMoveY: number;
  page = null;
  body = $('body');
  textLayer;
  pdfViewerPage;
  canvasWrapper;
  canvas;

  constructor(
    private translate: TranslateService,
    private actionService: ActionService,
    private hydraApi: HydraApiService,
    private errorsService: ErrorsService,
    private captureUpdate: CaptureUpdateService
  ) {}

  ngOnInit(): void {
    this.subscriptions.add(this.actionService.onActivateAction.subscribe(this.invokeAction));
    this.hydraApi.getAnnotationConfigurations(this.annotationConfigLoaded, this.annotationConfigFailed);
    this.captureUpdate.onChangeAnnotation.subscribe((res) => {
      this.annotations = res;
    });
  }

  annotationConfigLoaded = (config: AnnotationConfiguration): void => {
    this.configuration = config;
    this.loadFontNames();
    this.loadFontSizes();
    this.loadLineWidths();
    this.loadHighlightColors();
    this.loadStamps();
  };

  annotationConfigFailed = (err: any): void => {
    this.errorsService.showErrorsModal([err], this.translate.instant('annotations.config-load-failed'));
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.unbindEvents();
  }

  invokeAction = (actionEvent: ActionEvent): void => {
    if (!this.viewer) return;

    if (actionEvent.action == Action.StopAnnotating) {
      this.stop();
      return;
    }
    const annotationType: AnnotationTypes = AnnotationTypes[actionEvent.action as keyof typeof AnnotationTypes];
    if (annotationType == null) return;

    this.start(actionEvent.action);
  };

  start(action: Action) {
    this.currentAction = action;
    this.annotating = true;
    this.textLayer.addClass('annotating');
    $('.action-button.selected').removeClass('selected');
    $(`.action-button.action-${action}`).addClass('selected');
    this.canvas.css('z-index', 1);
    this.unSelectCurrentAnnotation();
  }

  stop() {
    this.currentAction = null;
    this.annotating = false;
    this.drawing = false;
    this.textLayer.removeClass('annotating');
    $('.action-button.selected').removeClass('selected');
    $('.action-StopAnnotating').addClass('selected');
    this.canvas.css('z-index', 0);
    this.unSelectCurrentAnnotation();
  }

  addAnnotationCanvas = (): void => {
    if (!this.textLayer) return;

    if ($('.annotations-canvas').length > 0) $('.annotations-canvas').remove();

    const pageRotation = this.textLayer.attr('data-main-rotation');
    const pageRotatedVertically = ['90', '270'].includes(pageRotation);

    const width = !pageRotatedVertically ? $('.textLayer').width() : $('.textLayer').height();
    const height = !pageRotatedVertically ? $('.textLayer').height() : $('.textLayer').width();
    this.canvas = $('<canvas class="annotations-canvas" width="' + width + '" height="' + height + '" />');

    this.textLayer.append(this.canvas);
  };

  getElementAnnotation = (el): Annotation => {
    const pageWidth = this.viewer.pdfViewer._pages[0].viewport.width;
    const pageHeight = this.viewer.pdfViewer._pages[0].viewport.height;
    const id = $(el).attr('annotation-id');
    let annotation = this.annotations.find((x) => x.id == id);
    if (!annotation) throw 'Annotation not found';
    let y = $(el).css('top') ? parseInt($(el).css('top').replace('px', '')) : $(el).offset().top;
    let x = $(el).css('left') ? parseInt($(el).css('left').replace('px', '')) : $(el).offset().left;
    let width = $(el).width();
    let height = $(el).height();

    x += this.annotationBorder;
    y += this.annotationBorder;

    if (annotation.annotationType == AnnotationTypes.Redaction) {
      x -= 2;
      y -= 1;
      width += this.annotationBorder + 1;
      height += this.annotationBorder + 1;
    }

    if (annotation.annotationType == AnnotationTypes.Text) {
      width += parseInt($(el).css('padding-left')) + parseInt($(el).css('padding-right'));
      height += parseInt($(el).css('padding-top')) + parseInt($(el).css('padding-bottom'));
    }

    annotation.setLocation(x / pageWidth, y / pageHeight);
    annotation.setSize(width / pageWidth, height / pageHeight);
    if (!annotation.pageScale) annotation.pageScale = this.page.scale;

    return annotation;
  };

  draggable = (el): void => {
    const that = this;
    $(el).draggable({
      start: function (event, ui) {
        $('.textLayer').addClass('dragging-annotation');
      },
      drag: function (event, ui) {
        that.updateAnnotation(that.getElementAnnotation(event.target));
        that.drawAnnotations();
      },
      stop: function (event, ui) {
        const annotation = that.getElementAnnotation(event.target);
        that.updateAnnotation(annotation);
        that.annotationUpdated.emit(annotation);
        that.drawAnnotations();
        $('.textLayer').removeClass('dragging-annotation');
      },
    });

    $(el).draggable('option', 'cancel', '.editable-text');
  };

  resizable = (el): void => {
    const that = this;
    $(el).resizable({
      handles: 'all',
      start: function (event, ui) {
        $('.textLayer').addClass('resizing-annotation');
      },
      resize: function (event, ui) {
        that.updateAnnotation(that.getElementAnnotation(event.target));
        that.drawAnnotations();
      },
      stop: function (event, ui) {
        const annotation = that.getElementAnnotation(event.target);
        that.updateAnnotation(annotation);
        that.annotationUpdated.emit(annotation);
        that.drawAnnotations();
        $('.textLayer').removeClass('resizing-annotation');
      },
    });
  };

  drawAnnotations = (isDrawing: boolean = false): void => {
    const width = this.viewer.pdfViewer._pages[0].viewport.width;
    const height = this.viewer.pdfViewer._pages[0].viewport.height;
    const ctx = $('.annotations-canvas')[0].getContext('2d');
    ctx.clearRect(0, 0, width, height);
    this.annotations
      .filter((a) => a.pageNumber == this.pageNumber)
      .sort((a, b) => a.order - b.order)
      .forEach((x) => {
        if (
          (x.annotationType == AnnotationTypes.Text || x.annotationType == AnnotationTypes.Redaction) &&
          (!isDrawing || x != this.currentAnnotation)
        )
          return;
        x.draw(ctx, width, height, isDrawing);
      });
  };

  setAnnotationEvents = (annotation: Annotation, el): void => {
    this.resizable(el);
    this.draggable(el);

    const that = this;
    $(el)
      .find('.item-delete')
      .mousedown(function () {
        that.removeAnnotation($(this).parent().attr('annotation-id'));
        $(this).parent().remove();
        that.drawAnnotations();
      });

    $(el).mousedown(function (event) {
      that.setCurrentAnnotation(that.getElementAnnotation(this));
    });

    if (annotation.annotationType == AnnotationTypes.Text) {
      const editElement = el.find('.editable-text');
      editElement.focus();
      editElement.keyup(function () {
        const annotation = that.getElementAnnotation($(this).parent());
        (annotation as TextAnnotation).text = this.innerText;
        that.updateAnnotation(annotation);
        that.annotationUpdated.emit(annotation);
      });
    } else {
      this.drawAnnotations();
    }
  };

  startDrawing = (): void => {
    this.drawing = true;
    this.canvas.css('z-index', 3);
    this.textLayer.addClass('drawing');
  };

  stopDrawing = (): void => {
    this.drawing = false;
    this.canvas.css('z-index', this.annotating ? 1 : 0);
    this.textLayer.removeClass('drawing');
  };

  unbindEvents = (): void => {
    if (this.body) this.body.unbind('mousemove');

    if (!this.textLayer) return;
    this.canvas.unbind('mousedown');
    this.canvas.unbind('mousemove');
    this.canvas.unbind('mouseup');
    this.canvas.unbind('mouseout');
  };

  initializeAnnotations(): void {
    this.page = this.viewer.pdfViewer._pages[0];
    const that = this;
    this.body = $('body');
    this.textLayer = $('.textLayer');
    this.pdfViewerPage = $('.pdfViewer .page');
    this.addAnnotationCanvas();
    this.unbindEvents();

    if (this.annotating && !this.textLayer.hasClass('annotating')) this.textLayer.addClass('annotating');

    this.canvas.mousedown(function (e) {
      $('.annotation.current').removeClass('current');
      if (!that.annotating || that.drawing) return;
      that.startDrawing();
      that.onClickX = that.onMoveX = e.pageX - $(that.page.canvas).offset().left;
      that.onClickY = that.onMoveY = e.pageY - $(that.page.canvas).offset().top;
      that.currentAnnotation = that.createNewAnnotation(
        {
          x: that.onClickX / that.page.viewport.width,
          y: that.onClickY / that.page.viewport.height,
          width: 0,
          height: 0,
        },
        that.page.viewport.width,
        that.page.viewport.height
      );
      that.annotations.push(that.currentAnnotation);
      that.currentAnnotation.onMouseDown(
        new Point(that.onClickX / that.page.viewport.width, that.onClickY / that.page.viewport.height)
      );
    });

    this.body.mousemove(function (event3) {
      if (!that.allowedTarget(event3.target)) that.stopDrawing();
    });

    this.canvas.mousemove(function (event4) {
      if (!that.drawing) return;
      that.onMouseMove(event4);
    });

    this.canvas.mouseup(function (event) {
      that.endDrawing(event);
    });

    this.canvas.mouseout(function (event) {
      that.endDrawing(event);
    });
  }

  endDrawing = (event): void => {
    if (!this.annotating || !this.drawing || !this.allowedTarget(event.target)) return;

    this.stopDrawing();
    if (this.currentAnnotation.area.width == 0 || this.currentAnnotation.area.height == 0) {
      this.currentAnnotation = null;
      this.annotations.pop();
      return;
    }

    this.changed = true;
    this.setAnnotationEvents(this.currentAnnotation, this.addAnnotationDiv(this.currentAnnotation));
    this.annotationAdded.emit(this.currentAnnotation);
    this.drawAnnotations(false);
  };

  updateCurrentRegion = (): void => {
    this.currentAnnotation.onMove(
      new Point(this.onMoveX / this.page.viewport.width, this.onMoveY / this.page.viewport.height)
    );
    this.currentAnnotation.calculateArea(this.page.viewport.width, this.page.viewport.height);
  };

  onMouseMove = (event): void => {
    this.onMoveX = event.pageX - $(this.page.canvas).offset().left;
    this.onMoveY = event.pageY - $(this.page.canvas).offset().top;

    this.updateCurrentRegion();

    this.drawAnnotations(true);
  };

  allowedTarget = (target): boolean => {
    return (
      $(target).hasClass('indexing-text') ||
      $(target).hasClass('textLayer') ||
      $(target).hasClass('endOfContent') ||
      $(target).hasClass('.page') ||
      $(target).hasClass('annotations-canvas') ||
      $(target).hasClass('text-wrapper')
    );
  };

  addAnnotationDiv = (annotation: Annotation): any => {
    const elHtml = `<div id="annotation-${annotation.id}" annotation-id="${annotation.id}" class="annotation current ${
      AnnotationTypes[annotation.annotationType]
    }"><span class="icon-cancel-circle item-delete" title="${this.translate.instant('Common.Remove')}"></span></div>`;
    const el = $(elHtml);
    this.pdfViewerPage.append(el);
    el.css({
      left: `${(annotation.areaRotated.x - this.annotationBorder / this.page.viewport.width) * 100}%`,
      top: `${(annotation.areaRotated.y - this.annotationBorder / this.page.viewport.height) * 100}%`,
      width: `${(annotation.areaRotated.width + (2 * this.annotationBorder) / this.page.viewport.width) * 100}%`,
      height: `${(annotation.areaRotated.height + (2 * this.annotationBorder) / this.page.viewport.height) * 100}%`,
      zIndex: 2,
    });
    $('.annotation.current').removeClass('current');
    $(el).addClass('current');
    if (annotation.annotationType === AnnotationTypes.Text) this.onAddTextAnnotation(annotation as TextAnnotation, el);

    return el;
  };

  onAddTextAnnotation = (annotation: TextAnnotation, el): void => {
    const textArea = $(`<div class="editable-text degree${annotation.rotation}" contenteditable="true" ></div>`);
    $(textArea).html(annotation.text.replace(/\n/g, '<br/>'));
    $(el).append(textArea);

    const scale = annotation.pageScale ? this.page.scale / annotation.pageScale : 1;
    textArea.css({
      color: annotation.color,
      fontFamily: annotation.fontName,
      fontSize: Math.round(annotation.fontSize * scale),
    });
  };

  updateTextAnnotationStyles = (annotation: TextAnnotation) => {
    $(`#annotation-${annotation.id}`).find('.editable-text').css({
      color: annotation.color,
      fontFamily: annotation.fontName,
      fontSize: annotation.fontSize,
    });
  };

  createNewAnnotation = (area: Region, pageWidth: number, pageHeight: number): Annotation => {
    const annotationType: AnnotationTypes = AnnotationTypes[this.currentAction as keyof typeof AnnotationTypes];

    return Annotation.create({
      id: ObjectIdGenerator.generateNewObjectId(),
      annotationType: annotationType,
      pageNumber: this.pageNumber,
      area: area,
      isNew: true,
      text: '',
      fontName: this.fontName,
      fontSize: this.fontSize,
      color: this.color,
      highlightColor: this.highlightColor,
      thickness: this.lineWidth,
      startPoint: new Point(this.onClickX, this.onClickY),
      endPoint: new Point(this.onClickX, this.onClickY),
      points: [],
      stamp: this.stamp,
      pageWidth: pageWidth,
      pageHeight: pageHeight,
      order: this.getNextAnnotationOrder(),
      rotation: 0,
      pageScale: this.page.scale,
    });
  };

  setCurrentAnnotation = (annotation: Annotation): void => {
    this.unSelectCurrentAnnotation();
    if (!annotation) return;

    this.currentAnnotation = annotation;
    $(`#annotation-${annotation.id}`).addClass('current');
    this.bringToTop(annotation);
  };

  unSelectCurrentAnnotation = (): void => {
    this.currentAnnotation = null;
    $('.annotation.current').removeClass('current');
  };

  getNextAnnotationOrder = (): number => {
    const orders = this.annotations
      .filter((x) => x.pageNumber == this.pageNumber)
      .map(function (x) {
        return x.order;
      });

    if (orders.length == 0) return 1;
    const maxOrder = Math.max.apply(Math, orders);

    return Number.isInteger(maxOrder) ? maxOrder + 1 : 1;
  };

  bringToTop = (annotation: Annotation): void => {
    annotation.order = this.getNextAnnotationOrder();
    $(`#annotation-${annotation.id}`).insertAfter($('.annotation').last());
    this.drawAnnotations();
  };

  onPageRendered = (event: any): void => {
    this.initializeAnnotations();
    $('.annotation').remove();
    this.annotations
      .filter((a) => a.pageNumber == this.pageNumber)
      .forEach((x) => this.setAnnotationEvents(x, this.addAnnotationDiv(x)));
    if (this.annotating) this.start(this.currentAction);
    if (!this.annotating) this.stop();
  };

  onCancelAnnotations() {
    this.resetAnnotations();
    $('.annotation').remove();
    this.reload.emit();
  }

  onApplyAnnotations() {
    this.applyAnnotations.emit();
  }

  resetAnnotations = (): void => {
    this.stop();

    this.annotations = [];
    this.changed = false;
  };

  updateAnnotation = (annotation: Annotation): void => {
    const index = this.annotations.findIndex((x) => x.id === annotation.id);

    if (index === -1) return;
    this.annotations[index] = annotation;
    this.changed = true;
  };

  removeAnnotation = (id: string): void => {
    const index = this.annotations.findIndex((x) => x.id == id);

    if (index == -1) return;
    const deletedAnnotation = this.annotations[index];
    this.annotations.splice(index, 1);
    this.annotationRemoved.emit(deletedAnnotation);
    if (this.annotations.length === 0) this.changed = false;
    this.currentAnnotation = null;
  };

  onColorChanged = (color: string) => {
    if (this.currentAnnotation != null && this.currentAnnotation['color']) {
      this.currentAnnotation['color'] = color;
      this.drawAnnotations();
      if (this.currentAnnotation.annotationType == AnnotationTypes.Text)
        this.updateTextAnnotationStyles(this.currentAnnotation as TextAnnotation);
      this.annotationUpdated.emit(this.currentAnnotation);
      return;
    }

    this.color = color;
  };

  onLineWidthChanged = (event: any) => {
    if (this.currentAnnotation != null && this.currentAnnotation['thickness']) {
      this.currentAnnotation['thickness'] = event.value;
      this.drawAnnotations();
      this.annotationUpdated.emit(this.currentAnnotation);
      return;
    }

    this.lineWidth = event.value;
  };

  onFontNameChanged = (event: any) => {
    if (this.currentAnnotation != null && this.currentAnnotation['fontName']) {
      this.currentAnnotation['fontName'] = event.value;
      this.updateTextAnnotationStyles(this.currentAnnotation as TextAnnotation);
      this.annotationUpdated.emit(this.currentAnnotation);
      return;
    }

    this.fontName = event.value;
    if (this.currentAction != Action.Text) this.start(Action.Text);
  };

  onFontSizeChanged = (event: any) => {
    if (this.currentAnnotation != null && this.currentAnnotation['fontSize']) {
      this.currentAnnotation['fontSize'] = event.value;
      this.updateTextAnnotationStyles(this.currentAnnotation as TextAnnotation);
      this.annotationUpdated.emit(this.currentAnnotation);
      return;
    }

    this.fontSize = event.value;
    if (this.currentAction != Action.Text) this.start(Action.Text);
  };

  onHighlighColorChanged = (event: any) => {
    if (this.currentAnnotation != null && this.currentAnnotation['highlightColor']) {
      this.currentAnnotation['highlightColor'] = event.value;
      this.drawAnnotations();
      this.annotationUpdated.emit(this.currentAnnotation);
      return;
    }

    this.highlightColor = event.value;
    if (this.currentAction != Action.Highlight) this.start(Action.Highlight);
  };

  onStampChanged = (event: any) => {
    if (this.currentAnnotation != null && this.currentAnnotation['stamp']) {
      this.currentAnnotation['stamp'] = event.value;
      this.drawAnnotations();
      this.annotationUpdated.emit(this.currentAnnotation);
      return;
    }

    this.stamp = event.value;
    if (this.currentAction != Action.Stamp) this.start(Action.Stamp);
  };

  getColor = () => {
    if (this.currentAnnotation != null && this.currentAnnotation['color']) return this.currentAnnotation['color'];
    return this.color;
  };

  getLineWidth = () => {
    if (this.currentAnnotation != null && this.currentAnnotation['thickness'])
      return this.currentAnnotation['thickness'];

    return this.lineWidth;
  };

  getFontName = () => {
    if (this.currentAnnotation != null && this.currentAnnotation['fontName']) return this.currentAnnotation['fontName'];

    return this.fontName;
  };

  getFontSize = () => {
    if (this.currentAnnotation != null && this.currentAnnotation['fontSize']) return this.currentAnnotation['fontSize'];

    return this.fontSize;
  };

  getHighlighColor = () => {
    if (this.currentAnnotation != null && this.currentAnnotation['highlightColor'])
      return this.currentAnnotation['highlightColor'];

    return this.highlightColor;
  };

  getStamp = () => {
    if (this.currentAnnotation != null && this.currentAnnotation['stamp']) return this.currentAnnotation['stamp'];
    return this.stamp;
  };

  loadFontSizes = (): void => {
    this.fontSizes = [];
    this.configuration.fontSizes.forEach((fontSize) => this.fontSizes.push({ name: fontSize, value: fontSize }));
  };

  loadFontNames = (): void => {
    this.fontNames = [];
    this.configuration.fontNames.forEach((x) => {
      const fontName = this.translate.instant(`annotations.fonts.${x}`);
      let html = `<div class="font-name text-left" style="font-family:${x}">${fontName}</div>`;

      if (this.nonAsciiFonts.indexOf(x) != -1) html = `<div class="font-name text-left">${fontName} (${html})</div>`;

      this.fontNames.push({ name: '', html: html, value: x });
    });
  };

  loadLineWidths = (): void => {
    this.lineWidths = [];
    this.configuration.lineWidths.forEach((x) =>
      this.lineWidths.push({
        name: '',
        html: `<div class="line-width d-flex" ><div class="line-width-value" style="height:${x}px"></div></div>`,
        value: x,
      })
    );
  };

  loadHighlightColors = (): void => {
    this.highlightColors = [];
    this.configuration.highlightColors.forEach((x) =>
      this.highlightColors.push({
        name: '',
        html: `<div class="color-row" style="background-color:${x}"></div>`,
        value: x,
      })
    );
  };

  loadStamps = (): void => {
    this.stamps = [];
    this.configuration.stamps.forEach((x) => {
      this.stamps.push({
        name: '',
        html: '<img class="stamp-image" src="api/user/annotations/stamps/' + x + '" />',
        value: x,
      });

      Graphics.loadStamp(x);
    });
  };
}
