import { AfterViewInit, Component, ElementRef, EventEmitter, HostListener, Output, ViewChild } from '@angular/core';

import moment from 'moment';
import { Languages } from '../../../utils/languages';
import { Strings } from '../../../utils/strings.service';
import { IDateRangePickerData } from './date-range-picker.model';

declare const $: any;
declare var Pikaday;

@Component({
  templateUrl: './date-range-picker.component.html',
  styleUrls: ['./date-range-picker.component.scss'],
})
export class DateRangePickerComponent implements AfterViewInit {
  @ViewChild('dateRangePicker', { static: true }) dateRangePicker: ElementRef;
  @ViewChild('calendarContainerFrom', { static: true }) calendarContainerFrom: ElementRef;
  @ViewChild('calendarFieldFrom', { static: true }) calendarFieldFrom: ElementRef;
  @ViewChild('calendarContainerTo', { static: true }) calendarContainerTo: ElementRef;
  @ViewChild('calendarFieldTo', { static: true }) calendarFieldTo: ElementRef;

  data: IDateRangePickerData;
  dateFormat = 'YYYY-MM-DD';

  pikadayFrom: any;
  pikadayTo: any;

  dateFrom: string;
  dateTo: string;

  preventWrongRange = true;

  isFirstRender = true;
  isFromDateChosen = false;

  @HostListener('window:resize')
  onResize() {
    this.initDateRangePickerPosition();
  }
  @HostListener('window:scroll', ['$event'])
  scrollHandler() {
    this.initDateRangePickerPosition();
  }
  @HostListener('document:click', ['$event'])
  clickout(event) {
    if (!this.dateRangePicker.nativeElement.contains(event.target)) {
      this.onHide.emit();
    }
  }

  @Output() onDateRangeSelected = new EventEmitter<string>();
  @Output() onHide = new EventEmitter();

  constructor(private languages: Languages) {}

  ngAfterViewInit(): void {
    $('body').scroll(() => {
      this.initDateRangePickerPosition();
    });

    this.initializePikaday();
    this.initDateRangePickerPosition();
    this.setLimits();
    this.renderValue();

    this.isFirstRender = false;
  }

  renderValue = (): void => {
    if (!this.data.value) return;

    const tokens = this.data.value.split(':');
    if (tokens.length != 2) return;

    this.pikadayFrom.setDate(new Date(tokens[0]));
    this.pikadayTo.setDate(new Date(tokens[1]));
  };

  initializePikaday = (): void => {
    this.pikadayFrom = new Pikaday({
      container: this.calendarContainerFrom.nativeElement,
      field: this.calendarFieldFrom.nativeElement,
      bound: false,
      format: this.dateFormat,
      i18n: this.languages.getLocalizedDate(),

      onSelect: (date: Date): void => {
        if (this.isFirstRender) return;

        this.isFromDateChosen = true;

        if (!date) {
          this.dateFrom = '';
          return;
        }

        if (this.preventWrongRange) this.pikadayTo.setMinDate(date);

        this.dateFrom = moment(date).format(this.dateFormat);
        if (Strings.isEmpty(this.dateFrom) || Strings.isEmpty(this.dateTo)) return;
      },
    });

    this.pikadayTo = new Pikaday({
      container: this.calendarContainerTo.nativeElement,
      field: this.calendarFieldTo.nativeElement,
      bound: false,
      format: this.dateFormat,
      i18n: this.languages.getLocalizedDate(),

      onSelect: (date: Date): void => {
        if (this.isFirstRender) return;

        if (!date) {
          this.dateTo = '';
          return;
        }

        if (this.preventWrongRange) this.pikadayFrom.setMaxDate(date);

        this.dateTo = moment(date).format(this.dateFormat);
        if (Strings.isEmpty(this.dateFrom) || Strings.isEmpty(this.dateTo)) return;

        this.setValue(`${this.dateFrom}:${this.dateTo}`);
      },
      disableDayFn: (date: Date): boolean => {
        if (this.preventWrongRange) {
          return !this.isFromDateChosen || !this.pikadayFrom.getDate() || date < this.pikadayFrom.getDate();
        }

        return false;
      },
    });
  };

  initDateRangePickerPosition() {
    const parent = $(this.data.parent);
    const dateRangePicker = $(this.dateRangePicker.nativeElement);
    let left = parent.offset().left;
    const width = $(dateRangePicker).width();
    const height = $(dateRangePicker).height();
    if (left + width > $(window).width()) {
      left = $(window).width() - width - 20;
    }

    let top = $(parent).offset().top + $(parent).height();
    if (top + height + 20 > $(window).height()) {
      top = $(window).height() - height - 20;
    }

    dateRangePicker.css({
      top: `${top}px`,
      left: `${left}px`,
    });
  }

  setLimits = (): void => {
    if (this.data?.minValue) {
      this.pikadayFrom.setMinDate(new Date(`${this.data.minValue}T00:00:00`));
      this.pikadayTo.setMinDate(new Date(`${this.data.minValue}T00:00:00`));
    }

    if (this.data?.maxValue) {
      this.pikadayFrom.setMaxDate(new Date(`${this.data.maxValue}T00:00:00`));
      this.pikadayTo.setMaxDate(new Date(`${this.data.maxValue}T00:00:00`));
    }
  };

  clear = () => {
    if (this.data.defaultValue) {
      this.setValue(this.data.defaultValue);
      return;
    }

    if (this.data.minValue && this.data.maxValue) {
      this.setValue(`${this.data.minValue}:${this.data.maxValue}`);
      return;
    }

    this.setValue('');
  };

  setValue = (value: string) => {
    this.data.value = value;
    this.onDateRangeSelected.emit(value);
    this.onHide.emit();
  };
}
