import { Component, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import {
  ColumnDisplayType,
  FieldDefinition,
  IQuestion,
  MetaDataCollection,
  MetaDataType,
  TableItem,
} from 'shared-code-lib';
import { JiraIssue } from '../../models/jira-issue';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResult } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-add-resolved-ticket',
  templateUrl: './add-resolved-ticket.component.html',
  styleUrls: ['./add-resolved-ticket.component.scss'],
})
export class AddResolvedTicketComponent implements OnInit {
  @ViewChild('ticketQuestions') ticketQuestions: any;
  @Output() closeModal = new EventEmitter();

  componentNames: string = '';
  componentIds = [];

  jiraIdField: FieldDefinition;
  linkedTicketIdField: FieldDefinition;
  jiraCommentField: FieldDefinition;

  jiraId: string;
  jiraComment: string;
  linkedTicketId: string;

  jiraIssue: JiraIssue = null;
  linkedTickets: Array<JiraIssue> = [];
  requiresDBUpdate: boolean = false;
  errors = [];
  linkedTicketColumns = [];
  linkedTicketTableItems = [];

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private hydraApi: HydraApiService
  ) {}

  ngOnInit(): void {
    this.componentIds = this.sharedDataService.extraParameters.items.map((i) => i.id);
    const names = this.sharedDataService.extraParameters.items.map((i) => i.name);
    this.componentNames = names.join(', ');

    this.createFields();
    this.buildColumns();
  }

  createFields = () => {
    this.jiraIdField = new FieldDefinition({
      type: MetaDataType.Text,
      placeholder: this.translateService.instant('add-resolved-ticket.jira-id-placeholder'),
      required: true,
    });

    this.jiraCommentField = new FieldDefinition({
      type: MetaDataType.LargeText,
      placeholder: this.translateService.instant('add-resolved-ticket.comment-placeholder'),
      required: false,
    });

    this.linkedTicketIdField = new FieldDefinition({
      type: MetaDataType.Text,
      placeholder: this.translateService.instant('add-resolved-ticket.linked-ticket-id-placeholder'),
      required: false,
    });
  };

  verify = () => {
    this.errors = [];
    this.jiraIssue = null;
    this.showSpinner();
    this.hydraApi.getJiraIssue(this.jiraId, true, this.onGetJiraTicketSucceeded, this.onGetJiraTicketFailed);
  };

  verifyLinkedTicket = () => {
    this.showSpinner();
    this.hydraApi.getJiraIssue(
      this.linkedTicketId,
      false,
      this.onGetLinkedJiraTicketSucceeded,
      this.onGetJiraTicketFailed
    );
  };

  addTicket = () => {
    this.errors = [];
    this.showSpinner();

    let questions: Array<IQuestion> = this.ticketQuestions.questions;
    if (questions.filter((q) => q.value === null).length > 0) {
      this.errors.push(this.translateService.instant('add-ticket-questions.errors.questions-mandatory'));
    } else if (this.linkedTickets.length < questions.filter((q) => q.value === true).length) {
      this.errors.push(
        this.translateService.instant('add-ticket-questions.errors.questions-yes-more-than-related-tickets')
      );
    }
    if (this.errors.length) {
      this.spinnerService.hide();
      return false;
    }

    const args = new MetaDataCollection();

    args.set('jiraid', this.jiraIssue.id);
    args.set('comment', this.jiraComment);
    args.set('questions', JSON.stringify(questions));

    if (this.linkedTickets.length) {
      args.set('ifx-related-tickets', this.linkedTickets.map((t) => t.id).join(','));
    }

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.componentIds,
      args,
      this.onAddTicketSucceeded,
      this.onAddTicketFailed
    );
    return false;
  };

  onGetJiraTicketSucceeded = (result: ApiResult) => {
    if (result.success) {
      this.jiraIssue = result.object;
      this.linkedTickets = this.jiraIssue.prerequisites;
      this.linkedTicketTableItems = this.linkedTickets.map((t) => this.createTicketTableItem(t));
      this.spinnerService.hide();
    } else {
      this.onGetJiraTicketFailed(result.errors);
    }
  };

  onGetLinkedJiraTicketSucceeded = (result: ApiResult) => {
    if (result.success) {
      this.linkedTicketId = '';
      if (!this.linkedTickets.some((a) => a.id == result.object.id)) this.linkedTickets.push(result.object);
      this.linkedTicketTableItems = this.linkedTickets.map((t) => this.createTicketTableItem(t));
    }
    this.spinnerService.hide();
  };

  onGetJiraTicketFailed = (errors: any[]) => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  onAddTicketSucceeded = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  onAddTicketFailed = (errors: any[]): void => {
    this.jiraIssue = null;
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  close = (): void => this.closeModal.emit();

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.add-resolved-ticket .nsm-content') as HTMLElement;
  }

  showSpinner = (): void => {
    this.spinnerService.show(this.translateService.instant('add-resolved-ticket.loading'), this.getSpinnerElement());
  };

  createTicketTableItem(ticket: JiraIssue): TableItem {
    const tableItem = new TableItem(ticket, this.linkedTicketColumns, this.translateService);
    return tableItem;
  }

  buildColumns(): void {
    this.linkedTicketColumns = [];

    this.linkedTicketColumns.push(
      this.createColumn(
        'id',
        ColumnDisplayType.Text,
        this.translateService.instant('add-resolved-ticket.column-id'),
        100,
        'id',
        true
      )
    );

    this.linkedTicketColumns.push(
      this.createColumn(
        'summary',
        ColumnDisplayType.Text,
        this.translateService.instant('add-resolved-ticket.column-summary'),
        100,
        'summary',
        true
      )
    );
  }

  createColumn(
    id: string,
    displayType: number,
    columnName: string,
    width: number,
    itemProperty: string,
    stretch = false
  ) {
    return {
      id: 'column_' + id,
      width: width,
      stretch: stretch,
      displayType: displayType,
      headerImage: '',
      headerText: columnName,
      itemProperty: itemProperty,
      columnName: columnName,
      sortable: false,
      sortByFieldName: '',
      invertBooleanValue: false,
    };
  }

  onDeleteLinkedTicket = (item: any): void => {
    this.linkedTickets = this.linkedTickets.filter((r) => r.id != item.id);

    this.linkedTicketTableItems = this.linkedTickets.map((t) => this.createTicketTableItem(t));
  };
}
