import { Component, OnInit, Output, EventEmitter, Input, OnChanges, SimpleChanges, AfterViewInit } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';

import { StickyFieldsService } from './../services/sticky-fields.service';
import { MetaDataCollection, MetaDataValidity } from '../models/metadata';
import { OverallValidityStatusChangedData, ValidationInProgressChangedData } from '../models/workflow-prompts';
import {
  PromptValidate,
  MetaDataDefinition,
  MetaDataType,
  ValidationRequest,
  IMetaDataDefinition,
} from '../models/metadata-definition';
import { LookupToBeSaved } from '../models/lookup-models';
import { FieldDataSource, FieldDefinition } from '../models/field-definition';
import { SaveLookupsEvent, BlurEvent } from '../models/field-events';
import { IFindMetaDataById, IMetaDataService, IMetaDataValidator } from '../interop/MetaDataService';

@Component({
  selector: 'app-workflow-indexing-panel',
  templateUrl: './workflow-indexing-panel.component.html',
  styleUrls: ['./workflow-indexing-panel.component.scss'],
})
export class WorkflowIndexingPanelComponent implements OnInit, OnChanges, AfterViewInit {
  @Input() prompts: Array<string>;
  @Input() metaDataCollection: MetaDataCollection;
  @Input() metadata: Array<IMetaDataDefinition>;
  @Input() metaDataService: IMetaDataService;
  @Input() indexingLoaded = false;

  @Input() findMetaDataService: IFindMetaDataById;
  @Input() metaDataValidator: IMetaDataValidator;

  @Output()
  overallValidityStatusChanged = new EventEmitter<OverallValidityStatusChangedData>();
  @Output() fieldTabbed = new EventEmitter<null>();

  fields: IMetaDataDefinition[] = [];
  fieldsDisabled: boolean = false;

  validationInProgress: boolean = false;
  @Output() validationInProgressChanged = new EventEmitter<ValidationInProgressChangedData>();

  constructor(
    public translateService: TranslateService,
    private toastr: ToastrService,
    private stickyService: StickyFieldsService
  ) {}

  ngOnChanges(changes: SimpleChanges) {
    if (this.isPromptsModalOpened()) {
      this.fields = this.prompts.map((metaDataId) => this.metadata.find((m) => m.id === metaDataId));
    }
  }

  ngOnInit() {}

  ngAfterViewInit() {
    if (this.isPromptsModalOpened() && !this.indexingLoaded) {
      setTimeout(() => {
        this.loadDefaultsAndValidate();
      }, 50);
    }
  }

  isPromptsModalOpened() {
    return this.prompts.length && this.metaDataCollection;
  }

  setValidationInProgress(inProgress: boolean, isInitial: boolean): void {
    this.validationInProgress = inProgress;
    this.validationInProgressChanged.emit(
      new ValidationInProgressChangedData({
        inProgress: inProgress,
        isInitial: isInitial,
      })
    );
  }

  loadDefaultsAndValidate = (): void => {
    this.setValidationInProgress(true, true);

    const pv = new PromptValidate(this.prompts, this.metaDataCollection);

    this.metaDataService.loadDefaultsAndValidateMetaData(pv, this.promptsLoaded, this.promptsLoadFailed);
  };

  promptsLoaded = (mdc: MetaDataCollection): void => {
    this.metaDataCollection.merge(mdc);
    this.updateOverallValidity();
    this.setValidationInProgress(false, true);
  };

  promptsLoadFailed = (err: any): void => {
    this.toastr.error(err);
    this.setValidationInProgress(false, true);
  };

  getFieldDefinition = (mdd: IMetaDataDefinition): FieldDefinition => {
    const fd = (mdd as MetaDataDefinition).asFieldDefinition();
    fd.datasource = FieldDataSource.create(mdd as MetaDataDefinition, this.metaDataService);

    return fd;
  };

  getFieldValue(mdd: IMetaDataDefinition) {
    const md = this.metaDataCollection.get(mdd.name);

    if (!md) return '';

    const mdValue = <string>md.value;

    if (!(mdd as MetaDataDefinition).stickyField) return mdValue;

    if (mdValue) {
      this.stickyService.setStickyField(mdd.name, mdValue);
      return mdValue;
    }

    const stickyValue = this.stickyService.getStickyField(mdd.name);
    if (!stickyValue) return '';

    this.setAndValidateMetaData(mdd, stickyValue);
    return stickyValue;
  }

  setField(value: string | BlurEvent, field: IMetaDataDefinition) {
    if (field.type == MetaDataType.CascadingOptions) {
      if (!(value as BlurEvent).mdd) return;
      this.metaDataCollection.set((value as BlurEvent).mdd.name, (value as BlurEvent).value, MetaDataValidity.unknown);
      return;
    }

    this.metaDataCollection.set(field.name, value as string, MetaDataValidity.unknown);
  }

  getValidity(mdd: IMetaDataDefinition) {
    const md = this.metaDataCollection.get(mdd.name);
    return md ? md.validity : MetaDataValidity.unknown;
  }

  onBlur(event: BlurEvent) {
    if (event.mdd) {
      this.setAndValidateMetaData(event.mdd, event.value);
      return;
    }
    this.setAndValidateMetaData(event.context, event.value);
  }

  setAndValidateMetaData(mdd: IMetaDataDefinition, value: string) {
    this.metaDataCollection.set(mdd.name, value, MetaDataValidity.unknown);

    this.setValidationInProgress(true, false);

    this.metaDataService.validateAndUpdateMetaData(
      new ValidationRequest(
        mdd,
        this.metaDataCollection,
        this.fields.map((x) => x.id).join(),
        this.fields.filter((x) => !x.id.startsWith('~~@')).map((x) => x.id),
        true
      ),
      (mdc: MetaDataCollection) => this.promptValidated(mdd, mdc),
      this.promptValidationFailed
    );
  }

  promptValidated = (mdd: IMetaDataDefinition, mdc: MetaDataCollection): void => {
    this.metaDataCollection.merge(mdc);
    this.updateOverallValidity();
    this.setValidationInProgress(false, false);
  };

  promptValidationFailed = (err: any): void => {
    this.toastr.error(err);
    this.setValidationInProgress(false, false);
  };

  updateOverallValidity = (): void => {
    this.overallValidityStatusChanged.emit(
      new OverallValidityStatusChangedData({
        overallValidity: this.metaDataCollection.getOverallValidity(),
        metaDataCollection: this.metaDataCollection,
      })
    );
  };

  onReturn(value: string) {
    this.fieldTabbed.emit();
  }

  onSaveLookupValues(event: SaveLookupsEvent) {
    this.updateMetadataValues(event.lookups);
    this.updateOverallValidity();
  }

  updateMetadataValues(lookupsToBeSaved: Array<LookupToBeSaved>) {
    lookupsToBeSaved.forEach((lookupToBeSaved) => {
      if (!lookupToBeSaved.overwrite) {
        if (this.getIndexingValue(lookupToBeSaved.metadata.name)) {
          return;
        }
      }

      this.metaDataCollection.set(lookupToBeSaved.metadata.name, lookupToBeSaved.value, lookupToBeSaved.validity);
    });
  }

  getIndexingValue(metaDataDefinitionName: string): string {
    const md = this.metaDataCollection.get(metaDataDefinitionName);
    return md ? <string>md.value : '';
  }
}
