  enqueue = (key: string, params: Array<any>, firstInFirstOut: boolean = true, cancelOld = false): boolean => {
    if (!this.queues[key]) this.queues[key] = [];
    if (cancelOld) this.dequeue(key, params);

    firstInFirstOut ? this.queues[key].push(params) : this.queues[key].unshift(params);

    return this.queues[key].length == 1;
  };

  dequeue = (key: string, params: Array<any>): boolean => {
    if (!this.queues[key] || this.queues[key].length <= 1) return true;
    const filteredQueue = this.queues[key].filter((x) => !Arrays.isSubsetOf(params, x));

    if (filteredQueue.indexOf(this.queues[key][0]) == -1) filteredQueue.push(this.queues[key][0]);
    this.queues[key] = filteredQueue;
  };

  nextInQueue = (key: string, oldParams: Array<any> = null): void => {
    if (!this.queues[key] || !this.queues[key].length) return;

    if (!oldParams || Arrays.isSubsetOf(oldParams, this.queues[key][0])) {
      this.queues[key].shift();
      if (!this.queues[key].length) return;
    }

    const methodName = this.queues[key][0][0];
    const params = this.queues[key][0].slice(1);
    params.push(false);

    this[methodName].apply(this, params);
  };

  updateQueuedMetaDataCollections = (key: string, request: ValidationRequest): void => {
    if (request.fromLineItem || !this.queues[key] || !this.queues[key].length) return;

    for (let i = 0; i < this.queues[key].length - 1; i++) {
      for (let x = 0; x < this.queues[key][i].length; x++) {
        if (!(this.queues[key][i][x] instanceof ValidationRequest)) continue;
        if ((this.queues[key][i][x] as ValidationRequest).id == request.id) continue;
        (this.queues[key][i][x] as ValidationRequest).mdc.merge(request.mdc);
      }
    }
  };

  syncWithQueuedMetaDataCollections = (key: string, mdc: MetaDataCollection, request: ValidationRequest): boolean => {
    if (request.fromLineItem || !this.queues[key] || this.queues[key].length <= 1) return;

    const md = mdc.get(request.mdd.name) as MetaData;
    for (let i = 0; i < this.queues[key].length; i++) {
      for (let x = 0; x < this.queues[key][i].length; x++) {
        if (!(this.queues[key][i][x] instanceof ValidationRequest)) continue;
        if ((this.queues[key][i][x] as ValidationRequest).id == request.id) continue;
        (this.queues[key][i][x] as ValidationRequest).mdc.set(md.name, md.value as string, md.validity, md.location);
      }
    }

    let latestQueuedMDC: MetaDataCollection;
    for (let i = this.queues[key].length - 1; i >= 0; i--) {
      for (let x = 0; x < this.queues[key][i].length; x++) {
        if (!(this.queues[key][i][x] instanceof ValidationRequest)) continue;
        if ((this.queues[key][i][x] as ValidationRequest).id == request.id) continue;
        latestQueuedMDC = (this.queues[key][i][x] as ValidationRequest).mdc;
        break;
      }

      if (latestQueuedMDC) break;
    }

    if (latestQueuedMDC) mdc.merge(latestQueuedMDC);

    return true;
  };

  canIgnoreRequest = (key: string, request: ValidationRequest): boolean => {
    if (request.fromLineItem || !this.queues[key] || this.queues[key].length <= 1) return false;

    for (let i = 0; i < this.queues[key].length; i++) {
      for (let x = 0; x < this.queues[key][i].length; x++) {
        if (
          this.queues[key][i][x] instanceof ValidationRequest &&
          (this.queues[key][i][x] as ValidationRequest).id != request.id &&
          (this.queues[key][i][x] as ValidationRequest).mdd.id == request.mdd.id
        )
          return true;
      }
    }

    return false;
  };

  public validateAndUpdateWorkItemMetaData(
    request: ValidationRequest,
    successCallBack: (workItem: WorkItem) => void,
    failureCallBack: (err: any) => void,
    isQueued: boolean = true
  ): void {
    const key = `metadata-validate-${request.workItemId}`;
    if (isQueued && !this.enqueue(key, [this.validateAndUpdateWorkItemMetaData.name, ...arguments])) {
      this.updateQueuedMetaDataCollections(key, request);
      return;
    }

    this._startMetaDataValidationSubject.next(request.mdd.id);
    this.incrementRequestsCount();
    this.http
      .post(
        `${this.baseUrl}/api/workitems/${request.workItemId}/metadata/${request.mdd.id}/validate`,
        request.mdc.serializable()
      )
      .subscribe(
        (updatedWorkItem: IWorkItem) => {
          this.onWorkitemMetadataValidationCompleted(request.mdd.id, key);

          if (this.canIgnoreRequest(key, request)) return;
          const workItem = new WorkItem(updatedWorkItem);
          this.syncWithQueuedMetaDataCollections(key, workItem.metadata, request);
          try {
            successCallBack(workItem);
          } catch (err) {}
        },
        (error: any) => {
          this.onWorkitemMetadataValidationCompleted(request.mdd.id, key);

          try {
            failureCallBack(error);
          } catch (err) {}
        }
      );
  }

  onWorkitemMetadataValidationCompleted = (id: string, key: string): void => {
    this.decrementRequestsCount();
    this._completeMetaDataValidationSubject.next(id);
    this.nextInQueue(key);
  };

