  public validateMetaData(
    request: ValidationRequest,
    successCallBack: (metaDataValidity: MetaDataValidity) => void,
    failureCallBack: (err: any) => void,
    isQueued: boolean = true
  ): void {
    const key = `metadata-validate-${request.workItemId}`;
    if (isQueued && !this.enqueue(key, [this.validateMetaData.name, ...arguments])) {
      this.updateQueuedMetaDataCollections(key, request);
      return;
    }

    this._startMetaDataValidationSubject.next(request.mdd.id);
    this.http.post(`${this.baseUrl}/api/metadata/${request.mdd.id}/validate`, request.mdc.serializable()).subscribe(
      (validity: MetaDataValidity) => {
        try {
          successCallBack(validity);
        } catch (err) {}

        this.onMetadataValidationCompleted(request.mdd.id, key);
      },
      (error: any) => {
        try {
          failureCallBack(error);
        } catch (err) {}

        this.onMetadataValidationCompleted(request.mdd.id, key);
      }
    );
  }

  onMetadataValidationCompleted = (id: string, key: string): void => {
    this._completeMetaDataValidationSubject.next(id);
    this.nextInQueue(key);
  };

  public validateAndUpdateMetaData(
    request: ValidationRequest,
    successCallBack: (mdc: MetaDataCollection) => void,
    failureCallBack: (err: any) => void,
    isQueued: boolean = true
  ): void {
    const key = `metadata-validate`;
    if (isQueued && !this.enqueue(key, [this.validateAndUpdateMetaData.name, ...arguments])) return;

    this._startMetaDataValidationSubject.next(request.mdd.id);
    if (request.mdd.id.startsWith('~~@@')) {
      const md = request.mdc.get(request.mdd.id);
      md.validity = MetaDataValidity.valid;
      try {
        successCallBack(request.mdc);
      } catch (error) {}

      this._completeMetaDataValidationSubject.next(request.mdd.id);
      this.nextInQueue(key);

      return;
    }

    this.http
      .post(
        `api/metadata/${request.mdd.id}/validateandupdate`,
        new MetaDataValidationParameters(request.mdc.serializable(), request.metaDataIds, request.evaluateExpressions)
      )
      .subscribe(
        (result: MetaDataCollectionDictionary) => {
          if (this.canIgnoreRequest(key, request)) {
            this.onMetadataValidationCompleted(request.mdd.id, key);
            return;
          }

          const mdc = new MetaDataCollection(result);
          this.syncWithQueuedMetaDataCollections(key, mdc, request);
          try {
            successCallBack(mdc);
          } catch (error) {}

          this.onMetadataValidationCompleted(request.mdd.id, key);
        },
        (error: any) => {
          try {
            failureCallBack(error);
          } catch (error) {}

          this.onMetadataValidationCompleted(request.mdd.id, key);
        }
      );
  }

