  public setDocumentLock(
    action: LockAction,
    documentId: string,
    successCallback: (ls: LockStatus) => void,
    failureCallback: (err) => void,
    isQueued: boolean = true
  ): void {
    const key = `document-lock-${documentId}`;
    if (isQueued && !this.enqueue(key, [this.setDocumentLock.name, ...arguments])) return;

    this.http.get(`${this.baseUrl}/api/locks/${action == LockAction.Lock ? 'lock' : 'unlock'}/${documentId}`).subscribe(
      (ils: ILockStatus) => {
        try {
          successCallback(new LockStatus(ils));
        } catch (err) {}

        this.nextInQueue(key);
      },
      (error: any) => {
        try {
          failureCallback(error);
        } catch (err) {}

        this.nextInQueue(key);
      }
    );
  }

