import { TranslateService } from '@ngx-translate/core';
import { Subject } from 'rxjs';
import { IInterFAXService } from '../interop/IInterFAXService';
import { IFieldDataSource, IFieldOptions } from './field-definition';

export interface ICoverPage {
  id: number;
  name: string;
  accountId: number;
  header: string;
  htmlBody: string;
  binaryBody: any;
  footer: string;
  type: CoverPageType;
  coverpageBodyType: CoverPageBodyType;
  isPublic: boolean;
  dateModifiedUTC?: Date;
  dateCreatedUTC?: Date;
  groups?: Array<number>;
  users?: Array<string>;
}

export enum CoverPageType {
  MessageOnly = 0,
  Html = 1,
  // PDF = 2, -- not supported for now
}

export enum CoverPageBodyType {
  None = 0,
  Text = 1,
  Html = 2,
}

export class CoverPage implements ICoverPage {
  public id: number;
  public name: string;
  public accountId: number;
  public header: string;
  public htmlBody: string;
  public binaryBody: any;
  public footer: string;
  public type: CoverPageType;
  public coverpageBodyType: CoverPageBodyType;
  public isPublic: boolean;
  public dateModifiedUTC?: Date;
  public dateCreatedUTC?: Date;
  public groups?: Array<number>;
  public users?: Array<string>;

  constructor(icp: ICoverPage) {
    this.id = icp.id;
    this.name = icp.name;
    this.accountId = icp.accountId;
    this.header = icp.header;
    this.htmlBody = icp.htmlBody;
    this.binaryBody = icp.binaryBody;
    this.footer = icp.footer;
    this.type = icp.type;
    this.coverpageBodyType = icp.coverpageBodyType;
    this.isPublic = icp.isPublic;
    this.dateModifiedUTC = icp.dateModifiedUTC;
    this.dateCreatedUTC = icp.dateCreatedUTC;
    this.groups = icp.groups;
    this.users = icp.users;
  }

  serializable(): ICoverPage {
    return {
      id: this.id,
      name: this.name,
      accountId: this.accountId,
      header: this.header,
      htmlBody: this.htmlBody,
      binaryBody: this.binaryBody,
      footer: this.footer,
      type: this.type,
      coverpageBodyType: this.coverpageBodyType,
      isPublic: this.isPublic,
      dateModifiedUTC: this.dateModifiedUTC,
      dateCreatedUTC: this.dateCreatedUTC,
      groups: this.groups,
      users: this.users,
    };
  }
}

export class CoverPagesDataSource implements IFieldDataSource {
  username: string;
  changed = new Subject<void>();

  coverPagesLoaded = (coverPages: Array<CoverPage>, successCallBack: (items: IFieldOptions[]) => void): void => {
    const fieldOptions = coverPages.map<IFieldOptions>((u) => ({ name: u.name, value: `${u.id}` }));

    fieldOptions.sort((a, b) => a.name.localeCompare(b.name));

    fieldOptions.unshift({ name: this.translate.instant('Common.None'), value: '0' });

    successCallBack(fieldOptions);
  };

  coverPagesFailedToLoad = (err, successCallBack: (items: IFieldOptions[]) => void): void => {
    this.coverPagesLoaded([], successCallBack);
  };

  constructor(
    private interFAXService: IInterFAXService,
    private translate: TranslateService,
    username: string
  ) {
    this.username = username;
  }

  getItems(
    startsWith: string,
    currentValue: string,
    successCallBack: (items: IFieldOptions[]) => void,
    failureCallBack: (err: any) => void
  ): void {
    this.interFAXService.getUserCoverpages(
      this.username,
      (coverPages: Array<CoverPage>) => {
        this.coverPagesLoaded(coverPages, successCallBack);
      },
      (err) => this.coverPagesFailedToLoad(err, successCallBack)
    );
  }
}
