import { Component, ElementRef, EventEmitter, OnDestroy, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { ToastrService } from 'ngx-toastr';
import { FieldDefinition, MetaDataType, ISearchItems } from 'shared-code-lib';
import { CostCenter, FaxUserStatus, IFaxUserSelect } from '../../InterFAX/Models/admin';
import { InterFAXService } from '../../services/interfax.service';
import { ApiResults } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { Subscription } from 'rxjs';

class Member {
  name: string;

  constructor(name: string) {
    this.name = name;
  }
}

@Component({
  selector: 'app-interfax-costcenter-modal',
  templateUrl: './interfax-costcenter-modal.component.html',
  styleUrls: ['./interfax-costcenter-modal.component.scss'],
})
export class InterfaxCostcenterModalComponent implements OnInit, OnDestroy, ISearchItems {
  directiveRef: PerfectScrollbarDirective;
  @ViewChild(PerfectScrollbarDirective, { static: false }) set content(content: PerfectScrollbarDirective) {
    if (content) {
      this.directiveRef = content;
    }
  }
  @ViewChild('spinnerElement', { static: true }) spinnerElement;

  @Output() closeModal = new EventEmitter();

  fieldName: FieldDefinition;
  title: string;
  errors = new Array<string>();
  show: boolean;
  costCenter: CostCenter;
  available: Array<Member> = [];
  current: Array<Member> = [];
  editMode: boolean;

  subscriptions = new Subscription();

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private interfaxService: InterFAXService,
    private toastr: ToastrService
  ) {}

  ngOnInit(): void {
    this.createFields();
    const id = this.sharedDataService.extraParameters ? this.sharedDataService.extraParameters.id : '';
    this.editMode = id != '';
    this.spinnerService.show(this.translateService.instant('Common.Loading'), this.spinnerElement.nativeElement);

    if (this.editMode) {
      this.title = this.translateService.instant('cost-center.title-existing');
      this.subscriptions.add(this.interfaxService.getCostCenter(id, this.loaded, this.loadFailed));
    } else {
      this.title = this.translateService.instant('cost-center.title-new');
      this.costCenter = new CostCenter();
      this.available = [];

      this.load();
    }
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  findMatches(searchTerm: string, completed: (items: Array<any>) => void): void {
    this.subscriptions.add(
      this.interfaxService.getUsersSelect(
        (users: Array<IFaxUserSelect>) => {
          completed(users.map((u) => new Member(u.userId)));
        },
        () => {},
        searchTerm,
        FaxUserStatus.Open
      )
    );
  }

  currentChanged = (current: Array<Member>): void => {
    this.costCenter.members = current.map((m) => m.name);
  };

  loaded = (cc: CostCenter): void => {
    this.costCenter = cc;

    this.load();
  };

  loadFailed = (err: any): void => {
    this.spinnerService.hide();
  };

  load = (): void => {
    this.current = this.costCenter.members.map((u) => new Member(u));

    this.spinnerService.hide();
    this.show = true;
  };

  save = (): void => {
    if (this.costCenter.name.trim()) {
      this.spinnerService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);
      this.subscriptions.add(this.interfaxService.setCostCenter(this.costCenter, this.saved, this.saveFailed));
    }
  };

  saved = (r: ApiResults): void => {
    this.spinnerService.hide();

    if (r.success) {
      this.toastr.success(
        this.translateService.instant(this.editMode ? 'cost-center.save-success' : 'cost-center.create-success')
      );
      this.close();
      this.sharedDataService.actionHandler.reload.emit(true);
    } else {
      this.errors = r.errors;
      this.directiveRef.update();
    }
  };

  saveFailed = (err: Error): void => {
    this.spinnerService.hide();
    this.errors.push(err.message);
    this.directiveRef.update();
  };

  close = (): void => {
    this.show = false;
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  createFields = (): void => {
    this.fieldName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('cost-center.name'),
      placeholder: this.translateService.instant('cost-center.name-placeholder'),
      required: true,
    });
  };
}
