import { Component, OnDestroy, OnInit, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-error-page-complete',
  templateUrl: './error-page.component.html',
  styleUrls: ['./error-page.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class ErrorPageComponent implements OnInit, OnDestroy {
  title: string = `app-initialize.failed`;
  errors: string[] = [];
  subscriptions = new Subscription();

  constructor(private route: ActivatedRoute, private translate: TranslateService) {}

  ngOnInit(): void {
    this.subscriptions.add(
      this.route.data.subscribe((d) => {
        if (d.is404) {
          const url = `/${this.route.snapshot.url.join('/')}`;
          const errorText = this.translate.instant('Common.UnableToAccessUrl').replace('{url}', url);

          this.title = `Common.SomethingWentWrong`;
          this.errors = [errorText];
        }
      })
    );

    this.subscriptions.add(
      this.route.queryParams.subscribe((params) => {
        const error = params['error'];
        if (error) this.errors = [params['error']];
      })
    );
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
