import { Directive, Input, Output, EventEmitter, ElementRef, HostListener } from '@angular/core';
declare var $: any;

@Directive({
  selector: '[clickOutside]',
})
export class ClickOutsideDirective {
  constructor(private _elementRef: ElementRef) {
    this.listenToScrollEvents();
  }

  scrollStates: Array<scrollState> = [];

  @Input() relatedItems: string;
  @Output() clickOutside = new EventEmitter();

  @HostListener('document:pointerdown', ['$event'])
  @HostListener('document:pointermove', ['$event'])
  onPointerDown(event) {
    if (!event.buttons) return;

    const clickedInside =
      this._elementRef.nativeElement.contains(event?.target) ||
      (this.relatedItems && event.target?.closest(this.relatedItems));
    if (!clickedInside) this.clickOutside.emit(null);
  }

  listenToScrollEvents = (): void => {
    document.querySelectorAll('*').forEach((x) => this.scrollStates.push({ element: x, scrollTop: x.scrollTop }));
    document.addEventListener(
      'scroll',
      (event: any) => {
        const target = event.target as HTMLElement;
        if (!target || target.tagName?.toLocaleLowerCase() == 'input') return;

        const index = this.scrollStates.findIndex((x) => x.element == target);

        if (index == -1) {
          this.scrollStates.push({ element: target, scrollTop: target.scrollTop });
        } else {
          if (this.scrollStates[index].scrollTop != target.scrollTop) {
            this.scrollStates[index].scrollTop = target.scrollTop;
          } else {
            return;
          }
        }

        const clickedInside =
          this._elementRef.nativeElement.contains(event?.target) ||
          (this.relatedItems && event?.target?.closest(this.relatedItems));

        if (!clickedInside) this.clickOutside.emit(null);
      },
      true
    );
  };
}

export class scrollState {
  constructor(public element: Element, public scrollTop: number) {}
}
