import { Injectable, NgZone } from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { SsoManagerService } from '../../../Bamba.Web/ClientApp/src/app/blocks/auth/sso-manager.service';
import { UserSignOnType } from '../../../Bamba.Web/ClientApp/src/app/blocks/models/user-profile';
import { SharedDataService } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/shared-data.service';
import { SpinnerStateService } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { AuthorizationResult } from '../auth/login-base/login-base.component';
import { SignOnDetailsResult } from '../auth/login/login.component';
import { AuthService } from './auth/auth.service';
import { SessionStorageService } from './session-storage.service';

interface IPrintTo {
  setCredentials(userName: string, password: string): void;
  getCredentials(): string;
  getDocuments(): string;
  closeApp(): void;
}

class Credentials {
  username: string;
  password: string;
}

class FileModel {
  fileName: string;
  base64File: string;
}

@Injectable({
  providedIn: 'root',
})
export class PrintToService {
  isInitialized: boolean;

  constructor(
    private sessionStorageService: SessionStorageService,
    private authService: AuthService,
    private router: Router,
    private zone: NgZone,
    private sharedDataService: SharedDataService,
    private translateService: TranslateService,
    private spinnerStateService: SpinnerStateService,
    private ssoManagerService: SsoManagerService
  ) {}

  get isPrintToMode() {
    return this.getPrintTo() ? true : false;
  }

  getPrintTo = (): IPrintTo => {
    return window['printToJavascriptObject'];
  };

  start = (type: string): void => {
    this.initialize();

    const credentials = this.getCredentials();
    if (credentials != null) {
      this.sessionStorageService.setUsername(credentials.username);

      this.translateService.get('Login.Verify-Username-Message').subscribe((res) => {
        this.spinnerStateService.show(res, document.documentElement);
        this.authService.getUserSignOnDetails(
          credentials.username,
          this.getUserSignOnDetailsSuccess,
          this.getUserSignOnDetailsFailure
        );
      });

      return;
    }

    this.navigateToLogin();
  };

  getUserSignOnDetailsSuccess = (sr: SignOnDetailsResult) => {
    this.spinnerStateService.hide();

    const credentials = this.getCredentials();

    if (sr.userSignOnType === UserSignOnType.Password) {
      this.authService.login(
        credentials.username,
        credentials.password,
        this.sessionStorageService.getIsMobile(),
        this.loginSuccessCallBack,
        this.navigateToLogin
      );
    } else if (sr.userSignOnType == UserSignOnType.SSO) {
      this.translateService.get('Login.transferring-to-sso').subscribe((res) => {
        this.spinnerStateService.show(res, document.documentElement);
        this.ssoManagerService.startSignin(sr.ssoAuthority, sr.ssoClientId);
      });
    } else if (sr.userSignOnType == UserSignOnType.SAML) {
      this.translateService.get('Login.transferring-to-sso').subscribe((res) => {
        this.spinnerStateService.show(res, document.documentElement);
        const url = `${window.location.protocol}//${window.location.host}/api/saml/InitiateSingleSignOn?id=${sr.id}&returnUrl=${window.location.origin}/saml-callback`;
        window.location.href = url;
      });
    } else {
      this.navigateToLogin();
    }
  };

  getUserSignOnDetailsFailure = (error: any) => this.navigateToLogin();

  initialize = (): void => {
    this.sessionStorageService.setIsMobile(false);
    this.sessionStorageService.setIsInterFaxMobile(false);

    this.addDocuments();
    this.isInitialized = true;
    this.sessionStorageService.setReturnUrl('/bamba-sendfax'); //todo: based on type
  };

  getCredentials = (): Credentials => {
    const credentials = this.getPrintTo().getCredentials();
    if (credentials == null) return null;

    const c: Credentials = JSON.parse(credentials);

    return c;
  };

  setCredentials = (username: string, password: string): void => {
    if (this.getPrintTo()) {
      this.getPrintTo().setCredentials(username, password);
    }
  };

  navigateToLogin = (): void => {
    this.router.navigate(['/login'], { queryParams: { returnUrl: '/bamba-sendfax' } });
  };

  addDocuments(): void {
    this.sharedDataService.files = [];

    const files: Array<FileModel> = JSON.parse(this.getPrintTo().getDocuments());
    for (const f of files) {
      this.sharedDataService.files.push(this.base64toFile(f.base64File, f.fileName));
    }
  }

  base64toFile = (b64Data: string, fileName: string) => {
    var binary = atob(b64Data.replace(/\s/g, ''));
    var len = binary.length;
    var buffer = new ArrayBuffer(len);
    var byteData = new Uint8Array(buffer);

    for (var i = 0; i < len; i++) {
      byteData[i] = binary.charCodeAt(i);
    }

    return new File([byteData], fileName);
  };

  loginSuccessCallBack = (ar: AuthorizationResult, username: any) => {
    if (!ar.succeeded) {
      this.navigateToLogin();
      return;
    }

    this.authService.setSession(ar);

    this.authService.loginPasswordSuccess(ar, username, this.getCredentials().password, this);

    document.body.className += ' print-to-mode';
  };

  closeAppIfPrintTo(): void {
    if (this.getPrintTo()) this.getPrintTo().closeApp();
  }
}
