import { Subject } from 'rxjs';

import { MetaDataDefinition, IMetaDataDefinition } from './../models/metadata-definition';
import { MetaDataValidity } from './../models/metadata';
import { IFieldDataSource, IFieldOptions } from './field-definition';
import { LookupMatchType } from './../utils/enums';
import { IMetaDataService, IFindMetaDataById } from '../interop/MetaDataService';

export class LookupMatch {
  type: LookupMatchType;
  mappings: Array<LookupMapping>;

  constructor(initializer?: any) {
    if (initializer.type == null) throw Error('Invalid LookupMatch Initializer');
    if (initializer.mappings == null) throw new Error('Invalid LookupMatch Initializer');

    this.type = initializer.type;
    this.mappings = initializer.mappings.map((m: any) => new LookupMapping(m));
  }
}

export class LookupMapping {
  metaDataId: string;
  value: string;
  overwrite: boolean;

  constructor(initializer?: any) {
    if (initializer.metaDataId == null) throw Error('Invalid LookupMapping Initializer');
    if (initializer.value == null) throw new Error('Invalid LookupMapping Initializer');
    if (initializer.overwrite == null) throw new Error('Invalid LookupMapping Initializer');

    this.metaDataId = initializer.metaDataId;
    this.value = initializer.value;
    this.overwrite = initializer.overwrite;
  }
}

export class LookupToBeSaved extends LookupMapping {
  metadata: IMetaDataDefinition;

  constructor(private finder: IFindMetaDataById, private mapping: LookupMapping, public validity: MetaDataValidity) {
    super(mapping);

    this.metadata = finder.findMetaDataById(mapping.metaDataId);
  }
}

export class MetaDataLookupDataSource implements IFieldDataSource {
  changed = new Subject<void>();
  displayLookUpAsList: boolean = false;

  constructor(private mdd: MetaDataDefinition, private metaDataService: IMetaDataService) {
    this.displayLookUpAsList = mdd.lookup.displayAsList;
  }

  getItems(
    startsWith: string,
    currentValue: string,
    successCallBack: (items: Array<IFieldOptions>, matches: Array<LookupMatch>) => void,
    failureCallBack: (err: any) => void
  ): void {
    this.getMatches(startsWith)
      .then((matches: Array<LookupMatch>) => {
        let options: IFieldOptions[] = [];
        matches.map((m) => {
          m.mappings
            .filter((m) => m.metaDataId === this.mdd.id)
            .forEach((map) => {
              options.push(<IFieldOptions>{
                name: map.value,
                value: map.value,
              });
            });
        });

        options.sort((a, b) => a.name.localeCompare(b.name));
        successCallBack(options, matches);
      })
      .catch((err) => {
        failureCallBack(err);
      });
  }

  getMatches(targetValue: string): Promise<Array<LookupMatch>> {
    return new Promise((resolve, reject) => {
      const targetMapping = new LookupMapping({
        metaDataId: this.mdd.id,
        value: targetValue,
        overwrite: true,
      });
      this.metaDataService.lookupMetaDataValue(
        targetMapping,
        (matches: Array<LookupMatch>) => {
          resolve(matches);
        },
        (err: any) => {
          reject(err);
        }
      );
    });
  }

  getId(): string {
    return this.mdd.id;
  }
}
