export interface IIDPSettings {
  name: string;
  singleSignOnServiceUrl: string;
  singleSignOnServiceBinding: string;
  partnerCertificates: ICertificateDetails[];
}

export class IDPSettings {
  public name: string;
  public singleSignOnServiceUrl: string;
  public singleSignOnServiceBinding: string;
  public partnerCertificates: CertificateDetails[];

  public constructor(idp: IIDPSettings) {
    this.name = idp.name;
    this.singleSignOnServiceUrl = idp.singleSignOnServiceUrl;
    this.singleSignOnServiceBinding = idp.singleSignOnServiceBinding;
    this.partnerCertificates = idp.partnerCertificates.map((x) => new CertificateDetails(x));
  }

  public serializable(): IIDPSettings {
    return {
      name: this.name,
      singleSignOnServiceUrl: this.singleSignOnServiceUrl,
      singleSignOnServiceBinding: this.singleSignOnServiceBinding,
      partnerCertificates: this.partnerCertificates.map((x) => x.serializable()),
    };
  }
}

export interface ICertificateDetails {
  fileName: string;
  contents: string;
  string?: string;
  use: string;
}

export class CertificateDetails {
  public fileName: string;
  public contents: string;

  get string() {
    return this.contents;
  }
  set string(val: string) {
    this.contents = val;
  }

  public use: string;

  public constructor(cd: ICertificateDetails) {
    this.fileName = cd.fileName;
    this.contents = cd.contents;
    if (cd.string) this.string = cd.string;

    this.use = cd.use;
  }

  serializable(): ICertificateDetails {
    return {
      fileName: this.fileName,
      contents: this.contents,
      string: this.string,
      use: this.use,
    };
  }
}

export class IDPMetadata {
  entityId: string;
  idpSSOKeys: CertificateDetails[];
  singleSignOnServiceUrl: string;
  singleSignOnServiceBinding: string;
  SingleLogoutService: string;
}
