import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  OnInit,
  Output,
  Renderer2,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { DelayService } from '../../utils/delay.service';

export class Tab {
  constructor(
    public id: string,
    public title: string
  ) {}
}

@Component({
  selector: 'app-tab-bar',
  templateUrl: './tab-bar.component.html',
  styleUrls: ['./tab-bar.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class TabBarComponent implements OnInit, AfterViewInit, OnChanges {
  @ViewChild('tabsWrapper') tabsWrapper: ElementRef;
  @Input() tabs: Array<Tab>;
  @Input() activeTab = '';

  @Output() tabSelected = new EventEmitter<string>();

  tabItemWidth: number;
  constructor(
    private delay: DelayService,
    private renderer: Renderer2,
    private route: ActivatedRoute
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.tabs) {
      this.initializeTabs();
    }
  }

  ngOnInit() {
    if (this.route.snapshot.queryParamMap.get('tab')) {
      this.activeTab = this.route.snapshot.queryParamMap.get('tab');

      this.initializeTabs();
    }
  }

  ngAfterViewInit(): void {
    this.delay.execute(() => {
      const tabsElements = Array.prototype.slice.call(this.tabsWrapper.nativeElement.querySelectorAll('.nav-tab-item'));
      this.handleTruncatingLongTitles(tabsElements);
    });
  }

  activateTab = (id: string): void => {
    this.activeTab = id;
    this.tabSelected.next(id);
  };

  private initializeTabs = () => {
    if (this.tabs.length === 0) return;

    const isActiveTabInTabs = this.tabs.map((t) => t.id).indexOf(this.activeTab) >= 0;

    if (!this.activeTab || !isActiveTabInTabs) this.activateTab(this.tabs[0].id);
  };

  private handleTruncatingLongTitles(tabsElements: Array<HTMLElement>): void {
    if (this.tabsWrapper.nativeElement.offsetWidth < this.getChildrenTotalWidth(tabsElements)) {
      const largestEl = this.getLargestElementByWidth(tabsElements);
      this.renderer.setStyle(largestEl, 'width', largestEl.offsetWidth - 1 + 'px');
      this.handleTruncatingLongTitles(tabsElements);
    }
  }

  private getLargestElementByWidth(elements: Array<HTMLElement>): HTMLElement {
    let largestEl: HTMLElement = elements[0];
    elements.forEach((el) => {
      largestEl = el.offsetWidth > largestEl.offsetWidth ? el : largestEl;
    });
    return largestEl;
  }

  private getChildrenTotalWidth(elements: Array<HTMLElement>): number {
    return elements.reduce((acc, current) => {
      return acc + current.offsetWidth;
    }, 0);
  }
}
