import { Log } from '../../../../blocks/core/log';
import { Filter, IFilter } from '../../../../blocks/models/filter';

class OLCProductionFilterByUser extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCUserComponent';
  }
}

class OLCTProductionFilterBySubmissionDate extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCDateComponent';
  }
}

class OLCTProductionFilterByStatus extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCTemplateVersionStatusComponent';
  }
}

export class OLCProductionFilters {
  public static Create = (filter: IFilter): Filter | null => {
    Log.enter('OLCProductionFilters.Create', filter);

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Production.Filters.FilterBySubmitterUser') {
      return new OLCProductionFilterByUser(filter);
    }

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Production.Filters.FilterByProductionUser') {
      return new OLCProductionFilterByUser(filter);
    }

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Production.Filters.FilterBySubmissionDate') {
      return new OLCTProductionFilterBySubmissionDate(filter);
    }

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Production.Filters.FilterByStatus') {
      return new OLCTProductionFilterByStatus(filter);
    }

    return null;
  };
}
