import { MappingHandleMultiple, MetaDataCollection, MetaDataCollectionDictionary } from 'shared-code-lib';
import { IWebIntegrationInbound, WebIntegrationInbound } from './webintegration';

export interface IBackup {
  enabled: boolean;
  timeoutPeriodInMinutes: number;
  faxNumber: string;
}

export class Backup {
  public enabled: boolean;
  public timeoutPeriodInMinutes: number;
  public faxNumber: string;

  constructor(b: IBackup = null) {
    this.enabled = b ? b.enabled : false;
    this.timeoutPeriodInMinutes = b ? b.timeoutPeriodInMinutes : 1;
    this.faxNumber = b ? b.faxNumber : '';
  }

  serializable(): IBackup {
    return {
      enabled: this.enabled,
      timeoutPeriodInMinutes: this.timeoutPeriodInMinutes,
      faxNumber: this.faxNumber,
    };
  }
}

export interface IRedistribute {
  enabled: boolean;
  redistributions: Array<IRedistributeTo>;
  restrictions: Array<IRestrictBy>;
}

export class Redistribute {
  public enabled: boolean;

  public redistributions: Array<RedistributeTo>;
  public restrictions: Array<RestrictBy>;

  constructor(r: IRedistribute = null) {
    this.enabled = r ? r.enabled : false;
    this.redistributions = r ? r.redistributions.map((r) => new RedistributeTo(r)) : [];
    this.restrictions = r ? r.restrictions.map((r) => new RestrictBy(r)) : [];
  }

  serializable(): IRedistribute {
    return {
      enabled: this.enabled,
      redistributions: this.redistributions.map((r) => r.serializable()),
      restrictions: this.restrictions.map((r) => r.serializable()),
    };
  }
}

export enum RedistributeToType {
  Fax = 0,
  ContactList = 1,
}

export interface IRedistributeTo {
  redistributeToType: RedistributeToType;
  to: string;
}

export class RedistributeTo {
  public redistributeToType: RedistributeToType;
  public to: string;

  constructor(rt: IRedistributeTo) {
    this.redistributeToType = rt.redistributeToType;
    this.to = rt.to;
  }

  serializable(): IRedistributeTo {
    return {
      redistributeToType: this.redistributeToType,
      to: this.to,
    };
  }
}

export enum DeleteFaxImageOptions {
  Never = 0,
  AfterNotificationsCompleted = 1,
  AfterFaxRetrievedUsingXMLWebService = 2,
}

export enum RestrictByType {
  CallerId = 0,
  CSID = 1,
}

export interface IRestrictBy {
  restrictByType: RestrictByType;
  by: string;
}
export class RestrictBy {
  public restrictByType: RestrictByType;
  public by: string;

  constructor(rb: IRestrictBy) {
    this.restrictByType = rb.restrictByType;
    this.by = rb.by;
  }

  serializable(): IRestrictBy {
    return {
      restrictByType: this.restrictByType,
      by: this.by,
    };
  }
}

export interface IAutoShare {
  enabled: boolean;
  shares: Array<IShareWith>;
}

export class AutoShare {
  public enabled: boolean;
  public shares: Array<ShareWith>;

  constructor(as: IAutoShare = null) {
    this.enabled = as ? as.enabled : false;
    this.shares = as ? as.shares.map((s) => new ShareWith(s)) : [];
  }

  serializable(): IAutoShare {
    return {
      enabled: this.enabled,
      shares: this.shares.map((s) => s.serializable()),
    };
  }
}

export enum ShareWithType {
  User = 0,
  Group = 1,
  Account = 2,
}

export enum SharePermissions {
  SelfDelete = 0,
  View = 1,
  Edit = 2,
  Share = 4,
  Owner = 127,
}

export enum DocumentEntityType {
  None,
  User,
  Group,
  Account,
}

export interface IShareWith {
  shareWithType: ShareWithType;
  permissions: SharePermissions;
  name: string;
  entity: string;
  entityType: DocumentEntityType;
}
export class ShareWith {
  public shareWithType: ShareWithType;
  public permissions: SharePermissions;
  public name: string;
  public entity: string;
  public entityType: DocumentEntityType;

  constructor(sw: IShareWith = null) {
    this.shareWithType = sw ? sw.shareWithType : (-1 as ShareWithType);
    this.permissions = sw ? sw.permissions : (-1 as SharePermissions);
    this.name = sw ? sw.name : '';
    this.entity = sw ? sw.entity : '';
    this.entityType = sw ? sw.entityType : (-1 as DocumentEntityType);
  }

  equals(shareWith: ShareWith) {
    return this.name === shareWith.name && this.entity === shareWith.entity;
  }

  serializable(): IShareWith {
    return {
      shareWithType: this.shareWithType,
      permissions: this.permissions,
      name: this.name,
      entity: this.entity,
      entityType: this.entityType,
    };
  }
}

export enum EmailFormat {
  PlainWithLink = 0,
  Plain = 1,
  Html = 2,
  NEC = 3,
}

export interface INotification {
  email: string;
  format: EmailFormat;
  sign: boolean;
  encrypt: boolean;
  hasDigitalId: boolean;
}

export class Notification {
  public email: string;
  public format: EmailFormat;
  public sign: boolean;
  public encrypt: boolean;
  public hasDigitalId: boolean;

  constructor(n: INotification) {
    this.email = n.email;
    this.format = n.format;
    this.sign = n.sign;
    this.encrypt = n.encrypt;
    this.hasDigitalId = n.hasDigitalId;
  }

  serializable(): INotification {
    return {
      email: this.email,
      format: this.format,
      sign: this.sign,
      encrypt: this.encrypt,
      hasDigitalId: this.hasDigitalId,
    };
  }
}

export interface IInbound {
  notifications: Array<Notification>;
  attachmentFormat: string;
  deleteFaxImage: DeleteFaxImageOptions;
  backup: IBackup;
  redistribute: IRedistribute;
  autoShare: IAutoShare;
  webIntegration: IWebIntegrationInbound;
  hasOutboundService: boolean;
  isPCI: boolean;
  inboundBarcodes: IUserInboundBarcodes;
  useAdvancedRouting: boolean;
  advancedRoutingWorkflowId: string;
}

export class Inbound implements IInbound {
  public notifications: Array<Notification>;
  public attachmentFormat: string;
  public deleteFaxImage: DeleteFaxImageOptions;
  public backup: Backup;
  public redistribute: Redistribute;
  public autoShare: AutoShare;
  public webIntegration: WebIntegrationInbound;
  public hasOutboundService: boolean;
  public useAdvancedRouting: boolean;
  public advancedRoutingWorkflowId: string;
  public inboundBarcodes: UserInboundBarcodes;
  public isPCI: boolean;

  constructor(i: IInbound) {
    this.notifications = i ? i.notifications.map((n) => new Notification(n)) : [];
    this.attachmentFormat = i ? i.attachmentFormat : '';
    this.deleteFaxImage = i ? i.deleteFaxImage ?? 0 : 0;
    this.backup = i ? new Backup(i.backup) : new Backup();
    this.redistribute = i ? new Redistribute(i.redistribute) : new Redistribute();
    this.autoShare = i ? new AutoShare(i.autoShare) : new AutoShare();
    this.webIntegration = i ? new WebIntegrationInbound(i.webIntegration) : new WebIntegrationInbound();
    this.hasOutboundService = i ? i.hasOutboundService : false;
    this.isPCI = i ? i.isPCI : false;
    this.inboundBarcodes = i ? new UserInboundBarcodes(i.inboundBarcodes) : new UserInboundBarcodes();
    this.useAdvancedRouting = i ? i.useAdvancedRouting : false;
    this.advancedRoutingWorkflowId = i ? i.advancedRoutingWorkflowId : '';
  }

  serializable(): IInbound {
    return {
      notifications: this.notifications,
      attachmentFormat: this.attachmentFormat,
      deleteFaxImage: this.deleteFaxImage,
      backup: this.backup.serializable(),
      redistribute: this.redistribute.serializable(),
      autoShare: this.autoShare.serializable(),
      webIntegration: this.webIntegration.serializable(),
      hasOutboundService: this.hasOutboundService,
      isPCI: this.isPCI,
      inboundBarcodes: this.inboundBarcodes.serializable(),
      useAdvancedRouting: this.useAdvancedRouting,
      advancedRoutingWorkflowId: this.advancedRoutingWorkflowId,
    };
  }
}

export interface IInboundDocument {
  id: number;
  labels: string[];
  metaData: MetaDataCollectionDictionary;
  sharing: Array<IShareWith>;
  name: string;
  reference: string;
  permissions: number;
}

export class InboundDocument {
  public id: number;
  public labels: string[];
  public metaData: MetaDataCollection;
  public sharing: Array<ShareWith>;
  public name: string;
  public reference: string;
  public permissions: number;

  constructor(document: IInboundDocument = null) {
    this.id = document ? document.id : -1;
    this.labels = document ? document.labels : [];
    this.metaData = document ? new MetaDataCollection(document.metaData) : new MetaDataCollection();
    this.sharing = document ? document.sharing.map((s) => new ShareWith(s)) : [];
    this.name = document ? document.name : '';
    this.reference = document ? document.reference : '';
    this.permissions = document ? document.permissions : 0;
  }

  permissionsAllowed(p: SharePermissions): boolean {
    return (this.permissions & p) === p;
  }

  serializable = (): IInboundDocument => {
    return {
      id: this.id,
      labels: this.labels,
      metaData: this.metaData.serializable(),
      sharing: this.sharing.map((s) => s.serializable()),
      name: this.name,
      reference: this.reference,
      permissions: this.permissions,
    };
  };
}

export enum PageLocation {
  Any = '*',
  First = 'first',
  Last = 'last',
  Custom = 'custom',
}

export class BarcodeMapping {
  page: string = '*';
  regEx: string = '.*';
  targetStorage: string = '#';
  value: string = '%barcode%';
  mappingHandleMultiple: MappingHandleMultiple = MappingHandleMultiple.None;
}

export interface IUserInboundBarcodes {
  id: number;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  userID: string;
  enabled: boolean;
  barcodeMappings: Array<BarcodeMapping>;
}

export class UserInboundBarcodes {
  id: number;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  userID: string;
  enabled: boolean;
  barcodeMappings: Array<BarcodeMapping>;
  constructor(configuration: IUserInboundBarcodes = null) {
    if (!configuration) return;

    this.id = configuration.id;
    this.dateCreatedUTC = configuration.dateCreatedUTC;
    this.dateModifiedUTC = configuration.dateModifiedUTC;
    this.userID = configuration.userID;
    this.enabled = configuration.enabled;
    this.barcodeMappings = configuration.barcodeMappings;
  }

  serializable = (): IUserInboundBarcodes => {
    return {
      id: this.id,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      userID: this.userID,
      enabled: this.enabled,
      barcodeMappings: this.barcodeMappings,
    };
  };
}
