import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
  name: 'search',
})
export class SearchPipe implements PipeTransform {
  public transform(value: any, keys: string, term: string) {
    const keysArr = keys.split('.');
    if (keysArr.length > 2) {
      throw new Error('You cannot provide more than two keys');
    }

    if (!term) {
      return value;
    }

    return (value || []).filter((item: any) => {
      let itemObject: any;
      let searchKey: string;
      if (keysArr.length > 1) {
        itemObject = item[keysArr[0]];
        searchKey = keysArr[1];
      } else {
        itemObject = item;
        searchKey = keysArr[0];
      }

      return (
        Object.prototype.hasOwnProperty.call(itemObject, searchKey) &&
        itemObject[searchKey].toLowerCase().indexOf(term.toLowerCase()) !== -1
      );
    });
  }
}
