import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { EditorComponent, EditorState, EditorView, Schema } from '@progress/kendo-angular-editor';
import { EditorCommand } from '@progress/kendo-angular-editor/common/commands';
import { insertNode } from '@progress/kendo-editor-common';
import { isEqual, uniqueId } from 'lodash';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { Node, DOMParser as ProseDOMParser } from 'prosemirror-model';
import { Selection } from 'prosemirror-state';
import { Observable, Subscription, concat, fromEvent, interval } from 'rxjs';
import { debounceTime, distinctUntilChanged, filter, first, map, skip, take, tap } from 'rxjs/operators';
import {
  DelayService,
  FieldDefinition,
  FixedDataSource,
  IFieldOptions,
  Key,
  MetaDataType,
  Strings,
  Substitution,
  TEXTFONTSIZE,
  TEXTFONTTYPE,
} from 'shared-code-lib';
import { Snippet } from '../../../views/admin-olc/models/snippet';
import {
  ITemplateConditionalContent,
  ITemplateVariable,
  StyleType,
  TemplateStyle,
} from '../../../views/admin-olc/models/template';
import { SendFaxService } from '../../services/send-fax.service';
import { UserStateService } from '../../services/user-state.service';
import { MediaFileType } from './../../../views/admin-olc/models/media';
import { MediaPreviewData } from './../../../views/admin-olc/templates/template-editor/models/ted-state';
import { createEditorSchema } from './editor-schema/schema';
import {
  FontSizes,
  defaultFontFamilies,
  defaultHTML,
  supportedBarcodesArray,
} from './html-editor-toolbar/editor-toolbar-constants';
import { IToolbarState, getToolbarState } from './html-editor-toolbar/html-editor-toolbar-state';
import { HtmlPartType, IHtmlPart, NavigationDirection } from './models';
import { showOrHidePageBreaks } from './page-breaks-utils/page-breaks-utils';
import {
  extractFirstPageFromPdfAsImage,
  mapImagesToBlobUrls,
  mapImagesToPdfImages,
} from './pdf-images-utils/pdf-images-utils';
import { AlignmentType, applyBlockStyleFormat } from './styles-utils/block-styles';
import { addInlineFormat, mapInlineStylesToString } from './styles-utils/inline-styles';
import {
  addColumnAfter,
  addColumnBefore,
  cursorIsInsideTable,
  goToNextTableCell,
  removeColumn,
  removeRow,
  removeTable,
} from './tables-utils/tables-utils';
import { createArrayFromNumber, isHtmlEmpty, pressArrowDown } from './utils/utils';

declare var $: any;

@Component({
  selector: 'app-html-editor',
  templateUrl: './html-editor.component.html',
  styleUrls: ['./html-editor.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class HtmlEditorComponent implements OnChanges, OnInit, AfterViewInit, OnDestroy {
  @Input() initialValue = '';
  @Input() placeholder = '';
  @Input() resizable = false;
  @Input() width = '100%';
  @Input() height = '100%';
  @Input() disabled = false;
  @Input() readonly = false;
  @Input() isMobile = false;

  @Input() showFontType = true;
  @Input() showFontSize = true;
  @Input() showBarcode = true;
  @Input() showBlockQuote = true;
  @Input() showPageBreak = false;
  @Input() showClearFormatting = true;
  @Input() showJustifyText = true;
  @Input() showOrderedList = true;
  @Input() showDecreaseIndent = true;
  @Input() showIncreaseIndent = true;
  @Input() showImage = true;
  @Input() showTableOptions = true;
  @Input() showUndoAndRedo = false;

  @Input() substitutions: Substitution[] = [];

  @Input() isOlcTed = false;
  @Input() olcTedVariables: ITemplateVariable[] = [];
  @Input() olcTedConditionalContents: ITemplateConditionalContent[] = [];
  @Input() olcTedSnippets: Snippet[] = [];
  @Input() olcTedStyles: TemplateStyle[] = [];

  @Output() valueChange = new EventEmitter<string>();

  @ViewChild('kendoEditor', { static: true }) kendoEditor: EditorComponent;
  editorId = uniqueId('html-editor-');
  isFocused = false;

  @ViewChild(PerfectScrollbarDirective) scrollbarDirective: PerfectScrollbarDirective;

  supportedBarcodes = supportedBarcodesArray;
  fieldBarcodes: FieldDefinition;
  selectedBarcode = 'Pdf417';
  fieldBarcodeData: FieldDefinition;
  barcodeData = '';
  showBarcodeModal = false;
  barcodeModalInstance: NgxSmartModalComponent;

  substitutionsWithIcons: Substitution[] = [];
  fieldSubstitutions: FieldDefinition;
  substitutionsOptions: IFieldOptions[] = [];
  selectedSubstitution = '';

  supportedFonts: string[] = [];
  fieldFonts: FieldDefinition;
  fontType = '';
  defaultFontType = 'Serif';

  fieldFontSize: FieldDefinition;
  fontSizePx = '';

  selectedRows = 0;
  selectedColumns = 0;
  showTableSizePopup = false;

  fieldOlcVariables: FieldDefinition;
  olcVariablesHeader = this.translate.instant('admin-olc-templates.variables-header');
  selectedVariableValue = '';

  fieldOlcConditionalContents: FieldDefinition;
  olcConditionalContentsHeader = this.translate.instant('admin-olc-templates.conditional-contents-header');
  selectedConditionalContentValue = '';

  fieldOlcSnippets: FieldDefinition;
  olcSnippetsHeader = this.translate.instant('admin-olc-templates.snippets-header');
  selectedSnippetValue = '';

  fieldOlcBlockStyles: FieldDefinition;
  fieldOlcInlineStyles: FieldDefinition;

  olcBlockStyles: TemplateStyle[] = [];
  olcInlineStyles: TemplateStyle[] = [];

  insertOlcImageModalInstance: NgxSmartModalComponent;
  showOlcInsertImageModal = false;

  showViewSourceModal = false;
  viewSourceModalInstance: NgxSmartModalComponent;
  fieldViewSource: FieldDefinition;
  viewSourceValue = '';

  toolbarState: IToolbarState = null;

  editorInitialized$: Observable<boolean>;

  editorSchema: Schema;

  value = '';

  defaultTableWidth = '';
  stopAutoFontTypeAndFontSizeApplying = false;
  isBarCodeModalVisible = false;

  subscriptions = new Subscription();

  constructor(
    private userState: UserStateService,
    private ngxSmartModalService: NgxSmartModalService,
    private translate: TranslateService,
    private delayService: DelayService,
    private sendFaxService: SendFaxService,
    private elementRef: ElementRef
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    const inputSubstitutions = changes.substitutions?.currentValue;

    if (inputSubstitutions) this.createSubstitutionsField(inputSubstitutions);

    const olcStyles = changes.olcTedStyles?.currentValue;

    if (olcStyles) {
      this.olcBlockStyles = olcStyles.filter((s, i) => this.filterStyles(s, i, StyleType.Block));

      this.olcInlineStyles = olcStyles.filter((s, i) => this.filterStyles(s, i, StyleType.Inline));

      this.createOlcBlockStylesField();
      this.createOlcInlineStylesField();
    }

    const initialValue = changes.initialValue?.currentValue;
    const isFirstChange = changes.initialValue?.isFirstChange();

    if (initialValue && isFirstChange) {
      if (!this.isOlcTed) {
        this.value = initialValue;
      } else {
        mapImagesToBlobUrls(initialValue).then((mappedValue) => {
          this.value = showOrHidePageBreaks(mappedValue, true);
        });
      }
    }
  }

  ngOnInit() {
    this.createFields();

    this.editorSchema = createEditorSchema(
      this.isOlcTed,
      this.olcTedStyles,
      this.olcTedConditionalContents.map((c) => ({
        groupName: c.group,
        className: this.getConditionalContentClassName(c.group),
      }))
    );

    this.editorInitialized$ = this.createEditorInitialized$();

    this.editorInitialized$.subscribe(() => {
      this.wrapEditorContentInsidePerfectScrollbar();
      this.getDefaultTableWidth();
      this.updateToolbarStateWhenStateChanges();
      this.handleEditorEvents();
    });
  }

  ngAfterViewInit(): void {
    this.barcodeModalInstance = this.ngxSmartModalService.getModal(`barcodeModal-${this.editorId}`);
    this.subscriptions.add(this.barcodeModalInstance.onEscape.subscribe(() => this.closeBarcodeModal()));
    this.subscriptions.add(
      this.barcodeModalInstance.onCloseFinished.subscribe(() => {
        this.focusEditor();
        this.delayService.execute(() => (this.showBarcodeModal = false), 100);
      })
    );

    this.insertOlcImageModalInstance = this.ngxSmartModalService.get(`olcInsertImageModal-${this.editorId}`);
    this.subscriptions.add(this.insertOlcImageModalInstance.onEscape.subscribe(() => this.closeInsertOlcImageModal()));
    this.subscriptions.add(
      this.insertOlcImageModalInstance.onCloseFinished.subscribe(() => {
        this.focusEditor();
        this.delayService.execute(() => (this.showOlcInsertImageModal = false), 100);
      })
    );

    this.viewSourceModalInstance = this.ngxSmartModalService.getModal(`viewSourceModal-${this.editorId}`);
    this.subscriptions.add(this.viewSourceModalInstance.onEscape.subscribe(() => this.closeViewSourceModal()));
    this.subscriptions.add(
      this.viewSourceModalInstance.onCloseFinished.subscribe(() => {
        this.focusEditor();
        this.delayService.execute(() => (this.showViewSourceModal = false), 100);
      })
    );
  }

  handleEditorEvents = () => {
    this.subscriptions.add(
      fromEvent(this.elementRef.nativeElement.querySelector(`#${this.editorId}`), 'keydown').subscribe(
        this.handleKeydownEvent
      )
    );
  };

  handleKeydownEvent = (event: KeyboardEvent) => {
    const editableArea = this.elementRef.nativeElement.querySelector(`#${this.editorId} .editor`);
    if (event.key === Key.Delete && event.target === editableArea) this.handleDeleteForward();

    if (event.key === Key.Tab || event.key === Key.Escape) {
      this.hideTableSizeGrid();
    }

    if (event.key === Key.Tab) {
      this.handleTableCellsNavigation(event);
    }
  };

  handleDeleteForward = () => {
    const { view } = this.kendoEditor;
    const { state, dispatch } = view;
    const { $from, $to } = state.selection;
    if ($from.pos !== $to.pos) return;

    dispatch(state.tr.delete($from.pos, $from.pos + 1));
  };

  handleTableCellsNavigation = (event: KeyboardEvent) => {
    const isTableFocused = this.isFocused && cursorIsInsideTable(this.kendoEditor.view);
    if (!isTableFocused) return;

    event.preventDefault();
    event.stopPropagation();

    goToNextTableCell(
      this.kendoEditor.view,
      event.shiftKey ? NavigationDirection.Backward : NavigationDirection.Forward
    );
  };

  updateToolbarStateWhenStateChanges() {
    const editorState$ = this.kendoEditor.stateChange.pipe(
      map(() => this.kendoEditor?.view?.state),
      filter((state) => !!state),
      distinctUntilChanged((prev, current) => isEqual(prev, current))
    );

    const firstEditorState$ = editorState$.pipe(first());
    const comingEditorStates$ = editorState$.pipe(skip(1), debounceTime(75));

    this.subscriptions.add(
      concat(firstEditorState$, comingEditorStates$)
        .pipe(
          tap((state) => {
            this.setToolbarActionsState(state);
            this.scrollbarDirective.update();
            this.applyFontTypeAndFontSizeIfNotExisting();
          })
        )
        .subscribe()
    );
  }

  wrapEditorContentInsidePerfectScrollbar() {
    const editorElement = this.elementRef.nativeElement.querySelector(
      `#${this.editorId} .k-editor-content .ProseMirror`
    ) as HTMLElement;
    if (!editorElement) return;

    ['k-content', 'editor'].forEach((c) => editorElement.classList.add(c));

    $(editorElement).appendTo(`#${this.editorId} #editor-content`);
    $(`#${this.editorId} #editor-content`).appendTo(`#${this.editorId} .k-editor-content`);
  }

  getDefaultTableWidth() {
    const editorContent = this.elementRef.nativeElement.querySelector(`#${this.editorId} .k-content`) as HTMLElement;
    if (!editorContent) return;

    const editorContentComputedStyle = window.getComputedStyle(editorContent);
    const paddingStart = +editorContentComputedStyle.paddingInlineStart.replace('px', '');
    const paddingEnd = +editorContentComputedStyle.paddingInlineEnd.replace('px', '');

    this.defaultTableWidth = editorContent.clientWidth - paddingStart - paddingEnd + 'px';
  }

  applyFontTypeAndFontSizeIfNotExisting = () => {
    if (this.isOlcTed || this.stopAutoFontTypeAndFontSizeApplying) return;
    if (!this.toolbarState?.oneOrMoreFontFamily.selected) this.setFontType(this.fontType, false);
    if (!this.toolbarState?.oneOrMoreFontSize.selected) this.setFontSize(this.fontSizePx, false);
  };

  filterStyles = (s, i, type: StyleType) => {
    return (
      s.elementType === type ||
      (s.elementType === StyleType.None && this.olcTedStyles[i + 1]?.elementType === type) ||
      s.name === this.translate.instant('admin-olc-custom-styles.custom-styles-separator-title')
    );
  };

  createEditorInitialized$() {
    return interval(150).pipe(
      map(() => this.kendoEditor),
      filter((editor) => !!editor),
      map((editor: EditorComponent) => {
        try {
          editor.blur();
          return true;
        } catch (err) {
          return false;
        }
      }),
      filter((initialized: boolean) => initialized),
      take(1)
    );
  }

  setToolbarActionsState(state: EditorState) {
    this.toolbarState = getToolbarState(state, this.fontType, this.fontSizePx, this.olcTedStyles, this.isOlcTed);
  }

  createFields() {
    this.createBarcodeField();
    this.createBarcodeDataField();
    this.createFontsField();
    this.createFontSizesField();
    this.createOlcVariablesField();
    this.createOlcSnippetsField();
    this.createViewSourceField();
    this.createOlcConditionalContentsField();
  }

  createBarcodeField() {
    if (!this.showBarcode) return;

    const barcodesDataSource: IFieldOptions[] = [];

    this.supportedBarcodes.forEach((x) => {
      if (!this.userState.hasFeature(`BARCODE_${x.value.toUpperCase()}`)) return;
      barcodesDataSource.push(x);
    });

    this.fieldBarcodes = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translate.instant('TextEditor.Barcodes.Type'),
      placeholder: this.translate.instant('TextEditor.Barcodes.Type'),
      required: true,
      datasource: new FixedDataSource(barcodesDataSource, true),
    });
  }

  createBarcodeDataField() {
    if (!this.showBarcode) return;

    this.fieldBarcodeData = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('TextEditor.Barcodes.Data'),
      placeholder: this.translate.instant('TextEditor.Barcodes.Data'),
      required: true,
    });
  }

  createViewSourceField() {
    if (!this.isOlcTed) return;

    this.fieldViewSource = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: null,
      placeholder: this.placeholder,
      required: false,
      autosizeMinRows: 20,
      scrollHeight: '375px',
    });
  }

  createSubstitutionsField(inputSubstitutions: Substitution[]) {
    this.substitutionsWithIcons = inputSubstitutions.filter((x) => x.icon);

    this.substitutionsOptions = [];

    inputSubstitutions
      .filter((x) => !x.icon)
      .forEach((x) =>
        this.substitutionsOptions.push({ name: this.translate.instant(x.displayName), value: x.markerText })
      );

    this.substitutionsOptions.sort((x, y) => x.name.localeCompare(y.name));

    this.fieldSubstitutions = new FieldDefinition({
      type: MetaDataType.List,
      label: '',
      placeholder: '',
      required: false,
      datasource: new FixedDataSource(this.substitutionsOptions),
      stickyHeader: this.translate.instant('TextEditor.Substitutions'),
      fireChangeEventIfSameValue: true,
    });
  }

  createFontsField() {
    if (!this.showFontType && !this.isMobile) return;

    this.supportedFonts = defaultFontFamilies;

    if (this.userState.userProfile?.fonts)
      this.supportedFonts = [...this.supportedFonts, ...this.userState.userProfile.fonts];

    this.supportedFonts = this.supportedFonts.sort((a, b) => a.localeCompare(b));

    this.fontType = this.getDefaultFontType();

    const fontsDataSource: IFieldOptions[] = [];

    this.supportedFonts.forEach((font) => {
      const value = font !== 'Sans Serif' ? font : 'sans-serif';
      fontsDataSource.push({ name: font, value, style: "font-family:'" + value + "';", isInputStyled: true });
    });

    this.fieldFonts = new FieldDefinition({
      type: MetaDataType.List,
      label: '',
      placeholder: this.translate.instant('TextEditor.FontTypePlaceholder'),
      required: false,
      datasource: new FixedDataSource(fontsDataSource),
      defaultValue: this.fontType,
      fireChangeEventIfSameValue: true,
    });
  }

  createFontSizesField() {
    if (!this.showFontSize && !this.isMobile) return;

    this.fontSizePx = this.getDefaultFontSizePx();

    const fontSizeDataSource: IFieldOptions[] = FontSizes.supportedSizes.map((fontSize) => ({
      name: fontSize.key,
      value: fontSize.value,
      style: `font-size: ${fontSize.value};`,
    }));

    this.fieldFontSize = new FieldDefinition({
      type: MetaDataType.List,
      label: '',
      placeholder: this.translate.instant('TextEditor.FontSizePlaceholder'),
      required: false,
      datasource: new FixedDataSource(fontSizeDataSource),
      defaultValue: this.fontSizePx,
      fireChangeEventIfSameValue: true,
    });
  }

  getDefaultFontType = () => {
    const savedFontType = this.sendFaxService.getSettingDefaultValue(TEXTFONTTYPE);
    if (savedFontType && this.supportedFonts.indexOf(savedFontType) != -1) {
      return savedFontType;
    } else {
      return this.defaultFontType;
    }
  };

  getDefaultFontSizePx = (): string => {
    const savedLegacyFontSizeIndex = this.sendFaxService.getSettingDefaultValue(TEXTFONTSIZE);

    if (
      !Strings.isEmpty(savedLegacyFontSizeIndex) &&
      savedLegacyFontSizeIndex > 0 &&
      savedLegacyFontSizeIndex <= FontSizes.legacySizes.length
    ) {
      const legacyFontSize = FontSizes.legacySizes[savedLegacyFontSizeIndex - 1];

      const fontSize = FontSizes.legacyToModern(legacyFontSize);

      return fontSize.value;
    } else {
      return FontSizes.defaultSizePx;
    }
  };

  createOlcVariablesField() {
    if (!this.olcTedVariables.length) return;

    const variablesDataSource: IFieldOptions[] = [];

    this.olcTedVariables.forEach((v) => {
      variablesDataSource.push({ name: v.name, value: v.name });
    });

    this.fieldOlcVariables = new FieldDefinition({
      type: MetaDataType.List,
      required: false,
      datasource: new FixedDataSource(variablesDataSource),
      stickyHeader: this.olcVariablesHeader,
      fireChangeEventIfSameValue: true,
    });
  }

  createOlcConditionalContentsField() {
    if (!this.olcTedConditionalContents.length) return;

    const ConditionalContentsDataSource: IFieldOptions[] = [];

    this.olcTedConditionalContents.forEach((c) => {
      ConditionalContentsDataSource.push({ name: c.group, value: c.group });
    });

    this.fieldOlcConditionalContents = new FieldDefinition({
      type: MetaDataType.List,
      required: false,
      datasource: new FixedDataSource(ConditionalContentsDataSource),
      stickyHeader: this.olcConditionalContentsHeader,
      fireChangeEventIfSameValue: true,
    });
  }

  createOlcSnippetsField() {
    if (!this.olcTedSnippets.length) return;

    const snippetsDataSource: IFieldOptions[] = this.olcTedSnippets.map((s) => ({ name: s.name, value: s.id }));

    this.fieldOlcSnippets = new FieldDefinition({
      type: MetaDataType.List,
      required: false,
      datasource: new FixedDataSource(snippetsDataSource),
      stickyHeader: this.olcSnippetsHeader,
      fireChangeEventIfSameValue: true,
    });
  }

  createOlcBlockStylesField() {
    if (!this.olcBlockStyles.length) return;

    const stylesDataSource: IFieldOptions[] = this.olcBlockStyles.map((s) => {
      const isSeparator = s.elementType === StyleType.None;
      return { name: s.name, value: s.id, disabled: isSeparator, isSeparator };
    });

    this.fieldOlcBlockStyles = new FieldDefinition({
      type: MetaDataType.List,
      placeholder: this.translate.instant('TextEditor.OLCBlockStylesPlaceholder'),
      required: false,
      datasource: new FixedDataSource(stylesDataSource),
      fireChangeEventIfSameValue: true,
    });
  }

  createOlcInlineStylesField() {
    if (!this.olcInlineStyles.length) return;

    const stylesDataSource: IFieldOptions[] = this.olcInlineStyles.map((s) => {
      const isSeparator = s.elementType === StyleType.None;
      return { name: s.name, value: s.id, disabled: isSeparator, isSeparator };
    });

    this.fieldOlcInlineStyles = new FieldDefinition({
      type: MetaDataType.List,
      placeholder: this.translate.instant('TextEditor.OLCInlineStylesPlaceholder'),
      required: false,
      datasource: new FixedDataSource(stylesDataSource),
      fireChangeEventIfSameValue: true,
    });
  }

  setValue(newValue: string) {
    if (!this.isOlcTed) {
      const val = newValue ? newValue : defaultHTML;
      this.execute('setHTML', val, false);
      return;
    }

    mapImagesToBlobUrls(newValue).then((mappedValue) => {
      const val = mappedValue ? showOrHidePageBreaks(mappedValue, true) : defaultHTML;
      this.execute('setHTML', val, false);
    });
  }

  onValueChange(value: string) {
    this.value = value;
    let mappedValue = !this.isOlcTed ? this.value : showOrHidePageBreaks(mapImagesToPdfImages(this.value), false);
    mappedValue = this.removeOurTablesIds(mappedValue);
    this.valueChange.emit(this.hasHtmlValue() ? mappedValue : '');
  }

  hasHtmlValue = () => {
    return !isHtmlEmpty(this.value);
  };

  onFocus() {
    this.isFocused = true;
  }

  onBlur() {
    this.isFocused = false;
  }

  execute(command: EditorCommand, attrs = undefined, focusEditor = true) {
    if (!this.kendoEditor) return;

    if (command === 'deleteTable')
      throw new Error('deleteTable command should not be used as it has bugs, use this.deleteTable() method instead.');

    if (command === 'deleteColumn')
      throw new Error(
        'deleteColumn command should not be used as it has bugs, use this.deleteColumn() method instead.'
      );

    if (command === 'deleteRow')
      throw new Error('deleteRow command should not be used as it has bugs, use this.deleteRow() method instead.');

    if (command === 'addColumnBefore')
      throw new Error(
        'addColumnBefore command should not be used as it has bugs, use this.insertColumnLeft() method instead.'
      );

    if (command === 'addColumnAfter')
      throw new Error(
        'addColumnAfter command should not be used as it has bugs, use this.insertColumnRight() method instead.'
      );

    if (attrs) {
      this.kendoEditor.exec(command, attrs);
    } else {
      this.kendoEditor.exec(command);
    }

    if (focusEditor) this.focusEditor();
  }

  focusEditor() {
    this.delayService.execute(() => {
      this.kendoEditor.focus();
      this.isFocused = true;
    }, 25);
  }

  removeFormatting() {
    if (this.isOlcTed) {
      this.applySelectedBlockStyle(this.olcBlockStyles[0]);
      this.execute('cleanFormatting');
    } else {
      this.cleanFormattingExceptFontTypeAndFontSize();
    }
  }

  cleanFormattingExceptFontTypeAndFontSize() {
    if (this.toolbarState?.bold.selected) this.execute('bold');
    if (this.toolbarState?.italic.selected) this.execute('italic');
    if (this.toolbarState?.underline.selected) this.execute('underline');
    if (this.toolbarState?.strikethrough.selected) this.execute('strikethrough');
  }

  insertImageHandler(imageInputFile) {
    if (!this.isOlcTed) {
      imageInputFile.click();
      return;
    }

    this.openInsertOlcImageModal();
  }

  insertImage(event) {
    const selectedFile = event.target.files[0];
    const reader = new FileReader();

    reader.onload = (event) => {
      this.execute('insertImage', {
        src: event.target.result.toString(),
      });
    };

    reader.readAsDataURL(selectedFile);
    event.target.value = null;
  }

  openInsertOlcImageModal() {
    this.showOlcInsertImageModal = true;
    this.insertOlcImageModalInstance.open();
  }

  closeInsertOlcImageModal() {
    this.insertOlcImageModalInstance.close();
  }

  async insertOlcImage(mediaPreviewData: MediaPreviewData) {
    const imageSrc =
      mediaPreviewData.type !== MediaFileType.PDF
        ? mediaPreviewData.url
        : await extractFirstPageFromPdfAsImage(mediaPreviewData.url);

    const attrs =
      mediaPreviewData.type !== MediaFileType.PDF ? { src: imageSrc } : { src: imageSrc, pdfurl: mediaPreviewData.url };

    this.execute('insertImage', attrs);

    this.closeInsertOlcImageModal();
  }

  openBarcodeModal = (): void => {
    this.showBarcodeModal = true;
    this.isBarCodeModalVisible = true;
    this.barcodeModalInstance.open();
    this.barcodeData = '';

    this.selectedBarcode = 'Pdf417';
    const options = (this.fieldBarcodes.datasource as FixedDataSource).options;
    if (options?.length && options.findIndex((x) => x.value == this.selectedBarcode) == -1) {
      this.selectedBarcode = options[0].value;
    }
  };

  closeBarcodeModal = () => {
    this.isBarCodeModalVisible = false;
    this.barcodeModalInstance.close();
  };

  insertBarcode = (): void => {
    if (!this.isBarCodeModalVisible) {
      return;
    }
    if (!this.selectedBarcode) return;
    this.execute('insertText', { text: `[[barcode:${this.selectedBarcode}:${encodeURIComponent(this.barcodeData)}]]` });
    this.closeBarcodeModal();
  };

  insertSubstitutionMarkerText(text: string) {
    this.execute('insertText', { text });
  }

  onSelectSubstitution = (): void => {
    if (!this.selectedSubstitution) return;
    this.execute('insertText', { text: `%%${this.selectedSubstitution}%%` });
  };

  setFontType = (value: string, focusEditor = true, saveAppliedValue = true) => {
    if (!this.showFontType && !this.isMobile) return;

    this.execute('fontFamily', value, focusEditor);
    if (saveAppliedValue) this.fontType = value;
  };

  setFontSize = (value: string, focusEditor = true, saveAppliedValue = true): void => {
    if (!this.showFontSize && !this.isMobile) return;

    this.execute('fontSize', value, focusEditor);
    if (saveAppliedValue) this.fontSizePx = value;
  };

  showTableSizeGrid = (): void => {
    this.selectedRows = 0;
    this.selectedColumns = 0;
    this.showTableSizePopup = true;
  };

  hideTableSizeGrid = (): void => {
    this.showTableSizePopup = false;
  };

  onInsertTable = (rows: number, cols: number): void => {
    this.stopAutoFontTypeAndFontSizeApplying = true;

    this.cleanFontTypeAndFontSizeTemporarily();
    this.cleanFormattingExceptFontTypeAndFontSize();

    this.hideTableSizeGrid();
    this.buildAndInsertTable(rows, cols, this.defaultTableWidth);

    this.stopAutoFontTypeAndFontSizeApplying = false;
  };

  buildAndInsertTable(rows: number, cols: number, width: string) {
    const rowCellsHtml = createArrayFromNumber(cols).reduce((acc) => {
      acc += `<td><p></p></td>`;
      return acc;
    }, '');

    const rowsHtml = createArrayFromNumber(rows).reduce((acc) => {
      acc += `<tr>${rowCellsHtml}</tr>`;
      return acc;
    }, '');

    const isNestedTable = !this.toolbarState?.addRowAfter.disabled;

    const style = !isNestedTable ? ` style="width: ${width};"` : '';

    const tableId = uniqueId(this.editorId + '-table-');

    const tableHtml = `<table${style} id="${tableId}"><tbody>${rowsHtml}</tbody></table$>`;

    this.insertTable(tableHtml, tableId);
  }

  cleanFontTypeAndFontSizeTemporarily() {
    this.setFontType(null, false, false);
    this.setFontSize(null, false, false);
  }

  onMouseEnterTableSizeBlock = (rows: number, columns: number): void => {
    this.selectedRows = rows;
    this.selectedColumns = columns;
  };

  insertRowBelow = (): void => {
    this.execute('addRowAfter');
  };

  insertRowAbove() {
    this.execute('addRowBefore');
  }

  insertColumnLeft() {
    addColumnBefore(this.kendoEditor.view);
  }

  insertColumnRight() {
    addColumnAfter(this.kendoEditor.view);
  }

  deleteTable() {
    removeTable(this.kendoEditor.view);
  }

  deleteColumn() {
    removeColumn(this.kendoEditor);
  }

  deleteRow() {
    removeRow(this.kendoEditor);
  }

  onVariableChanged = (variableName: string) => {
    const variable = this.olcTedVariables.find((v) => v.name === variableName);

    if (!variable) return;

    this.insertVariable(variable);

    this.selectedVariableValue = '';
  };

  insertVariable(variable: ITemplateVariable) {
    if (!variable.name.trim() || !variable.content.trim()) return;

    const domParser = new DOMParser();
    const variableDomNode = domParser.parseFromString(variable.content, 'text/html');
    const variableElement = variableDomNode.querySelector(`[data-variable]`);
    if (!variableElement) return;

    const dataVariableValue = variableElement.getAttribute('data-variable');
    if (!dataVariableValue || !variableElement.innerHTML) return;

    const { isEmptyBlock, selectionStartsFromBeginning } = this.getSelectedBlockInformation();

    const variableHtml = `${
      isEmptyBlock || selectionStartsFromBeginning ? '&zwnj;' : ''
    }<span class="ol-variable" style="user-select: all;" data-variable="${dataVariableValue}" contenteditable="false">${
      variableElement.innerHTML
    }</span>`;

    this.insertHTML([{ html: variableHtml, type: HtmlPartType.SingleInline }]);
  }

  onConditionalContentChanged(groupName: string) {
    this.insertConditionalContent(groupName);
    this.selectedConditionalContentValue = '';
  }

  insertConditionalContent(groupName: string) {
    const { view } = this.kendoEditor;
    const { state, dispatch } = view;
    const { schema } = state;

    const attrs = {
      class: this.getConditionalContentClassName(groupName),
      style: 'user-select: all;',
      contenteditable: 'false',
    };

    const conditionalContentNodeSpec = schema.nodes[groupName];
    const conditionalContentTextNode = schema.text(groupName);
    const newConditionalContentNode = conditionalContentNodeSpec.createAndFill(attrs, conditionalContentTextNode);
    if (!newConditionalContentNode) return;
    insertNode(newConditionalContentNode)(state, (tr) => dispatch(tr.scrollIntoView()));
    this.focusEditor();
  }

  getConditionalContentClassName(groupName: string) {
    return groupName
      .replace(/[-_]/g, ' ')
      .split(' ')
      .filter((w) => !!w)
      .join('-')
      .toLowerCase();
  }

  onOlcSnippetsChanged(snippetId: string) {
    const snippet = this.olcTedSnippets.find((s) => s.id === snippetId);

    if (!snippet) return;

    mapImagesToBlobUrls(snippet.html).then((mappedValue) => {
      this.insertHTML([{ html: mappedValue, type: HtmlPartType.CompleteSnippet }]);
      this.selectedSnippetValue = '';
    });
  }

  insertHTML(htmlParts: IHtmlPart[], focusEditor = true) {
    const { view } = this.kendoEditor;
    const { state, dispatch } = view;
    const { schema } = state;

    const parser = new DOMParser();

    const nodes: { node: Node; type: HtmlPartType }[] = [];

    htmlParts.forEach((part) => {
      const domNode = parser.parseFromString(part.html, 'text/html');
      const proseDomParser = ProseDOMParser.fromSchema(schema);
      const proseDomNode = proseDomParser.parse(domNode);

      if (part.type === HtmlPartType.CompleteSnippet) {
        nodes.push({ node: proseDomNode, type: part.type });
      } else {
        let wrapperNode: Node;

        if (part.type === HtmlPartType.SingleInline) {
          wrapperNode = proseDomNode.content.firstChild;
        } else if (part.type === HtmlPartType.SingleBlock) {
          wrapperNode = proseDomNode;
        }

        const childCount = wrapperNode.content.childCount;

        for (let i = 0; i < childCount; i++) {
          nodes.push({ node: wrapperNode.content.child(i), type: part.type });
        }
      }
    });

    const tr = state.tr;

    nodes.forEach((n) => {
      if (n.type !== HtmlPartType.CompleteSnippet) {
        tr.replaceSelectionWith(n.node, true);
      } else {
        const { to, blockStartPosition, blockEndPosition, isEmptyBlock, selectionStartsFromBeginning } =
          this.getSelectedBlockInformation();

        if (isEmptyBlock) {
          tr.replaceRangeWith(blockStartPosition, blockEndPosition, n.node);
        } else if (selectionStartsFromBeginning) {
          tr.replaceRangeWith(blockStartPosition, to, n.node);
        } else {
          tr.replaceSelectionWith(n.node, true);
        }
      }
    });

    dispatch(tr.scrollIntoView());

    if (focusEditor) this.focusEditor();

    return true;
  }

  getSelectedBlockInformation() {
    const { $from, from, to } = this.kendoEditor.view.state.selection;
    const blockRange = $from.blockRange($from.doc.resolve(from));
    const blockStartPosition = blockRange && blockRange.start;
    const blockNode = $from.node($from.depth);

    return {
      blockNode,
      from,
      to,
      blockStartPosition,
      blockEndPosition: blockRange && $from.doc.resolve(blockStartPosition + 1).end(),
      isEmptyBlock: blockNode && blockNode.content.size === 0,
      selectionStartsFromBeginning: from - 1 === blockStartPosition,
    };
  }

  insertTable(tableHtml: string, tableId: string) {
    const { view } = this.kendoEditor;
    const { state, dispatch } = view;
    const { schema } = state;

    const parser = new DOMParser();

    const domNode = parser.parseFromString(tableHtml, 'text/html');
    const proseDomParser = ProseDOMParser.fromSchema(schema);
    const proseDomNode = proseDomParser.parse(domNode);

    const childCount = proseDomNode.content.childCount;

    const nodes: Node[] = [];

    for (let i = 0; i < childCount; i++) {
      nodes.push(proseDomNode.content.child(i));
    }

    const tr = state.tr;

    nodes.forEach((n) => {
      tr.replaceSelectionWith(n, true);
    });

    dispatch(tr.scrollIntoView());

    this.focusFirstTd(view, tableId);
  }

  focusFirstTd(view: EditorView, tableId: string) {
    const insertedTable = view.dom.querySelector(`#${tableId}`);
    if (!insertedTable) return;

    const firstTd = insertedTable.querySelector('td');
    if (!firstTd) return;

    const pos = view.posAtDOM(firstTd, 0);
    const $pos = view.state.doc.resolve(pos);

    const selection = Selection.near($pos);

    view.dispatch(view.state.tr.setSelection(selection));
    view.focus();
  }

  removeOurTablesIds = (text: string) => {
    const domParser = new DOMParser();
    const textDomNode = domParser.parseFromString(text, 'text/html');

    const tables: NodeListOf<HTMLTableElement> = textDomNode.querySelectorAll(`table[id^="${this.editorId}-table-"]`);

    tables.forEach((table) => {
      table.removeAttribute('id');
    });

    return textDomNode.body.innerHTML;
  };

  onOlcBlockStylesChanged(styleId: string) {
    const selectedStyle = this.olcBlockStyles.find((s) => s.id === styleId);
    this.applySelectedBlockStyle(selectedStyle);
  }

  applySelectedBlockStyle(selectedStyle: TemplateStyle) {
    const { state, dispatch } = this.kendoEditor.view;

    if (!selectedStyle || selectedStyle.elementType === StyleType.None) return;

    applyBlockStyleFormat(selectedStyle)(state, dispatch);

    this.focusEditor();
  }

  onOlcInlineStylesChanged(styleId: string) {
    const selectedStyle = this.olcInlineStyles.find((s) => s.id === styleId);
    this.applySelectedInlineStyle(selectedStyle);
  }

  applySelectedInlineStyle(selectedStyle: TemplateStyle) {
    const { state, dispatch } = this.kendoEditor.view;

    if (!selectedStyle || selectedStyle.elementType === StyleType.None) return;

    addInlineFormat(
      {
        mark: selectedStyle.element,
      },
      state.tr,
      {
        class: selectedStyle.classes?.trim() ? selectedStyle.classes.trim() : null,
        style: mapInlineStylesToString(selectedStyle.inlineStyles) || null,
      }
    )(state, dispatch);

    this.focusEditor();
  }

  applyAlignmentStyle(alignment: AlignmentType = null) {
    const { state, dispatch } = this.kendoEditor.view;

    applyBlockStyleFormat(null, alignment)(state, dispatch);

    this.focusEditor();
  }

  alignCenter() {
    this.applyAlignmentStyle('center');
  }

  alignLeft() {
    this.applyAlignmentStyle('left');
  }

  alignRight() {
    this.applyAlignmentStyle('right');
  }

  alignJustify() {
    this.applyAlignmentStyle('justify');
  }

  openViewSourceModal() {
    this.showViewSourceModal = true;
    this.viewSourceValue = this.hasHtmlValue() ? this.value : '';
    this.viewSourceModalInstance.open();
  }

  closeViewSourceModal = () => {
    this.viewSourceValue = '';
    this.viewSourceModalInstance.close();
  };

  updateEditorValue() {
    const newValue = this.viewSourceValue ? this.viewSourceValue : defaultHTML;
    this.execute('setHTML', newValue);
    this.closeViewSourceModal();
  }

  insertPageBreak() {
    const inserted = this.insertHTML(
      [
        {
          html: `<hr class="ol-page-break" style="border-top: 1px dashed gray;">`,
          type: HtmlPartType.SingleBlock,
        },
      ],
      false
    );

    if (!inserted) return;

    const cursorMoved = pressArrowDown(this.kendoEditor.view);
    if (!cursorMoved) return;

    this.focusEditor();
  }

  onScroll = (event): void => {
    const editor = this.elementRef.nativeElement.querySelector(`#${this.editorId} .editor`);
    if (!editor) return;

    if (event.target.scrollLeft + event.target.clientWidth > editor.clientWidth) {
      event.target.scrollLeft = editor.clientWidth - event.target.clientWidth;
    }

    if (event.target.scrollTop + event.target.clientHeight > editor.clientHeight) {
      event.target.scrollTop = editor.clientHeight - event.target.clientHeight;
    }
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
