import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Subject } from 'rxjs';
import { WorkflowFolder } from '../../../blocks/models/workflow-folder';
import { CapturedDocument } from '../capture-models';
import { SelectedItem, SelectedItemType } from '../capture-models/selected-item';

@Injectable({
  providedIn: 'root',
})
export class SelectedItemsService {
  private _selectedItems: Array<SelectedItem> = [];

  private _selectedItemsSubject = new Subject<void>();
  onChangeSelectedItems = this._selectedItemsSubject.asObservable();

  constructor(private translate: TranslateService) {}

  changedSelectedItems() {
    this._selectedItemsSubject.next();
  }

  selectTreeFolder(folder: WorkflowFolder, isCtrlKey: boolean): void {
    const selectedItem = SelectedItem.CreateFolderSelectedItem(folder);

    if (!isCtrlKey) {
      this.selectSingleTreeItem(selectedItem);
      return;
    }

    if (this.isAnyAncestorSelectedForFolder(folder)) return;

    this.removeFolderSelectedChildren(folder);

    this.addOrRemoveSelectedItem(selectedItem);
  }

  selectTreeDocument(
    selectedDocument: CapturedDocument,
    parentFolder: WorkflowFolder,
    pagesCount: number,
    isCtrlKey: boolean
  ): void {
    const selectedItem = SelectedItem.CreateDocumentSelectedItem(selectedDocument, pagesCount);

    if (!isCtrlKey) {
      this.selectSingleTreeItem(selectedItem);
      return;
    }

    if (this.isAnyAncestorSelectedForDocument(parentFolder)) return;

    this.addOrRemoveSelectedItem(selectedItem);
  }

  private selectSingleTreeItem(selectedItem: SelectedItem): void {
    this._selectedItems = [selectedItem];
    this._selectedItemsSubject.next();
  }

  private addOrRemoveSelectedItem(selectedItem: SelectedItem): void {
    if (this.isItemSelectedBefore(selectedItem.id)) {
      this._selectedItems = this._selectedItems.filter((i) => i.id !== selectedItem.id);
      this._selectedItemsSubject.next();
      return;
    }

    this._selectedItems.push(selectedItem);
    this._selectedItemsSubject.next();
  }

  private isItemSelectedBefore(selectedItemId: string) {
    return this._selectedItems.some((i) => i.id === selectedItemId);
  }

  private removeFolderSelectedChildren(selectedFolder: WorkflowFolder): void {
    const parentsIds = [selectedFolder.id, ...this.getAllChildrenFolderIds(selectedFolder.folders)];
    this._selectedItems = this._selectedItems.filter((i) => !parentsIds.includes(i.parentId));
  }

  private getAllChildrenFolderIds(folders: WorkflowFolder[]): string[] {
    let ids: string[] = [];
    if (!folders?.length) return ids;

    folders.forEach((folder) => {
      ids.push(folder.id);
      if (!folder.folders?.length) return;
      ids = ids.concat(this.getAllChildrenFolderIds(folder.folders));
    });

    return ids;
  }

  getSelectedItems = (): SelectedItem[] => this._selectedItems;

  clearSelectedItems() {
    this._selectedItems = [];
    this._selectedItemsSubject.next();
  }

  getSelectedItemsCountText(): string {
    let foldersCount = 0;
    let documentsCount = 0;
    let pagesCount = 0;

    let countText = '';

    const selectedItems = this.getSelectedItems();

    selectedItems.forEach((item) => {
      if (item.type === SelectedItemType.Folder) foldersCount++;

      if (item.type === SelectedItemType.Document) {
        documentsCount++;
        pagesCount += item.pagesCount;
      }
    });

    if (foldersCount > 0) {
      countText += `${foldersCount} ${this.translate.instant('Document_Capture.folders')}`;
    }

    if (documentsCount) {
      if (foldersCount > 0) countText += ', ';
      countText += `${documentsCount} ${this.translate.instant(
        'Document_Capture.documents'
      )},  ${pagesCount} ${this.translate.instant('Document_Capture.pages')}`;
    }

    if (foldersCount || documentsCount) countText += ` ${this.translate.instant('Document_Capture.selected')}`;

    return countText;
  }

  isInDifferentWorkflowStep(selectedItemWorkflowStepId: string) {
    return this._selectedItems.some((i) => i.workflowStepId !== selectedItemWorkflowStepId);
  }

  isParentSelected = (itemParentId: string): boolean => this._selectedItems.some((i) => i.id === itemParentId);

  isAnyAncestorSelectedForFolder = (folder: WorkflowFolder): boolean => {
    if (!folder.parentWorkflowFolder) return false;
    if (this.isParentSelected(folder.parentID)) return true;
    return this.isAnyAncestorSelectedForFolder(folder.parentWorkflowFolder);
  };

  isAnyAncestorSelectedForDocument(parentFolder: WorkflowFolder): boolean {
    return this.isParentSelected(parentFolder.id) || this.isAnyAncestorSelectedForFolder(parentFolder);
  }

  isItemSelected = (id: string, workflowStepId: string) =>
    this._selectedItems.some((n) => n.id === id && n.workflowStepId === workflowStepId);

  isOneItemSelected = (): boolean => this._selectedItems.length === 1;

  isOneDocumentSelected = (): boolean =>
    this.isOneItemSelected() && this._selectedItems[0].type === SelectedItemType.Document;

  isOneFolderSelected = (): boolean =>
    this.isOneItemSelected() && this._selectedItems[0].type === SelectedItemType.Folder;

  hasItemsSelected = (): boolean => this._selectedItems.length >= 1;

  areMultipleItemsSelected = (): boolean => this._selectedItems.length > 1;

  get selectedItemsCount(): number {
    return this._selectedItems.length;
  }
}
