import { IFolderItem, FolderItem } from './folder-item';
import { IDocument } from './document';
import { WorkItem } from './work-item';

export interface IWorkflowFolder {
  id: string;
  parentID: string;
  workflowStepId: string;
  name: string;
  itemCount: number;
  folders: Array<IWorkflowFolder>;
  items: Array<IFolderItem>;

  findFolder(id: string): WorkflowFolder;
  findDocument(id: string): DocumentSearchResult;
}

export class WorkflowFolder {
  expanded: boolean = false;

  constructor(
    public id: string,
    public parentID: string,
    public parentWorkflowFolder: WorkflowFolder,
    public workflowStepId: string,
    public name: string,
    public itemCount: number,
    public folders: Array<WorkflowFolder>,
    public items: Array<FolderItem>
  ) {}

  folderHasItems = (): boolean => {
    if (this.itemCount > 0) return true;

    const subFolders = this.folders;
    if (!subFolders) return false;

    for (const subfolder of subFolders) {
      if (subfolder.folderHasItems()) return true;
    }

    return false;
  };

  findFolder(id: string): WorkflowFolder {
    if (this.id === id) return this;

    for (let f of this.folders) {
      const foundFolder = f.findFolder(id);
      if (foundFolder) return foundFolder;
    }

    return null;
  }

  findDocument(documentId: string): DocumentSearchResult {
    if (this.items) {
      for (const item of this.items) {
        const foundDocument = item.documents.find((d) => d.id === documentId);
        if (foundDocument) return new DocumentSearchResult(foundDocument, item.workItem);
      }
    }

    for (const f of this.folders) {
      const result = f.findDocument(documentId);
      if (result) return result;
    }

    return null;
  }

  updateWorkItem(workItem: WorkItem): void {
    if (this.items) {
      let foundDocument= this.items.find((item) => item.workItem.id == workItem.id);
      if (foundDocument) foundDocument.workItem = workItem;
    }
  }
}

export class DocumentSearchResult {
  constructor(public document: IDocument, public workItem: WorkItem) {}
}
