enum Level {
  Error = 0,
  Enter = 1 << 0,
  Exit = 1 << 1,
  Information = 1 << 2,
  Vars = 1 << 3,
  Verbose = 1 << 4,
  Warning = 1 << 5,

  All = 255,
}

export class Log {
  static enter(method: string, ...params: any[]): void {
    if (!this.ShouldLog(Level.Enter)) return;

    this.log(Level.Enter, `${method}(${this.varsToString(params)})`);
  }

  static exit(method: string, ...params: any[]): void {
    if (!this.ShouldLog(Level.Exit)) return;

    if (params.length) {
      this.log(Level.Exit, `${method} => ${this.varsToString(params)}`);
    } else {
      this.log(Level.Exit, `${method} => void`);
    }
  }

  static var(...vars: any[]): void {
    if (!this.ShouldLog(Level.Vars)) return;

    this.log(Level.Vars, this.varsToString(vars));
  }

  static info(message: string): void {
    if (!this.ShouldLog(Level.Information)) return;

    this.log(Level.Information, message);
  }

  static warn(message: string): void {
    if (!this.ShouldLog(Level.Warning)) return;

    this.log(Level.Warning, message);
  }

  static verbose(message: string): void {
    if (!this.ShouldLog(Level.Verbose)) return;

    this.log(Level.Verbose, message);
  }

  static error(message: string, err: Error): void {
    this.log(Level.Error, `${message}\n ${err.toString()}\n ${err.stack}`);
  }

  private static log(level: Level, message: string): void {
    let type = '';

    if (level == Level.Error) type = 'ERR: ';
    else if (level == Level.Information) type = 'INFO: ';
    else if (level == Level.Vars) type = 'VAR: ';
    else if (level == Level.Verbose) type = 'VERBOSE: ';
    else if (level == Level.Enter) type = 'ENTER: ';
    else if (level == Level.Exit) type = 'EXIT: ';
    else if (level == Level.Warning) type = 'WARN: ';

    const timestamp = new Date().toISOString();

    if (level == Level.Error) {
      console.error(`[${timestamp}] ${message}`);
    } else if (level == Level.Warning) {
      console.warn(`[${timestamp}] ${message}`);
    } else if (level == Level.Verbose) {
      console.debug(`[${timestamp}] ${message}`);
    } else if (level == Level.Information) {
      console.info(`[${timestamp}] ${message}`);
    } else {
      console.log(`[${timestamp}] ${type}${message}`);
    }
  }

  private static varsToString(params: any[]): string {
    let message = '';

    params.forEach((p) => {
      if (message.length > 0) message += ', ';
      if (p instanceof String || typeof p === 'string') {
        message += `"${p}"`;
      } else {
        message += JSON.stringify(p);
      }
    });

    return message;
  }

  private static ShouldLog(level: Level): boolean {
    return (this.level & level) != 0;
  }

  private static level = Level.All;
}
