import { MobileActionData } from './mobile-action-data';

export interface IImanageItem {
  id: string;
  name: string;
  database: string;
  parentId: string;
}

export class ImanageItem implements IImanageItem {
  id: string;
  name: string;
  database: string;
  parentId: string;

  constructor(initializer: IImanageItem) {
    if (!initializer) throw new Error('Invalid ImanageItem Initializer');

    this.id = initializer.id;
    this.name = initializer.name;
    this.database = initializer.database;
    this.parentId = initializer.parentId;
  }
}

export class IManageImportDocumentRequest {
  constructor(public document: ImanageItem, public actionData: MobileActionData) {}
}

