import { Variables } from './deployments';

export enum ComponentType {
  Website = 0,
  Service = 1,
  Tool = 2,
  ScheduledTask = 3,
  Database = 4,
  External = 5,
}

export interface IManifest {
  path: string;
  fileSpec: string;
  recursive: boolean;
}

export interface IComponent {
  id: string;
  name: string;
  componentType: ComponentType;
  manifest: IManifest[];
  nextReleaseVersion: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  variables: Variables;
}

export class Component implements IComponent {
  id: string;
  name: string;
  componentType: ComponentType;
  manifest: IManifest[] = [];
  nextReleaseVersion: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  variables: Variables;

  constructor(initializer: IComponent) {
    this.id = initializer.id;
    this.name = initializer.name;
    this.componentType = initializer.componentType;
    this.manifest = initializer.manifest;
    this.nextReleaseVersion = initializer.nextReleaseVersion;
    this.dateCreatedUTC = initializer.dateCreatedUTC;
    this.dateModifiedUTC = initializer.dateModifiedUTC;
    this.variables = initializer && initializer.variables ? initializer.variables : new Variables();
  }

  serializable = (): IComponent => {
    return {
      id: this.id,
      name: this.name,
      componentType: this.componentType,
      manifest: this.manifest,
      nextReleaseVersion: this.nextReleaseVersion,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      variables: this.variables,
    };
  };
}

export class Manifest implements IManifest {
  path: string;
  fileSpec: string;
  recursive: boolean;

  constructor(initializer: IManifest) {
    this.path = initializer.path;
    this.fileSpec = initializer.fileSpec;
    this.recursive = initializer.recursive;
  }

  serializable = (): IManifest => {
    return {
      path: this.path,
      fileSpec: this.fileSpec,
      recursive: this.recursive,
    };
  };
}
