export interface ILockStatus {
  locked: boolean;
  lockedByUserId: string;
  lockedByUserName: string;
  lockedByUserEmail: string;
  id: string;
  dateLockedUTC: string;
}

export class LockStatus {
  private static leaseExpirationMilliseconds = 1000 * 5 * 60;

  locked: boolean;

  lockedByUserId: string;
  lockedByUserName: string;
  lockedByUserEmail: string;

  id: string;
  dateLockedLocalTime: Date;

  public constructor(ls: ILockStatus = null) {
    if (ls) {
      this.locked = ls.locked;
      this.lockedByUserId = ls.lockedByUserId;
      this.lockedByUserName = ls.lockedByUserName;
      this.lockedByUserEmail = ls.lockedByUserEmail;
      this.id = ls.id;
      this.dateLockedLocalTime = new Date(ls.dateLockedUTC);
    }
  }

  public expired = (): boolean => {
    const localLocked = this.dateLockedLocalTime.getTime();
    const localNow = Date.now();

    return localNow - localLocked > LockStatus.leaseExpirationMilliseconds;
  };
}

export enum LockAction {
  Lock = 0,
  Unlock = 1,
}
