import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { ToastrService } from 'ngx-toastr';
import { TranslateService } from '@ngx-translate/core';
import { UserAppPassword } from '../../InterFAX/Models/admin';
import { InterFAXService } from '../../services/interfax.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { ClipboardService, FieldDefinition, MetaDataType } from 'shared-code-lib';
import { SharedDataService } from '../../services/shared-data.service';

@Component({
  selector: 'app-interfax-app-password-modal',
  templateUrl: './interfax-app-password-modal.component.html',
  styleUrls: ['./interfax-app-password-modal.component.scss'],
})
export class InterfaxAppPasswordModalComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  id: string;
  fieldDescription: FieldDefinition;
  title: string;
  appPassword: UserAppPassword;
  errors = new Array<string>();

  constructor(
    private toastr: ToastrService,
    private translateService: TranslateService,
    private spinnerService: SpinnerStateService,
    private interfaxService: InterFAXService,
    private shareDataService: SharedDataService
  ) { }

  ngOnInit(): void {
    this.errors = [];

    this.fieldDescription = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('app-password.description'),
      placeholder: this.translateService.instant('app-password.description-placeholder'),
      required: true,
    });

    this.title = this.translateService.instant('app-password.title-new');
    this.appPassword = new UserAppPassword();
  }

  onCopyToClipboard = (): void => {
    ClipboardService.copyToClipboard(this.appPassword.password);
    this.toastr.info(this.translateService.instant('general.copied-to-clipboard'));
  };

  create = (): void => {
    if (!this.appPassword?.description?.trim()) return;

    this.errors = [];
    this.spinnerService.show(this.translateService.instant('Common.Saving'), document.documentElement);
    this.interfaxService.createAppPassword(this.appPassword, this.created, this.creationFailed);
  };

  created = (appPassword: UserAppPassword): void => {
    this.spinnerService.hide();
    this.title = this.translateService.instant('app-password.title-created');
    this.appPassword = appPassword;
    this.shareDataService.actionHandler.reload.emit(true);
  };

  creationFailed = (err: any): void => {
    this.spinnerService.hide();
    this.errors = err;
  };

  close = (): void => {
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.spinnerService.hide();
    this.closeModal.emit();
  };
}
