import { Component, ElementRef, EventEmitter, OnDestroy, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import { CoverPage, FieldDefinition, ISearchItems, MetaDataType, Tab } from 'shared-code-lib';
import { FaxUserStatus, Group, IFaxUserSelect } from '../../InterFAX/Models/admin';
import { InterFAXService } from '../../services/interfax.service';
import { ApiResults } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

class GroupMember {
  name: string;

  constructor(name: string) {
    this.name = name;
  }
}

@Component({
  selector: 'app-interfax-group-modal',
  templateUrl: './interfax-group-modal.component.html',
  styleUrls: ['./interfax-group-modal.component.scss'],
})
export class InterfaxGroupModalComponent implements OnInit, OnDestroy, ISearchItems {
  @ViewChild('spinnerElement', { static: true }) spinnerElement: ElementRef;
  @ViewChild(PerfectScrollbarDirective, { static: true })
  scrollbar?: PerfectScrollbarDirective;

  @Output() closeModal = new EventEmitter();

  id: string;
  activeTab = 'general';
  tabs = new Array<Tab>();

  fieldName: FieldDefinition;

  title: string;
  group: Group = new Group();

  usersAreLoaded = false;
  errors = new Array<string>();

  availableCoverPages: Array<CoverPage> = [];
  currentCoverPages: Array<CoverPage> = [];
  coverPagesLoaded: boolean;

  available: Array<GroupMember> = [];
  current: Array<GroupMember> = [];
  editMode: boolean = false;

  subscriptions = new Subscription();

  constructor(
    private toastr: ToastrService,
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    public interfaxService: InterFAXService
  ) {}

  ngOnInit(): void {
    this.createTabs();
    this.createFields();

    this.id = this.sharedDataService.extraParameters ? this.sharedDataService.extraParameters.id : '';

    this.spinnerService.show(this.translateService.instant('Common.Loading'), this.spinnerElement.nativeElement);

    if (this.id) {
      this.editMode = true;
      this.title = this.translateService.instant('group.title-existing');
      this.subscriptions.add(this.interfaxService.getGroup(this.id, this.loaded, this.loadFailed));
    } else {
      this.title = this.translateService.instant('group.title-new');
      this.available = [];
      this.current = [];
      this.group = new Group();
      this.currentCoverPages = [];

      this.load();
    }
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  findMatches(searchTerm: string, completed: (items: Array<any>) => void): void {
    this.subscriptions.add(
      this.interfaxService.getUsersSelect(
        (users: Array<IFaxUserSelect>) => {
          completed(users.map((u) => new GroupMember(u.userId)));
        },
        () => {},
        searchTerm,
        FaxUserStatus.Open
      )
    );
  }

  currentChanged = (current: Array<GroupMember>): void => {
    this.group.members = current.map((m) => m.name);
    this.current = current;
  };

  currentCoverPagesChanged = (current: Array<CoverPage>): void => {
    this.currentCoverPages = current;
  };

  loaded = (g: Group): void => {
    this.group = g;

    this.load();
  };

  loadFailed = (err: Error): void => {
    this.spinnerService.hide();
  };

  load = (): void => {
    this.current = this.group.members.map((u) => new GroupMember(u));
    this.usersAreLoaded = true;
    this.spinnerService.hide(this.translateService.instant('Common.Loading'));
  };

  loadCoverPages = (): void => {
    if (this.coverPagesLoaded) return;

    this.spinnerService.show(
      this.translateService.instant('group.loading-cover-pages'),
      this.spinnerElement.nativeElement
    );
    this.subscriptions.add(
      this.interfaxService.getAccountCoverpages(this.onCoverPagesLoaded, this.onCoverPagesLoadFailed)
    );
  };

  onCoverPagesLoaded = (coverPages: Array<CoverPage>): void => {
    this.coverPagesLoaded = true;

    this.availableCoverPages = coverPages.map((a: any) => {
      a.icon = 'fa-file-contract fa-fw fa-lg fas';
      return a;
    });

    this.currentCoverPages = this.availableCoverPages
      .filter((cp) => this.group.coverPages.find((id) => cp.id == id) != null)
      .sort((x, y) => x.name.localeCompare(y.name));

    this.spinnerService.hide(this.translateService.instant('group.loading-cover-pages'));
  };

  onCoverPagesLoadFailed = (err: any): void => {
    this.spinnerService.hide();
    this.toastr.error(this.translateService.instant('group.load-cover-pages-failed'));
  };

  save = (): void => {
    if (!this.usersAreLoaded || !this.group.name.trim()) return;

    this.spinnerService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);
    this.group.coverPages = this.currentCoverPages.map((c) => c.id);
    this.subscriptions.add(this.interfaxService.setGroup(this.group, this.saved, this.saveFailed));
  };

  saved = (r: ApiResults): void => {
    this.spinnerService.hide();

    if (r.success) {
      this.toastr.success(this.translateService.instant(this.editMode ? 'group.save-success' : 'group.create-success'));
      this.close();
      this.sharedDataService.actionHandler.reload.emit(true);
    } else {
      this.errors = r.errors;
    }

    this.scrollbar.scrollToTop();
  };

  saveFailed = (err: Error): void => {
    this.spinnerService.hide();
    this.errors.push(err.message);
    this.scrollbar.scrollToTop(0, 300);
  };

  close = (): void => {
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  createFields = (): void => {
    this.fieldName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('group.name'),
      placeholder: this.translateService.instant('group.name-placeholder'),
      required: true,
    });
  };

  createTabs = (): void => {
    this.tabs.push(new Tab('members', this.translateService.instant('group.members')));
    this.tabs.push(new Tab('cover-pages', this.translateService.instant('group.cover-pages')));
  };

  activateTab = (tab: string): void => {
    this.activeTab = tab;
    if (this.activeTab === 'cover-pages') this.loadCoverPages();
  };
}
