import { Component, Input, OnInit } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { FieldDefinition, MetaDataType } from 'shared-code-lib';
import { InboundDocument } from '../../../InterFAX/Models/inbound';

@Component({
  selector: 'app-document-properties-general',
  templateUrl: './document-properties-general.component.html',
  styleUrls: ['./document-properties-general.component.scss'],
})
export class DocumentPropertiesGeneralComponent implements OnInit {
  @Input() document: InboundDocument;

  fieldName: FieldDefinition;
  fieldReference: FieldDefinition;

  constructor(private translateService: TranslateService) {}

  ngOnInit(): void {
    this.createFields();
  }

  createFields = (): void => {
    this.fieldName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('interfax-queue.document-name'),
      placeholder: '',
      required: false,
    });

    this.fieldReference = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('interfax-queue.document-reference'),
      placeholder: '',
      required: false,
    });
  };
}
