import { Component, OnDestroy, OnInit } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgxExtendedPdfViewerService } from 'ngx-extended-pdf-viewer';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import { DelayService } from '../../../../../../../Bamba.Shared/src/utils/delay.service';
import { PrintPdfFileService } from '../../services/print-pdf-file.service';

@Component({
  selector: 'app-print-pdf-file',
  templateUrl: './print-pdf-file.component.html',
  styleUrls: ['./print-pdf-file.component.scss'],
})
export class PrintPdfFileComponent implements OnInit, OnDestroy {
  pdfUrl = null;

  subscriptions = new Subscription();

  constructor(
    private printPdfFileService: PrintPdfFileService,
    private ngxExtendedPdfViewerService: NgxExtendedPdfViewerService,
    private toastr: ToastrService,
    private translate: TranslateService,
    private delayService: DelayService
  ) {}

  ngOnInit() {
    this.subscriptions.add(this.printPdfFileService.pdfUrl$.subscribe((pdfUrl) => (this.pdfUrl = pdfUrl)));
  }

  onPagesLoaded() {
    this.delayService.execute(() => {
      this.ngxExtendedPdfViewerService.print();
    }, 500);
  }

  onPdfLoadingFailed() {
    this.toastr.error(this.translate.instant('print-pdf-file.failed-to-print-pdf-file'));
    this.printPdfFileService.finishPrintFile();
  }

  onAfterPrint() {
    this.printPdfFileService.finishPrintFile();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
