import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { parseDate } from '@progress/kendo-angular-intl';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { BehaviorSubject, Subject } from 'rxjs';
import {
  CoverPageBodyType,
  CoverPageType,
  DelayService,
  FaxCSID,
  FaxForm,
  FeedbackEmail,
  NumberOfAttampts,
  PageOrientation,
  PageSize,
  PrintToService,
  RenderingOptimization,
  Resolution,
  SendAfter,
  SendAfterDateTime,
  UserPreferencesService,
} from 'shared-code-lib';
import { Email } from '../core/email';
import { ContentPostService } from './content-post.service';
import { ErrorsService } from './errors.service';
import { Control } from './models';
import { SpinnerStateService } from './spinner-state.service';
import { UserStateService } from './user-state.service';

@Injectable({
  providedIn: 'root',
})
export class SendFaxService {
  readonly preferencePrefix = 'InterFAX-SendFax-';

  private faxUserProfileLoadedSubject = new BehaviorSubject(false);
  faxUserProfileLoaded$ = this.faxUserProfileLoadedSubject.asObservable();

  private detailFormSubject = new BehaviorSubject(new FaxForm({}));
  detailForm$ = this.detailFormSubject.asObservable();

  private sendFormDiscardedSubject = new Subject<void>();
  sendFormDiscarded$ = this.sendFormDiscardedSubject.asObservable();

  constructor(
    private translateService: TranslateService,
    private spinnerState: SpinnerStateService,
    private userState: UserStateService,
    private errorsService: ErrorsService,
    private contentPost: ContentPostService,
    private userPreferencesService: UserPreferencesService,
    private toastr: ToastrService,
    private ngxSmartModalService: NgxSmartModalService,
    private printToService: PrintToService,
    private delay: DelayService
  ) {}

  private getDetailForm() {
    return this.detailFormSubject.getValue();
  }

  setDetailForm(detailForm: FaxForm) {
    this.detailFormSubject.next(detailForm);
  }

  loadSendFaxProfile = (
    spinnerContainer: HTMLElement,
    successCallback: () => void,
    failureCallback: (error: any) => void
  ): void => {
    this.spinnerState.show(this.translateService.instant('User.LoadingProfileDetails'), spinnerContainer);

    this.userState.loadSendFaxProfile(successCallback, failureCallback);
  };

  userProfileChangedHandler = () => {
    const faxUserProfileLoaded = this.isFaxUserProfileLoaded();
    this.faxUserProfileLoadedSubject.next(faxUserProfileLoaded);
    if (!faxUserProfileLoaded) return;

    this.loadFaxPageSettingsValues();
  };

  createSendFaxControl(
    loaderContainerSelector: string,
    invalidFeedbackEmailHandler?: () => void,
    optionsTabPageHandler?: () => void,
    updateScrollbarHandler?: () => void
  ) {
    return new Control(
      () =>
        this.sendFax(
          loaderContainerSelector,
          invalidFeedbackEmailHandler,
          optionsTabPageHandler,
          updateScrollbarHandler
        ),
      this.translateService.instant('SendFax.HeadText'),
      'btn btn-primary',
      '',
      this.translateService.instant('SendFax.HeadText'),
      'btn',
      true
    );
  }

  private sendFax = (
    loaderContainerSelector: string,
    invalidFeedbackEmailHandler?: () => void,
    optionsTabPageHandler?: () => void,
    updateScrollbarHandler?: () => void
  ) => {
    if (this.getDetailForm().faxPageSettings.saveAsDefault) this.saveSettingsAsDefault();

    const spinnerElement = document.querySelector(loaderContainerSelector) as HTMLElement;

    const { feedbackEmail } = this.getDetailForm().faxPageSettings;
    if (feedbackEmail && !Email.isValid(feedbackEmail)) {
      invalidFeedbackEmailHandler?.();

      this.errorsService.showErrorsModal(
        [this.translateService.instant('SendFax-Attributes-Form.EmailValidationError')],
        this.translateService.instant('Common.ValidationError')
      );
    } else {
      this.contentPost.sendFax(
        spinnerElement,
        this.getDetailForm(),
        (result) => this.sendFaxSucceeded(result, optionsTabPageHandler, updateScrollbarHandler),
        this.sendFaxFailed
      );
    }
  };

  private sendFaxSucceeded = (result: any, optionsTabPageHandler?: () => void, updateScrollbarHandler?: () => void) => {
    this.spinnerState.hide();

    if (result.succeeded) {
      this.getDetailForm().clear();
      this.detailFormSubject.next(this.getDetailForm());

      this.loadFaxPageSettingsValues();

      optionsTabPageHandler?.();

      this.ngxSmartModalService.getModal('sendFaxSuccessModal').open();
      this.delay.execute(() => document.getElementById('modal-btn-close').focus(), 50);

      updateScrollbarHandler?.();
    } else {
      if (result.errors) {
        this.errorsService.showErrorsModal(result.errors, this.translateService.instant('SendFax.SubmitFailed'));
      } else {
        this.sendFaxFailed();
      }
    }
  };

  loadFaxPageSettingsValues() {
    const detailForm = this.getDetailForm();

    detailForm.faxPageSettings.faxCSID = this.getSettingDefaultValue(FaxCSID);
    detailForm.faxPageSettings.numberOfAttempts = this.getSettingDefaultValue(NumberOfAttampts);
    detailForm.faxPageSettings.pageOrientation = this.getSettingDefaultValue(PageOrientation);
    detailForm.faxPageSettings.pageSize = this.getSettingDefaultValue(PageSize);
    detailForm.faxPageSettings.renderingOptimization = this.getSettingDefaultValue(RenderingOptimization);
    detailForm.faxPageSettings.resolution = this.getSettingDefaultValue(Resolution);
    detailForm.faxPageSettings.feedbackEmail = this.getSettingDefaultValue(FeedbackEmail);
    detailForm.faxPageSettings.sendAfterDateTime = parseDate(this.getSettingDefaultValue(SendAfterDateTime));
    detailForm.faxPageSettings.sendAfter = this.getSettingDefaultValue(SendAfter);

    this.setDetailForm(detailForm);
  }

  getSettingDefaultValue(specificationItemName: string): any {
    const preferenceValue = this.userPreferencesService.getPreference(
      `${this.preferencePrefix}${specificationItemName}`
    );
    if (preferenceValue != null) return preferenceValue;

    if (!this.isFaxUserProfileLoaded()) return '';

    const specificationItem = this.userState.userProfile.fax.advancePageSetting?.find(
      (item) => item.name === specificationItemName
    );
    if (!specificationItem) return '';

    return specificationItem['value'];
  }

  private sendFaxFailed = () => {
    this.spinnerState.hide();
    this.toastr.error(this.translateService.instant('SendFax.SubmitFailed'));
  };

  createDiscardControl = (optionsTabPageHandler?: () => void, updateScrollbarHandler?: () => void) => {
    return new Control(
      () => this.discard(optionsTabPageHandler, updateScrollbarHandler),
      this.translateService.instant('Common.Discard'),
      'btn btn-light',
      '',
      this.translateService.instant('Common.Discard'),
      'btn',
      false
    );
  };

  private discard = (optionsTabPageHandler?: () => void, updateScrollbarHandler?: () => void) => {
    if (!this.getDetailForm().hasChanges()) return;

    this.ngxSmartModalService.setModalData(
      {
        title: 'SendFax.HeadText',
        text: this.translateService.instant('SendFax.CancelConfirmation'),
        buttonText: this.translateService.instant('Common.Discard'),
        confirm: () => this.confirmDiscardHandler(optionsTabPageHandler, updateScrollbarHandler),
        cancel: this.cancelDiscardHandler,
      },
      'actionConfirmModal',
      true
    );

    this.ngxSmartModalService.getModal('actionConfirmModal').open();
  };

  private confirmDiscardHandler = (optionsTabPageHandler?: () => void, updateScrollbarHandler?: () => void) => {
    this.printToService.closeAppIfPrintTo();
    this.ngxSmartModalService.getModal('actionConfirmModal').close();
    this.getDetailForm().clear();
    this.setDetailForm(this.getDetailForm());
    this.faxUserProfileLoadedSubject.next(false);
    this.loadFaxPageSettingsValues();
    this.faxUserProfileLoadedSubject.next(this.isFaxUserProfileLoaded());

    optionsTabPageHandler?.();
    updateScrollbarHandler?.();

    this.sendFormDiscardedSubject.next();
  };

  private cancelDiscardHandler = () => {
    this.ngxSmartModalService.getModal('actionConfirmModal').close();
  };

  private isFaxUserProfileLoaded() {
    if (
      this.userState.userProfile &&
      this.userState.userProfile.fax &&
      this.userState.userProfile.fax.advancePageSetting
    )
      return true;

    return false;
  }

  private saveSettingsAsDefault = () => {
    this.userPreferencesService.setPreference(
      `${this.preferencePrefix}${FaxCSID}`,
      this.getDetailForm().faxPageSettings.faxCSID
    );

    this.userPreferencesService.setPreference(
      `${this.preferencePrefix}${NumberOfAttampts}`,
      this.getDetailForm().faxPageSettings.numberOfAttempts
    );

    this.userPreferencesService.setPreference(
      `${this.preferencePrefix}${PageOrientation}`,
      this.getDetailForm().faxPageSettings.pageOrientation
    );

    this.userPreferencesService.setPreference(
      `${this.preferencePrefix}${PageSize}`,
      this.getDetailForm().faxPageSettings.pageSize
    );

    this.userPreferencesService.setPreference(
      `${this.preferencePrefix}${RenderingOptimization}`,
      this.getDetailForm().faxPageSettings.renderingOptimization
    );

    this.userPreferencesService.setPreference(
      `${this.preferencePrefix}${Resolution}`,
      this.getDetailForm().faxPageSettings.resolution
    );

    this.userPreferencesService.setPreference(
      `${this.preferencePrefix}${FeedbackEmail}`,
      this.getDetailForm().faxPageSettings.feedbackEmail
    );

    this.userPreferencesService.setPreference(
      `${this.preferencePrefix}${SendAfterDateTime}`,
      this.getDetailForm().faxPageSettings.sendAfterDateTime
    );

    this.userPreferencesService.setPreference(
      `${this.preferencePrefix}${SendAfter}`,
      this.getDetailForm().faxPageSettings.sendAfter
    );
  };

  isValidDetailForm = (): boolean => {
    if (!this.hasRecipients()) return false;
    if (!this.hasContentToSend()) return false;

    return true;
  };

  hasRecipients = (): boolean => this.getDetailForm().recipients.length > 0;

  hasContentToSend = (): boolean => this.hasAttachments() || this.hasCoverpage() || this.hasMessageBody();

  hasAttachments = (): boolean => this.getDetailForm().attachedItems.length > 0;

  hasCoverpage = (): boolean => !!this.getDetailForm().coverPage;

  hasMessageBody = (): boolean => {
    if (this.hasHtmlMessageBodyContent()) return true;

    return this.getDetailForm().message.length > 0;
  };

  hasHtmlMessageBodyContent = (): boolean => {
    if (!this.hasCoverpage()) return false;
    if (this.getDetailForm().coverPage.type != CoverPageType.Html) return false;
    if (this.getDetailForm().coverPage.coverpageBodyType == CoverPageBodyType.None) return false;

    return this.getDetailForm().hasHtmlValue();
  };

  resetSendFaxState = () => {
    this.faxUserProfileLoadedSubject.next(false);
    this.detailFormSubject.next(new FaxForm({}));
  };
}
