import { Component, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { FieldDefinition, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { Delimiters, Email } from '../../core/email';
import { InterFAXService } from '../../services/interfax.service';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-interfax-resend-notifications-modal',
  templateUrl: './interfax-resend-notifications-modal.component.html',
  styleUrls: ['./interfax-resend-notifications-modal.component.scss'],
})
export class InterfaxResendNotificationsModalComponent implements OnInit {
  @ViewChild('spinnerElement', { static: true })
  spinnerElement;

  @Output() closeModal = new EventEmitter();

  title: string;

  fieldEmail: FieldDefinition;
  email: string;
  useAlternativeEmail = false;
  onlyResendFailures = false;

  show = false;
  errors = new Array<string>();
  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private toastrService: ToastrService
  ) {}

  ngOnInit(): void {
    this.show = true;
    this.title = this.translateService.instant('interfax-queue.resend-notifications-title');
    this.createFields();
  }

  save = (): void => {
    if (this.isResendDisabled()) return;
    const mdc = new MetaDataCollection();

    if (this.useAlternativeEmail) mdc.set('email', this.email);

    mdc.set('failedOnly', this.onlyResendFailures.toString());

    this.spinnerService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);
    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.sharedDataService.extraParameters.ids,
      mdc,
      this.saved,
      this.saveFailed
    );
  };

  onFieldEmailChange(value: string): void {}

  isResendDisabled = (): boolean => {
    if (!this.show) return true;

    if (!this.useAlternativeEmail) return false;

    if (!Email.isValidDelimited(this.email, Delimiters.Semicolon)) return true;

    return false;
  };

  saved = (): void => {
    this.spinnerService.hide();
    this.toastrService.success(this.translateService.instant('interfax-queue.resend-notifications-success'));

    this.close();
  };

  saveFailed = (errs: any[]): void => {
    this.spinnerService.hide();
    this.errors = errs;
  };

  close = (): void => {
    this.show = false;
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  createFields = (): void => {
    this.fieldEmail = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('interfax-queue.resend-notifications-email'),
      placeholder: this.translateService.instant('interfax-queue.resend-notifications-email-placeholder'),
      required: true,
    });
  };
}
