import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class WorkItemFilterByDateSubmitted extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByRelativeDateComponent';
  }
}

class WorkItemFilterByFilterByWorkflow extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByWorkflowComponent';
  }
}

class WorkItemFilterByFilterByOwner extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOwnerComponent';
  }
}

class WorkItemFilterByMetaData extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByMetaDataComponent';
  }
}

class FilterByOptions extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOptionsComponent';
  }
}

export class WorkItemFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('WorkItemFilters.Create', filter);

    if (
      filter.id == 'BambaApplication-Upland.Bamba.Application.WorkItems.Filtering.FilterByRelativeDateSubmitted' ||
      filter.id == 'BambaApplication-Upland.Bamba.Application.WorkItems.Filtering.FilterByRelativeDateCompleted'
    )
      return new WorkItemFilterByDateSubmitted(filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.WorkItems.Filtering.FilterByWorkflow')
      return new WorkItemFilterByFilterByWorkflow(filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.WorkItems.Filtering.FilterByOwner')
      return new WorkItemFilterByFilterByOwner(filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.WorkItems.Filtering.FilterByMetaData')
      return new WorkItemFilterByMetaData(filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.WorkItems.Filtering.FilterByCompleted') {
      return new FilterByOptions(filter);
    }

    return null;
  };
}
