import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Papa, ParseResult } from 'ngx-papaparse';

import { IFieldOptions } from 'shared-code-lib';
import { HydraApiService } from './hydra-api.service';

@Injectable({
  providedIn: 'root',
})
export class CSVService {
  constructor(private papa: Papa, private translate: TranslateService, private api: HydraApiService) {}

  parse = (
    csv: File,
    containsHeader: boolean,
    successCallBack: (result: ParseResult) => void,
    failureCallBack: (err: any) => void
  ): void => {
    if (!csv) return;

    this.api.getFileEncoding(
      csv,
      (encoding) => {
        this.papa.parse(csv, {
          delimiter: ',',
          skipEmptyLines: true,
          header: containsHeader,
          encoding: encoding,
          complete: successCallBack,
          error: failureCallBack,
        });
      },
      failureCallBack
    );
  };

  getColumns(parseResult: ParseResult, containsHeader: boolean): IFieldOptions[] {
    if (!parseResult) return null;

    if (containsHeader) {
      const headerRow = parseResult.meta.fields;

      return headerRow.map((field, index) => {
        return { name: field, value: `${index}` };
      });
    } else {
      const firstRow = parseResult.data[0];

      return Object.values(firstRow).map((value, index) => {
        const columnText = this.translate.instant('Metadata-Form.column');
        return { name: `${columnText + (index + 1)} (${value})`, value: `${index}` };
      });
    }
  }
}
