import { Component, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { FieldDefinition, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { InterFAXService } from '../../services/interfax.service';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-interfax-reset-user-password-modal',
  templateUrl: './interfax-reset-user-password-modal.component.html',
  styleUrls: ['./interfax-reset-user-password-modal.component.scss'],
})
export class InterfaxResetUserPasswordModalComponent implements OnInit {
  @ViewChild('spinnerElement', { static: true })
  spinnerElement;

  @Output() closeModal = new EventEmitter();

  fieldEmail: FieldDefinition;

  email: string;
  username: string;

  show = true;
  errors = new Array<string>();

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private interfaxService: InterFAXService
  ) {}

  ngOnInit(): void {
    this.createFields();

    this.email = this.sharedDataService.extraParameters ? this.sharedDataService.extraParameters.email : '';
    this.username = this.sharedDataService.extraParameters ? this.sharedDataService.extraParameters.username : '';
  }

  close = (): void => {
    this.show = false;
    this.closeModal.emit();
  };

  save = (): void => {
    this.spinnerService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);

    const items = [];

    const args = new MetaDataCollection();
    args.set('email', this.email);
    args.set('username', this.username);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      items,
      args,
      this.saved,
      this.saveFailed
    );
  };

  saved = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  saveFailed = (errors: any[]): void => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  cancel = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  createFields = (): void => {
    this.fieldEmail = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('reset-user-password.email'),
      placeholder: this.translateService.instant('reset-user-password.email-placeholder'),
      required: true,
    });
  };
}
