import {
  ChangeDetectorRef,
  Component,
  ElementRef,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Renderer2,
  SimpleChanges,
  ViewChild,
  ViewContainerRef,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { BehaviorSubject, Subscription } from 'rxjs';
import { debounceTime, distinctUntilChanged } from 'rxjs/operators';

import { IFieldOptions } from '../../models/field-definition';
import { DelayService } from '../../utils/delay.service';
import { Key } from '../../utils/key-enum';
import { DropDownComponent } from '../list/drop-down/drop-down.component';
import { DropDownService } from '../list/drop-down/drop-down.service';
import { TextComponent } from '../text/text.component';
import { NodeType, Subtitution } from './text-substitutable.model';

declare const $: any;

@Component({
  selector: 'app-text-substitutable',
  templateUrl: './text-substitutable.component.html',
  styleUrls: ['./text-substitutable.component.scss'],
  encapsulation: ViewEncapsulation.None,
  providers: [DropDownService],
})
export class TextSubstitutableComponent extends TextComponent implements OnInit, OnDestroy, OnChanges {
  @Input() isLargeText: boolean;
  @Input() fieldId: string = '';
  @ViewChild('input', { static: true })
  inputEl: ElementRef;
  @ViewChild('list', { static: true })
  listEl: ElementRef;
  @ViewChild('dropDownWrapper', { static: true })
  dropDownWrapper: ElementRef;
  searchTerm = new BehaviorSubject<string>('');
  optionsList = new BehaviorSubject<Array<IFieldOptions>>([]);
  filteredOptions: Array<string> = [];
  substitutions: Array<Subtitution> = [];
  removedSubstitutions: Array<Subtitution> = [];
  observers: Array<MutationObserver> = [];
  currentSubtitution: Subtitution = null;
  currentSelectedOption: string;
  currentSelectedOptionIndex: number;
  mousedown: boolean;
  isMenuVisible: boolean;
  datasourceChanged: Subscription;
  noMatchesFoundMessage: string;
  subscriptions: Subscription;
  initialValueLoaded: boolean = false;

  constructor(
    translateService: TranslateService,
    private dropDown: DropDownService,
    private delay: DelayService,
    private renderer: Renderer2,
    private viewContainerRef: ViewContainerRef,
    private cdr: ChangeDetectorRef
  ) {
    super(translateService);
    this.subscriptions = new Subscription();
  }

  ngOnInit(): void {
    this.noMatchesFoundMessage = this.translateService.instant('Common.noMatches');
    this.searchTerm.pipe(debounceTime(300), distinctUntilChanged()).subscribe((term) => {
      this.field.datasource.getItems(term, '', (items) => this.optionsList.next(items), null);
    });

    this.renderer.setAttribute(this.inputEl.nativeElement, 'placeholder', this.field.placeholder);
    if (!this.isLargeText) {
      this.renderer.setAttribute(this.inputEl.nativeElement, 'data-gramm_editor', 'false');
    }

    this.subscriptions.add(
      this.dropDown.onHide.subscribe(() => {
        if (this.isMenuVisible) {
          this.isMenuVisible = false;
        }
      })
    );

    this.subscriptions.add(
      this.dropDown.onSelect.subscribe((option) => {
        if (this.isMenuVisible) {
          this.currentSelectedOption = option.useValueForSubstitution ? option.value : option.name;
        }
      })
    );

    this.subscriptions.add(
      this.dropDown.onSelectViaClick.subscribe((option) => {
        if (this.isMenuVisible) {
          this.onSelect(option.useValueForSubstitution ? option.value : option.name);
        }
      })
    );

    this.subscriptions.add(
      this.dropDown.onClickOutside.subscribe(() => {
        this.hideList();
      })
    );

    if (this.value && !this.initialValueLoaded) {
      this.handlePreviouslySavedValues();
      this.initialValueLoaded = true;
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.value && changes.value.currentValue && !this.initialValueLoaded) {
      this.handlePreviouslySavedValues();
      this.initialValueLoaded = true;
    }
  }

  ngOnDestroy(): void {
    this.observers.forEach((o) => o.disconnect());
    this.subscriptions.unsubscribe();

    super.onBlur({ target: { value: this.getValue() } });
  }

  getValue = (): string => {
    if (!this.input.nativeElement.innerText) return '';

    return this.input.nativeElement.innerText.replace(/\s+$/, '').replace(/\u00A0/g, ' ');
  };

  handlePreviouslySavedValues(): void {
    const substitutionRegex = /%[^\s][^%]*[^\s]%/g;
    const substitutionsIds = [];

    const valueAsHtmlString = this.value.replace(substitutionRegex, (substitutionMatch) => {
      const substitution = new Subtitution('', document.createElement('span'));
      substitution.subEl.classList.add('sub');
      substitution.subEl.classList.add('closed');
      substitution.subEl.innerText = substitutionMatch;
      substitution.subEl.setAttribute('data-id', substitution.id);

      substitutionsIds.push(substitution.id);
      this.substitutions.push(substitution);

      return substitution.subEl.outerHTML;
    });

    this.inputEl.nativeElement.innerHTML = this.replaceSpacesWithNonBreakingSpaces(
      valueAsHtmlString.replace(/\n/g, '<br>')
    );

    this.cdr.detectChanges();

    substitutionsIds.forEach((id) => {
      const subEl = document.querySelector(`[data-id="${id}"]`) as HTMLElement;
      if (!subEl) return;

      this.substitutions.find((s) => s.id === id).subEl = subEl;

      this.handleAddingRemovingSubEl(
        subEl,
        this.inputEl.nativeElement,
        () => {
          this.onDeleteSubEl(subEl);
        },
        () => {
          this.onAddSubEl(subEl);
        }
      );
    });
  }

  replaceSpacesWithNonBreakingSpaces(html: string): string {
    const spacesAtStart = html.match(/^\s*/)[0];
    const spacesAtEnd = html.match(/\s*$/)[0];

    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');
    this.replaceTextSpaces(doc.body);

    return spacesAtStart.replace(/ /g, '\u00A0') + doc.body.innerHTML + spacesAtEnd.replace(/ /g, '\u00A0');
  }

  replaceTextSpaces(node: Node): void {
    node.childNodes.forEach((child) => {
      if (child.nodeType === Node.TEXT_NODE) {
        child.textContent = child.textContent.replace(/ /g, '\u00A0');
        return;
      }

      this.replaceTextSpaces(child);
    });
  }

  onInput(event: any): void {
    const target = event.target as HTMLElement;
    const sel = window.getSelection();
    const focusedEl = sel.focusNode.parentElement;
    const classes = focusedEl.classList;
    const data = event.data;

    this.initialValueLoaded = true;

    if (classes.contains('group')) {
      if (target.childNodes.length === 1) {
        target.innerText = '';
        this.placeCaretAtEnd(target);
      }
    } else if (classes.contains('sub')) {
      // substitution element
      this.handleOnInputInsideSubElement(focusedEl, data, target);
    } else if (classes.contains('substitution')) {
      // input element
      this.handleOnInputInsideNonSubElements(target, data);
    } else if (classes.contains('old-sub')) {
      // sub has multiple % with no value inside
      this.handleOnInputInsideOldSubElement(focusedEl, data, target);
    } else {
      const hasClass = focusedEl.className ? true : false;
      if (!hasClass && focusedEl.parentElement) this.handleOnInputInsideNonSubElements(target, data);
    }

    const trimmedString = this.getValue();
    event.value = trimmedString;
    super.onChangeValue(trimmedString);
    this.inputChange.emit(trimmedString);
  }

  handleOnInputInsideSubElement(focusedEl: HTMLElement, data: string, target: HTMLElement): void {
    const classes = focusedEl.classList;
    const isClosed = classes.contains('closed');
    const innerText = focusedEl.innerText;
    const numberOfPercentSigns = innerText.split('%').length - 1;
    const valueLength = innerText.length;
    const openingSignPos = innerText.indexOf('%');
    const closingSignPos = innerText.lastIndexOf('%');
    const lastCharPos = valueLength - 1;
    const actualValue = innerText.slice(
      openingSignPos + 1,
      closingSignPos && closingSignPos !== openingSignPos ? closingSignPos : valueLength
    );

    if (data === '%') {
      if (!isClosed) {
        if (actualValue) {
          // close sub
          classes.add('closed');
          this.hideList();
        } else {
          focusedEl.classList.remove('sub');
          focusedEl.classList.add('old-sub');
          this.hideList();
          const id = focusedEl.getAttribute('data-id');
          const subIndex = this.substitutions.findIndex((sub) => {
            return sub.id === id;
          });

          if (subIndex > -1) {
            this.substitutions.splice(subIndex, 1);
          }
        }
      } else {
        // we should do nothing but filter the list
        this.currentSubtitution.value = actualValue;
        this.drawList();
      }
    } else {
      if (numberOfPercentSigns === 1 && isClosed) {
        classes.remove('closed');
      }

      if (openingSignPos === 0) {
        // % at index 0
        if (data && isClosed && closingSignPos !== lastCharPos) {
          const text = document.createTextNode(innerText[lastCharPos]);
          this.addNewTextNode(text, target, focusedEl, true);
          this.hideList();
          return;
        }

        if (!this.currentSubtitution) {
          this.currentSubtitution = this.substitutions.find((s) => s.id === focusedEl.getAttribute('data-id'));
        }

        this.currentSubtitution.value = actualValue.split(':')[0];
        this.drawList();
      } else {
        const text = document.createTextNode(innerText[0]);
        this.addNewTextNode(text, target, focusedEl);
        this.hideList();
      }
    }
  }

  handleOnInputInsideNonSubElements(target: HTMLElement, data: string | any): void {
    if (data !== '%') return;

    let subElement = this.addSubstitutionElement(target);
    if (!subElement) return;

    this.setCaret(subElement, 0, 1);
    this.handleAddingRemovingSubEl(
      subElement,
      target,
      () => this.onDeleteSubEl(subElement),
      () => this.onAddSubEl(subElement)
    );

    this.drawList();
  }

  addSubstitutionElement(node: HTMLElement): HTMLElement {
    if (!node) return;
    if (node.classList?.contains('sub') && node.classList?.contains('closed')) return;
    if (node.nodeType == NodeType.Element) {
      for (let i = 0; i < node.childNodes.length; i++) {
        const el = this.addSubstitutionElement(node.childNodes[i] as HTMLElement);
        if (el) return el;
      }

      return;
    }

    if (node.nodeType != NodeType.Text) return;
    const nodeText = node.textContent;
    const percentSignIndex = nodeText.indexOf('%');
    if (percentSignIndex == -1) return;

    const left = document.createTextNode(nodeText.slice(0, percentSignIndex));
    const right = document.createTextNode(nodeText.slice(percentSignIndex + 1));
    const subElement = this.getNewSubElement();

    node.parentElement.insertBefore(left, node);
    node.parentElement.insertBefore(subElement, node);
    node.parentElement.insertBefore(right, node);
    node.remove();

    return subElement;
  }

  onDeleteSubEl(subElement: HTMLElement): void {
    const index = this.substitutions.findIndex((s) => s.id === subElement.getAttribute('data-id'));

    if (index > -1) {
      this.removedSubstitutions.push(this.substitutions.splice(index, 1)[0]);
      this.hideList();
    }
  }

  onAddSubEl(subElement: HTMLElement): void {
    const id = subElement.getAttribute('data-id');
    const index = this.removedSubstitutions.findIndex((s) => s.id === id);
    if (index > -1) {
      this.substitutions.push(this.removedSubstitutions.splice(index, 1)[0]);
    }
  }

  handleOnInputInsideOldSubElement(focusedEl: HTMLElement, data: string, target: HTMLElement): void {
    if (data && data !== '%') {
      const childNodes = [];
      let nodeIndex;
      target.childNodes.forEach((node: HTMLElement, i: number) => {
        if (node.nodeType === NodeType.Element) {
          if (node.getAttribute('data-id') === focusedEl.getAttribute('data-id')) {
            nodeIndex = i;
          }
        }

        childNodes.push(node);
      });

      target.innerHTML = '';
      childNodes.forEach((node, i) => {
        let innerNode = node;
        if (nodeIndex === i) {
          innerNode = document.createTextNode(node.innerText.split('').pop());
          node.innerText = node.innerText.slice(0, node.innerText.length - 1);
          target.appendChild(node);
        }

        target.appendChild(innerNode);
      });

      this.setCaret(target, nodeIndex + 1, 1);
    }
  }

  getNewSubElement(): HTMLElement {
    let sub = document.createElement('span');
    this.currentSubtitution = new Subtitution('', sub);
    sub.classList.add('sub');
    sub.innerHTML = '%';
    sub.setAttribute('data-id', this.currentSubtitution.id);
    this.substitutions.push(this.currentSubtitution);
    return sub;
  }

  addNewTextNode(text, target, focusedEl, after = false): void {
    let subElIndex = -1;
    const childNodes = [];
    target.childNodes.forEach((node: HTMLElement, index: number) => {
      if (node.nodeType === NodeType.Element && node) {
        if (node.getAttribute('data-id') === focusedEl.getAttribute('data-id')) {
          subElIndex = index;
        }
      }

      childNodes.push(node);
    });

    target.innerHTML = '';
    childNodes.forEach((node, i) => {
      if (i === subElIndex && !after) {
        target.appendChild(text);
      }

      target.appendChild(node);

      if (i === subElIndex && after) {
        target.appendChild(text);
      }
    });
    focusedEl.innerText = after
      ? focusedEl.innerHTML.slice(0, focusedEl.innerText.length - 1)
      : focusedEl.innerHTML.slice(1);

    this.setCaret(target, after ? subElIndex + 1 : subElIndex, 1);
  }

  onKeyup(event: any): void {
    const sel = window.getSelection();
    const focusedEl = sel.focusNode.parentElement;
    if (event.key === Key.ArrowLeft || event.key === Key.ArrowRight) {
      if (focusedEl.classList.contains('sub')) {
        this.handleFocusingOnLastChar(focusedEl);
      } else {
        this.hideList();
      }
    }
  }

  onClick(event: Event): void {
    event.stopPropagation();
    const sel = window.getSelection();
    const focusedEl = sel.focusNode.parentElement;
    if (focusedEl.classList.contains('sub')) {
      this.handleFocusingOnLastChar(focusedEl);
    } else {
      this.hideList();
    }
  }

  handleFocusingOnLastChar(focusedEl: HTMLElement): void {
    const pos = this.getCaretPosition(focusedEl);
    const char = focusedEl.innerText[pos];

    this.currentSubtitution = this.substitutions.find((s) => s.id === focusedEl.getAttribute('data-id'));
    if (
      focusedEl.classList.contains('closed') &&
      char === '%' &&
      this.currentSubtitution &&
      pos === focusedEl.innerText.length - 1
    ) {
      this.drawList();
    } else if (!focusedEl.classList.contains('closed') && pos === focusedEl.innerText.length) {
      this.drawList();
    } else {
      this.hideList();
    }
  }

  onFocus(event: any): void {
    event.target.parentElement.classList.add('has-focus');
    if (!this.mousedown && event.sourceCapabilities) {
      event.target.scrollLeft = 1000;
      this.placeCaretAtEnd(event.target);
    } else {
      this.mousedown = false;
    }

    event.target.value = event.target.innerText;
    super.onFocus(event);
  }

  onFocusout(event: any): void {
    event.target.parentElement.classList.remove('has-focus');
    this.mousedown = false;

    event.target.value = event.target.innerText;
    if (event.target.value.trim() == '') $(event.target).empty();
    this.value = this.getValue();
    super.onBlur(event);
  }

  onMouseDown(event): void {
    this.mousedown = true;
  }

  onKeydown(event: any): void {
    event.stopPropagation();
    if (event.key === Key.Enter) {
      if (this.isMenuVisible && this.currentSelectedOption && this.currentSubtitution) {
        event.preventDefault();
        const currentSubEl = this.inputEl.nativeElement.querySelector(`.sub[data-id="${this.currentSubtitution.id}"]`);
        this.currentSubtitution.value = this.currentSelectedOption;
        this.closeSubElement(currentSubEl);
      } else if (this.isLargeText) {
        this.delay.execute(() => this.replaceDivWithBr(event.target.querySelector('div')), 0);
      }

      super.onReturn();
    } else if (event.key === Key.Tab) {
      this.hideList();
    } else {
      this.dropDown.keydown(event);
    }

    event.target.value = event.target.innerText;

    super.onKeydown(event);
  }

  replaceDivWithBr(div: HTMLElement): void {
    if (!div) return;

    const parent = div.parentElement;
    let nodeIndex = parent.childNodes.length - 1;
    if (div.previousSibling.nodeName.toLocaleLowerCase() != 'br') {
      parent.insertBefore(document.createElement('br'), div);
      nodeIndex++;
    }
    while (div.childNodes.length) {
      parent.insertBefore(div.childNodes[0], div);
    }

    div.remove();

    this.setCaret(parent, nodeIndex, 0);
  }

  closeSubElement(subEl: HTMLElement): void {
    const focus = document.createElement('span');
    subEl.classList.add('closed');
    subEl.setAttribute('contenteditable', 'false');
    subEl.innerText = subEl.innerText.substr(1);
    if (subEl.innerText[subEl.innerText.length - 1] === '%') {
      subEl.innerText = subEl.innerText.substr(0, subEl.innerText.length - 2);
    }

    const textArr = subEl.innerText.split(':');
    textArr[0] = this.currentSubtitution.value;
    subEl.innerText = `%${textArr.join(':')}%`;
    subEl.appendChild(focus);
    focus.setAttribute('contenteditable', 'true');
    focus.focus();
    this.setCaret(subEl, 0, subEl.innerText.length);
    subEl.removeAttribute('contenteditable');
    focus.remove();

    this.setCursorAfter(subEl);

    this.hideList();
  }

  setCursorAfter(element: HTMLElement): void {
    element.insertAdjacentHTML('afterend', '&nbsp;');
    for (let i = 0; i < element.parentElement.childNodes.length; i++) {
      if (element.parentElement.childNodes[i] == element) {
        this.setCaret(element.parentElement, i + 1, 1);
        break;
      }
    }
  }

  drawList(): void {
    if (!this.optionsList?.value.length) return;
    if (!this.isMenuVisible) {
      this.delay.execute(() => {
        this.dropDown.show(
          {
            component: DropDownComponent,
            data: {
              value: this.currentSubtitution.value,
              disabled: this.disabled,
              options: this.optionsList,
              parent: this.dropDownWrapper.nativeElement,
              idPrefix: `field-list-${this.field.label}`,
              disableSearch: true,
              startsWithFiltering: true,
              noResultMessage: this.noMatchesFoundMessage,
              searchTerm: this.searchTerm,
            },
          },
          this.viewContainerRef
        );

        this.isMenuVisible = true;
      }, 0);
    } else {
      this.searchTerm.next(this.currentSubtitution.value);
    }
  }

  hideList(): void {
    this.dropDown.hide();
    this.isMenuVisible = false;
  }

  onSelect(option: string): void {
    if (this.currentSubtitution) {
      const currentSubEl = this.inputEl.nativeElement.querySelector(`.sub[data-id="${this.currentSubtitution.id}"]`);
      this.currentSubtitution.value = option;
      this.closeSubElement(currentSubEl);
    }
  }

  onClickOutSide(): void {
    this.hideList();
  }

  onClickInputWrapper(event): void {
    const target = event.target;
    const pWidth = $(target).innerWidth();
    const pOffset = $(target).offset();
    const x = event.pageX - pOffset.left;

    this.input.nativeElement.focus();
    if (pWidth / 2 < x) {
      this.placeCaretAtEnd(this.input.nativeElement);
    }
  }

  private handleAddingRemovingSubEl(
    element: HTMLElement,
    parent: HTMLElement,
    onDeleteCallback: () => void,
    onAddCallback: (el: HTMLElement) => void
  ): void {
    const observer = new MutationObserver((mutations) => {
      function isDetached(el) {
        if (el.parentNode === document) {
          mutations.forEach((mutation) => {
            if (mutation.addedNodes.length) {
              mutation.addedNodes.forEach((node: HTMLElement) => {
                if (node.classList && node.classList.contains('sub')) {
                  if (node.getAttribute('data-id') === element.getAttribute('data-id')) {
                    onAddCallback(node);
                  }
                }
              });
            }
          });
          return false;
        } else if (el.parentNode === null) {
          return true;
        } else {
          return isDetached(el.parentNode);
        }
      }

      if (isDetached(element)) {
        onDeleteCallback();
      }
    });

    this.observers.push(observer);
    observer.observe(parent, {
      childList: true,
      subtree: true,
    });
  }

  getCaretPosition(editableDiv: HTMLElement): number {
    let caretPos = 0,
      sel,
      range;
    if (window.getSelection) {
      sel = window.getSelection();
      if (sel.rangeCount) {
        range = sel.getRangeAt(0);
        if (range.commonAncestorContainer.parentNode === editableDiv) {
          caretPos = range.endOffset;
        }
      }
    }
    return caretPos;
  }

  placeCaretAtEnd(el) {
    el.focus();
    if (typeof window.getSelection !== 'undefined' && typeof document.createRange !== 'undefined') {
      const range = document.createRange();
      range.selectNodeContents(el);
      range.collapse(false);
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
    }
  }

  setCaret(el: HTMLElement, position: number, offset = 0) {
    el.focus();
    const range = document.createRange();
    const sel = window.getSelection();

    range.setStart(el.childNodes[position], offset);
    range.collapse(true);

    sel.removeAllRanges();
    sel.addRange(range);
  }
}
