import * as pdfjsLib from 'pdfjs-dist/legacy/build/pdf';

export const extractFirstPageFromPdfAsImage = async (pdfUrl: string) => {
  pdfjsLib.GlobalWorkerOptions.workerSrc = './../../../../../assets/pdfjs-dist/legacy/build/pdf.worker.min.js';
  const pdf = await pdfjsLib.getDocument({ url: pdfUrl, isEvalSupported: false }).promise;
  const page = await pdf.getPage(1);
  const scale = 1;
  const viewport = page.getViewport({ scale });

  const canvas = document.createElement('canvas');
  const context = canvas.getContext('2d');
  canvas.height = viewport.height;
  canvas.width = viewport.width;

  const renderContext = {
    canvasContext: context,
    viewport: viewport,
  };

  await page.render(renderContext).promise;

  const imageDataURL = canvas.toDataURL('image/png');

  pdfjsLib.GlobalWorkerOptions.workerSrc = '';

  const blob = await fetch(imageDataURL).then((response) => response.blob());
  return URL.createObjectURL(blob);
};

export const mapImagesToPdfImages = (text: string) => {
  const domParser = new DOMParser();
  const textDomNode = domParser.parseFromString(text, 'text/html');

  const pdfImages: NodeListOf<HTMLImageElement> = textDomNode.querySelectorAll('img[pdfURL]');

  pdfImages.forEach((image) => {
    image.setAttribute('src', image.getAttribute('pdfURL') as string);
    image.removeAttribute('pdfURL');
  });

  return textDomNode.body.innerHTML;
};

export const mapImagesToBlobUrls = async (text: string) => {
  const domParser = new DOMParser();
  const textDomNode = domParser.parseFromString(text, 'text/html');

  const pdfImages: NodeListOf<HTMLImageElement> = textDomNode.querySelectorAll('img[src$="filetype=pdf"]');

  const imagesPromise = new Promise((resolve) => {
    if (pdfImages.length) {
      pdfImages.forEach(async (image, index) => {
        const pdfurl = image.getAttribute('src') as string;
        image.setAttribute('pdfurl', pdfurl);

        const firstPageUrl = await extractFirstPageFromPdfAsImage(pdfurl);
        image.setAttribute('src', firstPageUrl);

        if (index === pdfImages.length - 1) resolve(1);
      });
    } else {
      resolve(1);
    }
  });

  await imagesPromise;

  return textDomNode.body.innerHTML;
};
