export enum Criterias {
  StartsWith = 'Upland.Hydra.Core.Formatters.StartsWith',
  EndsWith = 'Upland.Hydra.Core.Formatters.EndsWith',
  Contains = 'Upland.Hydra.Core.Formatters.Contains',
  Regex = 'Upland.Hydra.Core.Formatters.Regex',
  Length = 'Upland.Hydra.Core.Formatters.Length',
}

export class Criteria {
  public criteriaType: string;

  constructor(initializer: any = null) {}

  public static create = (initializer: any): Criteria => {
    if (initializer.criteriaType == Criterias.StartsWith) return new StartsWith(initializer);
    if (initializer.criteriaType == Criterias.EndsWith) return new EndsWith(initializer);
    if (initializer.criteriaType == Criterias.Contains) return new Contains(initializer);
    if (initializer.criteriaType == Criterias.Regex) return new Regex(initializer);
    if (initializer.criteriaType == Criterias.Length) return new Length(initializer);

    throw new Error(`Invalid Criteria type: ${initializer.criteriaType}`);
  };

  public serializable(): any {
    return { criteriaType: this.criteriaType };
  }
}

export class TextCriteria extends Criteria {
  public text: string;
  public ignoreCase: boolean;

  constructor(initializer: any = null) {
    super(initializer);

    if (initializer) {
      if (initializer.text === undefined) throw new Error('invalid initializer.text');
      if (initializer.ignoreCase === undefined) throw new Error('invalid initializer.ignoreCase');

      this.text = initializer.text;
      this.ignoreCase = initializer.ignoreCase;
    }
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      text: this.text,
      ignoreCase: this.ignoreCase,
    };
  }
}

export class StartsWith extends TextCriteria {
  constructor(initializer: any = null) {
    super(initializer);

    this.criteriaType = Criterias.StartsWith;
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
    };
  }
}

export class EndsWith extends TextCriteria {
  constructor(initializer: any = null) {
    super(initializer);

    this.criteriaType = Criterias.EndsWith;
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
    };
  }
}

export class Contains extends TextCriteria {
  constructor(initializer: any = null) {
    super(initializer);

    this.criteriaType = Criterias.Contains;
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
    };
  }
}

export class Regex extends TextCriteria {
  constructor(initializer: any = null) {
    super(initializer);

    this.criteriaType = Criterias.Regex;
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
    };
  }
}

export enum Operators {
  Equals = 0,
  NotEquals = 1,
  LessThan = 2,
  GreaterThan = 3,
  LessThanOrEquals = 4,
  GreaterThanOrEquals = 5,
}

export class Length extends Criteria {
  public operand = 0;
  public operator = Operators.Equals;

  constructor(initializer: any = null) {
    super(initializer);

    this.criteriaType = Criterias.Length;

    if (initializer) {
      if (initializer.operand === undefined) throw new Error('invalid initializer.operand');
      if (initializer.operator === undefined) throw new Error('invalid initializer.operator');

      this.operand = initializer.operand;
      this.operator = initializer.operator;
    }
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      operand: this.operand,
      operator: this.operator,
    };
  }
}
