import { Component, OnInit, ViewEncapsulation } from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';

import { ITenant } from '../../models/tenant';
import { AuthService } from '../../services/auth/auth.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { BambaDetailsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/bamba-details.service';
import { Log } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { BrandingService } from '../../services/branding.service';
import { LoginBaseComponent, AuthorizationResult } from '../login-base/login-base.component';
import { SessionStorageService } from '../../services/session-storage.service';
import { HydraApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';

@Component({
  selector: 'app-login-tenants',
  templateUrl: './login-tenants.component.html',
  styleUrls: ['./login-tenants.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class LoginTenantsComponent extends LoginBaseComponent implements OnInit {
  partnerTenants: Array<ITenant>;

  constructor(
    hydraApi: HydraApiService,
    userStateService: UserStateService,
    authService: AuthService,
    spinnerStateService: SpinnerStateService,
    translateService: TranslateService,
    bds: BambaDetailsService,
    sss: SessionStorageService,
    bs: BrandingService,
    r: Router,
    private toastr: ToastrService
  ) {
    super(hydraApi, spinnerStateService, translateService, authService, bds, userStateService, sss, bs, r);
  }

  ngOnInit(): void {
    super.ngOnInit();

    if (this.restartLoginProcess()) return;

    this.partnerTenants = this.sessionStorageService.getTenantsList();
  }

  onCancel(e) {
    e.preventDefault();

    this.isSubmitted = false;
    this.partnerTenants = null;

    this.router.navigateByUrl('/login');
  }

  selectTenantSuccessCallback = (ar: AuthorizationResult): void => {
    if (!ar.succeeded) {
      this.spinnerStateService.hide();
      this.toastr.error(this.translateService.instant(ar.errorText));
      return;
    }

    this.authService.setSession(ar);

    this.router.navigate(['/login-complete']);
  };

  onSelectTenant = (tenant: ITenant): void => {
    this.errorOccurred = false;
    this.isSubmitted = true;

    this.translateService.get('Login.Sign-In-Message').subscribe((res) => {
      this.spinnerStateService.show(res, this.loginDivElement);
    });

    this.authService.selectTenant(tenant.id, this.selectTenantSuccessCallback, this.loginFailureCallBack);
  };

  loginFailureCallBack = (err) => {
    Log.error('login-tenants.loginFailureCallBack', err);

    this.loginFailure('Login.InvalidLoginData');
  };
}
