import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class WorkflowFilterByName extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByWorkflowNameComponent';
  }
}

export class WorkflowFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('WorkflowFilters.Create', filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.Workflows.Filters.FilterByWorkflowName')
      return new WorkflowFilterByName(filter);

    return null;
  };
}
