import { AfterViewInit, Component, EventEmitter, OnDestroy, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import { FieldDefinition } from '../../../../../../../../../Bamba.Shared/src/models/field-definition';
import { MetaDataType } from '../../../../../../../../../Bamba.Shared/src/models/metadata-definition';
import { HydraApiService } from '../../../../../blocks/services/hydra-api.service';
import { ApiResult } from '../../../../../blocks/services/models';
import { ProductItemRefreshService } from '../../../../../blocks/services/product-item-refresh.service';
import { SharedDataService } from '../../../../../blocks/services/shared-data.service';
import { SpinnerStateService } from '../../../../../blocks/services/spinner-state.service';
import { ApprovalSelection, IApprovalSelection } from '../../../models/approvals';
import { Template, VersionStatus } from '../../../models/template';
import { IApproveOrRejectTemplatesPayload } from '../../template-editor/models/ted-state';
import { OlcTedPublicTemplateEditorService } from '../../template-editor/services/olc-ted-public-template-editor.service';

@Component({
  selector: 'app-reject-template-modal',
  templateUrl: './reject-template-modal.component.html',
  styleUrls: ['./reject-template-modal.component.scss'],
})
export class RejectTemplateModalComponent implements OnInit, AfterViewInit, OnDestroy {
  @Output() closeModal = new EventEmitter();

  rejectCommentField: FieldDefinition = new FieldDefinition();
  rejectComment = '';

  rejectTemplateModal: NgxSmartModalComponent;

  template: Template;

  selectedApprovals: IApprovalSelection[];

  errors: string[] = [];

  subscriptions: Subscription[] = [];

  constructor(
    private translateService: TranslateService,
    private hydraApiService: HydraApiService,
    private templateEditorService: OlcTedPublicTemplateEditorService,
    private spinnerService: SpinnerStateService,
    private toastr: ToastrService,
    private ngxSmartModalService: NgxSmartModalService,
    private productItemRefreshService: ProductItemRefreshService,
    private sharedDataService: SharedDataService
  ) {}

  ngOnInit() {
    this.subscriptions.push(
      this.templateEditorService.template$.subscribe((template) => {
        this.template = template;
      })
    );

    this.createFields();

    this.selectedApprovals = this.sharedDataService.extraParameters?.selectedApprovals;
  }

  ngAfterViewInit(): void {
    this.rejectTemplateModal = this.ngxSmartModalService.get('rejectTemplateModal');
  }

  createFields() {
    this.rejectCommentField = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('admin-olc-menu.reject-template-comment-label'),
      placeholder: this.translateService.instant('admin-olc-menu.reject-template-comment-placeholder'),
      required: true,
    });
  }

  close = () => {
    this.closeModal.emit();
  };

  updateRejectComment(comment: string) {
    this.rejectComment = comment;
  }

  closeRejectTemplateModal = () => {
    this.close();
    this.rejectTemplateModal.close();
    this.rejectComment = '';
    this.errors = [];
  };

  rejectTemplate() {
    this.errors = [];

    if (!this.rejectComment) {
      this.toastr.error(this.translateService.instant('admin-olc-menu.reject-comment-is-required'));
      return;
    }

    this.spinnerService.show(this.translateService.instant('admin-olc-menu.rejecting-template'), document.body);

    const payload: IApproveOrRejectTemplatesPayload = {
      selectedApprovals: this.selectedApprovals
        ? this.selectedApprovals
        : [
            new ApprovalSelection({
              approvalId: null,
              templateId: this.templateEditorService.templateID,
              versionId: this.templateEditorService.versionId,
            }),
          ],
      comment: this.rejectComment,
    };

    this.hydraApiService.rejectTemplate(payload, this.rejectTemplateSuccess, this.rejectTemplateFailure);
  }

  rejectTemplateSuccess = (result: ApiResult) => {
    this.spinnerService.hide();

    if (!result.success) {
      this.errors = result.errors;
      return;
    }

    this.toastr.success(this.translateService.instant('admin-olc-menu.reject-template-succeeded'));

    this.closeRejectTemplateModal();

    this.productItemRefreshService.onRefresh.next();
    this.sharedDataService.actionHandler.reload.emit(false);

    if (this.template) {
      const versionIndex = this.template.versions.findIndex(
        (v) => v.versionId === this.templateEditorService.versionId
      );

      if (versionIndex !== 1) this.template.versions[versionIndex].status = VersionStatus.Rejected;

      this.templateEditorService.setCurrentTemplate(this.template);
    }
  };

  rejectTemplateFailure = () => {
    this.spinnerService.hide();
    this.toastr.error(this.translateService.instant('admin-olc-menu.reject-template-failed'));
  };

  ngOnDestroy(): void {
    this.subscriptions.forEach((s) => s.unsubscribe());
  }
}
