export enum WorkflowStepCostType {
  Constant = 0,
  Multiplier = 1,
}

export interface IWorkflowStepPageLicenseCost {
  id: string;
  workflowStepClassName: string;
  workflowStepDisplayName: string;
  baseCostType: WorkflowStepCostType;
  baseCostValue: number;
  brandOverrides: Array<BrandOverride>;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
}


export class IBrandOverride {
  brandID: string;
  dealerID: string;
  baseCostType: WorkflowStepCostType;
  baseCostValue: number;
}

export class BrandOverride {
  brandID: string;
  dealerID: string;
  baseCostType: WorkflowStepCostType;
  baseCostValue: number;

  constructor(initializer: IBrandOverride) {
    this.brandID = initializer.brandID;
    this.dealerID = initializer.dealerID;
    this.baseCostType = initializer.baseCostType;
    this.baseCostValue = initializer.baseCostValue;
  }
}

export class WorkflowStepPageLicenseCost implements IWorkflowStepPageLicenseCost {
  public id: string;
  public workflowStepClassName: string;
  public workflowStepDisplayName: string;
  public baseCostType: WorkflowStepCostType;
  public baseCostValue: number;
  public brandOverrides: Array<BrandOverride> = [];
  public dateCreatedUTC: Date;
  public dateModifiedUTC: Date;

  constructor(initializer: IWorkflowStepPageLicenseCost) {
    this.id = initializer.id;
    this.workflowStepClassName = initializer.workflowStepClassName;
    this.workflowStepDisplayName = initializer.workflowStepDisplayName;
    this.baseCostType = initializer.baseCostType;
    this.baseCostValue = initializer.baseCostValue;
    this.brandOverrides = initializer.brandOverrides.map(x=>new BrandOverride(x));
    this.dateCreatedUTC = initializer.dateCreatedUTC;
    this.dateModifiedUTC = initializer.dateModifiedUTC;
  }

  serializable = (): IWorkflowStepPageLicenseCost => {
    return {
      id: this.id,
      workflowStepClassName: this.workflowStepClassName,
      workflowStepDisplayName: this.workflowStepDisplayName,
      baseCostType: this.baseCostType,
      baseCostValue: this.baseCostValue,
      brandOverrides: this.brandOverrides,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
    };
  };
}
