import { Injectable } from '@angular/core';

import { Subject } from 'rxjs';

import { MetaDataDefinition } from 'shared-code-lib';
import { UpdateFieldData, UpdateGroupOfFields } from '../../../blocks/models/update-field-data';
import { GroupOfValuesObj, IndexingPanels, ValueObj } from '../capture-models';

@Injectable({
  providedIn: 'root',
})
export class IndexingPanelService {
  private _focusedPanel: number;
  private _currentFieldName: string;
  private _changeCurrentWorkflowStep = new Subject<Array<MetaDataDefinition>>();
  private _initIndexing = new Subject<void>();
  private _pointAndClickInitialized = new Subject<void>();
  private _toggleLineItemIndexing = new Subject<boolean>();
  private _changeCurrentField = new Subject<string>();
  private _takeFocusSubject = new Subject<number>();
  private _currentFieldValueSubject = new Subject<ValueObj>();
  private _groupOfFieldsValuesSubject = new Subject<GroupOfValuesObj>();

  onChangeWorkflowStep = this._changeCurrentWorkflowStep.asObservable();
  onInit = this._initIndexing.asObservable();
  onPointAndClickInitialized = this._pointAndClickInitialized.asObservable();
  onChangeCurrentField = this._changeCurrentField.asObservable();
  onTakeFocus = this._takeFocusSubject.asObservable();
  onChangeCurrentFieldValue = this._currentFieldValueSubject.asObservable();
  onFillGroupOfValues = this._groupOfFieldsValuesSubject.asObservable();
  onChangeLineItemIndexing = this._toggleLineItemIndexing.asObservable();

  constructor() {
    this._focusedPanel = IndexingPanels.AdvancedIndexing;
  }

  changeCurrentWorkflowStep(metaDataDefinitions: Array<MetaDataDefinition>) {
    this._changeCurrentWorkflowStep.next(metaDataDefinitions);
  }

  init(): void {
    this._initIndexing.next();
  }

  pointAndClickInitialized(): void {
    this._pointAndClickInitialized.next();
  }

  fillCurrentField(updateFieldData: UpdateFieldData): void {
    this._currentFieldValueSubject.next({ panel: this._focusedPanel, updateFieldData: updateFieldData });
  }

  fillGroupOfFieldsValues(updateGroupOfFields: UpdateGroupOfFields) {
    this._groupOfFieldsValuesSubject.next({ panel: this._focusedPanel, UpdateGroupOfFields: updateGroupOfFields });
  }

  takeFocus(panel: number): void {
    this._focusedPanel = panel;
    this._takeFocusSubject.next(this._focusedPanel);
  }

  changeCurrentField(panel: number, fieldName: string): void {
    if (panel !== this._focusedPanel) {
      this._focusedPanel = panel;
      this._takeFocusSubject.next(panel);
    }

    this._currentFieldName = fieldName;
    this._changeCurrentField.next(fieldName);
  }

  toggleLineItemPanel(show: boolean): void {
    this._toggleLineItemIndexing.next(show);
  }

  getCurrentFieldName(): string {
    return this._currentFieldName;
  }
}
