import { Component, OnInit, Output, EventEmitter } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { DeleteTenantDataRequest, FieldDefinition, MetaDataType } from 'shared-code-lib';
import { HydraApiService } from '../../services/hydra-api.service';
import { ToastrService } from 'ngx-toastr';
import { Log } from 'oidc-client';

@Component({
  selector: 'app-delete-tenant-data',
  templateUrl: './delete-tenant-data.component.html',
  styleUrls: ['./delete-tenant-data.component.scss'],
})
export class DeleteTenantDataComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  fieldUsername: FieldDefinition;
  fieldPassword: FieldDefinition;

  request = new DeleteTenantDataRequest();
  deletionConfirmed: boolean;

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private hydraApi: HydraApiService,
    private toast: ToastrService,
    private spinner: SpinnerStateService
  ) {}

  ngOnInit(): void {
    const tenantId = this.sharedDataService.extraParameters.tenantId;
    if (!tenantId) throw new Error('invalid tenant id');

    this.request.tenantId = tenantId;

    this.createFields();
  }

  createFields = (): void => {
    this.fieldUsername = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('Login.Username'),
      placeholder: '',
      required: true,
    });

    this.fieldPassword = new FieldDefinition({
      type: MetaDataType.Password,
      label: this.translateService.instant('Login.Password'),
      placeholder: '',
      required: true,
      canShowPassword: false,
    });
  };

  deleteTenant = (): void => {
    this.spinner.show(this.translateService.instant('admin-tenant.deleting-tenant-data'), document.documentElement);

    this.hydraApi.deleteTenantData(this.request, this.tenantDataDeleted, this.FailedToDeleteTenantData);
  };

  tenantDataDeleted = (): void => {
    this.spinner.hide();
    this.toast.success(this.translateService.instant('admin-tenant.tenant-data-deleted'));
    this.sharedDataService.actionHandler.reload.emit(true);

    this.close();
  };

  FailedToDeleteTenantData = (err: any): void => {
    this.spinner.hide();
    Log.error('DeleteTenantDataComponent.FailedToDeleteTenantData', err);
    this.toast.error(err);
  };

  close = (): void => this.closeModal.emit();
}
