import { Component, Input, OnInit, ViewEncapsulation } from '@angular/core';

@Component({
  selector: 'app-errors',
  templateUrl: './errors.component.html',
  styleUrls: ['./errors.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class ErrorsComponent implements OnInit {
  @Input() errors: Array<any>;
  @Input() fontSize = 16;
  displayErrors: Array<string>;

  constructor() {}

  ngOnInit() {
    this.init();
  }

  ngOnChanges(): void {
    this.init();
  }

  init(): void {
    this.displayErrors = new Array<string>();
    this.processError(this.errors);
  }

  processError(e) {
    if (Array.isArray(e)) {
      this.iterateErrors(e);
    } else if (typeof e === 'string') {
      this.displayErrors.push(e);
    } else if (e.message) {
      this.displayErrors.push(e.message);
    } else {
      this.displayErrors.push(e.toString());
    }
  }

  iterateErrors = (errors: Array<any>): void => {
    for (const e of errors) {
      this.processError(e);
    }
  };
}
