import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Subject } from 'rxjs';
import { FaxForm, IFaxPreview } from 'shared-code-lib';
import { UploadForm } from '../../views/upload/upload.component';
import { ApiService } from './api.service';
import { SpinnerStateService } from './spinner-state.service';

@Injectable({
  providedIn: 'root',
})
export class ContentPostService {
  itemSubscription = new Subject<Array<any>>();
  faxData: FaxForm;

  constructor(private api: ApiService, private spinner: SpinnerStateService, private translate: TranslateService) {}

  sendFax(spinnerElement: HTMLElement, faxData: FaxForm, onSuccess: Function, onFailure: Function) {
    this.spinner.show(this.translate.instant('SendFax.FaxSubmission'), spinnerElement);

    const formData = new FormData();
    const formDataItems = [];

    this.faxData = faxData;

    for (let i = 0; i < faxData.attachedItems.length; i++) {
      if (
        faxData.attachedItems[i].name &&
        faxData.attachedItems[i].size &&
        (faxData.attachedItems[i].lastModified || faxData.attachedItems[i].lastModifiedDate)
      ) {
        formData.append(i.toString(), faxData.attachedItems[i], faxData.attachedItems[i].name);
      } else {
        formDataItems.push(faxData.attachedItems[i]);
      }
    }

    const payloadObject = {
      ...faxData.serializable(),
      items: formDataItems,
      attachmentsCount: faxData.attachedItems.length,
    };
    const payloadString = JSON.stringify(payloadObject);

    formData.append('data', payloadString);
    this.api.postItemtoServer('Content/SendFax', formData).subscribe(
      (result: any) => onSuccess(result),
      (err: any) => onFailure(err)
    );
  }

  uploadFile(spinnerElement: HTMLElement, uploadData: UploadForm) {
    this.spinner.show(this.translate.instant('Upload.FileSubmission'), spinnerElement);

    const formData = new FormData();

    for (let i = 0; i < uploadData.attachedItems.length; i++) {
      formData.append(i.toString(), uploadData.attachedItems[i], uploadData.attachedItems[i].name);
    }

    const payloadObject = { ...uploadData, items: uploadData.attachedItems, files: [] };
    const payloadString = JSON.stringify(payloadObject);
    formData.append('data', payloadString);

    // Todo: clear the form after success
    // Todo: Create a variable set to false on initial and set to true when successful that tell system to clear form

    // this.api.postItemtoServer('Content/SendFile', formData).subscribe(this.sendfaxSucceeded, this.sendfaxFailed);
  }

  GetFaxPreview(faxData: FaxForm, onSuccess: (result: IFaxPreview) => void, onFailure: (err: any) => void) {
    const formData = new FormData();
    const payloadObject = { ...faxData.serializable(), items: [] };
    const payloadString = JSON.stringify(payloadObject);

    formData.append('data', payloadString);

    const files = payloadObject.attachedItems;
    for (let i = 0; i < files.length; i++) {
      formData.append('files', files[i]);
    }

    this.api.postItemtoServer('Content/GetFaxPreview', formData).subscribe(onSuccess, onFailure);
  }
}
