import {
  Component,
  OnInit,
  ElementRef,
  ViewChild,
  ViewEncapsulation,
  AfterViewInit,
  ChangeDetectorRef,
} from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';

import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { AuthService, PasswordResetResult } from '../../services/auth/auth.service';
import { DelayService } from './../../utils/delay.service';
import { Log } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { BrandDetails, BrandingService } from '../../services/branding.service';
import { Subscription } from 'rxjs';
import { FieldDefinition } from '../../models/field-definition';
import { MetaDataType } from '../../..';
import { Strings } from '../../utils/strings.service';

@Component({
  selector: 'app-password-help',
  templateUrl: './password-help.component.html',
  styleUrls: ['./password-help.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class PasswordHelpComponent implements OnInit, AfterViewInit {
  @ViewChild('passwordHelpComponent', { static: true }) loginDiv: ElementRef;

  fieldUsername: FieldDefinition;

  errorOccurred: boolean = false;
  errorText: string = '';
  passwordReset: boolean = false;

  username: string;
  savedUsername: string;

  logoColor: string;

  loginDivElement: HTMLElement;

  input: ElementRef;

  subscriptions = new Subscription();
  focusedInput: boolean;

  constructor(
    public translateService: TranslateService,
    private spinnerState: SpinnerStateService,
    private auth: AuthService,
    private delay: DelayService,
    private router: Router,
    private brandingService: BrandingService,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit() {
    this.updateBrandDetails(this.brandingService.getBrandDetails());
    this.subscriptions.add(this.brandingService.onBrandDetailsUpdated.subscribe(this.updateBrandDetails));

    this.loginDivElement = this.loginDiv.nativeElement;

    this.createPromptField(true);
  }
  ngAfterViewInit(): void {
    this.setFocusToInput();
  }

  createPromptField = (username: boolean): void => {
    //Login.Email
    this.fieldUsername = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant(username ? 'Login.Username' : 'Login.Email'),
      placeholder: '',
      required: false,
    });
  };

  updateBrandDetails = (bd: BrandDetails): void => {
    this.logoColor = bd?.loginLogoUrl;

    if (bd?.primaryColor) {
      document.documentElement.style.setProperty('--brand-primary-color', bd.primaryColor);
    }

    if (bd?.secondaryColor) {
      document.documentElement.style.setProperty('--brand-secondary-color', bd.secondaryColor);
    }
  };

  setFocusToInput = (): void => {
    this.focusedInput = null;
    this.delay.execute(() => {
      this.focusedInput = true;
    }, 100);
  };

  resetErrors = (): void => {
    this.errorOccurred = false;
    this.errorText = '';
  };

  login = (): void => {
    this.router.navigateByUrl('/');
  };

  reset = (): void => {
    if (Strings.isEmptyOrWhiteSpace(this.username)) return;
    let username = this.username;
    let email = '';

    if (this.savedUsername) {
      email = username;
      username = this.savedUsername;
    } else {
      this.savedUsername = username;
    }

    this.translateService.get('Login.RequestingResetPassword').subscribe((res) => {
      this.spinnerState.show(res, this.loginDivElement);
    });

    this.auth.requestPasswordReset(username, email, this.resetSucceeded, this.resetFailed);
  };

  resetSucceeded = (r: PasswordResetResult): void => {
    this.spinnerState.hide();
    this.errorOccurred = false;

    if (r.promptForEmail) {
      this.createPromptField(false);
      this.username = '';
      this.cdr.detectChanges();
    } else {
      this.passwordReset = true;
    }
    this.setFocusToInput();
  };

  resetFailed = (err): void => {
    Log.error('PasswordHelpComponent.resetFailed', err);

    this.spinnerState.hide();
    this.errorOccurred = true;

    this.errorText = this.translateService.instant('Login.ResetPasswordFailed');

    this.setFocusToInput();
  };
}
