import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class PrintPdfFileService {
  private showSubject = new BehaviorSubject(false);
  show$ = this.showSubject.asObservable();

  private pdfUrlSubject = new BehaviorSubject<string | null>(null);
  pdfUrl$ = this.pdfUrlSubject.asObservable();

  onFinishPrintFileCallback = () => {};

  constructor() {}

  printFile(url: string, onFinishPrintFileCallback = () => {}) {
    this.pdfUrlSubject.next(url);
    this.showSubject.next(true);
    this.onFinishPrintFileCallback = onFinishPrintFileCallback;
  }

  finishPrintFile() {
    this.onFinishPrintFileCallback?.();
    this.showSubject.next(false);
    this.pdfUrlSubject.next(null);
  }
}
