export class InterFAXFilters {
  public static Create = (f: IFilter): Filter => {
    if (f.id == 'InterFAX-Upland.Bamba.InterFAX.Administration.Contacts.FilterByContactProperty') {
      return new FilterByContactProperty(f);
    }

    if (f.id == 'InterFAX-Upland.Bamba.InterFAX.Inbox.Filtering.ByInterFAXUsername') {
      return new FilterByInterFAXUsername(f);
    }

    if (f.id == 'InterFAX-Upland.Bamba.InterFAX.Outbox.Filtering.ByInterFAXStatus') {
      return new ByInterFAXStatus(f);
    }

    if (f.id == 'InterFAX-Upland.Bamba.InterFAX.Outbox.Filtering.ByInterFAXProperty') {
      return new ByInterFAXProperty(f);
    }

    if (f.id == 'InterFAX-Upland.Bamba.InterFAX.Inbox.Filtering.ByInterFAXInboxProperties') {
      return new ByInterFAXInboxProperty(f);
    }

    if (f.id == 'InterFAX-Upland.Bamba.InterFAX.Administration.Invoices.BillingOpenFilter') {
      return new ByInterFAXTransactionStatus(f);
    }

    if (
      f.id == 'InterFAX-Upland.Bamba.InterFAX.Inbox.Filtering.ByInterFAXDateRange' ||
      f.id == 'InterFAX-Upland.Bamba.InterFAX.Administration.Widgets.FilterByInterFAXDateRange' ||
      f.id == 'BambaApplication-Upland.Bamba.Application.WorkItems.Filtering.FilterByPageUsageDate'
    ) {
      return new ByInterFAXDateRange(f);
    }

    if (f.id == 'InterFAX-Upland.Bamba.InterFAX.Administration.Widgets.FilterByInterFAXDateSelection') {
      return new ByInterFAXDateSelection(f);
    }

    if (f.id == 'InterFAX-Upland.Bamba.InterFAX.Administration.Contacts.ContactListTypeFilter') {
      return new ByInterFAXContactListType(f);
    }

    if (f.id === 'InterFAX-Upland.Bamba.InterFAX.Inbox.Filtering.ByInterFAXInboxSharedWith') {
      return new ByInterFAXInboxSharedWith(f);
    }

    return null;
  };
}
