export interface IContact {
  id: number;
  name: string;
  faxNumber: string;
  phoneNumber: string;
  company: string;
  contactListId: number;
}

export class Contact {
  public id: number;
  public name: string;
  public faxNumber: string;
  public phoneNumber: string;
  public company: string;
  public contactListId: number;

  constructor(c: IContact = null) {
    this.id = c ? c.id : 0;
    this.name = c ? c.name : '';
    this.faxNumber = c ? c.faxNumber : '';
    this.phoneNumber = c ? c.phoneNumber : '';
    this.company = c ? c.company : '';
    this.contactListId = c ? c.contactListId : undefined;
  }

  serializable(): IContact {
    return {
      id: this.id,
      name: this.name,
      faxNumber: this.faxNumber,
      phoneNumber: this.phoneNumber,
      company: this.company,
      contactListId: this.contactListId,
    };
  }
}
