import { Subject } from 'rxjs';
import { Annotation } from 'shared-code-lib';
import { BasicObject } from './capture-basic-object';

export enum PageState {
  Empty = 0,
  Loading = 1,
  Loaded = 2,
  FailedLoad = 3,
}
export class Page extends BasicObject {
  viewerURL: string;
  thumbnailURL: string;
  order: number;
  parentDocumentId: string;
  originalFile: File;
  tooltip: string;
  state: PageState;
  annotations: Annotation[];
  annotationsChanged: Subject<void>;

  constructor(order: number, parentDocumentId: string, annotations: Annotation[] = []) {
    super('page-' + order);
    this.order = order;
    this.parentDocumentId = parentDocumentId;
    this.state = PageState.Empty;
    this.annotations = annotations.map((a) => Annotation.create(a));
    this.annotationsChanged = new Subject<void>();
  }

  onAnnotationsChanged = (): void => {
    this.annotationsChanged.next();
  };
}
