export class Variables {
  [Key: string]: string;
}

export interface IGrouping {
  id: string;
  name: string;
  environmentId: string;
  variables: Variables;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
}

export class Grouping implements IGrouping {
  id: string;
  name: string;
  environmentId: string;
  variables: Variables = new Variables();
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;

  constructor(initializer: IGrouping) {
    this.id = initializer ? initializer.id : '';
    this.name = initializer ? initializer.name : '';
    this.variables = initializer && initializer.variables ? initializer.variables : new Variables();
    this.dateCreatedUTC = initializer ? initializer.dateCreatedUTC : null;
    this.dateModifiedUTC = initializer ? initializer.dateModifiedUTC : null;
    this.environmentId = initializer ? initializer.environmentId : '';
  }

  serializable = (): IGrouping => {
    return {
      id: this.id,
      name: this.name,
      variables: this.variables,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      environmentId: this.environmentId,
    };
  };
}

export interface IIFXEnvironment {
  id: string;
  name: string;
  variables: Variables;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  roleIds: Array<string>;
}

export class IFXEnvironment implements IIFXEnvironment {
  id: string;
  name: string;
  variables: Variables = new Variables();
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  roleIds: Array<string> = [];

  constructor(initializer: IIFXEnvironment) {
    this.id = initializer ? initializer.id : '';
    this.name = initializer ? initializer.name : '';
    this.variables = initializer && initializer.variables ? initializer.variables : new Variables();
    this.dateCreatedUTC = initializer ? initializer.dateCreatedUTC : null;
    this.dateModifiedUTC = initializer ? initializer.dateModifiedUTC : null;
    this.roleIds = initializer && initializer.roleIds ? initializer.roleIds : [];
  }

  serializable = (): IIFXEnvironment => {
    return {
      id: this.id,
      name: this.name,
      variables: this.variables,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      roleIds: this.roleIds,
    };
  };
}

export interface IMachine {
  id: string;
  name: string;
  groupingId: string;
  variables: Variables;
  installedComponents: Array<InstalledComponent>;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
}

export class Machine implements IMachine {
  id: string;
  name: string;
  groupingId: string;
  variables: Variables = new Variables();
  installedComponents: Array<InstalledComponent> = new Array<InstalledComponent>();
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;

  constructor(initializer: IMachine) {
    this.id = initializer ? initializer.id : '';
    this.name = initializer ? initializer.name : '';
    this.groupingId = initializer ? initializer.groupingId : '';
    this.variables = initializer && initializer.variables ? initializer.variables : new Variables();
    this.installedComponents =
      initializer && initializer.installedComponents
        ? initializer.installedComponents
        : new Array<InstalledComponent>();

    this.dateCreatedUTC = initializer ? initializer.dateCreatedUTC : null;
    this.dateModifiedUTC = initializer ? initializer.dateModifiedUTC : null;
  }

  serializable = (): IMachine => {
    return {
      id: this.id,
      name: this.name,
      groupingId: this.groupingId,
      variables: this.variables,
      installedComponents: this.installedComponents,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
    };
  };
}

export class InstalledComponent {
  componentId: string;
  version: string;
  dateInstalledUTC: Date;
  variables: Variables = new Variables();
  configuratorSettings: Variables = new Variables();

  constructor(initializer: any) {
    this.componentId = initializer ? initializer.componentId : '';
    this.version = initializer ? initializer.version : '';
    this.dateInstalledUTC = initializer ? initializer.dateInstalledUTC : new Date();
    this.variables = initializer && initializer.variables ? initializer.variables : new Variables();
    this.configuratorSettings =
      initializer && initializer.configuratorSettings ? initializer.configuratorSettings : new Variables();
  }
}
