import { AfterViewInit, ChangeDetectorRef, Component, Input, OnChanges, OnInit, SimpleChanges } from '@angular/core';

import { TranslateService } from '@ngx-translate/core';

import { Strings } from '../../utils/strings.service';
import { TextComponent } from '../text/text.component';

@Component({
  selector: 'app-hoverable-text-input',
  templateUrl: './hoverable-text-input.component.html',
  styleUrls: ['./hoverable-text-input.component.scss'],
})
export class HoverableTextInputComponent extends TextComponent implements OnChanges, OnInit, AfterViewInit {
  @Input() fieldId: string = '';

  showLabel = true;
  textInputWidthInPx: number;

  get truncatedValue() {
    return Strings.truncate(this.value, 30);
  }

  constructor(translateService: TranslateService, private cdr: ChangeDetectorRef) {
    super(translateService);
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.value || changes.setValue) {
      this.resizeInputElement();
    }
  }

  ngOnInit(): void {
    super.ngOnInit();
  }

  ngAfterViewInit(): void {
    super.ngAfterViewInit();
  }

  setFocused(isFocused: boolean): void {
    super.setFocused(isFocused, () => {
      this.showLabel = !isFocused;
      this.cdr.detectChanges();
    });
  }

  protected onChangeValue(value: string): void {
    super.onChangeValue(value);
    this.resizeInputElement();
  }

  onLabelFocus(event) {
    if (this.disabled) return;

    this.focused = true;
  }

  onLabelBlur(event) {}

  onReturnHandler(event: Event) {
    super.onReturn();
    super.onBlur(event);
  }

  resizeInputElement(maxWidthPx: number = 200) {
    const oneLetterWidth = Strings.getTextWidthPx(this.value?.[0] || 'A');
    const textInputLeftAndRightPadding = 24;

    this.textInputWidthInPx = Math.min(
      (Strings.getTextWidthPx(this.truncatedValue) || oneLetterWidth) + textInputLeftAndRightPadding,
      (Strings.getTextWidthPx(this.value) || oneLetterWidth) + textInputLeftAndRightPadding,
      maxWidthPx
    );
  }
}
