import { Component, Input } from '@angular/core';
import { Action } from '../../core/actions';
import { ActionButtonComponent } from '../action-button/action-button.component';

@Component({
  selector: 'app-action-color-button',
  templateUrl: './action-color-button.component.html',
  styleUrls: ['./action-color-button.component.scss'],
})
export class ColorActionButtonComponent extends ActionButtonComponent {
  @Input() disabled = false;
  @Input() title = '';
  @Input() action: Action;
  @Input() color: string = 'black';
  @Input() onChangeAction: Function;
  @Input() showOkButton: boolean = false;
  @Input() oKButtonText: string;
  @Input() showCancelButton: boolean = false;
  @Input() cancelButtonText: string;
  @Input() showLabel: boolean = false;

  colorChanged = (): void => {
    if (this.onChangeAction) this.onChangeAction(this.color);
  };
}
