import { AfterViewInit, Component, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { SafeResourceUrl } from '@angular/platform-browser';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { DelayService, FieldDefinition, MetaDataType } from 'shared-code-lib';
import { IntegratedApplication, IntegratedApplicationSettings } from '../../models/integrated-application';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResult } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-integrated-app-properties',
  templateUrl: './integrated-app-properties.component.html',
  styleUrls: ['./integrated-app-properties.component.scss'],
})
export class IntegratedAppPropertiesComponent implements OnInit, AfterViewInit {
  @ViewChild('spinnerElement', { static: true })
  spinnerElement;

  @Output() closeModal = new EventEmitter();

  fieldIntegratedAppUserName: FieldDefinition;
  fieldIntegratedAppSecret: FieldDefinition;

  integratedApplication: IntegratedApplication;
  integratedAppSettings: IntegratedApplicationSettings;
  integratedErrors: string[];

  authorizingOAuthIntegration = false;
  oauthAuthorizationUrl: SafeResourceUrl;
  showIntegratedAppSettingsModalBody: boolean;

  title: string;
  actionButtonText: string;

  constructor(
    private translateService: TranslateService,
    private spinnerStateService: SpinnerStateService,
    private ngxSmartModalService: NgxSmartModalService,
    private userStateService: UserStateService,
    private delayService: DelayService,
    private toastrService: ToastrService,
    private hydraApi: HydraApiService,
    private shareDataService: SharedDataService
  ) {}

  ngOnInit(): void {
    this.integratedAppSettings = this.userStateService.getIntegratedApplicationSettingsFor(
      this.shareDataService.extraParameters.application
    );
    this.integratedApplication = this.userStateService.integratedApplications.find(
      (ia) => ia.application == this.shareDataService.extraParameters.application
    );

    const titleResource = this.translateService.instant('MainHeader.update-itegrated-app-settings');
    this.title = titleResource.replace('{{application}}', this.integratedApplication.applicationDisplayName);

    this.loadUI();
  }

  ngAfterViewInit(): void {}

  createFields = (): void => {
    this.fieldIntegratedAppUserName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('MainHeader.field-app-username'),
      placeholder: this.translateService.instant('MainHeader.field-app-username-placeholder'),
      required: true,
    });

    this.fieldIntegratedAppSecret = new FieldDefinition({
      type: MetaDataType.Password,
      label: this.translateService.instant('MainHeader.field-app-secret'),
      placeholder: this.translateService.instant('MainHeader.field-app-secret-placeholder'),
      required: true,
    });
  };

  loadUI = (): void => {
    if (this.integratedAppSettings.application == 'OneDrive') {
      this.actionButtonText = this.translateService.instant('oauth.authorize');

      this.authorizingOAuthIntegration = true;

      const stateObj = { a: 'OneDrive', r: '/' };
      const redirectUri = encodeURI(`${window.location.origin}/oauth-redirect`);
      const state = btoa(JSON.stringify(stateObj));

      const clientId = this.integratedApplication.data.get('clientId').value as string;

      this.oauthAuthorizationUrl = `https://login.microsoftonline.com/common/oauth2/authorize?prompt=select_account&response_type=code&client_id=${clientId}&redirect_uri=${redirectUri}&State=${state}`;
    } else {
      this.actionButtonText = this.translateService.instant('MainHeader.Save');
      this.createFields();
      this.integratedErrors = [];
      this.showIntegratedAppSettingsModalBody = true;
    }
  };

  cancelUpdateIntegratedAppSettings = (): void => {
    this.close();
  };

  close = (): void => {
    this.showIntegratedAppSettingsModalBody = false;
    this.closeModal.emit();
  };

  updateIntegratedAppSettings() {
    if (this.authorizingOAuthIntegration) {
      window.location.href = this.oauthAuthorizationUrl.toString();
    } else {
      this.integratedErrors = [];

      this.spinnerStateService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);

      this.hydraApi.updateIntegratedApplicationSettings(
        this.integratedAppSettings,
        this.onIntegratedAppSettingsSaved,
        this.onIntegratedAppSettingsFailed
      );
    }
  }

  onIntegratedAppSettingsSaved = (result: ApiResult): void => {
    if (result && !result.success) {
      this.integratedErrors = result.errors;
      this.spinnerStateService.hide();
      return;
    }

    this.spinnerStateService.hide();
    this.toastrService.success(this.translateService.instant('MainHeader.saved-integrated-app-settings'));

    this.userStateService.updateIntegratedApplicationSettings(this.integratedAppSettings);

    this.showIntegratedAppSettingsModalBody = false;
    this.close();

    this.userStateService.loadUserProfile();
    this.shareDataService.actionHandler.reload.emit(false);
  };

  onIntegratedAppSettingsFailed = (err: any): void => {
    this.integratedErrors = ['MainHeader.failed-updated-integrated-app-settings'];
    this.spinnerStateService.hide();
  };

  onOAuthCancelled = () => {
    this.authorizingOAuthIntegration = false;

    this.close();
  };
}
