import {
  Component,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { Subject, Subscription } from 'rxjs';
import { distinctUntilChanged } from 'rxjs/operators';
import {
  ColumnDisplayType,
  Contact,
  ContactList,
  ContactListSearchType,
  FieldDefinition,
  FixedDataSource,
  ICombinedColumn,
  IFieldOptions,
  IInterFAXService,
  Individual,
  MetaDataType,
  RecipientContainer,
  TableItem,
} from 'shared-code-lib';

declare const $: any;

@Component({
  selector: 'app-search-contacts-modal',
  templateUrl: './search-contacts-modal.component.html',
  styleUrls: ['./search-contacts-modal.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class SearchContactsModalComponent implements OnInit, OnChanges, OnDestroy {
  @Input() interfaxService: IInterFAXService;
  @Input() contactLists: ContactList[] = [];
  @Output() onCloseModal = new EventEmitter<void>();
  @Output() onSaveModal = new EventEmitter<RecipientContainer<Individual>[]>();
  @ViewChild(PerfectScrollbarDirective) tableScrollbar: PerfectScrollbarDirective;

  title = '';
  errors: string[] = [];

  fieldRecipients: FieldDefinition;
  _recipients: RecipientContainer<Individual>[] = [];
  get recipients() {
    return this._recipients;
  }
  set recipients(val: RecipientContainer<Individual>[]) {
    this._recipients = val;
    this.searchItems = [...this.searchItems];
    this.tableScrollbar.update();
  }

  fieldContactLists: FieldDefinition;
  _selectedContactList = '';
  get selectedContactList() {
    return this._selectedContactList;
  }
  set selectedContactList(val: string) {
    if (val !== this.selectedContactList) this.forceSearch = true;

    this._selectedContactList = val;
    this.searchQuerySubject.next(this.searchQuery);
  }

  fieldPropertyToSearch: FieldDefinition;
  propertyToSearch: ContactListSearchType = ContactListSearchType.Auto;
  get searchProperty() {
    return `${this.propertyToSearch}`;
  }
  set searchProperty(val: string) {
    const newSearchProperty = Number(val);
    if (newSearchProperty !== this.propertyToSearch) this.forceSearch = true;

    this.propertyToSearch = newSearchProperty;
    this.searchQuerySubject.next(this.searchQuery);
  }

  fieldSearchText: FieldDefinition;
  private _searchQuery = '';
  forceSearch = false;
  searchQuerySubject = new Subject<string>();
  get searchQuery() {
    return this._searchQuery;
  }
  set searchQuery(value) {
    this._searchQuery = value;
    this.searchQuerySubject.next(value);
  }

  columns: ICombinedColumn[] = [];

  _searchItems: TableItem[] = [];
  get searchItems() {
    return this._searchItems;
  }
  set searchItems(val) {
    this._searchItems = val;
    this.tableScrollbar.update();
  }

  isLoading: string[] = [];

  subscriptions = new Subscription();

  constructor(private translate: TranslateService) {}

  ngOnInit(): void {
    this.title = this.translate.instant('search-contacts-modal.title');

    this.createFields();

    this.columns = this.getColumns();

    this.subscriptions.add(
      this.searchQuerySubject
        .pipe(
          distinctUntilChanged((prev, curr) => {
            if (this.forceSearch) {
              this.forceSearch = false;
              return false;
            }
            return prev === curr;
          })
        )
        .subscribe((s) => {
          this.isLoading.push(s);
          this.interfaxService.searchContactLists(
            s,
            this.propertyToSearch,
            this.selectedContactList,
            (contacts) => {
              this.searchItems = contacts.map((c) => new TableItem(c, this.columns, this.translate));
              this.recipients.forEach((r) => {
                const currentItem = this.searchItems.find((sI) => (sI.data as Contact).id == r.value.id);

                if (currentItem) currentItem.selected = true;
              });

              this.isLoading = this.isLoading.filter((loadText) => loadText != s);
              this.errors = [];
            },
            (error) => {
              this.errors = error;
              this.searchItems = [];

              this.isLoading = this.isLoading.filter((loadText) => loadText != s);
            }
          );
        })
    );
  }

  ngOnChanges(): void {
    this.createFields();
  }

  onTableSelectionChanged = () => {
    const currentItems = this.searchItems;
    this.recipients = this.recipients.filter((r) => {
      const currentItem = currentItems.find((cI) => (cI.data as Contact).id == r.value.id);
      if (!currentItem) return true;

      return currentItem.selected;
    });
    const selectedItems = currentItems.filter((ti) => ti.selected);
    const newRecipients: RecipientContainer<Individual>[] = selectedItems
      .filter((sI) => !this.recipients.find((r) => r.value.id == (sI.data as Contact).id))
      .map((sI) => {
        const contact = sI.data as Contact;
        return new Individual(
          contact.name,
          contact.faxNumber,
          contact.company,
          contact.phoneNumber,
          '',
          contact.id,
          contact.contactListId
        );
      })
      .map((i) => ({ value: i, display: i.getDisplayName() }));

    this.recipients = [...this.recipients, ...newRecipients];
  };

  onTagInputItemRemoved = (val: RecipientContainer<Individual>) => {
    const recipient = val.value;
    this.searchItems
      .filter((sI) => sI.data.id == recipient.id)
      .forEach((sI) => {
        sI.selected = false;
      });
  };

  createFields = () => {
    this.fieldRecipients = new FieldDefinition({
      type: MetaDataType.Text,
      placeholder: this.translate.instant('search-contacts-modal.no-recipients-added'),
    });

    const sortedContactLists = this.contactLists
      .sort((a, b) => a.name.localeCompare(b.name))
      .map((cl) => ({ name: cl.name, value: cl.id }));

    const contactListOptions: IFieldOptions[] = [
      {
        name: this.translate.instant('search-contacts-modal.field-contact-lists-none'),
        value: '-1',
      },
      ...sortedContactLists,
    ];

    this.fieldContactLists = new FieldDefinition({
      type: MetaDataType.List,
      placeholder: this.translate.instant('search-contacts-modal.field-contact-lists-placeholder'),
      datasource: new FixedDataSource(contactListOptions),
      defaultValue: '-1',
    });

    let searchPropertyOptions: IFieldOptions[] = [
      {
        name: this.translate.instant('search-contacts-modal.field-search-property.name'),
        value: `${ContactListSearchType.Name}`,
      },
      {
        name: this.translate.instant('search-contacts-modal.field-search-property.fax-number'),
        value: `${ContactListSearchType.FaxNumber}`,
      },
      {
        name: this.translate.instant('search-contacts-modal.field-search-property.company'),
        value: `${ContactListSearchType.Company}`,
      },
    ];
    this.fieldPropertyToSearch = new FieldDefinition({
      type: MetaDataType.List,
      placeholder: this.translate.instant('search-contacts-modal.field-search-property-placeholder'),
      datasource: new FixedDataSource(searchPropertyOptions),
      defaultValue: `${ContactListSearchType.Name}`,
    });

    this.fieldSearchText = new FieldDefinition({
      type: MetaDataType.Text,
      placeholder: this.translate.instant('search-contacts-modal.field-search-text-placeholder'),
      required: false,
    });
  };

  getColumns = (): ICombinedColumn[] => {
    let cols: ICombinedColumn[] = [
      this.createColumn(
        'name',
        this.translate.instant('search-contacts-modal.field-search-property.name'),
        40,
        true,
        ColumnDisplayType.Text
      ),
      this.createColumn(
        'company',
        this.translate.instant('search-contacts-modal.field-search-property.company'),
        20,
        true,
        ColumnDisplayType.Text
      ),
      this.createColumn(
        'faxNumber',
        this.translate.instant('search-contacts-modal.field-search-property.fax-number'),
        20,
        true,
        ColumnDisplayType.Text
      ),
    ];

    return cols;
  };

  createColumn = (
    field: string,
    headerText: string,
    width: number,
    stretch: boolean,
    displayType: ColumnDisplayType
  ): ICombinedColumn => ({
    id: `column_${field}`,
    width: width,
    stretch: stretch,
    displayType: displayType,
    headerImage: '',
    headerText: headerText,
    itemProperty: field,
    columnName: field,
    sortable: false,
    sortByFieldName: '',
    invertBooleanValue: false,
  });

  onCancel = () => {
    this.onCloseModal.emit();
  };

  onAdd = () => {
    this.onSaveModal.emit(this.recipients);
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
