import {
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  SimpleChanges,
  ViewChild,
  ViewContainerRef,
  ViewEncapsulation,
} from '@angular/core';

import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { BehaviorSubject, Subscription } from 'rxjs';
import { debounceTime, distinctUntilChanged } from 'rxjs/operators';

import { DeviceDetectorService } from 'ngx-device-detector';
import { DocumentEventsService } from '../../../../Bamba.Web/ClientApp/src/app/views/document-capture/capture-services/document-events.service';
import { DropDownDirection } from '../../models/drop-down';
import { LookupMatch } from '../../models/lookup-models';
import { FieldDefinition, IFieldOptions } from './../../models/field-definition';
import { MetaDataValidity } from './../../models/metadata';
import { DelayService } from './../../utils/delay.service';
import { Key } from './../../utils/key-enum';
import { DropDownComponent } from './drop-down/drop-down.component';
import { DropDownService } from './drop-down/drop-down.service';
import { ListService } from './list.service';

@Component({
  selector: 'app-list',
  templateUrl: './list.component.html',
  styleUrls: ['./list.component.scss'],
  encapsulation: ViewEncapsulation.None,
  providers: [DropDownService],
})
export class ListComponent implements OnInit, OnChanges, OnDestroy {
  @ViewChild('selectedValueContainer', { static: true })
  selectedValueContainer: ElementRef;
  @ViewChild('dropDownWrapper', { static: true })
  dropDownWrapper: ElementRef;
  @Input() value: string;
  @Input() field: FieldDefinition;
  @Input() disabled: boolean;
  @Input() validity: number;
  @Input() displayAsList: boolean = false;
  @Input() fieldTabIndex = 0;
  @Input() fieldId: string = '';
  @Input() autocomplete: string = 'on';

  @Input()
  set focused(isFocused: boolean) {
    if (isFocused) {
      this.selectedValueContainer.nativeElement.focus();
      this.isCurrentField = true;
    } else {
      this.selectedValueContainer.nativeElement.blur();
      this.isCurrentField = false;
    }
  }

  @Input()
  set setValue(value: string) {
    if (value) {
      this.checkValues(value);
    }
  }

  @Input() triggerBlurEventOnLoad: boolean = true;
  @Input() resetValueIfNotExist: boolean = true;
  @Input() valueMapper: (value: string) => string;

  @Output() fieldFocus = new EventEmitter();
  @Output() fieldBlur = new EventEmitter<string>();
  @Output() fieldOnTab = new EventEmitter<any>();
  @Output() fieldOnShiftTab = new EventEmitter<any>();
  @Output() fieldChanged = new EventEmitter<string>();
  @Output() optionFieldChanged = new EventEmitter<IFieldOptions>();
  @Output() setLookupRowMatch = new EventEmitter<Array<LookupMatch>>();

  matchingCount: number;
  isCurrentField: boolean;
  isMenuVisible: boolean;
  options = new BehaviorSubject<Array<IFieldOptions>>([]);
  filtered: Array<IFieldOptions> = [];
  searchTerm = new BehaviorSubject<string>('');
  metaDataValidity = MetaDataValidity;
  datasourceChanged: Subscription;
  direction: string = '';
  term = '';
  selectedOption: IFieldOptions;
  browserAutofill = false;

  subscriptions: Subscription;

  get loading() {
    return this.listService.getLoading(this.fieldId);
  }

  get isFirefox() {
    return this.deviceDetector.browser.toLowerCase() === 'firefox';
  }

  constructor(
    private viewContainerRef: ViewContainerRef,
    public translate: TranslateService,
    private toastr: ToastrService,
    public dropDown: DropDownService,
    private delay: DelayService,
    private documentEvents: DocumentEventsService,
    private cdr: ChangeDetectorRef,
    private listService: ListService,
    private deviceDetector: DeviceDetectorService
  ) {
    this.subscriptions = new Subscription();
  }

  ngOnInit() {
    if (this.field.datasource) {
      this.reloadListItems(null);

      this.subscriptions.add(
        this.searchTerm.pipe(debounceTime(300), distinctUntilChanged()).subscribe((term) => {
          this.term = term;
          this.reloadListItems(this.term);
        })
      );

      this.subscriptions.add(
        this.field.datasource.changed.subscribe(() => {
          this.reloadListItems(this.term);
        })
      );
    }

    this.subscriptions.add(
      this.dropDown.onSelectViaClick.subscribe((option) => {
        this.dropDown.hide();
        this.selectValue(option, true);
      })
    );

    this.subscriptions.add(
      this.dropDown.onTab.subscribe((event: KeyboardEvent) => {
        if (this.isMenuVisible) {
          this.onKey(event);
        }
      })
    );

    this.subscriptions.add(
      this.dropDown.onHide.subscribe((event) => {
        this.onHide();
      })
    );

    this.subscriptions.add(
      this.documentEvents.onDocumentKeyDownSubject.subscribe((event: KeyboardEvent) => {
        if (event.key === Key.Escape) {
          this.dropDown.hide();
        }
      })
    );

    this.subscriptions.add(
      this.dropDown.onDirectionChanged.subscribe((direction: DropDownDirection) => {
        this.direction = DropDownDirection[direction];
      })
    );
  }

  onAutofillChange(value: string) {
    const mappedValue = this.valueMapper ? this.valueMapper(value) : value;
    this.checkValues(mappedValue, false, true);
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (
      changes.value &&
      changes.value.currentValue == '' &&
      changes.value.currentValue != changes.value.previousValue
    ) {
      this.checkValues(changes.value.currentValue);
    }

    if (!this.isMenuVisible || !changes.validity) return;

    this.dropDown.update({
      component: DropDownComponent,
      data: {
        value: this.value,
        disabled: this.disabled,
        options: this.options,
        searchTerm: this.searchTerm,
        parent: this.dropDownWrapper.nativeElement,
        idPrefix: `field-list-${this.field.label}`,
        validity: this.validity,
      },
    });
  }

  ngOnDestroy() {
    if (this.datasourceChanged) {
      this.datasourceChanged.unsubscribe();
    }

    if (this.isMenuVisible) {
      this.dropDown.hide();
    }

    this.subscriptions.unsubscribe();
  }

  onSearchStarted = (event: KeyboardEvent): void => {
    this.searchTerm.next(event.key);
  };

  onDisplay = (): void => {
    this.fieldFocus.emit();
    this.focused = true;
    if (this.field.allowNoSelection) this.addNoSelectionOption();
    if (!this.isMenuVisible) {
      this.dropDown.show(
        {
          component: DropDownComponent,
          data: {
            value: this.value,
            disabled: this.disabled,
            options: this.options,
            searchTerm: this.searchTerm,
            parent: this.dropDownWrapper.nativeElement,
            idPrefix: `field-list-${this.field.label}`,
            validity: this.validity,
            fireChangeEventIfSameValue: this.field.fireChangeEventIfSameValue,
          },
        },
        this.viewContainerRef
      );
    }

    this.isMenuVisible = true;
  };

  onHide() {
    if (this.isCurrentField) {
      this.selectedValueContainer.nativeElement.focus();
      this.focused = true;
    }

    this.dropDown.hide();
    this.isMenuVisible = false;
  }

  addNoSelectionOption = (): void => {
    if (!this.filtered || this.filtered.find((x) => x.name == '' && x.value == '')) return;

    this.filtered.unshift({ name: '', value: '' } as IFieldOptions);
  };

  reloadListItems = (update: any): void => {
    this.options.next(null);
    this.listService.setLoading(this.fieldId, true);
    this.field.datasource.getItems(
      this.term,
      this.value,
      (a, m) => this.optionsLoadSucceeded(a, m),
      this.optionsLoadFailed
    );
  };

  optionsLoadSucceeded = (items: Array<IFieldOptions>, matches: Array<LookupMatch>): void => {
    this.filtered = [];
    this.filtered.push(...items.filter((i) => i.name.trim().length));
    this.filtered = this.filtered.filter((v, i, a) => a.findIndex((t) => t.value === v.value) === i);
    this.matchingCount = items.length;
    this.options.next(this.filtered);

    if (this.resetValueIfNotExist && this.filtered.find((o) => o.value?.toString() == this.value?.toString()) == null) {
      this.value = this.selectedOption?.value ?? this.field.defaultValue;
    }

    if (this.triggerBlurEventOnLoad) this.fieldBlur.emit(this.value);

    this.checkValues(this.value, false);

    if (this.displayAsList) this.setLookupRowMatch.emit(matches);

    this.listService.setLoading(this.fieldId, false);

    this.cdr.detectChanges();
  };

  optionsLoadFailed = (err): void => {
    if (err != null) {
      const failureMessage: string = this.translate.instant('Common.FailedLoadListItems');
      this.toastr.warning(failureMessage.replace('{fieldname}', this.field.label));
    }

    this.value = '';
    this.fieldBlur.emit(this.value);

    this.listService.setLoading(this.fieldId, false);
  };

  onFocus() {
    this.fieldFocus.emit();
  }

  onBlur() {
    this.delay.execute(() => {
      if (!this.isMenuVisible) {
        this.focused = false;
      }
    }, 5);
  }

  get selectedValue(): string {
    if (this.loading) return this.translate.instant('Common.Searching');

    if (this.field.stickyHeader) return this.field.stickyHeader;
    if (this.value) this.selectedOption = this.filtered.find((x) => x.value == this.value);

    const value =
      this.selectedOption && this.value != null
        ? this.selectedOption.name
        : !this.field.label && this.field.placeholder
          ? this.field.placeholder
          : '';

    const element = this.selectedValueContainer.nativeElement;
    element.parentNode.title = element.offsetWidth < element.scrollWidth ? value : '';

    return value;
  }

  selectAdjacentValue = (distance: number): void => {
    if (this.value == null && this.filtered && this.filtered.length > 0) {
      this.selectValue(this.filtered[0]);
      return;
    }

    if (this.value != null && this.filtered) {
      for (var i = 0; i < this.filtered.length; i++) {
        if (this.value == this.filtered[i].value) {
          const index = i + distance;
          if (i < 0 || i >= this.filtered.length) return;
          this.selectValue(this.filtered[index]);
          break;
        }
      }
    }
  };

  onKey = (event: KeyboardEvent): void => {
    if (this.disabled) return;

    if (event.key === Key.Tab) {
      this.confirmSuspicious();

      if (event.shiftKey) {
        this.fieldOnShiftTab.emit(this.value);
        return;
      }

      this.fieldOnTab.emit(this.value);
    } else {
      if (this.isMenuVisible) {
        this.dropDown.arrowUpDown(event);
      } else {
        if (event.key === Key.ArrowUp) {
          this.selectAdjacentValue(-1);
        } else if (event.key === Key.ArrowDown) {
          this.selectAdjacentValue(1);
          this.onDisplay();
        } else if (event.key === Key.Enter) {
          this.onDisplay();
        }
      }
    }
  };

  confirmSuspicious = (): boolean => {
    if (this.validity !== MetaDataValidity.suspicious) {
      return false;
    }

    this.fieldBlur.emit(<any>this.value);

    return true;
  };

  handleOnTab(event: KeyboardEvent) {
    this.confirmSuspicious();

    if (event.shiftKey) {
      this.fieldOnShiftTab.emit(this.value);
      return;
    }

    this.fieldOnTab.emit(this.value);
  }

  checkValues(value: string, hideDropDown = true, isBrowserAutofill = false) {
    const _option: IFieldOptions = this.filtered.find((option) => option.value?.toString() == value?.toString());

    if (_option) {
      this.selectValue(_option, hideDropDown, isBrowserAutofill);
    } else if (!value) {
      this.selectedOption = null;
      this.value = value;
    }
  }

  selectValue(option: any, hideDropDown?: boolean, isBrowserAutofill?: boolean) {
    this.browserAutofill = isBrowserAutofill;
    this.selectedOption = option;

    const valueDidNotChange =
      this.value?.toString() === option.value?.toString() && !this.field.fireChangeEventIfSameValue;

    if (this.loading || valueDidNotChange) return;

    this.optionFieldChanged.emit(option);

    this.fieldChanged.emit(option.value);

    this.fieldBlur.emit(option.value);
    this.value = option.value;

    if (hideDropDown) {
      this.dropDown.hide();

      this.delay.execute(() => {
        this.selectedValueContainer.nativeElement.focus();
      }, 10);
    }
  }
}
