import { Injectable, EventEmitter } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

export class ProgressData {
  constructor(public text: string, public finished: number = 0, public total: number = 0) {}

  get percentage(): number {
    if (!this.total) return 0;
    return Math.round((this.finished / this.total) * 100);
  }

  get showProgress(): boolean {
    return this.total > 1;
  }
}

@Injectable({
  providedIn: 'root',
})
export class InProgressService {
  onDisplay = new EventEmitter<ProgressData>();
  onClose = new EventEmitter();
  onOpen = new EventEmitter<string>();

  constructor(private translate: TranslateService) {}

  open = (text: string): void => {
    this.onOpen.emit(text);
  };

  close = (): void => {
    this.onClose.emit();
  };

  display = (text: string, translateText: boolean = true): void => {
    if (translateText) text = this.translate.instant(text);
    this.onDisplay.emit(new ProgressData(text));
  };

  displayProgress = (text: string, finished: number, total: number, translateText: boolean = true): void => {
    if (translateText) text = this.translate.instant(text);
    this.onDisplay.emit(new ProgressData(text, finished, total));
  };
}
