import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';
import { ITenant } from '../models/tenant';

export const storageKeys = {
  ISMOBILE: 'isMobile',
  ISINTERFAXMOBILE: 'isInterFaxMobile',
  RETURNURL: 'returnUrl',
  TOKEN: 'token',
  USERNAME: 'login-state-username',
  TENANTS: 'login-state-tenants',
  OAUTH_STATE: 'oauth-state',
  LANDINGDOMAIN: 'landing-domain',
  LOGINMODE: 'login-mode',
  ISPRINTRELOAD: 'is-print-reload',
  ISAPPRELOAD: 'is-app-reload',
  CURRENTACTIONID: 'current-action-id',
};

@Injectable({
  providedIn: 'root',
})
export class SessionStorageService {
  private _isInterFaxMobileSubject = new Subject<boolean>();
  public onIsInterFaxMobileChanged = this._isInterFaxMobileSubject.asObservable();

  constructor() {}

  setOAuthState(state: any) {
    this.setItem(storageKeys.OAUTH_STATE, JSON.stringify(state));
  }

  getOAuthState(): any {
    return JSON.parse(this.getItem(storageKeys.OAUTH_STATE));
  }

  setLandingDomain(value: string): void {
    this.setItem(storageKeys.LANDINGDOMAIN, value);
  }

  getLandingDomain(): string {
    return this.getItem(storageKeys.LANDINGDOMAIN);
  }

  setIsMobile(value: boolean): void {
    this.setItem(storageKeys.ISMOBILE, value);
  }

  getIsMobile(): boolean {
    return !!this.getItem(storageKeys.ISMOBILE);
  }

  removeIsMobile(): void {
    this.removeItem(storageKeys.ISMOBILE);
  }

  setIsInterFaxMobile(value: boolean): void {
    this.setItem(storageKeys.ISINTERFAXMOBILE, value);
    this._isInterFaxMobileSubject.next(value);
  }

  getIsInterFaxMobile(): boolean {
    return !!this.getItem(storageKeys.ISINTERFAXMOBILE);
  }

  setReturnUrl(value: string): void {
    this.setItem(storageKeys.RETURNURL, !value ? '' : value);
  }

  getReturnUrl(): string {
    return this.getItem(storageKeys.RETURNURL);
  }

  setLoginMode(value: string): void {
    this.setItem(storageKeys.LOGINMODE, !value ? '' : value);
  }

  getLoginMode(): string {
    return this.getItem(storageKeys.LOGINMODE) ?? '';
  }

  setToken(value: string): void {
    this.setItem(storageKeys.TOKEN, value);
  }

  getToken(): string {
    return this.getItem(storageKeys.TOKEN);
  }

  removeToken(): void {
    this.removeItem(storageKeys.TOKEN);
  }

  setTenantsList(tenants: ITenant[]): void {
    this.setItem(storageKeys.TENANTS, tenants);
  }

  getTenantsList(): ITenant[] {
    return this.getItem(storageKeys.TENANTS);
  }

  setUsername(userName: string): void {
    this.setItem(storageKeys.USERNAME, userName);
  }

  getUsername(): string {
    return this.getItem(storageKeys.USERNAME);
  }

  setIsPrintReload(isPrintReload: boolean) {
    this.setItem(storageKeys.ISPRINTRELOAD, isPrintReload);
  }

  getIsPrintReload(): boolean {
    return this.getItem(storageKeys.ISPRINTRELOAD);
  }

  setIsAppReload(isAppRedirect: boolean) {
    this.setItem(storageKeys.ISAPPRELOAD, isAppRedirect);
  }

  getIsAppReload(): boolean {
    return this.getItem(storageKeys.ISAPPRELOAD);
  }

  setCurrentActionId(id: string) {
    this.setItem(storageKeys.CURRENTACTIONID, id);
  }

  getCurrentActionId(): string {
    return this.getItem(storageKeys.CURRENTACTIONID);
  }

  private setItem(key: string, value: any): void {
    sessionStorage.setItem(key, JSON.stringify(value));
  }

  private getItem(key: string): any {
    return JSON.parse(sessionStorage.getItem(key));
  }

  private removeItem(key: string): void {
    sessionStorage.removeItem(key);
  }

  logoutSession = (): void => {
    Object.keys(storageKeys)
      .filter((k) => storageKeys[k] != storageKeys.LANDINGDOMAIN)
      .forEach((k) => this.removeItem(storageKeys[k]));
  };

  clear = (): void => {
    sessionStorage.clear();
  };
}
