import { Component, OnInit, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

import { TranslateService } from '@ngx-translate/core';

import { BambaDetailsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/bamba-details.service';
import { HydraApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { AuthService } from '../../services/auth/auth.service';
import { BrandingService } from '../../services/branding.service';
import { SessionStorageService } from '../../services/session-storage.service';
import { AuthorizationResult, LoginBaseComponent } from '../login-base/login-base.component';

@Component({
  selector: 'app-saml-callback',
  templateUrl: './saml-callback.component.html',
  styleUrls: ['./saml-callback.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class SamlCallbackComponent extends LoginBaseComponent implements OnInit {
  loginErrorText: string = '';

  constructor(
    protected sessionStorageService: SessionStorageService,
    authService: AuthService,
    userStateService: UserStateService,
    spinnerStateService: SpinnerStateService,
    translateService: TranslateService,
    bds: BambaDetailsService,
    bs: BrandingService,
    r: Router,
    protected route: ActivatedRoute,
    protected api: HydraApiService
  ) {
    super(api, spinnerStateService, translateService, authService, bds, userStateService, sessionStorageService, bs, r);
  }

  ngOnInit(): void {
    super.ngOnInit();

    this.spinnerStateService.show(this.translateService.instant('Login.authenticating'), document.documentElement);

    this.authService.samlAuthenticate(this.route.snapshot.queryParams['jwt'], this.authenticated, this.failed);
  }

  authenticated = (ar: AuthorizationResult): void => {
    this.spinnerStateService.hide();
    if (ar.succeeded) {
      this.authService.setSession(ar);

      if (ar.tenants && ar.tenants.length > 0) {
        this.sessionStorageService.setTenantsList(ar.tenants);
        this.router.navigateByUrl('/login-tenants');
      } else {
        this.router.navigate(['/login-complete']);
      }
    } else {
      this.loginErrorText = ar.errorText;
    }
  };

  failed = (e): void => {
    this.spinnerStateService.hide();
    this.loginErrorText = e.toString();
  };
}
