import { Component, Input, OnInit } from '@angular/core';

export class WizardBarPage {
  public title: string;
  public id: string;

  constructor(id: string, title: string) {
    this.id = id;
    this.title = title;
  }
}
@Component({
  selector: 'app-wizard-bar',
  templateUrl: './wizard-bar.component.html',
  styleUrls: ['./wizard-bar.component.scss'],
})
export class WizardBarComponent implements OnInit {
  @Input() pages: Array<WizardBarPage>;
  @Input() selectedPage: number;

  constructor() {}

  ngOnInit(): void {}
}
