import { Injectable, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { Subject, Subscription } from 'rxjs';
import { map } from 'rxjs/operators';
import { ApiService } from './api.service';
import { ApiResult, Folder, IFolder, IProduct, Product, User, UserTypes } from './models';

import { ActivatedRoute } from '@angular/router';
import { DEFAULT_INTERRUPTSOURCES, Idle } from '@ng-idle/core';
import * as moment from 'moment';
import { DeviceDetectorService } from 'ngx-device-detector';
import {
  AuthService,
  Feature,
  IFeatureAvailableService,
  IFindMetaDataById,
  IMetaDataDefinition,
  MeasurementSettings,
  MetaDataDefinition,
  Role,
  RolePermissions,
  SessionStorageService,
} from 'shared-code-lib';
import {
  IIntegratedApplicationSettings,
  IntegratedApplication,
  IntegratedApplicationSettings,
} from './../models/integrated-application';
import { IUserProfile } from './../models/user-profile';
import { HydraApiEventService } from './hydra-api-event.service';
import { HydraApiService } from './hydra-api.service';

const AUTHORITY = 'sso-authority';

@Injectable({
  providedIn: 'root',
})
export class UserStateService implements OnDestroy, IFindMetaDataById, IFeatureAvailableService {
  user: User;
  userRoles = new Array<Role>();
  userFeatures = new Array<string>();
  integratedApplications = new Array<IntegratedApplication>();

  actionPanelLeft: any = [];
  actionPanelRight: any = [];
  viewDropDown: any = [];
  selectedItems: any = [];
  forceReloadFoldersIds: string[] = [];
  private locale: string;

  userChanged = new Subject<User>();

  public localeChanged = new Subject<string>();
  public selectedItemsChanged = new Subject<any>();
  public userProfileLoaded = new Subject<void>();
  public accountchanged = new Subject<void>();

  public userProfileChanged = new Subject<IUserProfile>();
  public userProfile: IUserProfile = null;

  public LastSelectedWorkflowId: string;

  languageSubscription: any;

  logoutInterval;
  OneSecondInMilliSeconds = 1000;

  subscriptions = new Subscription();

  constructor(
    private api: ApiService,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    public auth: AuthService,
    private hydraApi: HydraApiService,
    private idle: Idle,
    private hydraApiEventService: HydraApiEventService,
    private ss: SessionStorageService,
    private deviceDetector: DeviceDetectorService
  ) {
    this.subscriptions.add(
      this.hydraApiEventService.onAddMetaData.subscribe((metaData) => {
        this.addOrUpdateMetaData(metaData);
      })
    );

    this.subscriptions.add(
      this.hydraApiEventService.onUpdateMetaData.subscribe((metaData) => {
        this.addOrUpdateMetaData(metaData);
      })
    );

    this.subscriptions.add(
      this.hydraApiEventService.onDeleteMetaData.subscribe((id) => {
        const index = this.user.metaData.findIndex((md) => md.id === id);
        if (index > -1) {
          this.user.metaData.splice(index, 1);
        }
      })
    );
  }

  addOrUpdateMetaData(metaData: MetaDataDefinition) {
    let index = this.user.metaData.findIndex((md) => md.id === metaData.id);

    if (index != -1) {
      this.user.metaData[index] = metaData;
    } else {
      this.user.metaData.push(metaData);
    }
  }

  findFolderById(folderid: string): IFolder {
    const parts = folderid.split('@');
    const fid = parts[0];

    if (this.user && this.user.products) {
      for (const p of this.user.products) {
        for (const f of p.folders) {
          if (f.id === fid) {
            return f;
          }
        }
      }
    }

    return null;
  }

  replaceFolder(folder: IFolder): boolean {
    if (this.user && this.user.products) {
      for (const p of this.user.products) {
        for (let i = 0; i < p.folders.length; i++) {
          if (p.folders[i].id === folder.id) {
            p.folders[i] = folder;
            return true;
          }
        }
      }
    }

    return false;
  }

  reloadFolder(
    folderId: string,
    successCallBack: (folder: IFolder) => void,
    failureCallBack: (err: any) => void
  ): void {
    this.api.queryServer(`folders/${folderId}`).subscribe((f: IFolder) => {
      const folder = new Folder(f, f.product);
      this.replaceFolder(folder);
      this.userChanged.next(this.user);
      successCallBack(folder);
    }, failureCallBack);
  }

  findProductById(id: string): IProduct {
    if (this.user && this.user.products) {
      for (const p of this.user.products) {
        if (p.id === id) {
          return p;
        }
      }
    }

    return null;
  }

  findMetaDataById(id: string): IMetaDataDefinition {
    if (this.user && this.user.metaData) {
      for (const md of this.user.metaData) {
        if (md.id === id) {
          return md;
        }
      }
    }

    return null;
  }

  findMetaDataByName(name: string): IMetaDataDefinition {
    if (!this.user || !this.user.metaData) return null;

    return this.user.metaData.find((md) => md.name.toUpperCase() == name.toUpperCase());
  }

  showDashboardView = (): boolean => {
    if (!this.user || !this.user.products) return false;

    for (let p of this.user.products) {
      if (p.showDashboardView) return true;
    }

    return false;
  };

  getUserHomePage = (): string => {
    if (this.user.userType == UserTypes.InterFAX && this.deviceDetector.isMobile()) {
      this.ss.setIsInterFaxMobile(true);
    }

    if (!this.ss.getIsMobile() && !this.ss.getIsInterFaxMobile()) {
      if (this.user && this.user.products) {
        for (let p of this.user.products) {
          if (p.homePage) return p.homePage;
        }
      }

      return '/home';
    }

    if (this.ss.getIsInterFaxMobile()) {
      return '/fax-mobile';
    }

    return '/mobile';
  };

  setPassword = (
    currentPassword: string,
    newPassword: string,
    successCallBack: (result: ApiResult) => void,
    failureCallBack: (err: any) => void
  ): void => {
    this.api
      .postItemtoServer(`user/changepassword`, { currentPassword, newPassword })
      .subscribe(successCallBack, failureCallBack);
  };

  changeUserInformation = (
    newName: string,
    newEmail: string,
    successCallBack: (result: ApiResult) => void,
    failureCallBack: (err: any) => void
  ): void => {
    this.api.postItemtoServer(`user/changeuserinformation`, { newName, newEmail }).subscribe((result: ApiResult) => {
      successCallBack(result);
    }, failureCallBack);
  };

  loadUser(successCallBack: () => void, failureCallBack: (err: any) => void): void {
    this.api.queryServer('user').subscribe((data: User) => {
      this.user = data;

      successCallBack();
    }, failureCallBack);
  }

  loadUserProducts(successCallBack: () => void, failureCallBack: (err: any) => void): void {
    this.api
      .queryServer('user/products')
      .pipe(
        map((products: Array<IProduct>) => {
          return products.map((product) => new Product(product));
        })
      )
      .subscribe((data: Array<Product>) => {
        this.user.products = data;
        this.userChanged.next(this.user);
        successCallBack();
      }, failureCallBack);
  }

  loadUserMetaData(successCallBack: () => void, failureCallBack: (err: any) => void): void {
    const bambaApp = this.findProductById('BambaApplication');

    if (bambaApp) {
      this.hydraApi.getMetaDataDefinitions((metaData) => {
        this.user.metaData = metaData;
        this.userChanged.next(this.user);
        successCallBack();
      }, failureCallBack);
    } else {
      successCallBack();
    }
  }

  loadUserProfile(successCallBack: () => void = null, failureCallBack: (err: any) => void = null): void {
    this.api.queryServer('user/profile').subscribe(
      (result: ApiResult) => {
        if (result.success) {
          this.userProfile = result.object;
          this.userProfileChanged.next(this.userProfile);
          this.userProfileLoaded.next();
          if (successCallBack) successCallBack();
        } else {
          if (failureCallBack) failureCallBack(result.errors);
        }
      },
      (err) => {
        if (failureCallBack) failureCallBack(err);
      }
    );
  }

  loadSendFaxProfile(successCallBack: () => void = null, failureCallBack: (err: any) => void = null): void {
    this.api.queryServer('user/sendfaxprofile').subscribe(
      (result: ApiResult) => {
        if (result.success) {
          this.userProfile.fax = result.object.fax;
          this.userProfile.fonts = result.object.fonts;
          this.userProfileChanged.next(this.userProfile);
          if (successCallBack) successCallBack();
        } else {
          if (failureCallBack) failureCallBack(result.errors);
        }
      },
      (err) => {
        if (failureCallBack) failureCallBack(err);
      }
    );
  }

  loadUserRoles(successCallBack: () => void, failureCallBack: (err: any) => void): void {
    this.hydraApi.getUserRoles((userRoles: Role[]) => {
      this.userRoles = userRoles;
      successCallBack();
    }, failureCallBack);
  }

  loadUserFeatures(successCallBack: () => void, failureCallBack: (err: any) => void): void {
    this.hydraApi.getUserFeatures((features: string[]) => {
      this.userFeatures = features;
      successCallBack();
    }, failureCallBack);
  }

  loadAppIntegrations(successCallBack: () => void, failureCallBack: (err: any) => void): void {
    this.hydraApi.getIntegratedApplications((apps: Array<IntegratedApplication>) => {
      this.integratedApplications = apps;
      successCallBack();
    }, failureCallBack);
  }

  getUser() {
    return this.user;
  }

  clearUser() {
    delete this.user;
  }

  getAppId() {
    // Todo: Fix app Module by keeping app status at every route change
    return 'App-Module';
  }

  setNewLocal(locale: string) {
    if (locale == 'en') {
      this.locale = 'en-US';
    } else if (locale == 'en-US') {
      this.locale = locale;
    } else if (locale == 'en-GB') {
      this.locale = locale;
    } else {
      this.locale = locale.split('-')[0];
    }

    this.locale = this.locale == 'zh' ? 'zh-CN' : this.locale;
    this.localeChanged.next(this.locale);
  }

  getLocale() {
    return this.locale;
  }

  getLocalDateFormat() {
    return moment.localeData(this.getLocale()).longDateFormat('L');
  }

  getLocalTimeFormat() {
    return moment.localeData(this.getLocale()).longDateFormat('LT');
  }

  setupLocale() {
    // subscribe to router event
    this.languageSubscription = this.activatedRoute.queryParams.subscribe((param: any) => {
      if (param['locale']) {
        this.setNewLocal(param['locale']);
      }
    });
  }

  ngOnDestroy(): void {
    this.languageSubscription.unsubscribe();
    this.subscriptions.unsubscribe();
  }

  hasLoginToken = (): boolean => {
    if (!this.user) return false;
    if (!this.auth) return false;

    return this.auth.hasLoginToken();
  };

  isLoggedIn(): boolean {
    if (!this.user) {
      return false;
    }
    if (!this.auth) {
      return false;
    }

    return this.auth.isLoggedIn();
  }

  confirmLogOut(logoutConfirmModalInstance) {
    const isMobileView = this.ss.getIsMobile();
    const isFaxMobile = this.ss.getIsInterFaxMobile();
    const isLoggedInViaSSO = !!sessionStorage.getItem(AUTHORITY);

    clearInterval(this.logoutInterval);
    logoutConfirmModalInstance.close();

    this.auth.logout();
    this.clearUser();

    if (isLoggedInViaSSO) return;

    if (!isMobileView && !isFaxMobile) {
      this.router.navigateByUrl('/login');
      return;
    }

    if (isFaxMobile) {
      this.router.navigateByUrl('/fax-mobile/login');
      return;
    }

    this.router.navigateByUrl('/mobile/login');
  }

  timeoutConfirmModal = (logoutConfirmModalInstance) => {};

  cancelLogout(logoutConfirmModalInstance) {
    clearInterval(this.logoutInterval);
    logoutConfirmModalInstance.close();

    this.startIdle();
  }

  startLogoutTimer(logoutCountdownFormatted, logoutConfirmModalInstance, countDownTime, idleTimeOutModalInstance?) {
    clearInterval(this.logoutInterval);

    const timerStartedAt = new Date().getTime();
    this.logoutInterval = setInterval(() => {
      const now = new Date().getTime();
      const dif = now - timerStartedAt;
      const secondsBetweenDates = Math.floor(dif / 1000);
      if (countDownTime > secondsBetweenDates) {
        logoutCountdownFormatted['countdownTime'] = this.transformLogoutCount(countDownTime - secondsBetweenDates);
      } else {
        clearInterval(this.logoutInterval);

        if (idleTimeOutModalInstance != null) {
          logoutConfirmModalInstance.close();

          this.auth.logoutBackend();
          idleTimeOutModalInstance.open();
        } else {
          this.confirmLogOut(logoutConfirmModalInstance);
        }
      }
    }, this.OneSecondInMilliSeconds);
  }

  transformLogoutCount(value: number): string {
    const minutesNumbers: number = Math.floor(value / 60);
    let minutes: string = minutesNumbers + '';
    let seconds: string = `${value - minutesNumbers * 60}`;
    if (minutes.length < 2) {
      minutes = `0${minutes}`;
    }
    if (seconds.length < 2) {
      seconds = `0${seconds}`;
    }
    return `${minutes}:${seconds}`;
  }

  logout(logoutConfirmModalInstance, logoutCountdownFormatted, countDownTime, idleTimeOutModalInstance?) {
    this.clearIdleTimeOut();

    this.startLogoutTimer(
      logoutCountdownFormatted,
      logoutConfirmModalInstance,
      countDownTime,
      idleTimeOutModalInstance
    );

    logoutCountdownFormatted['countdownTime'] = this.transformLogoutCount(countDownTime);
    logoutConfirmModalInstance.open();
  }

  setIdleTimeOut = (onStartIdleCallback: () => void) => {
    this.idle.stop();
    this.idle.setIdle(60 * this.userProfile.sessionTimeInMinutes);
    this.idle.setInterrupts(DEFAULT_INTERRUPTSOURCES);
    this.idle.watch();
    this.idle.onIdleStart.subscribe(() => {
      onStartIdleCallback();
    });
  };

  public keepSessionAlive = (): void => {
    this.api.postItemtoServer(`user/keepSessionAlive`, {}).subscribe();
  };

  clearIdleTimeOut = () => {
    clearInterval(this.logoutInterval);
    this.idle.stop();
  };

  startIdle = () => {
    this.idle.watch();
  };

  hasRolePermission = (permission: string): boolean => {
    for (const role of this.userRoles) {
      for (const rolePermission of role.permissions) {
        if (rolePermission === permission) return true;
      }
    }

    return false;
  };

  hasFeature = (feature: Feature | string): boolean => {
    for (const f of this.userFeatures) {
      if (f == feature) return true;
    }

    return false;
  };

  hasOLCFeature(): boolean {
    return this.hasFeature(Feature.OLCTED) || this.hasFeature(Feature.OLCAPI);
  }

  getIntegratedApplicationSettingsFor = (app: string): IntegratedApplicationSettings => {
    const settings = this.user.integratedApplicationsSettings.find((s) => s.application === app);

    if (settings) return new IntegratedApplicationSettings(settings);

    return new IntegratedApplicationSettings({
      application: app,
      username: '',
      secret: '',
    });
  };

  updateIntegratedApplicationSettings = (integratedAppSettings: IIntegratedApplicationSettings) => {
    const index = this.user.integratedApplicationsSettings.findIndex(
      (s) => s.application === integratedAppSettings.application
    );

    if (index < 0) {
      this.user.integratedApplicationsSettings.push(integratedAppSettings);
    } else {
      this.user.integratedApplicationsSettings[index] = integratedAppSettings;
    }
  };

  get interFAXUsername(): string {
    if (this.user.userType == UserTypes.InterFAX) return this.user.email;

    const interfaxApp = this.getIntegratedApplicationSettingsFor('InterFAX');
    if (interfaxApp && interfaxApp.username) return interfaxApp.username;

    return '';
  }

  addToForceReloadFoldersIds = (folderIds: string[]): void => {
    folderIds.forEach((folderId) => {
      if (!this.forceReloadFoldersIds.includes(folderId)) {
        this.forceReloadFoldersIds.push(folderId);
      }
    });
  };

  updateOlcUserDefaultUnit(
    measurementSettings: MeasurementSettings,
    successCallBack: (result: ApiResult) => void,
    failureCallBack: (err: any) => void
  ): void {
    this.hydraApi.updateMeasurementSettings(
      measurementSettings,
      (result) => {
        this.user.tedOptions.measurementSettings = result.object.tedOptions.measurementSettings;
        this.userChanged.next(this.user);

        successCallBack(result);
      },
      failureCallBack
    );
  }

  areInboundNotificationsAllowed(): boolean {
    return (
      this.hasRolePermission(RolePermissions.INTERFAX_PERMISSIONS_ALLOWINBOUNDEMAILNOTIFICATIONS) ||
      this.hasRolePermission(RolePermissions.INTERFAX_ADMINISTRATOR)
    );
  }

  areOutboundNotificationsAllowed(): boolean {
    return (
      this.hasRolePermission(RolePermissions.INTERFAX_PERMISSIONS_ALLOWOUTBOUNDEMAILNOTIFICATIONS) ||
      this.hasRolePermission(RolePermissions.INTERFAX_ADMINISTRATOR)
    );
  }
}
