import { ObjectIdGenerator } from '../../../../../../Bamba.Shared';

export enum FieldMappingType {
  Standard = 0,
  Advanced = 1,
  NotMapped = 2,
}

export enum DuplicateSelectionType {
  First = 0,
  Last = 1,
  None = 2,
}

export interface IAwsFieldMapping {
  fieldId: string;
  value: string;
  type: FieldMappingType;
}

export class AwsFieldMapping implements IAwsFieldMapping {
  fieldId: string;
  value: string;
  type: FieldMappingType;
  duplicateSelectionType: DuplicateSelectionType;

  constructor(initializer) {
    if (initializer.fieldId == null) throw new Error('Invalid initializer');
    if (initializer.value == null) throw new Error('Invalid initializer');
    if (initializer.type == null) throw new Error('Invalid initializer');
    if (initializer.duplicateSelectionType == null) throw new Error('Invalid initializer');

    this.fieldId = initializer.fieldId;
    this.value = initializer.value;
    this.type = initializer.type;
    this.duplicateSelectionType = initializer.duplicateSelectionType;
  }

  get mappingType(): string {
    return `${this.type}`;
  }

  set mappingType(val: string) {
    this.type = Number(val);
  }

  get mappingDuplicateSelectionType(): string {
    return `${this.duplicateSelectionType}`;
  }

  set mappingDuplicateSelectionType(val: string) {
    this.duplicateSelectionType = Number(val);
  }

  static create(): AwsFieldMapping {
    return new AwsFieldMapping({
      fieldId: ObjectIdGenerator.Empty,
      value: '',
      type: FieldMappingType.Standard,
      duplicateSelectionType: DuplicateSelectionType.First,
    });
  }
}
