import { Directive, Input, OnInit, OnChanges, ElementRef, Renderer2 } from '@angular/core';
import { WindowRef } from 'shared-code-lib';

@Directive({
  selector: '[appContentEditable]',
})
export class ContentEditableDirective implements OnInit, OnChanges {
  @Input() appContentEditable: boolean;
  constructor(private el: ElementRef, private renderer: Renderer2, private windowRef: WindowRef) {}

  ngOnInit() {
    this.handleContentEditable();
  }

  ngOnChanges() {
    this.handleContentEditable();
  }

  handleContentEditable() {
    if (this.appContentEditable) {
      this.renderer.setAttribute(this.el.nativeElement, 'contenteditable', 'true');
      this.setEndOfContenteditable(this.el.nativeElement);
    } else {
      this.renderer.setAttribute(this.el.nativeElement, 'contenteditable', 'false');
    }
  }

  setEndOfContenteditable(contentEditableElement: ElementRef) {
    let range;
    let selection;
    if (document.createRange) {
      range = document.createRange();
      range.selectNodeContents(contentEditableElement);
      range.collapse(false);
      selection = this.windowRef.nativeWindow.getSelection();
      selection.removeAllRanges();
      selection.addRange(range);
    }
  }
}
