import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root',
})
export class StickyFieldsService {
  stickyFieldsDictionary = {};

  setStickyField(metadataName: string, value: string): void {
    if (!metadataName) return;
    this.stickyFieldsDictionary[metadataName.toLowerCase()] = value;
  }

  getStickyField(metadataName: string): string {
    const value = this.stickyFieldsDictionary[metadataName.toLowerCase()];
    return value ? value : null;
  }

  clear() {
    this.stickyFieldsDictionary = {};
  }
}