import * as signalR from '@microsoft/signalr';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { AuthService } from 'shared-code-lib';
import { HubConnectionOperations } from '../core/hubconnection-operations';
import { Log } from '../core/log';
import { EventTypes, FolderViewEvent, ItemTypes } from './../models/folder-view-event';
import { Workflow } from './../models/workflow';
import { WorkflowFolder } from './../models/workflow-folder';
import { HydraApiService } from './hydra-api.service';
import { UserStateService } from './user-state.service';

export abstract class ActivityEventsService {
  protected _hubConnection: signalR.HubConnection;
  public workflows: Workflow[] = [];
  public folders = {};

  constructor(
    protected userStateService: UserStateService,
    protected hydraApi: HydraApiService,
    protected translate: TranslateService,
    protected toastr: ToastrService,
    protected authService: AuthService
  ) {}

  abstract loadWorkflows(): void;
  abstract workflowsLoaded(workflows: Workflow[]): void;
  abstract processStatusEvent(folderEvent: FolderViewEvent): void;

  abstract statusTextNoItems: string;
  abstract statusTextOneItem: string;
  abstract statusTextCount: string;
  abstract eventId: string;
  workflowsEventId: string = 'workflowsstatus-*';

  initialize() {
    Log.enter('ActivityEventsService.initialize');

    try {
      this.createHub();
      this.loadWorkflows();
    } catch (e) {
      Log.error('ActivityEventsService.initialize', e);
    }
  }

  public getStatusText = (): string => {
    const itemCount = this.getTotalFolderItemCount();

    if (itemCount == 0) {
      return this.translate.instant(this.statusTextNoItems);
    } else if (itemCount == 1) {
      return this.translate.instant(this.statusTextOneItem);
    } else {
      return this.translate.instant(this.statusTextCount).replace('{count}', itemCount);
    }
  };

  public getItemsAreInProcess = (): boolean => {
    return this.getTotalFolderItemCount() != 0;
  };

  private createHub = (): void => {
    if (this._hubConnection && this._hubConnection.state === signalR.HubConnectionState.Connected) {
      this._hubConnection.stop();
      delete this._hubConnection;
    }

    if (!this.userStateService.hasLoginToken()) return;

    this._hubConnection = new signalR.HubConnectionBuilder()
      .withUrl('/eventhub', { accessTokenFactory: () => this.authService.getToken() })
      .build();

    HubConnectionOperations.setTimeout(this._hubConnection);
    this._hubConnection.start().catch((err) => console.log(err));

    HubConnectionOperations.executeOnClose(this._hubConnection, () => {
      this.createHub();
    });

    this._hubConnection.on(this.workflowsEventId, this.onWorkflowChanged);
  };

  onWorkflowChanged = (event: FolderViewEvent) => {
    if (event.itemType != ItemTypes.item) return;

    const index = this.workflows.findIndex((x) => x.id == event.data.id);

    if (event.eventType === EventTypes.added) {
      if (index == -1) this.workflows.unshift(event.data);
    } else if (event.eventType === EventTypes.updated) {
      if (index != -1) this.workflows[index] = event.data;
    } else if (event.eventType === EventTypes.deleted) {
      if (index != -1) this.workflows.splice(index, 1);
    }
  };

  protected getTotalFolderItemCount(): number {
    let total = 0;

    for (let workflow of this.workflows) {
      if (!this.folders[workflow.id]) continue;

      total += this.getTotalFolderItemCountRecursive(this.folders[workflow.id]);
    }

    return total;
  }

  private getTotalFolderItemCountRecursive = (folders: WorkflowFolder[]): number => {
    let total = 0;

    for (let folder of folders) {
      total += folder.itemCount;
      total += this.getTotalFolderItemCountRecursive(folder.folders);
    }

    return total;
  };

  workflowFolderLoaded = (workflow: Workflow, folders: WorkflowFolder[]): void => {
    const eventId = `${this.eventId}-${workflow.id}`;
    this._hubConnection.on(eventId, this.processStatusEvent);
    this.folders[workflow.id] = folders;
  };

  protected workflowsFailedLoad = (err: any): void => {
    this.toastr.error(this.translate.instant('errors.failed-load-workflows'));
  };

  protected workflowFolderFailedLoad = (err: any): void => {
    console.log(`CaptureStatusHub.workflowFolderFailedLoad ${err}`);
  };

  protected findFolder = (id: string): WorkflowFolder => {
    for (let workflow of this.workflows) {
      if (!this.folders[workflow.id]) continue;

      const parent = this.findFolderRecursive(id, this.folders[workflow.id]);
      if (parent) return parent;
    }

    return null;
  };

  protected findFolderRecursive = (id: string, folders: WorkflowFolder[]): WorkflowFolder => {
    for (let folder of folders) {
      if (folder.id == id) return folder;

      const f = this.findFolderRecursive(id, folder.folders);
      if (f) return f;
    }

    return null;
  };
}
