import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { Router } from '@angular/router';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { LoadAppStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/load-app-state.service';
import { AuthService } from '../../services/auth/auth.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { Log } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { SessionStorageService } from '../../services/session-storage.service';

@Component({
  selector: 'app-complete-info',
  templateUrl: './complete-info.component.html',
  styleUrls: ['./complete-info.component.scss'],
})
export class CompleteInfoComponent implements OnInit {
  @ViewChild('spinnerWrapper', { static: true })
  spinnerWrapper: ElementRef;

  constructor(
    private userState: UserStateService,
    private router: Router,
    private appState: LoadAppStateService,
    private ss: SessionStorageService,
    private auth: AuthService,
    private spinner: SpinnerStateService,
    private authService: AuthService
  ) {}

  ngOnInit() {
    this.userState.startIdle();

    this.appState.load(
      this.spinnerWrapper.nativeElement,
      () => this.loadInfoCompleted(),
      (err) => this.appLoadFailureCallback(err),
      (err) => this.metaDataLoadFailureCallback(err)
    );
  }

  loadInfoCompleted(): void {
    this.spinner.hide();

    this.authService.setUserStateLoaded(true);

    this.router.navigateByUrl(this.ss.getReturnUrl() || this.userState.getUserHomePage());
  }

  appLoadFailureCallback(err: any): void {
    Log.error('app-complete-info.appLoadFailureCallback', err);

    this.auth.logout();
  }

  metaDataLoadFailureCallback(err: any): void {
    Log.error('app-complete-info.metaDataLoadFailureCallback', err);

    this.handleError();
  }

  private handleError(): void {
    this.spinner.hide();
    this.auth.logout();
    this.router.navigateByUrl('/login');
  }
}
