import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

@Injectable({
  providedIn: 'root',
})
export class Languages {
  constructor(private translate: TranslateService) {}

  public static isRTLLanguage = () => {
    return navigator.language == 'ar' || navigator.language == 'he';
  };

  public static getDirection = () => {
    return Languages.isRTLLanguage() ? 'rtl' : 'ltr';
  };

  public static getLanguage = () => {
    return navigator.language;
  };

  public getLocalizedDate() {
    const months = [
      'January',
      'February',
      'March',
      'April',
      'May',
      'June',
      'July',
      'August',
      'September',
      'October',
      'November',
      'December',
    ];
    const weekdays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const translatedWeekdays = weekdays.map((x) => this.translate.instant(`Common.Calendar.WeekDays.${x}`));

    return {
      previousMonth: this.translate.instant('Common.PreviousMonth'),
      nextMonth: this.translate.instant('Common.NextMonth'),
      months: months.map((x) => this.translate.instant(`Common.Calendar.Months.${x}`)),
      weekdays: translatedWeekdays,
      weekdaysShort: translatedWeekdays.map((x) => x.substr(0,3)),
    };
  }
}
