import { Injectable } from '@angular/core';
import { ApiService } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/api.service';
import { ApiResult } from '../models/ApiResult';

@Injectable({
  providedIn: 'root',
})
export class UserStateService {
  url: string = '';

  constructor(private apiService: ApiService) {}

  setPassword = (
    currentPassword: string,
    newPassword: string,
    successCallBack: (result: ApiResult) => void,
    failureCallBack: (err: any) => void,
    forceHighAuthenticationStrength: boolean = false
  ): void => {
    this.apiService
      .postItemtoServer(`user/changepassword`, { currentPassword, newPassword, forceHighAuthenticationStrength })
      .subscribe(successCallBack, failureCallBack);
  };
}
