import { Component, EventEmitter, Input, Output, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { DelayService, FieldDefinition, MetaDataType } from 'shared-code-lib';
import { Variables } from '../../models/deployments';

@Component({
  selector: 'app-variable-list',
  templateUrl: './variable-list.component.html',
  styleUrls: ['./variable-list.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class VariableListComponent {
  @Input() variables: Variables = new Variables();
  @Output() variablePending = new EventEmitter<boolean>();

  key = '';
  value = '';
  nameFocused = true;

  ngOnInit(): void {}
  constructor(private translate: TranslateService, private delayService: DelayService) {}

  createField = (label: string, placeholder: string, hideLabel: boolean = undefined) => {
    return new FieldDefinition({
      type: MetaDataType.Text,
      label: label ? this.translate.instant(label) : '',
      placeholder: placeholder ? this.translate.instant(placeholder) : '',
      required: true,
      hideLabel: hideLabel,
    });
  };

  textChanged(): void {
    this.variablePending.emit(!!this.key || !!this.value);
  }

  onNameBlur(): void {
    this.nameFocused = false;
  }

  addField = (): void => {
    if (this.key) {
      this.variables[this.key] = this.value;
      this.key = '';
      this.value = '';
      this.textChanged();
      this.delayService.execute(() => (this.nameFocused = true), 0);
    }
  };

  deleteItem = (key: string): void => {
    delete this.variables[key];
  };

  deleteAllItems = (): void => {
    this.variables = new Variables();
  };

  trackBy(index: number): number {
    return index;
  }
}
