import { Component, Input, OnInit } from '@angular/core';
import moment from 'moment';
import { PropertyTypes } from 'shared-code-lib';
import { UserStateService } from '../../../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { UtilityService } from '../../../../../../Bamba.Web/ClientApp/src/app/blocks/services/utility.service';

@Component({
  selector: '[appBambafxExpandedDetail]',
  templateUrl: './bambafx-expanded-detail.component.html',
  styleUrls: ['./bambafx-expanded-detail.component.scss'],
})
export class BambafxExpandedDetailComponent implements OnInit {
  @Input() details: any;

  metaData = [];

  datelocaleFormat: string = '';

  constructor(private userService: UserStateService, private utility: UtilityService) {}

  ngOnInit() {
    this.datelocaleFormat = this.userService.getLocalDateFormat();

    for (const property in this.details.metaData) {
      const md = this.details.metaData[property];

      if (!md) continue;

      if (md.propertyType == PropertyTypes.Date) {
        md.value = this.formatValue(md.value, this.datelocaleFormat);
      } else if (md.propertyType == PropertyTypes.Integer) {
        md.value = this.utility.localizeNumber(md.value);
      }

      this.metaData.push(md);
    }
  }

  formatValue(value: any, formater: string): string {
    return moment(value).local().format(formater);
  }
}
