import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class FilterByTenant extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByTenantComponent';
  }
}

class FilterByOptions extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOptionsComponent';
  }
}

class FilterByEntry extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByLogEntryComponent';
  }
}

export class LogsFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('LogsFilters.Create', filter);

    if (
      filter.id === 'BambaApplication-Upland.Bamba.Application.Logs.Filtering.FilterByTenant' ||
      filter.id === 'BambaAdministratorApplication-Upland.Bamba.Application.TenantDocumentChart.FilterByTenant' ||
      filter.id === 'BambaApplication-Upland.Bamba.Application.TenantDocumentChart.FilterByTenant'
    ) {
      return new FilterByTenant(filter);
    }

    if (
      filter.id === 'BambaApplication-Upland.Bamba.Application.Logs.Filtering.FilterByLevel' ||
      filter.id === 'BambaApplication-Upland.Bamba.Application.Logs.Filtering.FilterBySource'
    ) {
      return new FilterByOptions(filter);
    }

    if (filter.id === 'BambaApplication-Upland.Bamba.Application.Logs.Filtering.FilterByEntry') {
      return new FilterByEntry(filter);
    }

    return null;
  };
}
