import { Log } from '../core/log';
import { Periods } from '../filters/filter-by-time-period/filter-by-time-period.component';
import { Filter, IFilter } from './filter';
class FilterChartRange extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterChartRange';
  }
}

class FilterByBrowser extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByBrowser';
  }
}

export class LoginChartFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('LoginsFilters.Create', filter);

    if (
      filter.id == 'BambaAdministratorApplication-Upland.Bamba.Core.Widgets.Shared.FilterChartRange' ||
      filter.id == 'BambaApplication-Upland.Bamba.Core.Widgets.Shared.FilterChartRange' ||
      filter.id == 'BambaDWFToolsApplication-Upland.Bamba.Core.Widgets.Shared.FilterChartRange'
    ) {
      filter.value = filter.defaultValue ?? Periods.Week;
      return new FilterChartRange(filter);
    }

    if (filter.id == 'BambaAdministratorApplication-Upland.Bamba.Core.Widgets.Filters.FilterByBrowser')
      return new FilterByBrowser(filter);

    return null;
  };
}
