import { Component, Input, OnInit } from '@angular/core';
import { ItemActionHandler } from '../../core/itemActionHandler';
import { Alert, AlertType, IAlert } from '../../models/alert';
import { ProductsAlertsService } from '../../services/products-alerts.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-alert-banner',
  templateUrl: './alert-banner.component.html',
  styleUrls: ['./alert-banner.component.scss'],
})
export class AlertBannerComponent implements OnInit {
  @Input() itemActionHandler: ItemActionHandler;

  alerts: Alert[];
  selectedAlertIndex: number = 0;
  selectedAlert: Alert;
  textBeforeActionableText: string;
  actionableText: string;
  textAfterActionableText: string;
  alertBannerClass: string;
  timerId: number = 0;

  constructor(private alertsService: ProductsAlertsService, private userstate: UserStateService) {}

  ngOnInit(): void {
    this.load();
    this.userstate.accountchanged.subscribe(this.load);
  }

  load = (): void => {
    this.alertsService.get(this.onGetAlertsSuccess, this.onGetAlertsFail);
  };

  onGetAlertsSuccess = (iAlerts: IAlert[]): void => {
    if (!iAlerts.length) return;
    this.alerts = Alert.ConstructFrom(iAlerts);

    if (!this.alerts?.length) {
      this.selectedAlert = null;
      return;
    }

    this.displaySelectedAlert();
  };

  onAlertActionClick = (): void => {
    this.selectedAlert.action ? this.itemActionHandler.invoke('', this.selectedAlert.action, [], []) : null;
  };

  close = (): void => {
    this.selectedAlert = null;
    this.clearAlertTimer();
  };

  pageAlerts = (num: number): void => {
    const maxIndex = this.alerts.length - 1;
    this.selectedAlertIndex += num;
    if (this.selectedAlertIndex < 0) this.selectedAlertIndex = maxIndex;
    else if (this.selectedAlertIndex > maxIndex) this.selectedAlertIndex = 0;
    this.displaySelectedAlert();
  };

  displaySelectedAlert() {
    const alert = this.alerts[this.selectedAlertIndex];
    if (!alert) return;

    this.textBeforeActionableText = alert.textBeforeActionableText();
    this.actionableText = alert.actionableText();
    this.textAfterActionableText = alert.textAfterActionableText();
    this.alertBannerClass = AlertType[alert.type];
    this.selectedAlert = alert;

    this.startAlertTimer();
  }

  startAlertTimer = (): void => {
    this.clearAlertTimer();
    this.timerId = window.setTimeout(() => this.pageAlerts(1), 10 * 1000);
  };

  clearAlertTimer = (): void => {
    if (this.timerId) clearTimeout(this.timerId);

    this.timerId = null;
  };

  onGetAlertsFail = (err: any): void => {
    throw new Error('Failed to load products alerts.');
  };
}
