import { KeyValue } from '@angular/common';

export interface IPaymentMethodConfigurations {
  name: string;
  configurations: KeyValue<string, string>[];
}

export class PaymentMethodConfigurations implements IPaymentMethodConfigurations {
  configurations: KeyValue<string, string>[] = [];

  constructor(public name: string) {}

  serialize(): IPaymentMethodConfigurations {
    return {
      name: this.name,
      configurations: this.configurations,
    };
  }
}
