import { MongoObjectId } from './mongo-object-id';

export interface IOutcome {
  id: string;
  outcomeType: string;
  text: string;
  label: string;
  enabled: boolean;
  requiresValidMetaData: boolean;
  requiresConfirmation: boolean;
  nextId: string;
}

export class Outcome implements IOutcome {
  public static readonly SendToDoneId = 'SEND_TO_DONE';

  public id: string;
  public outcomeType: string;
  public text: string;
  public label: string;
  public enabled: boolean;
  public requiresValidMetaData: boolean;
  public requiresConfirmation: boolean;
  public nextId: string;

  constructor(initializer) {
    if (initializer.id == null) throw new Error('Invalid initializer');
    if (initializer.outcomeType == null) throw new Error('Invalid initializer');
    if (initializer.text == null) throw new Error('Invalid initializer');
    if (initializer.label == null) throw new Error('Invalid initializer');
    if (initializer.enabled == null) throw new Error('Invalid initializer');
    if (initializer.requiresValidMetaData == null) throw new Error('Invalid initializer');
    if (initializer.nextId == null) throw new Error('Invalid initializer');
    if (initializer.requiresConfirmation == null) throw new Error('Invalid initializer');

    this.id = initializer.id;
    this.outcomeType = initializer.outcomeType;
    this.text = initializer.text;
    this.label = initializer.label;
    this.enabled = initializer.enabled;
    this.requiresValidMetaData = initializer.requiresValidMetaData;
    this.nextId = initializer.nextId;
    this.requiresConfirmation = initializer.requiresConfirmation;
  }

  serializable(): any {
    return {
      id: this.id,
      outcomeType: this.outcomeType,
      text: this.text,
      label: this.label,
      enabled: this.enabled,
      requiresValidMetaData: this.requiresValidMetaData,
      requiresConfirmation: this.requiresConfirmation,
      nextId: this.nextId,
    };
  }

  graphLabel(): string {
    return this.label;
  }

  static create = (initializer: IOutcome): Outcome => {
    if (initializer.outcomeType == 'succeeded') return new Succeeded(initializer);
    if (initializer.outcomeType == 'failed') return new Failed(initializer);
    if (initializer.outcomeType == 'outcome') return new Outcome(initializer);
    if (initializer.outcomeType == 'interactiveoutcome') return new Interactive(initializer);

    if (initializer.outcomeType == 'recognized') return new Recognized(initializer);
    if (initializer.outcomeType == 'unrecognized') return new Unrecognized(initializer);
    if (initializer.outcomeType == 'recognizednotvalid') return new RecognizedNotValid(initializer);

    if (initializer.outcomeType == 'true') return new True(initializer);
    if (initializer.outcomeType == 'false') return new False(initializer);

    if (initializer.outcomeType == 'incorrectcount') return new IncorrectCount(initializer);

    if (initializer.outcomeType == 'signaturefound') return new SignatureFound(initializer);
    if (initializer.outcomeType == 'signaturesuspicious') return new SignatureSuspicious(initializer);
    if (initializer.outcomeType == 'signaturemissing') return new SignatureMissing(initializer);

    if (initializer.outcomeType == 'detectedpii') return new DetectedPII(initializer);
    if (initializer.outcomeType == 'suspectedpii') return new SuspectedPII(initializer);
    if (initializer.outcomeType == 'piinotdetected') return new PIINotDetected(initializer);

    if (initializer.outcomeType == 'notclassified') return new NotClassified(initializer);
    if (initializer.outcomeType == 'classified') return new Classified(initializer);

    if (initializer.outcomeType == 'originalworkitem') return new OriginalWorkitem(initializer);
    if (initializer.outcomeType == 'duplicateworkitem') return new DuplicateWorkItem(initializer);

    throw new Error(`Unknown outcome type ${initializer.outcomeType}`);
  };
}

export class Succeeded extends Outcome {
  constructor(initializer) {
    super(initializer);
  }

  graphLabel(): string {
    return 'Succeeded';
  }
}

