export class Interactive extends Outcome {
  constructor(initializer) {
    super(initializer);
  }

  graphLabel(): string {
    return this.label;
  }

  static create(): Interactive {
    return new Interactive({
      id: MongoObjectId.generate(),
      outcomeType: 'interactiveoutcome',
      text: 'Interactive',
      label: '',
      enabled: true,
      requiresValidMetaData: true,
      requiresConfirmation: false,
      nextId: '',
    });
  }
}

