import { Component, OnInit, Input } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { UserStateService } from '../../../../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { SystemMetaData } from '../../../../../../../Bamba.Web/ClientApp/src/app/blocks/core/systemMetaData';
import { MetaData, RolePermissions } from 'shared-code-lib';

class DisplayMetaData {
    constructor(public name: string, public value: string) {}
}

@Component({
    selector: 'app-workitem-properties-datafields',
    templateUrl: './workitem-properties-datafields.component.html',
    styleUrls: ['./workitem-properties-datafields.component.scss'],
})
export class WorkitemPropertiesDataFieldsComponent implements OnInit {
    @Input() details: any;

    systemMetaDataToHide = [
        SystemMetaData.AccuRouteMsgEID,
        SystemMetaData.ExtractedDocumentData,
        SystemMetaData.ExtractedInvoiceData,
    ];

    metadata = new Array<DisplayMetaData>();
    systemMetadata = new Array<DisplayMetaData>();

    constructor(private userState: UserStateService, private translate: TranslateService) {}

    ngOnInit() {
        this.buildMetaData();
    }

    buildMetaData = (): void => {
        for (const key in this.details.metaData) {
            const md = <MetaData>this.details.metaData[key];

            if (
                !this.userState.hasRolePermission(RolePermissions.BAMBA_ADMIN) &&
                this.userState.findMetaDataByName(md.name) == null
            )
                continue;

            this.metadata.push(new DisplayMetaData(this.getMetaDataLabel(md.name), this.getMetaDataValue(md)));
        }

        this.metadata.sort((a, b) => a.name.localeCompare(b.name));

        for (const key in this.details.metaData) {
            const md = <MetaData>this.details.metaData[key];

            if (!md.name.startsWith('@')) continue;
            if (this.systemMetaDataToHide.findIndex((mdToHide) => mdToHide.toLowerCase() === md.name.toLowerCase()) != -1)
                continue;

            this.systemMetadata.push(new DisplayMetaData(md.name.slice(1), this.getMetaDataValue(md)));
        }

        this.systemMetadata.sort((a, b) => a.name.localeCompare(b.name));
    };

    getMetaDataValue = (md: MetaData) => {
        if (md.value instanceof Array) {
            return `${md.value.length.toString()} ${this.translate.instant('general.line-items-row-count')}`;
        } else {
            return md.value;
        }
    };

    getMetaDataLabel = (name: string): string => {
        const md = this.userState.findMetaDataByName(name);

        if (md == null) return name;

        return md.label;
    };
}