import { AfterViewInit, Component, EventEmitter, OnInit, Output, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import {
  IMetaDataDefinition,
  MetaDataCollection,
  MetaDataDefinition,
  MetaDataValidity,
  OverallValidityStatusChangedData,
  ValidationInProgressChangedData,
} from 'shared-code-lib';
import { FileDropService } from '../../../views/dashboard/widgets/file-drop/file-drop.service';
import { FileDropWidget } from '../../models/home-page-tab';
import { HydraApiService } from '../../services/hydra-api.service';
import { SpinnerState } from '../../services/models';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-workflow-prompts',
  templateUrl: './workflow-prompts.component.html',
  styleUrls: ['./workflow-prompts.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class WorkflowPromptsComponent implements OnInit, AfterViewInit {
  @Output() closeModal = new EventEmitter();

  workflowPromptsModal: NgxSmartModalComponent;
  widget: FileDropWidget;
  filesToSubmit: Array<File>;
  overallValidityStatus: MetaDataValidity;
  metaDataCollection: MetaDataCollection = new MetaDataCollection();
  toggleSpinner = new EventEmitter<SpinnerState>();
  modalData: any = null;

  validationInProgress: boolean = false;
  waitForValidation: boolean = false;
  loadingText: string;
  metadata: Array<IMetaDataDefinition> = [];

  constructor(
    private ngxSmartModalService: NgxSmartModalService,
    private translate: TranslateService,
    private toastr: ToastrService,
    private fileDropService: FileDropService,
    private spinner: SpinnerStateService,
    public hydraApi: HydraApiService,
    public userStateService: UserStateService
  ) {}

  ngOnInit(): void {
    this.metadata = this.userStateService.user.metaData;
  }

  ngAfterViewInit() {
    this.workflowPromptsModal = this.ngxSmartModalService.getModal('workflowPromptsModal');
    this.modalData = this.workflowPromptsModal.getData();
    this.widget = this.modalData.widget;
    this.filesToSubmit = this.modalData.filesToSubmit;
    this.toggleSpinner = this.modalData.toggleSpinner;
  }

  setOverallValidityStatus(event: OverallValidityStatusChangedData) {
    this.overallValidityStatus = event.overallValidity;
    this.metaDataCollection = event.metaDataCollection;
  }

  updateValidationInProgressState(event: ValidationInProgressChangedData) {
    this.validationInProgress = event.inProgress;
    let isInitialValidation = event.isInitial;

    if (isInitialValidation) {
      if (this.validationInProgress) {
        this.loadingText = this.translate.instant('workflow-indexing-panel.loading-defaults');
        this.spinner.show(this.loadingText, this.getModalContentElement());
        return;
      } else {
        this.spinner.hide();
        return;
      }
    }

    if (!this.waitForValidation || this.validationInProgress) return;

    this.waitForValidation = false;
    this.spinner.hide();
    this.submitFilesToWidget();
  }

  closeWorkflowPromptsModal = (): void => {
    this.closeModal.emit();
  };

  submitFilesToWidget() {
    if (this.validationInProgress) {
      this.waitForValidation = true;
      this.loadingText = this.translate.instant('workflow-indexing-panel.waiting');
      this.spinner.show(this.loadingText, this.getModalContentElement());
      return;
    }

    if (this.overallValidityStatus !== MetaDataValidity.valid) {
      this.toastr.error(this.translate.instant('workflow-indexing-panel.overall-validity-invalid'));
      return;
    }

    this.closeWorkflowPromptsModal();

    this.fileDropService.submitFilesToWidget(
      this.widget,
      this.filesToSubmit,
      this.metaDataCollection,
      this.toggleSpinner
    );
  }

  getModalContentElement() {
    return document.querySelector('.workfowPromptsModal .nsm-content') as HTMLElement;
  }

  getIMetaDataDefinitionAsMetaDataDefinition = () => this.metadata as MetaDataDefinition[];
}
