import { MetaDataCollection } from '../../../../../../Bamba.Shared/src/models/metadata';
import { IFilterValue } from '../models/filter';
import { DocumentSearchResult, WorkflowFolder } from '../models/workflow-folder';

export enum Action {
  EditSelection = 'EditSelection',
  SetFocusTreePanel = 'SetFocusTreePanel',

  RotateRight = 'RotateRight',
  RotateLeft = 'RotateLeft',
  ZoomIn = 'ZoomIn',
  ZoomOut = 'ZoomOut',
  FitToHeight = 'FitToHeight',
  FitToWidth = 'FitToWidth',

  CtrlDeleteSelectedItem = 'DeleteSelectedItemCtrl',
  DeleteSelectedItem = 'DeleteSelectedItem',

  ScanToFolder = 'ScanToFolder',
  ScanNew = 'ScanNew',
  ScanMorePages = 'ScanMorePages',
  RescanPage = 'RescanPage',

  ImportToFolder = 'ImportToFolder',
  ImportToUnselectedFolder = 'ImportToUnselectedFolder',
  ScanToUnselectedFolder = 'ScanToUnselectedFolder',
  ImportNew = 'ImportNew',
  RescanDocument = 'RescanDocument',
  ReimportDocument = 'ReimportDocument',
  ImportMorePages = 'ImportMorePages',
  ReimportPage = 'ReimportPage',

  CaptureToFolder = 'CaptureToFolder',
  CaptureNew = 'CaptureNew',
  CaptureMorePages = 'CaptureMorePages',
  RecapturePage = 'RecapturePage',
  RecaptureDocument = 'RecaptureDocument',

  NextPage = 'NextPage',
  PreviousPage = 'PreviousPage',

  Outcome1 = 'Outcome1',
  Outcome2 = 'Outcome2',
  Outcome3 = 'Outcome3',
  Outcome4 = 'Outcome4',

  BreakDocument = 'BreakDocument',

  GenerateRoutingSheet = 'GenerateRoutingSheet',

  CloseLatestEscapableModal = 'CloseLatestEscapableModal',

  Redaction = 'Redaction',
  Text = 'Text',
  Stamp = 'Stamp',
  Highlight = 'Highlight',
  Arrow = 'Arrow',
  Line = 'Line',
  Circle = 'Circle',
  Rectangle = 'Rectangle',
  FreeHand = 'FreeHand',
  StopAnnotating = 'StopAnnotating',
}

export class ActionEvent {
  constructor(public action: Action, public documentResult?: DocumentSearchResult) {}
}

export class FolderActionEvent extends ActionEvent {
  constructor(public action: Action, public folder: WorkflowFolder) {
    super(action);
  }
}

export interface IActionFileExtraParameters {
  folderId: string;
  ids: string[];
  filters: IFilterValue[];
  fileType?: string;
  args: MetaDataCollection;
}

export class ActionFileExtraParameters implements IActionFileExtraParameters {
  public folderId: string;
  public ids: string[] = [];
  public filters: IFilterValue[] = [];
  fileType?: string;
  args: MetaDataCollection;

  constructor(initializer: IActionFileExtraParameters) {
    this.folderId = initializer.folderId;
    this.ids = initializer.ids;
    this.fileType = initializer?.fileType;
    this.filters = initializer.filters?.map((x) => {
      return { id: x.id, value: x.value };
    });
    this.args = initializer.args;
  }

  public serializable(): IActionFileExtraParameters {
    return { folderId: this.folderId, ids: this.ids, filters: this.filters, fileType: this.fileType, args: this.args };
  }
}
