import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import {
  catchError,
  concatMap,
  filter,
  finalize,
  map,
  Observable,
  range,
  retry,
  Subject,
  switchMap,
  throwError,
  toArray,
} from 'rxjs';
import { IPartETagInfo, IUploadProgressEvent } from '../models/large-file-upload';
import { HydraApiService } from './hydra-api.service';
import { ApiResult } from './models';

import { ajax, AjaxResponse } from 'rxjs/ajax';

@Injectable({
  providedIn: 'root',
})
export class LargeFileUploadService {
  private uploadProgressSubject = new Subject<IUploadProgressEvent>();
  public uploadProgress$ = this.uploadProgressSubject.asObservable();

  private partsProgress = new Map<number, number>();
  private currentFilename = '';
  private currentUploadId = '';
  private uploadProgressData: IUploadProgressEvent = {
    overallLoaded: 0,
    overallPercentComplete: 0,
    overallTotal: 0,
    done: false,
  };

  private MAX_PART_UPLOAD_RETRIES = 3;
  private PART_UPLOAD_RETRY_DELAY = 1000;

  constructor(
    private http: HttpClient,
    private hydraApiService: HydraApiService,
    private translateService: TranslateService
  ) {}

  uploadLargeFile(file: File, fileName: string, partSizeInMb: number = 5): Observable<string> {
    this.uploadProgressData.overallTotal = file.size;
    this.partsProgress.clear();
    this.currentFilename = fileName;

    return this.startMultiPartUpload(fileName, file.name, file.type).pipe(
      switchMap((startResult: ApiResult) => {
        const { success, errors, object: uploadId } = startResult;

        if (!success) return throwError(() => new Error(errors[0]));

        this.currentUploadId = uploadId;

        const partSize = partSizeInMb * 1024 * 1024;
        const partsCount = Math.ceil(file.size / partSize);

        return range(0, partsCount).pipe(
          concatMap((partIndex) => {
            const start = partIndex * partSize;
            const end = Math.min(start + partSize, file.size);
            const part = file.slice(start, end);

            return this.uploadPart(part, fileName, uploadId, partIndex + 1).pipe(
              retry({ count: this.MAX_PART_UPLOAD_RETRIES, delay: this.PART_UPLOAD_RETRY_DELAY })
            );
          }),
          toArray(),
          switchMap((parts: IPartETagInfo[]) => this.completeMultipartUpload(fileName, uploadId, parts)),

          map((result: ApiResult) => {
            if (!result.success) throw new Error(result.errors[0]);
            return result.object;
          })
        );
      }),
      catchError((error: Error) =>
        this.currentUploadId
          ? this.abortMultipartUpload(fileName, this.currentUploadId).pipe(switchMap(() => throwError(() => error)))
          : throwError(() => error)
      ),
      finalize(() => {
        this.cleanup();
      })
    );
  }

  abortFileUpload(): Observable<ApiResult> | null {
    if (!this.currentUploadId || !this.currentFilename) return null;

    return this.abortMultipartUpload(this.currentFilename, this.currentUploadId);
  }

  private cleanup(): void {
    this.partsProgress.clear();
    this.currentFilename = '';
    this.currentUploadId = '';
    this.uploadProgressData = {
      overallLoaded: 0,
      overallPercentComplete: 0,
      overallTotal: 0,
      done: false,
    };
  }

  private startMultiPartUpload(filename: string, originalFilename: string, contentType: string): Observable<ApiResult> {
    return this.http.post<ApiResult>(`${this.hydraApiService.getBaseUrl()}/api/ReleaseManager/start-multipart-upload`, {
      filename,
      originalFilename,
      contentType,
    });
  }

  private getPartUploadPreSignedUrl(filename: string, uploadId: string, partNumber: number): Observable<ApiResult> {
    return this.http.post<ApiResult>(`${this.hydraApiService.getBaseUrl()}/api/ReleaseManager/get-part-presigned-url`, {
      filename,
      uploadId,
      partNumber,
    });
  }

  private abortMultipartUpload(filename: string, uploadId: string): Observable<ApiResult> {
    return this.http.post<ApiResult>(`${this.hydraApiService.getBaseUrl()}/api/ReleaseManager/abort-multipart-upload`, {
      filename,
      uploadId,
    });
  }

  private completeMultipartUpload(filename: string, uploadId: string, parts: IPartETagInfo[]): Observable<ApiResult> {
    return this.http.post<ApiResult>(
      `${this.hydraApiService.getBaseUrl()}/api/ReleaseManager/complete-multipart-upload`,
      {
        filename,
        uploadId,
        parts,
      }
    );
  }

  private uploadPart(
    partFile: Blob,
    filename: string,
    uploadId: string,
    partNumber: number
  ): Observable<IPartETagInfo> {
    return this.getPartUploadPreSignedUrl(filename, uploadId, partNumber).pipe(
      switchMap((presignedUrlResult: ApiResult) => {
        if (!presignedUrlResult.success) return throwError(() => new Error(presignedUrlResult.errors[0]));

        const url = presignedUrlResult.object;
        return this.uploadPartToS3(url, partFile, partNumber);
      }),
      map((response: AjaxResponse<unknown>) => {
        if (response.status !== 200)
          throw new Error(this.translateService.instant('file-upload.failed-to-upload-file'));

        const etag = response.responseHeaders.etag ? JSON.parse(response.responseHeaders.etag) : '';
        if (!etag) throw new Error(this.translateService.instant('file-upload.failed-to-upload-file'));

        return {
          partNumber: partNumber,
          eTag: etag,
        };
      })
    );
  }

  private uploadPartToS3(presignedUrl: string, part: Blob, partNumber: number): Observable<AjaxResponse<unknown>> {
    return ajax({
      url: presignedUrl,
      method: 'PUT',
      body: part,
      includeUploadProgress: true,
    }).pipe(
      map((event: AjaxResponse<unknown>) => this.handleUploadProgress(event, partNumber)),
      filter((event): event is AjaxResponse<unknown> => event instanceof AjaxResponse)
    );
  }

  handleUploadProgress = (event: AjaxResponse<unknown>, partNumber: number): AjaxResponse<unknown> | null => {
    console.log(`Upload event type: ${event.type}`);

    if (['upload_loadstart', 'upload_progress', 'upload_load'].includes(event.type)) {
      this.partsProgress.set(partNumber, event.loaded);
      const overallLoaded = Array.from(this.partsProgress.values()).reduce((sum, loaded) => sum + loaded, 0);
      const overallPercentComplete = Math.floor((overallLoaded * 100) / this.uploadProgressData.overallTotal);

      this.uploadProgressData = {
        ...this.uploadProgressData,
        overallLoaded,
        overallPercentComplete,
        done: false,
      };

      console.log(
        `Upload inprogress: Percent ${this.uploadProgressData.overallPercentComplete} Done ${this.uploadProgressData.done}`
      );

      this.uploadProgressSubject.next(this.uploadProgressData);
    }

    if (event.type !== 'download_load') return null;

    if (this.uploadProgressData.overallPercentComplete === 100) {
      this.uploadProgressData = {
        ...this.uploadProgressData,
        done: true,
      };

      console.log(
        `Upload complete: Percent ${this.uploadProgressData.overallPercentComplete} Done ${this.uploadProgressData.done}`
      );

      this.uploadProgressSubject.next(this.uploadProgressData);
    }

    return event as AjaxResponse<unknown>;
  };
}
