import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  forwardRef,
  HostListener,
  Input,
  OnInit,
  Output,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ResizableDirective } from 'shared-code-lib';
import { Preference } from '../../../../../Bamba.Web/ClientApp/src/app/views/document-capture/capture-models';
import { IFindMetaDataById } from '../../../interop/MetaDataService';
import { SessionStorageService } from '../../../services/session-storage.service';
import { UserPreferencesService } from '../../../services/user-preferences.service';
import { LookupMatch } from './../../../models/lookup-models';
import { CalculationsService } from './../../../utils/calculations.service';
import { DelayService } from './../../../utils/delay.service';
import { LookupMatchType } from './../../../utils/enums';
import { Key } from './../../../utils/key-enum';

declare const $: any;
@Component({
  selector: 'app-lookup-modal',
  templateUrl: './lookup-modal.component.html',
  styleUrls: ['./lookup-modal.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class LookupModalComponent implements OnInit, AfterViewInit {
  @ViewChild(forwardRef(() => ResizableDirective), { static: true }) resizableLookupModal: ResizableDirective;

  @Output() onSelectValue = new EventEmitter<number>();
  @Output() onClose = new EventEmitter();
  @Output() onSearch = new EventEmitter<string>();

  @Input() matches: Array<LookupMatch>;
  @Input() findMetaDataService: IFindMetaDataById;
  @Input() value: string;
  @Input() placeholder: string;
  @Input() lookupModalKey: string;
  @Input() loading: boolean;

  private modalBody: ElementRef;

  get visible(): boolean {
    return this.lookupFieldSearchModal?.isVisible();
  }

  @ViewChild('modalBody') set content(content: ElementRef) {
    if (content) this.modalBody = content;
  }

  tableHead: Array<string> = [];
  selectedRowIndex: number;
  isMobileOrFaxMobile: boolean;

  lookupFieldSearchModal: NgxSmartModalComponent;

  @HostListener('document:keydown', ['$event']) onKeydownHandler(event: KeyboardEvent) {
    switch (event.key) {
      case Key.ArrowUp:
        this.moveUp(event);
        this.scrollToSelectedRow(event);
        break;
      case Key.ArrowDown:
        this.moveDown(event);
        this.scrollToSelectedRow(event);
        break;
      case Key.Enter:
        if ($(event.target).hasClass('search-text')) {
          this.search();
          return;
        }

        this.selectValue();
    }
  }

  constructor(
    private calculationsService: CalculationsService,
    private delay: DelayService,
    private ss: SessionStorageService,
    private userPreferencesService: UserPreferencesService,
    public ngxSmartModalService: NgxSmartModalService
  ) {}

  ngOnInit() {
    this.isMobileOrFaxMobile = this.ss.getIsMobile() || this.ss.getIsInterFaxMobile();

    this.tableHead = this.matches[0].mappings.map((mapping) => {
      const mdd = this.findMetaDataService.findMetaDataById(mapping.metaDataId);
      return mdd.name;
    });

    this.getSelectedRow();
  }

  ngAfterViewInit(): void {
    this.modalBody.nativeElement.focus();
  }

  show = (): void => {
    this.lookupFieldSearchModal = this.ngxSmartModalService.getModal('lookupFieldSearchModal');
    this.lookupFieldSearchModal.open();

    if (!this.isMobileOrFaxMobile) this.resizableLookupModal.setElementDimensions();

    if (this.isScanUIModalOpened()) this.setTransformToLookupDialog();
  };

  selectRow(index: number): void {
    this.setAndEmitSelectedIndex(index);
  }

  getSelectedRow() {
    for (let i = 0; i < this.matches.length; i++) {
      if (this.matches[i].type === LookupMatchType.Exact) {
        this.setAndEmitSelectedIndex(i);
        return;
      }
    }

    this.setAndEmitSelectedIndex(0);
  }

  scrollToSelectedRow(event: KeyboardEvent) {
    event.preventDefault();
    event.stopPropagation();

    this.delay.execute(() => {
      const element = document.querySelector('.match-row.selected');
      const container = document.querySelector('#matchesTableBody');

      if (!this.calculationsService.isVisibleInScrollableElement(element, container, false)) {
        element.scrollIntoView({ block: 'nearest' });
      }
    }, 0);
  }

  moveUp(event: KeyboardEvent) {
    event.stopPropagation();
    const index = this.selectedRowIndex === 0 ? this.matches.length - 1 : this.selectedRowIndex - 1;
    this.setAndEmitSelectedIndex(index);
  }

  moveDown(event: KeyboardEvent) {
    event.stopPropagation();
    const index = this.selectedRowIndex === this.matches.length - 1 ? 0 : this.selectedRowIndex + 1;
    this.setAndEmitSelectedIndex(index);
  }

  setAndEmitSelectedIndex(index: number) {
    this.selectedRowIndex = index;
  }

  getPreferenceValue(key: string): string {
    return this.userPreferencesService.getPreference(key);
  }

  onWidthResize(preference: Preference) {
    this.userPreferencesService.setPreference(preference.name, preference.value);
    if (this.isScanUIModalOpened()) this.setTransformToLookupDialog();
  }

  setTransformToLookupDialog() {
    const resizableElementWidth = parseInt(this.resizableLookupModal.getElement().offsetWidth);
    const lookupDialog = document.querySelector('.nsm-dialog.lookup-modal') as HTMLElement;
    const scanUIDialog = document.querySelector('.nsm-dialog.scan-ui-modal') as HTMLElement;
    const scanUIDialogWidth = scanUIDialog.offsetWidth;
    const translateX = (scanUIDialogWidth - resizableElementWidth) / 2;
    lookupDialog.style.transform = `translate(${translateX}px, 5%)`;
  }

  isScanUIModalOpened() {
    const openedModals = this.ngxSmartModalService.getOpenedModals();
    const scanUIModal = openedModals.find((modal) => modal.id === 'scanUIModal');
    return !!scanUIModal;
  }

  search = (): void => this.onSearch.emit(this.value);

  selectValue = (): void => {
    this.onSelectValue.emit(this.selectedRowIndex);
    this.close();
  };

  close = (): void => {
    this.lookupFieldSearchModal.close();
    this.onClose.emit();
  };
}
