import {
  Directive,
  ElementRef,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  Output,
  Renderer2,
} from '@angular/core';

// https://gist.github.com/darrenmothersele/7afda13d858a156ce571510dd78b7624

// <div (appDropZone)="onDrop($event)"></div>
//
// Any files dropped onto the region are then
// returned as a Javascript array of file objects.
// Which in TypeScript is `Array<File>`
//

export interface FileDropEvent {
  files: Array<File>;
}

@Directive({ selector: '[appDropZone]' })
export class DropZoneDirective {
  constructor(private renderer: Renderer2, private element: ElementRef) {}

  @Output('appDropZone') fileDrop = new EventEmitter<FileDropEvent>();

  @Input() preventBodyDrop = true;

  @HostBinding('class.drop-zone-active') active = false;

  @HostListener('drop', ['$event'])
  onDrop(event: any) {
    event.preventDefault();
    this.active = false;

    const { dataTransfer } = event;

    var dropEvent: FileDropEvent = {
      files: [],
    };

    if (dataTransfer.items) {
      for (let i = 0; i < dataTransfer.items.length; i++) {
        // If dropped items aren't files, reject them
        if (dataTransfer.items[i].kind === 'file') {
          dropEvent.files.push(dataTransfer.items[i].getAsFile());
        }
      }
      dataTransfer.items.clear();
    } else {
      for (var i = 0; i < dataTransfer.files.length; i++) {
        dropEvent.files.push(dataTransfer.files[i]);
      }

      dataTransfer.clearData();
    }

    this.fileDrop.emit(dropEvent);

    this.renderer.removeClass(this.element.nativeElement, 'ngx-file-drop__drop-zone--over');
  }

  @HostListener('dragover', ['$event'])
  onDragOver(event: any) {
    if (event.dataTransfer.files && event.dataTransfer.items) {
      if (event.dataTransfer.items.length === 0 && event.dataTransfer.files.length === 0) return;
    }
    event.stopPropagation();
    event.preventDefault();
    this.active = true;

    this.renderer.addClass(this.element.nativeElement, 'ngx-file-drop__drop-zone--over');
  }

  @HostListener('dragleave', ['$event'])
  onDragLeave(event: any) {
    this.active = false;

    this.renderer.removeClass(this.element.nativeElement, 'ngx-file-drop__drop-zone--over');
  }

  @HostListener('body:dragover', ['$event'])
  onBodyDragOver(event: any) {
    if (this.preventBodyDrop) {
      event.preventDefault();
      event.stopPropagation();
    }
  }
  @HostListener('body:drop', ['$event'])
  onBodyDrop(event: any) {
    if (this.preventBodyDrop) {
      event.preventDefault();
    }
  }
}
