import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { FieldDefinition, MetaDataType, PasswordPolicy } from 'shared-code-lib';
import { ItemActionHandler } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/itemActionHandler';
import { ActionService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/action.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { ApiResult } from '../../models/ApiResult';
import { ChangePasswordToHighResult } from '../../models/change-password-to-high-result';
import { HydraApiService } from '../../services/hydra-api.service';
import { UserStateService } from '../../services/user-state.service';

enum Fields {
  ExistingPassword,
  NewPassword,
  ConfirmPassword,
  None,
}

@Component({
  selector: 'app-change-password-modal',
  templateUrl: './change-password-modal.component.html',
  styleUrls: ['./change-password-modal.component.scss'],
})
export class ChangePasswordModalComponent implements OnInit {
  @Output() closeModal = new EventEmitter();
  @Input() existingPasswordExpired: boolean = false;
  @Input() description = '';
  @Input() forceHighAuthenticationStrength = false;
  @Input() data: ChangePasswordToHighResult;

  fieldUserExistingPassword: FieldDefinition;
  fieldUserNewPassword: FieldDefinition;
  fieldUserNewPasswordConfirm: FieldDefinition;

  existingPassword: string = '';
  newPassword: string = '';
  newPasswordConfirm: string = '';
  passwordPolicy: PasswordPolicy;

  currentFocusField: Fields = Fields.None;

  errors: string[] = [];

  itemActionHandler: ItemActionHandler;

  constructor(
    public userState: UserStateService,
    private toastr: ToastrService,
    private translateService: TranslateService,
    private hydraApi: HydraApiService,
    private spinnerService: SpinnerStateService,
    private actionService: ActionService
  ) {}

  ngOnInit(): void {
    this.itemActionHandler = this.actionService.createItemActionHandler();

    this.createFields();
    this.currentFocusField = Fields.ExistingPassword;
    this.spinnerService.show(
      this.translateService.instant('MainHeader.loading-password-requirements'),
      document.documentElement
    );
    this.hydraApi.getPasswordPolicy(this.passwordPolicyLoaded, this.passwordPolicyLoadFailed);
  }

  passwordPolicyLoaded = (pp: PasswordPolicy): void => {
    this.passwordPolicy = pp;
    this.spinnerService.hide();
  };

  passwordPolicyLoadFailed = () => {
    this.toastr.error(this.translateService.instant('MainHeader.failed-to-load-password-requirements'));
    this.spinnerService.hide();
  };

  createFields = () => {
    this.fieldUserExistingPassword = new FieldDefinition({
      type: MetaDataType.Password,
      label: this.translateService.instant('MainHeader.field-existing-password'),
      placeholder: this.translateService.instant('MainHeader.field-existing-password-placeholder'),
      required: true,
    });

    this.fieldUserNewPassword = new FieldDefinition({
      type: MetaDataType.Password,
      label: this.translateService.instant('MainHeader.field-new-password'),
      placeholder: this.translateService.instant('MainHeader.field-new-password-placeholder'),
      required: true,
    });

    this.fieldUserNewPasswordConfirm = new FieldDefinition({
      type: MetaDataType.Password,
      label: this.translateService.instant('MainHeader.field-confirm-password'),
      placeholder: this.translateService.instant('MainHeader.field-confirm-password-placeholder'),
      required: true,
    });
  };

  applyChangePassword = (): void => {
    this.currentFocusField = Fields.None;

    if (!this.existingPassword.length) {
      this.errors = ['MainHeader.existing-password-required'];
      this.currentFocusField = Fields.ExistingPassword;
      return;
    }

    if (!this.newPassword.length) {
      this.errors = ['MainHeader.new-password-required'];
      this.currentFocusField = Fields.NewPassword;
      return;
    }

    if (this.newPassword != this.newPasswordConfirm) {
      this.errors = ['MainHeader.password-mismatch'];
      this.currentFocusField = Fields.ConfirmPassword;
      return;
    }

    this.spinnerService.show(this.translateService.instant('MainHeader.changing-password'), document.documentElement);

    this.userState.setPassword(
      this.existingPassword,
      this.newPassword,
      this.onPasswordSaved,
      this.onFailedSavePassword,
      this.forceHighAuthenticationStrength
    );
  };

  onPasswordSaved = (result: ApiResult): void => {
    this.spinnerService.hide();

    if (result.success) {
      this.toastr.success(this.translateService.instant('MainHeader.saved-password'));
      this.closeAndSendNewPassword();

      if (!this.data?.action || !this.data?.extraParameters) return;

      const { folderId, ids, filters } = this.data.extraParameters;

      this.itemActionHandler.invoke(
        folderId,
        this.data.action,
        ids.map((id) => ({
          id,
        })),
        filters
      );
    } else {
      this.errors = result.errors;
      this.currentFocusField = Fields.ExistingPassword;
    }
  };

  onFailedSavePassword = (): void => {
    this.spinnerService.hide();
    this.errors = ['MainHeader.failed-set-password'];
    this.currentFocusField = Fields.ExistingPassword;
  };

  existingPasswordFocused(): boolean {
    return this.currentFocusField === Fields.ExistingPassword;
  }

  newPasswordFocused(): boolean {
    return this.currentFocusField === Fields.NewPassword;
  }

  confirmPasswordFocused(): boolean {
    return this.currentFocusField === Fields.ConfirmPassword;
  }

  closeAndSendNewPassword = (): void => {
    this.closeModal.emit(this.newPassword);
  };

  cancel = () => {
    this.closeModal.emit();
  };
}
