export class StepDesignerProperties {
  x: number;
  y: number;

  constructor(intializer: IStepDesignerProperties) {
    this.x = intializer.x;
    this.y = intializer.y;
  }

  serializable() {
    return {
      x: this.x,
      y: this.y,
    };
  }
}

export interface IStepDesignerProperties {
  x: number;
  y: number;
}
