import { IContourPoints, IPoint } from '../models/scanner';

export interface IRotateResult {
  rotatedImage: string;
  newWidth: number;
  newHeight: number;
}

export const rotateImage = (imageURL: string, angleInDegrees: number): Promise<IRotateResult> => {
  return new Promise((resolve) => {
    const img = new Image();

    img.onload = () => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d') as CanvasRenderingContext2D;
      const angleInRadians = (angleInDegrees * Math.PI) / 180;

      canvas.width = Math.abs(Math.cos(angleInRadians)) * img.width + Math.abs(Math.sin(angleInRadians)) * img.height;
      canvas.height = Math.abs(Math.sin(angleInRadians)) * img.width + Math.abs(Math.cos(angleInRadians)) * img.height;

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.translate(canvas.width / 2, canvas.height / 2);
      ctx.rotate(angleInRadians);
      ctx.drawImage(img, -img.width / 2, -img.height / 2);
      ctx.setTransform(1, 0, 0, 1, 0, 0);

      resolve({
        rotatedImage: canvas.toDataURL('image/png'),
        newWidth: canvas.width,
        newHeight: canvas.height,
      });
    };

    img.src = imageURL;
  });
};

export const rotateBoundaries = (
  boundaries: IContourPoints,
  originalWidth: number,
  originalHeight: number,
  angleInDegrees: number
): IContourPoints => {
  return {
    topLeft: rotatePoint(boundaries.topLeft, originalWidth, originalHeight, angleInDegrees),
    topRight: rotatePoint(boundaries.topRight, originalWidth, originalHeight, angleInDegrees),
    bottomLeft: rotatePoint(boundaries.bottomLeft, originalWidth, originalHeight, angleInDegrees),
    bottomRight: rotatePoint(boundaries.bottomRight, originalWidth, originalHeight, angleInDegrees),
  };
};

export const swapBoundariesKeysBasedOnRotation = (
  boundaries: IContourPoints,
  angleInDegrees: number
): IContourPoints => {
  if ([0, 360].includes(angleInDegrees)) return boundaries;

  if (![90, 180, 270].includes(angleInDegrees)) throw new Error('Angle is not supported');

  if (angleInDegrees === 90) {
    return {
      topLeft: boundaries.bottomLeft,
      topRight: boundaries.topLeft,
      bottomRight: boundaries.topRight,
      bottomLeft: boundaries.bottomRight,
    };
  }

  if (angleInDegrees === 180) {
    return {
      topLeft: boundaries.bottomRight,
      topRight: boundaries.bottomLeft,
      bottomRight: boundaries.topLeft,
      bottomLeft: boundaries.topRight,
    };
  }

  return {
    topLeft: boundaries.topRight,
    topRight: boundaries.bottomRight,
    bottomRight: boundaries.bottomLeft,
    bottomLeft: boundaries.topLeft,
  };
};

const rotatePoint = (point: IPoint, originalWidth: number, originalHeight: number, angleInDegrees: number): IPoint => {
  const cartesianPoint = imagePointToCartesian(point, originalWidth, originalHeight);

  if ([0, 360].includes(angleInDegrees)) return point;

  if (![90, 180, 270].includes(angleInDegrees))
    throw new Error('Angle is not supported until now but you can extend the function');

  if (angleInDegrees === 90) {
    return cartesianToImagePoint({ x: cartesianPoint.y, y: -cartesianPoint.x }, originalHeight, originalWidth);
  }

  if (angleInDegrees === 180) {
    return cartesianToImagePoint({ x: -cartesianPoint.x, y: -cartesianPoint.y }, originalHeight, originalWidth);
  }

  return cartesianToImagePoint({ x: -cartesianPoint.y, y: cartesianPoint.x }, originalHeight, originalWidth);
};

const imagePointToCartesian = (point: IPoint, imageWidth: number, imageHeight: number): IPoint => {
  return { x: point.x - imageWidth / 2, y: imageHeight / 2 - point.y };
};

const cartesianToImagePoint = (point: IPoint, imageWidth: number, imageHeight: number): IPoint => {
  return { x: point.x + imageWidth / 2, y: imageHeight / 2 - point.y };
};
