import { Location } from '@angular/common';
import { Component, OnDestroy, OnInit, ViewEncapsulation } from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';

import { DelayService } from 'shared-code-lib';
import { ItemActionHandler } from '../../core/itemActionHandler';
import { Log } from '../../core/log';
import { ActionService } from '../../services/action.service';
import { ApiService } from '../../services/api.service';
import { UserStateService } from '../../services/user-state.service';
import { VerticalNavService } from '../../services/vertical-nav.service';
import { ActionTypes, IAction, IProduct, IUser } from './../../services/models';

declare const UES: any;

@Component({
  selector: '[appVerticalNav]',
  templateUrl: './vertical-nav.component.html',
  styleUrls: ['./vertical-nav.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class VerticalNavComponent implements OnInit, OnDestroy {
  products: Array<IProduct>;
  route: string;
  previousRoute: string;
  itemActionHandler: ItemActionHandler;
  actions: Array<IAction> = [];
  leftNavActions: Array<IAction> = [];
  leftNavBottomActions: Array<IAction> = [];
  leftNavProducts: Array<IProduct> = [];
  addContentActions: Array<IAction> = [];

  settingsActions: Array<IAction> = [];
  settingsCategoryOrder = ['', 'dwf-if-rm', 'dwf-if-d', 'if-user', 'if-account'];

  currentSubMenu: string;
  isExpanded = true;

  settingsCategories: { id: string; title: string; actions: IAction[]; products: IProduct[] }[] = [];

  private subscriptions = new Subscription();

  constructor(
    private userState: UserStateService,
    router: Router,
    private location: Location,
    private translate: TranslateService,
    private apiService: ApiService,
    private toastr: ToastrService,
    private delay: DelayService,
    private verticalNav: VerticalNavService,
    private translateService: TranslateService,
    private actionService: ActionService
  ) {
    this.itemActionHandler = this.actionService.createItemActionHandler();

    this.subscriptions.add(
      router.events.subscribe((val) => {
        const url = (val as any).url;
        if (url) {
          this.route = url.toLowerCase();
        }
      })
    );
  }

  ngOnInit() {
    this.subscriptions.add(this.userState.userChanged.subscribe(this.onUserChanged));

    this.subscriptions.add(
      this.verticalNav.onToggleVerticalNav$.subscribe((isExpanded) => (this.isExpanded = isExpanded))
    );

    this.subscriptions.add(this.userState.userChanged.subscribe(this.initializeUES));
  }

  initializeUES = (user): void => {
    if (!user) return;

    this.apiService.queryServer('help/uesconfig').subscribe(this.uesConfigLoaded, this.uesConfigFailed);
  };

  uesConfigLoaded = (token: any): void => {
    try {
      UES.destroy();
      UES.init(token);
    } catch (e) {
      console.error(e);
    }
  };

  uesConfigFailed = (error: any): void => {
    this.toastr.error(this.translateService.instant('help.ues-config-load-failed'));
    Log.error('help.ues-config-load-failed', error);
  };

  onUserChanged = (user: IUser) => {
    this.actions = [];
    this.leftNavActions = [];
    this.leftNavProducts = [];
    this.leftNavBottomActions = [];
    this.settingsActions = [];
    this.addContentActions = [];
    this.settingsCategories = [];

    if (!user) return;

    this.products = user && user.products;

    if (!this.products) return;

    this.products.forEach((product) => {
      if (product.folders.length > 0 && product.displayInNavigation) {
        this.leftNavProducts.push(product);
      } else {
        this.actions = [...this.actions, ...product.actions];
      }
    });

    this.actions.forEach((action) => {
      if (action.type === ActionTypes.LeftNav) {
        this.leftNavActions.push(action);
      }
    });

    this.actions.forEach((action) => {
      if (action.type === ActionTypes.LeftNavBottom) {
        this.leftNavBottomActions.push(action);
      }
    });

    for (const p of user.products) {
      for (const a of p.actions) {
        if (this.isSettingsAction(a)) {
          this.settingsActions.push(a);
        }

        if (this.isNewContentAction(a)) {
          this.addContentActions.push(a);
        }
      }
    }

    if (this.addContentActions.length == 1) {
      this.moveAddContentToLeftNav();
    }

    this.leftNavActions.sort(this.sortAction);
    this.leftNavBottomActions.sort(this.sortAction);
    this.settingsActions.sort(this.sortAction);

    this.settingsCategoryOrder
      .filter((a) => this.hasSettingsActionsForCategory(a))
      .forEach((a) =>
        this.settingsCategories.push({
          id: a,
          title: this.getTitleForSettingsCategory(a),
          actions: this.getSettingsActionsForCategory(a),
          products: this.products,
        })
      );
  };

  sortAction = (x: IAction, y: IAction): number => {
    if (x.order == y.order) return x.name.localeCompare(y.name);

    return x.order - y.order;
  };

  moveAddContentToLeftNav = (): void => {
    const action = this.addContentActions[0];

    this.addContentActions = [];

    this.leftNavActions.unshift(action);
  };

  hasSettingsActionsForCategory = (category: string): boolean => {
    return this.settingsActions.some((a) => a.settingsCategory == category);
  };

  getSettingsActionsForCategory = (category: string): Array<IAction> => {
    return this.settingsActions.filter((a) => a.settingsCategory == category);
  };

  getTitleForSettingsCategory = (category: string): string => {
    return this.translate.instant(`settings.category-${category}`);
  };

  ngOnDestroy() {
    this.subscriptions.unsubscribe();
  }

  onAddContentActionClicked = (action: IAction) => {
    this.itemActionHandler.invoke('', action, [], []);
  };

  onSettingsActionClicked = (action: IAction) => {
    this.itemActionHandler.invoke('', action, [], []);
  };

  hasNewContentActions = (): boolean => {
    if (!this.products) return false;

    for (let p of this.products) {
      for (let a of p.actions) {
        if (this.isNewContentAction(a)) return true;
      }
    }

    return false;
  };

  hasSettingsActions = (): boolean => {
    if (!this.products) return false;

    for (let p of this.products) {
      if (p.settingsUrl) return true;

      for (let a of p.actions) {
        if (this.isSettingsAction(a)) return true;
      }
    }

    return false;
  };

  isNewContentAction = (action: IAction) => {
    return (action.type & ActionTypes.NewContent) !== 0;
  };

  isSettingsAction = (action: IAction) => {
    return (action.type & ActionTypes.Settings) !== 0;
  };

  checkIfActive(id: string): boolean {
    if (this.location.path().toLowerCase() === id.toLowerCase()) return true;

    switch (id.toLowerCase()) {
      case '$settings':
        return this.route && this.route.split('/')[1] === 'settings';

      default:
        return this.route === id.toLowerCase();
    }
  }

  onShow(subMenu: string) {
    this.delay.execute(() => {
      this.currentSubMenu = subMenu;
      if (this.route) {
        this.previousRoute = this.route;
      }

      this.route = null;
    }, 0);
  }

  onHide() {
    this.currentSubMenu = null;
    this.route = this.previousRoute;
  }

  trackById(_, name) {
    return name.id;
  }

  toggleVerticalNav() {
    this.verticalNav.toggleVerticalNav(!this.isExpanded, true);
  }
}
