import { Injectable } from '@angular/core';
import { Feature } from 'shared-code-lib';
import { UserStateService } from '../../../../blocks/services/user-state.service';

@Injectable({
  providedIn: 'root',
})
export class UploadConfigService {
  constructor(private userState: UserStateService) {}

  getUploadConfig() {
    let supportedFileTypes = '';
    let uploadTooltip = '';

    if (this.userState.hasFeature(Feature.OLCTED) && this.userState.hasFeature(Feature.OLCAPI)) {
      supportedFileTypes = '.zip,.ol-package,.ol-template';
      uploadTooltip = 'admin-olc-templates.upload-text-ted-and-api';
    } else if (this.userState.hasFeature(Feature.OLCTED)) {
      supportedFileTypes = '.zip,.ol-package';
      uploadTooltip = 'admin-olc-templates.upload-text-ted';
    } else if (this.userState.hasFeature(Feature.OLCAPI)) {
      supportedFileTypes = '.ol-template';
      uploadTooltip = 'admin-olc-templates.upload-text-api';
    }

    return { supportedFileTypes, uploadTooltip };
  }

  getReplaceConfig(isTEDPackage: boolean) {
    let supportedFileTypes = '';
    let uploadTooltip = '';

    if (isTEDPackage) {
      supportedFileTypes = '.zip,.ol-package';
      uploadTooltip = 'admin-olc-templates.replace-package-text';
    } else {
      supportedFileTypes = '.ol-template';
      uploadTooltip = 'admin-olc-templates.replace-template-text';
    }

    return { supportedFileTypes, uploadTooltip };
  }
}
