import { Pipe, PipeTransform } from '@angular/core';
import { get } from 'lodash';
import { IColumn, ICombinedColumn, Operator } from '../models/column';
import { IValueWithHeaderParameter } from './../models/cell-value-with-header';

@Pipe({
  name: 'cellValueWithHeader',
})
export class CellValueWithHeaderPipe implements PipeTransform {
  transform(value: any, ...args: IValueWithHeaderParameter[]) {
    const param = args[0];
    if (!param) throw new Error('CellValueWithHeaderPipe must have one parameter of type IValueWithHeaderParameter');

    const { column, item } = param;
    const columnHeaderText = this.getColumnHeaderText(column, item);
    return this.shouldAppendHeaderToValue(columnHeaderText, value, column) ? `${value} ${columnHeaderText}` : value;
  }

  private getColumnHeaderText = (column: ICombinedColumn, item: any) => {
    if (column.headerText.trim()) return column.headerText;
    if (!column.dynamicHeaderTexts?.length) return '';

    let firstMatchedHeaderText = '';
    const itemValue = get(item, column.itemProperty);

    for (var i = 0; i < column.dynamicHeaderTexts.length; i++) {
      const { condition, text } = column.dynamicHeaderTexts[i];
      const { compareValue, operator } = condition;

      if (operator === Operator.Equal && itemValue == compareValue) {
        firstMatchedHeaderText = text;
        break;
      }

      if (operator === Operator.NotEqual && itemValue != compareValue) {
        firstMatchedHeaderText = text;
        break;
      }
    }

    return firstMatchedHeaderText;
  };

  private shouldAppendHeaderToValue(columnHeaderText: string, value: any, column: IColumn) {
    return columnHeaderText && column.shouldAppendHeaderToValue && (value !== '' || !column.ignoreHeaderForEmptyValue);
  }
}
