import { IEvent } from './event';

export enum ItemTypes {
  folder = 0,
  item = 1,
}

export enum EventTypes {
  added = 0,
  updated = 1,
  deleted = 2,
}

export interface IFolderViewEvent extends IEvent {
  eventType: EventTypes;
  itemType: ItemTypes;
}

export class FolderViewEvent implements IFolderViewEvent {
  constructor(public id: string, public data: any, public eventType: EventTypes, public itemType: ItemTypes) {}
}
