export interface IInboundLogBarcode {
  transactionID: number;
  serial: number;
  barcodeType: string;
  value: string;
  page: number;
  x: number;
  y: number;
  width: number;
  height: number;
  confidence: number;
  rotation: number;
}

export class InboundLogBarcode implements IInboundLogBarcode {
  public transactionID: number;
  public serial: number;
  public barcodeType: string;
  public value: string;
  public page: number;
  public x: number;
  public y: number;
  public width: number;
  public height: number;
  public confidence: number;
  public rotation: number;

  constructor(initializer: IInboundLogBarcode) {
    this.transactionID = initializer.transactionID;
    this.serial = initializer.serial;
    this.barcodeType = initializer.barcodeType;
    this.value = initializer.value;
    this.page = initializer.page;
    this.x = initializer.x;
    this.y = initializer.y;
    this.width = initializer.width;
    this.height = initializer.height;
    this.confidence = initializer.confidence;
    this.rotation = initializer.rotation;
  }
}
