import { TranslateService } from '@ngx-translate/core';
import { ScanPages } from '../../views/document-capture/capture-models/scan-commands';

export class Filename {
  static supportedFileTypes = '.pdf,.tif,.tiff,.gif,.png,.jpg,.jpeg,.bmp,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.rtf';
  static supportedImageFileTypes = '.png,.jpg,.jpeg';
  private static documentNameIndex: number = 0;

  static getFileExtension(filePath: string): string {
    if (!filePath) return '';
    const parts = filePath.split('.');
    return parts.length > 1 ? parts[parts.length - 1] : '';
  }

  static getFileNameWithoutExtension(filePath: string): string {
    if (!filePath) return '';
    if (!filePath.includes('.')) return filePath;
    return filePath.substr(0, filePath.lastIndexOf('.'));
  }

  static getDefaultScannedDocumentName = (): string => {
    Filename.documentNameIndex++;
    return 'Document-' + Filename.documentNameIndex;
  };

  static getScannedDocumentName = (scanpages: ScanPages): string => {
    let fileName = scanpages.scanOptions.allowDocumentName ? scanpages.documentProperties.documentName : '';
    if (!fileName || fileName == '') fileName = Filename.getDefaultScannedDocumentName();

    if (!fileName.endsWith('.pdf')) fileName += '.pdf';

    return fileName;
  };

  static getPageCountText(pageCount: number, translate: TranslateService): string {
    const pageSuffix = translate.instant(pageCount === 1 ? 'Document_Capture.page' : 'Document_Capture.pages');

    return `(${pageCount} ${pageSuffix})`;
  }

  static extensionIsOneOf(fileName: string, ext: string[]): boolean {
    return new RegExp(`(${ext.join('|').replace(/\./g, '\\.')})$`).test(fileName);
  }
}
