import { OLCApprovalsFilters } from './../../views/admin-olc/models/filters/approvals-filters';
import { OLCProductionFilters } from './../../views/admin-olc/models/filters/production-filters';
import { OLCTemplateVersionsFilters } from './../../views/admin-olc/models/filters/template-versions-filters';
import { InterFAXFilters } from './../InterFAX/models/filters';
import { DataSourceFilters } from './datasource-filters';
import { DeviceFilters } from './device-filters';
import { DWFToolsItemsFilters } from './dwf-tools-items-filter';
import { FaxUsersFilters } from './fax-users-filter';
import { Filter, IFilter } from './filter';
import { LoginChartFilters } from './login-chart-filters';
import { LogsFilters } from './logs-filter';
import { MetaDataFilters } from './metadata-filters';
import { OneDriveFilters } from './one-drive-filters';
import { SentFaxesChartFilters } from './sent-faxes-chart-filters';
import { TenantFilters } from './tenant-filters';
import { UserFilters } from './user-filters';
import { WorkflowFilters } from './workflow-filters';
import { WorkItemFilters } from './workitem-filter';

export class FilterFactory {
  public static Create = (ifilter: IFilter): Filter => {
    if (!ifilter.hasUI) return new Filter(ifilter);

    let filter = WorkItemFilters.Create(ifilter);
    if (filter) return filter;

    filter = DataSourceFilters.Create(ifilter);
    if (filter) return filter;

    filter = InterFAXFilters.Create(ifilter);
    if (filter) return filter;

    filter = DeviceFilters.Create(ifilter);
    if (filter) return filter;

    filter = TenantFilters.Create(ifilter);
    if (filter) return filter;

    filter = UserFilters.Create(ifilter);
    if (filter) return filter;

    filter = MetaDataFilters.Create(ifilter);
    if (filter) return filter;

    filter = WorkflowFilters.Create(ifilter);
    if (filter) return filter;

    filter = LoginChartFilters.Create(ifilter);
    if (filter) return filter;

    filter = SentFaxesChartFilters.Create(ifilter);
    if (filter) return filter;

    filter = OneDriveFilters.Create(ifilter);
    if (filter) return filter;

    filter = LogsFilters.Create(ifilter);
    if (filter) return filter;

    filter = FaxUsersFilters.Create(ifilter);
    if (filter) return filter;

    filter = DWFToolsItemsFilters.Create(ifilter);
    if (filter) return filter;

    filter = OLCTemplateVersionsFilters.Create(ifilter);
    if (filter) return filter;

    filter = OLCApprovalsFilters.Create(ifilter);
    if (filter) return filter;

    filter = OLCProductionFilters.Create(ifilter);
    if (filter) return filter;

    throw new Error(`Unknown Filter Type ${ifilter.id}`);
  };
}
