import { Contact, IContact } from './contact';

export interface IContactList {
  id: string;
  name: string;
  isPrivate: boolean;
  members: Array<IContact>;
  hasContacts: boolean;
}

export class ContactList {
  public id: string;
  public name: string;
  public isPrivate: boolean;
  public members: Array<Contact>;
  public hasContacts: boolean;

  constructor(cl: IContactList = null) {
    this.id = cl ? cl.id : '';
    this.name = cl ? cl.name : '';
    this.isPrivate = cl ? cl.isPrivate : false;
    this.members = cl ? cl.members.map((m) => new Contact(m)) : [];
    this.hasContacts = cl ? cl.hasContacts : false;
  }

  serializable(): IContactList {
    return {
      id: this.id,
      name: this.name,
      isPrivate: this.isPrivate,
      members: this.members.map((m) => m.serializable()),
      hasContacts: this.hasContacts,
    };
  }
}
