import { ChangeDetectorRef, Component, ElementRef, HostListener, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { Subscription } from 'rxjs';

import { CaptureUpdateService } from '../../../../../Bamba.Web/ClientApp/src/app/views/document-capture/capture-services/capture-update.service';
import { DropDownDirection } from '../../../models/drop-down';
import { MetaDataValidity } from '../../../models/metadata';
import { RepeatedService } from '../../../utils/repeated.service';
import { IFieldOptions } from './../../../models/field-definition';
import { CalculationsService } from './../../../utils/calculations.service';
import { DelayService } from './../../../utils/delay.service';
import { Key } from './../../../utils/key-enum';
import { IDropDownData } from './drop-down.model';
import { DropDownService } from './drop-down.service';

declare const $: any;

@Component({
  templateUrl: './drop-down.component.html',
  styleUrls: ['./drop-down.component.scss'],
})
export class DropDownComponent implements OnInit, OnDestroy {
  @ViewChild(PerfectScrollbarDirective) directiveRef?: PerfectScrollbarDirective;
  @ViewChild('dropDown', { static: true }) dropDown: ElementRef;
  @ViewChild('searchField') search: ElementRef;
  data: IDropDownData;
  searchTerm: string = '';
  currentIndex: number;
  filtered: Array<IFieldOptions> = [];
  subscriptions: Subscription;
  selectedValue: string;
  readonly maxDropdownHeight = 375;
  checkParentPositionInterval: Subscription;
  noResultMessage: string;
  direction: string;
  metaDataValidity = MetaDataValidity;
  disableMouseHoverEvents = false;

  filteredItemsLoading = false;

  @HostListener('window:resize')
  onResize() {
    this.initDropDownPosition();
  }
  @HostListener('window:scroll', ['$event'])
  scrollHandler(event: Event) {
    this.initDropDownPosition();
  }

  public _dropDown: DropDownService;

  constructor(
    private calculations: CalculationsService,
    private captureUpdate: CaptureUpdateService,
    private delay: DelayService,
    private translate: TranslateService,
    private repeat: RepeatedService,
    private cdr: ChangeDetectorRef
  ) {
    this.currentIndex = -1;
    this.subscriptions = new Subscription();
  }

  ngOnInit() {
    $('body').scroll(() => {
      this.initDropDownPosition();
    });

    this.data.searchTerm.subscribe((term) => {
      this.searchTerm = term;
    });

    this.subscriptions.add(
      this.data.options.subscribe((options) => {
        this.cdr.detach();

        this.filtered = [];
        this.filteredItemsLoading = options == null;

        if (options) {
          for (const option of options) {
            if (this.filterHandler(option)) {
              this.filtered.push(option);
            }
          }
        }

        this.currentIndex = this.filtered.findIndex((o) => o.value === this.selectedValue);
        if (this.currentIndex > -1) {
          this.selectCurrentIndex();
        }

        this.filtered = [...this.filtered];
        this.directiveRef?.update();
        this.cdr.reattach();
        this.cdr.detectChanges();
        this.initDropDownPosition(true);
      })
    );

    this.selectedValue = this.data.value as string;

    this.subscriptions.add(this.captureUpdate.onPanelsResize.subscribe(() => this.initDropDownPosition()));

    this.subscriptions.add(this._dropDown.onArrowUpDown.subscribe((event: KeyboardEvent) => this.onKey(event)));

    this.subscriptions.add(this._dropDown.onScrollUpOrDown.subscribe(() => this.initDropDownPosition()));

    this.subscriptions.add(
      this._dropDown.onKeydown.subscribe((e) => {
        this.onKey(e);
      })
    );

    if (!this.data.disableSearch) {
      this.delay.execute(() => {
        this.search?.nativeElement?.focus();
        this.initDropDownPosition();
      }, 50);
    } else {
      this.searchTerm = (this.data.value as string) || '';
      this.data.searchTerm.next(this.searchTerm);
      this.initDropDownPosition();

      this.checkParentPositionInterval = this.repeat.start(100).subscribe(() => {
        if (this.calculations.isVisibleInScrollableElement(this.data.parent, null, false)) {
          this.initDropDownPosition();
        } else {
          this._dropDown.hide();
        }
      });
    }

    if (!this.data.noResultMessage) {
      this.noResultMessage = this.translate.instant('Common.NoResult');
    } else {
      this.noResultMessage = this.data.noResultMessage;
    }
  }

  ngOnDestroy() {
    this.subscriptions.unsubscribe();
    if (this.checkParentPositionInterval) {
      this.repeat.stop(this.checkParentPositionInterval);
    }
  }

  initDropDownPosition(keepPosition?: boolean) {
    const parent = $(this.data.parent);
    const dropDown = $(this.dropDown.nativeElement);
    const left = parent.offset().left;
    const { top, height, direction } = this.calculations.getDropDownHeightAndDirection(
      $(this.dropDown.nativeElement),
      parent,
      this.maxDropdownHeight
    );

    dropDown.css({
      height: height,
      width: parent.outerWidth(),
      top: `${top}px`,
      left: `${left}px`,
      opacity: 1,
    });

    if (this.direction != DropDownDirection[direction]) this._dropDown.directionChanged(direction);
    this.direction = DropDownDirection[direction];
  }

  onKey = (event: KeyboardEvent): void => {
    if (event.key === Key.Tab) {
      this._dropDown.tab(event);
    }

    if (event.key === Key.ArrowDown) {
      event.stopPropagation();
      this.currentIndex++;
      if (this.currentIndex >= this.filtered.length) {
        this.currentIndex = 0;
      }

      this.checkIfItemIsNotInViewAndScroll();
      event.preventDefault();
    } else if (event.key === Key.ArrowUp) {
      event.stopPropagation();
      this.currentIndex--;
      if (this.currentIndex < 0) {
        this.currentIndex = this.filtered.length - 1;
      }

      this.checkIfItemIsNotInViewAndScroll();
      event.preventDefault();
    } else if (event.key === Key.Enter) {
      this.selectCurrentIndex(true);
    }
  };

  checkIfItemIsNotInViewAndScroll() {
    this.selectCurrentIndex();
    const selectedElement = $(`.option-item-${this.currentIndex}`);
    const container = $('.items-wrapper');
    if (
      selectedElement[0] &&
      container[0] &&
      !this.calculations.isVisibleInScrollableElement(selectedElement, container, false)
    ) {
      const animationSpeed = 100;
      this.disableMouseHoverEvents = true;
      this.directiveRef?.scrollToElement(`.option-item-${this.currentIndex}`, 0, animationSpeed);
      setTimeout(() => {
        this.disableMouseHoverEvents = false;
      }, animationSpeed);
    }
  }

  selectCurrentIndex = (viaClick = false): void => {
    if (!this.filtered) {
      return;
    }

    if (this.currentIndex < 0 || this.currentIndex >= this.filtered.length) {
      return;
    }

    this.select(this.filtered[this.currentIndex], viaClick);
  };

  select(option: any, viaClick = true) {
    if (viaClick || this.data.value !== option.value || this.data.fireChangeEventIfSameValue) {
      this.data.value = option.value;
      this.selectedValue = option.value;
      this._dropDown.select(option);
      if (viaClick) this._dropDown.selectViaClick(option);
    }
  }

  private filterHandler(option: any): boolean {
    if (this.data.startsWithFiltering) {
      return option.name.toLowerCase().startsWith(this.searchTerm.replace(String.fromCharCode(160), ' ').toLowerCase());
    } else {
      return option.name.toLowerCase().indexOf(this.searchTerm.toLowerCase()) !== -1;
    }
  }

  getSelectedIndexValue = (): string => {
    if (!this.filtered || this.currentIndex == null) {
      return '';
    }

    if (this.currentIndex < 0 || this.currentIndex >= this.filtered.length) {
      return '';
    }

    return this.filtered[this.currentIndex].value.toString();
  };

  handlePropagation(event: any) {
    if (!event.target.classList.contains('option-item')) {
      event.stopPropagation();
    }
  }

  onClickOutside(): void {
    this._dropDown.clickOutside();
  }

  onMouseEnter = (e: MouseEvent, itemValue: string) => {
    if (this.disableMouseHoverEvents) return;

    this.currentIndex = this.filtered.findIndex((o) => o.value === itemValue);
  };
}
