import { Injectable, OnDestroy } from '@angular/core';

import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { Observable, Subject, Subscription } from 'rxjs';
import { debounceTime, delay, distinctUntilChanged, first, switchMap } from 'rxjs/operators';

import {
  Annotation,
  DelayService,
  Files,
  IMetaData,
  IMetaDataDefinition,
  IMetaDataValidator,
  Location,
  LookupToBeSaved,
  MetaDataCollection,
  MetaDataDefinition,
  MetaDataLineItems,
  MetaDataType,
  MetaDataValidity,
  MetaDataValueType,
  ValidationRequest,
} from 'shared-code-lib';
import { UpdateDocument } from '../../../blocks//models/update-document';
import { Filename } from '../../../blocks/core/fileName';
import { CreateDocument } from '../../../blocks/models/create-document';
import { Document } from '../../../blocks/models/document';
import { IOutcome, Outcome } from '../../../blocks/models/outcome';
import { TransitionResult } from '../../../blocks/models/transition-result';
import { WorkItem } from '../../../blocks/models/work-item';
import { Workflow } from '../../../blocks/models/workflow';
import { WorkflowFolder } from '../../../blocks/models/workflow-folder';
import { InteractiveWorkflowStep, WorkflowStep } from '../../../blocks/models/workflow-step';
import { ErrorsService } from '../../../blocks/services/errors.service';
import { HydraApiService } from '../../../blocks/services/hydra-api.service';
import { InProgressService } from '../../../blocks/services/in-progress.service';
import { ApiResult } from '../../../blocks/services/models';
import { SpinnerStateService } from '../../../blocks/services/spinner-state.service';
import { UserStateService } from '../../../blocks/services/user-state.service';
import { Batch, Capture, CapturedDocument, DragData, LineItemHeader, Page, PageState } from '../capture-models';
import { SelectedItemType } from '../capture-models/selected-item';
import { CaptureUpdateService } from './capture-update.service';
import { DocumentLastTouchedService } from './document-last-touched.service';
import { DocumentViewerService } from './document-viewer.service';
import { IndexingPanelService } from './indexing-panel.service';
import { OutcomesService } from './outcomes.service';
import { ScanAppService } from './scan-app.service';
import { SelectedItemsService } from './selected-items.service';

@Injectable({
  providedIn: 'root',
})
export class DocumentCaptureService implements IMetaDataValidator, OnDestroy {
  private _captureObject: Capture;
  private _currentBatch: Batch;
  private _currentWorkflow: Workflow;
  private _workflowFirstFolder: WorkflowFolder;
  private _currentFolder: WorkflowFolder;
  private _currentWorkItem: WorkItem;
  private _currentDocument: CapturedDocument;
  private _currentPage: Page;
  private _documentNameIndex: number;
  private _savingIndexingValueInProgress: boolean;
  private hydraPendingInterval: number;
  private batchCount: number;
  private batchIndex: number;
  private batchFiles: File[];
  private batchMetaData: MetaDataCollection;
  private successfullyUploadedBatches: number;
  private _lineiItemsMDD: Array<IMetaDataDefinition>;
  private _lineItemMetaDataName: string;
  private folders: Array<WorkflowFolder> = [];
  private _startMetaDataValidationSubject = new Subject<string>();
  onStartMetaDataValidation = this._startMetaDataValidationSubject.asObservable();
  private _completeMetaDataValidationSubject = new Subject<string>();
  onCompleteMetaDataValidation = this._completeMetaDataValidationSubject.asObservable();
  private metaDataChangeProgress: Subject<boolean> = new Subject<boolean>();
  private outcomeSubject: Subject<IOutcome> = new Subject<IOutcome>();
  private cancelSelectDocumentOnAppendMorePages: boolean = false;
  subscription: Subscription;

  setMetaDataChangeInProgress(value: boolean) {
    this.metaDataChangeProgress.next(value);
  }

  getMetaDataChangeInProgress(): Observable<boolean> {
    return this.metaDataChangeProgress.asObservable().pipe(debounceTime(100), distinctUntilChanged());
  }

  executeOutcome = (outcome: IOutcome): void => {
    this.outcomeSubject.next(outcome);
  };

  constructor(
    private indexing: IndexingPanelService,
    private userStateService: UserStateService,
    private hydraApi: HydraApiService,
    private captureUpdate: CaptureUpdateService,
    private toastrService: ToastrService,
    private translate: TranslateService,
    private inProgress: InProgressService,
    private scanAppService: ScanAppService,
    private viewerService: DocumentViewerService,
    private delay: DelayService,
    private toastr: ToastrService,
    private documentLastTouchedService: DocumentLastTouchedService,
    private outcomesService: OutcomesService,
    private selectedItemsService: SelectedItemsService,
    private errorsService: ErrorsService,
    private spinnerService: SpinnerStateService
  ) {
    this.clean();

    this.init();
  }

  private init(): void {
    this._currentBatch = null;
    this._currentDocument = null;
    this._currentPage = null;
    this._currentFolder = null;
    this._currentWorkflow = null;
    this._documentNameIndex = 0;

    this.subscription = new Subscription();

    this.subscription.add(
      this.outcomeSubject
        .asObservable()
        .pipe(delay(100), this.waitForFalse(this.getMetaDataChangeInProgress()))
        .subscribe((outcome) => {
          if (outcome.requiresConfirmation) {
            this.outcomesService.confirmOutcome(outcome, this.confirmedOutcome);
          } else {
            this.transitionSelectedItems(outcome.id);
          }
        })
    );
  }

  confirmedOutcome = (data: any) => {
    this.transitionSelectedItems(data.id);
  };

  waitForFalse<T>(signal: Observable<boolean>) {
    return (source: Observable<T>) =>
      signal.pipe(
        first((a) => a == false),
        switchMap((_) => source)
      );
  }

  get captureObject() {
    return this._captureObject;
  }
  get currentBatch() {
    return this._currentBatch;
  }
  get currentPage() {
    return this._currentPage;
  }

  get currentWorkflow() {
    return this._currentWorkflow;
  }

  addBatch(
    e: any,
    md?: MetaDataCollection,
    successCallBack?: (workitem: WorkItem) => void,
    failureCallBack?: () => void
  ): void {
    const file = e.type === 'message' ? e.data : e;

    const workItem = WorkItem.create(this._currentWorkflow.id);
    if (md) {
      workItem.metadata = md;
    }

    const doc = new CreateDocument(
      file,
      Filename.getFileNameWithoutExtension(file.name),
      Filename.getFileExtension(file.name)
    );

    this.createNewWorkItem(workItem, doc, successCallBack, failureCallBack, false);
  }

  createNewWorkItem(
    workItem: WorkItem,
    doc: CreateDocument,
    successCallBack?: (workitem: WorkItem) => void,
    failureCallBack?: () => void,
    showLoadingMessage: boolean = true
  ) {
    if (showLoadingMessage) this.inProgress.display('app-scan.uploading-documents');

    this.hydraApi.createWorkItem(
      workItem,
      doc,
      (newWorkItem: WorkItem) => {
        this.documentLastTouchedService.setLastTouchedWorkItem(newWorkItem.id);

        if (successCallBack) {
          successCallBack(newWorkItem);
        } else {
          this.inProgress.close();
          this.toastrService.success(this.translate.instant('Document_Capture.upload-success'));
        }
      },
      (err) => {
        this.inProgress.close();
        this.showError(err, 'Common.upload-failed', 'Common.upload-failed');

        if (failureCallBack) failureCallBack();
      }
    );
  }

  discardWorkItem(workItemId: string, successCallBack?: Function) {
    this.outcomesService.transitionWorkItem(Outcome.SendToDoneId, workItemId, successCallBack);
  }

  hasChangedByCurrentUser(workItem: WorkItem, shouldSelect: boolean): boolean {
    const lastTouchedWorkItemId = this.documentLastTouchedService.getLastTouchedWorkItemId();

    if (lastTouchedWorkItemId && lastTouchedWorkItemId === workItem.id) {
      if (!shouldSelect) return true;

      if (!this._savingIndexingValueInProgress) {
        this.documentLastTouchedService.resetLastTouchedWorkItem();
        return true;
      }
    }

    return false;
  }

  setWorkflowFirstFolder(folder: WorkflowFolder): void {
    this._workflowFirstFolder = folder;
    this.selectFolder(folder);
  }

  getWorkflowFirstFolder(): WorkflowFolder {
    return this._workflowFirstFolder;
  }

  getWorkflowStepById(stepId: string): WorkflowStep {
    return this._currentWorkflow?.workflowSteps.find((s) => s.id === stepId) as InteractiveWorkflowStep;
  }

  showNoScanFolderError() {
    this.toastrService.error(this.translate.instant('app-scan.no-folder-to-scan'));
  }

  showNoScanDocumentError() {
    this.toastrService.error(this.translate.instant('app-scan.no-document-to-scan'));
  }

  showNoScanPageError() {
    this.toastrService.error(this.translate.instant('app-scan.no-page-to-scan'));
  }

  showFailedToAddPagesToDocumentError() {
    this.toastrService.error(this.translate.instant('Scanning.AddPagesToDocumentFailed'));
  }

  showFailedToDeletePageFromDocumentError() {
    this.toastrService.error(this.translate.instant('Scanning.DeletePageFromDocumentFailed'));
  }

  showError = (err: any, prefix: string, genericMsg: string): void => {
    const error =
      err && err.error ? `${this.translate.instant(prefix)}: ${err.error}` : this.translate.instant(genericMsg);
    this.toastr.error(error);
  };

  closeScanInProgress() {
    this.scanAppService.closeInProgress();
  }

  getMetaDataId(): string {
    const step = <InteractiveWorkflowStep>(
      this._currentWorkflow.workflowSteps.find((s) => s.id === this._workflowFirstFolder.parentID)
    );

    if (step == null) {
      return '';
    }

    return step.metaDataIds[0]; // todo: this seems a bit hard-coded...
  }

  initIndexing(stepId: string): void {
    this.indexing.toggleLineItemPanel(false);

    const step = <InteractiveWorkflowStep>this._currentWorkflow?.workflowSteps.find((s) => s.id === stepId);
    if (!step) return;

    this.captureUpdate.updateOutcomeButtons(step.clone().outcomes);

    const metaDataDefArray = [];
    for (const id of step.metaDataIds) {
      const metaDefinition = this.userStateService.findMetaDataById(id);
      if (metaDefinition == null) {
        continue;
      }

      if (metaDefinition.type === MetaDataType.LineItems) {
        if (this.selectedItemsService.hasItemsSelected()) {
          this.indexing.toggleLineItemPanel(true);
        }

        const metaDataDefinition = metaDefinition as MetaDataDefinition;
        this._lineiItemsMDD = [];
        this._lineItemMetaDataName = metaDataDefinition.name;

        for (let i = 0; i < metaDataDefinition.lineItemConfigurations.length; i++) {
          const tableColumnHeadMdd = this.userStateService.findMetaDataById(
            metaDataDefinition.lineItemConfigurations[i].metaDataId
          );
          this._lineiItemsMDD.push(tableColumnHeadMdd);
        }

        this.captureUpdate.updateLineItemTableHead(
          new LineItemHeader(
            metaDataDefinition.id,
            metaDataDefinition.name,
            metaDataDefinition.label,
            this._lineiItemsMDD
          )
        );

        if (this._currentWorkItem) {
          let md = this._currentWorkItem.getMetaData(this._lineItemMetaDataName);
          if (md == null) {
            this._currentWorkItem.metadata.setLineItems(this._lineItemMetaDataName, new MetaDataLineItems());
            md = this._currentWorkItem.getMetaData(this._lineItemMetaDataName);
          }

          const lineitems = <MetaDataLineItems>md.value;

          this.captureUpdate.updateLineItemTableBody(lineitems);
        } else {
          this.captureUpdate.updateLineItemTableBody(new MetaDataLineItems());
        }
      } else {
        metaDataDefArray.push(metaDefinition);
      }
    }

    this.indexing.changeCurrentWorkflowStep(metaDataDefArray);
    this.setMetaDataChangeInProgress(false);
  }

  saveLineItems(lineitems: MetaDataLineItems, currentWorkItem: WorkItem = this._currentWorkItem): Promise<WorkItem> {
    currentWorkItem.metadata.setLineItems(this._lineItemMetaDataName, lineitems);

    return new Promise<WorkItem>((resolve, reject) => {
      this.updateWorkItemMetadata(currentWorkItem)
        .then((updatedWorkItem) => {
          currentWorkItem = updatedWorkItem;
          resolve(updatedWorkItem);
        })
        .catch((err) => {
          this.toastrService.error(this.translate.instant('errors.failed-update-workitem-metadata'));
          reject(err);
        });
    });
  }

  addBatchWithMultipleDocuments(files: File[]): void {
    this.batchCount = files.length;
    this.batchIndex = 0;
    this.successfullyUploadedBatches = 0;
    this.batchFiles = files;
    this.batchMetaData = null;
    this.inProgress.open('app-scan.title-import');
    this.addBatchDocuments();
  }

  addBatchDocuments() {
    if (this.batchIndex >= this.batchCount) {
      this.addBatchDocumentsComplete();
      return;
    }

    this.inProgress.displayProgress(
      `${this.translate.instant('app-scan.uploading')} ${this.batchFiles[this.batchIndex].name} ...`,
      this.batchIndex + 1,
      this.batchCount,
      false
    );

    this.addBatch(
      this.batchFiles[this.batchIndex],
      this.batchMetaData,
      (workitem: WorkItem) => {
        this.batchMetaData = workitem.metadata;
        this.successfullyUploadedBatches++;
        this.addNextBatch();
      },
      () => {
        this.addNextBatch();
      }
    );
  }

  addNextBatch() {
    this.batchIndex++;
    this.addBatchDocuments();
  }

  addBatchDocumentsComplete() {
    this.inProgress.close();
    if (this.successfullyUploadedBatches) {
      this.toastrService.success(this.translate.instant('Document_Capture.upload-success'));
    }
  }

  selectFolder(folder: WorkflowFolder, isCtrlKey = false): void {
    if (this.shouldCancelSelectFolder(folder, isCtrlKey)) {
      this.initIndexing(this._currentFolder?.workflowStepId);
      return;
    }

    this.resetSelectedFolder(folder, isCtrlKey);
    this.captureUpdate.updateEnableOutcomeButtonsForFolders(false);
  }

  resetSelectedFolder(folder: WorkflowFolder, isCtrlKey = false): void {
    this._currentPage = null;
    this._currentWorkItem = null;
    this._currentDocument = null;
    this.captureUpdate.updateDocument(this._currentDocument);

    this._currentFolder = folder;
    this.captureUpdate.updateFolder(this._currentFolder);

    this.selectedItemsService.selectTreeFolder(folder, isCtrlKey);

    this.resetCurrentIfOneItemRemained();

    this.initIndexing(folder.workflowStepId);
  }

  shouldCancelSelectFolder(folder: WorkflowFolder, isCtrlKey: boolean): boolean {
    if (
      this._currentFolder &&
      this._currentFolder.id === folder.id &&
      this.selectedItemsService.isOneItemSelected() &&
      this.selectedItemsService.isItemSelected(folder.id, folder.workflowStepId) &&
      !isCtrlKey
    ) {
      return true;
    }

    if (isCtrlKey && this.selectedItemsService.isAnyAncestorSelectedForFolder(folder)) return true;

    if (isCtrlKey && this.selectedItemsService.isInDifferentWorkflowStep(folder.workflowStepId)) return true;

    return false;
  }

  getSelectedFolder(): WorkflowFolder {
    return this._currentFolder;
  }

  handleDragDropDocuments(dragData: DragData, stepId: string, groupingArray: Array<any>) {
    if (
      dragData.elementParentId === dragData.target.id ||
      dragData.element.workflowStepId !== dragData.target.workflowStepId
    ) {
      return;
    } else {
      const step = <InteractiveWorkflowStep>this.getWorkflowStepById(stepId);
      const stepGroupingIds = step.itemGroupingIds;
      const metadataDefinitions: Array<IMetaDataDefinition> = [];
      const workItem = dragData.element as WorkItem;
      for (let i = 0; i < stepGroupingIds.length; i++) {
        metadataDefinitions.push(this.userStateService.findMetaDataById(stepGroupingIds[i]));
      }
      this.validateAndSetGroupOfMetadata(metadataDefinitions, groupingArray, 0, workItem, false);
    }
  }

  deleteDocumentPage(
    workItemId: string,
    documentId: string,
    pageOrder: number,
    successCallBack: () => void,
    failedCallBack: (err: any) => void
  ) {
    this.hydraApi.deleteWorkItemDocumentPage(
      workItemId,
      documentId,
      pageOrder.toString(),
      () => {
        successCallBack();
      },
      (err) => {
        failedCallBack(err);
      }
    );
  }

  moveDocumentPageToSameDocument(
    workItemId: string,
    documentId: string,
    oldPageNumber: number,
    newPageNumber: number,
    originalPageFile: File,
    fileType: string,
    successCallBack: () => void,
    failedCallBack: (err: any) => void
  ) {
    this.hydraApi.moveDocumentPageToSameDocument(
      workItemId,
      documentId,
      oldPageNumber.toString(),
      newPageNumber.toString(),
      originalPageFile,
      fileType,
      () => {
        successCallBack();
      },
      (err) => {
        failedCallBack(err);
      }
    );
  }

  addPageToFolder(page: Page, elementPosition: any, folder: WorkflowFolder) {
    return new Promise<void>((resolve, reject) => {
      if (!page.originalFile) {
        this.showPageLoadingError();
        reject();
        return;
      }

      const currentWorkItemId = this._currentWorkItem.id;
      const currentDocument = this._currentDocument;

      this._documentNameIndex++;
      const fileName = 'Document-' + this._documentNameIndex;
      this.addFiletoFolder(page.originalFile, fileName, 'pdf', folder);

      let currentPageCount = currentDocument.pageCount;

      this.deleteDocumentPage(
        currentWorkItemId,
        currentDocument.id,
        elementPosition.toString(),
        () => {
          currentPageCount -= 1;
          if (currentPageCount <= 0) {
            this.discardWorkItem(currentWorkItemId);
          } else {
            if (this._currentDocument && this._currentDocument.id === currentDocument.id) {
              this._currentDocument.removePage(page);
            }
          }

          resolve();
        },
        (err) => {
          this.toastrService.error(this.translate.instant('errors.failed-to-delete-page'));
          reject();
        }
      );
    });
  }

  addFiletoFolder(file: File | Blob, fileName: string, fileExtension: string, folder: WorkflowFolder) {
    const step = <InteractiveWorkflowStep>this.getWorkflowStepById(folder.workflowStepId);

    const doc = new CreateDocument(file, fileName, fileExtension);
    const workItem = WorkItem.create(this._currentWorkflow.id);

    const stepGroupingIds = step.itemGroupingIds;
    if (stepGroupingIds.length === 0) {
      this.createNewWorkItem(workItem, doc);
      return;
    }

    const metadataDefinitions: Array<IMetaDataDefinition> = [];
    for (let i = 0; i < stepGroupingIds.length; i++) {
      metadataDefinitions.push(this.userStateService.findMetaDataById(stepGroupingIds[i]));
    }

    const groupingArray = this.getGroupingFolderValues(folder);

    this.validateAndSetGroupOfMetadata(metadataDefinitions, groupingArray, 0, workItem, true, doc);
  }

  getGroupingFolderValues(groupingFolder: WorkflowFolder) {
    let folder = groupingFolder;
    const groupingFolderValues = [];

    while (folder.parentWorkflowFolder) {
      groupingFolderValues.unshift(folder.name);
      folder = folder.parentWorkflowFolder;
    }

    return groupingFolderValues;
  }

  handleSortingPages(dragData: DragData) {
    return new Promise<void>((resolve, reject) => {
      const page = { ...dragData.element } as Page;

      if (!page.originalFile) {
        this.showPageLoadingError();
        reject();
        return;
      }

      this.moveDocumentPageToSameDocument(
        this._currentWorkItem.id,
        this._currentDocument.id,
        dragData.elementPosition,
        dragData.targetPosition,
        page.originalFile,
        'pdf',
        () => {
          resolve();
        },
        () => {
          this.getDocumentPages();
          reject();
        }
      );
    });
  }

  sortPages(updateOrder?: boolean) {
    this.sortAnnotationIndex();

    if (updateOrder) {
      for (let i = 0; i < this._currentDocument.pages.length; i++) {
        this._currentDocument.pages[i].order = i + 1;
      }
    }

    this._currentDocument.sortPages();
  }

  handleDragDropPageIntoDocument(dragData: DragData, workItem: WorkItem, doc: Document) {
    return new Promise<void>((resolve, reject) => {
      const page = { ...dragData.element } as Page;
      const parentDocId = this._currentDocument.id;
      const parentWorkItem = { ...this._currentWorkItem } as WorkItem;
      const shouldDiscardWorkItem = this._currentDocument.pages.length < 2;

      if (!page.originalFile) {
        this.showPageLoadingError();
        reject();
        return;
      }

      this.hydraApi.moveDocumentPageToDifferentDocument(
        page.order,
        parentWorkItem.id,
        parentDocId,
        workItem.id,
        doc.id,
        (result: TransitionResult) => {
          if (!result.result) {
            this.toastrService.error(result.errorText);
            reject();
            return;
          }

          if (shouldDiscardWorkItem) {
            this.discardWorkItem(parentWorkItem.id);
          } else if (this._currentDocument && this._currentDocument.id === parentDocId) {
            this.viewerService.thumbnailScrolled(0);
          }

          if (this._currentDocument) {
            if (shouldDiscardWorkItem && this._currentDocument.id !== doc.id) {
              this.selectDocument(doc, workItem, this._currentDocument.parentFolderId, doc.pageCount);
            } else if (this._currentDocument.id === doc.id) {
              this._currentDocument.addPage(page);
              this._currentPage = page;
              this.sortPages(true);
            }
          }

          this.deleteAnnotationFromPage(page.order);

          resolve();
        },
        (err) => {
          this.toastrService.error(this.translate.instant('errors.failed-to-insert-page'));
          reject();
        }
      );
    });
  }

  handleDragDropWorkItemsIntoDocument(
    dragDataArray: DragData[],
    workItem: WorkItem,
    doc: Document,
    parentFolderId: string
  ) {
    return new Promise<void>((resolve, reject) => {
      const sourceWorkItemsIds = [];
      const sourceDocumentIds = [];
      let newPagesCount = 0;

      dragDataArray.forEach((dragDataItem: DragData) => {
        sourceWorkItemsIds.push(dragDataItem.element.id);
        sourceDocumentIds.push(dragDataItem.document.id);

        newPagesCount += dragDataItem.document.pageCount;
      });

      this.selectedItemsService.clearSelectedItems();

      this.hydraApi.moveWorkItemsIntoDocument(
        sourceWorkItemsIds,
        sourceDocumentIds,
        workItem.id,
        doc.id,
        (result: TransitionResult) => {
          if (!result.result) {
            this.toastrService.error(result.errorText);
            reject();
            return;
          }

          doc.pageCount += newPagesCount;

          sourceWorkItemsIds.forEach((id: any) => this.discardWorkItem(id));

          this.selectDocument(doc, workItem, this._currentDocument.parentFolderId);

          resolve();
        },
        (err: any) => {
          this.toastrService.error(this.translate.instant('errors.failed-to-move-documents'));
          reject();
        }
      );
    });
  }

  appendPagesToDocument(
    workItem: WorkItem,
    doc: Document,
    data: File | File[],
    fileType: string = 'pdf',
    selectFirst: boolean = false
  ) {
    this.cancelSelectDocumentOnAppendMorePages = true;
    this.appendPagesToDocumentProxy(workItem, doc, data, doc.pageCount + 1, fileType, selectFirst);
  }

  appendPagesToDocumentProxy(
    workItem: WorkItem,
    doc: Document,
    data: File | File[],
    startPageNumber: number,
    fileType: string = 'pdf',
    selectFirst: boolean = false
  ) {
    let file = data instanceof Array ? data[0] : data;

    this.inProgress.display('app-scan.uploading-documents');

    this.hydraApi.appendWorkItemDocumentPages(
      workItem.id,
      doc.id,
      file,
      fileType,
      (updatedDocument) => {
        this.onUpdatedDocumentSucceeded(
          updatedDocument,
          workItem,
          startPageNumber,
          doc,
          data,
          fileType,
          selectFirst,
          this.appendPagesToDocumentProxy
        );
      },
      this.onUpdateDocumentFailed
    );
  }

  addPagesToDocument(
    workItem: WorkItem,
    doc: Document,
    data: File | File[],
    startPageNumber: number,
    fileType: string = 'pdf',
    selectFirst: boolean = false,
    handlePagesOrder: boolean = true
  ) {
    let file = data instanceof Array ? data[0] : data;

    this.inProgress.display('app-scan.uploading-documents');

    this.hydraApi.insertWorkItemDocumentPages(
      workItem.id,
      doc.id,
      startPageNumber.toString(),
      file,
      fileType,
      (updatedDocument) => {
        if (!handlePagesOrder) {
          this.closeScanInProgress();
          return;
        }

        this.onUpdatedDocumentSucceeded(
          updatedDocument,
          workItem,
          startPageNumber,
          doc,
          data,
          fileType,
          selectFirst,
          this.addPagesToDocument
        );
      },
      this.onUpdateDocumentFailed
    );
  }

  onUpdateDocumentFailed = (err: any): void => {
    this.showFailedToAddPagesToDocumentError();
    this.closeScanInProgress();

    this.showError(err, 'Common.upload-failed', 'errors.failed-to-insert-page');
  };

  onUpdatedDocumentSucceeded = (
    updatedDocument: Document,
    workItem: WorkItem,
    startPageNumber: number,
    doc: Document,
    data: File | File[],
    fileType: string = 'pdf',
    selectFirst: boolean = false,
    callnext
  ): void => {
    const addedPagesCount = updatedDocument.pageCount - doc.pageCount;
    this._currentDocument.shiftPages(startPageNumber, addedPagesCount);

    for (let i = 0; i < addedPagesCount; i++) {
      const pageNumber = startPageNumber + i;
      this._currentDocument.addPage(
        new Page(
          pageNumber,
          doc.id,
          workItem.annotations.filter((x) => x.pageNumber == pageNumber)
        )
      );
    }

    if (!(data instanceof File) && data.length > 1) {
      startPageNumber += addedPagesCount;
      doc.pageCount = updatedDocument.pageCount;
      data.shift();

      callnext(workItem, doc, data, startPageNumber, fileType, selectFirst);
      return;
    }

    this.closeScanInProgress();
    this.toastrService.success(this.translate.instant('Document_Capture.upload-success'));

    if (this._currentDocument.id === doc.id) {
      this._currentDocument.updatePageCount();

      this.sortPages();

      if (selectFirst) {
        this.selectPage(startPageNumber);
      } else {
        this.selectPage(this.currentPage.order);
      }

      this.delay.execute(() => {
        this.viewerService.thumbnailScrolled(0);
      }, 50);
    } else {
      this.selectDocument(doc, workItem, this._currentDocument.parentFolderId, startPageNumber);
    }
  };

  reImportPageToDocument(file: File) {
    this.inProgress.display('app-scan.uploading-documents');

    const folder = this.findFolder(this._currentDocument.parentFolderId);
    const { workItem, document } = folder.findDocument(this._currentDocument.id);
    const pageNumber = this.currentPage.order;

    this.hydraApi.insertWorkItemDocumentPages(
      workItem.id,
      document.id,
      (pageNumber + 1).toString(),
      file,
      Filename.getFileExtension(file.name) || 'pdf',
      () => {
        this.hydraApi.deleteWorkItemDocumentPage(
          workItem.id,
          document.id,
          pageNumber.toString(),
          (updatedDocument) => {
            this.hydraApi.getWorkItem(
              this._currentWorkItem.id,
              (updatedWorkItem) => {
                folder.updateWorkItem(updatedWorkItem);
                this.selectDocument(updatedDocument, updatedWorkItem, folder.id, null, true);
                this.closeScanInProgress();
              },
              () => {
                this.toastr.error(this.translate.instant('Common.LoadingDataError'));
                this.selectDocument(updatedDocument, workItem, folder.id, null, true);
                this.closeScanInProgress();
              }
            );
          },
          () => {
            this.showFailedToDeletePageFromDocumentError();
            this.closeScanInProgress();
          }
        );
      },
      (err) => this.onUpdateDocumentFailed(err)
    );
  }

  validateAndSetGroupOfMetadata(
    metadataArray: Array<IMetaDataDefinition>,
    valuesArray: Array<any>,
    currentIndex: number,
    workItem: WorkItem,
    isNew: boolean,
    doc?: CreateDocument
  ) {
    if (metadataArray.length === 0) {
      throw new RangeError('metadataArray has a wrong range of elements.');
    }
    this.validateMetadataValue(metadataArray[0], valuesArray[currentIndex] ? valuesArray[currentIndex] : '').then(
      (metadata) => {
        workItem.setMetaData(
          metadataArray[0].name,
          valuesArray[currentIndex] ? valuesArray[currentIndex] : '',
          metadata.validity
        );
        metadataArray.splice(0, 1);
        currentIndex += 1;
        if (metadataArray.length) {
          this.validateAndSetGroupOfMetadata(metadataArray, valuesArray, currentIndex, workItem, isNew, doc);
        } else {
          if (isNew) {
            if (!doc) {
              throw new Error('New document to be adding is missing');
            }

            this.createNewWorkItem(workItem, doc);
          } else {
            this.updateWorkItemMetadata(workItem);
          }
        }
      }
    );
  }

  reInitIndexing() {
    if (this._currentFolder) {
      this.selectFolder(this._currentFolder);
    } else {
      const currentDocument = this.getCurrentDocument();
      if (currentDocument) {
        this.selectDocument(
          currentDocument.document,
          this._currentWorkItem,
          this._currentDocument.parentFolderId,
          null,
          true
        );
      }
    }
  }

  selectDocument(
    doc: Document,
    workItem: WorkItem,
    parentFolderId: string,
    selectedPagePosition?: number,
    force?: boolean,
    isCtrlKey = false
  ): void {
    const parentFolder = this.findFolder(parentFolderId);

    if (this.shouldCancelSelectDocument(doc, workItem, parentFolder, force, isCtrlKey)) {
      this.selectedItemsService.changedSelectedItems();
      return;
    }

    this.documentLastTouchedService.clearLastTouchedWorkItem();

    this._currentPage = null;
    this._currentFolder = null;
    this.captureUpdate.updateFolder(this._currentFolder);

    this._currentWorkItem = workItem;
    this._currentDocument = new CapturedDocument(doc, workItem, parentFolderId);

    this.selectedItemsService.selectTreeDocument(this._currentDocument, parentFolder, doc.pageCount, isCtrlKey);

    this.initIndexing(workItem.workflowStepId);
    this.captureUpdate.updateDocument(this._currentDocument);

    this.resetCurrentIfOneItemRemained();

    if (
      this.selectedItemsService.isOneItemSelected() &&
      this.selectedItemsService.isItemSelected(
        this._currentDocument.workitem.id,
        this._currentDocument.workitem.workflowStepId
      )
    ) {
      this.getDocumentPages(selectedPagePosition);
    }
  }

  shouldCancelSelectDocument(
    doc: Document,
    workItem: WorkItem,
    parentFolder: WorkflowFolder,
    force: boolean,
    isCtrlKey: boolean
  ): boolean {
    if (
      this._currentDocument &&
      this._currentDocument.id === doc.id &&
      this.selectedItemsService.isOneItemSelected() &&
      this.selectedItemsService.isItemSelected(workItem.id, workItem.workflowStepId) &&
      !force &&
      !isCtrlKey
    ) {
      return true;
    }

    if (isCtrlKey && this.selectedItemsService.isAnyAncestorSelectedForDocument(parentFolder)) return true;

    if (isCtrlKey && this.selectedItemsService.isInDifferentWorkflowStep(workItem.workflowStepId)) return true;

    if (this.cancelSelectDocumentOnAppendMorePages) {
      this.cancelSelectDocumentOnAppendMorePages = false;
      return true;
    }

    return false;
  }

  resetCurrentIfOneItemRemained() {
    if (!this.selectedItemsService.isOneItemSelected()) return;

    const selectedItem = this.selectedItemsService.getSelectedItems()[0];

    if (selectedItem.type === SelectedItemType.Document) {
      this._currentFolder = null;
      this.captureUpdate.updateFolder(this._currentFolder);

      if (!this._currentDocument || this._currentDocument.workitem.id !== selectedItem.id) {
        this._currentDocument = selectedItem.item;
        this._currentWorkItem = selectedItem.item.workitem;
        this.captureUpdate.updateDocument(this._currentDocument);
      }

      return;
    }

    if (selectedItem.type === SelectedItemType.Folder) {
      this._currentWorkItem = null;
      this._currentDocument = null;
      this.captureUpdate.updateDocument(this._currentDocument);

      if (!this._currentFolder || this._currentFolder.id !== selectedItem.id) {
        this._currentFolder = selectedItem.item;
        this.captureUpdate.updateFolder(this._currentFolder);
      }
    }
  }

  getCurrentWorkItem = (): WorkItem => this._currentWorkItem;
  setCurrentWorkItem = (workItem: WorkItem) => (this._currentWorkItem = workItem);

  getCurrentDocument(): CapturedDocument {
    return this._currentDocument;
  }

  getDocumentPages(selectedPageOrder?: number) {
    for (let i = 1; i <= this._currentDocument.pageCount; i++) {
      const newPage = new Page(
        i,
        this._currentDocument.id,
        this._currentWorkItem.annotations.filter((x) => x.pageNumber == i)
      );

      this._currentDocument.addPage(newPage);

      if (selectedPageOrder) {
        this._currentPage = this._currentDocument.getPageByOrder(selectedPageOrder);
      } else {
        this._currentPage = this._currentDocument.getPageByOrder(1);
      }
    }

    if (this._currentPage) {
      this.captureUpdate.updateDocumentPage(this._currentPage);
    }
  }

  loadDocumentPage = (page: Page, callBack: () => void): void => {
    page.state = PageState.Loading;

    this.hydraApi.getWorkItemDocumentPageStream(
      this._currentWorkItem.id,
      this._currentDocument.id,
      'ocr.pdf|pdf',
      page.order.toString(),
      async (pageStream: File) => {
        if (!this._currentDocument || page.parentDocumentId !== this._currentDocument?.id) {
          page.state = PageState.Empty;
          return;
        }

        page.originalFile = pageStream;
        const base64File = await Files.toBase64String(pageStream);
        page.viewerURL = base64File;
        page.state = PageState.Loaded;
        callBack();
      },
      () => {
        page.state = PageState.FailedLoad;
        this.toastrService.error(this.translate.instant('errors.failed-to-get-page'));
      },
      false
    );
  };

  cancelLoadDocumentPage = (page: Page): void => {
    const key = `workitem-load-page-by-format-${this._currentDocument.id}`;
    this.hydraApi.dequeue(key, [
      this.hydraApi.getWorkItemDocumentPageStream.name,
      this._currentWorkItem.id,
      this._currentDocument.id,
      'ocr.pdf|pdf',
      page.order.toString(),
    ]);
  };

  showPageLoadingError() {
    this.toastrService.error(this.translate.instant('Document_Capture.Page_Not_yet_Loaded'));
  }

  unselectDocument(documentId: string) {
    if (this._currentDocument && this._currentDocument.id === documentId) {
      this._currentDocument = null;
      this._currentPage = null;
      this.captureUpdate.updateDocument(this._currentDocument);
      this.captureUpdate.updateLineItemTableBody(new MetaDataLineItems());

      this.indexing.toggleLineItemPanel(false);
    }
  }

  transitionSelectedItems(outcomeId: string) {
    if (this.hydraApi.isAvailable()) {
      this.selectedItemsService.getSelectedItems().forEach((item) => {
        if (item.type === SelectedItemType.Document) {
          this.outcomesService.transitionWorkItem(outcomeId, item.id, this.transitionCompleted);
        } else if (item.type === SelectedItemType.Folder) {
          this.outcomesService.transitionFolder(outcomeId, item.id, this.transitionCompleted);
        }
      });
      return;
    }
    setTimeout(() => this.transitionSelectedItems(outcomeId), 100);
  }

  transitionCompleted = (): void => {
    this.selectedItemsService.clearSelectedItems();
    this._currentWorkItem = null;
    this._currentDocument = null;
    this.captureUpdate.updateDocument(this._currentDocument);
    this._currentPage = null;
    this.captureUpdate.updateDocumentPage(this._currentPage);
    this._currentFolder = this.getWorkflowFirstFolder();
    this.captureUpdate.updateFolder(this._currentFolder);
    this.selectedItemsService.selectTreeFolder(this._currentFolder, false);
    this.indexing.toggleLineItemPanel(false);
  };

  validateAndSaveIndexingValue(value: string, metadata: MetaDataDefinition, workItem: WorkItem, force = false) {
    if (this.getCurrentWorkItem().id != workItem.id) return;
    const currentMetadata = this.getCurrentWorkItem().getMetaData(metadata.name);
    if (!force && value === currentMetadata?.value && !metadata.hasValidation) return;

    this.setMetaDataChangeInProgress(true);

    workItem.setMetaData(
      metadata.name,
      value,
      MetaDataValidity.unknown,
      currentMetadata && currentMetadata.value === value ? new Location(currentMetadata.location) : null
    );

    this._startMetaDataValidationSubject.next(metadata.id);
    this._savingIndexingValueInProgress = true;
    this.validateAndUpdateMetadataValue(workItem, metadata, value)
      .then((updatedWorkItem) => {
        this._completeMetaDataValidationSubject.next(metadata.id);
        this._savingIndexingValueInProgress = false;
        this.setMetaDataChangeInProgress(false);
        if (this.getCurrentWorkItem().id != updatedWorkItem.id) return;

        workItem.metadata = updatedWorkItem.metadata;
        this.captureUpdate.updateWorkitemMetadata(workItem, this.getCurrentWorkItem());

        this.captureUpdate.changeValueValidity({ id: metadata.id, validity: this.getFieldValidity(metadata) });

        workItem = updatedWorkItem;
      })
      .catch((err) => {
        this._completeMetaDataValidationSubject.next(metadata.id);
        this._savingIndexingValueInProgress = false;
        this.setMetaDataChangeInProgress(false);
      });
  }

  validateLineItemValue(metadata: IMetaDataDefinition, value: string, fromLineItem: boolean = false) {
    return new Promise((resolve, reject) => {
      this.validateMetadataValue(metadata, value, fromLineItem)
        .then((metadata: IMetaData) => {
          resolve(metadata);
        })
        .catch((err) => reject(err));
    });
  }

  validateMetadataValue(metadata: IMetaDataDefinition, value: string, fromLineItem: boolean = false) {
    const metaDataCollection = new MetaDataCollection();

    metaDataCollection.set(metadata.name, value, MetaDataValidity.unknown);

    return new Promise<IMetaData>((resolve, reject) => {
      this.hydraApi.validateAndUpdateMetaData(
        new ValidationRequest(metadata, metaDataCollection, this._currentWorkItem?.id, [], false, fromLineItem),
        (mdc: MetaDataCollection) => {
          resolve(mdc.get(metadata.name));
        },
        (err) => {
          reject(err);
        }
      );
    });
  }

  updateWorkItemMetadata(workItem: WorkItem) {
    if (this._currentWorkItem && this._currentWorkItem.id === workItem.id) {
      this.documentLastTouchedService.setLastTouchedWorkItem(workItem.id);
    }

    return new Promise<WorkItem>((resolve, reject) => {
      this.hydraApi.updateWorkItemMetaData(
        workItem.id,
        workItem.metadata,
        (updatedWorkItem) => {
          resolve(updatedWorkItem);
        },
        (err) => {
          reject(err);
        }
      );
    });
  }

  updateMetadataValues(workItem: WorkItem, values: Array<LookupToBeSaved>) {
    const validationPromise: Promise<void | MetaDataValidity>[] = [];

    values.forEach((value) => {
      if (!value.overwrite) {
        if (this.getWorkItemIndexingValue(value.metadata.name)) {
          return;
        }
      }

      const currentMetadata = this.getCurrentWorkItem().getMetaData(value.metadata.name);

      workItem.setMetaData(
        value.metadata.name,
        value.value,
        MetaDataValidity.unknown,
        currentMetadata ? new Location(currentMetadata.location) : null
      );

      validationPromise.push(
        this.validateMetadataValue(value.metadata, value.value).then((metadata) => {
          workItem.setMetaData(
            value.metadata.name,
            value.value,
            metadata.validity,
            currentMetadata ? new Location(currentMetadata.location) : null
          );
        })
      );
    });

    Promise.all(validationPromise).then((res) => {
      this.updateWorkItemMetadata(workItem).then((updateDocument) => (workItem.metadata = updateDocument.metadata));
    });
  }

  validateAndUpdateMetadataValue(workItem: WorkItem, metadata: IMetaDataDefinition, value: string) {
    if (this._currentWorkItem && this._currentWorkItem.id === workItem.id) {
      this.documentLastTouchedService.setLastTouchedWorkItem(workItem.id);
    }

    return new Promise<WorkItem>((resolve, reject) => {
      this.hydraApi.validateAndUpdateWorkItemMetaData(
        new ValidationRequest(metadata, workItem.metadata, workItem.id),
        (updatedWorkItem) => {
          resolve(updatedWorkItem);
        },
        (err) => {
          this.toastrService.error(this.translate.instant('Document_Capture.metadata-validation-failed'));
          reject(err);
        }
      );
    });
  }

  getFieldValidity(mdd: MetaDataDefinition) {
    if (this._currentWorkItem == null) {
      return null;
    }

    const metaData = this._currentWorkItem.getMetaData(mdd.name);
    if (metaData) {
      return metaData.validity;
    }

    return null;
  }

  getValueLocation(mdd: MetaDataDefinition | IMetaDataDefinition) {
    if (!mdd) {
      return null;
    }

    const metaData = this._currentWorkItem?.getMetaData(mdd.name);
    if (metaData) {
      return metaData.location;
    }

    return null;
  }

  setValueLocation(mdd: MetaDataDefinition | IMetaDataDefinition, value: string, location: Location) {
    if (!mdd) {
      return null;
    }

    const metaData = this._currentWorkItem.getMetaData(mdd.name);
    if (metaData) {
      metaData.location = location;
      this._currentWorkItem.setMetaData(mdd.name, value, MetaDataValidity.valid, location);
    }
  }

  getWorkItemIndexingValue(metadataDefinitionName: string): string {
    if (this._currentWorkItem) {
      const metaData = this._currentWorkItem.getMetaData(metadataDefinitionName);
      if (!metaData || metaData.valueType !== MetaDataValueType.String) {
        return '';
      }

      return <string>metaData.value;
    }
  }

  editDocumentName(docId: string, fileType: string, name: string, workItemId: string): Promise<Document> {
    return new Promise((resolve, reject) => {
      const newName = `${name}.${fileType}`;
      const updateDocument = new UpdateDocument(newName, fileType);
      this.hydraApi.updateWorkItemDocument(
        workItemId,
        docId,
        updateDocument,
        (result: ApiResult) => {
          if (result.success) {
            resolve(
              new Document(
                result.object.id,
                result.object.tenantId,
                result.object.ownerId,
                result.object.filename,
                result.object.fileType,
                result.object.size,
                result.object.pageCount
              )
            );
          } else {
            this.errorsService.showErrorsModal(
              result.errors,
              this.translate.instant('Scanning.ApplyDocumentFailed') +
                ' ' +
                this.translate.instant('document-actions.rename')
            );
            reject(result);
          }
        },
        (err) => {
          console.log(err);
          this.errorsService.showErrorsModal(
            [err],
            this.translate.instant('Scanning.ApplyDocumentFailed') +
              ' ' +
              this.translate.instant('document-actions.rename')
          );
          reject(err);
        }
      );
    });
  }

  replaceDocument(workItemId: string, documentId: string, file: File, fileType: string) {
    this.inProgress.display('app-scan.uploading-documents');

    this.hydraApi.updateWorkItemDocumentStream(
      workItemId,
      documentId,
      file,
      fileType,
      (pageCount: number) => {
        this.closeScanInProgress();
        this.toastrService.success(this.translate.instant('Document_Capture.upload-success'));
        if (this._currentDocument && this._currentDocument.id === documentId) {
          const parentFolder = this.folders.find((folder) => folder.id === this._currentDocument.parentFolderId);
          const { workItem, document } = parentFolder.findDocument(documentId);

          document.pageCount = pageCount;
          this.hydraApi.getWorkItem(
            this._currentWorkItem.id,
            (_workItem) => {
              parentFolder.updateWorkItem(_workItem);
              this.selectDocument(document, _workItem, this._currentDocument.parentFolderId, null, true);
            },
            (err) => {
              this.toastr.error(this.translate.instant('Common.LoadingDataError'));
              this.selectDocument(document, workItem, this._currentDocument.parentFolderId, null, true);
            }
          );
        }
      },
      (err) => {
        this.showError(err, 'Common.upload-failed', 'Common.upload-failed');
        this.closeScanInProgress();
      }
    );
  }

  deleteDocument(doc: CapturedDocument) {
    const documentIndex = this._currentBatch.getDocumentIndex(doc);
    const batchIndex = this.captureObject.getBatchIndex(this._currentBatch);
    this._currentBatch.removeDocument(doc);
    if (!this._currentBatch.children.length) {
      this._captureObject.removeBatch(this._currentBatch);
      if (!this._captureObject.children.length) {
        this.reset();
      } else {
        this._currentBatch = this._captureObject.getBatchByIndex(batchIndex === 0 ? 0 : batchIndex - 1);
        this._currentDocument = this._currentBatch.getCurrentDocument();
        this._currentPage = this._currentDocument.getCurrentPage();
      }
    } else {
      this._currentDocument = this._currentBatch.getDocumentByIndex(documentIndex === 0 ? 0 : documentIndex - 1);
      this._currentPage = this._currentDocument.getPageByIndex(0);
    }
  }

  selectSpecificPage(page: Page): void {
    this._currentPage = page;
    this.captureUpdate.updateDocumentPage(page);
  }

  selectPage(order: number): void {
    this._currentPage = this._currentDocument.getCurrentPage(order);
  }

  deletePage(page: Page, deleteSuccess: Function): void {
    this.spinnerService.show(
      this.translate.instant('App.executing-action'),
      document.getElementById('app-spinner-panel')
    );
    const pageOrder = this._currentDocument.pages.find((p) => p.id === page.id).order;
    const currentWorkItemId = this._currentWorkItem.id;
    let currentPageCount = this._currentDocument.pages.length;

    this.deleteDocumentPage(
      currentWorkItemId,
      this._currentDocument.id,
      pageOrder,
      () => {
        deleteSuccess();
        this.documentPageDeleted(page, currentPageCount, currentWorkItemId);
      },
      (err) => {
        this.spinnerService.hide();
        this.toastrService.error(this.translate.instant('errors.failed-to-delete-page'));
      }
    );
  }

  documentPageDeleted(page: Page, currentPageCount: number, currentWorkItemId: string) {
    this.spinnerService.hide();

    if (currentPageCount <= 1) {
      this.discardWorkItem(currentWorkItemId, () => {
        this.resetSelectedFolder(this.folders?.[0]);
      });

      return;
    }

    let selectNextPage = false;
    if (currentWorkItemId === this._currentWorkItem.id) {
      this.viewerService.thumbnailScrolled(0);
      if (this._currentPage.order === page.order) selectNextPage = true;
    } else {
      if (this._currentDocument && this._currentPage && this._currentPage.order === page.order) {
        selectNextPage = true;
      }
    }

    if (selectNextPage) {
      this._currentPage = this._currentDocument.getPageByOrder(
        page.order <= this._currentDocument.pageCount ? page.order : page.order - 1
      );
    }

    this.deleteAnnotationFromPage(page.order);
  }

  deleteAnnotationFromPage(pageNumber: number) {
    this._currentDocument.workitem.annotations = this._currentDocument.workitem.annotations.filter(
      (a) => a.pageNumber != pageNumber
    );

    this._currentDocument.workitem.annotations
      .filter((x) => x.pageNumber > pageNumber)
      .forEach((x) => (x.pageNumber -= 1));

    this.sortAnnotationIndex();
  }

  rotateCurrentPage(rotation: number) {
    return new Promise<WorkItem>((resolve, reject) => {
      this.hydraApi.rotateWorkItemDocumentPage(
        this._currentWorkItem.id,
        this._currentDocument.id,
        this._currentPage.order,
        rotation,
        (workItem: WorkItem) => {
          this.captureUpdate.reloadCurrentPage();
          resolve(workItem);
        },
        (err) => {
          reject();
        }
      );
    });
  }

  setDestination(workflow: Workflow) {
    this._currentWorkflow = workflow;
    this._currentWorkItem = null;
    this._currentDocument = null;
    this._currentPage = null;
    this.captureUpdate.updateWorkflow(workflow);
    this.captureUpdate.updateLineItemTableHead(new LineItemHeader('', '', '', []));
    this.captureUpdate.updateLineItemTableBody(new MetaDataLineItems());
  }

  reset() {
    this.clean();
    this.init();
  }

  updateDocumentName(newName: string) {
    this._currentDocument.name = newName;
  }

  currentStepHasIndexing(): boolean {
    const currentStepId = this.getCurrentStepId();
    if (!currentStepId) return false;

    const currentStep = this.getWorkflowStepById(currentStepId) as InteractiveWorkflowStep;
    if (!currentStep || !currentStep.metaDataIds.length) return false;

    return true;
  }

  canAutomaticallyAdvanceOnTab(): boolean {
    const currentStepId = this.getCurrentStepId();
    if (!currentStepId) return;

    return (this.getWorkflowStepById(currentStepId) as InteractiveWorkflowStep).automaticallyAdvanceDocumentOnTab;
  }

  getCurrentStepId(): string {
    if (this.selectedItemsService.hasItemsSelected()) {
      return this.selectedItemsService.getSelectedItems()[0].workflowStepId;
    }

    return null;
  }

  addToFolders(folder: WorkflowFolder): void {
    this.folders.push(folder);
  }

  findFolder(id: string): WorkflowFolder {
    return this.folders.find((folder) => folder.id === id);
  }

  removeFolder(id: string): void {
    const folderIndex = this.folders.findIndex((folder) => folder.id === id);
    if (folderIndex < 0) {
      return;
    }

    this.folders.splice(folderIndex, 1);
  }

  loadWorkFlows(): Promise<Array<Workflow>> {
    return new Promise((resolve, reject) => {
      this.hydraApi.getUserWorkflows(
        (workflows: Array<Workflow>) => resolve(workflows),
        (err: any) => reject(err)
      );
    });
  }

  getMetaDataCollection = (): MetaDataCollection => {
    if (this._currentWorkItem) {
      return this._currentWorkItem.metadata;
    }

    return null;
  };

  addAnnotation = (annotation: Annotation, successCallBack: () => void, failedCallBack: (err: any) => void): void => {
    this.hydraApi.addAnnotation(
      this._currentWorkItem.id,
      annotation,
      () => {
        this.addAnnotationsToCurrentDocument(annotation);
        successCallBack();
      },
      failedCallBack
    );
  };

  updateAnnotation = (
    annotation: Annotation,
    successCallBack: () => void,
    failedCallBack: (err: any) => void
  ): void => {
    this.hydraApi.updateAnnotation(this._currentWorkItem.id, annotation, successCallBack, failedCallBack);
  };

  removeAnnotation = (annotationId: string, successCallBack: () => void, failedCallBack: (err: any) => void): void => {
    this.hydraApi.removeAnnotation(this._currentWorkItem.id, annotationId, successCallBack, failedCallBack);
  };

  addAnnotationsToCurrentDocument(annotation: Annotation) {
    if (!this._currentDocument.workitem.annotations) this._currentDocument.workitem.annotations = [];
    if (this._currentDocument.workitem.annotations.find((a) => a == annotation)) return;

    this._currentDocument.workitem.annotations.push(annotation);
  }

  sortAnnotationIndex = () => {
    const annotations = this._currentDocument.workitem.annotations;

    if (annotations.length > 0) {
      annotations.forEach((annotation) => {
        annotation.pageNumber = this._currentDocument.pages.findIndex((p) => p.order == annotation.pageNumber) + 1;
      });
    }

    this.captureUpdate.changeAnnotation(annotations);
  };

  updatePageAnnotations(pageOrder: number, documentWorkItemAnnotations: Annotation[]) {
    this._currentDocument.updatePageAnnotations(pageOrder, documentWorkItemAnnotations);
    this.captureUpdate.updateDocument(this._currentDocument);
    this._currentPage = this._currentDocument.pages.find((p) => p.order === pageOrder);
    this.captureUpdate.updateDocumentPage(this._currentPage);
    this._currentWorkItem.annotations = this._currentDocument.workitem.annotations;
  }

  clean() {
    if (this.hydraPendingInterval) {
      clearInterval(this.hydraPendingInterval);
    }

    if (this.subscription) {
      this.subscription.unsubscribe();
    }
  }

  ngOnDestroy() {
    this.clean();
  }
}
