import {
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

import { Subscription } from 'rxjs';
import { Dictionary } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/models';
import { FieldDefinition } from '../../models/field-definition';
import { MetaDataValidity } from '../../models/metadata';
import { CharactersValidator } from '../../utils/characters-validator.service';
import { DateTime } from '../../utils/date-time.service';
import { DelayService } from '../../utils/delay.service';
import { Languages } from '../../utils/languages';
import { ObjectIdGenerator } from '../../utils/objectid-generator';
import { Strings } from '../../utils/strings.service';
import { DateRangePickerComponent } from './date-range-picker/date-range-picker.component';
import { IDateRangePickerData } from './date-range-picker/date-range-picker.model';
import { DateRangePickerService } from './date-range-picker/date-range-picker.service';

@Component({
  selector: 'app-date-range',
  templateUrl: './date-range.component.html',
  styleUrls: ['./date-range.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class DateRangeComponent implements OnInit, OnDestroy, OnChanges {
  @ViewChild('dateTextField', { static: true })
  dateTextField: ElementRef;
  @ViewChild('dateRangePickerWrapper', { static: true }) dateRangePickerWrapper: ElementRef;

  isCurrentField: boolean;
  metaDataValidity = MetaDataValidity;

  @Input() field: FieldDefinition;
  @Input() value: string;
  @Input() disabled: boolean;
  @Input() validity: number;
  @Input() minValue: string;
  @Input() maxValue: string;
  @Input() options: Array<Dictionary>;
  @Input() defaultValue: string;
  @Input() fieldTabIndex = 0;

  @Input()
  set focused(isFocused: boolean) {
    if (isFocused) {
      this.dateTextField.nativeElement.focus();
      this.isCurrentField = true;
    } else if (!isFocused) {
      this.dateTextField.nativeElement.blur();
      this.isCurrentField = false;
    }
  }

  @Input()
  set setValue(value: string) {
    this.value = value;
  }

  @Output() fieldFocus = new EventEmitter();
  @Output() fieldBlur = new EventEmitter<string>();
  @Output() fieldOnTab = new EventEmitter<string>();
  @Output() fieldOnShiftTab = new EventEmitter<string>();

  id: string;
  dialogIsOpened: boolean;
  subscriptions = new Subscription();

  constructor(
    private delay: DelayService,
    private dateRangePickerService: DateRangePickerService,
    private validator: CharactersValidator,
    private translateService: TranslateService
  ) {
    this.id = ObjectIdGenerator.generateNewObjectId();
  }

  ngOnInit(): void {
    this.subscriptions.add(
      this.dateRangePickerService.onDateRangeSelected.subscribe((data: IDateRangePickerData) => {
        if (data.idPrefix == this.id) this.onDateRangeChanged(data.value);
      })
    );

    this.subscriptions.add(
      this.dateRangePickerService.onDateRangeSelectionCanceled.subscribe((data: IDateRangePickerData) => {
        this.delay.execute(() => {
          this.dialogIsOpened = false;
        }, 200);
      })
    );
  }

  ngOnDestroy() {
    this.dateRangePickerService.hide();
    this.subscriptions.unsubscribe();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.value && changes.value.currentValue != this.value) this.value = changes.value.currentValue;
  }

  showDateRangePicker = (): void => {
    if (this.dialogIsOpened) return;

    this.delay.execute(() => {
      this.dateRangePickerService.show({
        component: DateRangePickerComponent,
        data: {
          value: this.value,
          disabled: this.disabled,
          parent: this.dateRangePickerWrapper.nativeElement,
          idPrefix: this.id,
          minValue: this.minValue,
          maxValue: this.maxValue,
          options: this.options,
          defaultValue: this.defaultValue,
        },
      });
    }, 0);
    this.dialogIsOpened = true;
  };

  getValue = (): string => {
    if (this.dialogIsOpened && Strings.isEmpty(this.value))
      return this.translateService.instant('fields.select-date-range');
    if (Strings.isEmpty(this.value)) return this.translateService.instant('fields.all-dates');

    const parts = this.value.split(':');
    if (parts.length != 2) return;

    var startDate = new Date(new Date(`${parts[0]}T00:00:00`));
    var endDate = new Date(new Date(`${parts[1]}T00:00:00`));

    if (DateTime.isToday(startDate) && DateTime.isToday(endDate)) return this.translateService.instant('fields.today');

    return `${startDate.toLocaleDateString(Languages.getLanguage())} ${this.translateService.instant(
      'Common.To'
    )} ${endDate.toLocaleDateString(Languages.getLanguage())}`;
  };

  onKeydown(event: any) {
    this.validator.allowDateRangeOnly(event);
  }

  onDateRangeChanged = (value): void => {
    this.fieldBlur.emit(value);
  };

  closeOnScroll() {
    this.dateRangePickerService.hide();
  }
}
