export enum DateValueType {
  RelativeDate = -1,
  SpecificDate = 0,
  DaysBefore = 1,
  DaysAfter = 2,
}
export class DateValue {
  data: string;
  type: DateValueType;
  constructor(initializer?) {
    if (initializer.data == null) throw new Error('Invalid Initializer');
    if (initializer.type == null) throw new Error('Invalid Initializer');

    this.data = initializer.data;
    this.type = initializer.type;
  }

  public serializable(): any {
    return {
      data: this.data,
      type: this.type,
    };
  }
}

export class MetaDataDateValidator extends MetaDataValidation {
  public beginDate: DateValue;
  public endDate: DateValue;

  constructor(initializer?) {
    if (initializer == null)
      initializer = {
        type: 'MetaDataDateValidator',
        validationMessage: '',
        beginDate: new DateValue({
          data: moment(new Date()).format('YYYY-MM-DD'),
          type: 0,
        }),
        endDate: new DateValue({
          data: moment(new Date()).add(90, 'days').format('YYYY-MM-DD'),
          type: 0,
        }),
      };

    super(initializer);

    if (initializer.beginDate == null) throw new Error('Invalid Initializer');
    if (initializer.endDate == null) throw new Error('Invalid Initializer');

    this.beginDate = new DateValue(initializer.beginDate);
    this.endDate = new DateValue(initializer.endDate);
  }

  public changeType(type: DateValueType): void {
    if (type == DateValueType.SpecificDate) {
      this.beginDate.type = this.endDate.type = DateValueType.SpecificDate;
      this.beginDate.data = moment(new Date()).format('YYYY-MM-DD');
      this.endDate.data = moment(new Date()).add(90, 'days').format('YYYY-MM-DD');
      return;
    }

    this.beginDate.type = this.endDate.type = DateValueType.DaysBefore;
    this.endDate.type = this.endDate.type = DateValueType.DaysAfter;
    this.beginDate.data = this.endDate.data = '30';
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      beginDate: this.beginDate.serializable(),
      endDate: this.endDate.serializable(),
    };
  }
}

export class MetaDataLengthValidator extends MetaDataValidation {
  public minLength: number;
  public maxLength: number;

  constructor(initializer?) {
    if (initializer == null)
      initializer = {
        type: 'MetaDataLengthValidator',
        validationMessage: '',
        minLength: 1,
        maxLength: 10,
      };

    super(initializer);

    if (initializer.minLength == null) throw new Error('Invalid Initializer');
    if (initializer.maxLength == null) throw new Error('Invalid Initializer');

    this.minLength = initializer.minLength;
    this.maxLength = initializer.maxLength;
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      minLength: this.minLength,
      maxLength: this.maxLength,
    };
  }

  validate(): string[] {
    const errors = [];

    if (!this.minLength.toString().length || Number(this.minLength) < 0) {
      errors.push('Metadata-Form.min-length-required');
    } else if (!this.maxLength.toString().length || Number(this.maxLength) < Number(this.minLength)) {
      errors.push('Metadata-Form.max-length-required');
    }

    return errors;
  }
}

