export class MetaDataLookup {
  public type: string;
  public lookupFieldId: string = null;
  public displayAsList: boolean = false;
  public mappings: Array<MetaDataLookupMapping>;

  constructor(initializer) {
    if (initializer.type == null) throw Error('Invalid MetaDataLookup Initializer');
    if (initializer.mappings == null) throw new Error('Invalid MetaDataLookup Initializer');

    this.type = initializer.type;

    this.lookupFieldId = initializer.lookupFieldId;
    this.displayAsList = initializer.displayAsList;
    this.mappings = initializer.mappings.map((m: any) => new MetaDataLookupMapping(m));
  }

  public serializable(): any {
    return {
      type: this.type,
      lookupFieldId: this.lookupFieldId,
      displayAsList: this.displayAsList,
      mappings: this.mappings.map((m) => m.serializable()),
    };
  }

  public static create = (initializer): MetaDataLookup => {
    if (initializer == null) return null;

    if (initializer.type == null) throw new Error('Invalid initializer');

    if (initializer.type === 'Upland.Hydra.FileBound.FileBoundLookup') return new FileBoundLookup(initializer);
    if (initializer.type === 'Upland.Hydra.Core.MetaDataNoopLookup') return new MetaDataNoopLookup(initializer);
    if (initializer.type === 'Upland.Hydra.Core.CSVLookup') return new CSVLookup(initializer);
    if (initializer.type === 'Upland.Hydra.Database.DataSourcesLookup') return new DataSourceLookup(initializer);

    throw new Error(`Unknown MetaDataLookup type ${initializer.type}`);
  };

  public lookupType(): LookupType {
    return LookupType.FileBound;
  }
}

