export class MetaDataDefinition {
  public id: string;
  public tenantId: string;
  public name: string;
  public label: string;
  public type: MetaDataType;
  public hasValidation: boolean;
  public dataSource: MetaDataDataSource;
  public validation: MetaDataValidation;
  public defaultValue: string;
  public allowNoSelection: boolean;
  public lineItemConfigurations: Array<LineItemConfiguration>;
  public workflowsAssigned: boolean;
  public assignedWorkflowIds: Array<string>;
  public stickyField: string;
  public dateCreatedUTC: Date;
  public dateModifiedUTC: Date;
  public lookup: MetaDataLookup;
  public groupingFormat: string;
  public expression: string;
  public formatters: Array<Formatter>;
  public autosizeMinRows;
  public scrollHeight;

  constructor(initializer) {
    if (initializer.id == null) throw new Error('Invalid initializer');
    if (initializer.tenantId == null) throw new Error('Invalid initializer');
    if (initializer.name == null) throw new Error('Invalid initializer');
    if (initializer.label == null) throw new Error('Invalid initializer');
    if (initializer.type == null) throw new Error('Invalid initializer');
    if (initializer.hasValidation == null) throw new Error('Invalid initializer');
    if (initializer.dataSource == null) throw new Error('Invalid initializer');
    if (initializer.validation == null) throw new Error('Invalid initializer');
    if (initializer.defaultValue == null) throw new Error('Invalid initializer');
    if (initializer.allowNoSelection == null) throw new Error('Invalid initializer.allowNoSelection');
    if (initializer.workflowsAssigned == null) throw new Error('Invalid initializer');
    if (initializer.assignedWorkflowIds == null) throw new Error('Invalid initializer');
    if (initializer.lineItemConfigurations == null) throw new Error('Invalid initializer');
    if (initializer.stickyField == null) throw new Error('Invalid initializer');
    if (initializer.dateCreatedUTC == null) throw new Error('Invalid initializer');
    if (initializer.dateModifiedUTC == null) throw new Error('Invalid initializer');
    if (initializer.groupingFormat == null) throw new Error('Invalid initializer');
    if (initializer.expression == null) throw new Error('Invalid initializer');
    if (initializer.formatters == null) throw new Error('Invalid initializer.formatters');

    this.id = initializer.id;
    this.tenantId = initializer.tenantId;
    this.name = initializer.name;
    this.label = initializer.label;
    this.defaultValue = initializer.defaultValue;
    this.allowNoSelection = initializer.allowNoSelection;
    this.type = initializer.type;
    this.hasValidation = initializer.hasValidation;
    this.lineItemConfigurations = initializer.lineItemConfigurations.map((lic) => new LineItemConfiguration(lic));
    this.workflowsAssigned = initializer.workflowsAssigned;
    this.assignedWorkflowIds = initializer.assignedWorkflowIds;
    this.stickyField = initializer.stickyField;
    this.dataSource = MetaDataDataSource.create(initializer.dataSource);
    this.validation = MetaDataValidation.create(initializer.validation);
    this.dateCreatedUTC = initializer.dateCreatedUTC;
    this.dateModifiedUTC = initializer.dateModifiedUTC;
    this.lookup = MetaDataLookup.create(initializer.lookup);
    this.groupingFormat = initializer.groupingFormat;
    this.expression = initializer.expression;
    this.formatters = initializer.formatters.map((f) => new Formatter(f));
    this.autosizeMinRows = initializer.autosizeMinRows;
    this.scrollHeight = initializer.scrollHeight;
  }

  public allowedForWorkflow(workflowid: string): boolean {
    return !this.workflowsAssigned || this.assignedWorkflowIds.includes(workflowid);
  }

  public serializable(): any {
    return {
      id: this.id,
      tenantId: this.tenantId,
      name: this.name,
      label: this.label,
      defaultValue: this.defaultValue,
      allowNoSelection: this.allowNoSelection,
      type: this.type,
      hasValidation: this.hasValidation,
      dataSource: this.dataSource.serializable(),
      validation: this.validation.serializable(),
      lineItemConfigurations: this.lineItemConfigurations.map((lic) => lic.serializable()),
      workflowsAssigned: this.workflowsAssigned,
      assignedWorkflowIds: this.assignedWorkflowIds,
      stickyField: this.stickyField,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      lookup: this.lookup ? this.lookup.serializable() : { type: 'Upland.Hydra.Core.MetaDataNoopLookup' },
      groupingFormat: this.groupingFormat,
      expression: this.expression,
      formatters: this.formatters.map((f) => f.serializable()),
      autosizeMinRows: this.autosizeMinRows,
      scrollHeight: this.scrollHeight,
    };
  }

  public asFieldDefinition(): FieldDefinition {
    return {
      label: this.label,
      smallLabel: '',
      type: this.type,
      searchable: false,
      datasource: this.dataSource.serializable(),
      hasValidation: this.hasValidation,
      tooltip: this.validation.validationMessage,
      placeholder: '',
      required: false,
      dateFieldExpectedFormat: this.groupingFormat.toLocaleUpperCase(),
      substitutable: false,
      allowNoSelection: this.allowNoSelection,
      displayMode: FieldDisplayMode.vertical,
      hideLabel: false,
      allowNegativeNumbers: true,
      stickyHeader: '',
      fireChangeEventIfSameValue: false,
      defaultValue: this.defaultValue,
      id: '',
      autosizeMinRows: this.autosizeMinRows,
      scrollHeight: this.scrollHeight,
      infoText: '',
      canShowPassword: true,
    };
  }

  public static asIColumn = (mdd: IMetaDataDefinition): IColumn => {
    return {
      displayType: mdd.type == MetaDataType.Date ? ColumnDisplayType.Date : ColumnDisplayType.ActionLink,
      groupingFormat: mdd.groupingFormat,
      headerImage: '',
      headerText: mdd.label,
      id: `SETTINGS.METADATA.${mdd.name}`,
      itemProperty: `extendedDetails.metaData.${mdd.name}`,
      columnName: mdd.name,
      width: 200,
      sortable: false,
      stretch: true,
      sortByFieldName: '',
      invertBooleanValue: false,
    };
  };
}

