import {
  AfterViewInit,
  Component,
  ElementRef,
  Input,
  OnDestroy,
  OnInit,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { Subject, Subscription } from 'rxjs';

import {
  AuthService,
  BrandDetails,
  BrandingService,
  DelayService,
  FieldDefinition,
  Key,
  MetaDataType,
  SessionStorageService,
} from 'shared-code-lib';
import { ItemActionHandler } from '../../core/itemActionHandler';
import { Blurb, UserBlurbInfo } from '../../models/marketing-blurb';
import { IUserProfile, UserSignOnType } from '../../models/user-profile';
import { ActionService } from '../../services/action.service';
import { CaptureStatusService } from '../../services/capture-status.service';
import { HydraApiService } from '../../services/hydra-api.service';
import { TrainingStatusService } from '../../services/training-status.service';
import { UserStateService } from '../../services/user-state.service';
import { VerticalNavService } from '../../services/vertical-nav.service';
import { ActionTypes, ApiResult, IAction, IUser, User, UserTypes } from './../../services/models';

enum Fields {
  UserName,
  Email,
  IntegratedAppUsername,
  IntegratedAppSecret,
  None,
}

class UserSettings {
  constructor(name: string = '', email: string = '') {
    this.newName = name;
    this.newEmail = email;
  }

  newName: string;
  newEmail: string;

  failed: boolean;
  errors: string[] = [];
}

@Component({
  selector: '[appMainHeader]',
  templateUrl: './main-header.component.html',
  styleUrls: ['./main-header.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class MainHeaderComponent implements OnInit, OnDestroy, AfterViewInit {
  @ViewChild('confirmModalButton') confirmModalButton: ElementRef;
  @ViewChild('toggleProfileDropdown') toggleProfileDropdown: ElementRef;
  @Input() isPrintTo;
  @Input() isMobileView = false;
  @Input() isFaxMobile = false;
  @Input() isRegistering = false;
  user: IUser;
  logoutCountdownFormatted = { countdownTime: '' };
  showChangeUserInfoModalBody: boolean;

  logoutConfirmModalInstance: NgxSmartModalComponent;
  modalChangeUserPassword: NgxSmartModalComponent;
  modalChangeUserInformation: NgxSmartModalComponent;

  fieldUserName: FieldDefinition;
  fieldUserEmail: FieldDefinition;
  fieldsCreated = false;
  currentFocusField = Fields.None;

  userSettings: UserSettings;
  userChangedSubscription: Subscription;
  subscriptions = new Subscription();
  openDropDownSubject: Subject<void>;

  isNormalUser: boolean;
  isPasswordSignOn: boolean;
  allowPasswordChange: boolean;
  showWorkflowStatus = true;

  profileActions: Array<IAction> = [];
  itemActionHandler: ItemActionHandler;

  verticalNavExpanded = true;

  readonly OneMinuteInSeconds = 60;
  readonly FiveMinutesInSeconds = this.OneMinuteInSeconds * 5;

  mobileLogoWhite: string;

  logoWhite: string;
  feedbackModal: NgxSmartModalComponent;
  marketingBlurbs: Array<UserBlurbInfo>;
  whatsNewModal: NgxSmartModalComponent;
  selectOptionModal: NgxSmartModalComponent;
  multiSelectOptionModal: NgxSmartModalComponent;
  newBlurbs = false;

  profileDropdownItems: string[] = [];
  selectedProfileDropdownItem = '';

  get isMobileOrFaxMobile() {
    return this.isMobileView || this.isFaxMobile;
  }

  constructor(
    public userState: UserStateService,
    public ngxSmartModalService: NgxSmartModalService,
    private translateService: TranslateService,
    private router: Router,
    private toastr: ToastrService,
    public captureStatus: CaptureStatusService,
    public trainingStatus: TrainingStatusService,
    private delay: DelayService,
    private brandingService: BrandingService,
    private verticalNav: VerticalNavService,
    private ss: SessionStorageService,
    public authService: AuthService,
    private hydraApi: HydraApiService,
    private actionService: ActionService
  ) {
    this.user = <IUser>{};
    this.openDropDownSubject = new Subject<void>();
  }

  ngOnInit() {
    this.userSettings = new UserSettings('');
    this.userChangedSubscription = this.userState.userChanged.subscribe(this.onUserChanged);
    this.isMobileView = this.ss.getIsMobile();
    this.isFaxMobile = this.ss.getIsInterFaxMobile();
    this.subscriptions.add(this.ss.onIsInterFaxMobileChanged.subscribe((x) => (this.isFaxMobile = x)));
    this.showWorkflowStatus = !this.isMobileView && !this.isFaxMobile;

    this.handleBranding();

    this.subscriptions.add(
      this.verticalNav.onToggleVerticalNav$.subscribe((isExpanded) => (this.verticalNavExpanded = isExpanded))
    );

    this.subscriptions.add(this.brandingService.onBrandingChanged.subscribe(() => this.handleBranding()));

    this.subscriptions.add(
      this.userState.userProfileChanged.subscribe((profile: IUserProfile) => {
        this.isPasswordSignOn = profile && profile.signOnType === UserSignOnType.Password;
        this.hydraApi.LoadUserBlurbs(this.blurbsLoaded, this.blurbsFailed);
      })
    );

    this.itemActionHandler = this.actionService.createItemActionHandler();
  }

  blurbsLoaded = (result: ApiResult) => {
    if (result && result.success) {
      this.marketingBlurbs = result.object.map((a) => {
        a.blurbs = a.blurbs.map((d: Blurb) => {
          d.details = d.details.replace(/\n/g, ' <br/> ');
          return d;
        });

        return a;
      });

      this.newBlurbs = this.marketingBlurbs.some((a) => a.seen == false);

      if (this.newBlurbs) this.openWhatsNewModal();
    }
  };

  blurbsFailed = (error: any) => {
    console.log('blurbsFailed', error);
  };

  private handleBranding = (): void => {
    this.mobileLogoWhite = this.brandingService.isBranded()
      ? `logo-mobile-white-${this.brandingService.get()}.svg`
      : 'logo-mobile-white.svg';

    this.updateLogoWhite(this.brandingService.getBrandDetails());
    this.subscriptions.add(this.brandingService.onBrandDetailsUpdated.subscribe(this.updateLogoWhite));
  };

  updateLogoWhite = (bd: BrandDetails) => {
    this.logoWhite = bd?.titleLogoUrl;
    if (!this.logoWhite && bd?.loginLogoUrl) this.logoWhite = bd?.loginLogoUrl;
  };

  ngOnDestroy() {
    if (this.userChangedSubscription) this.userChangedSubscription.unsubscribe();

    this.subscriptions.unsubscribe();
  }

  private onUserChanged = (user: IUser): void => {
    if (!user) return;

    if (!this.isMobileView && !this.isFaxMobile && this?.user?.id != user?.id) {
      this.captureStatus.initialize();
      this.trainingStatus.initialize();
    }

    this.user = user;

    this.isNormalUser = this.user.userType == UserTypes.Normal;
    this.allowPasswordChange = this.user.userType == UserTypes.InterFAX || (this.isNormalUser && this.isPasswordSignOn);

    this.showWorkflowStatus = !this.isMobileView && !this.isFaxMobile && this.user.userType != UserTypes.InterFAX;

    this.updateProfileActions();

    this.setProfileDropdownItems();
  };

  updateProfileActions = (): void => {
    this.profileActions = [];
    if (!this.user?.products) return;

    for (const p of this.user.products) {
      for (const a of p.actions) {
        if (a.type != ActionTypes.ProfileMenu) continue;

        this.profileActions.push(a);
      }
    }
  };

  setProfileDropdownItems() {
    this.profileDropdownItems = [];

    if (this.isNormalUser) this.profileDropdownItems.push('user-information');
    if (this.allowPasswordChange) this.profileDropdownItems.push('change-password');
    this.profileActions.forEach((action) => this.profileDropdownItems.push(action.name));
    this.profileDropdownItems.push('logout');
  }

  onToggleMenu = (): void => {
    this.verticalNav.toggleVerticalNav(!this.verticalNavExpanded, true);
  };

  createFields = (): void => {
    if (this.fieldsCreated) return;

    this.fieldUserName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('MainHeader.field-user-name'),
      placeholder: this.translateService.instant('MainHeader.field-user-name-placeholder'),
      required: true,
    });

    this.fieldUserEmail = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('MainHeader.field-user-email'),
      placeholder: this.translateService.instant('MainHeader.field-user-email-placeholder'),
      required: true,
    });

    this.fieldsCreated = true;
  };

  confirmLogOut() {
    this.userState.confirmLogOut(this.logoutConfirmModalInstance);
  }

  cancelLogout = () => {
    this.userState.cancelLogout(this.logoutConfirmModalInstance);
  };

  logout() {
    if (this.userState.userProfile && this.userState.userProfile.tenantOptions.confirmLogout) {
      this.userState.logout(this.logoutConfirmModalInstance, this.logoutCountdownFormatted, this.FiveMinutesInSeconds);
    } else {
      this.confirmLogOut();
    }
  }

  onDownloadPrintToFax = (): void => {};

  onChangePasswordClicked = (): void => {
    this.modalChangeUserPassword.open();
  };

  cancelChangePassword = (): void => {
    this.modalChangeUserPassword.close();
  };

  onChangeUserInformationClicked = (): void => {
    this.createFields();

    this.userSettings = new UserSettings(this.user.name, this.user.email);
    this.setFocusedField(Fields.UserName);

    this.delay.execute(() => {
      this.showChangeUserInfoModalBody = true;
    }, 0);

    this.modalChangeUserInformation.open();
  };

  cancelChangeUserInformation = (): void => {
    this.showChangeUserInfoModalBody = false;
    this.modalChangeUserInformation.close();
  };

  applyChangeUserInformation = (): void => {
    this.setFocusedField(Fields.None);

    if (!this.userSettings.newName.length) {
      this.userSettings.errors = ['MainHeader.new-name-required'];
      this.setFocusedField(Fields.UserName);
      return;
    }

    if (!this.userSettings.newEmail.length) {
      this.userSettings.errors = ['MainHeader.new-email-required'];
      this.setFocusedField(Fields.Email);
      return;
    }

    this.userState.changeUserInformation(
      this.userSettings.newName,
      this.userSettings.newEmail,
      this.onUserInformationSaved,
      this.onFailedSaveUserInformation
    );
  };

  onUserInformationSaved = (result: ApiResult): void => {
    if (result && !result.success) {
      this.userSettings.errors = result.errors;
      this.setFocusedField(Fields.UserName);
      return;
    }

    this.toastr.success(this.translateService.instant('MainHeader.saved-user-information'));

    this.user.name = this.userSettings.newName;
    this.user.email = this.userSettings.newEmail.toLowerCase();
    this.userState.userChanged.next(new User(this.user));

    this.showChangeUserInfoModalBody = false;
    this.modalChangeUserInformation.close();
  };

  onFailedSaveUserInformation = (err: any): void => {
    this.userSettings.errors = ['MainHeader.failed-save-user-information'];
    this.setFocusedField(Fields.UserName);
  };

  ngAfterViewInit() {
    this.modalChangeUserPassword = this.ngxSmartModalService.getModal('changeUserPasswordModal');
    this.modalChangeUserPassword.onEscape.subscribe(() => this.cancelChangePassword());

    this.modalChangeUserInformation = this.ngxSmartModalService.getModal('changeUserInformationModal');
    this.modalChangeUserInformation.onEscape.subscribe(() => this.cancelChangeUserInformation());

    this.logoutConfirmModalInstance = this.ngxSmartModalService.getModal('logoutConfirmModal');
    this.subscriptions.add(
      this.logoutConfirmModalInstance.onOpen.subscribe((modal: NgxSmartModalComponent) => {
        modal.removeData();
      })
    );

    this.feedbackModal = this.ngxSmartModalService.getModal('feedbackModal');

    this.whatsNewModal = this.ngxSmartModalService.getModal('whatsNewModal');
    this.subscriptions.add(this.whatsNewModal.onAnyCloseEvent.subscribe(() => this.closeWhatsNewModal()));

    const actionConfirmModal = this.ngxSmartModalService.getModal('actionConfirmModal');
    this.subscriptions.add(
      actionConfirmModal.onOpen.subscribe((modal: NgxSmartModalComponent) => {
        this.delay.execute(() => {
          this.confirmModalButton.nativeElement.focus();
        }, 50);
      })
    );

    this.selectOptionModal = this.ngxSmartModalService.getModal('selectOptionModal');
    this.multiSelectOptionModal = this.ngxSmartModalService.getModal('multiSelectOptionModal');
  }

  toAddSecondaryTitle() {
    if (this.router.url === '/document-capture') {
      return true;
    } else {
      return false;
    }
  }

  viewHelp = (): void => {
    if (this.isFaxMobile) {
      this.goToInterFaxHelpPage();
      return;
    }

    if (this.isMobileView) {
      window.open('https://help.uplandsoftware.com/intelligentcapture/en/mobile/mobile.htm', 'UplandICDocumentation');
      return;
    }

    window.open('https://help.uplandsoftware.com/intelligentcapture/en/Home.htm', 'UplandICDocumentation');
  };

  goToInterFaxHelpPage() {
    this.onProfileAction(this.getInterFaxHelpAction());
  }

  getInterFaxHelpAction() {
    let interFaxHelpAction;

    this.user.products.forEach((product) => {
      product.actions.forEach((action) => {
        if (action.id === 'InterFAX-Upland.Bamba.InterFAX.Actions.ShowUserHelp') interFaxHelpAction = action;
      });
    });

    return interFaxHelpAction;
  }

  onShowMenu() {
    this.openDropDownSubject.next();
  }

  userNameFocused(): boolean {
    return this.currentFocusField === Fields.UserName;
  }

  emailFocused(): boolean {
    return this.currentFocusField === Fields.Email;
  }

  setFocusedField = (field = Fields.None): void => {
    this.delay.execute(() => {
      this.currentFocusField = field;
    }, 0);
  };

  onProfileAction = (action: IAction) => {
    if (!action) return;

    this.itemActionHandler.invoke('', action, [], []);
  };

  openFeedbackModal = (): void => {
    this.feedbackModal.open();
  };

  closeFeedbackModal = (): void => {
    this.feedbackModal.close();
  };

  openWhatsNewModal = (): void => {
    this.whatsNewModal.open();
  };

  closeWhatsNewModal = (): void => {
    const unseenBlurbs: string[] = [];

    this.marketingBlurbs.forEach((marketingBlurb) => {
      if (marketingBlurb.seen) return;

      unseenBlurbs.push(marketingBlurb.id);
      marketingBlurb.seen = true;
    });

    this.whatsNewModal.close();

    if (unseenBlurbs.length == 0) return;

    this.hydraApi.markMarketingBlurbsAsSeen(
      unseenBlurbs,
      () => {
        this.newBlurbs = false;
      },
      (err) => {
        console.log(err);
      }
    );
  };

  onKeyDown = (e: KeyboardEvent) => {
    if (e.key == Key.ArrowUp) {
      let selectedProfileItemIndex = this.profileDropdownItems.findIndex(
        (item) => item === this.selectedProfileDropdownItem
      );

      this.setProfileDropdownSelectedItem(this.profileDropdownItems[--selectedProfileItemIndex]);

      if (selectedProfileItemIndex < 0)
        this.setProfileDropdownSelectedItem(this.profileDropdownItems[this.profileDropdownItems.length - 1]);
    } else if (e.key == Key.ArrowDown) {
      let selectedProfileItemIndex = this.profileDropdownItems.findIndex(
        (item) => item === this.selectedProfileDropdownItem
      );

      this.setProfileDropdownSelectedItem(this.profileDropdownItems[++selectedProfileItemIndex]);

      if (selectedProfileItemIndex === this.profileDropdownItems.length)
        this.setProfileDropdownSelectedItem(this.profileDropdownItems[0]);
    } else if (e.key == Key.Enter) {
      this.executeSelectedProfileItem();
      this.toggleProfileDropdown?.nativeElement?.click();
      this.resetProfileDropdownSelectedItem();
    }
  };

  executeSelectedProfileItem() {
    switch (this.selectedProfileDropdownItem) {
      case 'user-information':
        this.onChangeUserInformationClicked();
        break;
      case 'change-password':
        this.onChangePasswordClicked();
        break;
      case 'logout':
        this.logout();
        break;
      default:
        const selectedAction = this.profileActions.find((action) => action.name === this.selectedProfileDropdownItem);
        this.onProfileAction(selectedAction);
        break;
    }
  }

  setProfileDropdownSelectedItem(itemId: string) {
    this.selectedProfileDropdownItem = itemId;
  }

  resetProfileDropdownSelectedItem() {
    this.selectedProfileDropdownItem = '';
  }

  goToInterFaxMobileHomePage() {
    if (!this.ss.getIsInterFaxMobile()) return;
    this.router.navigate([this.userState.getUserHomePage()]);
  }
}
