import { EditorView } from '@progress/kendo-angular-editor';
import { GapCursor } from 'prosemirror-gapcursor';
import { TextSelection } from 'prosemirror-state';

export const isHtmlEmpty = (html: string) => {
  const domParser = new DOMParser();
  const valueDomNode = domParser.parseFromString(html, 'text/html');

  const hasTexts = !!valueDomNode.body.innerText.trim();
  const hasImages = !!valueDomNode.querySelector('img');
  const hasTables = !!valueDomNode.querySelector('table');
  const hasLists = !!valueDomNode.querySelector('li');

  return !html || (!hasTexts && !hasImages && !hasTables && !hasLists);
};

export const doesHtmlContainText = (html: string) => {
  const domParser = new DOMParser();
  const valueDomNode = domParser.parseFromString(html, 'text/html');

  return html && valueDomNode.body.innerText;
};

export const createArrayFromNumber = (number: number) => [...Array(number).keys()];

const pressArrowKey = (axis: 'vertical' | 'horizontal', dir: 1 | -1, view: EditorView) => {
  const { state, dispatch } = view;
  const dirStr = axis === 'vertical' ? (dir > 0 ? 'down' : 'up') : dir > 0 ? 'right' : 'left';

  const { $to, $from, empty } = state.selection;
  let $start = dir > 0 ? $to : $from;
  let mustMove = empty;

  const isTextSelection = state.selection instanceof TextSelection;

  if (isTextSelection && (!view!.endOfTextblock(dirStr) || $start.depth == 0)) return false;

  if (isTextSelection && !(!view!.endOfTextblock(dirStr) || $start.depth == 0)) {
    mustMove = false;
    $start = state.doc.resolve(dir > 0 ? $start.after() : $start.before());
  }

  const selection = GapCursor.findFrom($start, dir, mustMove);
  if (!selection) return false;

  //@ts-ignore
  if (dispatch) dispatch(state.tr.setSelection(new GapCursor(selection)));

  return true;
};

export const pressArrowDown = (view: EditorView) => {
  return pressArrowKey('vertical', 1, view);
};
