import {
  AfterViewInit,
  Directive,
  ElementRef,
  EventEmitter,
  HostListener,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
} from '@angular/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { Observable, Subscription } from 'rxjs';

import { DelayService, Languages } from 'shared-code-lib';
import { TabItem, Widget } from '../../models/home-page-tab';
import { VerticalNavService } from '../../services/vertical-nav.service';
import { Attributes, AttributesEnum, Grid } from './grid-classes';

declare const $: any;

@Directive({
  selector: '[appGridLayout]',
})
export class GridLayoutDirective implements OnInit, AfterViewInit, OnChanges, OnDestroy {
  @Input() sortable: boolean;
  @Input() items: Array<TabItem>;
  @Input() widgets: Array<Widget>;
  @Input() scrollbar: PerfectScrollbarDirective;
  @Input() updateGrid: Observable<Widget>;
  @Output() sorted = new EventEmitter();

  constructor(private el: ElementRef, private delay: DelayService, private verticalNav: VerticalNavService) {}

  private grid: Grid;
  private margin = 16;
  private draggingItemIndex: number;
  private draggingElement: any;
  private readonly distance = 150;
  private readonly repeatTime = 5;
  private readonly step = 50;
  private intTopHandler: any;
  private intBottomHandler: any;
  private updateGridSubscription: Subscription;
  private verticalNavSubscription: Subscription;

  @HostListener('window:resize')
  onResize() {
    this.setUpGrid();
  }

  ngOnInit() {
    this.verticalNavSubscription = this.verticalNav.onToggleVerticalNav$.subscribe(() => this.init(400));

    $(this.el.nativeElement).addClass('loading');

    this.updateGridSubscription = this.updateGrid.subscribe(() => {
      this.init(0);
    });
  }

  ngAfterViewInit() {
    this.init(1000);
  }

  ngOnChanges() {
    this.init(0);
  }

  init(delay: number) {
    if (this.items.length && this.widgets.length) {
      this.delay.execute(() => {
        this.setUpGrid();
        if (this.sortable) {
          this.initSorting();
        }
      }, delay);
    }
  }

  ngOnDestroy() {
    this.updateGridSubscription.unsubscribe();
    this.verticalNavSubscription.unsubscribe();
  }

  setUpGrid() {
    const that = this;
    const gridElement = $(this.el.nativeElement);
    const rowWidth = gridElement.width();
    this.grid = new Grid(gridElement, rowWidth, 2, this.margin);
    let gridHeight = 0;

    $('.empty').each(function () {
      $(this).remove();
    });

    this.scrollbar.update();
    this.clearIntervals();

    gridElement.children('.grid-item').each(function (index: number) {
      const $this = $(this);
      const item: TabItem = that.items[index];
      const widgetWidth = that.getWidgetWidth(item);
      let { width, topPosition, leftPosition } = that.grid.getBlockPosition(item, widgetWidth);
      if (Languages.isRTLLanguage()) leftPosition *= -1;
      $this.css({
        right: Languages.isRTLLanguage() ? 0 : 'initial',
        left: Languages.isRTLLanguage() ? 'initial' : 0,
        top: 0,
        transform: `translateX(${leftPosition}px) translateY(${topPosition}px)`,
        width: width,
      });

      if (topPosition + item.height > gridHeight) {
        gridHeight = topPosition + item.height;
      }
    });

    gridElement.height(gridHeight);
    this.delay.execute(() => {
      gridElement.removeClass('loading');
      this.scrollbar.update();
    }, 500);
  }

  onDropOnEmptyBlock = (attributes: Attributes, isColumn: boolean) => {
    const draggedItem = this.items[this.draggingItemIndex] as TabItem;
    const widgetWidth = this.getWidgetWidth(draggedItem);
    this.grid.handleDragOnEmptyBlock(draggedItem, widgetWidth, attributes, isColumn);
    this.sortItems();
    this.clearIntervals();
    this.sorted.emit();
    this.destroySorting();
    this.init(100);
  };

  sortItems() {
    this.items = this.items.sort((a: TabItem, b: TabItem) => {
      if (a.primaryColumn === b.primaryColumn) {
        if (a.row === b.row) {
          return a.column - b.column;
        }

        return a.row - b.row;
      }

      return a.primaryColumn - b.primaryColumn;
    });
  }

  getWidgetWidth(item: TabItem) {
    return this.widgets.find((widget) => widget.id === item.widgetId).width;
  }

  initSorting = () => {
    const that = this;
    const el = document.querySelector('.tab-content');
    const container = $(el);

    if (this.draggingElement) {
      this.draggingElement.removeClass('drag-started');
      this.draggingElement.removeClass('draggable');
      $('body').removeClass('drag-started');
    }

    this.clearIntervals();

    container.unbind('dragover');
    container.unbind('drop');

    container.on('dragover', (ev: DragEvent) => this.onDragOverContainer(ev));
    container.on('drop', (ev: DragEvent) => this.onDropOverContainer(ev));

    $(this.el.nativeElement)
      .children('.grid-item')
      .each(function (i: number) {
        const element = $(this);
        element.unbind('dragstart');
        element.unbind('drag');
        element.unbind('dragend');
        element.attr({
          draggable: 'true',
          'data-index': i,
        });
        element.addClass('item-drop');

        const dragHandler = element.find('.gripper');
        if (dragHandler.length) {
          dragHandler.mousedown(function (ev: DragEvent) {
            ev.stopPropagation();
            element.addClass('draggable');
          });

          dragHandler.mouseup(function (ev: DragEvent) {
            ev.stopPropagation();
            element.removeClass('draggable');
          });
        }

        element.on('dragstart', (ev: DragEvent) => that.onDragStart(ev, element, i));

        element.on('dragend', (ev: DragEvent) => that.onDragEnd(ev, element));
      });
  };

  private onDragStart(ev: DragEvent, element: any, index: number) {
    this.draggingElement = $(element);
    this.handleFireFoxDnDRequirements(ev);
    if (!element.hasClass('draggable')) {
      ev.preventDefault();
      return;
    }

    ev.stopPropagation();
    this.draggingElement.addClass('drag-started');
    $('body').addClass('drag-started');
    this.draggingItemIndex = index;
    this.grid.onDrag(this.items[index]);
  }

  private onDragEnd(ev: DragEvent, element: any) {
    ev.preventDefault();
    ev.stopPropagation();
    this.clearIntervals();
    $(element).removeClass('drag-started');
    $(element).removeClass('draggable');
    $('body').removeClass('drag-started');
    this.draggingItemIndex = null;
    this.grid.onDragEnd();
  }

  private onDragOverContainer(ev: DragEvent) {
    ev.stopPropagation();
    ev.preventDefault();

    if (!this.grid.dragFromPage) return;

    const prevTarget = $('.drop-available');
    const target = $(ev.target).closest('.item-drop');

    if (prevTarget) {
      prevTarget.removeClass('drop-available');
    }

    if (target) {
      target.addClass('drop-available');
    }

    if ((ev as any).originalEvent.clientY < this.distance) {
      this.handleAutoScroll('top');
      return;
    }

    if ((ev as any).originalEvent.clientY > $(window).height() - this.distance) {
      this.handleAutoScroll('bottom');
      return;
    }

    this.handleAutoScroll(null);
  }

  private onDropOverContainer(ev: DragEvent) {
    ev.preventDefault();
    ev.stopPropagation();
    this.clearIntervals();

    const prevTarget = $('.drop-available');
    const target = $(ev.target).closest('.item-drop');
    const index = parseInt(target.attr('data-index'), 10);

    if (prevTarget) {
      prevTarget.removeClass('drop-available');
    }

    if (!target.length) {
      return;
    }

    if (target.hasClass('grid-item')) {
      if (this.draggingItemIndex === index) {
        return;
      }

      const item = this.items[this.draggingItemIndex];
      const widgetWidth = this.getWidgetWidth(item);
      this.grid.handleDragDropBlocks(item, widgetWidth, this.items[index]);
      this.sortItems();
      this.sorted.emit();
      this.destroySorting();
      this.init(100);

      return;
    }

    const dataAttr: Attributes = {
      'data-column': parseInt(target.attr(AttributesEnum.dataColumn), 10),
      'data-row': parseInt(target.attr(AttributesEnum.dataRow), 10),
      'data-primary-column': parseInt(target.attr(AttributesEnum.dataPrinmaryColumn), 10),
    };

    if (target.hasClass('empty')) {
      this.onDropOnEmptyBlock(dataAttr, false);
      return;
    }

    if (target.hasClass('empty-column') || target.hasClass('empty-bottom-column')) {
      this.onDropOnEmptyBlock(dataAttr, true);
    }
  }

  private handleFireFoxDnDRequirements(event: DragEvent): void {
    const firefoxEvent = <any>event;
    if (firefoxEvent.originalEvent && firefoxEvent.originalEvent.dataTransfer) {
      firefoxEvent.originalEvent.dataTransfer.setData('text', '');
    }
  }

  private destroySorting = () => {
    $('.tab-content').unbind('dragover');
    $('.tab-content').unbind('drop');
    $(this.el.nativeElement)
      .children('.grid-item')
      .each(function () {
        const element = $(this);
        element.unbind('dragstart');
        element.unbind('dragend');
      });
  };

  private handleAutoScroll(dir?: string) {
    const div = $('.tab-content');

    if (dir === 'top') {
      if (!this.intTopHandler) {
        this.intTopHandler = setInterval(() => {
          this.scrollbar.scrollToY(div.scrollTop() - this.step, 30);
        }, this.repeatTime);
      }
    } else if (dir === 'bottom') {
      if (!this.intBottomHandler) {
        this.intBottomHandler = setInterval(() => {
          this.scrollbar.scrollToY(div.scrollTop() + this.step, 30);
        }, this.repeatTime);
      }
    } else {
      this.clearIntervals();
    }
  }

  private clearIntervals() {
    if (this.intBottomHandler) {
      clearInterval(this.intBottomHandler);
      this.intBottomHandler = null;
    }

    if (this.intTopHandler) {
      clearInterval(this.intTopHandler);
      this.intTopHandler = null;
    }
  }
}
