import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnInit,
  Output,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';

import { TranslateService } from '@ngx-translate/core';

import { MetaDataType } from '../../models/metadata-definition';
import { Key } from '../../utils/key-enum';
import { FieldDefinition } from './../../models/field-definition';
import { MetaDataValidity } from './../../models/metadata';

@Component({
  selector: 'field-text',
  templateUrl: './text.component.html',
  styleUrls: ['./text.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class TextComponent implements OnInit, AfterViewInit {
  @ViewChild('input', { static: false }) input: ElementRef<HTMLInputElement>;

  _value: string;

  @Input()
  get value(): string {
    return this._value;
  }
  set value(value: string) {
    this._value = this.normalizeValue(value);
  }

  @Input() field: FieldDefinition;
  @Input() disabled: boolean;
  @Input()
  set validity(state: MetaDataValidity) {
    this.validationState = state;
    this.previousValidationState = state;
    this.needToBeValidated = false;
  }
  @Input() validityError: string;

  _focused: boolean;

  @Input()
  get focused() {
    return this._focused;
  }
  set focused(isFocused: boolean) {
    this.setFocused(isFocused);
  }

  @Input()
  set setValue(value: string) {
    if (value) {
      this._value = this.normalizeValue(value);
      this.valueChange.emit(this.value);
      if (this.triggerBlurEventOnValueChange) this.fieldBlur.emit(this.value);
    }
  }

  @Input() triggerBlurEventOnValueChange: boolean;

  @Input() forceMaxLength = false;
  @Input() maxLength: number;
  @Input() fieldTabIndex = 0;
  @Input() fieldId: string = '';
  @Input() regex: RegExp;
  @Input() autocomplete: string = 'on';

  @Output() fieldFocus = new EventEmitter();
  @Output() fieldBlur = new EventEmitter<string>();
  @Output() fieldOnTab = new EventEmitter<string>();
  @Output() fieldOnShiftTab = new EventEmitter<string>();
  @Output() valueChange = new EventEmitter<string>();
  @Output() fieldOnReturn = new EventEmitter<string>();
  @Output() inputChange = new EventEmitter<string>();
  @Output() escape = new EventEmitter<void>();

  isCurrentField: boolean;
  needToBeValidated: boolean;
  validationState: MetaDataValidity;
  previousValidationState: MetaDataValidity;
  metaDataValidity = MetaDataValidity;

  substitutable: boolean;
  substitutableTooltip: string;

  valueHasChanged = false;

  constructor(public translateService: TranslateService) {
    this.substitutableTooltip = this.translateService ? this.translateService.instant('fields.substitutable') : '';
  }

  ngOnInit(): void {
    this.valueHasChanged = false;
    this.substitutable = this.field.substitutable;
  }

  ngAfterViewInit() {
    if (this.maxLength || this.maxLength === 0) {
      if (this.maxLength > 0 || this.forceMaxLength) this.input.nativeElement.maxLength = this.maxLength;
    }

    this.setFocused(this._focused);

    this.validateRegex(this.value, '');
  }

  setFocused(isFocused: boolean, beforeEventFiredCallback?: () => void) {
    this._focused = isFocused;
    beforeEventFiredCallback?.();
    this.toggleInputFocus();
  }

  toggleInputFocus() {
    if (this._focused) {
      this.input?.nativeElement.focus();
      this.isCurrentField = true;
      return;
    }

    this.input?.nativeElement.blur();
    this.isCurrentField = false;
  }

  onFocus(e: any) {
    this.valueHasChanged = false;
    this.focused = true;
    this.fieldFocus.emit();
  }

  onBlur(event: any) {
    if (!event.target) return;

    this.onBeforeBlurCheck(event);
    this.onChangeValue(this._value);
    this.focused = false;
    const blurEventTriggered = this.checkValues();
    if (!blurEventTriggered) this.confirmSuspicious(this._value);
  }

  protected onBeforeBlurCheck(event: any) {}

  onKeydown(event: any): void {
    let currentValue = event.target.value?.toString();
    if (!currentValue && this.isNumericField()) currentValue = '0';

    if (event.key === Key.Tab) {
      this.confirmSuspicious(currentValue);
      event.shiftKey ? this.fieldOnShiftTab.emit(currentValue) : this.fieldOnTab.emit(currentValue);
      return;
    }

    if (!this.isNumericField()) return;

    switch (event.key) {
      case Key.ArrowUp:
        this.value = this.formatNumber(Number(currentValue) + 1);
        this.valueHasChanged = true;
        event.preventDefault();
        break;

      case Key.ArrowDown:
        if (currentValue !== '0' || this.field.allowNegativeNumbers) {
          this.value = this.formatNumber(Number(currentValue) - 1);
          this.valueHasChanged = true;
          event.preventDefault();
        }
        break;
    }
  }

  isNumericField(): boolean {
    return (
      this.field.type === MetaDataType.Integer ||
      this.field.type === MetaDataType.Decimal ||
      this.field.type === MetaDataType.Currency
    );
  }

  formatNumber(value: number): string {
    return value.toFixed(10).replace(/\.?0+$/, '');
  }

  formatValue(value: string): string {
    return this.normalizeValue(value);
  }

  onReturn() {
    const value = this.input.nativeElement.value.toString();

    this.confirmSuspicious(value);

    this.fieldOnReturn.emit(value);
  }

  onEscape() {
    this.escape.emit();
  }

  onSearch(): void {
    const value = this.input.nativeElement.value.toString();
    if (value) {
      this.onReturn();
    }
  }

  checkValues(): boolean {
    if (this.valueHasChanged) {
      this.valueChange.emit(this.value);
      this.fieldBlur.emit(this.value);
      return true;
    } else {
      this.validationState = this.previousValidationState;
      this.needToBeValidated = false;
    }

    return false;
  }

  confirmSuspicious = (value: string): boolean => {
    if (this.validationState !== MetaDataValidity.suspicious) return false;

    this.fieldBlur.emit(value);

    return true;
  };

  protected onChangeValue(value: string) {
    if (this.value == value) return;

    const validRegex = this.validateRegex(value, this.value);
    if (!validRegex) return;

    this.valueHasChanged = true;
    this.value = value ? value.toString() : '';

    if (this.field.hasValidation) {
      this.needToBeValidated = true;
      this.previousValidationState = this.validationState;
      this.validationState = null;
    }

    const trimmedString = this.normalizeValue(this.value);
    this.valueChange.emit(trimmedString);
  }

  validateRegex(value: string, previousValue: string): boolean {
    if (this.regex === undefined || this.regex.test(value)) return true;

    this.input.nativeElement.value = previousValue;
    this.value = previousValue;
    return false;
  }

  onInputChanged(event: any) {
    this.valueHasChanged = true;

    const trimmedString = this.normalizeValue(event?.target?.value);
    this.inputChange.emit(trimmedString);
  }

  protected normalizeValue(value: string): string {
    return value?.replace(/\s+$/, '');
  }

  protected parseLocaleNumber(strNum: string) {
    const decSep = (1.1).toLocaleString().substring(1, 2);
    // split sign and number
    const sign = strNum.match(/^-/) ? '-' : '';
    const number = strNum.replace(/^-/, '');

    let val = number == '.' || number == decSep ? `${sign}0.` : `${sign}${number}`;

    const formatted = val
      .replace(new RegExp(`([${decSep}])(?=.*\\1)`, 'g'), '')
      .replace(new RegExp(`[^0-9${decSep}-]`, 'g'), '');

    const num = formatted === '' ? '' : formatted === '-' ? '-' : formatted.replace(decSep, '.');
    return num;
  }
}
