import { Component, Input } from '@angular/core';
import { localizeNumberToCurrency } from '../../utils/currency';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { IMoneyAmount } from 'shared-code-lib';

@Component({
  selector: 'app-localized-money-amount',
  templateUrl: './LocalizedMoneyAmount.component.html',
  styleUrls: ['./LocalizedMoneyAmount.component.scss'],
})
export class LocalizedMoneyAmountComponent {
  @Input() amount: IMoneyAmount;

  get localizedAmount() {
    return localizeNumberToCurrency(this.amount.value, this.amount.currencyCode, this.userState.getLocale());
  }

  constructor(private userState: UserStateService) {}
}
