import { Directive, ElementRef, Output, EventEmitter, OnInit } from '@angular/core';
import * as Hammer from 'hammerjs';

export interface GesturesFinalResult {
  posX: number;
  posY: number;
  scale: number;
}

@Directive({
  selector: '[appTouchGestures]',
})
export class TouchGesturesDirective implements OnInit {
  scale: number = 1;
  posX: number = 0;
  posY: number = 0;

  maxPosX: number;
  maxPosY: number;

  minScale: number = 1;
  maxScale: number = 2;

  @Output() onSingleTap = new EventEmitter<any>();
  @Output() onDoubleTap = new EventEmitter<any>();
  @Output() onPanEnd = new EventEmitter<any>();
  @Output() onPinchend = new EventEmitter<any>();
  @Output() onMouseWheel = new EventEmitter<any>();
  @Output() onGesturesFinish = new EventEmitter<GesturesFinalResult>();

  constructor(private elementRef: ElementRef) {}

  ngOnInit(): void {
    this.setHammerTouchEventsToElement(this.elementRef.nativeElement);
  }

  setHammerTouchEventsToElement(el) {
    this.setAnimationWithTransform(el);
    this.setMaxXAndYPositions(el);

    let hammerManager = new Hammer.Manager(el, {
      recognizers: [[Hammer.Pinch, { enable: true }], [Hammer.Pan]],
    });

    hammerManager.add(new Hammer.Tap({ event: 'doubletap', taps: 2 }));
    hammerManager.add(new Hammer.Tap({ event: 'singletap' }));
    hammerManager.get('doubletap').recognizeWith('singletap');
    hammerManager.get('singletap').requireFailure('doubletap');

    hammerManager.on('singletap', (ev) => {
      this.onSingleTap.emit();
      this.emitFinalGesturesResult();
    });

    hammerManager.on('doubletap', (ev) => {
      let updatedScale = this.scale > this.minScale ? this.minScale : this.maxScale;
      this.scale = updatedScale;
      const updatedPosition = this.updateXAndYPositions(ev);
      this.setTransform(el, this.scale, updatedPosition.x, updatedPosition.y);
      this.setMaxXAndYPositions(el);
      this.onDoubleTap.emit();
      this.emitFinalGesturesResult();
    });

    hammerManager.on('pinchstart', (ev) => {
      //remove pan event listener while pinch event is active
      hammerManager.off('pan');
      hammerManager.off('panend');
    });

    hammerManager.on('pinch', (ev) => {
      const updatedScale = this.updateScale(ev);
      const updatedPosition = this.updateXAndYPositions(ev);

      this.setTransform(el, updatedScale, updatedPosition.x, updatedPosition.y);
    });

    hammerManager.on('pinchend', (ev) => {
      this.scale = this.updateScale(ev);
      this.setMaxXAndYPositions(el);
      this.posX = Math.min(Math.max(-this.maxPosX, this.posX), this.maxPosX);
      this.posY = Math.min(Math.max(-this.maxPosY, this.posY), this.maxPosY);
      this.setTransform(el, this.scale, this.posX, this.posY);
      this.onPinchend.emit();
      this.emitFinalGesturesResult();
      //set pan event listener again after finishing pinch event
      window.setTimeout(hammerPan, 500);
    });

    const hammerPan = () => {
      hammerManager.on('pan', (ev) => {
        const updatedPosition = this.updateXAndYPositions(ev);
        this.setTransform(el, this.scale, updatedPosition.x, updatedPosition.y);
      });

      hammerManager.on('panend', (ev) => {
        const updatedPosition = this.updateXAndYPositions(ev);
        this.posX = updatedPosition.x;
        this.posY = updatedPosition.y;
        this.onPanEnd.emit();
        this.emitFinalGesturesResult();
      });
    };

    hammerPan();

    el.addEventListener(
      'wheel',
      (ev) => {
        if (ev.ctrlKey) {
          ev.preventDefault();

          const updatedPosition = this.updateXAndYPositions(ev, true);
          this.scale = this.updateScale(ev, true);

          this.setTransform(el, this.scale, updatedPosition.x, updatedPosition.y);
          this.setMaxXAndYPositions(el);
          this.onMouseWheel.emit();
          this.emitFinalGesturesResult();
        }
      },
      { passive: false }
    );
  }

  setAnimationWithTransform(el) {
    el.style.transition = 'transform .2s linear';
  }

  updateXAndYPositions(ev, wheelEvent?: boolean) {
    let updatedXPosition;
    let updatedYPosition;

    if (wheelEvent) {
      const dx_And_dy = ev.deltaY * 0.01;
      updatedXPosition = this.scale === 1 ? 0 : this.posX + dx_And_dy;
      updatedYPosition = this.scale === 1 ? 0 : this.posY + dx_And_dy;
    } else {
      updatedXPosition = this.scale === 1 ? 0 : this.posX + ev.deltaX / this.scale;
      updatedYPosition = this.scale === 1 ? 0 : this.posY + ev.deltaY / this.scale;
    }

    updatedXPosition = Math.min(Math.max(-this.maxPosX, updatedXPosition), this.maxPosX);
    updatedYPosition = Math.min(Math.max(-this.maxPosY, updatedYPosition), this.maxPosY);

    return {
      x: updatedXPosition,
      y: updatedYPosition,
    };
  }

  updateScale(ev, wheelEvent?: boolean) {
    let updatedScale;
    if (wheelEvent) {
      const dx_And_dy = ev.deltaY * 0.01;
      updatedScale = this.scale - dx_And_dy;
    } else {
      updatedScale = this.scale * ev.scale;
    }
    updatedScale = Math.min(Math.max(this.minScale, updatedScale), this.maxScale);

    return updatedScale;
  }

  setMaxXAndYPositions(el) {
    this.maxPosX = Math.ceil(((this.scale - 1) * el.clientWidth) / (2 * this.scale));
    this.maxPosY = Math.ceil(((this.scale - 1) * el.clientHeight) / (2 * this.scale));
  }

  setTransform(element, scale, xPos, yPos) {
    element.style.transform = 'scale(' + scale + ') translate(' + xPos + 'px,' + yPos + 'px)';
  }

  emitFinalGesturesResult() {
    this.onGesturesFinish.emit({
      posX: this.posX,
      posY: this.posY,
      scale: this.scale,
    });
  }
}
