import { Component, EventEmitter, OnDestroy, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { FieldDefinition, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { JiraIssue } from '../../models/jira-issue';

import { ApiResult } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

import { Subscription, take } from 'rxjs';
import { IUploadProgressEvent } from '../../models/large-file-upload';
import { HydraApiService } from '../../services/hydra-api.service';
import { LargeFileUploadService } from '../../services/large-file-upload.service';

@Component({
  selector: 'app-add-external-resolved-ticket',
  templateUrl: './add-external-resolved-ticket.component.html',
  styleUrls: ['./add-external-resolved-ticket.component.scss'],
})
export class AddExternalResolvedTicketComponent implements OnInit, OnDestroy {
  @Output() closeModal = new EventEmitter();
  zipFile: File;

  componentNames: string = '';
  componentIds = [];

  jiraIdField: FieldDefinition;
  externalVersionNumberField: FieldDefinition;

  jiraId: string;
  externalVersionNumber: string;

  jiraIssue: JiraIssue = null;
  errors = [];

  subscriptions = new Subscription();

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private largeFileUploadService: LargeFileUploadService,
    private hydraApiService: HydraApiService
  ) {}

  ngOnInit(): void {
    this.componentIds = this.sharedDataService.extraParameters.items.map((i) => i.id);
    this.validateSelectedComponents();

    const names = this.sharedDataService.extraParameters.items.map((i) => i.name);
    this.componentNames = names.join(', ');

    this.createFields();

    this.subscriptions.add(
      this.largeFileUploadService.uploadProgress$.subscribe((progress: IUploadProgressEvent) =>
        this.onReceiveUploadProgress(progress)
      )
    );
  }

  validateSelectedComponents = () => {
    if ((this.componentIds.length = 1)) return;

    this.errors.push(
      this.translateService.instant('add-external-resolved-ticket.errors.please-choose-one-external-component')
    );
  };

  createFields = () => {
    this.jiraIdField = new FieldDefinition({
      type: MetaDataType.Text,
      placeholder: this.translateService.instant('add-resolved-ticket.jira-id-placeholder'),
      label: this.translateService.instant('add-resolved-ticket.jira-id'),
      required: true,
    });

    this.externalVersionNumberField = new FieldDefinition({
      type: MetaDataType.Text,
      placeholder: this.translateService.instant('add-external-resolved-ticket.external-version-number'),
      label: this.translateService.instant('add-external-resolved-ticket.external-version-number'),
      required: true,
    });
  };

  onReceiveUploadProgress = (progressData: IUploadProgressEvent) => {
    const { done, overallPercentComplete } = progressData;

    console.log(`Progress: ${overallPercentComplete}, Done: ${done}`);

    const uploadMessage$ = done
      ? this.translateService.get('add-external-resolved-ticket.finalizing-file-upload')
      : this.translateService.get('add-external-resolved-ticket.uploading-file');

    this.subscriptions.add(
      uploadMessage$.subscribe((message) => {
        const uploadMessage = done ? message : `${message}${overallPercentComplete}%`;
        this.spinnerService.show(uploadMessage, this.getSpinnerElement());
      })
    );
  };

  handleFileSelect = (event: Event): void => {
    const input = event.target as HTMLInputElement;
    this.zipFile = input?.files?.[0];
    if (!this.zipFile) return;

    this.externalVersionNumber = this.getFileVersion();
  };

  getFileVersion = () => {
    const fileName = this.zipFile.name;

    const chromiumVersionPattern = /\d+\.\d+\.\d+\.\d+/;
    const chromiumMatch = fileName.match(chromiumVersionPattern);
    if (chromiumMatch) return chromiumMatch[0];

    const lexiityVersionPattern = /\d+_\d+_\d+_\d+/;
    const lexiityMatch = fileName.match(lexiityVersionPattern);

    return lexiityMatch ? lexiityMatch[0].replace(/_/g, '.') : '';
  };

  verify = () => {
    if (this.componentIds.length > 1) return;

    this.errors = [];
    this.jiraIssue = null;
    this.spinnerService.show(
      this.translateService.instant('add-external-resolved-ticket.loading'),
      this.getSpinnerElement()
    );

    this.hydraApiService.getJiraIssue(
      this.jiraId,
      true,
      this.onGetJiraTicketSucceeded,
      this.onGetJiraTicketFailed,
      false,
      'Code Review, Merged'
    );
  };

  addTicket = () => {
    this.errors = this.validateData();

    if (this.errors.length) return false;

    const fileName = this.componentNames + `-${this.externalVersionNumber}.zip`;

    this.spinnerService.show(
      this.translateService.instant('add-external-resolved-ticket.preparing-file-upload'),
      this.getSpinnerElement()
    );

    this.subscriptions.add(
      this.largeFileUploadService.uploadLargeFile(this.zipFile, fileName).subscribe({
        next: this.uploadSucceeded,
        error: this.uploadFailed,
      })
    );
  };

  validateData = () => {
    const errors = [];

    if (this.componentIds.length > 1) {
      errors.push(
        this.translateService.instant('add-external-resolved-ticket.errors.please-choose-one-external-component')
      );
    }

    if (!this.jiraId) {
      errors.push(this.translateService.instant('add-external-resolved-ticket.errors.jira-ticket-id-mandatory'));
    }

    if (!this.zipFile) {
      errors.push(this.translateService.instant('add-external-resolved-ticket.errors.zip-file-mandatory'));
    }

    if (!this.externalVersionNumber) {
      errors.push(
        this.translateService.instant('add-external-resolved-ticket.errors.external-version-number-mandatory')
      );
    }

    return errors;
  };

  uploadSucceeded = () => {
    this.errors = [];

    const args = new MetaDataCollection();

    args.set('isExternalComponentTicket', 'true');
    args.set('jiraid', this.jiraIssue.id);
    args.set('externalVersionNumber', this.externalVersionNumber);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.componentIds,
      args,
      this.onAddTicketSucceeded,
      this.onAddTicketFailed
    );
  };

  uploadFailed = () => {
    this.errors.push(this.translateService.instant('add-external-resolved-ticket.errors.failed-to-upload-file'));
    this.spinnerService.hide();
  };

  onGetJiraTicketSucceeded = (result: ApiResult) => {
    if (result.success) {
      this.jiraIssue = result.object;
      this.spinnerService.hide();
    } else {
      this.onGetJiraTicketFailed(result.errors);
    }
  };

  onGetJiraTicketFailed = (errors: any[]) => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
    this.jiraId = '';
  };

  onAddTicketSucceeded = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  onAddTicketFailed = (errors: any[]): void => {
    this.jiraIssue = null;
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  close = (): void => this.closeModal.emit();

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.add-external-resolved-ticket .nsm-content') as HTMLElement;
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.largeFileUploadService.abortFileUpload()?.pipe(take(1)).subscribe();
  }
}
