import {
  AfterViewInit,
  ChangeDetectorRef,
  Component,
  DoCheck,
  ElementRef,
  EventEmitter,
  Inject,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  Renderer2,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ColumnReorderEvent, GridComponent, RowArgs } from '@progress/kendo-angular-grid';
import { SortDescriptor } from '@progress/kendo-data-query';

import { BsDropdownDirective } from 'ngx-bootstrap/dropdown';
import { PERFECT_SCROLLBAR_CONFIG, PerfectScrollbarConfigInterface } from 'ngx-perfect-scrollbar-portable';
import PerfectScrollbar from 'perfect-scrollbar';
import { Subscription } from 'rxjs';
import {
  ColumnDisplayType,
  DropdownEvent,
  ICombinedColumn,
  IDefaultColumn,
  InvokeAction,
  MouseClick,
  TableItem,
  UserPreferencesService,
} from 'shared-code-lib';
import { ContextMenuComponent } from '../../context-menu/context-menu.component';

declare const $: any;

@Component({
  selector: 'app-table',
  templateUrl: './table.component.html',
  styleUrls: ['./table.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class TableComponent implements OnInit, AfterViewInit, OnChanges, DoCheck, OnDestroy {
  @ViewChild('tableWrapper', { static: false })
  tableWrapper: ElementRef;
  @ViewChild('grid', { static: true })
  grid: GridComponent;

  @Output() onRender = new EventEmitter<GridComponent>();
  @Output() onSelectionChanged = new EventEmitter<void>();
  @Output() onInvokeAction = new EventEmitter<InvokeAction>();
  @Output() onSort = new EventEmitter<SortDescriptor>();
  @Output() onSaveColumns = new EventEmitter<Array<IDefaultColumn>>();
  @Output() onDeleteIconClicked = new EventEmitter<InvokeAction>();
  @Output() reload = new EventEmitter<void>();
  @Output() expandedItemsChange = new EventEmitter<{ id: string }[]>();

  _items: Array<TableItem>;

  @Input() set items(val: Array<TableItem>) {
    this._items = val;
    this.cdr.detectChanges();
  }

  get items(): Array<TableItem> {
    return this._items;
  }

  _columns: Array<ICombinedColumn> = [];
  @Input() set columns(value: Array<ICombinedColumn>) {
    this._columns = value;
    this.loadColumnsWidth();
    this.handleStretchableColumns();
  }
  get columns(): Array<ICombinedColumn> {
    return this._columns;
  }
  @Input() expandableDetail: boolean = false;
  @Input() multiselect: boolean = false;
  @Input() sort: SortDescriptor[];
  @Input() scrollable = 'scrollable';
  @Input() deleteIcon: boolean = false;
  @Input() deleteIconTooltip: string = '';
  @Input() showCheckboxes: boolean = true;
  @Input() reorderable: boolean = false;
  @Input() supportActions: boolean = true;
  @Input() preferencesKey: string;
  @Input() expandedItems: { id: string }[] = [];
  @Input() suppressScrollX = false;
  @Input() suppressScrollY = false;

  allItemsSelected = false;
  showSelectAllCheckbox: boolean = false;

  contextMenu: ContextMenuComponent;
  private actionsDropdown: BsDropdownDirective;
  actionsColumnWidth = 50;
  selectionColumnWidth: 40 | 68 = 40;
  stretchableColumnMinimumWidth: number = 50;

  ps1: PerfectScrollbar = null;

  subscriptions = new Subscription();

  constructor(
    private renderer: Renderer2,
    private translate: TranslateService,
    private userPreferencesService: UserPreferencesService,
    @Inject(PERFECT_SCROLLBAR_CONFIG) private globalScrollbarConfig: PerfectScrollbarConfigInterface,
    private _elementRef: ElementRef,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    this.toggleScrollBarOnEmptyTable();
    if (this.ps1) this.ps1.update();
    if (changes.items && changes.items.previousValue) {
      this.allItemsSelected = this.items.length !== 0 && this.items.every((i) => i.selected);
      this.showSelectAllCheckbox = this.allItemsSelected;
    }

    if (changes.columns && changes.columns.previousValue && this.items) {
      this.items = this.items.map((i) => new TableItem(i.data, this.columns, this.translate));
    }

    if (changes.preferencesKey) this.loadColumnsWidth();

    if (changes.columns || changes.preferencesKey || changes.items) this.handleStretchableColumns();

    if (this.items) {
      this.items.forEach((item, index) => {
        if (item.selected) {
          item.showCheckbox = true;
          this.addRowBackground(index);
        } else {
          this.removeRowBackground(index);
        }

        this.sortActions(item);
      });
    }

    this.cdr.detectChanges();

    if (this.ps1) this.ps1.update();
  }

  ngOnInit(): void {
    if (this.preferencesKey) this.loadColumnsWidth();
    this.items.forEach((item) => this.sortActions(item));

    this.subscriptions.add(this.onSaveColumns.subscribe((_) => this.ps1.update()));
  }

  ngAfterViewInit() {
    const scrollbarConfig = {
      ...this.globalScrollbarConfig,
      suppressScrollX: this.suppressScrollX,
      suppressScrollY: this.suppressScrollY,
    };
    const element = this._elementRef.nativeElement.querySelector('.k-grid-content');

    this.ps1 = new PerfectScrollbar(element, scrollbarConfig);

    this.toggleScrollBarOnEmptyTable();

    const that = this;
    this.onRender.emit(this.grid);

    $(this.grid.wrapper.nativeElement).on('mousedown', 'tr[role="row"]', function (e) {
      if (!that.supportActions) return true;

      if (e.which === MouseClick.Right) {
        if (that.contextMenu) {
          if (that.actionsDropdown) {
            that.actionsDropdown.hide();
          }

          const index = $(this).attr('data-kendo-grid-item-index');
          that.contextMenu.open(
            e,
            that.items[index],
            index,
            [],
            `action-dropdown-${that.getDataItemId(that.items[index])}`
          );

          const isExpanded = that.isExpandedRow(this);

          const isNested = !!$(this).parents('.k-detail-row').length;

          if (isExpanded || isNested) {
            e.stopPropagation();
            return;
          }

          that.selectedOneRow(+index);
        }
      }
    });

    $(this.grid.wrapper.nativeElement).on('mouseenter', 'tr[role="row"]', function (e) {
      const isExpanded = that.isExpandedRow(this);

      const isNested = !!$(this).parents('.k-detail-row').length;

      if (isExpanded || isNested) {
        e.stopPropagation();
        return;
      }

      const index = $(this).attr('data-kendo-grid-item-index');
      if (!index) {
        that.showSelectAllCheckbox = true;
        return;
      }

      const isVisibleCheckbox = that.items[index].showCheckbox;
      if (isVisibleCheckbox) return;

      that.items[index].showCheckbox = true;
    });

    $(this.grid.wrapper.nativeElement).on('mouseleave', 'tr[role="row"]', function (e) {
      const index = $(this).attr('data-kendo-grid-item-index');

      if (!index && that.allItemsSelected) return;

      if (!index && !that.allItemsSelected) {
        that.showSelectAllCheckbox = false;
        return;
      }

      const isSelected = that.items[index].selected;

      if (isSelected) return;

      that.items[index].showCheckbox = false;
    });

    // double click
    $(this.grid.wrapper.nativeElement).on('dblclick', 'tr[role="row"]', function (e) {
      const index = $(this).attr('data-kendo-grid-item-index');
      if (!that.items[index]?.data?.defaultAction) return;
      that.onActionInvoked(that.items[index].data?.defaultAction, that.items[index], index);
    });

    $(this.grid.wrapper.nativeElement).bind('contextmenu', function (e) {
      e.preventDefault();
    });

    this.handleStretchableColumns();

    this.cdr.detectChanges();
  }

  ngDoCheck(): void {
    if (this.ps1) this.ps1.update();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  handleStretchableColumns(): void {
    if (!this.grid || !this.grid.header) return;
    if (this.multiselect && this.expandableDetail) this.selectionColumnWidth = 68;

    const masterHeaderTable = $(this._elementRef.nativeElement).find('.k-grid-header-wrap table');

    let availableWidth =
      this._elementRef.nativeElement.offsetWidth > masterHeaderTable.width()
        ? this._elementRef.nativeElement.offsetWidth
        : masterHeaderTable.width();
    availableWidth -= this.actionsColumnWidth + this.selectionColumnWidth;

    this.columns.forEach((column) => {
      if (!column.stretch) {
        availableWidth -= column.width;
      }
    });

    const stretchableCols = this.columns.filter((column) => column.stretch);

    const avColsWidth = availableWidth / stretchableCols.length;
    const stretchColWidth =
      avColsWidth > this.stretchableColumnMinimumWidth ? avColsWidth : this.stretchableColumnMinimumWidth;
    stretchableCols.forEach((column) => {
      column.width = stretchColWidth;
    });

    this.grid.columns.forEach((column: any) => {
      const col = this.columns.find((c) => c.id === column.field);
      if (!col) return;
      column.width = col.width;
    });
  }

  onRenderContextMenu(contextMenu: ContextMenuComponent): void {
    this.contextMenu = contextMenu;
  }

  onSelectAction(event: InvokeAction): void {
    this.onActionInvoked(event.action, event.item, event.index);
  }

  onOpenChange(event: DropdownEvent, rowIndex: number): void {
    const isOpened = event.isOpened;

    const isNested = !!$(this._elementRef.nativeElement).find('.action-caret').parents('.k-detail-row').length;
    if (isOpened && !isNested) {
      this.selectedOneRow(rowIndex);
    }

    this.actionsDropdown = isOpened ? event.dropdown : null;
  }

  onColumnReorder(columnReorderEvent: ColumnReorderEvent): void {
    if (columnReorderEvent.newIndex == 0 && (this.multiselect || this.expandableDetail)) {
      this.grid.reorderColumn(columnReorderEvent.column, columnReorderEvent.newIndex + 1, {
        before: true,
      });
      columnReorderEvent.preventDefault();
      return;
    }

    if (columnReorderEvent.newIndex > this.columns.length - (this.multiselect || this.expandableDetail ? 0 : 1)) {
      this.grid.reorderColumn(columnReorderEvent.column, columnReorderEvent.newIndex - 1, {
        before: false,
      });

      columnReorderEvent.preventDefault();
      return;
    }

    const oldIndex = columnReorderEvent.oldIndex - (this.multiselect || this.expandableDetail ? 1 : 0);
    const newIndex = columnReorderEvent.newIndex - (this.multiselect || this.expandableDetail ? 1 : 0);
    const reorderedColumn: ICombinedColumn = this.columns[oldIndex];

    this.columns.splice(oldIndex, 1);
    this.columns.splice(newIndex, 0, reorderedColumn);

    this.onSaveColumns.emit(
      this.columns.map<IDefaultColumn>((c) => {
        return { id: c.id, width: c.width, stretch: c.stretch };
      })
    );

    if (this.preferencesKey) this.saveColumnsWidth();
  }

  onColumnResize(event: any): void {
    this.toggleScrollBarOnEmptyTable();

    let isLast = false;
    event.forEach((item) => {
      const index = this.columns.findIndex((col) => col.id === item.column.field);
      if (index == -1) return;
      const col = this.columns[index];

      col.width = item.newWidth;
      col.stretch = isLast = index == this.columns.length - 1;
    });

    this.handleStretchableColumns();

    this.onSaveColumns.emit(
      this.columns.map<IDefaultColumn>((c) => {
        return { id: c.id, width: c.width, stretch: c.stretch };
      })
    );

    if (this.preferencesKey) this.saveColumnsWidth();
  }

  saveColumnsWidth = (): void => {
    this.columns.forEach((c) =>
      this.userPreferencesService.setPreference(`grid-${this.preferencesKey}-${c.id}-width`, c.width)
    );
  };

  loadColumnsWidth = (): void => {
    const hasStretchable = this.columns.some((a) => a.stretch);

    for (let i = 0; i < this.columns.length; i++) {
      const savedColumnWidth = this.userPreferencesService.getPreference(
        `grid-${this.preferencesKey}-${this.columns[i].id}-width`
      );

      if (!savedColumnWidth) continue;

      this.columns[i].width =
        savedColumnWidth > this.stretchableColumnMinimumWidth ? savedColumnWidth : this.stretchableColumnMinimumWidth;

      this.columns[i].stretch = this.columns[i].stretch || (!hasStretchable && i == this.columns.length - 1);
    }
  };

  onSorting(sd: SortDescriptor[]): void {
    this.onSort.emit(sd[0]);
  }

  onActionInvoked = (action: any, item: TableItem, index: number): void => {
    this.onInvokeAction.emit({ action, item: item.data, index: index });
  };

  onDefaultAction = (ia: InvokeAction): void => {
    this.onInvokeAction.emit(ia);
  };

  selectAll = (selected: boolean): void => {
    this.items.forEach((item, index) => {
      item.selected = selected;
      item.showCheckbox = selected;

      if (selected) {
        this.addRowBackground(index);
      } else {
        this.removeRowBackground(index);
      }
    });

    this.onSelectionChanged.emit();
  };

  itemSelected = (rowIndex: number): void => {
    this.allItemsSelected = this.items.every((i) => i.selected);
    this.showSelectAllCheckbox = this.allItemsSelected;
    this.toggleRowBackground(rowIndex);
    this.onSelectionChanged.emit();
  };

  toggleRowBackground(index) {
    const row = $(this._elementRef.nativeElement).find(
      `tr[data-kendo-grid-item-index="${index}"]:not(.k-detail-row):not(.k-detail-row tr)`
    )[0];
    if (row) row.classList.toggle('selected-row');
  }

  addRowBackground(index) {
    const row = $(this._elementRef.nativeElement).find(
      `tr[data-kendo-grid-item-index="${index}"]:not(.k-detail-row):not(.k-detail-row tr)`
    )[0];
    if (row) row.classList.add('selected-row');
  }

  removeRowBackground(index) {
    const row = $(this._elementRef.nativeElement).find(
      `tr[data-kendo-grid-item-index="${index}"]:not(.k-detail-row):not(.k-detail-row tr)`
    )[0];
    if (row) row.classList.remove('selected-row');
  }

  selectedOneRow = (rowIndex: number) => {
    this.items.forEach((item, i) => {
      if (i === rowIndex) {
        item.selected = true;
        item.showCheckbox = true;
        this.addRowBackground(i);
      } else {
        item.selected = false;
        item.showCheckbox = false;
        this.removeRowBackground(i);
      }
    });

    this.allItemsSelected = false;
    this.showSelectAllCheckbox = false;
    this.onSelectionChanged.emit();
  };

  isExpandedRow = (row) => {
    const rowClass = $(row).attr('class');
    const isExpanded = rowClass && rowClass.includes('k-detail-row');
    return isExpanded;
  };

  onClickDetails = (item: TableItem, rowIndex: number, tab = ''): void => {
    item.detailsTab = tab;
    item.expanded = !item.expanded;

    let expandedItems = this.items
      .filter((i) => i.expanded)
      .map((i) => ({
        id: `${i.data.id}`,
      }));
    this.expandedItemsChange.emit(expandedItems);

    if (item.expanded) {
      this.renderer.addClass(this.tableWrapper.nativeElement, 'show-details');
    } else {
      const hasExpandedItems = this.items.some((loopItem) => loopItem.expanded === true);
      if (!hasExpandedItems) {
        this.renderer.removeClass(this.tableWrapper.nativeElement, 'show-details');
      }
    }
  };

  getDataItemId = (dataItem: any): string => {
    for (const c of this.columns) {
      if (c.displayType == ColumnDisplayType.ActionLink) {
        return dataItem.data.values[c.id];
      }
    }

    return '';
  };

  deleteIconClicked(item: TableItem, index: number) {
    this.onDeleteIconClicked.emit({ action: 'delete', item: item, index: index });
  }

  onReload = (): void => {
    this.reload.emit();
  };

  getHeaderStyle = (c: ICombinedColumn) => {
    if (c.displayType == ColumnDisplayType.Money || c.displayType == ColumnDisplayType.TextRight)
      return { 'justify-content': 'flex-end' };

    return {};
  };

  isDetailsExpanded = (args: RowArgs): boolean => args.dataItem.expanded;

  onCellClick(event: any): void {
    const item = event.dataItem;
    const e: MouseEvent = event.originalEvent;
    let multipleItemsSelected = false;

    for (let i = 0; i < this.items.length; i++) {
      if (this.items[i].selected && i !== event.rowIndex) {
        multipleItemsSelected = true;
        break;
      }
    }

    if (
      (item.selected && !multipleItemsSelected) ||
      (e.target as any).parentElement.classList.contains('check-label')
    ) {
      return;
    }

    if (!e.ctrlKey) {
      this.items.forEach((innerItem, index) => {
        if (innerItem.selected) {
          innerItem.selected = false;
          innerItem.showCheckbox = false;
          this.toggleRowBackground(index);
        }
      });
    }

    item.selected = !item.selected;
    item.showCheckbox = item.selected;
    this.itemSelected(event.rowIndex);
  }

  toggleScrollBarOnEmptyTable() {
    if (this.items.length == 0) {
      this._elementRef.nativeElement.querySelector('tbody')?.classList.add('tbody-height');
    } else {
      this._elementRef.nativeElement.querySelector('tbody')?.classList.remove('tbody-height');
    }
  }

  sortActions = (item: TableItem): void => {
    if (item?.data?.allowedActions?.some((action) => action.order != 0)) {
      item?.data?.allowedActions?.sort((x, y) => {
        if (x.order == y.order) return x.name.localeCompare(y.name);

        return x.order - y.order;
      });
    }
  };
}
