import {
  ApplicationRef,
  ComponentFactoryResolver,
  EmbeddedViewRef,
  EventEmitter,
  Injectable,
  Injector,
  Output,
} from '@angular/core';
import { Subscription } from 'rxjs';

import { DateRangePickerComponent } from './date-range-picker.component';
import { DateRangePicker, IDateRangePickerData } from './date-range-picker.model';

@Injectable({
  providedIn: 'root',
})
export class DateRangePickerService {
  componentRef: any;

  subscriptions: Array<Subscription> = [];

  @Output() onDateRangeSelected = new EventEmitter<IDateRangePickerData>();
  @Output() onDateRangeSelectionCanceled = new EventEmitter<IDateRangePickerData>();

  constructor(
    private componentFactoryResolver: ComponentFactoryResolver,
    private injector: Injector,
    private appRef: ApplicationRef
  ) {}

  show(dateRangePicker: DateRangePicker) {
    if (this.componentRef) {
      this.hide();
    }

    const componentFactory = this.componentFactoryResolver.resolveComponentFactory(dateRangePicker.component);

    this.componentRef = componentFactory.create(this.injector);
    const drp: DateRangePickerComponent = <DateRangePickerComponent>this.componentRef.instance;
    if (!drp) return;

    drp.data = dateRangePicker.data;
    this.subscriptions.push(drp.onHide.subscribe(() => this.hide()));
    this.subscriptions.push(
      drp.onDateRangeSelected.subscribe((value: string) =>
        this.onDateRangeSelected.emit({ value: value, idPrefix: dateRangePicker.data.idPrefix } as IDateRangePickerData)
      )
    );

    this.appRef.attachView(this.componentRef.hostView);

    const domElem = (this.componentRef.hostView as EmbeddedViewRef<any>).rootNodes[0] as HTMLElement;
    document.body.appendChild(domElem);
  }

  hide() {
    this.subscriptions.forEach((x) => x.unsubscribe());
    this.subscriptions = [];

    if (!this.componentRef) return;
    this.appRef.detachView(this.componentRef.hostView);
    this.componentRef.destroy();
    this.componentRef = null;

    this.onDateRangeSelectionCanceled.emit();
  }
}
