import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import {
  DeliveryFormats,
  DeliveryFormatsDataSource,
  FieldDefinition,
  MetaDataCollection,
  MetaDataType,
} from 'shared-code-lib';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-create-routingsheet',
  templateUrl: './create-routingsheet.component.html',
  styleUrls: ['./create-routingsheet.component.scss'],
})
export class CreateRoutingsheetComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  fieldDocumentName: FieldDefinition;
  fieldDeliveryFormat: FieldDefinition;

  finalFormCode = 'pdf';
  documentName = '';

  constructor(
    private translateService: TranslateService,
    private userStateService: UserStateService,
    private spinnerService: SpinnerStateService,
    private sharedDataService: SharedDataService
  ) {}

  ngOnInit(): void {
    this.createFields();
  }

  createFields = (): void => {
    const allowedFormats = DeliveryFormats.All()
      .filter((f) => !f.singlePage)
      .map((f) => f.finalformcode);

    this.fieldDeliveryFormat = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('workflow-step.delivery-format'),
      placeholder: '',
      datasource: new DeliveryFormatsDataSource(this.translateService, this.userStateService, allowedFormats),
      required: true,
    });

    this.fieldDocumentName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('step-deliver-to-email.document-name'),
      placeholder: this.translateService.instant('create-routingsheet.document-name-placeholder'),
      required: false,
      substitutable: false,
    });
  };

  close = (): void => {
    this.closeModal.emit();
  };

  create = (): void => {
    this.spinnerService.show(this.translateService.instant('create-routingsheet.creating'), this.getSpinnerElement());

    const items = [];

    const args = new MetaDataCollection();
    args.set(
      'document-name',
      this.documentName
        ? this.documentName
        : this.translateService.instant('create-routingsheet.document-name-placeholder')
    );
    args.set('final-form-code', this.finalFormCode);

    if (this.sharedDataService.extraParameters != null)
      args.set('FolderId', this.sharedDataService.extraParameters.folderId);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      items,
      args,
      this.onCreateSucceeded
    );
  };

  onCreateSucceeded = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.create-routing-sheet-modal .nsm-content') as HTMLElement;
  }
}
