import {
  Component,
  OnInit,
  Output,
  EventEmitter,
  ViewEncapsulation,
  Input,
  OnDestroy,
  ViewChild,
  ElementRef,
} from '@angular/core';
import { ApiService } from '../../services/api.service';

import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { Subscription } from 'rxjs';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { TranslateService } from '@ngx-translate/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { NgxFileDropEntry, FileSystemFileEntry } from 'ngx-file-drop';
import * as moment from 'moment';
import { FieldDefinition, MetaDataCollection, MetaDataType } from 'shared-code-lib';

@Component({
  selector: 'app-import-workflow',
  templateUrl: './import-workflow.component.html',
  styleUrls: ['./import-workflow.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class ImportWorkflowComponent implements OnInit, OnDestroy {
  @ViewChild('spinnerElement', { static: true })
  spinnerElement: { nativeElement: HTMLElement };
  @Input() title: string;
  @Input() executeAction: boolean = true;
  @Input() modalId: string = 'ImportWorkflowModal';
  @Output() closeModal = new EventEmitter();
  @ViewChild(PerfectScrollbarDirective, { static: true }) directiveRef?: PerfectScrollbarDirective;
  @ViewChild('input') input: ElementRef;

  subscriptions = new Subscription();
  modal: NgxSmartModalComponent;
  importErrors = [];
  supportedFileTypes = '.exp';
  formData = {
    overwrite: false,
    attachedItems: [],
    prefix: '',
    suffix: `_${moment(new Date()).format('YYYY-MM-DD')}`,
  };

  prefixField: FieldDefinition;
  suffixField: FieldDefinition;
  base64FileData: any;

  constructor(
    public api: ApiService,
    public ngxSmartModalService: NgxSmartModalService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    protected translateService: TranslateService
  ) {
    this.title = sharedDataService.action?.name;
    this.modal = this.ngxSmartModalService.getModal(this.modalId);
  }

  ngOnInit(): void {
    this.prefixField = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('import-workflow.prefix'),
      placeholder: '',
      required: false,
    });

    this.suffixField = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('import-workflow.suffix'),
      placeholder: '',
      required: false,
    });
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  close = (): void => {
    this.modal?.close();
    this.closeModal.emit();
  };

  onFileSelected = (event: any): void => {
    this.formData.attachedItems = [];
    if (!event.target.files || !event.target.files.length) return;

    for (const file of event.target.files) {
      this.formData.attachedItems.push(file);
    }

    if (this.formData.attachedItems.length) {
      this.readFile(this.formData.attachedItems[0]);
    }

    event.target.value = null;
  };

  deleteItem = (file: File): void => {
    const index = this.formData.attachedItems.indexOf(file);
    if (index != -1) this.formData.attachedItems.splice(index, 1);
    this.directiveRef.update();
    this.base64FileData = null;
  };

  public dropped(files: NgxFileDropEntry[]) {
    this.formData.attachedItems = [];
    for (const droppedFile of files) {
      // Is it a file?
      if (droppedFile.fileEntry.isFile) {
        const fileEntry = droppedFile.fileEntry as FileSystemFileEntry;
        fileEntry.file((file: File) => {
          this.formData.attachedItems.push(file);
          this.readFile(file);
        });

        break;
      }
    }
  }

  save = (): void => {
    this.spinnerService.show(
      this.translateService.instant('import-workflow.importing'),
      this.spinnerElement.nativeElement
    );

    const items = [];
    const args = new MetaDataCollection();

    args.set('file', this.base64FileData);
    args.set('overwrite', this.formData.overwrite.toString());
    args.set('prefix', this.formData.prefix);
    args.set('suffix', this.formData.suffix);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      items,
      args,
      this.onImportSucceeded,
      this.onImportFailed
    );
  };

  readFile = (file: File): void => {
    this.base64FileData = null;
    const reader = new FileReader();
    reader.onload = (event: any) => {
      this.base64FileData = event.target.result.split(',')[1];
    };

    reader.readAsDataURL(file);
  };

  onImportFailed = (errors: any[]): void => {
    console.log('onImportFailed', errors);
    this.spinnerService.hide();
    this.importErrors = errors.map((e) => e);
  };

  onImportSucceeded = (): void => {
    this.spinnerService.hide();
    this.close();
  };
}
