import { Injectable } from '@angular/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { Icons } from './alert-default/alert-default.component';

@Injectable({
  providedIn: 'root',
})
export class AlertsService {
  private onClose: Function;

  constructor(private ngxSmartModal: NgxSmartModalService) {}

  public success = (
    title: string,
    message: string,
    autoClose: boolean,
    { onClose, buttonText, customClass, showIcon = Icons.None }: ISuccessOptions = {}
  ): void => {
    this.onClose = onClose;
    const data = {
      title: title,
      message: message,
      autoClose: autoClose,
      buttonText: buttonText,
      close: this.close,
      timeoutInSeconds: 10,
      type: 'success',
      customClass: customClass,
      showIcon: showIcon,
    };
    this.ngxSmartModal.setModalData(data, 'alertsModal', true);
    this.ngxSmartModal.open('alertsModal');
  };

  close = (): void => {
    if (this.onClose) this.onClose();
    this.ngxSmartModal.setModalData({}, 'alertsModal', true);
    this.ngxSmartModal.close('alertsModal');
  };
}

interface ISuccessOptions {
  onClose?: Function;
  buttonText?: string;
  customClass?: string;
  showIcon?: Icons;
}
