import {
  Annotation,
  IMetaData,
  Location,
  MetaData,
  MetaDataCollection,
  MetaDataCollectionDictionary,
  MetaDataDefinition,
  MetaDataType,
  MetaDataValidity,
} from 'shared-code-lib';
import { UserStateService } from './../services/user-state.service';
import { InteractiveWorkflowStep } from './workflow-step';

export interface IWorkItem {
  id: string;
  tenantId: string;
  workflowId: string;
  workflowStepId: string;
  owner: string;
  metaData: MetaDataCollectionDictionary;
  files: Array<string>;
  annotations: Annotation[];
}

export class WorkItem {
  public metadata: MetaDataCollection;
  public annotations: Annotation[];

  public id: string;
  public tenantId: string;
  public workflowId: string;
  public workflowStepId: string;
  public owner: string;
  public mdc: MetaDataCollectionDictionary;
  public files: Array<string>;

  constructor(wi: IWorkItem) {
    this.id = wi.id;
    this.tenantId = wi.tenantId;
    this.workflowId = wi.workflowId;
    this.workflowStepId = wi.workflowStepId;
    this.owner = wi.owner;
    this.files = wi.files;

    this.metadata = new MetaDataCollection(wi.metaData);
    this.annotations = wi.annotations.map((a) => Annotation.create(a));
  }

  public static create(workflowId: string) {
    return new WorkItem({
      id: '',
      tenantId: '',
      workflowId: workflowId,
      workflowStepId: '',
      owner: '',
      metaData: {},
      files: [],
      annotations: [],
    });
  }

  public setMetaData(name: string, value: string, validity: MetaDataValidity, location?: Location) {
    this.metadata.set(name, value, validity, location);
  }

  public getMetaData(name: string): IMetaData {
    return this.metadata.get(name);
  }

  public serializable = (): IWorkItem => {
    return {
      id: this.id,
      tenantId: this.tenantId,
      workflowId: this.workflowId,
      workflowStepId: this.workflowStepId,
      owner: this.owner,
      files: this.files,
      metaData: this.metadata.serializable(),
      annotations: this.annotations.map((x) => x.serializable()),
    };
  };

  public getOverallValidity = (step: InteractiveWorkflowStep, userState: UserStateService): MetaDataValidity => {
    if (this.hasValidityOf(MetaDataValidity.notValid, step, userState)) {
      return MetaDataValidity.notValid;
    }
    if (this.hasValidityOf(MetaDataValidity.suspicious, step, userState)) {
      return MetaDataValidity.suspicious;
    }
    if (this.hasValidityOf(MetaDataValidity.unknown, step, userState)) {
      return MetaDataValidity.unknown;
    }

    return MetaDataValidity.valid;
  };

  private hasValidityOf(
    validity: MetaDataValidity,
    step: InteractiveWorkflowStep,
    userState: UserStateService
  ): boolean {
    if (!step || !step.metaDataIds) {
      return false;
    }

    for (const id of step.metaDataIds) {
      const metaDataDefinition = userState.findMetaDataById(id) as MetaDataDefinition;
      if (!metaDataDefinition) continue;

      const metaData = this.getMetaData(metaDataDefinition.name);
      if (metaDataDefinition.type === MetaDataType.LineItems) {
        if (metaData) {
          const configuredLineItemFieldNames = metaDataDefinition.lineItemConfigurations.map((item) =>
            userState.findMetaDataById(item.metaDataId).name.toLowerCase()
          );
          const hasValidity = (metaData.value as Array<MetaDataCollection>).some((collection) => {
            return collection.metadata
              .filter((itemCell: MetaData) => configuredLineItemFieldNames.includes(itemCell.name.toLowerCase()))
              .some((itemCell: MetaData) => itemCell.validity === validity);
          });
          if (hasValidity) {
            return hasValidity;
          }
        }
      } else {
        if (metaData) {
          if (metaData.validity === validity) {
            return true;
          }
        } else {
          if (validity === MetaDataValidity.unknown) {
            return true;
          }
        }
      }
    }

    return false;
  }
}
