import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';
import { WindowRef } from 'shared-code-lib';

@Injectable({
  providedIn: 'root',
})
export class DocumentEventsService {
  private _documentClickSubject = new Subject<MouseEvent>();
  private _documentKeyDownSubject = new Subject<KeyboardEvent>();

  onDocumentClick = this._documentClickSubject.asObservable();
  onDocumentKeyDownSubject = this._documentKeyDownSubject.asObservable();

  constructor(private windowRef: WindowRef) {
    this.windowRef.nativeWindow.addEventListener('click', (event: MouseEvent) => {
      this._documentClickSubject.next(event);
    });

    this.windowRef.nativeWindow.addEventListener('keydown', (event: KeyboardEvent) => {
      this._documentKeyDownSubject.next(event);
    });
  }
}
