import { Schema, schema as defaultSchema } from '@progress/kendo-angular-editor';
import { StyleType, TemplateStyle } from './../../../../views/admin-olc/models/template';
import {
  createBlockStyleNode,
  createOlcConditionalContentNode,
  createOlcVariableNode,
  preNode,
  hrNode,
  updatedDiv,
  updatedImageNode,
  updatedListItem,
} from './nodes';
import { createInlineStyleMark } from './marks';

interface ConditionalContentEntry {
  groupName: string;
  className: string;
}

export const createEditorSchema = (
  isOlcTed: boolean,
  olcTedStyles: TemplateStyle[],
  conditionalContents: ConditionalContentEntry[]
): Schema => {
  let newNodes = defaultSchema.spec.nodes;

  const tableNodeSpec = newNodes.get('table');
  tableNodeSpec.content = 'table_row*';

  newNodes = newNodes.update('table', tableNodeSpec);

  if (!isOlcTed) {
    const newSchema = new Schema({
      marks: defaultSchema.spec.marks,
      nodes: newNodes,
    });

    return newSchema;
  }

  newNodes = newNodes.addToEnd('olcVariable', createOlcVariableNode());

  newNodes = conditionalContents.reduce((nodes, c) => {
    const conditionalContentNode = createOlcConditionalContentNode(c.className);
    nodes = nodes.addToEnd(c.groupName, conditionalContentNode);
    return nodes;
  }, newNodes);

  newNodes = olcTedStyles
    .filter((s) => s.elementType === StyleType.Block)
    .reduce((nodes, s) => {
      const isParagraph = /^p$/i.test(s.element);
      const isHeading = /^h[1-6]$/i.test(s.element);
      const isDiv = /^div$/i.test(s.element);
      const isPre = /^pre$/i.test(s.element);

      if (isParagraph || isHeading || isDiv || isPre) return nodes;

      const blockFormatNode = createBlockStyleNode(s);
      nodes = nodes.addToEnd(s.id, blockFormatNode);
      return nodes;
    }, newNodes);

  newNodes = newNodes.update('div', updatedDiv);
  newNodes = newNodes.update('list_item', updatedListItem);
  newNodes = newNodes.update('image', updatedImageNode);
  newNodes = newNodes.remove('code_block');
  newNodes = newNodes.addToEnd('pre', preNode);
  newNodes = newNodes.update('horizontal_rule', hrNode);

  const inlineStylesMarks = olcTedStyles
    .filter((s) => s.elementType === StyleType.Inline)
    .reduce((marks, s) => {
      // prevent marks duplications
      if (marks[s.element]) return marks;

      marks = { ...marks, ...createInlineStyleMark(s) };
      return marks;
    }, {});

  // prepend new marks at start to take higher rank
  const newMarks = defaultSchema.spec.marks.prepend({
    ...inlineStylesMarks,
  });

  const newSchema = new Schema({
    marks: newMarks,
    nodes: newNodes,
  });

  return newSchema;
};
