import { Formatter } from 'shared-code-lib';

export class TestFormattingParameters {
  public value: string;
  public formatters: Array<Formatter>;

  serializable() {
    return {
      value: this.value,
      formatters: this.formatters,
    };
  }
}

export interface IFormatResult {
  ruleName: string;
  input: string;
  output: string;
  status: string;
}

export interface IFormattingResults {
  formattedValue: string;
  results: Array<IFormatResult>;
}

export class FormatResult {
  public ruleName: string;
  public input: string;
  public output: string;
  public status: string;

  constructor(initializer: IFormatResult) {
    this.ruleName = initializer.ruleName;
    this.input = initializer.input;
    this.output = initializer.output;
    this.status = initializer.status;
  }
}

export class FormattingResults {
  public formattedValue: string;
  public results: Array<FormatResult>;

  constructor(initializer: IFormattingResults) {
    this.formattedValue = initializer.formattedValue;
    this.results = initializer.results.map((r) => new FormatResult(r));
  }
}
