import { Component, EventEmitter, OnDestroy, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import { RolePermissions, Tab } from 'shared-code-lib';
import { CustomProperty } from '../../InterFAX/Models/admin';
import { InboundDocument, SharePermissions } from '../../InterFAX/Models/inbound';
import { InterFAXService } from '../../services/interfax.service';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-interfax-document-properties-modal',
  templateUrl: './interfax-document-properties-modal.component.html',
  styleUrls: ['./interfax-document-properties-modal.component.scss'],
})
export class InterfaxDocumentPropertiesModalComponent implements OnInit, OnDestroy {
  @ViewChild('spinnerElement', { static: true })
  spinnerElement;
  @ViewChild(PerfectScrollbarDirective, { static: false }) scrollbar: PerfectScrollbarDirective;

  @Output() closeModal = new EventEmitter();

  title: string;

  show = false;
  errors = new Array<string>();

  activeTab = 'general';
  tabs = new Array<Tab>();

  document: InboundDocument;

  customProperties: CustomProperty[];
  tags: string[];

  subscriptions = new Subscription();

  constructor(
    private translateService: TranslateService,
    public sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private interfaxService: InterFAXService,
    private toastrService: ToastrService,
    private userStateService: UserStateService
  ) {}

  ngOnInit(): void {
    this.title = this.translateService.instant('interfax-queue.document-properties-title');
    this.load();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  load = (): void => {
    this.spinnerService.show(this.translateService.instant('Common.Loading'), this.spinnerElement.nativeElement);

    this.subscriptions.add(
      this.interfaxService.getInboundDocument(
        this.sharedDataService.extraParameters.details.documentID,
        this.documentLoaded,
        this.failed
      )
    );
  };

  documentLoaded = (d: InboundDocument): void => {
    d.labels = this.getUniqueLabels(d.labels);
    this.document = d;

    this.subscriptions.add(this.interfaxService.getCustomProperties(this.propertiesLoaded, this.failed));
  };

  failed = (err): void => {
    this.spinnerService.hide();
    this.toastrService.error(err);
  };

  propertiesLoaded = (cps: CustomProperty[]): void => {
    this.customProperties = cps;
    if (!this.canShowTagsTab()) {
      this.loaded();
      return;
    }

    this.subscriptions.add(this.interfaxService.getLabels(this.tagsLoaded, this.failed));
  };

  tagsLoaded = (tags: string[]): void => {
    this.tags = this.getUniqueLabels(tags);

    this.loaded();
  };

  getUniqueLabels(labels: string[]) {
    return [...new Set(labels.map((t) => t.trim()).filter((t) => t))];
  }

  loaded = (): void => {
    this.createTabs();
    this.spinnerService.hide();
    this.show = true;
  };

  save = (): void => {
    this.spinnerService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);
    if (this.canShowTagsTab()) {
      this.subscriptions.add(
        this.interfaxService.setLabels(
          this.tags,
          () => {
            this.subscriptions.add(this.interfaxService.setInboundDocument(this.document, this.saved, this.saveFailed));
          },
          this.saveFailed
        )
      );
    } else {
      this.subscriptions.add(this.interfaxService.setInboundDocument(this.document, this.saved, this.saveFailed));
    }
  };

  saved = (): void => {
    this.spinnerService.hide();
    this.toastrService.success(this.translateService.instant('interfax-queue.document-properties-success'));
    this.sharedDataService.actionHandler.reload.emit(true);
    this.close();
  };

  saveFailed = (errs: any[]): void => {
    this.spinnerService.hide();
    this.errors = errs;
    this.scrollbar.scrollToTop();
    this.updateScrollbar();
  };

  close = (): void => {
    this.show = false;
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  createTabs = (): void => {
    if (this.document.permissionsAllowed(SharePermissions.Edit)) {
      this.addTab('general');
    }

    if (this.canShowTagsTab()) this.addTab('tags');

    if (
      this.document.permissionsAllowed(SharePermissions.Edit) &&
      this.customProperties &&
      this.customProperties.length
    ) {
      this.addTab('custom-properties');
    }

    if (
      this.userStateService.hasRolePermission(RolePermissions.INTERFAX_PERMISSIONS_ALLOWMANUALSHARE) &&
      this.document.permissionsAllowed(SharePermissions.Share)
    ) {
      this.addTab('sharing');
    }

    if (this.sharedDataService?.extraParameters?.details.barcodes?.length) this.addTab('barcodes');
  };

  canShowTagsTab = () => this.document.permissionsAllowed(SharePermissions.Edit);

  addTab = (tab: string): void => {
    this.tabs.push(new Tab(tab, this.translateService.instant(`interfax-queue.document-properties-tab-${tab}`)));
  };

  activateTab = (tab: string): void => {
    this.activeTab = tab;
    this.updateScrollbar();
  };

  updateScrollbar() {
    this.scrollbar.update();
  }

  onScrollEnded(edge: 'start' | 'end') {
    if (edge === 'start') {
      this.scrollbar.scrollToTop();
    } else {
      this.scrollbar.scrollToBottom();
    }
  }
}
