import { jsPDF } from 'jspdf';

export const createPDFFromImages = (imagesURLS: string[], name: string, compressPdf: boolean) => {
  const doc = new jsPDF('p', 'pt', 'letter', compressPdf);
  const width = doc.internal.pageSize.width;
  const height = doc.internal.pageSize.height;

  imagesURLS.forEach((image, index) => {
    doc.addImage(image, 'PNG', 0, 0, width, height, '', compressPdf ? 'FAST' : undefined);
    if (index !== imagesURLS.length - 1) doc.addPage();
  });

  return new File([doc.output('blob')], name, {
    type: 'application/pdf',
  });
};
