import { Injectable } from '@angular/core';
import { IAlert } from '../models/alert';
import { ApiService } from './api.service';

@Injectable({
  providedIn: 'root',
})
export class ProductsAlertsService {
  constructor(private api: ApiService) {}

  get(successCallBack: (alerts: IAlert[]) => void, failureCallBack: (err: any) => void): void {
    this.api.queryServer(`alerts/`).subscribe(successCallBack, failureCallBack);
  }
}
