import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { AuthService } from 'shared-code-lib';
import { EventTypes, FolderViewEvent, ItemTypes } from './../models/folder-view-event';
import { Workflow } from './../models/workflow';
import { WorkflowFolder } from './../models/workflow-folder';
import { ActivityEventsService } from './activity-events-service';
import { HydraApiService } from './hydra-api.service';
import { UserStateService } from './user-state.service';

@Injectable({
  providedIn: 'root',
})
export class CaptureStatusService extends ActivityEventsService {
  constructor(
    userStateService: UserStateService,
    hydraApi: HydraApiService,
    translate: TranslateService,
    toastr: ToastrService,
    authService: AuthService
  ) {
    super(userStateService, hydraApi, translate, toastr, authService);
  }

  statusTextNoItems: string = 'Document_Capture.status-tooltip-none';
  statusTextOneItem: string = 'Document_Capture.status-tooltip-one';
  statusTextCount: string = 'Document_Capture.status-tooltip-count';
  eventId: string = 'folderview';

  loadWorkflows = (): void => {
    this.hydraApi.getUserWorkflows(this.workflowsLoaded, this.workflowsFailedLoad);
  };

  workflowsLoaded = (workflows: Workflow[]): void => {
    this.workflows = workflows;

    for (let workflow of workflows) {
      this.hydraApi.getWorkflowNonInteractiveFolders(
        workflow.id,
        (folders: WorkflowFolder[]): void => {
          this.workflowFolderLoaded(workflow, folders);
        },
        this.workflowFolderFailedLoad
      );
    }
  };

  processStatusEvent = (folderViewEvent: FolderViewEvent) => {
    if (folderViewEvent.itemType == ItemTypes.item) return;

    if (folderViewEvent.eventType === EventTypes.added) {
      this.addEventItem(folderViewEvent);
    } else if (folderViewEvent.eventType === EventTypes.updated) {
      this.updateEventItem(folderViewEvent);
    } else if (folderViewEvent.eventType === EventTypes.deleted) {
      this.deleteEventItem(folderViewEvent);
    }
  };

  private addEventItem = (fve: FolderViewEvent): void => {};

  private updateEventItem = (fve: FolderViewEvent): void => {
    let folder = this.findFolder(fve.data.Id);
    if (folder == null) {
      let parent = this.findFolder(fve.data.ParentId);
      if (parent == null) return;

      parent.folders.push(
        new WorkflowFolder(
          fve.data.Id,
          fve.data.ParentId,
          parent,
          fve.data.WorkflowStepId,
          fve.data.Name,
          fve.data.ItemCount,
          [],
          []
        )
      );
    } else {
      folder.itemCount = fve.data.ItemCount;
    }
  };

  private deleteEventItem = (fve: FolderViewEvent): void => {};
}
