export class Subtitution {
  value: string;
  id: string;
  subEl: HTMLElement;
  constructor(value: string, subEl: HTMLElement) {
    this.value = value;
    this.id = (new Date().getTime() + Math.floor(Math.random() * 100) + 1).toString();
    this.subEl = subEl;
  }
}

export enum NodeType {
  Element = 1,
  Attr = 2,
  Text = 3,
}
