import { Component, Input, ViewEncapsulation, OnInit, Output, EventEmitter, OnChanges } from '@angular/core';
import { ToastrService } from 'ngx-toastr';

import { TranslateService } from '@ngx-translate/core';
import {
  IFieldOptions,
  FieldDefinition,
  ICascadingFieldOptions,
  CascadingFieldOptions,
  ColumnValue,
} from './../../models/field-definition';
import { MetaDataCollection, MetaDataValidity } from './../../models/metadata';
import { FixedDataSource } from '../../models/fixed-datasource';
import { CascadingOptionsFieldDataSource } from '../../models/metadata-cascading-options-datasource';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { Log } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { IFindMetaDataById, IMetaDataValidator } from '../../interop/MetaDataService';
import { BlurEvent } from '../../models/field-events';
import { MetaDataDefinition, MetaDataType } from '../../models/metadata-definition';
import { Subscription } from 'rxjs';
import { DelayService } from '../../utils/delay.service';

@Component({
  selector: 'app-cascading-lists',
  templateUrl: './cascading-lists.component.html',
  styleUrls: ['./cascading-lists.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class CascadingListsComponent implements OnInit, OnChanges {
  @Input() context: any;
  @Input() value: string;
  @Input() field: FieldDefinition;
  @Input() disabled: boolean;
  @Input() validity: number;
  @Input() fieldTabIndex = 0;
  @Input() findMetaDataService: IFindMetaDataById;
  @Input() metaDataValidator: IMetaDataValidator;
  @Input()
  set focused(value: boolean) {
    this.focusedListIndex = value ? 0 : -1;
  }
  @Input()
  set setValue(value: string) {
    this.setValues();
  }
  @Input() metaDataCollection: MetaDataCollection;
  @Output() fieldFocus = new EventEmitter();
  @Output() fieldBlur = new EventEmitter<BlurEvent>();
  @Output() fieldOnTab = new EventEmitter<any>();
  @Output() fieldOnShiftTab = new EventEmitter<any>();
  @Output() fieldChanged = new EventEmitter<BlurEvent>();
  @Output() overallValidityChanged = new EventEmitter();

  isCurrentField: boolean;
  metaDataValidity = MetaDataValidity;

  options: ICascadingFieldOptions[] = [];
  fields: FieldDefinition[] = [];
  values: string[] = [];
  datasources: FixedDataSource[] = [];
  triggeringEvents: boolean;
  focusedListIndex = -1;
  subscriptions: Subscription = new Subscription();
  validatingFieldsCount: number = 0;

  constructor(
    private spinner: SpinnerStateService,
    private translate: TranslateService,
    private delayService: DelayService,
    private toastr: ToastrService
  ) {}

  ngOnInit() {
    this.field.datasource.getItems('', '', this.itemsLoaded, this.itemsLoadFailed);

    if (this.metaDataValidator) {
      this.subscriptions.add(
        this.metaDataValidator.onStartMetaDataValidation.subscribe((metadataId) => {
          if (this.options.find((x) => x.metaDataId == metadataId) == null) return;
          this.validatingFieldsCount++;
        })
      );

      this.subscriptions.add(
        this.metaDataValidator.onCompleteMetaDataValidation.subscribe((metadataId) => {
          if (this.options.find((x) => x.metaDataId == metadataId) == null) return;
          this.validatingFieldsCount--;
          if (this.validatingFieldsCount == 0) this.delayService.execute(() => this.overallValidityChanged.emit(), 100);
        })
      );
    }
  }

  ngOnDestroy() {
    this.subscriptions.unsubscribe();
  }

  itemsLoaded = (fields: IFieldOptions[]): void => {
    this.options = fields.map((f) => f as CascadingFieldOptions);
    this.setValues();
    this.loadData();
  };

  itemsLoadFailed = (error): void => {
    this.toastr.error(this.translate.instant('fields.items-load-failed'));
    Log.error('fields.items-load-failed', error);
  };

  ngOnChanges(changes: any) {
    this.setValues();
  }

  setValues = (): void => {
    if (this.triggeringEvents) return;

    if (!this.metaDataCollection || !this.metaDataCollection.metadata) {
      this.clearAllValues();
      return;
    }

    for (let i = 0; i < this.options.length; i++) {
      const md = this.metaDataCollection.get(
        this.findMetaDataService.findMetaDataById(this.options[i].metaDataId).name
      );
      if (!md) {
        this.values[i] = '';
        continue;
      }

      if (this.values[i] == md.value) continue;
      this.values[i] = md.value ? md.value.toString() : '';
      if (i < this.options.length - 1 && this.values[i] != '') this.loadOptions(i + 1);
    }
  };

  clearAllValues = (): void => {
    for (let i = 0; i < this.options.length; i++) {
      this.values[i] = '';
    }
  };

  loadData = (): void => {
    for (let i = 0; i < this.options.length; i++) {
      this.datasources[i] = new FixedDataSource(new Array<IFieldOptions>());
      if (i == 0) this.loadOptions(i);
      this.values.push('');
      this.fields.push(
        new FieldDefinition({
          type: MetaDataType.List,
          label: this.getFieldLabelById(this.options[i].metaDataId),
          placeholder: this.getFieldLabelById(this.options[i].metaDataId),
          required: true,
          datasource: this.datasources[i],
          fireChangeEventIfSameValue: false,
        })
      );
    }

    this.initializeOptionsValues();
  };

  initializeOptionsValues = (): void => {
    if (!this.metaDataCollection) return;

    for (let i = 0; i < this.options.length; i++) {
      if (!this.metaDataCollection.get(this.findMetaDataService.findMetaDataById(this.options[i].metaDataId).name))
        this.setItemValue(this.options[i].metaDataId, '');
    }
  };

  setItemValue = (metaDataId: string, value: string): void => {
    this.metaDataCollection.set(
      this.findMetaDataService.findMetaDataById(metaDataId).name,
      value,
      MetaDataValidity.unknown
    );
  };

  getFieldLabelById = (id: string): string => {
    const metaData = this.findMetaDataService.findMetaDataById(id);
    if (!metaData) throw this.translate.instant('fields.datafield-not-exist');

    return this.translate.instant(metaData.label);
  };

  loadOptions = (levelIndex: number) => {
    this.spinner.show(this.translate.instant('fields.loading-cascading-options'), document.body);

    const filters: ColumnValue[] = [];
    for (let i = 0; i < levelIndex; i++) {
      filters.push(new ColumnValue(this.options[i].value.toString(), this.values[i]));
    }

    (this.field.datasource as CascadingOptionsFieldDataSource).getCascadingOptions(
      this.options[levelIndex].name,
      this.options[levelIndex].value.toString(),
      levelIndex == 0 ? [] : filters,
      (values: IFieldOptions[]) => {
        this.onOptionsLoadSucceeded(this.datasources[levelIndex], values);
      },
      this.onOptionsLoadFailed
    );
    return;
  };

  onOptionsLoadSucceeded = (datasource: FixedDataSource, cells: IFieldOptions[]) => {
    this.spinner.hide();
    const tempFields: Array<IFieldOptions> = [];
    for (let i = 0; i < cells.length; i++) {
      tempFields.push({
        name: cells[i].name,
        value: cells[i].value,
      });
    }

    datasource.updateOptions(tempFields);
  };

  onOptionsLoadFailed = () => {
    this.spinner.hide();
  };

  onTabKey(index: number, event: Event) {
    if (this.focusedListIndex < this.options.length - 1) {
      event.preventDefault();
      event.stopPropagation();
      this.focusedListIndex = index + 1;
      return;
    }

    this.focusedListIndex = -1;

    this.fieldOnTab.emit(this.createBlurEvent(index, this.values[index]));
  }

  onShiftTabKey(index: number, event: Event) {
    if (this.focusedListIndex > 0) {
      event.preventDefault();
      event.stopPropagation();
      this.focusedListIndex = -1;
      return;
    }

    this.focusedListIndex = index - 1;

    this.fieldOnTab.emit(this.createBlurEvent(index, this.values[index]));
  }

  onFieldChanged = (index, value): void => {
    if (this.values[index] == value) return;
    this.triggeringEvents = true;
    this.fieldChanged.emit(this.createBlurEvent(index, value));
    const nextIndex = index + 1;

    if (nextIndex < this.options.length) {
      this.datasources[nextIndex].updateOptions([]);
      this.setItemValue(this.options[nextIndex].metaDataId, '');

      this.onFieldChanged(nextIndex, '');
    }

    this.delayService.execute(() => {
      if (index < this.options.length - 1 && this.values[index] != '') this.loadOptions(index + 1);
      this.triggeringEvents = false;
    }, 1);
  };

  onFieldBlur = (index, value): void => {
    if (this.values[index] == value) return;
    this.triggeringEvents = true;
    this.fieldBlur.emit(this.createBlurEvent(index, value));

    const nextIndex = index + 1;

    if (index + 1 < this.options.length) {
      this.onFieldBlur(nextIndex, this.values[nextIndex]);
    }

    this.delayService.execute(() => (this.triggeringEvents = false), 1);
  };

  getValidity = (index: number): MetaDataValidity => {
    if (!this.metaDataCollection || !this.findMetaDataService) return null;
    const mdd = this.findMetaDataService.findMetaDataById(this.options[index].metaDataId) as MetaDataDefinition;
    if (!mdd) return null;
    const md = this.metaDataCollection.get(mdd.name);
    if (!md) return null;
    return md.validity;
  };

  createBlurEvent = (index: number, value: string): BlurEvent => {
    const event = new BlurEvent('', value);
    event.mdd = this.findMetaDataService.findMetaDataById(this.options[index].metaDataId) as MetaDataDefinition;

    return event;
  };
}
