import { ColumnDisplayType } from '../utils/enums';

export enum Operator {
  Equal = 0,
  NotEqual = 1,
}

export interface ICondition {
  operator: Operator;
  compareValue: number;
}
export interface IDynamicHeaderText {
  text: string;
  condition: ICondition;
}

export interface IColumn {
  displayType: ColumnDisplayType;
  headerImage: string;
  headerText: string;
  id: string;
  itemProperty: string;
  columnName: string;
  width: number;
  sortable: boolean;
  stretch: boolean;
  sortByFieldName: string;
  invertBooleanValue: boolean;
  displayArrayContent?: boolean;
  groupingFormat?: string;
  dynamicHeaderTexts?: IDynamicHeaderText[];
  shouldAppendHeaderToValue?: boolean;
  ignoreHeaderForEmptyValue?: boolean;
}

export interface IDefaultColumn {
  id: string;
  width: number;
  stretch: boolean;
}

export interface ICombinedColumn extends IDefaultColumn, IColumn {}
