import { Component, Input, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { CharactersValidator } from '../../utils/characters-validator.service';
import { Strings } from '../../utils/strings.service';
import { TextComponent } from '../text/text.component';
import { FieldDefinition } from './../../models/field-definition';

@Component({
  selector: 'app-integer',
  templateUrl: './integer.component.html',
  styleUrls: ['./integer.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class IntegerComponent extends TextComponent {
  @Input() field: FieldDefinition = undefined;
  @Input() cssClasses: string;
  @Input() fieldId: string = '';
  @Input() maxLength: number = undefined;
  @Input() autocomplete: string = 'on';

  constructor(translateService: TranslateService, private validator: CharactersValidator) {
    super(translateService);
  }

  onKeydown(event: KeyboardEvent): void {
    this.validator.allowIntegerOnly(event, this.field.allowNegativeNumbers);
    super.onKeydown(event);
  }

  onKeyup(event: KeyboardEvent): void {
    if (!this.field.allowNegativeNumbers && parseInt(this.value) < 0) this.value = '';
  }

  onMouseUp(e: any): boolean {
    this.handleValueChangeUsingArrows();
    return true;
  }

  handleValueChangeUsingArrows(): void {
    this.checkValues();
  }

  override onChangeValue(value: string): void {
    if (this.value == value) return;

    this.valueHasChanged = true;
    this.value = value ? value.toString() : '';

    if (this.field.hasValidation) {
      this.needToBeValidated = true;
      this.previousValidationState = this.validationState;
      this.validationState = null;
    }

    const trimmedString = this.normalizeValue(this.value);
    if (trimmedString != '-') this.valueChange.emit(trimmedString);
  }

  onBeforeBlurCheck(event: any): void {
    event.target.value = this.formatValue(event.target.value);
  }

  formatValue(value: string): string {
    let formatted = Number.parseInt(value).toString();
    return this.normalizeValue(formatted == 'NaN' ? '' : value);
  }

  override normalizeValue(value: string): string {
    if (Strings.isEmpty(value) || value === '-') return '';
    if (typeof value == 'number') value = (value as number).toString();

    const parsedLocaleNumber = this.parseLocaleNumber(value);
    const num = BigInt(parsedLocaleNumber);

    return num.toString();
  }
}
