import { Subject } from 'rxjs';

import { MetaDataCascadingOptionsDataSource, MetaDataDefinition } from './metadata-definition';
import { ColumnValue, IFieldDataSource, IFieldOptions } from './field-definition';
import { IMetaDataService } from '../interop/MetaDataService';

export class CascadingOptionsFieldDataSource implements IFieldDataSource {
  changed = new Subject<void>();
  itemsLoaded = new Subject<any>();

  getItemsRequestSent = false;
  loaded = false;
  loadedSuccessfully = false;
  loadingFailureError: any;
  items: Array<IFieldOptions> = [];
  dataSourceId: string;

  constructor(private mdd: MetaDataDefinition, private metaDataService: IMetaDataService) {
    const ds = <any>mdd.dataSource;
    if (ds.dataSet && ds.dataSet.length) {
      this.loaded = true;
      this.loadedSuccessfully = true;
      this.items = ds.dataSet;
      this.dataSourceId = (mdd.dataSource as MetaDataCascadingOptionsDataSource).dataSourceId;
    }
  }

  getItems(
    startsWith: string,
    currentValue: string,
    successCallBack: (items: Array<IFieldOptions>) => void,
    failureCallBack: (err: any) => void
  ): void {
    if (this.loaded) {
      this.getLoadedItems(startsWith, successCallBack, failureCallBack);
      return;
    }

    if (!this.getItemsRequestSent) {
      this.getItemsRequestSent = true;
      this.loadItems(startsWith, successCallBack, failureCallBack);
    } else {
      this.itemsLoaded.subscribe(() => {
        this.getLoadedItems(startsWith, successCallBack, failureCallBack);
        this.itemsLoaded.unsubscribe();
      });
    }
  }

  getCascadingOptions = (
    displayColumnId: string,
    valueColumnId: string,
    filters: ColumnValue[],
    successCallBack: (rows: IFieldOptions[]) => void,
    failureCallBack: (err: any) => void
  ): void => {
    this.metaDataService.getCascadingOptions(
      this.dataSourceId,
      displayColumnId,
      valueColumnId,
      filters,
      successCallBack,
      failureCallBack
    );
  };

  loadItems(
    startsWith: string,
    successCallBack: (items: Array<IFieldOptions>) => void,
    failureCallBack: (err: any) => void
  ) {}

  getLoadedItems(
    startsWith: string,
    successCallBack: (items: Array<IFieldOptions>) => void,
    failureCallBack: (err: any) => void
  ) {
    if (this.loadedSuccessfully) {
      successCallBack(this.getFilteredItems(startsWith));
      return;
    }

    failureCallBack(this.loadingFailureError);
  }

  getFilteredItems(startsWith: string): Array<IFieldOptions> {
    return this.items.filter((item) => item.name.toString().startsWith(startsWith));
  }
}
