import { Component, Input, OnInit } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { DelayService, FieldDefinition, MetaDataType } from 'shared-code-lib';
import { InboundDocument } from '../../../InterFAX/Models/inbound';

class TagObject {
  name: string;

  constructor(t: string) {
    this.name = t;
  }
}

@Component({
  selector: 'app-document-properties-tags',
  templateUrl: './document-properties-tags.component.html',
  styleUrls: ['./document-properties-tags.component.scss'],
})
export class DocumentPropertiesTagsComponent implements OnInit {
  @Input() document: InboundDocument;
  @Input() tags: string[];

  available: TagObject[];
  current: TagObject[];
  errors = [];

  fieldLabel: FieldDefinition;
  label = '';

  constructor(private translateService: TranslateService, private delay: DelayService) { }

  ngOnInit(): void {
    this.available = this.tags.map((t) => new TagObject(t));

    for (const label of this.document.labels) {
      if (this.available.findIndex((to) => to.name.localeCompare(label) == 0) != -1) continue;

      this.available.push(new TagObject(label));
    }

    this.available.sort((x, y) => x.name.localeCompare(y.name));

    this.current = this.available.filter(
      (to) => this.document.labels.findIndex((l) => l.localeCompare(to.name) == 0) != -1
    );

    this.errors = [];
    this.createFields();
  }

  currentChanged = (selected: TagObject[]): void => {
    this.current = selected;

    this.document.labels = this.current.map((c) => c.name);
  };

  onAddLabel = (label: string): void => {
    const labelTrimmed = label?.trim();
    this.delay.execute(() => {
      this.label = '';

      if (!labelTrimmed.length) return;
      this.errors = [];

      if (labelTrimmed.length > 50) {
        this.errors.push(this.translateService.instant('interfax-queue.long-tag'));
        return;
      }

      if (this.available.findIndex((to) => to.name.localeCompare(labelTrimmed) == 0) != -1) {
        this.errors.push(this.translateService.instant('interfax-queue.tag-exist'));
        return;
      }

      const tag = new TagObject(labelTrimmed);
      // force change angular to detect change
      this.available = this.available.map((x) => x);
      this.current = this.available.filter(
        (to) => this.current.findIndex((c) => c.name.localeCompare(to.name) == 0) != -1
      );

      this.available.push(tag);
      this.available.sort((x, y) => x.name.localeCompare(y.name));

      this.current.push(tag);
      this.tags.push(tag.name);
      this.document.labels.push(tag.name);
      this.errors = [];
    });
  };

  createFields = (): void => {
    this.fieldLabel = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('interfax-queue.add-label'),
      placeholder: this.translateService.instant('interfax-queue.add-label-placeholder'),
      required: false,
    });
  };
}
