import { Log } from './../../../../blocks/core/log';
import { Filter, IFilter } from './../../../../blocks/models/filter';

class OLCTemplateApprovalsFilterBySubmitter extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCUserComponent';
  }
}

class OLCTemplateApprovalsFilterByReviewer extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCUserComponent';
  }
}

class OLCTemplateApprovalsFilterByCreationDate extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCDateComponent';
  }
}

class OLCTemplateApprovalsFilterByStatus extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOLCTemplateVersionStatusComponent';
  }
}

export class OLCApprovalsFilters {
  public static Create = (filter: IFilter): Filter | null => {
    Log.enter('OLCApprovalsFilters.Create', filter);

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Approvals.Filters.FilterBySubmitterUser') {
      return new OLCTemplateApprovalsFilterBySubmitter(filter);
    }

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Approvals.Filters.FilterByReviewerUser') {
      return new OLCTemplateApprovalsFilterByReviewer(filter);
    }

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Approvals.Filters.FilterByCreationDate') {
      return new OLCTemplateApprovalsFilterByCreationDate(filter);
    }

    if (filter.id == 'BambaOLCTEDApplication-Upland.Bamba.OLCTed.Approvals.Filters.FilterByStatus') {
      return new OLCTemplateApprovalsFilterByStatus(filter);
    }

    return null;
  };
}
