import { Component, Input, OnInit, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import {
  IMetaData,
  MetaData,
  MetaDataCollection,
  MetaDataCollectionDictionary,
  MetaDataLineItems,
  MetaDataValueType,
  Tab,
} from 'shared-code-lib';
import { HydraApiService } from '../../services/hydra-api.service';
import { SystemMetaData } from '../../core/systemMetaData';

@Component({
  selector: 'app-workitem-properties',
  templateUrl: './workitem-properties.component.html',
  styleUrls: ['./workitem-properties.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class WorkitemPropertiesComponent implements OnInit {
  @Input() workitemId: string;
  details: any;
  activeTab = 'general';
  tabs = new Array<Tab>();
  isLoading = true;

  constructor(private toastr: ToastrService, private translate: TranslateService, private hydraApi: HydraApiService) {}

  ngOnInit() {
    this.tabs.push(new Tab('general', this.translate.instant('workitem-properties.general')));
    this.tabs.push(new Tab('datafields', this.translate.instant('workitem-properties.data-fields')));
    this.tabs.push(new Tab('journal', this.translate.instant('workitem-properties.journal')));

    this.loadWorkitemProperties();
  }

  activateTab = (view) => {
    this.activeTab = view;
  };

  loadWorkitemProperties() {
    this.isLoading = true;

    const itemId = `BambaSettingsApplication~BambaSettingsApplication-Upland.Bamba.Application.WorkItems.Folder~${this.workitemId}`;
    this.hydraApi.getItemDetails(itemId, this.workitemPropertiesLoaded, this.workitemPropertiesLoadFailed);
  }

  workitemPropertiesLoaded = (result: any) => {
    this.isLoading = false;
    this.removeEmptyLineItems(result);
    this.details = result.extendedDetails;

    const extractedDataFieldNames = [SystemMetaData.ExtractedDocumentData, SystemMetaData.ExtractedInvoiceData];

    for (const key in this.details.metaData) {
      const md = <MetaData>this.details.metaData[key];
      if (
        extractedDataFieldNames.findIndex(
          (extractedFieldName) => extractedFieldName.toLowerCase() === md.name.toLowerCase()
        ) !== -1
      ) {
        this.tabs.splice(2, 0, new Tab('extracteddata', this.translate.instant('workitem-properties.extracted-data')));
        break;
      }
    }
  };

  removeEmptyLineItems(result) {
    const metaDataCollection = result.extendedDetails.metaData as MetaDataCollectionDictionary;

    Object.entries(metaDataCollection).forEach(([metaDataName, metaDataValue]) => {
      if (metaDataValue.valueType !== MetaDataValueType.LineItems) return;

      metaDataCollection[metaDataName].value = (metaDataCollection[metaDataName].value as MetaDataCollection[]).filter(
        (mdCollection: MetaDataCollection) =>
          !Object.values(mdCollection).every(
            (md: IMetaData) => md.valueType === MetaDataValueType.String && md.value === ''
          )
      ) as MetaDataLineItems;
    });
  }

  workitemPropertiesLoadFailed = (err: any) => {
    this.isLoading = false;
    this.toastr.error(this.translate.instant('workitem-properties.loading-workitem-properties-failed'));
  };
}
