import { Component, Input, OnInit } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { EnumDataSource, FieldDefinition, MetaDataType } from 'shared-code-lib';
import {
  ITemplateVersion,
  VersionStatus,
} from '../../../../../../Bamba.Web/ClientApp/src/app/views/admin-olc/models/template';

@Component({
  selector: 'app-olc-template-version-details',
  templateUrl: './olc-template-version-details.component.html',
  styleUrls: ['./olc-template-version-details.component.scss'],
})
export class OlcTemplateVersionDetailsComponent implements OnInit {
  @Input() version: ITemplateVersion;
  fieldVersionId: FieldDefinition;
  fieldDateCreated: FieldDefinition;
  fieldComment: FieldDefinition;
  fieldUploadUsername: FieldDefinition;
  fieldStatus: FieldDefinition;

  get versionStatus() {
    return `${this.version.status}`;
  }
  set versionStatus(val: string) {
    this.version.status = Number(val);
  }

  constructor(private translate: TranslateService) {}

  ngOnInit() {
    this.fieldVersionId = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('admin-olc-templates.version-id-label'),
      placeholder: this.translate.instant('admin-olc-templates.version-id-placeholder'),
      required: false,
    });

    this.fieldDateCreated = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('admin-olc-templates.version-date-created-label'),
      placeholder: this.translate.instant('admin-olc-templates.version-date-created-placeholder'),
      required: false,
    });

    this.fieldUploadUsername = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('admin-olc-templates.version-upload-username-label'),
      placeholder: this.translate.instant('admin-olc-templates.version-upload-username-placeholder'),
      required: false,
    });

    this.fieldComment = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translate.instant('admin-olc-templates.version-comment-label'),
      placeholder: this.translate.instant('admin-olc-templates.version-comment-placeholder'),
      required: false,
    });

    this.fieldStatus = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translate.instant('admin-olc-templates.version-status-label'),
      placeholder: this.translate.instant('admin-olc-templates.version-status-placeholder'),
      datasource: new EnumDataSource(VersionStatus, 'OLCTemplateVersionStatusEnum', this.translate),
      required: false,
    });
  }

  updateVersionComment(comment: string) {
    this.version.comment = comment;
  }

  updateVersionStatus(status: string) {
    this.version.status = Number(status);
  }
}
