export enum Actions {
  Case = 'Upland.Hydra.Core.Formatters.Case',
  Prefix = 'Upland.Hydra.Core.Formatters.Prefix',
  Suffix = 'Upland.Hydra.Core.Formatters.Suffix',
  Replace = 'Upland.Hydra.Core.Formatters.Replace',
  Remove = 'Upland.Hydra.Core.Formatters.Remove',
  Insert = 'Upland.Hydra.Core.Formatters.Insert',
}

export class Action {
  public actionType: string;

  constructor(initializer: any) {}

  public static create = (initializer: any): Action => {
    if (!initializer) throw new Error('Invalid initializer');

    if (initializer.actionType == Actions.Case) return new Case(initializer);
    if (initializer.actionType == Actions.Prefix) return new Prefix(initializer);
    if (initializer.actionType == Actions.Suffix) return new Suffix(initializer);
    if (initializer.actionType == Actions.Replace) return new Replace(initializer);
    if (initializer.actionType == Actions.Remove) return new Remove(initializer);
    if (initializer.actionType == Actions.Insert) return new Insert(initializer);

    throw new Error(`invalid actionType ${initializer.actionType}`);
  };

  serializable(): any {
    return { actionType: this.actionType };
  }
}

export enum Casings {
  Upper = 0,
  Lower = 1,
}

export class Case extends Action {
  public casing = Casings.Upper;

  constructor(initializer: any) {
    super(initializer);

    this.actionType = Actions.Case;

    if (initializer) {
      if (initializer.casing === undefined) throw new Error('Invalid initializer.casing');

      this.casing = initializer.casing;
    }
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      casing: this.casing,
    };
  }
}

