export class Insert extends Action {
  public text = '';
  public position = 0;
  public untilLengthIs = 0;

  constructor(initializer: any) {
    super(initializer);

    this.actionType = Actions.Insert;

    if (initializer) {
      if (initializer.text === undefined) throw new Error('Invalid initializer.text');
      if (initializer.position === undefined) throw new Error('Invalid initializer.position');
      if (initializer.untilLengthIs === undefined) throw new Error('Invalid initializer.untilLengthIs');

      this.text = initializer.text;
      this.position = initializer.position;
      this.untilLengthIs = initializer.untilLengthIs;
    }
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      text: this.text,
      position: this.position,
      untilLengthIs: this.untilLengthIs,
    };
  }
}
