export class Replace extends Action {
  public target = '';
  public replaceWith = '';
  public ignoreCase = false;

  constructor(initializer: any) {
    super(initializer);

    this.actionType = Actions.Replace;

    if (initializer) {
      if (initializer.target === undefined) throw new Error('Invalid initializer.target');
      if (initializer.replaceWith === undefined) throw new Error('Invalid initializer.replaceWith');
      if (initializer.ignoreCase === undefined) throw new Error('Invalid initializer.ignoreCase');

      this.target = initializer.target;
      this.replaceWith = initializer.replaceWith;
      this.ignoreCase = initializer.ignoreCase;
    }
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      target: this.target,
      replaceWith: this.replaceWith,
      ignoreCase: this.ignoreCase,
    };
  }
}
