import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { AuthService, Feature, RolePermissions, UserPreferencesService } from 'shared-code-lib';
import { SpinnerStateService } from './spinner-state.service';
import { UserStateService } from './user-state.service';
import { VerticalNavService } from './vertical-nav.service';
import { ApiResult } from './models';

@Injectable({
  providedIn: 'root',
})
export class LoadAppStateService {
  constructor(
    private userState: UserStateService,
    private translate: TranslateService,
    private spinnerState: SpinnerStateService,
    private authService: AuthService,
    private toastr: ToastrService,
    private router: Router,
    private userPreferences: UserPreferencesService,
    private verticalNavService: VerticalNavService
  ) { }

  spinnerElement: HTMLElement;
  successCallBack: () => void;
  failureCallBack: (err: any) => void;
  metaDatafailureCallBack: (err: any) => void;

  reloadStateIfCurrentUserIs(userName: string, spinnerElement: HTMLElement = null, successCallBack: () => void = null, failureCallBack: (err: any) => void = null, metaDatafailureCallBack: (err: any) => void = null) {
    if (this.userState.interFAXUsername.toLowerCase() === userName.toLowerCase()) this.reloadState(spinnerElement, successCallBack, failureCallBack, metaDatafailureCallBack);
  }

  reloadState(spinnerElement: HTMLElement = null, successCallBack: () => void = null, failureCallBack: (err: any) => void = null, metaDatafailureCallBack: (err: any) => void = null) {
    this.authService.renewInterFaxUserSessionToken((result: ApiResult) => {
      this.authService.startSession(result.object.token);
      this.load(spinnerElement, successCallBack, failureCallBack, metaDatafailureCallBack);
    }, failureCallBack);
  }

  load(spe: HTMLElement, scb: () => void, fcb: (err: any) => void, mcb: (err: any) => void) {
    this.spinnerElement = spe;
    this.successCallBack = scb;
    this.failureCallBack = fcb;
    this.metaDatafailureCallBack = mcb;

    this.userState.loadUser(this.userLoaded, this.failureCallBack);
  }

  private userLoaded = () => {
    this.spinnerState.show(this.translate.instant('User.LoadingUserRoles'), this.spinnerElement);

    this.userState.loadUserRoles(this.userRolesLoaded, this.failureCallBack);
  };

  private userRolesLoaded = () => {
    if (this.userState.user.roleIds.length == 0) {
      this.showLoginError('Login.cannot-login-without-assigned-roles');
      this.router.navigateByUrl('/login');
      return;
    } else {
      if (!this.userState.hasRolePermission(RolePermissions.WORKFLOW_ENUMERATE)) {
        if (this.userState.hasOLCFeature()) {
          this.showLoginError('Login.cannot-login-without-workflow-permissions');
        } else {
          this.showLoginError('Login.cannot-login-without-workflow-permissions-olc');
        }

        this.router.navigateByUrl('/login');
        return;
      }

      if (!this.userState.hasRolePermission(RolePermissions.METADATA_ENUMERATE)) {
        this.showLoginError('Login.cannot-login-without-metadata-permissions');
        this.router.navigateByUrl('/login');
        return;
      }
    }

    this.userState.userChanged.next(this.userState.user);

    this.spinnerState.show(this.translate.instant('User.LoadingUserProducts'), this.spinnerElement);

    this.userState.loadUserProducts(this.userProductsLoaded, this.failureCallBack);
  };

  showLoginError(error: string) {
    this.spinnerState.hide();
    this.authService.logout();
    this.toastr.error(this.translate.instant(error));
  }

  private userProductsLoaded = () => {
    this.spinnerState.show(this.translate.instant('User.LoadingProfileDetails'), this.spinnerElement);
    this.userState.loadUserProfile(this.userProfileLoaded, this.metaDatafailureCallBack);
  };

  private userProfileLoaded = () => {
    this.spinnerState.show(this.translate.instant('User.LoadingProfileDetails'), this.spinnerElement);

    this.userPreferences.loadPreferences(this.userPreferencesLoaded, this.failureCallBack);
  };

  private userPreferencesLoaded = () => {
    this.spinnerState.show(this.translate.instant('User.LoadingUserFeatures'), this.spinnerElement);
    this.userState.loadUserFeatures(this.userFeaturesLoaded, this.failureCallBack);
    this.verticalNavService.initVerticalNavExpansion();
  };

  private userFeaturesLoaded = () => {
    this.spinnerState.show(this.translate.instant('User.LoadingMetaData'), this.spinnerElement);
    this.userState.loadUserMetaData(this.userMetaDataLoaded, this.metaDatafailureCallBack);
  };

  private userMetaDataLoaded = () => {
    this.spinnerState.show(this.translate.instant('User.LoadingAppIntegrations'), this.spinnerElement);
    this.userState.loadAppIntegrations(this.stateLoadCompleted, this.failureCallBack);
  };

  private stateLoadCompleted = () => {
    this.spinnerState.hide();
    this.successCallBack();
  };
}
