import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { UserPreferencesService } from '../../../../../../Bamba.Shared/src/services/user-preferences.service';

@Injectable({
  providedIn: 'root',
})
export class VerticalNavService {
  private readonly preferenceKey = 'left-nav-expanded';
  private toggleVerticalNavSubject = new BehaviorSubject(true);
  onToggleVerticalNav$ = this.toggleVerticalNavSubject.asObservable();

  constructor(private userPreferencesService: UserPreferencesService) {}

  initVerticalNavExpansion() {
    const leftNavExpandedPreference = this.userPreferencesService.getPreference(this.preferenceKey);
    this.toggleVerticalNav(leftNavExpandedPreference === null || leftNavExpandedPreference);
  }

  toggleVerticalNav(isExpanded: boolean, setPreference = false): void {
    this.toggleVerticalNavSubject.next(isExpanded);
    if (!setPreference) return;
    this.userPreferencesService.setPreference(this.preferenceKey, isExpanded);
  }
}
