import { Graphics } from '../utils/graphics';

export class Point {
  constructor(public x: number = 0, public y: number = 0) {}
}

export class Region {
  x: number;
  y: number;
  width: number;
  height: number;
}

export enum AnnotationTypes {
  Redaction = 1,
  Text = 2,
  Rectangle = 3,
  Circle = 4,
  Line = 5,
  Arrow = 6,
  FreeHand = 7,
  Highlight = 8,
  Stamp = 9,
}

export class AnnotationConfiguration {
  stamps: string[] = [];
  fontNames: string[] = [];
  fontSizes: number[] = [];
  lineWidths: number[] = [];
  highlightColors: string[] = [];

  constructor(initializer: any = null) {
    if (initializer) {
      if (initializer.stamps === undefined) throw new Error('invalid initializer.stamps');
      if (initializer.fontNames === undefined) throw new Error('invalid initializer.fontNames');
      if (initializer.fontSizes === undefined) throw new Error('invalid initializer.fontSizes');
      if (initializer.lineWidths === undefined) throw new Error('invalid initializer.lineWidths');
      if (initializer.highlightColors === undefined) throw new Error('invalid initializer.highlightColors');

      this.stamps = initializer.stamps;
      this.fontNames = initializer.fontNames;
      this.fontSizes = initializer.fontSizes;
      this.lineWidths = initializer.lineWidths;
      this.highlightColors = initializer.highlightColors;
    }
  }
}

export class Annotation {
  id: string;
  area: Region;
  annotationType: AnnotationTypes;
  pageNumber: number;
  startPoint: Point = new Point();
  endPoint: Point = new Point();
  isNew: boolean = false;
  pageWidth: number;
  pageHeight: number;
  order: number = 0;
  rotation: number;
  pageScale: number;

  get isRotated90Degrees(): boolean {
    return this.rotation == 90 || this.rotation == 270;
  }

  get startPointRotated(): Point {
    return this.rotatePoint(this.startPoint);
  }

  get endPointRotated(): Point {
    return this.rotatePoint(this.endPoint);
  }

  get areaRotated(): Region {
    const rotatedPosition = this.rotatePoint({ x: this.area.x, y: this.area.y }, this.area.width, this.area.height);

    return {
      x: rotatedPosition.x,
      y: rotatedPosition.y,
      width: this.isRotated90Degrees ? this.area.height : this.area.width,
      height: this.isRotated90Degrees ? this.area.width : this.area.height,
    };
  }

  rotatePoint = (point: Point, width: number = 0, height: number = 0, angle: number = 0): Point => {
    angle = angle === 0 ? this.rotation : angle;
    if (angle == 90) return { x: 1 - point.y - height, y: point.x };
    if (angle == 270) return { x: point.y, y: 1 - point.x - width };
    if (angle == 180) return { x: 1 - point.x - width, y: 1 - point.y - height };

    return { x: point.x, y: point.y };
  };

  constructor(initializer: any = null) {
    if (initializer) {
      if (initializer.id === undefined) throw new Error('invalid initializer.id');
      if (initializer.area === undefined) throw new Error('invalid initializer.area');
      if (initializer.startPoint === undefined) throw new Error('invalid initializer.startPoint');
      if (initializer.endPoint === undefined) throw new Error('invalid initializer.endPoint');
      if (initializer.annotationType === undefined) throw new Error('invalid initializer.annotationType');
      if (initializer.pageNumber === undefined) throw new Error('invalid initializer.pageNumber');
      if (initializer.pageWidth === undefined) throw new Error('invalid initializer.pageWidth');
      if (initializer.pageHeight === undefined) throw new Error('invalid initializer.pageHeight');
      if (initializer.order === undefined) throw new Error('invalid initializer.order');
      if (initializer.rotation === undefined) throw new Error('invalid initializer.rotation');
      if (initializer.pageScale === undefined) throw new Error('invalid initializer.pageScale');

      this.id = initializer.id;
      this.area = initializer.area;
      this.startPoint = initializer.startPoint;
      this.endPoint = initializer.endPoint;
      this.annotationType = initializer.annotationType;
      this.pageNumber = initializer.pageNumber;
      this.pageWidth = initializer.pageWidth;
      this.pageHeight = initializer.pageHeight;
      this.order = initializer.order;
      this.rotation = initializer.rotation;
      this.pageScale = initializer.pageScale;
      if (initializer.isNew) this.isNew = initializer.isNew;
    }
  }

  public static create = (initializer: any): Annotation => {
    if (initializer.annotationType == AnnotationTypes.Redaction) return new RedactionAnnotation(initializer);
    if (initializer.annotationType == AnnotationTypes.Text) return new TextAnnotation(initializer);
    if (initializer.annotationType == AnnotationTypes.Rectangle) return new RectangleAnnotation(initializer);
    if (initializer.annotationType == AnnotationTypes.Circle) return new CircleAnnotation(initializer);
    if (initializer.annotationType == AnnotationTypes.Line) return new LineAnnotation(initializer);
    if (initializer.annotationType == AnnotationTypes.Arrow) return new ArrowAnnotation(initializer);
    if (initializer.annotationType == AnnotationTypes.FreeHand) return new FreeHandAnnotation(initializer);
    if (initializer.annotationType == AnnotationTypes.Highlight) return new HighlightAnnotation(initializer);
    if (initializer.annotationType == AnnotationTypes.Stamp) return new StampAnnotation(initializer);

    throw new Error(`Invalid Annotation: ${initializer.annotationType}`);
  };

  public onMouseDown(point: Point) {
    this.startPoint = point;
  }

  public onMove(point: Point) {
    this.endPoint = point;
  }
  public calculateArea(width, height) {
    this.area.x = Math.min(this.startPoint.x, this.endPoint.x);
    this.area.y = Math.min(this.startPoint.y, this.endPoint.y);
    this.area.width = Math.abs(this.startPoint.x - this.endPoint.x);
    this.area.height = Math.abs(this.startPoint.y - this.endPoint.y);
  }

  public setLocation(x: number, y: number) {
    const xDiff = x - this.areaRotated.x;
    const yDiff = y - this.areaRotated.y;

    if (this.rotation == 90) {
      this.area.x = y;
      this.area.y = 1 - x - this.area.height;
    } else if (this.rotation == 270) {
      this.area.x = 1 - y - this.area.width;
      this.area.y = x;
    } else if (this.rotation == 180) {
      this.area.x = 1 - x - this.area.width;
      this.area.y = 1 - y - this.area.height;
    } else {
      this.area.x = x;
      this.area.y = y;
    }

    if (this.startPoint.x > this.endPoint.x) {
      this.startPoint.x = this.area.x + this.area.width;
      this.endPoint.x = this.area.x;
    } else {
      this.startPoint.x = this.area.x;
      this.endPoint.x = this.area.x + this.area.width;
    }
    if (this.startPoint.y > this.endPoint.y) {
      this.startPoint.y = this.area.y + this.area.height;
      this.endPoint.y = this.area.y;
    } else {
      this.startPoint.y = this.area.y;
      this.endPoint.y = this.area.y + this.area.height;
    }
  }

  public setSize(width: number, height: number) {
    const xDiff = width - this.areaRotated.width;
    const yDiff = height - this.areaRotated.height;

    if (this.isRotated90Degrees) {
      this.area.width = height;
      this.area.height = width;
    } else {
      this.area.width = width;
      this.area.height = height;
    }

    if (this.startPoint.x > this.endPoint.x) {
      this.startPoint.x = this.area.x + this.area.width;
      this.endPoint.x = this.area.x;
    } else {
      this.startPoint.x = this.area.x;
      this.endPoint.x = this.area.x + this.area.width;
    }
    if (this.startPoint.y > this.endPoint.y) {
      this.startPoint.y = this.area.y + this.area.height;
      this.endPoint.y = this.area.y;
    } else {
      this.startPoint.y = this.area.y;
      this.endPoint.y = this.area.y + this.area.height;
    }
  }

  public draw(ctx: any, width: number, height: number, isDrawing: boolean = false) {}

  public serializable(): any {
    return {
      id: this.id,
      pageNumber: this.pageNumber,
      area: this.area,
      annotationType: this.annotationType,
      startPoint: this.startPoint,
      endPoint: this.endPoint,
      pageWidth: this.pageWidth,
      pageHeight: this.pageHeight,
      order: this.order,
      rotation: this.rotation,
      pageScale: this.pageScale,
    };
  }
}

export class TextAnnotation extends Annotation {
  public text: string = '';
  public color: string = 'black';
  public fontName: string = 'Arial';
  public fontSize: number = 16;
  readonly topPadding = 7;
  readonly leftPadding = 7;
  readonly rightPadding = 7;

  constructor(initializer: any = null) {
    super(initializer);

    if (initializer) {
      if (initializer.text === undefined) throw new Error('invalid initializer.text');
      if (initializer.color === undefined) throw new Error('invalid initializer.color');
      if (initializer.fontName === undefined) throw new Error('invalid initializer.fontName');
      if (initializer.fontSize === undefined) throw new Error('invalid initializer.fontSize');

      this.text = initializer.text;
      this.color = initializer.color;
      this.fontName = initializer.fontName;
      this.fontSize = initializer.fontSize;
    }
  }

  public draw(ctx: any, width: number, height: number, isDrawing: boolean = false) {
    if (isDrawing) {
      Graphics.drawDottedRectangle(
        ctx,
        this.areaRotated.x * width,
        this.areaRotated.y * height,
        this.areaRotated.width * width,
        this.areaRotated.height * height
      );
      return;
    }
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      text: this.text,
      color: this.color,
      fontName: this.fontName,
      fontSize: this.fontSize,
    };
  }
}

export class ShapeAnnotation extends Annotation {
  color: string = 'black';
  thickness: number = 1;

  constructor(initializer: any = null) {
    super(initializer);

    if (initializer) {
      if (initializer.color === undefined) throw new Error('invalid initializer.color');
      if (initializer.thickness === undefined) throw new Error('invalid initializer.thickness');

      this.color = initializer.color;
      this.thickness = initializer.thickness;
    }
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      color: this.color,
      thickness: this.thickness,
    };
  }
}

export class RedactionAnnotation extends Annotation {
  public draw(ctx: any, width: number, height: number, isDrawing: boolean = false) {
    Graphics.fillRectangle(
      ctx,
      this.areaRotated.x * width,
      this.areaRotated.y * height,
      this.areaRotated.width * width,
      this.areaRotated.height * height
    );
  }
}

export class HighlightAnnotation extends Annotation {
  highlightColor: string = 'yellow';
  opacity: number = 0.3;

  constructor(initializer: any = null) {
    super(initializer);

    if (initializer) {
      if (initializer.highlightColor === undefined) throw new Error('invalid initializer.points');

      this.highlightColor = initializer.highlightColor;
    }
  }

  public draw(ctx: any, width: number, height: number, isDrawing: boolean = false) {
    Graphics.fillRectangle(
      ctx,
      this.areaRotated.x * width,
      this.areaRotated.y * height,
      this.areaRotated.width * width,
      this.areaRotated.height * height,
      this.highlightColor,
      this.opacity
    );
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      highlightColor: this.highlightColor,
    };
  }
}

export class RectangleAnnotation extends ShapeAnnotation {
  public draw(ctx: any, width: number, height: number, isDrawing: boolean = false) {
    Graphics.drawRectangle(
      ctx,
      this.areaRotated.x * width,
      this.areaRotated.y * height,
      this.areaRotated.width * width,
      this.areaRotated.height * height,
      this.color,
      this.thickness * (width / this.pageWidth)
    );
  }
}

export class CircleAnnotation extends ShapeAnnotation {
  public draw(ctx: any, width: number, height: number, isDrawing: boolean = false) {
    Graphics.drawCircle(
      ctx,
      this.areaRotated.x * width,
      this.areaRotated.y * height,
      this.areaRotated.width * width,
      this.areaRotated.height * height,
      this.color,
      this.thickness * (width / this.pageWidth)
    );
  }
}

export class LineAnnotation extends ShapeAnnotation {
  public draw(ctx: any, width: number, height: number, isDrawing: boolean = false) {
    Graphics.drawLine(
      ctx,
      this.startPointRotated.x * width,
      this.startPointRotated.y * height,
      this.endPointRotated.x * width,
      this.endPointRotated.y * height,
      this.color,
      this.thickness * (width / this.pageWidth)
    );
  }
}

export class ArrowAnnotation extends ShapeAnnotation {
  public calculateArea(width: any, height: any): void {
    const lineWidth = this.thickness * (width / this.pageWidth);
    const headLength = Math.max(10, Math.min(25, lineWidth * 5));
    let dx = this.endPoint.x - this.startPoint.x;
    let dy = this.endPoint.y - this.startPoint.y;
    const angle = Math.atan2(dy, dx);
    const arrow1X = this.endPoint.x * width - headLength * Math.cos(angle - Math.PI / 4);
    const arrow1Y = this.endPoint.y * height - headLength * Math.sin(angle - Math.PI / 4);
    const arrow2X = this.endPoint.x * width - headLength * Math.cos(angle + Math.PI / 4);
    const arrow2Y = this.endPoint.y * height - headLength * Math.sin(angle + Math.PI / 4);

    const xValues: number[] = [this.startPoint.x * width, this.endPoint.x * width, arrow1X, arrow2X];
    const yValues: number[] = [this.startPoint.y * height, this.endPoint.y * height, arrow1Y, arrow2Y];
    const minX = Math.min(...xValues) / width;
    const minY = Math.min(...yValues) / height;
    const maxX = Math.max(...xValues) / width;
    const maxY = Math.max(...yValues) / height;
    this.area.x = minX - 0.5 * (this.thickness / width);
    this.area.y = minY - 0.5 * (this.thickness / height);
    this.area.width = Math.abs(maxX - minX) + this.thickness / width;
    this.area.height = Math.abs(maxY - minY) + this.thickness / height;
  }
  public draw(ctx: any, width: number, height: number, isDrawing: boolean = false) {
    Graphics.drawArrow(
      ctx,
      this.startPointRotated.x * width,
      this.startPointRotated.y * height,
      this.endPointRotated.x * width,
      this.endPointRotated.y * height,
      this.color,
      this.thickness * (width / this.pageWidth)
    );
  }
}

export class FreeHandAnnotation extends ShapeAnnotation {
  points: Array<Point> = [];

  constructor(initializer: any = null) {
    super(initializer);

    if (initializer) {
      if (initializer.points === undefined) throw new Error('invalid initializer.points');

      this.points = initializer.points;
    }
  }

  public onMouseDown(point: Point) {
    this.points.push(point);
  }

  public onMove(point: Point) {
    this.points.push(point);
  }

  public calculateArea(width, height) {
    const minX = Math.min(...this.points.map((p) => p.x));
    const minY = Math.min(...this.points.map((p) => p.y));
    const maxX = Math.max(...this.points.map((p) => p.x));
    const maxY = Math.max(...this.points.map((p) => p.y));
    this.area.x = minX - 0.5 * (this.thickness / width);
    this.area.y = minY - 0.5 * (this.thickness / height);
    this.area.width = Math.abs(maxX - minX) + this.thickness / width;
    this.area.height = Math.abs(maxY - minY) + this.thickness / height;
  }

  public setLocation(x: number, y: number) {
    const dx = x - this.areaRotated.x;
    const dy = y - this.areaRotated.y;

    this.points = this.points.map((p) => {
      const rotatedPoint = this.rotatePoint(p);
      rotatedPoint.x += dx;
      rotatedPoint.y += dy;

      const unRotatedPoint = this.rotatePoint(rotatedPoint, 0, 0, 360 - this.rotation);
      return unRotatedPoint;
    });

    super.setLocation(x, y);
  }

  public setSize(width: number, height: number) {
    const widthRatio = width / this.areaRotated.width;
    const heightRatio = height / this.areaRotated.height;

    this.points = this.points.map((p) => {
      const rotatedPoint = this.rotatePoint(p);
      rotatedPoint.x = this.startPointRotated.x + (rotatedPoint.x - this.startPointRotated.x) * widthRatio;
      rotatedPoint.y = this.startPointRotated.y + (rotatedPoint.y - this.startPointRotated.y) * heightRatio;
      const unRotatedPoint = this.rotatePoint(rotatedPoint, 0, 0, 360 - this.rotation);
      return unRotatedPoint;
    });

    super.setSize(width, height);
  }

  public draw(ctx: any, width: number, height: number, isDrawing: boolean = false) {
    Graphics.drawFreeHand(
      ctx,
      this.points.map((x) => this.rotatePoint(x)),
      width,
      height,
      this.color,
      this.thickness * (width / this.pageWidth)
    );
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      points: this.points,
    };
  }
}

export class StampAnnotation extends Annotation {
  stamp: string;

  constructor(initializer: any = null) {
    super(initializer);

    if (initializer) {
      if (initializer.stamp === undefined) throw new Error('invalid initializer.stamp');

      this.stamp = initializer.stamp;
    }
  }

  public draw(ctx: any, width: number, height: number, isDrawing: boolean = false) {
    const position = this.rotatePoint({ x: this.area.x, y: this.area.y });
    Graphics.drawStamp(
      ctx,
      this.stamp,
      position.x * width,
      position.y * height,
      this.area.width * (this.isRotated90Degrees ? height : width),
      this.area.height * (this.isRotated90Degrees ? width : height),
      this.rotation
    );
  }

  public serializable(): any {
    const base = super.serializable();

    return {
      ...base,
      stamp: this.stamp,
    };
  }
}
