import { Component, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';

import {
  IMetaDataDefinition,
  MetaDataCollection,
  MetaDataValidity,
  OverallValidityStatusChangedData,
  ValidationInProgressChangedData,
  WorkflowMobileAction,
} from 'shared-code-lib';
import { DocumentCaptureService } from '../../../views/document-capture/capture-services';
import { CreateDocument } from '../../models/create-document';
import { WorkItem } from '../../models/work-item';
import { Workflow } from '../../models/workflow';
import { HydraApiService } from '../../services/hydra-api.service';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-submit-to-workflow',
  templateUrl: './submit-to-workflow.component.html',
  styleUrls: ['./submit-to-workflow.component.scss'],
})
export class SubmitToWorkflowComponent implements OnInit {
  @ViewChild(PerfectScrollbarDirective, { static: false }) directiveRef?: PerfectScrollbarDirective;
  @Output() closeModal = new EventEmitter();
  workflowsToSubmit: Workflow[];
  actions: WorkflowMobileAction[];
  selectedAction: WorkflowMobileAction;
  metaDataCollection: MetaDataCollection = new MetaDataCollection();
  overallValidityStatus: MetaDataValidity;
  validationInProgress: boolean;
  waitForValidation: boolean;
  loadingText: string;
  filesCount: number;
  filesSubmittedCount: number;
  filesFailedCount: number;
  errors: string[] = [];
  isLoading = true;
  private spinnerElement: HTMLElement;
  modalTitle: string;
  metadata: Array<IMetaDataDefinition> = [];

  constructor(
    private shared: SharedDataService,
    private toastr: ToastrService,
    private translate: TranslateService,
    private ngxSmartModalService: NgxSmartModalService,
    private spinner: SpinnerStateService,
    public hydraApi: HydraApiService,
    public userStateService: UserStateService,
    public capture: DocumentCaptureService
  ) {}

  ngOnInit() {
    this.modalTitle = `${this.translate.instant('myfiles.submit-to')} ${this.translate.instant('myfiles.workflow')}`;
    this.loadWorkflowsToSubmit();
    this.metadata = this.userStateService.user.metaData;
  }

  loadWorkflowsToSubmit() {
    this.isLoading = true;
    this.hydraApi.getWorkflowsUserCanSubmitTo(
      (workflows: Workflow[]) => {
        this.workflowsToSubmit = workflows.sort((a, b) => a.name.localeCompare(b.name));
        this.actions = this.workflowsToSubmit.map((w) => WorkflowMobileAction.createFrom(w));
        this.isLoading = false;
      },
      (err) => {
        this.toastr.error(this.translate.instant('myfiles.get-workflows-to-submit-failed'));
        this.isLoading = false;
      }
    );
  }

  handleAction(action: WorkflowMobileAction): void {
    if (action.prompts.length) {
      this.selectedAction = action;
      this.modalTitle = `${this.translate.instant('myfiles.submit-to')} ${action.title}`;
      this.directiveRef.update();
    } else {
      this.submitFilesToWorkflow(action);
    }
  }

  setOverallValidityStatus(event: OverallValidityStatusChangedData) {
    this.overallValidityStatus = event.overallValidity;
    this.metaDataCollection = event.metaDataCollection;
  }

  updateValidationInProgressState(event: ValidationInProgressChangedData) {
    this.validationInProgress = event.inProgress;
    const isInitialValidation = event.isInitial;

    if (isInitialValidation) {
      if (this.validationInProgress) {
        this.loadingText = this.translate.instant('workflow-indexing-panel.loading-defaults');
        const element = this.getSpinnerElement();
        this.spinner.show(this.loadingText, element);
        return;
      } else {
        this.spinner.hide();
        return;
      }
    }

    if (!this.waitForValidation || this.validationInProgress) return;

    this.waitForValidation = false;
    this.spinner.hide();
    this.submitToWorkflowWithPrompts();
  }

  submitToWorkflowWithPrompts() {
    if (this.validationInProgress) {
      this.waitForValidation = true;
      this.loadingText = this.translate.instant('workflow-indexing-panel.waiting');
      const element = this.getSpinnerElement();
      this.spinner.show(this.loadingText, element);
      return;
    }

    if (this.overallValidityStatus !== MetaDataValidity.valid) {
      this.toastr.error(this.translate.instant('workflow-indexing-panel.overall-validity-invalid'));
      return;
    }

    this.submitFilesToWorkflow(this.selectedAction);
  }

  submitFilesToWorkflow(action: WorkflowMobileAction) {
    const workflow: Workflow = this.workflowsToSubmit.find((w) => w.id === action.id);
    this.filesCount = 0;
    this.filesSubmittedCount = 0;
    this.filesFailedCount = 0;
    this.errors = [];

    const element = this.getSpinnerElement();
    this.spinner.show(this.translate.instant('myfiles.submitting-to-workflow'), element);

    this.filesCount = this.shared.extraParameters.items.length;

    this.shared.extraParameters.items.forEach((item) => {
      this.hydraApi.downloadDocument(
        item.id,
        (file: File) => {
          this.submitFileToWorkflow(file, item.name, workflow.id);
        },
        (err) => {
          this.filesFailedCount += 1;
          this.errors.push(`${this.translate.instant('myfiles.download-file-failed')} ${item.name}`);
          this.handleProcessedFilesCount();
        }
      );
    });
  }

  submitFileToWorkflow(file: File, fileName: string, workflowId: string) {
    const doc = new CreateDocument(file, fileName, '');

    const workItem = WorkItem.create(workflowId);
    workItem.metadata = this.metaDataCollection;

    this.hydraApi.createWorkItem(
      workItem,
      doc,
      (_workItem: WorkItem) => {
        this.filesSubmittedCount += 1;
        this.handleProcessedFilesCount();
      },
      (err) => {
        this.filesFailedCount += 1;

        const error =
          err && err.error
            ? `${fileName}: ${err.error}`
            : `${fileName}: ${this.translate.instant('Common.upload-failed')}`;
        this.toastr.error(error);

        this.errors.push(error);

        this.handleProcessedFilesCount();
      }
    );
  }

  handleProcessedFilesCount = () => {
    if (this.filesSubmittedCount + this.filesFailedCount !== this.filesCount) return;

    this.spinner.hide();
    this.ngxSmartModalService.getModal('submitToWorkflow').close();

    if (this.filesSubmittedCount === this.filesCount) {
      this.toastr.success(this.translate.instant('myfiles.submitted-successfully'));
      this.close();
      return;
    }

    this.errors.forEach((error) => {
      this.toastr.error(error);
    });
  };

  close = (): void => this.closeModal.emit();

  private getSpinnerElement(): HTMLElement {
    return this.spinnerElement
      ? this.spinnerElement
      : (document.querySelector('.submit-to-workflow-modal .nsm-content') as HTMLElement);
  }
}
