import { Component, Input, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { DateTimeFormat } from '../../core/dateTimeFormat';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-created-modified',
  templateUrl: './created-modified.component.html',
  styleUrls: ['./created-modified.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class CreatedModifiedComponent {
  @Input() id: string;
  @Input() createdDate: Date;
  @Input() modifiedDate: Date;

  constructor(private translate: TranslateService, private userStateService: UserStateService) {}

  getLocalDate = (date: Date): string => {
    if (!this.id) return this.translate.instant('general.date-not-applicable');

    return DateTimeFormat.getLocalDateTime(date, this.userStateService.getLocale());
  };
}
