import { ChangeDetectorRef, Component, EventEmitter, Input, Output, ViewEncapsulation } from '@angular/core';
import { cloneDeep } from 'lodash';
import { ICapture } from '../../models/scanner';
import { rotateBoundaries, rotateImage, swapBoundariesKeysBasedOnRotation } from '../../utils/image-rotation';

@Component({
  selector: 'app-document-scanner-editor',
  templateUrl: './document-scanner-editor.component.html',
  styleUrls: ['./document-scanner-editor.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class DocumentScannerEditorComponent {
  private _captures: ICapture[] = [];

  @Input()
  get captures(): ICapture[] {
    return this._captures;
  }
  set captures(captures: ICapture[]) {
    this._captures = captures?.length ? cloneDeep(captures) : [];
  }

  @Input() currentCaptureIndex = 0;

  @Output() cancel = new EventEmitter<void>();
  @Output() done = new EventEmitter<ICapture[]>();

  showCropCapture = false;

  get currentCapture() {
    const currentCapture = this.captures[this.currentCaptureIndex];
    return currentCapture ? currentCapture.capturedImage : '';
  }

  constructor(private cdr: ChangeDetectorRef) {}

  cancelEditing() {
    this.cancel.emit();
  }

  goToPreviousCapture() {
    this.currentCaptureIndex--;
    if (this.currentCaptureIndex > -1) return;
    this.currentCaptureIndex = this.captures.length - 1;
  }

  goToNextCapture() {
    this.currentCaptureIndex++;
    if (this.currentCaptureIndex < this.captures.length) return;
    this.currentCaptureIndex = 0;
  }

  async rotateCapture(index: number) {
    const currentCapture = this.captures[index];
    const angleInDegrees = 90;

    currentCapture.capturedImage = (await rotateImage(currentCapture.capturedImage, angleInDegrees)).rotatedImage;
    currentCapture.capturedImageBoundaries = swapBoundariesKeysBasedOnRotation(
      rotateBoundaries(
        currentCapture.capturedImageBoundaries,
        currentCapture.originalImageBoundaries.topRight.x,
        currentCapture.originalImageBoundaries.bottomRight.y,
        angleInDegrees
      ),
      angleInDegrees
    );

    const rotatedOriginalImage = await rotateImage(currentCapture.originalImage, angleInDegrees);
    currentCapture.originalImage = rotatedOriginalImage.rotatedImage;
    currentCapture.originalImageBoundaries = {
      topLeft: { x: 0, y: 0 },
      topRight: { x: rotatedOriginalImage.newWidth, y: 0 },
      bottomLeft: { x: 0, y: rotatedOriginalImage.newHeight },
      bottomRight: { x: rotatedOriginalImage.newWidth, y: rotatedOriginalImage.newHeight },
    };

    this.cdr.detectChanges();
  }

  openCropCapture() {
    this.showCropCapture = true;
  }

  closeCropCapture() {
    this.showCropCapture = false;
  }

  saveCroppedCapture(croppedCapture: ICapture) {
    this.captures[this.currentCaptureIndex] = croppedCapture;
    this.closeCropCapture();
  }

  onDone() {
    this.done.emit(this.captures);
  }
}
