import {
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnInit,
  Output,
  Renderer2,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';

import { TranslateService } from '@ngx-translate/core';
import { BsDropdownDirective } from 'ngx-bootstrap/dropdown';
import { CalculationsService, DelayService, DropdownEvent, Key } from 'shared-code-lib';

declare const $: any;

@Component({
  selector: 'action-dropdown',
  templateUrl: './action-dropdown.component.html',
  styleUrls: ['./action-dropdown.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class ActionDropdownComponent implements OnInit {
  @ViewChild('menu') menu: ElementRef;
  @ViewChild('menuParent', { static: true }) menuParent: ElementRef;
  @Input() listItems: ListItem[];
  @Input() actionPlaceHolder: any;
  @Input() isSelectable: boolean;
  @Input() extraClasses: string;
  @Input() onChangeAction: any;
  @Input() dropdownMenuExtraClass: string;
  @Input() actionDropTypeType: string;
  @Input() rowItem: any;
  @Input() idPrefix: string;
  @Input() minWidth: number = 0;
  @Input() minListWidth: number = 0;
  @Input() displayValue: boolean = true;
  @Input() displayHtmlValue: boolean = false;
  @Input() container = 'body';

  isOpened: boolean;
  dropdownSelectedItemIndex = -1;

  @Output() openChange = new EventEmitter<DropdownEvent>();

  constructor(
    private renderer: Renderer2,
    private translate: TranslateService,
    private calc: CalculationsService,
    private delay: DelayService
  ) {}

  ngOnInit() {
    if (this.actionPlaceHolder === null || this.actionPlaceHolder === undefined) {
      this.actionPlaceHolder = this.translate.instant('Table.Action');
    }

    if (this.isSelectable === null || this.isSelectable === undefined) this.isSelectable = false;
    if (this.extraClasses === null || this.extraClasses === undefined) this.extraClasses = '';

    if (this.dropdownMenuExtraClass === null || this.dropdownMenuExtraClass === undefined) {
      this.dropdownMenuExtraClass = '';
    }

    if (this.idPrefix === null || this.idPrefix === undefined) this.idPrefix = '';
  }

  onClickActionDropDown = (selectedItem, theWholeRoleItem): void => {
    if (this.onChangeAction) {
      this.onChangeAction(selectedItem, theWholeRoleItem);
    }

    this.resetDropdownSelectedItem();
  };

  getSelectedText = (): string => {
    if (this.displayValue) return this.actionPlaceHolder;

    const selectedItem = this.listItems.find((x) => x.value == this.actionPlaceHolder);
    if (selectedItem) return selectedItem.name;

    return '';
  };

  getSelectedHtml = (): string => {
    const selectedItem = this.listItems.find((x) => x.value == this.actionPlaceHolder);
    if (selectedItem) return selectedItem.html;

    return '';
  };

  onOpenChange(isOpened: boolean, dropdown: BsDropdownDirective): void {
    this.isOpened = isOpened;
    this.openChange.emit({ isOpened, dropdown });
    if (isOpened) {
      this.delay.execute(this.showMenu, 10);
      return;
    }

    this.hideMenu();
  }

  showMenu = (): void => {
    this.renderer.addClass(this.menu.nativeElement, 'show-menu');
    this.delay.execute(this.keepMenuInsideWindowBoundaries, 10);
  };

  keepMenuInsideWindowBoundaries = (): void => {
    const marginBuffer = 5;
    const { bottom } = this.menu.nativeElement.getBoundingClientRect();
    const distanceBetweenMenuBottomAndWindowBottom = bottom - (window.innerHeight - marginBuffer);
    if (distanceBetweenMenuBottomAndWindowBottom <= 0) return;

    this.renderer.setStyle(
      this.menu.nativeElement,
      'transform',
      `translateY(${-distanceBetweenMenuBottomAndWindowBottom}px)`
    );
  };

  hideMenu = (): void => {
    this.renderer.removeClass(this.menu.nativeElement, 'show-menu');
    this.resetDropdownSelectedItem();
  };

  onClick(e: MouseEvent) {
    if (!$(e.target).hasClass('dropdown-item') && !$(e.target).parents('.dropdown-item').length) e.stopPropagation();
  }

  clickOutside(): void {
    this.renderer.removeClass(this.menu.nativeElement, 'show-menu');
  }

  onKeyDown = (e: KeyboardEvent) => {
    if (e.key == Key.ArrowUp) {
      this.dropdownSelectedItemIndex--;
      if (this.dropdownSelectedItemIndex < 0) this.dropdownSelectedItemIndex = this.listItems.length - 1;
    } else if (e.key == Key.ArrowDown) {
      this.dropdownSelectedItemIndex++;
      if (this.dropdownSelectedItemIndex == this.listItems.length) this.dropdownSelectedItemIndex = 0;
    } else if (e.key == Key.Enter) {
      if (this.dropdownSelectedItemIndex < 0) return;
      this.onClickActionDropDown(this.listItems[this.dropdownSelectedItemIndex], this.rowItem);
    }
  };

  onMouseOver = (itemIndex: number, e: MouseEvent) => {
    this.dropdownSelectedItemIndex = itemIndex;
  };

  resetDropdownSelectedItem() {
    this.dropdownSelectedItemIndex = -1;
  }
}

export type ListItem = {
  name: string;
  value: string | number;
  html?: string;
  icon?: string;
};
