import { Component, EventEmitter, Input, OnDestroy, OnInit, Output, ViewEncapsulation } from '@angular/core';

import { Subject, Subscription } from 'rxjs';
import { debounceTime, distinctUntilChanged } from 'rxjs/operators';

import { MetaDataType } from '../..';
import { Dictionary } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/models';
import { IFindMetaDataById, IMetaDataValidator } from '../interop/MetaDataService';
import { MetaDataCollection } from '../models/metadata';

import { FieldDefinition } from './../models/field-definition';
import { BlurEvent, SaveLookupsEvent } from './../models/field-events';

enum TextTypes {
  Normal = 'normal',
  Hover = 'hover',
  Substitutable = 'substitutable',
}

@Component({
  selector: 'app-field',
  templateUrl: './field.component.html',
  styleUrls: ['./field.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class FieldComponent implements OnInit, OnDestroy {
  @Input() context: any;
  @Input() field: FieldDefinition;
  @Input() value: string;
  @Input() disabled: boolean;
  @Input() validity: number;
  @Input() validityError: string;
  @Input() focused = false;
  @Input() forceMaxLength = false;
  @Input() maxLength: number;
  @Input() fillViaPointAClick: string;
  @Input() findMetaDataService: IFindMetaDataById;
  @Input() metaDataValidator: IMetaDataValidator;
  @Input() metaDataCollection: MetaDataCollection;
  @Input() minValue: string;
  @Input() maxValue: string;
  @Input() options: Array<Dictionary>;
  @Input() defaultValue: string;
  @Input() triggerBlurEventOnLoad: boolean = true;
  @Input() triggerBlurEventOnValueChange: boolean = true;
  @Input() emitDistinctAndDebouncedValues: boolean = false;
  @Input() debounceDuration: number = 300;
  @Input() height: number;
  @Input() cssClasses: string;
  @Input() fieldTabIndex = 0;
  @Input() regex: RegExp;
  @Input() autocomplete: string = 'on';
  @Input() valueMapper: (value: string) => string;

  @Output() focus = new EventEmitter();
  @Output() blur = new EventEmitter<string>();
  @Output() tab = new EventEmitter<string>();
  @Output() shiftTab = new EventEmitter<string>();
  @Output() blurex = new EventEmitter<BlurEvent>();
  @Output() tabex = new EventEmitter<BlurEvent>();
  @Output() valueChange = new EventEmitter<string>();
  @Output() return = new EventEmitter<string>();
  @Output() noLookupFound = new EventEmitter<BlurEvent>();
  @Output() saveLookupValues = new EventEmitter<SaveLookupsEvent>();
  @Output() fieldChanged = new EventEmitter<string>();
  @Output() inputChange = new EventEmitter<string>();
  @Output() escape = new EventEmitter<void>();

  subscriptions = new Subscription();
  modelChanged: Subject<string> = new Subject<string>();
  tooltip: string = '';

  MetaDataType = MetaDataType;
  TextTypes = TextTypes;

  timer: any;
  lastValue: string;

  get fieldId() {
    if (
      this.field.type === MetaDataType.Text ||
      this.field.type === MetaDataType.LargeText ||
      this.field.substitutable ||
      this.field.infoText.trim().length > 0
    ) {
      return 'field-text-' + this.field.label;
    }
    if (this.field.type === MetaDataType.Password) return 'field-text-' + this.replaceSpacesWithDash(this.field.label);
    if (this.field.type === MetaDataType.Integer) return 'field-integer-' + this.field.label;
    if (this.field.type === MetaDataType.Currency) return 'field-currency-' + this.field.label;
    if (this.field.type === MetaDataType.Date) return this.field.id || 'field-text-' + this.field.label;
    if (this.field.type === MetaDataType.List) return 'field-list-' + this.field.label;
    if (this.field.type === MetaDataType.Decimal) return 'field-decimal-' + this.field.label;
    if (this.field.type === MetaDataType.Expression) return 'field-expression-' + this.field.label;

    return 'field-' + this.field.type + this.field.label;
  }

  constructor() {
    this.value = '';
  }

  ngOnInit() {
    if (!this.field.placeholder) this.field.placeholder = '';
    if (this.field.hasValidation) this.tooltip = this.field.tooltip;

    const modelChanged$ = this.emitDistinctAndDebouncedValues
      ? this.modelChanged.pipe(distinctUntilChanged(), debounceTime(this.debounceDuration))
      : this.modelChanged;

    this.subscriptions.add(
      modelChanged$.subscribe((model: string) => {
        this.value = model;
        this.triggerOnValueChangedEvents(model);
      })
    );
  }

  onFocus(e: any) {
    this.focus.emit();
  }

  onValueChanged = (value: string): void => {
    this.modelChanged.next(value);
  };

  triggerOnValueChangedEvents = (value): void => {
    this.valueChange.emit(value as string);
    this.fieldChanged.emit(value as string);
  };

  onBlur(value: string) {
    this.value = value;
    this.blur.emit(value);
    this.valueChange.emit(value);
    this.blurex.emit(new BlurEvent(this.context, value));
  }

  onCascadingListsValueChanged = (event: BlurEvent): void => {
    if (!event.context) event.context = this.context;
    this.value = event.value;
    this.valueChange.emit(`${event}`);
    this.fieldChanged.emit(`${event}`);
  };

  onCascadingListsBlur(event: BlurEvent) {
    if (!event.context) event.context = this.context;
    this.blur.emit(`${event}`);
    this.valueChange.emit(`${event}`);
    this.blurex.emit(event);
  }

  onTab(value: string) {
    this.value = value;
    this.tab.emit(value);
    this.tabex.emit(new BlurEvent(this.context, value));
  }

  onShiftTab(value: string) {
    this.value = value;
    this.shiftTab.emit(value);
  }

  onReturn(value: any) {
    this.value = value;
    this.return.emit(value);
  }

  setLookupValues(event: SaveLookupsEvent) {
    event.context = this.context;
    this.saveLookupValues.emit(event);
  }

  onInputChanged(value: any) {
    this.value = value;
    this.inputChange.emit(value);
  }

  onEscape() {
    this.escape.emit();
  }

  onNoLookupFound(event) {}

  getTextType() {
    if (this.field.infoText.trim().length > 0) return TextTypes.Hover;
    if (this.field.substitutable) return TextTypes.Substitutable;
    return TextTypes.Normal;
  }

  replaceSpacesWithDash(LabelInId: string): string {
    return LabelInId.replace(/\s+/g, '-');
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
