export enum DocumentPropertyDataType {
  String = 0,
  Date = 1,
  Integer = 2,
}

export interface ICustomProperty {
  id: number;
  name: string;
  type: DocumentPropertyDataType;
}

export class CustomProperty {
  id: number;
  name: string;
  type: DocumentPropertyDataType;

  constructor(cp: ICustomProperty = null) {
    this.id = cp ? cp.id : 0;
    this.name = cp ? cp.name : '';
    this.type = cp ? cp.type : DocumentPropertyDataType.String;
  }

  serializable(): ICustomProperty {
    return {
      id: this.id,
      name: this.name,
      type: this.type,
    };
  }

  getMetaDataType = (): MetaDataType => {
    if (this.type == DocumentPropertyDataType.Date) return MetaDataType.Date;
    if (this.type == DocumentPropertyDataType.Integer) return MetaDataType.Integer;

    return MetaDataType.Text;
  };
}

