export interface INewFaxUser {
  user: IFaxUser;
  inbound: IInboundService;
  outbound: IOutboundService;
}

export class NewFaxUser {
  user: FaxUser;
  inbound: InboundService;
  outbound: OutboundService;

  constructor() {
    this.user = new FaxUser();
    this.inbound = new InboundService();
    this.outbound = new OutboundService();
  }

  serializable(): INewFaxUser {
    return {
      user: this.user.serializable(),
      inbound: this.inbound.serializable(),
      outbound: this.outbound.serializable(),
    };
  }

  isPaymentRequired = (): boolean => {
    if (this.outbound.enabled) {
      if (this.outbound.setupCharge || this.outbound.subscriptionCharge) return true;
    }

    if (this.inbound.enabled) {
      if (this.inbound.setupCharge || this.inbound.subscriptionCharge) return true;
    }

    return false;
  };
}

