export class CountryContext implements ICountryContext {
  paymentMeans: string[];
  countryISOCode: string;
  countryName: string;
  currency: string;
  dealerID: string;
  vAT: number;
  accountTaxidRequired: TriState;
  vATAffectedByTaxID: boolean;
  allowedCreditCards: string[];
  ownerIDRequired: boolean;
  enablePrintedInvoices: boolean;
  bankFormat: Array<BankField>;
  dateFormat: string;
  timeFormat: string;
  decimalSeparator: string;
  thousandSeparator: string;
  numberGroupSizes: number[];
  currencyDecimalSeparator: string;
  currencyThousandSeparator: string;
  currencyGroupSizes: number[];
  showVATInclusive: boolean;

  constructor(cc: ICountryContext) {
    this.paymentMeans = cc.paymentMeans ? cc.paymentMeans.map((pm) => pm) : [];
    this.countryISOCode = cc.countryISOCode;
    this.countryName = cc.countryName;
    this.currency = cc.currency;
    this.dealerID = cc.dealerID;
    this.vAT = cc.vAT;
    this.accountTaxidRequired = cc.accountTaxidRequired;
    this.vATAffectedByTaxID = cc.vATAffectedByTaxID;
    this.allowedCreditCards = cc.allowedCreditCards ? cc.allowedCreditCards.map((cc) => cc) : [];
    this.ownerIDRequired = cc.ownerIDRequired;
    this.enablePrintedInvoices = cc.enablePrintedInvoices;
    this.bankFormat = cc.bankFormat ? cc.bankFormat.map((bf) => new BankField(bf)) : [];
    this.dateFormat = cc.dateFormat;
    this.timeFormat = cc.timeFormat;
    this.decimalSeparator = cc.decimalSeparator;
    this.thousandSeparator = cc.thousandSeparator;
    this.numberGroupSizes = cc.numberGroupSizes ? cc.numberGroupSizes.map((ngs) => ngs) : [];
    this.currencyDecimalSeparator = cc.currencyDecimalSeparator;
    this.currencyThousandSeparator = cc.currencyThousandSeparator;
    this.currencyGroupSizes = cc.currencyGroupSizes ? cc.currencyGroupSizes.map((cgs) => cgs) : [];
    this.showVATInclusive = cc.showVATInclusive;
  }

  public getPaymentMeans(): string[] {
    return this.paymentMeans;
  }

  serialize(): ICountryContext {
    return {
      paymentMeans: this.paymentMeans,
      countryISOCode: this.countryISOCode,
      countryName: this.countryName,
      currency: this.currency,
      dealerID: this.dealerID,
      vAT: this.vAT,
      accountTaxidRequired: this.accountTaxidRequired,
      vATAffectedByTaxID: this.vATAffectedByTaxID,
      allowedCreditCards: this.allowedCreditCards,
      ownerIDRequired: this.ownerIDRequired,
      enablePrintedInvoices: this.enablePrintedInvoices,
      bankFormat: this.bankFormat ? [] : this.bankFormat.map((bf) => bf.serialize()),
      dateFormat: this.dateFormat,
      timeFormat: this.timeFormat,
      decimalSeparator: this.decimalSeparator,
      thousandSeparator: this.thousandSeparator,
      numberGroupSizes: this.numberGroupSizes ? [] : this.numberGroupSizes.map((ngs) => ngs),
      currencyDecimalSeparator: this.currencyDecimalSeparator,
      currencyThousandSeparator: this.currencyThousandSeparator,
      currencyGroupSizes: this.currencyGroupSizes ? [] : this.currencyGroupSizes.map((cgs) => cgs),
      showVATInclusive: this.showVATInclusive,
    };
  }
}

