import {
  Component,
  OnInit,
  Output,
  EventEmitter,
  ViewEncapsulation,
  Input,
  OnDestroy,
  HostListener,
} from '@angular/core';
import { ApiService } from '../../services/api.service';
import { ScanAppConnectionStatus } from '../../../views/document-capture/capture-models';

import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import {
  DocumentProperties,
  ScanOptions,
  ScanPagesResult,
  ScanTo,
} from '../../../views/document-capture/capture-models/scan-commands';
import { ScanAppService } from '../../../views/document-capture/capture-services/scan-app.service';
import { Subscription } from 'rxjs';
import { SharedDataService } from '../../services/shared-data.service';
import { Filename } from '../../core/fileName';
import { MetaDataCollection } from 'shared-code-lib';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { InProgressService } from '../../services/in-progress.service';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';

@Component({
  selector: 'app-scan-to',
  templateUrl: './scan-to.component.html',
  styleUrls: ['./scan-to.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class ScanToComponent implements OnInit, OnDestroy {
  @Input() title: string;
  @Input() startscan: ScanTo;
  @Input() executeAction: boolean = true;
  @Input() modalId: string = 'ScanToModal';
  @Output() closeModal = new EventEmitter();

  subscriptions = new Subscription();
  scanAppInterval: any;
  scanAppConnectionStatus = ScanAppConnectionStatus;
  connectionStatus: number;
  scanAppOpened: boolean = false;
  modal: NgxSmartModalComponent;
  dialogeIsVisible: boolean = false;

  constructor(
    public api: ApiService,
    public ngxSmartModalService: NgxSmartModalService,
    private scanAppService: ScanAppService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private inProgress: InProgressService,
    protected translateService: TranslateService,
    private toastr: ToastrService
  ) {
    this.title = sharedDataService.action?.name;
    this.modal = this.ngxSmartModalService.getModal(this.modalId);
    this.startscan = new ScanTo(new ScanOptions(this.translateService.currentLang, true), new DocumentProperties());
  }

  @HostListener('window:focus', ['$event'])
  onFocus(event: any): void {
    if (this.scanAppOpened) this.scanAppService.activate();
  }

  @HostListener('window:mousedown', ['$event'])
  onMouseDown(event: any): void {
    if (this.scanAppOpened) this.scanAppService.activate();
  }

  ngOnInit(): void {
    this.subscriptions.add(
      this.scanAppService.onDocumentScanned.subscribe((scanresult: ScanPagesResult) => {
        this.onScanCompleted(scanresult);
        this.close();
      })
    );

    this.subscriptions.add(
      this.scanAppService.onScanCancelled.subscribe((scanresult: ScanPagesResult) => {
        this.scanAppOpened = false;
        this.close();
      })
    );

    this.subscriptions.add(
      this.scanAppService.onConnectionStatusChange.subscribe((status) => {
        this.setStatus(this.scanAppConnectionStatus[`${status}`]);
      })
    );

    this.subscriptions.add(
      this.scanAppService.onTransferDocument.subscribe(() => {
        this.hideDialoge();
      })
    );

    this.connect();
    clearInterval(this.scanAppInterval);
    this.scanAppInterval = setInterval(() => {
      this.connect();
    }, 3500);
  }

  ngOnDestroy(): void {
    clearInterval(this.scanAppInterval);
  }

  connect() {
    this.scanAppService.start();
    this.setStatus(this.scanAppService.connectionStatus);
  }

  setStatus(status): void {
    if (status == ScanAppConnectionStatus.connected) {
      if (!this.scanAppOpened) this.scan();
    } else if (
      this.connectionStatus != -1 &&
      (status == ScanAppConnectionStatus.disconnected || status == ScanAppConnectionStatus.needUpdate)
    ) {
      this.scanAppOpened = false;
      this.showDialoge();
    }

    this.connectionStatus = status;
  }

  hideDialoge = (): void => {
    this.modal.visible = false;
    this.dialogeIsVisible = false;
  };

  showDialoge = (): void => {
    this.modal.visible = true;
    this.dialogeIsVisible = true;
  };

  scan = (): void => {
    this.scanAppOpened = true;
    this.scanAppService.scan(this.startscan);
  };

  onScanCompleted(scanresult: ScanPagesResult): void {
    if (!this.executeAction) return;

    this.inProgress.display('app-scan.uploading-documents');

    let fileName = Filename.getScannedDocumentName(scanresult.scanpages);
    const file: File = new File([scanresult.data], fileName);
    var reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const fileAsBase64: string = reader.result.toString();
      const args = new MetaDataCollection();
      args.set('Filename', fileName);
      args.set('Base64Data', fileAsBase64);
      this.sharedDataService.actionHandler.invokeEx(
        this.sharedDataService.folderId,
        this.sharedDataService.action,
        [],
        args,
        this.onSucceeded,
        this.onError,
        false
      );
    };
    reader.onerror = (error) => {
      this.onError(this.translateService.instant('Common.LoadingDataError'));
    };
  }

  onSucceeded = (): void => {
    this.spinnerService.hide();
    this.inProgress.close();
  };

  onError = (err: any): void => {
    this.toastr.error(err);
    this.spinnerService.hide();
    this.inProgress.close();
  };

  isConnected(): boolean {
    return this.connectionStatus == ScanAppConnectionStatus.connected;
  }

  needUpdates(): boolean {
    return this.connectionStatus == ScanAppConnectionStatus.needUpdate;
  }

  appNotInstalled(): boolean {
    return (
      this.connectionStatus === ScanAppConnectionStatus.disconnected ||
      this.connectionStatus === ScanAppConnectionStatus.connecting
    );
  }

  close = (): void => {
    this.subscriptions.unsubscribe();
    this.modal?.close();
    this.closeModal.emit();
  };
}
