import { Workflow } from '../../../blocks/models/workflow';
import { Batch } from './batch';
import { DragData } from './capture-interfaces';
import { CapturedDocument } from './document';

export class Capture {
  name: string;
  destination: Workflow;
  children: Array<Batch>;

  constructor() {
    this.name = 'Capture';
    this.children = [];
  }

  addBatch(batch: Batch): void {
    this.children.push(batch);
  }

  removeBatch(batch: Batch): void {
    this.children.splice(this.children.indexOf(batch), 1);
  }

  getBatch(id: string): Batch {
    return this.children.filter((batch) => batch.id === id)[0];
  }

  getBatchIndex(batch: Batch): number {
    return this.children.indexOf(batch);
  }

  getBatchByIndex(index: number): Batch {
    return this.children[index];
  }

  dragPageFromDocumentToAnother(batch: Batch, doc: CapturedDocument, dragData: DragData): Batch {
    const targetBatch = this.getBatch(dragData.target);
    const targetDocument = targetBatch.getDoc(dragData.target.id);
    if (doc.pages.length === 0) {
      batch.removeDocument(doc);
    }
    if (batch.children.length === 0) {
      this.removeBatch(batch);
    }
    return targetBatch;
  }

  dragDocumentFromBatchToAnother(docId: string, parentId: string, targetId: string): Batch {
    const parent = this.getBatch(parentId);
    const target = this.getBatch(targetId);
    const doc = parent.getDoc(docId);

    target.addDocument(doc);
    parent.removeDocument(doc);
    if (parent.children.length === 0) {
      this.removeBatch(parent);
    }
    return target;
  }

  removeAllBatches(): void {
    this.children = [];
  }
}
