import { LookupToBeSaved } from './lookup-models';
import { MetaDataDefinition } from './metadata-definition';

export class FieldEvent {
  constructor(public context: any) {}
}

export class BlurEvent extends FieldEvent {
  public mdd: MetaDataDefinition;
  constructor(context, public value: string) {
    super(context);
  }
}

export class SaveLookupsEvent extends FieldEvent {
  constructor(public lookups: Array<LookupToBeSaved>, public move: boolean, public forward: boolean, context?: any) {
    super(context);
  }
}
