import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { FieldDefinition, FixedDataSource, MetaDataType } from 'shared-code-lib';
import { SharePermissions, ShareWith } from '../../InterFAX/Models/inbound';
import { InterfaxDocumentSharingService } from './../../../blocks/services/interfax-document-sharing.service';

@Component({
  selector: 'app-interfax-sharing-grid',
  templateUrl: './interfax-sharing-grid.component.html',
  styleUrls: ['./interfax-sharing-grid.component.scss'],
})
export class InterfaxSharingGridComponent implements OnInit {
  @Input() entities: Array<ShareWith>;
  @Input() current: Array<ShareWith>;

  @Output() currentChange = new EventEmitter<Array<ShareWith>>();

  entityDataSource: FixedDataSource;
  permissionsDataSource: FixedDataSource;
  fieldDefinitions = {};

  constructor(private interfaxDocumentSharingService: InterfaxDocumentSharingService) {}

  ngOnInit(): void {
    this.createDataSources();
  }

  addRow = (): void => {};

  getEntityFieldDefinition = (share: ShareWith): FieldDefinition => {
    const name = `entity~${share.entityType}~${share.entity}`;

    if (this.fieldDefinitions[name] == null) {
      this.fieldDefinitions[name] = new FieldDefinition({
        type: MetaDataType.List,
        label: '',
        placeholder: '',
        required: true,
        datasource: this.entityDataSource,
      });
    }

    return this.fieldDefinitions[name];
  };

  getEntityValue = (share: ShareWith): string => {
    return `${share.entityType}~${share.entity}`;
  };

  setEntityValue = (share: ShareWith, value: string): void => {
    const parts = value.split('~');
    if (parts.length != 2) return;

    share.entityType = parseInt(parts[0]);
    share.entity = parts[1];
  };

  getPermissionFieldDefinition = (share: ShareWith): FieldDefinition => {
    const name = `permission~${share.entityType}~${share.entity}`;

    if (this.fieldDefinitions[name] == null) {
      this.fieldDefinitions[name] = new FieldDefinition({
        type: MetaDataType.List,
        label: '',
        placeholder: '',
        required: true,
        datasource: this.permissionsDataSource,
      });
    }

    return this.fieldDefinitions[name];
  };

  getPermissionValue = (share: ShareWith): string => {
    return `${share.permissions}`;
  };

  setPermissionValue = (share: ShareWith, value: string): void => {
    share.permissions = Number(value);
  };

  createDataSources = (): void => {
    const entityOptions = this.entities
      .filter((e) => e.permissions != SharePermissions.Owner)
      .map((e) => {
        return { name: e.name, value: `${e.entityType}~${e.entity}` };
      });

    this.entityDataSource = new FixedDataSource(entityOptions);

    this.permissionsDataSource = new FixedDataSource(this.interfaxDocumentSharingService.options);
  };
}
