import { Filter } from '../models/filter';

export class FilterBaseComponent {
  declare filter: Filter;

  initializeFilter = (): void => {
    if (!this.filter?.value) {
      this.clearFilter();
    } else {
      this.setValue(this.filter.value);
    }
  };

  clearFilter = (): void => this.setValue(this.filter?.defaultValue ?? '');

  setValue = (val: string): void => void (this.filter.value = val);

  getFilterParts = (val: string, splitBy = ':'): string[] => {
    const i = val.indexOf(splitBy);
    if (i === -1) return [];

    return [val.substring(0, i), val.substring(i + 1)];
  };
}
