import { Directive, ElementRef, Input, OnDestroy, OnInit, Renderer2 } from '@angular/core';
import { AngularFittextDirective } from 'angular-fittext';
import { Observable, Subscription } from 'rxjs';

@Directive({
  selector: '[appAutoFittext]',
})
export class AutoFittextDirective extends AngularFittextDirective implements OnDestroy, OnInit {
  @Input() onWidthResized: Observable<any>;

  private subscription = new Subscription();
  constructor(el: ElementRef, renderer: Renderer2) {
    super(el, renderer);
  }

  ngOnInit(): void {
    super.ngOnInit();
    this.subscription.add(
      this.onWidthResized.subscribe(() => {
        this.onWindowResize();
      })
    );
  }

  ngOnDestroy(): void {
    this.subscription.unsubscribe();
  }
}
