import { Component, Input, OnInit, OnChanges, Output, EventEmitter, ViewEncapsulation, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';

import { ElementRef } from '@angular/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { DelayService, Strings } from 'shared-code-lib';
import { Key } from '../../utils/key-enum';

export interface ISearchItems {
  findMatches(searchTerm: string, completed: (items: Array<any>) => void): void;
}

export interface ISelectable {
  selected: boolean;
  item: any;
}

export class Selectable implements ISelectable {
  selected: boolean;
  item: any;

  constructor(item: any, selected: boolean) {
    this.selected = selected;
    this.item = item;
  }
}

export class DualPickListItem {
  name: string;
  value: any;
  icon: string;

  constructor(name: string, value: any, icon?: string) {
    this.name = name;
    this.value = value;
    this.icon = icon;
  }
}
declare const $: any;

@Component({
  selector: 'app-dual-picklist',
  templateUrl: './dual-picklist.component.html',
  styleUrls: ['./dual-picklist.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class DualPicklistComponent implements OnInit, OnChanges {
  @Input() listName: string;
  @Input() available: Array<any>;
  @Input() current: Array<any>;
  @Output() currentChange = new EventEmitter<Array<any>>();
  @Input() displayField: string;
  @Input() keyField: string;
  @Input() allowOrderSelectedItems: boolean = true;
  @Input() sortAvailableItems: boolean = true;
  @Input() sortSelectedItems: boolean = false;
  @Input() iconField?: string;
  @Input() iconType?: string;
  @Input() allowDoubleClick: boolean = true;
  @Input() searchItems: ISearchItems;
  @Input() availableTitle: string = 'Action-panel.Available';
  @Input() selectedTitle: string = 'Action-panel.Selected';

  @ViewChild('selectedListWrapper', { static: true }) selectedListWrapper: ElementRef;
  @ViewChild('psLeft', { static: true }) psLeft: PerfectScrollbarDirective;
  @ViewChild('psRight', { static: true }) psRight: PerfectScrollbarDirective;
  @ViewChild('dualPickSpinner', { static: true }) spinnerElement: ElementRef;
  @Input() containerSpinnerElement;

  selectedList: Array<Selectable>;
  availableList: Array<Selectable>;
  searchTerm = '';
  timeOut = null;
  searchDelay = 250;
  dragEnabled = false;

  private draggedItem: ISelectable;
  private sortingItem: ISelectable;
  areAllSelected: boolean;

  constructor(
    private translate: TranslateService,
    private delay: DelayService,
    private spinnerStateService: SpinnerStateService
  ) {}

  ngOnInit() {
    this.selectedList = [];
    this.availableList = [];
    this.searchTerm = '';
    if (!this.keyField) this.keyField = this.displayField;

    if (!this.listName) {
      this.listName = this.translate.instant('Action-panel.Name');
    }

    this.loadAvailable();
  }

  ngOnChanges(): void {
    if (this.available.length > 0) this.buildAvailableItems(this.available);
  }

  loadAvailable = () => {
    this.availableList = [];
    this.spinnerStateService.show(
      this.translate.instant('Common.Searching'),
      this.containerSpinnerElement ?? this.spinnerElement.nativeElement
    );
    if (this.searchItems) {
      this.searchItems.findMatches(this.searchTerm, this.buildAvailableItems);
    } else {
      this.buildAvailableItems(this.available);
    }
  };

  buildAvailableItems = (items: Array<any>): void => {
    this.spinnerStateService.hide(this.translate.instant('Common.Searching'));

    this.available = items;

    if (this.sortAvailableItems && this.available) this.available = this.available.sort(this.itemsCompare);
    if (this.sortSelectedItems && this.selectedList)
      this.selectedList = this.selectedList.sort(this.selectedItemsCompare);

    this.availableList = this.available.map((item) => new Selectable(item, this.isCurrentlySelected(item)));
    this.selectedList = this.current.map((item) => new Selectable(item, true));

    this.psLeft.update();
    this.psRight.update();
  };

  isCurrentlySelected = (item: any): boolean => {
    return this.current.find((x) => x[this.keyField] == item[this.keyField]) != null;
  };

  itemsCompare = (a: any, b: any) => a[this.displayField].localeCompare(b[this.displayField]);
  selectedItemsCompare = (a: any, b: any) => this.itemsCompare(a.item, b.item);

  private updatePickList = () => {
    this.selectedList = [...this.selectedList];

    if (this.sortSelectedItems) this.selectedList = this.selectedList.sort(this.selectedItemsCompare);

    this.current = this.selectedList.map((i) => i.item);
    this.currentChange.emit(this.current);

    this.areAllSelected = this.areAllFilteredItemsSelected();

    this.psRight.update();
  };

  listOrderChanged = (event) => {
    this.updatePickList();
  };

  addItem(item: ISelectable) {
    item.selected = true;
    this.selectedList.push(item);
    this.updatePickList();
  }

  addAll(): void {
    const filteredAvailableList = this.getFilteredAvailableList();

    filteredAvailableList.forEach((item) => {
      if (!item.selected) {
        item.selected = true;
        this.selectedList.push(item);
      }
    });

    this.updatePickList();
  }

  areAllFilteredItemsSelected(): boolean {
    return this.getFilteredAvailableList().every((item) => item.selected === true);
  }

  getFilteredAvailableList() {
    let filteredAvailableList = this.availableList.filter((i) => {
      const displayFieldValue = <string>i.item[this.displayField];
      return displayFieldValue.toLowerCase().includes(this.searchTerm.toLowerCase());
    });

    return filteredAvailableList;
  }

  removeItem(index: number) {
    const removedItem = this.selectedList.splice(index, 1)[0];
    const availableItem = this.availableList.find((x) => x.item[this.keyField] == removedItem.item[this.keyField]);

    if (availableItem) availableItem.selected = false;

    this.updatePickList();
  }

  removeAll() {
    this.selectedList = [];
    this.availableList.forEach((item) => {
      item.selected = false;
    });

    this.updatePickList();
  }

  drag(event: DragEvent, item: ISelectable, sorting: boolean = undefined) {
    event.dataTransfer.setData('text', '');
    event.stopPropagation();

    const target = event.target as HTMLElement;
    if (!target.classList.contains('drag-enabled')) {
      event.preventDefault();
      return;
    }

    target.classList.add('dragging');

    if (sorting) {
      this.sortingItem = item;
    } else {
      this.draggedItem = item;
    }
  }

  onDragEnd(event: DragEvent) {
    event.stopPropagation();
    event.preventDefault();

    const target = event.target as HTMLElement;

    target.classList.remove('dragging');
    this.dragEnabled = false;
    this.draggedItem = null;
  }

  onDragOver(event: DragEvent, item?: ISelectable, index?: number) {
    event.preventDefault();
    event.stopPropagation();

    let draggedElementIndex = this.selectedList.indexOf(this.draggedItem);

    if (this.draggedItem && draggedElementIndex < 0) {
      if (item && this.allowOrderSelectedItems) {
        this.selectedList.splice(index, 0, this.draggedItem);
      } else {
        this.selectedList.push(this.draggedItem);
      }

      this.draggedItem.selected = true;
    } else if ((this.draggedItem && draggedElementIndex > -1) || this.sortingItem) {
      if (item && this.allowOrderSelectedItems) {
        if (!this.draggedItem) {
          draggedElementIndex = this.selectedList.indexOf(this.sortingItem);
        }

        const diff = draggedElementIndex - index;

        if (diff === 1 || diff === -1) {
          const tempItem = this.selectedList[draggedElementIndex];
          this.selectedList[draggedElementIndex] = this.selectedList[index];
          this.selectedList[index] = tempItem;
        } else {
          const tempItem = this.selectedList.splice(draggedElementIndex, 1)[0];
          this.selectedList.splice(index, 0, tempItem);
        }
      }
    }
  }

  onDragLeave(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();

    if (!this.isElementInsideSelectedList(event)) {
      if (this.draggedItem) {
        const draggedItemIndex = this.selectedList.indexOf(this.draggedItem);
        if (draggedItemIndex > -1) {
          this.selectedList.splice(draggedItemIndex, 1);
          this.draggedItem.selected = false;
        }
      }
    }
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();

    this.dragEnabled = false;
    this.draggedItem = null;
    this.updatePickList();
  }

  isElementInsideSelectedList(event: DragEvent) {
    const div = $(this.selectedListWrapper.nativeElement);
    const offset = div.offset();
    const offsetHeight = div.height();
    const offsetWidth = div.width();

    return (
      event.pageX < offset.left + offsetWidth &&
      event.pageX > offset.left &&
      event.pageY < offset.top + offsetHeight &&
      event.pageY > offset.top
    );
  }

  onKeyDown(event: any) {
    if (event.key === Key.Escape) return;

    clearTimeout(this.timeOut);
    this.timeOut = null;
    this.timeOut = this.delay.execute(() => this.fireSearch(event), this.searchDelay);
  }

  fireSearch = (event: any): void => {
    this.searchTerm = event.target.value;
    this.loadAvailable();
  };

  hasIcon = (item): boolean => {
    if (!item) return false;

    return Strings.notEmpty(this.iconField) && Strings.notEmpty(item.item[this.iconField]);
  };

  isImage = (): boolean => {
    return this.iconType == 'image' || Strings.isEmpty(this.iconType);
  };

  isFontAwesome = (): boolean => {
    return this.iconType == 'fa';
  };
}
