import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';

import { ActivatedRoute, Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { AuthService, BrandingService, FieldDefinition, MetaDataType } from 'shared-code-lib';
import { Log } from '../../core/log';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResults } from '../../services/models';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-mobile-registration',
  templateUrl: './mobile-registration.component.html',
  styleUrls: ['./mobile-registration.component.scss'],
})
export class MobileRegistrationComponent implements OnInit {
  @ViewChild('spinnerDiv', { static: true }) div: ElementRef;
  divElement: HTMLElement;

  errorOccurred: boolean = false;
  errorText: string = '';
  registrationCompleted: boolean = false;

  logoColor: string;

  email = '';
  code = '';

  fieldEmail: FieldDefinition;
  fieldCode: FieldDefinition;

  constructor(
    private router: Router,
    private translate: TranslateService,
    private spinnerState: SpinnerStateService,
    private auth: AuthService,
    private route: ActivatedRoute,
    private brandingService: BrandingService,
    private hydraApi: HydraApiService
  ) {}

  ngOnInit() {
    this.divElement = this.div.nativeElement;

    this.handleBranding();

    this.fieldEmail = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('Login.mobile-registration-email'),
      placeholder: this.translate.instant('Login.mobile-registration-email-placeholder'),
      required: true,
    });

    this.fieldCode = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('Login.mobile-registration-code'),
      placeholder: this.translate.instant('Login.mobile-registration-code-placeholder'),
      required: true,
    });
  }

  private handleBranding = (): void => {
    this.logoColor = this.brandingService.isBranded()
      ? `logo-color-${this.brandingService.get()}.svg`
      : 'logo-color.svg';
  };

  login = (): void => {
    this.router.navigateByUrl('/');
  };

  reset = (): void => {
    this.spinnerState.show(this.translate.instant('Login.mobile-registering'), this.divElement);
    this.hydraApi.mobileRegisterUser(this.email, this.code, this.registrationSucceeded, this.registrationFailed);
  };

  registrationSucceeded = (result: ApiResults): void => {
    this.spinnerState.hide();

    if (!result.success) {
      this.errorText = result.errors[0];
      this.errorOccurred = true;

      return;
    }

    this.registrationCompleted = true;
  };

  registrationFailed = (err): void => {
    Log.error('MobileRegistrationComponent.resetFailed', err);
    Log.var(err);

    this.spinnerState.hide();
    this.errorOccurred = true;

    if (err.status && err.status == 400 && err.error) {
      this.errorText = err.error;
    } else {
      this.errorText = this.translate.instant('Login.mobile-registration-failed');
    }
  };
}
