import { Component, ElementRef, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { ToastrService } from 'ngx-toastr';
import { Log } from 'oidc-client';
import {
  FieldDefinition,
  FixedDataSource,
  IFieldOptions,
  MetaDataCollection,
  MetaDataType,
  Strings,
} from 'shared-code-lib';
import { Filename } from '../../core/fileName';
import { IItemId } from '../../core/itemActionHandler';
import { CSVColumnMapping, DataSource, ImportCSVData } from '../../models/datasource';
import { ErrorsService } from '../../services/errors.service';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResults } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-datasource-csv-import',
  templateUrl: './datasource-csv-import.component.html',
  styleUrls: ['./datasource-csv-import.component.scss'],
})
export class DataSourceCSVImportComponent implements OnInit {
  @ViewChild(PerfectScrollbarDirective, { static: true }) directiveRef?: PerfectScrollbarDirective;
  @Output() closeModal = new EventEmitter();
  @ViewChild('csvImportInput', { static: true })
  csvImportInput: ElementRef;
  csvFile: any;
  csvContent: any;
  importErrors = [];
  importExtensions = ['txt', 'csv'];
  replaceField: FieldDefinition;
  replaceFieldValue: boolean = true;
  firstRowIsColumnHeaders: boolean = true;
  csvColumns: FixedDataSource;
  fieldCsvColumns: FieldDefinition[] = [];
  fieldCsvColumnsValues: number[] = [];
  importedColumns: string[] = [];
  datasource: DataSource;

  constructor(
    private translateService: TranslateService,
    public sharedDataService: SharedDataService,
    private spinner: SpinnerStateService,
    private hydraApi: HydraApiService,
    private toastr: ToastrService,
    private errorsService: ErrorsService,
    private userState: UserStateService
  ) {}

  ngOnInit(): void {
    this.replaceField = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('admin-datasource.name'),
      placeholder: this.translateService.instant('admin-datasource.name'),
      required: true,
    });

    this.csvColumns = new FixedDataSource(new Array<IFieldOptions>());

    const folder = this.userState.findFolderById(this.sharedDataService.extraParameters.folderId);
    if (folder) {
      this.hydraApi.getDataSource(folder.parentFolderId, this.datasourceLoadSucceeded, this.datasourceLoadFailed);
    } else {
      this.errorsService.showError('admin-datasource.invalid-datasource', '');
    }
  }

  datasourceLoadSucceeded = (datasource: DataSource): void => {
    this.datasource = datasource;
    this.createMappingFields();
  };

  datasourceLoadFailed = (error: any): void => {
    Log.error('admin-datasource.load-failed', error);
  };

  handleFileSelect(event: any) {
    if (!event.target.files || !event.target.files.length) return;

    const file = event.target.files[0];

    this.importErrors = [];
    if (!Filename.extensionIsOneOf(file.name, this.importExtensions)) {
      this.importErrors.push('csv.only-csv-and-text');
      this.csvImportInput.nativeElement.value = '';
      return;
    }

    this.csvFile = file;
    var reader = new FileReader();

    reader.onload = () => {
      this.csvContent = reader.result as string;
      if (Strings.isEmpty(this.csvContent)) {
        this.csvColumns.updateOptions([]);
      } else {
        const eolChar = Strings.getEOLCharacters(this.csvContent);
        this.importedColumns = this.csvContent.split(eolChar)[0].split(',');
        this.createMappingFields();
      }
    };
    reader.readAsText(this.csvFile);
  }

  createMappingFields = (): void => {
    const columnsFields: Array<IFieldOptions> = [];
    for (let i = 0; i < this.importedColumns.length; i++) {
      columnsFields.push({ name: this.translateService.instant(this.importedColumns[i]), value: `${i}` });
    }
    this.csvColumns.updateOptions(columnsFields);
    this.fieldCsvColumns = [];
    this.fieldCsvColumnsValues = [];
    for (let i = 0; i < this.datasource.columns.length; i++) {
      this.fieldCsvColumns.push(
        new FieldDefinition({
          type: MetaDataType.List,
          label: this.datasource.columns[i].name,
          placeholder: '',
          required: false,
          hideLabel: true,
          datasource: this.csvColumns,
        })
      );
      this.fieldCsvColumnsValues.push(-1);
    }
  };

  close = (): void => {
    this.resetImportModal();
    this.closeModal.emit();
  };

  onImport() {
    const csvData = new ImportCSVData({
      firstRowIsColumnHeaders: this.firstRowIsColumnHeaders,
      replaceExistingRows: this.replaceFieldValue,
      columnsMapping: this.getMapping(),
      content: this.csvContent,
    });
    this.hydraApi.updateDataSourceWithCSV(
      this.datasource.id,
      csvData,
      this.datasourceImportSucceeded,
      this.csvImportFailed
    );

    this.resetImportModal();
    this.close();
    this.spinner.show(
      this.translateService.instant('datasource-import-csv.import-spinner-message'),
      document.documentElement
    );
  }

  getMapping = (): Array<CSVColumnMapping> => {
    const mapping: Array<CSVColumnMapping> = [];
    for (let i = 0; i < this.datasource.columns.length; i++) {
      if (this.fieldCsvColumnsValues[i] == -1) continue;
      mapping.push(
        new CSVColumnMapping({
          dataSourceColumnId: this.datasource.columns[i].id,
          cSVColumnIndex: this.fieldCsvColumnsValues[i],
        })
      );
    }
    return mapping;
  };

  datasourceImportSucceeded = (result: ApiResults) => {
    this.spinner.hide();

    const items: IItemId[] = [];

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      items,
      new MetaDataCollection(),
      () => {}
    );

    if (result.success) {
      this.toastr.success(this.translateService.instant('datasource-import-csv.import-success-message'));
    } else {
      this.spinner.hide();
      this.errorsService.showErrorsModal(result.errors, 'datasource-import-csv.import-error-dialog-title');
    }
  };

  csvImportFailed = (err: any) => {
    this.close();
    this.spinner.hide();
    this.toastr.error(this.translateService.instant(err.message));
  };

  resetImportModal = () => {
    this.csvFile = null;
    this.csvImportInput.nativeElement.value = '';
    this.importErrors = [];
  };

  canImport = (): boolean => {
    if (!this.csvFile) return false;
    if (this.fieldCsvColumnsValues.find((x) => x != -1 && x.toString() != '') == null) return false;

    return true;
  };

  getFieldCsvColumnValue = (index: number): string => {
    return `${this.fieldCsvColumnsValues[index]}`;
  };
  setFieldCsvColumnValue = (index: number, val: string) => {
    this.fieldCsvColumnsValues[index] = Number(val);
  };
}
