import { ITemplateStyle, InlineStyle, StyleType } from './template';

export interface IStyle extends ITemplateStyle {
  id: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
}

export class Style implements IStyle {
  id = '';
  dateCreatedUTC = new Date();
  dateModifiedUTC = new Date();
  name = '';
  element = '';
  elementType = StyleType.None;
  classes = '';
  inlineStyles: InlineStyle[] = [];

  constructor(initializer: IStyle | null = null) {
    if (initializer) {
      if (initializer.id === undefined) throw new Error('Invalid initializer.id');
      if (initializer.dateCreatedUTC === undefined) throw new Error('Invalid initializer.dateCreatedUTC');
      if (initializer.dateModifiedUTC === undefined) throw new Error('Invalid initializer.dateModifiedUTC');
      if (initializer.name === undefined) throw new Error('Invalid initializer.name');
      if (initializer.element === undefined) throw new Error('Invalid initializer.element');
      if (initializer.elementType === undefined) throw new Error('Invalid initializer.elementType');
      if (initializer.classes === undefined) throw new Error('Invalid initializer.classes');
      if (initializer.inlineStyles === undefined) throw new Error('Invalid initializer.inlineStyles');

      this.id = initializer.id;
      this.dateCreatedUTC = initializer.dateCreatedUTC;
      this.dateModifiedUTC = initializer.dateModifiedUTC;
      this.name = initializer.name;
      this.element = initializer.element;
      this.elementType = initializer.elementType;
      this.classes = initializer.classes;
      this.inlineStyles = initializer.inlineStyles.map((i) => new InlineStyle(i));
    }
  }

  public serializable(): IStyle {
    return {
      id: this.id,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      name: this.name,
      element: this.element,
      elementType: this.elementType,
      classes: this.classes,
      inlineStyles: this.inlineStyles,
    };
  }
}
