import { Component, EventEmitter, OnInit, Output, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { DeviceDetectorService } from 'ngx-device-detector';
import { ToastrService } from 'ngx-toastr';
import { FieldDefinition, MetaDataType } from 'shared-code-lib';
import { Feedback } from '../../models/feedback';
import { ApiService } from '../../services/api.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

declare const $: any;
@Component({
  selector: 'app-feedback-modal',
  templateUrl: './feedback-modal.component.html',
  styleUrls: ['./feedback-modal.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class FeedbackModalComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  feedbackField: FieldDefinition;

  feedback: string;

  feedbackType = 1;

  errors = [];

  constructor(
    private translateService: TranslateService,
    private apiService: ApiService,
    private spinnerService: SpinnerStateService,
    private toastr: ToastrService,
    private deviceDetector: DeviceDetectorService
  ) {}

  ngOnInit(): void {
    this.feedback = '';

    this.createFields();
  }

  createFields = () => {
    this.feedbackField = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('feedback-modal.feedback'),
      placeholder: this.translateService.instant('feedback-modal.feedback-placeholder'),
      required: true,
      scrollHeight: '192px',
    });
  };

  sendFeedback = () => {
    this.showSpinner();

    const feedbackObj: Feedback = new Feedback();
    feedbackObj.feedback = this.feedback;
    feedbackObj.overAllStatus = this.getOverAllStatus();
    feedbackObj.browser = { name: this.deviceDetector.browser, version: this.deviceDetector.browser_version };
    feedbackObj.route = window.location.pathname;

    this.apiService.postFeedback(feedbackObj, this.onAddFeedbackSucceeded, this.onAddFeedbackFailed);
  };

  onAddFeedbackSucceeded = (): void => {
    this.toastr.success(this.translateService.instant('feedback-modal.feedback-success'));

    this.spinnerService.hide();
    this.close();
  };

  onAddFeedbackFailed = (errors: any[]): void => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  close = (): void => {
    this.closeModal.emit();
  };

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.feedback .nsm-content') as HTMLElement;
  }

  showSpinner = (): void => {
    this.spinnerService.show(this.translateService.instant('feedback-modal.loading'), this.getSpinnerElement());
  };

  getCurrentRoute = () => {
    return window.location.pathname;
  };

  getOverAllStatus = () => {
    switch (this.feedbackType) {
      case 1:
        return 'Smile';
      case 0:
        return 'Meh';
      case -1:
        return 'Frown';
    }
  };

  validateFeedbackLength = (event: string) => {
    this.feedback = event;
    if (this.feedback.length <= 2048) this.errors = [];
    else this.errors = [this.translateService.instant('feedback-modal.feedback-length-error')];
  };
}
