export interface ISelectOptionActionResult {
  title: string;
  description: string;
  options: IOption[];
  extraParameters: any;
}

export interface IOption {
  id: string;
  title: string;
  icon: string;
}

export class SelectOptionActionResult implements ISelectOptionActionResult {
  title: string;
  description: string;
  options: Option[];
  extraParameters: any;

  constructor(selectOptionActionResult: ISelectOptionActionResult) {
    this.title = selectOptionActionResult?.title;
    this.description = selectOptionActionResult?.description;
    this.options = selectOptionActionResult?.options?.map((a) => new Option(a)) ?? [];
    this.extraParameters = selectOptionActionResult?.extraParameters;
  }
}

export class Option {
  id: string;
  title: string;
  icon: string;

  constructor(option: IOption) {
    this.id = option?.id;
    this.title = option?.title;
    this.icon = option?.icon;
  }
}
