import { MongoObjectId } from './mongo-object-id';

export enum ThresholdUnits {
  Minutes = 0,
  Hours = 1,
  Days = 2,
}
export enum ThresholdStyle {
  Caution = 0,
  Warning = 1,
  Critical = 2,
}
export enum ThresholdDataField {
  DateCreated = 0,
  DateModified = 1,
}

export interface IThreshold {
  id: string;
  minimum: number;
  maximum: number;
  unit: ThresholdUnits;
  dataField: ThresholdDataField;
  style: ThresholdStyle;
  tooltip: string;
}

export class Threshold implements IThreshold {
  public id: string;
  minimum: number;
  maximum: number;
  unit: ThresholdUnits;
  dataField: ThresholdDataField;
  style: ThresholdStyle;
  tooltip: string;

  public constructor(initializer: IThreshold) {
    this.id = initializer.id;
    this.minimum = initializer.minimum;
    this.maximum = initializer.maximum;
    this.unit = initializer.unit;
    this.dataField = initializer.dataField;
    this.style = initializer.style;
    this.tooltip = initializer.tooltip;
  }

  public static create = (): Threshold => {
    return new Threshold({
      id: MongoObjectId.generate(),
      minimum: 1,
      maximum: 999,
      unit: ThresholdUnits.Days,
      style: ThresholdStyle.Warning,
      dataField: ThresholdDataField.DateModified,
      tooltip: '',
    });
  };

  serializable(): IThreshold {
    return {
      id: this.id,
      minimum: this.minimum,
      maximum: this.maximum,
      unit: this.unit,
      dataField: this.dataField,
      style: this.style,
      tooltip: this.tooltip,
    };
  }
}
