import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { distinctUntilChanged, map } from 'rxjs/operators';
@Injectable({
  providedIn: 'root',
})
export class ListService {
  private _loadingSubject = new BehaviorSubject<Record<string, boolean>>({});
  loading$ = this._loadingSubject.asObservable();

  overallLoadingChanged$ = this.loading$.pipe(
    map(() => this.getOverallLoading()),
    distinctUntilChanged()
  );

  constructor() {}

  setLoading = (id: string, loading: boolean): void => {
    const loadingState = { ...this._loadingSubject.value };
    if (loading) {
      loadingState[id] = true;
    } else {
      delete loadingState[id];
    }

    this._loadingSubject.next(loadingState);
  };

  getLoading = (id: string): boolean => {
    return !!this._loadingSubject.value[id];
  };

  getOverallLoading = (): boolean => {
    return Object.values(this._loadingSubject.value).some((loading) => loading);
  };
}
