import { Component, OnInit, Input } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { UserStateService } from '../../../../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { SystemMetaData } from '../../../../../../../Bamba.Web/ClientApp/src/app/blocks/core/systemMetaData';
import { MetaData, RolePermissions } from 'shared-code-lib';
import { ClipboardService } from 'shared-code-lib';

class DisplayExtractedMetaData {
    constructor(public name: string, public value: string) {}
}

@Component({
    selector: 'app-workitem-properties-extracted-data',
    templateUrl: './workitem-properties-extracted-data.component.html',
    styleUrls: ['./workitem-properties-extracted-data.component.scss'],
})
export class WorkitemPropertiesExtractedDataComponent implements OnInit {
    @Input() details: any;

    systemMetaDataToShow = [SystemMetaData.ExtractedDocumentData, SystemMetaData.ExtractedInvoiceData];

    extractedMetadata = new Array<DisplayExtractedMetaData>();

    constructor(
        private userState: UserStateService,
        private translate: TranslateService,
        private toastr: ToastrService
    ) {}

    ngOnInit() {
        this.buildMetaData();
    }

    buildMetaData = (): void => {
        if (!this.userState.hasRolePermission(RolePermissions.WORKITEM_MANAGE)) return;

        for (const key in this.details.metaData) {
            const md = <MetaData>this.details.metaData[key];
            if (this.systemMetaDataToShow.findIndex((mdToShow) => mdToShow.toLowerCase() === md.name.toLowerCase()) === -1)
                continue;

            const extractedJSON = JSON.stringify(JSON.parse(md.value as string), undefined, 2);

            this.extractedMetadata.push(new DisplayExtractedMetaData(md.name.slice(1), extractedJSON));
        }
    };

    onCopyToClipboard = (): void => {
        let clipboardText = `ID: ${this.details.id}\n\n`;

        for (const extractedData of this.extractedMetadata) {
            clipboardText = clipboardText + `${extractedData.name}: ${extractedData.value}\n`;
        }

        ClipboardService.copyToClipboard(clipboardText);

        this.toastr.info(this.translate.instant('general.copied-to-clipboard'));
    };
}