import { Component, Input, ViewEncapsulation } from '@angular/core';
import { Icons } from '../alert-default/alert-default.component';

@Component({
  selector: 'app-modal-success',
  templateUrl: './alert-success.component.html',
  styleUrls: ['./alert-success.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class AlertSuccessComponent {
  @Input() title: string;
  @Input() message: string;
  @Input() autoClose: boolean = true;
  @Input() timeoutInSeconds: number;
  @Input() onClose: Function;
  @Input() buttonText: string;
  @Input() buttonClass: string = 'btn-primary';
  @Input() customClass: string = 'success-modal';
  @Input() showIcon: Icons = Icons.None;

  Icons = Icons;
}
