export interface IMoneyAmount {
  value: number;
  currencyCode: string;
}

export class MoneyAmount implements IMoneyAmount {
  value: number;
  currencyCode: string;

  constructor(initializer: IMoneyAmount) {
    if (initializer.value === undefined) throw new Error('invalid initializer.value');
    if (initializer.currencyCode === undefined) throw new Error('invalid initializer.currencyCode');

    this.value = initializer.value;
    this.currencyCode = initializer.currencyCode;
  }
}
