import {
  AfterViewInit,
  Component,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  Output,
  SimpleChanges,
} from '@angular/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { Subscription } from 'rxjs';
import { UserStateService } from '../../services/user-state.service';

@Component({
  selector: 'app-change-secure-user-password-modal',
  templateUrl: './change-secure-user-password-modal.component.html',
  styleUrls: ['./change-secure-user-password-modal.component.scss'],
})
export class ChangeSecureUserPasswordModalComponent implements OnChanges, AfterViewInit, OnDestroy {
  @Input() shouldOpen = false;
  @Output() passwordUpdated = new EventEmitter<void>();

  changeSecureUserPasswordModal: NgxSmartModalComponent;

  subscriptions = new Subscription();
  constructor(public userState: UserStateService, private ngxSmartModalService: NgxSmartModalService) {}

  ngOnChanges(changes: SimpleChanges): void {
    const currentShouldOpen = changes.shouldOpen?.currentValue;
    if (currentShouldOpen) this.changeSecureUserPasswordModal?.open();
  }

  ngAfterViewInit(): void {
    this.changeSecureUserPasswordModal = this.ngxSmartModalService.getModal('changeSecureUserPasswordModal');
    this.subscriptions.add(
      this.changeSecureUserPasswordModal.onEscape.subscribe(() => this.closeChangePasswordModal(null))
    );
  }

  closeChangePasswordModal = (newPassword: string): void => {
    if (newPassword) this.passwordUpdated.emit();
    this.changeSecureUserPasswordModal.close();
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
