import { Component, Input, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { CharactersValidator } from '../../utils/characters-validator.service';
import { DecimalComponent } from '../decimal/decimal.component';

@Component({
  selector: 'app-currency',
  templateUrl: './currency.component.html',
  styleUrls: ['./currency.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class CurrencyComponent extends DecimalComponent {
  @Input() fieldId: string = '';

  constructor(translateService: TranslateService, validator: CharactersValidator) {
    super(translateService, validator);
  }

  onKeydown(event: any) {
    this.validator.allowDecimalOnly(event);
    super.onKeydown(event);
  }
}
