import { Component, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { FieldDefinition, MetaDataType } from 'shared-code-lib';
import { IPAddressRange } from '../../InterFAX/Models/admin';
import { InterFAXService } from '../../services/interfax.service';
import { ApiResults } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-interfax-iprange-modal',
  templateUrl: './interfax-iprange-modal.component.html',
  styleUrls: ['./interfax-iprange-modal.component.scss'],
})
export class InterfaxIprangeModalComponent implements OnInit {
  @ViewChild('spinnerElement', { static: true })
  spinnerElement;

  @Output() closeModal = new EventEmitter();

  fieldName: FieldDefinition;
  fieldFrom: FieldDefinition;
  fieldTo: FieldDefinition;

  range: IPAddressRange;

  title: string;

  show = false;
  errors = new Array<string>();

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private interfaxService: InterFAXService,
    private toastrService: ToastrService
  ) {}

  ngOnInit(): void {
    this.createFields();

    const id = this.sharedDataService.extraParameters ? this.sharedDataService.extraParameters.id : '';

    if (id) {
      this.title = this.translateService.instant('ip-range.title-existing');
      this.spinnerService.show(this.translateService.instant('Common.Loading'), this.spinnerElement.nativeElement);
      this.interfaxService.getIPAddressRange(id, this.loaded, this.loadFailed);
    } else {
      this.title = this.translateService.instant('ip-range.title-new');
      this.show = true;
      this.range = new IPAddressRange();
    }
  }

  loaded = (r: IPAddressRange): void => {
    this.spinnerService.hide();
    this.range = r;
    this.show = true;
  };

  loadFailed = (err: Error): void => {
    this.spinnerService.hide();
  };

  close = (): void => {
    this.show = false;
    this.closeModal.emit();
  };

  save = (): void => {
    this.spinnerService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);
    this.interfaxService.setIPAddressRange(this.range, this.saved, this.saveFailed);
  };

  saved = (r: ApiResults): void => {
    this.spinnerService.hide();

    if (r.success) {
      this.close();
      if (!this.range.id) {
        this.toastrService.success(this.translateService.instant('ip-range.ip-created'));
      } else {
        this.toastrService.success(this.translateService.instant('ip-range.ip-saved'));
      }
      this.sharedDataService.actionHandler.reload.emit(false);
    } else {
      this.errors = r.errors;
    }
  };

  saveFailed = (err: Error): void => {
    this.spinnerService.hide();
    this.errors.push(err.message);
  };

  cancel = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  createFields = (): void => {
    this.fieldName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('ip-range.name'),
      placeholder: this.translateService.instant('ip-range.name-placeholder'),
      required: true,
    });

    this.fieldFrom = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('ip-range.from'),
      placeholder: this.translateService.instant('ip-range.from-placeholder'),
      required: true,
    });

    this.fieldTo = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('ip-range.to'),
      placeholder: this.translateService.instant('ip-range.to-placeholder'),
      required: true,
    });
  };
}
