import { Component, OnInit, OnDestroy, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Params, Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { TranslateService } from '@ngx-translate/core';

import { FieldDefinition } from './../../models/field-definition';
import { MetaDataType } from './../../models/metadata-definition';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { AuthService } from '../../services/auth/auth.service';
import { Log } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { BrandingService } from '../../services/branding.service';
import { BambaDetailsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/bamba-details.service';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { LoginBaseComponent } from '../login-base/login-base.component';
import { SessionStorageService } from '../../services/session-storage.service';
import { ToastrService } from 'ngx-toastr';
import { SharedDataService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/shared-data.service';
import { ApiResult } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/models';
import { HydraApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';
import { PasswordPolicy } from '../../models/tenant';

@Component({
  selector: 'app-reset-password',
  templateUrl: './reset-password.component.html',
  styleUrls: ['./reset-password.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class ResetPasswordComponent extends LoginBaseComponent implements OnInit, OnDestroy {
  errorOccurred: boolean = false;
  errorText: string = '';
  passwordReset: boolean = false;

  password = '';
  confirmPassword = '';
  resetCode = '';

  fieldPassword: FieldDefinition;
  fieldConfirmPassword: FieldDefinition;

  subscriptions = new Subscription();

  passwordPolicy: PasswordPolicy;
  passwordPolicyLoaded: boolean;

  constructor(
    hydraApi: HydraApiService,
    private route: ActivatedRoute,
    userStateService: UserStateService,
    authService: AuthService,
    spinnerStateService: SpinnerStateService,
    translateService: TranslateService,
    bds: BambaDetailsService,
    sss: SessionStorageService,
    bs: BrandingService,
    r: Router,
    private toastr: ToastrService,
    private sharedDataService: SharedDataService
  ) {
    super(hydraApi, spinnerStateService, translateService, authService, bds, userStateService, sss, bs, r);
  }

  ngOnInit() {
    super.ngOnInit();
    this.route.data.subscribe((data) => {
      if (!data?.passwordExpired) this.changePassword();
    });

    this.fieldPassword = new FieldDefinition({
      type: MetaDataType.Password,
      label: this.translateService.instant('Login.password'),
      required: true,
    });

    this.translateService.get('Login.password-placeholder').subscribe((res) => {
      this.fieldPassword.placeholder = res;
    });

    this.fieldConfirmPassword = new FieldDefinition({
      type: MetaDataType.Password,
      label: this.translateService.instant('Login.confirm-password'),
      required: true,
    });

    this.translateService.get('Login.confirm-password-placeholder').subscribe((res) => {
      this.fieldConfirmPassword.placeholder = res;
    });

    this.route.params.subscribe((params: Params) => this.init(params.resetcode));
  }

  init = (resetCode: string): void => {
    if (!resetCode) return;
    this.resetCode = resetCode;

    this.hydraApi.getPasswordPolicyByResetCode(resetCode, this.passwordPolicySucceeded, this.passwordPolicyFailed);
  };

  passwordPolicySucceeded = (pp: PasswordPolicy): void => {
    this.passwordPolicy = pp;
    this.passwordPolicyLoaded = true;
  };

  passwordPolicyFailed = (err: any) => {
    Log.error('ResetPasswordComponent.passwordPolicyFailed', err);
    this.toastr.error(this.translateService.instant('Login.password-policy-load-failed'));
  };

  login = (userName: string): void => {
    this.toastr.success(this.translateService.instant('Login.password-changed'));
    this.sessionStorageService.setUsername(userName);
    this.sharedDataService.extraParameters = this.password;
    this.router.navigateByUrl('/login-password?auto=true');
  };

  reset = (): void => {
    if (this.password != this.confirmPassword) {
      this.errorOccurred = true;
      this.errorText = this.translateService.instant('Login.passwords-donot-match');

      return;
    }

    this.translateService.get('Login.ResettingPassword').subscribe((res) => {
      this.spinnerStateService.show(res, this.loginDivElement);
    });

    this.authService.resetPassword(this.resetCode, this.password, this.resetSucceeded, this.resetFailed);
  };

  resetSucceeded = (res: ApiResult): void => {
    if (res.success) {
      this.spinnerStateService.hide();
      this.login(res.object);
      return;
    }

    this.errorOccurred = true;
    this.errorText = res.errors.join('\n');
    this.spinnerStateService.hide();
  };

  resetFailed = (err): void => {
    Log.error('PasswordHelpComponent.resetFailed', err);
    Log.var(err);

    this.spinnerStateService.hide();
    this.errorOccurred = true;

    if (err.status && err.status == 400 && err.error) {
      this.errorText = err.error;
    } else {
      this.errorText = this.translateService.instant('Login.ResetPasswordFailed');
    }
  };

  changePassword = (): void => {
    this.passwordReset = true;
  };
}
