import { MediaFileType } from '../../../models/media';
import { IApprovalSelection } from '../../../models/approvals';
import { ITemplateVariable, ITemplateVariablesHighlight } from '../../../models/template';
import { ShapeType } from './shape';
import { FieldDefinition } from '../../../../../../../../../Bamba.Shared/src/models/field-definition';

export interface IACF {
  content: string;
  find: string;
  replace: string;
}

export interface IRefreshBackgroundPayload {
  page: number;
  section: ITEDSection;
  items: ITEDItem[];
  conditionalContentSelections: IConditionalContentSelection[];
}

export interface IPayloadTEDSection {
  name: string;
  content: string;
}

export interface ISaveVersionPayload {
  comment: string;
  sections: ITEDSection[];
  items: ITEDItem[];
}

export interface IRequestApprovalPayload {
  comment: string;
}

export interface IApproveOrRejectTemplatesPayload {
  selectedApprovals: IApprovalSelection[];
  comment: string;
}

export interface ISetTemplatesToProductionPayload {
  selectedApprovals: IApprovalSelection[];
}

export interface IDownloadTemplatePayload {
  controlScript: string;
  itemsConditions: string;
  images: DownloadImage[];
  sections: TEDSection[];
}

export interface DownloadImage {
  URL: string;
  fileName: string;
}

export interface IPdfPreviewPayload {
  recordNumber: number;
  sections: ITEDSection[];
  items: ITEDItem[];
}

export interface ITEDItem {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
  rotate: number;
  page: number;
  section: number;
  class: string;
  title: string;
  type: ShapeType;
  texts: ITextItem[];
  images: IImageItem[];
}

export interface ITextItem {
  group: string;
  condition: string;
  from: string;
  to: string;
  text: string;
}

export interface IImageItem {
  group: string;
  condition: string;
  from: string;
  to: string;
  image: string;
  imageName: string;
  type: MediaFileType;
}

export class TEDItem implements ITEDItem {
  id: string = '';
  x: number = 0;
  y: number = 0;
  w: number = 0;
  h: number = 0;
  rotate: number = 0;
  page: number = 0;
  section: number = 0;
  class: string = '';
  title: string = '';
  type: ShapeType = ShapeType.Text;
  texts: ITextItem[] = [];
  images: IImageItem[] = [];
}

export class TextItem implements ITextItem {
  group: string = '';
  condition: string = '';
  from: string = '';
  to: string = '';
  text: string = '';
}

export class ImageItem implements IImageItem {
  group: string = '';
  condition: string = '';
  from: string = '';
  to: string = '';
  image: string = '';
  imageName: string = '';
  type: MediaFileType;
}

export interface ITEDCondition {
  id: string;
  title: string;
  connectScript: string;
  // support old code
  group?: string | boolean;
}

export class Condition implements ITEDCondition {
  id: string = '';
  title: string = '';
  connectScript: string = '';
  // support old code
  group = false;
}

export interface ITEDBody {
  group: string;
  condition: string;
  from: string;
  to: string;
  text: string;
}

export class TEDBody implements ITEDBody {
  group: string = '';
  condition: string = '';
  from: string = '';
  to: string = '';
  text: string = '';
}

export interface ITEDSection {
  name: string;
  id: string;
  index: number;
  leftMargin: number;
  topMargin: number;
  rightMargin: number;
  bottomMargin: number;
  pageSize: string;
  portrait: boolean;
  pages: number;
  width: number;
  height: number;
  content: string;
  backgrounds: IBackground[];
  bodies: ITEDBody[];
}

export interface IBackground {
  from: string;
  to: string;
  group: string;
  condition: string;
  pdfURL: string;
  pdfName: string;
  type: MediaFileType.PDF;
}

export class TEDSection implements ITEDSection {
  name: string = '';
  id: string = '';
  index: number = 0;
  leftMargin: number = 0;
  topMargin: number = 0;
  rightMargin: number = 0;
  bottomMargin: number = 0;
  pageSize: string = '';
  portrait: boolean = false;
  pages: number = 0;
  width: number = 0;
  height: number = 0;
  content: string = '';
  backgrounds: IBackground[] = [];
  bodies: ITEDBody[] = [];
}

export class Background implements IBackground {
  from: string = '';
  to: string = '';
  group: string = '';
  condition: string = '';
  pdfURL: string = '';
  pdfName: string = '';
  type: MediaFileType.PDF;
}

export interface IPayloadImage {
  url: string;
  filename: string;
  type: MediaFileType;
}

export interface IConditionalContentSelection {
  groupName: string;
  value: string;
}

export interface ITEDPayloadState {
  items: ITEDItem[];
  sections: ITEDSection[];
}

export interface MousePosition {
  x: number;
  y: number;
}

export interface IConnectTemplate {
  options: any;
  package: any;
  recordCount: number;
}

export enum LengthUnit {
  CM = 'cm',
  IN = 'in',
  MM = 'mm',
  PT = 'pt',
  PC = 'pc',
  PX = 'px',
}

export interface MediaPreviewData {
  url: string;
  name: string;
  type: MediaFileType;
}

export enum ItemToAddOrEdit {
  Text = 'texts',
  Image = 'images',
  Background = 'background',
  BodyText = 'body text',
}

export enum MediaType {
  All,
  PDF,
  Image,
}

export class ConditionalGroup {
  title: string;
  field: FieldDefinition;
  value: string;
}
