import { Component, Input, OnDestroy, OnInit } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { SortDescriptor } from '@progress/kendo-data-query';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import {
  ColumnDisplayType,
  DelayService,
  FieldDefinition,
  FixedDataSource,
  ICombinedColumn,
  IFieldOptions,
  InvokeAction,
  MetaDataType,
  TableItem,
} from 'shared-code-lib';
import { FaxUserStatus, Group, IFaxUser } from '../../../InterFAX/Models/admin';
import { DocumentEntityType, InboundDocument, SharePermissions, ShareWith } from '../../../InterFAX/Models/inbound';
import { InterfaxDocumentSharingService } from '../../../services/interfax-document-sharing.service';
import { InterFAXService } from '../../../services/interfax.service';
import { SpinnerStateService } from '../../../services/spinner-state.service';
import { UserStateService } from '../../../services/user-state.service';

@Component({
  selector: 'app-document-properties-sharing',
  templateUrl: './document-properties-sharing.component.html',
  styleUrls: ['./document-properties-sharing.component.scss'],
})
export class DocumentPropertiesSharingComponent implements OnInit, OnDestroy {
  @Input() document: InboundDocument;
  items: TableItem[] = [];
  columns: ICombinedColumn[];
  sort: SortDescriptor;
  entityIcons: Array<string> = ['fa-user fa-lg', 'fa-users fa-lg', 'fa-globe fa-lg'];

  permissionDataSource: FixedDataSource;
  entityDataSource: InterFAXEntityDataSource;

  fieldEntities: FieldDefinition;
  fieldPermissions: FieldDefinition;

  entity = '';
  permissions = SharePermissions.View;

  entities = new Array<ShareWith>();
  itemsLoaded: boolean;
  renderFields = true;

  subscriptions = new Subscription();

  get permissionsString() {
    return this.permissions.toString();
  }

  set permissionsString(val: string) {
    this.permissions = Number(val);
  }

  get permissionsSelected() {
    return this.getPermissionsOptions()
      .map((option) => option.value)
      .includes(this.permissions.toString());
  }

  get disableAddSharing() {
    return !this.entity || !this.permissionsSelected;
  }

  constructor(
    private translateService: TranslateService,
    private interfaxService: InterFAXService,
    private spinnerService: SpinnerStateService,
    private delayService: DelayService,
    private toastr: ToastrService,
    private userState: UserStateService,
    private interfaxDocumentSharingService: InterfaxDocumentSharingService
  ) {}

  ngOnInit(): void {
    this.columns = this.getColumns();
    this.sort = { field: '1', dir: 'asc' };

    this.loadEntitiesSources();
    this.permissionDataSource = new FixedDataSource(this.getPermissionsOptions());
  }

  loadEntitiesSources = (): void => {
    this.spinnerService.show(
      this.translateService.instant('Common.LoadingData'),
      document.getElementById('spinnerElement')
    );
    this.subscriptions.add(this.interfaxService.getGroups(this.groupsLoaded, this.failed));
  };

  deleteItem(action: InvokeAction) {
    const ti: TableItem = action.item;
    const sw: ShareWith = ti.data;

    this.document.sharing = this.document.sharing.filter((s) => s.entity != sw.entity || s.entityType != sw.entityType);
    this.items = this.createItems();
  }

  onAddSharing = (): void => {
    if (this.disableAddSharing) return;

    const sw: ShareWith = new ShareWith(JSON.parse(this.entity));
    sw.permissions = this.permissions;

    const addingEveryoneDuplicate = this.document.sharing.find((swEntity) => {
      return swEntity.name == sw.name && sw.entity == '';
    });

    if (addingEveryoneDuplicate) {
      this.toastr.info(this.translateService.instant('admin-inbound-fax-settings.everyone-option-already-added'));
      return;
    }

    this.document.sharing = [...this.document.sharing.filter((s) => !s.equals(sw)), sw];
    this.items = this.createItems();

    this.entity = '';
    this.rerenderFieldsInUI();
    this.onEntityChanged(true);
  };

  createFields = (): void => {
    this.fieldEntities = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('interfax-queue.sharing-entities'),
      placeholder: '',
      required: false,
      datasource: this.entityDataSource,
    });

    this.fieldPermissions = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('interfax-queue.sharing-permissions'),
      placeholder: '',
      required: false,
      datasource: this.permissionDataSource,
    });
  };

  rerenderFieldsInUI() {
    this.renderFields = false;
    this.delayService.execute(() => {
      this.renderFields = true;
    }, 10);
  }

  createItems = (): Array<TableItem> => {
    const items = new Array<TableItem>();

    for (const sw of this.document.sharing) {
      if ((sw.permissions & SharePermissions.Owner) == SharePermissions.Owner) continue;

      items.push(this.createTableItem(sw));
    }

    return items.sort((x, y) => x.data.name.localeCompare(y.data.name));
  };

  getColumns(): Array<ICombinedColumn> {
    const columns: Array<ICombinedColumn> = [];

    columns.push(this.createColumn('type', ColumnDisplayType.FontAwesome, '', 32, 'icon'));

    columns.push(
      this.createColumn(
        'destination',
        ColumnDisplayType.Text,
        this.translateService.instant('admin-inbound-fax-settings.column-destination'),
        200,
        'name'
      )
    );

    columns.push(
      this.createColumn(
        'permissions',
        ColumnDisplayType.Text,
        this.translateService.instant('admin-inbound-fax-settings.column-permissions'),
        200,
        'permissionsText',
        true
      )
    );

    return columns;
  }

  createColumn(
    id: string,
    displayType: number,
    columnName: string,
    width: number,
    itemProperty: string,
    stretch = false
  ) {
    return {
      id: 'column_' + id,
      width: width,
      stretch: stretch,
      displayType: displayType,
      headerImage: '',
      headerText: columnName,
      itemProperty: itemProperty,
      columnName: columnName,
      sortable: false,
      sortByFieldName: '',
      invertBooleanValue: false,
    };
  }

  createTableItem(shareWith: ShareWith): TableItem {
    this.setColumnData(shareWith);
    const tableItem = new TableItem(shareWith, this.columns, this.translateService);

    tableItem.data.defaultAction = {
      name: this.translateService.instant('admin-inbound-fax-settings.edit-share'),
    };

    return tableItem;
  }

  setColumnData(shareWith: ShareWith) {
    shareWith['icon'] = this.entities.find((a) => a.equals(shareWith))
      ? this.entities.find((a) => a.equals(shareWith))['icon']
      : this.entityIcons[shareWith.entityType - 1];

    this.setPermissionText(shareWith);
  }

  setPermissionText(shareWith: ShareWith) {
    const option = this.interfaxDocumentSharingService.options.find(
      (o) => o.value === shareWith.permissions.toString()
    );

    shareWith['permissionsText'] = option.name;
  }

  getPermissionsOptions = (): Array<IFieldOptions> => {
    if (this.entityExistsAndEmpty()) return [this.interfaxDocumentSharingService.options[0]];
    return this.interfaxDocumentSharingService.options;
  };

  failed = () => {
    this.spinnerService.hide();
  };

  groupsLoaded = (groups: Array<Group>) => {
    this.entities = groups.map((g) => {
      const shareUser = new ShareWith();
      shareUser.entity = g.id;
      shareUser.name = g.name;
      shareUser.entityType = DocumentEntityType.Group;
      shareUser['icon'] = 'fa-users';
      return shareUser;
    });

    this.addEveryone();

    this.entityDataSource = new InterFAXEntityDataSource(this.interfaxService, this.userState, this.entities);

    this.loaded();
  };

  loaded = (): void => {
    this.createFields();

    this.items = this.createItems();
    this.itemsLoaded = true;
    this.spinnerService.hide();
  };

  addEveryone = () => {
    const everyone = new ShareWith();
    everyone.entity = '';
    everyone.name = this.translateService.instant('admin-inbound-fax-settings.everyone');
    everyone.entityType = DocumentEntityType.Account;
    everyone['icon'] = 'fa-globe';
    this.entities.push(everyone);
  };

  onEntityChanged = (resetPermissions = false): void => {
    this.permissionDataSource.updateOptions(this.getPermissionsOptions());
    if (this.entityExistsAndEmpty() || resetPermissions) this.permissions = SharePermissions.View;
  };

  entityExistsAndEmpty = () => {
    return this.entity && (JSON.parse(this.entity) as ShareWith).entity == '';
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}

export class InterFAXEntityDataSource extends FixedDataSource {
  constructor(
    private interfaxService: InterFAXService,
    private userState: UserStateService,
    private entities: Array<ShareWith>
  ) {
    super();
  }

  successCallBack: (items: IFieldOptions[]) => void;
  failureCallBack: (err: any) => void;

  getItems(
    startsWith: string,
    currentValue: string,
    successCallBack: (items: IFieldOptions[]) => void,
    failureCallBack: (err: any) => void
  ): void {
    this.successCallBack = successCallBack;
    this.failureCallBack = failureCallBack;

    this.interfaxService.getFaxUsers(this.usersLoaded, this.failed, startsWith, FaxUserStatus.Open, [
      this.userState.interFAXUsername.trim(),
    ]);
  }

  usersLoaded = (users: Array<IFaxUser>): void => {
    const options = new Array<IFieldOptions>();

    let userShareWith = users.map((u) => {
      const shareUser = new ShareWith();
      shareUser.entity = u.userId;
      shareUser.name = u.userId;
      shareUser.entityType = DocumentEntityType.User;
      shareUser['icon'] = u.iconUrl;
      return shareUser;
    });

    let allEntities = this.entities.concat(userShareWith);

    allEntities = allEntities.filter(
      (shareWith) =>
        !(
          shareWith.entityType === DocumentEntityType.User &&
          shareWith.entity.trim() === this.userState.interFAXUsername.trim()
        )
    );

    for (const sw of allEntities) {
      options.push({ name: sw.name, value: JSON.stringify(sw) });
    }

    options.sort((x, y) => x.name.localeCompare(y.name));

    this.successCallBack(options);
  };

  failed = (err): void => {
    this.failureCallBack(err);
  };
}
