import { Component, Input, OnInit } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { IMoneyAmount, MoneyAmount } from 'shared-code-lib';

@Component({
  selector: 'app-payment-receipt',
  templateUrl: './payment-receipt.component.html',
  styleUrls: ['./payment-receipt.component.scss'],
})
export class PaymentReceiptDetailsComponent implements OnInit {
  @Input() details: any;

  amount: IMoneyAmount;
  cardType: string;

  constructor(private translate: TranslateService) {}

  ngOnInit() {
    this.amount = new MoneyAmount(this.details?.amount);
    this.cardType = this.translate.instant(`product-details.billing.card-types.${this.details.cardType}`);
  }
}
