import { Injectable } from '@angular/core';
import { ResizeObserver as ResizeObserverPolyfill } from '@juggle/resize-observer';
import { TranslateService } from '@ngx-translate/core';
import { Subject } from 'rxjs';
import { ISpinnerService } from 'shared-code-lib';

const ResizeObserver = window.ResizeObserver || ResizeObserverPolyfill;

@Injectable({
  providedIn: 'root',
})
export class SpinnerStateService implements ISpinnerService {
  private visible: boolean = false;
  private element: HTMLElement = null;
  private text: string = '';
  private messages: Array<string> = [];

  visibilityChanged = new Subject<any>();

  private resizeObserver = new ResizeObserver((entries) => this.display());

  constructor(private translate: TranslateService) {}

  show(text: string, element?: HTMLElement) {
    this.visible = true;
    this.element = element;
    this.text = text;
    this.messages.unshift(text);

    if (!this.element) return;

    this.element.ownerDocument.defaultView.addEventListener('resize', this.display);
    this.resizeObserver.observe(this.element);

    this.display();
  }

  private display = () => {
    var configuration: any = {};

    configuration.text = this.text;
    configuration.visible = this.visible;

    if (!this.element) return;

    var elemRect = this.element.getBoundingClientRect();

    configuration.top = elemRect.top + window.pageYOffset;
    configuration.left = elemRect.left;
    configuration.height = elemRect.height;
    configuration.width = elemRect.width;

    this.visibilityChanged.next(configuration);
  };

  hide(msg?: string) {
    if (msg) {
      const index = this.messages.findIndex((x) => x == msg);
      if (index != -1) this.messages.splice(index, 1);
    } else {
      this.messages = [];
    }

    if (this.messages.length) {
      if (msg == this.text) this.text = this.messages[0];
      return;
    }

    if (this.element != null) {
      this.element.ownerDocument.defaultView.removeEventListener('resize', this.display);
      this.resizeObserver.unobserve(this.element);
    }

    this.visible = false;
    this.element = null;

    var configuration: any = {};
    configuration.visible = this.visible;

    this.visibilityChanged.next(configuration);
  }

  isVisible(): boolean {
    return this.visible;
  }

  showSavingSpinner(resourceId?: string) {
    this.show(this.translate.instant(resourceId ? resourceId : 'Common.Saving'), document.documentElement);
  }
}
