import { CdkDragDrop, moveItemInArray } from '@angular/cdk/drag-drop';
import {
  AfterViewInit,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  SimpleChange,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { cloneDeep } from 'lodash';
import { DeviceDetectorService } from 'ngx-device-detector';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { ToastrService } from 'ngx-toastr';
import { Subscription, fromEvent } from 'rxjs';
import { take } from 'rxjs/operators';
import { Capture, ICapture, IEditCapturesData, ScanResult } from '../../models/scanner';
import { WebScannerService } from '../../services/web-scanner.service';
import { loadOpenCV } from '../../utils/opencv-loader';

@Component({
  selector: 'app-document-scanner',
  templateUrl: './document-scanner.component.html',
  styleUrls: ['./document-scanner.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class DocumentScannerComponent implements OnChanges, OnInit, OnDestroy, AfterViewInit {
  private _captures: ICapture[] = [];

  @Input()
  get captures(): ICapture[] {
    return this._captures;
  }
  set captures(captures: ICapture[]) {
    this._captures = captures?.length ? cloneDeep(captures) : [];
  }

  @Input() shouldPauseCamera = false;

  @ViewChild(PerfectScrollbarDirective, { static: false })
  scrollbar?: PerfectScrollbarDirective;

  @Output() done = new EventEmitter<ICapture[]>();
  @Output() close = new EventEmitter();
  @Output() edit = new EventEmitter<IEditCapturesData>();

  video: HTMLVideoElement;
  stream: MediaStream = null;
  videoCapture = null;
  frameRate = 30;

  useAutoCapturing = false;
  scanResult = ScanResult.NoDocument;
  autoCropTimeoutId: any;

  availableCameras: MediaDeviceInfo[] = [];
  activeCameraIndex = 0;
  loadingCameraError = false;

  subscriptions = new Subscription();

  get isVideoClosed() {
    return !this.video?.srcObject;
  }

  get isVideoStreaming() {
    return !this.isVideoClosed && !this.video.paused;
  }

  get isVideoPaused() {
    return !this.isVideoClosed && this.video.paused;
  }

  constructor(
    private scanner: WebScannerService,
    private translateService: TranslateService,
    private toastr: ToastrService,
    private cdr: ChangeDetectorRef,
    private deviceDetectorService: DeviceDetectorService
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    const shouldPauseCamera: SimpleChange = changes.shouldPauseCamera;

    if (shouldPauseCamera !== undefined && !shouldPauseCamera.firstChange) {
      if (shouldPauseCamera.currentValue && this.isVideoStreaming) {
        this.video?.pause();
      }

      if (!shouldPauseCamera.currentValue && this.isVideoPaused) {
        try {
          this.video?.play();
        } catch (error) {
          this.toastr.error(error);
        }
      }
    }
  }

  ngOnInit() {}

  ngAfterViewInit(): void {
    loadOpenCV(
      {
        asm: window.location.origin + '/assets/js/opencv/opencv.js',
      },
      () => {
        this.InitScanner();
      },
      () => {
        this.toastr.error(this.translateService.instant('document-scanner.error-happened'));
      }
    ).catch((error) => this.toastr.error(error));
  }

  async InitScanner() {
    await this.scanner.initScanner();

    this.video = document.getElementById('video')! as HTMLVideoElement;

    this.subscriptions.add(
      fromEvent(document, 'visibilitychange').subscribe(() => {
        if (document.visibilityState === 'visible') {
          try {
            this.video.play();
          } catch (error) {
            this.toastr.error(error);
          }
        } else {
          this.video.pause();
        }
      })
    );

    this.subscriptions.add(
      fromEvent(this.video, 'play').subscribe(() => {
        setTimeout(this.processVideo, 0);
      })
    );

    await this.getAvailableCameras();
    this.openCamera();
  }

  getAvailableCameras() {
    return navigator.mediaDevices
      .getUserMedia({
        video: {
          facingMode: 'environment',
        },
        audio: false,
      })
      .then(() => navigator.mediaDevices.enumerateDevices())
      .then((devices) => devices.filter((device) => device.kind.toLowerCase() === 'videoinput'))
      .then((cameras) => {
        const rearCameras = cameras.filter((camera) => camera.label.toLowerCase().includes('back'));
        this.availableCameras = rearCameras.length ? rearCameras : cameras;

        if (!this.availableCameras.length)
          throw new Error(this.translateService.instant('document-scanner.no-available-cameras'));

        this.activeCameraIndex = 0;

        return;
      })
      .catch((error: any) => {
        this.toastr.error(error);
      });
  }

  openCamera = () => {
    const activeCamera = this.availableCameras[this.activeCameraIndex];
    if (!activeCamera) return;

    this.loadingCameraError = false;

    return navigator.mediaDevices
      .getUserMedia({
        video: {
          deviceId: { exact: activeCamera.deviceId },
          width: { ideal: 3840 },
          height: { ideal: 2160 },
          frameRate: { exact: this.frameRate },
        },
        audio: false,
      })
      .then((stream) => {
        this.video.srcObject = stream;
        this.stream = stream;
        this.cdr.detectChanges();

        fromEvent(this.video, 'canplay')
          .pipe(take(1))
          .subscribe(() => {
            this.loadingCameraError = false;
            this.video.width = this.video.videoWidth;
            this.video.height = this.video.videoHeight;
            const isTouchDevice = this.deviceDetectorService.isMobile() || this.deviceDetectorService.isTablet();
            this.scanner.circleRadius = +((isTouchDevice ? 0.12 : 0.05) * this.video.width).toFixed(1);
            this.scanner.lineThickness = +(0.003 * this.video.width).toFixed(1);
            this.video.play();
            this.videoCapture = new this.scanner.cv.VideoCapture(this.video);
            this.cdr.detectChanges();
          });
      })
      .catch((error) => {
        this.loadingCameraError = true;
        this.toastr.error(error);
        this.cdr.detectChanges();
      });
  };

  switchCamera() {
    this.activeCameraIndex++;
    if (this.activeCameraIndex > this.availableCameras.length - 1) this.activeCameraIndex = 0;

    this.restartCamera();
  }

  restartCamera() {
    this.stopCamera();
    this.openCamera();
  }

  processVideo = () => {
    if (this.isVideoClosed || this.isVideoPaused) return;

    const startProcessingTime = Date.now();

    try {
      if (!this.useAutoCapturing) {
        this.scanner.renderOriginalVideo(this.videoCapture);
      }

      if (this.useAutoCapturing) {
        this.scanResult = this.scanner.highlightDocument(this.videoCapture);
        const shouldAutoCrop = this.scanResult === ScanResult.ReadyDocument;

        this.cdr.detectChanges();

        if (shouldAutoCrop && this.autoCropTimeoutId === undefined) {
          this.autoCropTimeoutId = setTimeout(() => {
            if (!shouldAutoCrop) {
              this.removeAutoCroppingListener();
              return;
            }

            this.captureDocument();
            this.toggleCapturingMode();
            this.cdr.detectChanges();
          }, 1000);
        } else if (!shouldAutoCrop && this.autoCropTimeoutId !== undefined) {
          this.removeAutoCroppingListener();
        }
      }
    } catch (error) {
      this.toastr.error(error);
      return;
    }

    setTimeout(this.processVideo, 1000 / this.frameRate - (Date.now() - startProcessingTime));
  };

  stopCameraAndFireCloseEvent = () => {
    this.close.emit();
    this.stopCamera();
  };

  stopCamera() {
    this.removeAutoCroppingListener();
    this.resetVideo();
  }

  resetVideo() {
    if (!this.video) return;

    const stream = this.video.srcObject as MediaStream;
    this.video.pause();
    this.video.srcObject = null;

    if (!stream) return;
    stream.getVideoTracks()[0].stop();
  }

  toggleCapturingMode() {
    this.useAutoCapturing = !this.useAutoCapturing;
    this.scanResult = ScanResult.NoDocument;
    this.removeAutoCroppingListener();
  }

  captureDocument() {
    this.captures.push(new Capture(this.scanner.extractOriginalAndDefaultCroppedDocuments(this.videoCapture)));

    this.cdr.detectChanges();
    this.scrollbar?.scrollToRight();
  }

  removeAutoCroppingListener() {
    if (!this.autoCropTimeoutId) return;

    clearTimeout(this.autoCropTimeoutId);
    this.autoCropTimeoutId = undefined;
  }

  drop(event: CdkDragDrop<string[]>) {
    moveItemInArray(this.captures, event.previousIndex, event.currentIndex);
  }

  deleteImage(index: number) {
    this.captures = this.captures.filter((_, i) => i !== index);
    this.scrollbar?.update();
  }

  editCapture(index: number) {
    this.edit.emit({
      captures: this.captures,
      indexToEdit: index,
    });
  }

  generateDocumentAndClose() {
    this.done.emit(this.captures);
    this.stopCameraAndFireCloseEvent();
  }

  ngOnDestroy(): void {
    this.stopCamera();
    this.subscriptions.unsubscribe();
    if (this.videoCapture) this.videoCapture = null;
  }
}
