import { Component, Input, OnInit, ViewEncapsulation } from '@angular/core';
import { SpinnerStateService } from '../../services/spinner-state.service';
// import { ToastrService } from 'ngx-toastr';
// import { ApiService } from '../../services/api.service';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { IMobileAction, MetaDataCollection } from 'shared-code-lib';
import { Filter } from '../../models/filter';
import { SelectOptionActionResult } from '../../models/select-option-action-result';
import { SharedDataService } from '../../services/shared-data.service';

@Component({
  selector: 'app-options-modal',
  templateUrl: './options-modal.component.html',
  styleUrls: ['./options-modal.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class OptionsModalComponent implements OnInit {
  @Input() data: SelectOptionActionResult;
  modal: any;

  constructor(
    private spinnerService: SpinnerStateService,
    private sharedDataService: SharedDataService,
    public ngxSmartModalService: NgxSmartModalService
  ) {}

  ngOnInit(): void {
    this.modal = this.ngxSmartModalService.getModal('selectOptionModal');
  }

  close = (): void => {
    this.modal?.close();
  };

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.options .nsm-content') as HTMLElement;
  }

  select(option: IMobileAction): void {
    const args = new MetaDataCollection();

    args.set('option', option.id);
    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.data.extraParameters.ids,
      args,
      this.close,
      this.close,
      true,
      this.data.extraParameters.filters.map((x) => new Filter({ id: x.id, value: x.value }))
    );
  }
}
