import { Component, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Subscription } from 'rxjs';
import { FieldDefinition, FixedDataSource, IFieldOptions, MetaDataType } from 'shared-code-lib';
import { Filter } from '../../models/filter';
import { FilterBaseComponent } from '../filter-base.component';

@Component({
  selector: 'app-filter-by-list-property',
  templateUrl: './filter-by-list-property.component.html',
  styleUrls: ['./filter-by-list-property.component.scss'],
})
export class FilterByListPropertyComponent extends FilterBaseComponent implements OnInit, OnChanges, OnDestroy {
  @Input() filter: Filter;
  @Input() layoutVertically: boolean;
  @Input() options: Array<IFieldOptions> = [];
  @Input() dataSourceAsync: FixedDataSource;
  @Input() smallLabel: string;
  @Input() label: string;
  @Output() selected = new EventEmitter<string>();

  fieldOptions: FieldDefinition;

  subscriptions = new Subscription();

  constructor(private translate: TranslateService) {
    super();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.options && this.fieldOptions?.datasource) {
      (<FixedDataSource>this.fieldOptions.datasource).updateOptions(this.options);
    }
  }

  ngOnInit(): void {
    this.fieldOptions = new FieldDefinition({
      type: MetaDataType.List,
      label: this.label ? this.translate.instant(this.label) : '',
      smallLabel: this.smallLabel ? this.translate.instant(this.smallLabel) : '',
      placeholder: '',
      required: false,
      datasource: this.dataSourceAsync || new FixedDataSource(this.options),
      hideLabel: true,
    });

    this.subscriptions.add(this.filter.clearFilter.subscribe(this.clearFilter));

    if (this.dataSourceAsync) this.updateFieldOptions(this.filter.value);
  }

  clearFilter = (): void => {
    const value = this.filter?.defaultValue || '';
    this.setValue(value);

    if (!this.dataSourceAsync) return;

    this.updateFieldOptions(value);
  };

  onFieldChanged = (value: string): void => {
    if (this.filter.value !== value) {
      this.filter.value = value;
      this.selected.emit(value);
    }

    if (!this.dataSourceAsync) return;

    this.updateFieldOptions(value);
  };

  updateFieldOptions = (value: string) => {
    if (!this.fieldOptions) return;

    this.fieldOptions.defaultValue = value;
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
