export class Recipient {
  private static _id = 0;

  id: number;
  type: SendFaxRecipientType;

  constructor() {
    this.id = Recipient._id++;
  }

  getDisplayName = (): string => {
    return '';
  };

  clone = (): Recipient => {
    return null;
  };

  copyFrom = (r: Recipient): void => {};
}

export enum recipientDialogState {
  Edit = 'Edit',
  New = 'New',
}

export class Individual extends Recipient {
  constructor(
    public name: string,
    public faxnumber: string,
    public company: string,
    public phoneNumber: string,
    public saveToContactListId = null,
    cloneId?: number,
    public contactListId = null
  ) {
    super();

    if (cloneId) {
      this.id = cloneId;
    }

    this.type = SendFaxRecipientType.Recipient;
  }

  getDisplayName = (): string => {
    if (this.name) {
      return `${this.name} (${this.faxnumber})`;
    }

    return this.faxnumber;
  };

  clone = (): Recipient => {
    return new Individual(
      this.name,
      this.faxnumber,
      this.company,
      this.phoneNumber,
      this.saveToContactListId,
      this.id,
      this.contactListId
    );
  };

  copyFrom = (r: Recipient): void => {
    const individual = <Individual>r;

    this.name = individual.name;
    this.faxnumber = individual.faxnumber;
    this.saveToContactListId = individual.saveToContactListId;
    this.contactListId = individual.contactListId;
    this.type = SendFaxRecipientType.Recipient;
  };
}

export class ContactListRecipient extends Recipient {
  constructor(public name: string, public contactListId: string) {
    super();

    if (name) {
      this.name = name;
    }

    if (Strings.notEmpty(contactListId)) this.id = parseInt(contactListId);

    this.type = SendFaxRecipientType.ContactList;
  }

  getDisplayName = (): string => {
    return this.name;
  };

  clone = (): ContactListRecipient => {
    return new ContactListRecipient(this.name, this.contactListId);
  };

  copyFrom = (cl: Recipient): void => {
    this.id = (<ContactListRecipient>cl).id;
    this.name = (<ContactListRecipient>cl).name;
    this.contactListId = (<ContactListRecipient>cl).contactListId;
    this.type = SendFaxRecipientType.ContactList;
  };
}

export interface IFaxForm {
  recipients: Recipient[];
  message: string;
  subject: string;
  attachedItems: any[];
  faxPageSettings: IFaxPageSettings;
  coverPageId: number;
  coverPage: CoverPage;
}

export class FaxForm implements IFaxForm {
  recipients: Recipient[] = [];
  message = '';
  subject = '';
  faxPageSettings = new FaxPageSettings();
  attachedItems: any[] = [];
  coverPageId: number;
  coverPage: CoverPage;
  onFormClear = new Subject<void>();
  hasHtmlValue: () => boolean;

  constructor(item) {
    this.recipients = item.recipients ? item.recipients : this.recipients;
    this.message = item.message || this.message;
    this.subject = item.subject || this.subject;
    this.faxPageSettings = item.faxPageSettings || this.faxPageSettings;
    this.attachedItems = item.attachedItems ? item.attachedItems : this.attachedItems;
    this.coverPage = item.coverPage;
    this.coverPageId = item.coverPageId;
    this.hasHtmlValue = item.hasHtmlValue;
  }

  clear() {
    this.subject = '';
    this.message = '';
    this.attachedItems = [];
    this.recipients = [];
    this.faxPageSettings = new FaxPageSettings();
    this.onFormClear.next();
  }

  hasChanges() {
    if (this.subject) return true;
    if (this.message) return true;
    if (this.attachedItems && this.attachedItems.length) return true;
    if (this.recipients && this.recipients.length) return true;
    if (this.faxPageSettings.hasChanges()) return true;
  }

  serializable(): IFaxForm {
    return {
      recipients: this.recipients,
      message: this.getFaxMessage(),
      subject: this.subject,
      attachedItems: this.attachedItems,
      faxPageSettings: this.faxPageSettings.serializable(),
      coverPageId: this.coverPageId,
      coverPage: this.coverPage,
    };
  }

  getFaxMessage = (): string => {
    if (this?.coverPage?.coverpageBodyType == CoverPageBodyType.Text) return this.message;
    if (this?.coverPage?.coverpageBodyType == CoverPageBodyType.Html) return this.hasHtmlValue() ? this.message : '';

    return this.message;
  };
}

export interface IFaxPageSettings {
  faxCSID: string;
  numberOfAttempts: string;
  pageOrientation: string;
  renderingOptimization: string;
  resolution: string;
  pageSize: string;
  saveAsDefault: boolean;
  sendAfter: boolean;
  sendAfterDateTime: Date;
  feedbackEmail: string;
}

export class FaxPageSettings implements IFaxPageSettings {
  faxCSID: string = '';
  numberOfAttempts: string = '';
  pageOrientation: string = '';
  renderingOptimization: string = '';
  resolution: string = '';
  pageSize: string = '';
  saveAsDefault: boolean = false;
  sendAfter: boolean = false;
  sendAfterDateTime: Date;
  feedbackEmail: string;

  public clear() {
    this.faxCSID = '';
    this.numberOfAttempts = '';
    this.pageOrientation = '';
    this.renderingOptimization = '';
    this.resolution = '';
    this.pageSize = '';
    this.sendAfter = false;
    this.saveAsDefault = false;
    this.sendAfterDateTime = new Date();
    this.feedbackEmail = '';
  }

  public hasChanges() {
    if (this.faxCSID) return true;
    if (this.numberOfAttempts) return true;
    if (this.pageOrientation) return true;
    if (this.renderingOptimization) return true;
    if (this.resolution) return true;
    if (this.pageSize) return true;
    if (this.feedbackEmail) return true;
    if (this.saveAsDefault) return true;

    return false;
  }

  serializable(): IFaxPageSettings {
    return {
      faxCSID: this.faxCSID,
      numberOfAttempts: this.numberOfAttempts,
      pageOrientation: this.pageOrientation,
      renderingOptimization: this.renderingOptimization,
      resolution: this.resolution,
      pageSize: this.pageSize,
      saveAsDefault: this.saveAsDefault,
      sendAfter: this.sendAfter,
      sendAfterDateTime: this.sendAfterDateTime,
      feedbackEmail: this.feedbackEmail,
    };
  }
}

export enum SendFaxRecipientType {
  Recipient = 0,
  ContactList = 1,
}

export enum SubstitutionUseFlag {
  SendFax = 1 << 0,
  Templates = 1 << 1,
}

export interface ISubstitution {
  markerText: string;
  displayName: string;
  icon: string;
  hasSubstitutionMarkers(text: string): boolean;
  useFlags: SubstitutionUseFlag;
  requiredFeatures: string[];
}

export class Substitution implements ISubstitution {
  public markerText: string;
  public displayName: string;
  public icon: string;
  public useFlags: SubstitutionUseFlag;
  public requiredFeatures: string[] = [];
  public requiredPermissions: string[] = [];

  hasSubstitutionMarkers = (text: string): boolean => {
    return text.indexOf(this.markerText) != -1;
  };

  isAllowed(useFlag: SubstitutionUseFlag, userState: UserStateService) {
    return (
      !!(this.useFlags & useFlag) &&
      this.requiredFeatures.every((f) => userState.hasFeature(f)) &&
      this.requiredPermissions.every((p) => userState.hasRolePermission(p))
    );
  }
}

