import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { SessionStorageService } from 'shared-code-lib';

@Component({
  selector: 'app-oauth-capture-redirect',
  templateUrl: './oauth-capture-redirect.component.html',
  styleUrls: ['./oauth-capture-redirect.component.scss'],
})
export class OauthCaptureRedirectComponent implements OnInit {
  constructor(
    private route: ActivatedRoute,
    private sessionStorageService: SessionStorageService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.route.queryParamMap.subscribe((params) => {
      const oauthState = { state: params.get('state'), code: params.get('code') };

      this.sessionStorageService.setOAuthState(oauthState);
      this.sessionStorageService.setReturnUrl('oauth-capture');
      this.router.navigateByUrl('complete-user-info');
    });
  }
}
