import { MetaDataValidity, MetaDataCollection } from './metadata';

export interface IOverallValidityStatusChangedData {
  overallValidity: MetaDataValidity;
  metaDataCollection: MetaDataCollection;
}

export class OverallValidityStatusChangedData {
  overallValidity: MetaDataValidity;
  metaDataCollection: MetaDataCollection;

  constructor(initializer: IOverallValidityStatusChangedData) {
    this.overallValidity = initializer.overallValidity;
    this.metaDataCollection = initializer.metaDataCollection;
  }
}

export interface IValidationInProgressChangedData {
  inProgress: boolean;
  isInitial: boolean;
}

export class ValidationInProgressChangedData {
  inProgress: boolean;
  isInitial: boolean;

  constructor(initializer: IValidationInProgressChangedData) {
    this.inProgress = initializer.inProgress;
    this.isInitial = initializer.isInitial;
  }
}
