import {
  Component,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  SimpleChanges,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { HydraApiService } from '../../../../../../blocks/services/hydra-api.service';
import { ApiResult } from '../../../../../../blocks/services/models';
import { ProductItemRefreshService } from '../../../../../../blocks/services/product-item-refresh.service';
import { SelectFilesService } from '../../../../../../blocks/services/select-files.service';
import { SpinnerStateService } from '../../../../../../blocks/services/spinner-state.service';

@Component({
  selector: 'app-upload-media-modal-body-and-footer',
  templateUrl: './upload-media-modal-body-and-footer.component.html',
  styleUrls: ['./upload-media-modal-body-and-footer.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class UploadMediaModalBodyAndFooterComponent implements OnChanges, OnInit, OnDestroy {
  @Input() modalClass = '';
  @Input() supportedFileTypes = '';
  @Output() close = new EventEmitter();

  uploadText = '';

  errors: string[] = [];

  constructor(
    private translateService: TranslateService,
    private spinnerService: SpinnerStateService,
    public selectFilesService: SelectFilesService,
    private hydraApiService: HydraApiService,
    private toastr: ToastrService,
    private translate: TranslateService,
    private productItemRefreshService: ProductItemRefreshService
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.supportedFileTypes) {
      this.uploadText =
        this.translateService.instant('admin-olc-media.upload-text') +
        ' ' +
        this.supportedFileTypes.split(',').join(' or ');
    }
  }

  ngOnInit() {}

  cancel = () => {
    this.errors = [];
    this.close.emit();
  };

  uploadMedia() {
    this.errors = [];

    this.spinnerService.show(
      this.translateService.instant('admin-olc-media.uploading'),
      document.querySelector(`.${this.modalClass} .nsm-content`)
    );

    this.hydraApiService.uploadOLCMedia(this.selectFilesService.files, this.uploadSucceeded, this.uploadFailed);
  }

  uploadSucceeded = (result: ApiResult) => {
    this.spinnerService.hide();

    if (!result.success) {
      this.errors = result.errors;
      return;
    }

    this.toastr.success(this.translate.instant('admin-olc-media.media-uploaded'));
    this.cancel();
    this.productItemRefreshService.onRefresh.next();
  };

  uploadFailed = () => {
    this.spinnerService.hide();
    this.toastr.error(this.translate.instant('admin-olc-media.upload-media-failed'));
  };

  ngOnDestroy(): void {
    this.selectFilesService.clear();
  }
}
