import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class UserFilterByProperty extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByUserPropertyComponent';
  }
}

export class UserFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('UserFilters.Create', filter);

    if (filter.id == 'BambaApplication-Upland.Bamba.Application.Users.Filters.FilterByUserProperty')
      return new UserFilterByProperty(filter);

    return null;
  };
}
