import { Component, OnInit, ViewEncapsulation } from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';

import { AuthorizationResult, LoginBaseComponent } from '../login-base/login-base.component';
import { LoadAppStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/load-app-state.service';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { UserStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/user-state.service';
import { Log } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { AuthService } from '../../services/auth/auth.service';
import { BambaDetailsService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/bamba-details.service';
import { BrandingService } from '../../services/branding.service';
import { SharedDataService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/shared-data.service';
import { HydraApiService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/hydra-api.service';
import { SessionStorageService } from '../../services/session-storage.service';

@Component({
  selector: 'app-login-terms-of-service',
  templateUrl: './login-terms-of-service.component.html',
  styleUrls: ['./login-terms-of-service.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class LoginTermsOfServiceComponent extends LoginBaseComponent implements OnInit {
  constructor(
    private appState: LoadAppStateService,
    userState: UserStateService,
    auth: AuthService,
    spinnerState: SpinnerStateService,
    translate: TranslateService,
    bds: BambaDetailsService,
    sss: SessionStorageService,
    bs: BrandingService,
    r: Router,
    private sharedDataService: SharedDataService,
    hydraApi: HydraApiService
  ) {
    super(hydraApi, spinnerState, translate, auth, bds, userState, sss, bs, r);
  }

  authorizationResult: AuthorizationResult;
  linkClicked: boolean;
  acceptTerms: boolean;

  ngOnInit(): void {
    super.ngOnInit();

    this.authorizationResult = this.sharedDataService.extraParameters;
    if (!this.authorizationResult?.notAcceptedTermsOfService) this.router.navigate(['/login']);
  }

  onLinkClicked = (): void => {
    this.linkClicked = true;
  };

  acceptTermsOfService = (): void => {
    this.hydraApi.acceptTermsOfService(
      this.authorizationResult.notAcceptedTermsOfService.id,
      this.acceptanceSucceeded,
      this.acceptanceFailed
    );
  };

  acceptanceSucceeded = () => {
    if (this.authorizationResult.tenants && this.authorizationResult.tenants.length > 0) {
      this.sessionStorageService.setTenantsList(this.authorizationResult.tenants);
      this.router.navigateByUrl('/login-tenants');
      return;
    }

    this.router.navigate(['/login-complete']);
  };

  acceptanceFailed = (err) => {
    Log.error('login-terms-of-service.acceptanceFailed', err);
    this.loginFailure('Login.terms-of-service.acceptance-failed');
  };
}
