import { ITEDOptions, TEDOptions } from '../../../Bamba.Web/ClientApp/src/app/blocks/services/models';
import { IDPSettings } from './sso';

export enum TenantAuthenticationType {
  ApplicationBased = 0,
  SSO = 1,
  SAML = 2,
}

export enum MeasurementUnit {
  CM = 0,
  MM = 1,
  IN = 2,
  PT = 3,
}

export interface ITenant {
  id: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  name: string;
  packageIds: string[];
  disabled: boolean;
  dateLastUserLoginUTC: Date;
  tenantCode: string;
  mobileBranding: string;
  cleanupCompletedWorkItemsAfterDays: number;
  pageCountLicenses: PageCountLicense[];
  tenantType: TenantType;
  partnerTenantId: string;
  deviceSettings: DeviceSettings;
  billable: boolean;
  enforceTermsOfServiceAcceptanceRequirement: boolean;
  sessionTimeInMinutes: number;
  tedOptions: TEDOptions;
}

export interface ITenantOptions {
  authenticationType: TenantAuthenticationType;

  ssoClientId: string;
  ssoAuthority: string;
  idp: IDPSettings;
}

export enum SamlSsoBinding {
  HttpPost = 'urn:oasis:names:tc:SAML:2.0:bindings:HTTP-POST',
  HttpRedirect = 'urn:oasis:names:tc:SAML:2.0:bindings:HTTP-Redirect',
}

export interface IDocumentLimits {
  monthlyPageLimit: number;
  documentPageLimit: number;
}

export interface IMeasurementSettings {
  unit: MeasurementUnit;
}

export interface IPasswordPolicy {
  passwordMemoryCount: number;
  expiresAfter: number;
  expireUnits: ExpirationUnits;
  minimumLength: number;
  minimumNumbers: number;
  minimumSpecialCharacters: number;
  minimumUpperCaseCharacters: number;
  minimumLowerCaseCharacters: number;
  passwordRequirements: Array<string>;
  optionalPasswordRequirements: Array<string>;
  optionalRequirementsHeader: string;
  excludesPartOfName: boolean;
  excludesPartOfEmailUserName: boolean;
  excludesPartOfEmailDomain: boolean;
}

export enum ExpirationUnits {
  Day = 0,
  Week = 1,
  Month = 2,
  Year = 3,
}

export class TenantOptions implements ITenantOptions {
  authenticationType: TenantAuthenticationType;

  ssoClientId: string;
  ssoAuthority: string;
  idp: IDPSettings;

  constructor(initializer?: ITenantOptions) {
    this.authenticationType = initializer ? initializer.authenticationType : TenantAuthenticationType.ApplicationBased;
    this.ssoClientId = initializer ? initializer.ssoClientId : '';
    this.ssoAuthority = initializer ? initializer.ssoAuthority : '';
    this.idp = initializer
      ? initializer.idp
      : new IDPSettings({
          name: '',
          partnerCertificates: [],
          singleSignOnServiceUrl: '',
          singleSignOnServiceBinding: '',
        });
  }

  public serializable(): ITenantOptions {
    return {
      authenticationType: this.authenticationType,
      ssoClientId: this.ssoClientId,
      ssoAuthority: this.ssoAuthority,
      idp: this.idp,
    };
  }
}

export class DocumentLimits implements IDocumentLimits {
  monthlyPageLimit: number;
  documentPageLimit: number;
  constructor(initializer?: IDocumentLimits) {
    this.monthlyPageLimit = initializer ? initializer.monthlyPageLimit : 250;
    this.documentPageLimit = initializer ? initializer.documentPageLimit : 100;
  }

  public serializable(): IDocumentLimits {
    return {
      monthlyPageLimit: this.monthlyPageLimit,
      documentPageLimit: this.documentPageLimit,
    };
  }
}

export class MeasurementSettings implements IMeasurementSettings {
  unit: MeasurementUnit;

  constructor(initializer?: IMeasurementSettings) {
    this.unit = initializer ? initializer.unit : MeasurementUnit.CM;
  }

  public serializable(): IMeasurementSettings {
    return {
      unit: this.unit,
    };
  }
}

export class PasswordPolicy implements IPasswordPolicy {
  constructor(initializer?: IPasswordPolicy) {
    this.passwordMemoryCount = initializer ? initializer.passwordMemoryCount : 0;
    this.expiresAfter = initializer ? initializer.expiresAfter : 0;
    this.expireUnits = initializer ? initializer.expireUnits : ExpirationUnits.Year;
    this.minimumLength = initializer ? initializer.minimumLength : 0;
    this.minimumNumbers = initializer ? initializer.minimumNumbers : 0;
    this.minimumSpecialCharacters = initializer ? initializer.minimumSpecialCharacters : 0;
    this.minimumUpperCaseCharacters = initializer ? initializer.minimumUpperCaseCharacters : 0;
    this.minimumLowerCaseCharacters = initializer ? initializer.minimumLowerCaseCharacters : 0;
    this.passwordRequirements = initializer ? initializer.passwordRequirements : [];
    this.optionalPasswordRequirements = initializer ? initializer.optionalPasswordRequirements : [];
    this.optionalRequirementsHeader = initializer ? initializer.optionalRequirementsHeader : '';
    this.excludesPartOfName = initializer ? initializer.excludesPartOfName : false;
    this.excludesPartOfEmailUserName = initializer ? initializer.excludesPartOfEmailUserName : false;
    this.excludesPartOfEmailDomain = initializer ? initializer.excludesPartOfEmailDomain : false;
  }

  passwordMemoryCount: number;
  expiresAfter: number;
  expireUnits: ExpirationUnits;
  minimumLength: number;
  minimumNumbers: number;
  minimumSpecialCharacters: number;
  minimumUpperCaseCharacters: number;
  minimumLowerCaseCharacters: number;
  passwordRequirements: Array<string> = [];
  optionalPasswordRequirements: Array<string> = [];
  optionalRequirementsHeader: string;
  excludesPartOfName: boolean;
  excludesPartOfEmailUserName: boolean;
  excludesPartOfEmailDomain: boolean;

  public serializable(): IPasswordPolicy {
    return {
      passwordMemoryCount: this.passwordMemoryCount,
      expiresAfter: this.expiresAfter,
      expireUnits: this.expireUnits,
      minimumLength: this.minimumLength,
      minimumNumbers: this.minimumNumbers,
      minimumSpecialCharacters: this.minimumSpecialCharacters,
      minimumUpperCaseCharacters: this.minimumUpperCaseCharacters,
      minimumLowerCaseCharacters: this.minimumLowerCaseCharacters,
      passwordRequirements: this.passwordRequirements,
      optionalPasswordRequirements: this.optionalPasswordRequirements,
      optionalRequirementsHeader: this.optionalRequirementsHeader,
      excludesPartOfName: this.excludesPartOfName,
      excludesPartOfEmailUserName: this.excludesPartOfEmailUserName,
      excludesPartOfEmailDomain: this.excludesPartOfEmailDomain,
    };
  }
}

export interface ITenantDetails {
  name: string;
  cleanupCompletedWorkItemsAfterDays: number;
  pageCountLicenses: PageCountLicense[];
  options: ITenantOptions;
  documentLimits: IDocumentLimits;
  passwordPolicy: IPasswordPolicy;
  tedOptions: ITEDOptions;
}

export class TenantDetails implements ITenantDetails {
  name: string;
  cleanupCompletedWorkItemsAfterDays: number;
  pageCountLicenses: PageCountLicense[];
  options: TenantOptions;
  documentLimits: DocumentLimits;
  passwordPolicy: PasswordPolicy;
  tedOptions: TEDOptions;

  constructor(initializer: ITenantDetails) {
    this.name = initializer.name;
    this.cleanupCompletedWorkItemsAfterDays = initializer.cleanupCompletedWorkItemsAfterDays;
    this.pageCountLicenses = initializer.pageCountLicenses;
    this.options = new TenantOptions(initializer.options);
    this.documentLimits = new DocumentLimits(initializer.documentLimits);
    this.passwordPolicy = new PasswordPolicy(initializer.passwordPolicy);
    this.tedOptions = new TEDOptions(initializer.tedOptions);
  }
}

export class Tenant implements ITenant {
  id: string;
  dateCreatedUTC: Date;
  dateModifiedUTC: Date;
  name: string;
  packageIds: string[];
  disabled: boolean;
  dateLastUserLoginUTC: Date;
  tenantCode: string;
  mobileBranding: string;
  cleanupCompletedWorkItemsAfterDays: number;
  pageCountLicenses: PageCountLicense[];
  tenantType: TenantType;
  partnerTenantId: string;
  deviceSettings: DeviceSettings;
  billable: boolean;
  enforceTermsOfServiceAcceptanceRequirement: boolean;
  sessionTimeInMinutes: number;
  tedOptions: TEDOptions;

  constructor(initializer?: ITenant) {
    this.id = initializer ? initializer.id : '';
    this.dateCreatedUTC = initializer ? initializer.dateCreatedUTC : new Date();
    this.dateModifiedUTC = initializer ? initializer.dateModifiedUTC : new Date();
    this.name = initializer ? initializer.name : '';
    this.packageIds = initializer ? initializer.packageIds : new Array<string>();
    this.disabled = initializer ? initializer.disabled : false;
    this.dateLastUserLoginUTC = initializer ? initializer.dateLastUserLoginUTC : new Date();
    this.tenantCode = initializer ? initializer.tenantCode : '';
    this.mobileBranding = initializer ? initializer.mobileBranding : '';
    this.cleanupCompletedWorkItemsAfterDays = initializer ? initializer.cleanupCompletedWorkItemsAfterDays : 30;
    this.pageCountLicenses = initializer ? initializer.pageCountLicenses : [];
    this.tenantType = initializer ? initializer.tenantType : TenantType.normal;
    this.partnerTenantId = initializer ? initializer.partnerTenantId : '';
    this.deviceSettings = initializer ? initializer.deviceSettings : new DeviceSettings();
    this.billable = initializer ? initializer.billable : true;
    this.enforceTermsOfServiceAcceptanceRequirement = initializer
      ? initializer.enforceTermsOfServiceAcceptanceRequirement
      : true;

    this.sessionTimeInMinutes = initializer ? initializer.sessionTimeInMinutes : 15;
  }

  public serializable(): ITenant {
    return {
      id: this.id,
      dateCreatedUTC: this.dateCreatedUTC,
      dateModifiedUTC: this.dateModifiedUTC,
      name: this.name,
      packageIds: this.packageIds,
      disabled: this.disabled,
      dateLastUserLoginUTC: this.dateLastUserLoginUTC,
      tenantCode: this.tenantCode,
      mobileBranding: this.mobileBranding,
      cleanupCompletedWorkItemsAfterDays: this.cleanupCompletedWorkItemsAfterDays,
      pageCountLicenses: this.pageCountLicenses,
      tenantType: this.tenantType,
      partnerTenantId: this.partnerTenantId,
      deviceSettings: this.deviceSettings,
      billable: this.billable,
      enforceTermsOfServiceAcceptanceRequirement: this.enforceTermsOfServiceAcceptanceRequirement,
      sessionTimeInMinutes: this.sessionTimeInMinutes,
      tedOptions: this.tedOptions,
    };
  }
}

export enum TenantType {
  normal = 0,
  partner = 1,
  InterFAX = 2,
}

export class CreateTenant {
  constructor(
    public tenant: Tenant,
    public administratorEmail: string,
    public administratorPassword: string
  ) {}

  public serializable(): any {
    return {
      tenant: this.tenant.serializable(),
      administratorEmail: this.administratorEmail,
      administratorPassword: this.administratorPassword,
    };
  }
}

export class PageCountLicense {
  id: string;
  licenseType: LicenseType;
  countType: PageCountType;
  dateTermStartsUTC: Date;
  dateTermEndsUTC: Date;
  pageCountAllowance: number;

  constructor(initializer?: any) {
    this.id = initializer ? initializer.id : '';
    this.licenseType = initializer ? initializer.licenseType : LicenseType.Upload;
    this.countType = initializer ? initializer.countType : PageCountType.primary;
    this.dateTermStartsUTC = initializer ? initializer.dateTermStartsUTC : new Date();
    this.dateTermEndsUTC = initializer ? initializer.dateTermEndsUTC : new Date();
    this.pageCountAllowance = initializer ? initializer.pageCountAllowance : 0;
  }
}

export enum PageCountType {
  primary = 0,
  powerPack = 1,
}

export enum LicenseType {
  Upload = 0,
  InvoiceProcessing = 1,
  PIIDetection = 2,
  DocumentSumarization = 3,
  SignatureDetection = 4,
  DataExtraction = 5,
}

export class DeviceSettings {
  secret: string;
  allowedIPAddresses: Array<string>;

  constructor(initializer?: any) {
    this.secret = initializer ? initializer.secret : '';
    this.allowedIPAddresses = initializer ? initializer.allowedIPAddresses : new Array<string>();
  }
}

