import { AfterViewInit, Component, ElementRef, EventEmitter, Inject, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PERFECT_SCROLLBAR_CONFIG, PerfectScrollbarConfigInterface } from 'ngx-perfect-scrollbar-portable';
import { NgxSmartModalService } from 'ngx-smart-modal';
import PerfectScrollbar from 'perfect-scrollbar';
import { FieldDefinition, FixedDataSource, IFieldOptions, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

declare const $: any;
@Component({
  selector: 'app-add-notes-modal',
  templateUrl: './add-notes-modal.component.html',
  styleUrls: ['./add-notes-modal.component.scss'],
})
export class AddNotesModalComponent implements OnInit, AfterViewInit {
  @Output() closeModal = new EventEmitter();

  componentName: string = '';
  componentIds = [];

  jiraCommentField: FieldDefinition;

  jiraId: string;
  jiraComment: string;
  jiraIds = [];
  jiraIssues = '';
  ignoreIssues = false;

  errors = [];
  id = '';
  modalTitle: string;
  actionLabel: string;
  jiraIssueListView: any;

  installStatuses = [];

  installStatusField: FieldDefinition;

  installStatus = '0';

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    @Inject(PERFECT_SCROLLBAR_CONFIG) private config: PerfectScrollbarConfigInterface,
    private _elementRef: ElementRef,
    private ngxSmartModalService: NgxSmartModalService
  ) {}

  ngOnInit(): void {
    this.id = this.sharedDataService.extraParameters.id;
    this.jiraIds = this.sharedDataService.extraParameters.jiraIssues;
    this.jiraIssues = this.jiraIds.join(', ');
    this.componentName = this.sharedDataService.extraParameters.componentVersionName;
    this.componentIds = [this.id];
    this.modalTitle = this.sharedDataService.extraParameters.modalTitle;
    this.actionLabel = this.sharedDataService.extraParameters.actionLabel;
    this.jiraIssueListView = this.sharedDataService.extraParameters.jiraIssueListView;
    this.installStatuses = this.sharedDataService.extraParameters.installStatuses;

    this.createFields();
  }

  ngAfterViewInit() {
    const config = this.config;

    const element = this._elementRef.nativeElement.querySelector('.k-grid-content');

    const ps1 = new PerfectScrollbar(element, config);
  }

  createFields = () => {
    this.jiraCommentField = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('add-notes-modal.notes'),
      placeholder: this.translateService.instant('add-notes-modal.notes-placeholder'),
      required: true,
    });

    const options = new Array<IFieldOptions>();
    this.installStatuses.forEach((x) => options.push({ value: x.key, name: x.value }));
    const datasource = new FixedDataSource(options);

    this.installStatusField = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('add-notes-modal.install-status'),
      placeholder: this.translateService.instant('add-notes-modal.install-status-placeholder'),
      required: true,
      datasource: datasource,
    });
  };

  addNotes = () => {
    this.errors = [];

    this.showSpinner();
    const args = new MetaDataCollection();

    args.set('jiraissues', this.jiraIds.join(','));
    args.set('comment', this.jiraComment);
    args.set('installstatus', this.installStatus);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.componentIds,
      args,
      this.onAddNotesSucceeded,
      this.onAddNotesFailed
    );

    return false;
  };

  onAddNotesSucceeded = (result): void => {
    this.spinnerService.hide();

    if (result.type == 'ConfirmationResult') return this.showConfirmationModel(result.result.message);

    this.close();
  };

  showConfirmationModel(confirmationText: string) {
    const args = new MetaDataCollection();
    args.set('jiraissues', this.jiraIds.join(','));
    args.set('comment', this.jiraComment);
    args.set('installstatus', this.installStatus);
    args.set('skipfailed', true.toString());

    this.ngxSmartModalService.setModalData(
      {
        title: 'MainHeader.ActionConfirmation',
        text: confirmationText,
        buttonText: this.translateService.instant('MainHeader.ActionConfirmationYes'),
        confirm: () => {
          this.showSpinner();
          this.closeConfirmationAction();
          this.sharedDataService.actionHandler.invokeEx(
            this.sharedDataService.folderId,
            this.sharedDataService.action,
            this.componentIds,
            args,
            this.onAddNotesSucceeded,
            this.onAddNotesFailed
          );
        },
        cancel: () => this.closeConfirmationAction(),
      },
      'actionConfirmModal',
      true
    );

    this.ngxSmartModalService.getModal('actionConfirmModal').open();
  }

  closeConfirmationAction = () => {
    this.ngxSmartModalService.getModal('actionConfirmModal').close();
  };

  onAddNotesFailed = (errors: any[]): void => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  close = (): void => this.closeModal.emit();

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.add-notes-modal .nsm-content') as HTMLElement;
  }

  showSpinner = (): void => {
    this.spinnerService.show(this.translateService.instant('add-notes-modal.loading'), this.getSpinnerElement());
  };
}
