import { Component, OnInit, Output, EventEmitter } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { FieldDefinition, MetaDataCollection, MetaDataType } from 'shared-code-lib';

@Component({
  selector: 'app-set-component-version',
  templateUrl: './set-component-version.component.html',
  styleUrls: ['./set-component-version.component.scss'],
})
export class SetComponentVersionComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  componentName: string = '';
  componentIds = [];

  versionField: FieldDefinition;
  commentField: FieldDefinition;

  version: string;
  comment: string;

  errors = [];

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService
  ) {}

  ngOnInit(): void {
    this.componentIds = [this.sharedDataService.extraParameters.id];
    this.componentName = this.sharedDataService.extraParameters.component.name;
    this.version = this.sharedDataService.extraParameters.component.nextReleaseVersion;
    this.createFields();
  }

  createFields = () => {
    this.versionField = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('set-component-version.version'),
      placeholder: this.translateService.instant('set-component-version.version-placeholder'),
      required: true,
    });

    this.commentField = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('set-component-version.comment'),
      placeholder: this.translateService.instant('set-component-version.comment-placeholder'),
      required: true,
    });
  };

  setVersion = () => {
    this.errors = [];
    if (!this.version.trim()) return;

    this.showSpinner();
    const args = new MetaDataCollection();

    args.set('version', this.version);
    args.set('comment', this.comment);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.componentIds,
      args,
      this.onSetVersionSucceeded,
      this.onSetVersionFailed
    );
    return false;
  };

  onSetVersionSucceeded = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  onSetVersionFailed = (errors: any[]): void => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  close = (): void => this.closeModal.emit();

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.set-component-version .nsm-content') as HTMLElement;
  }

  showSpinner = (): void => {
    this.spinnerService.show(this.translateService.instant('set-component-version.loading'), this.getSpinnerElement());
  };
}
