import { Component, EventEmitter, Input, OnInit, Output, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { Blurb, UserBlurbInfo } from '../../models/marketing-blurb';
import { ApiService } from '../../services/api.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-blurbs-modal',
  templateUrl: './blurbs-modal.component.html',
  styleUrls: ['./blurbs-modal.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class BlurbsModalComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  @Input() marketingBlurbs: Array<UserBlurbInfo> = [];

  constructor(
    private translateService: TranslateService,
    private apiService: ApiService,
    private spinnerService: SpinnerStateService,
    private toastr: ToastrService
  ) {}

  learnMoreText = '';

  ngOnInit(): void {
    this.learnMoreText = this.translateService.instant('MainHeader.learnMore');
  }

  close = (): void => this.closeModal.emit();

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.blurbs .nsm-content') as HTMLElement;
  }

  showSpinner = (): void => {
    this.spinnerService.show(this.translateService.instant('blurbs.loading'), this.getSpinnerElement());
  };

  getBlurbLearnMoreLink = (blurb: Blurb): string => {
    if (!blurb.learnMoreLink) return '';

    return '<a href="' + blurb.learnMoreLink + '" target="_blank">' + this.learnMoreText + '</a>';
  };
}
