import { Injectable } from "@angular/core";
import { timer, Observable, Subscription } from "rxjs";

@Injectable({
  providedIn: "root",
})
export class RepeatedService {
  start(repeatTime: number): Observable<number> {
    return timer(0, repeatTime);
  }

  stop(interval: Subscription): void {
    interval.unsubscribe();
    return null;
  }
}
