import { Component, Input, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { CharactersValidator } from '../../utils/characters-validator.service';
import { TextComponent } from '../text/text.component';

@Component({
  selector: 'app-decimal',
  templateUrl: './decimal.component.html',
  styleUrls: ['./decimal.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class DecimalComponent extends TextComponent {
  @Input() fieldId: string = '';
  @Input() autocomplete: string = 'on';

  constructor(translateService: TranslateService, protected validator: CharactersValidator) {
    super(translateService);
  }

  onKeydown(event: any) {
    this.validator.allowDecimalOnly(event, this.field.allowNegativeNumbers);
    super.onKeydown(event);
  }

  onBeforeBlurCheck(event: any) {
    event.target.value = this.formatValue(event.target.value);
  }

  formatValue(value: string): string {
    let formatted = Number.parseFloat(value).toString();
    return this.normalizeValue(formatted == 'NaN' ? '' : value);
  }

  override normalizeValue(value: string): string {
    if (value == null || value == undefined || value === '' || value === '-') return value;
    const num = Number.parseFloat(this.parseLocaleNumber(value)).toString();
    return num;
  }
}
