import { Languages } from 'shared-code-lib';
import { TabItem, WidgetWidth } from '../../models/home-page-tab';

declare const $: any;

export interface Attributes {
  'data-column': number;
  'data-row': number;
  'data-primary-column': number;
}

export enum AttributesEnum {
  dataColumn = 'data-column',
  dataRow = 'data-row',
  dataPrinmaryColumn = 'data-primary-column',
}

export class ColumnRow {
  columns: Array<TabItem> = [];
  height = 0;

  constructor(
    public rowNumber: number,
    public top: number,
    public left: number,
    public width: number,
    public margin: number
  ) {}

  addBlock(
    item: TabItem,
    draggedItemWidth: WidgetWidth,
    itemWidth: number,
    gridElement: any
  ): { topPosition: number; leftPosition: number } {
    let emptyBlock: any;

    this.removeOldEmptyBlocks(item);

    this.columns.push(item);
    this.columns.forEach((column) => {
      if (column.height > this.height) {
        this.height = column.height;
      }
    });

    if (draggedItemWidth === WidgetWidth.Half && this.columns.length < 2) {
      emptyBlock = this.addEmptyBlock(item, gridElement);
    }

    let translateXValue = this.left + (this.width - itemWidth);
    if (Languages.isRTLLanguage()) translateXValue *= -1;
    if (item.column === 0) {
      if (emptyBlock) {
        emptyBlock.css({
          transform: `translateX(${translateXValue}px) translateY(${this.top}px)`,
        });
      }

      return { topPosition: this.top, leftPosition: this.left };
    } else {
      if (emptyBlock) {
        translateXValue = this.left;
        if (Languages.isRTLLanguage()) translateXValue *= -1;
        emptyBlock.css({
          transform: `translateX(${translateXValue}px) translateY(${this.top}px)`,
        });
      }

      return { topPosition: this.top, leftPosition: this.left + (this.width - itemWidth) };
    }
  }

  private removeOldEmptyBlocks(item: TabItem) {
    $(`.empty-block-0-${item.row}-${item.primaryColumn}`).remove();
    $(`.empty-block-1-${item.row}-${item.primaryColumn}`).remove();
  }

  private addEmptyBlock(item: TabItem, gridElement: any) {
    const that = this;
    let emptyBlock: any;
    let emptyBlockNumber: number;

    if (item.column === 0) {
      emptyBlockNumber = 1;
    } else {
      emptyBlockNumber = 0;
    }

    const emptyBlockClassName = `empty-block-${emptyBlockNumber}-${item.row}-${item.primaryColumn}`;
    const dataAttributes: Attributes = {
      'data-column': emptyBlockNumber,
      'data-row': item.row,
      'data-primary-column': item.primaryColumn,
    };

    gridElement.append(`<div class="${emptyBlockClassName}"></div>`);
    emptyBlock = $(`.${emptyBlockClassName}`);
    emptyBlock.addClass('empty');
    emptyBlock.addClass('item-drop');
    let translateXValue = this.left;
    if (Languages.isRTLLanguage()) translateXValue *= -1;
    emptyBlock.css({
      right: Languages.isRTLLanguage() ? 0 : 'initial',
      left: Languages.isRTLLanguage() ? 'initial' : 0,
      top: 0,
      transform: `translateX(${translateXValue}px) translateY(${this.top}px)`,
      width: (this.width - this.margin) / 2,
      height: this.height,
    });

    this.setDataAttributes(emptyBlock, dataAttributes);

    return emptyBlock;
  }

  private setDataAttributes(block: any, data: Attributes) {
    block.attr(data);
  }
}

export class GridColumn {
  height = 0;
  width: number;
  rows: Array<ColumnRow> = [];
  private bottomEmptySpace: any;
  private isEmpty = true;

  constructor(
    public gridElement: any,
    public gridWidth: number,
    public columnNumber: number,
    public numberOfGridColumns: number,
    public margin: number
  ) {
    this.width = (gridWidth - this.margin) / numberOfGridColumns;

    this.createEmptyColumn();
  }

  private createEmptyColumn() {
    this.gridElement.append(`<div class="item-drop empty-column empty-column-${this.columnNumber}"></div>`);
    const emptyColumn = $(`.empty-column-${this.columnNumber}`);

    this.setDataAttributesAndAddEventListeners(emptyColumn, 0, '100%');
  }

  private createEmptyColumnAtBottom() {
    this.gridElement.append(
      `<div class="item-drop empty-bottom-column empty-bottom-column-${this.columnNumber}"></div>`
    );
    this.bottomEmptySpace = $(`.empty-bottom-column-${this.columnNumber}`);

    this.setDataAttributesAndAddEventListeners(this.bottomEmptySpace, this.rows.length, '200px');
    let translateXValue = this.width * this.columnNumber + this.margin * this.columnNumber;
    if (Languages.isRTLLanguage()) translateXValue *= -1;
    this.bottomEmptySpace.css({
      top: 0,
      right: Languages.isRTLLanguage() ? 0 : 'initial',
      left: Languages.isRTLLanguage() ? 'initial' : 0,
      transform: `translateX(${translateXValue}px) translateY(${this.height + this.margin}px)`,
    });
  }

  private setDataAttributesAndAddEventListeners(emptyColumn: any, row: number, height: string): void {
    const dataAttributes: Attributes = {
      'data-column': 0,
      'data-row': row,
      'data-primary-column': this.columnNumber,
    };

    let translateXValue = this.width * this.columnNumber + this.margin * this.columnNumber;
    if (Languages.isRTLLanguage()) translateXValue *= -1;
    emptyColumn.css({
      width: this.width + 'px',
      height: height,
      transform: `translateX(${translateXValue}px) translateY(0px)`,
    });

    emptyColumn.attr(dataAttributes);
  }

  getBlockPosition(
    item: TabItem,
    draggedItemWidth: WidgetWidth,
    gridElement: any
  ): { width: number; topPosition: number; leftPosition: number } {
    const width = this.getWidgetWidth(this.width, draggedItemWidth);
    let row = this.rows.find((_row) => _row.rowNumber === item.row);

    $(`.empty-column-${this.columnNumber}`).remove();
    $(`.empty-bottom-column-${this.columnNumber}`).remove();
    this.isEmpty = false;

    if (!row) {
      row = new ColumnRow(
        item.row,
        item.row === 0 ? this.height : this.height + this.margin,
        this.width * this.columnNumber + this.margin * this.columnNumber,
        this.width,
        this.margin
      );

      this.rows.push(row);
    }

    const { topPosition, leftPosition } = row.addBlock(item, draggedItemWidth, width, gridElement);
    this.height = this.rows.map((_row) => _row.height).reduce((total, current) => total + current + this.margin);

    this.createEmptyColumnAtBottom();
    return { width, topPosition, leftPosition };
  }

  getRows(): Array<ColumnRow> {
    return this.rows;
  }

  getRow(rowNumber: number): ColumnRow {
    return this.rows[rowNumber];
  }

  isLastRow(rowNumber: number): boolean {
    return this.rows[this.rows.length - 1].rowNumber === rowNumber;
  }

  showEmptyBottomSpace() {
    if (!this.isEmpty) {
      this.bottomEmptySpace.show();
    }
  }

  hideEmptyBottomSpace() {
    if (!this.isEmpty) {
      this.bottomEmptySpace.hide();
    }
  }

  private getWidgetWidth(columnWidth: number, width: WidgetWidth): number {
    const halfColWidth = (columnWidth - this.margin) / 2;

    switch (width) {
      case WidgetWidth.Full:
        return columnWidth;
      case WidgetWidth.Half:
        return halfColWidth;
    }
  }
}

export class Grid {
  private columns: Array<GridColumn> = [];
  dragFromPage: boolean = false;
  constructor(public gridElement: any, public rowWidth: number, public numberOfColumns: number, public margin: number) {
    for (let i = 0; i < numberOfColumns; i++) {
      this.columns.push(new GridColumn(gridElement, rowWidth, i, numberOfColumns, this.margin));
    }
  }

  getBlockPosition(item: TabItem, draggedItemWidth: WidgetWidth) {
    return this.columns[item.primaryColumn].getBlockPosition(item, draggedItemWidth, this.gridElement);
  }

  handleDragDropBlocks(draggedItem: TabItem, draggedItemWidth: WidgetWidth, droppedIntoItem: TabItem) {
    const rows = this.getPrimaryColumn(droppedIntoItem.primaryColumn).getRows();
    const targetRow = this.getPrimaryColumn(droppedIntoItem.primaryColumn).getRow(droppedIntoItem.row);
    const draggedItemRow = this.getPrimaryColumn(draggedItem.primaryColumn).getRow(draggedItem.row);
    const targetColumnNumber = droppedIntoItem.column;

    if (draggedItem.row === droppedIntoItem.row && draggedItem.primaryColumn === droppedIntoItem.primaryColumn) {
      droppedIntoItem.column = draggedItem.column;
      draggedItem.column = targetColumnNumber;
      return;
    } else if (draggedItemWidth === WidgetWidth.Full && draggedItem.primaryColumn === droppedIntoItem.primaryColumn) {
      this.handleSwapRowWithRow(rows, draggedItemRow, targetRow);

      draggedItem.row = targetRow.rowNumber;
    } else if (draggedItem.primaryColumn !== droppedIntoItem.primaryColumn) {
      draggedItem.column = 0;
      draggedItem.row = droppedIntoItem.row;

      for (let i = targetRow.rowNumber; i < rows.length; i++) {
        rows[i].columns.map((tabItem) => (tabItem.row = i + 1));
      }

      if (draggedItemRow.columns.length < 2) {
        const draggedFromRows = this.getPrimaryColumn(draggedItem.primaryColumn).getRows();
        const rowIndex = draggedFromRows.findIndex((row) => row.rowNumber === draggedItemRow.rowNumber);

        draggedFromRows.splice(rowIndex, 1);

        for (let i = 0; i < draggedFromRows.length; i++) {
          draggedFromRows[i].rowNumber = i;
          draggedFromRows[i].columns.map((tabItem) => (tabItem.row = i));
        }
      }
    } else {
      if (draggedItem.row < targetRow.rowNumber) {
        if (draggedItemRow.columns.length < 2) {
          this.handleSwapRowWithRow(rows, draggedItemRow, targetRow);
        } else {
          for (let i = targetRow.rowNumber; i < rows.length; i++) {
            rows[i].columns.map((tabItem) => (tabItem.row = i + 1));
          }

          draggedItem.column = 0;
        }

        draggedItem.row = targetRow.rowNumber;
      } else {
        if (draggedItemRow.columns.length < 2) {
          for (let i = targetRow.rowNumber; i < draggedItem.row; i++) {
            rows[i].columns.map((tabItem) => (tabItem.row = i + 1));
          }
        } else {
          for (let i = targetRow.rowNumber; i < rows.length; i++) {
            rows[i].columns.map((tabItem) => (tabItem.row = i + 1));
          }

          draggedItem.column = 0;
        }

        draggedItem.row = targetRow.rowNumber;
      }
    }

    draggedItem.primaryColumn = droppedIntoItem.primaryColumn;
    draggedItem.column = 0;
  }

  private handleSwapRowWithRow(rows: Array<ColumnRow>, draggedFrom: ColumnRow, droppedInto: ColumnRow) {
    if (draggedFrom.rowNumber < droppedInto.rowNumber) {
      for (let i = draggedFrom.rowNumber; i <= droppedInto.rowNumber; i++) {
        rows[i].columns.map((tabItem) => (tabItem.row = i - 1));
      }
    } else {
      for (let i = droppedInto.rowNumber; i < draggedFrom.rowNumber; i++) {
        rows[i].columns.map((tabItem) => (tabItem.row = i + 1));
      }
    }
  }

  handleDragOnEmptyBlock(
    draggedItem: TabItem,
    draggedItemWidth: WidgetWidth,
    attributes: Attributes,
    isColumn: boolean
  ) {
    const primaryColumn = this.getPrimaryColumn(draggedItem.primaryColumn);
    const rows = primaryColumn.getRows();
    const row = primaryColumn.getRow(draggedItem.row);
    const rowIndex = rows.findIndex((r) => r.rowNumber === row.rowNumber);

    if (isColumn) {
      draggedItem.primaryColumn = attributes[AttributesEnum.dataPrinmaryColumn];
      draggedItem.row = attributes[AttributesEnum.dataRow];
      draggedItem.column = attributes[AttributesEnum.dataColumn];

      if (row.columns.length < 2) {
        rows.splice(rowIndex, 1);

        for (let i = 0; i < rows.length; i++) {
          rows[i].rowNumber = i;
          rows[i].columns.map((tabItem) => (tabItem.row = i));
        }
      }

      return;
    }

    if (draggedItemWidth === WidgetWidth.Full) {
      const item = this.getPrimaryColumn(attributes[AttributesEnum.dataPrinmaryColumn]).getRow(
        attributes[AttributesEnum.dataRow]
      ).columns[0];
      this.handleDragDropBlocks(draggedItem, draggedItemWidth, item);
      return;
    }

    draggedItem.row = attributes[AttributesEnum.dataRow];

    if (
      row.columns.length < 2 &&
      (row.rowNumber !== attributes[AttributesEnum.dataRow] ||
        draggedItem.primaryColumn !== attributes[AttributesEnum.dataPrinmaryColumn])
    ) {
      if (draggedItem.primaryColumn === attributes[AttributesEnum.dataPrinmaryColumn]) {
        rows.find((r) => r.rowNumber === attributes[AttributesEnum.dataRow]).columns.push(draggedItem);
      }

      rows.splice(rowIndex, 1);

      for (let i = 0; i < rows.length; i++) {
        rows[i].rowNumber = i;
        rows[i].columns.map((tabItem) => (tabItem.row = i));
      }
    }

    draggedItem.column = attributes[AttributesEnum.dataColumn];
    draggedItem.primaryColumn = attributes[AttributesEnum.dataPrinmaryColumn];
  }

  private getPrimaryColumn(columnNumber: number): GridColumn {
    return this.columns[columnNumber];
  }

  onDrag(item: TabItem) {
    this.dragFromPage = true;
    this.columns.forEach((column) => {
      if (column.columnNumber === item.primaryColumn && column.isLastRow(item.row)) {
        return;
      } else {
        column.showEmptyBottomSpace();
      }
    });
  }

  onDragEnd() {
    this.dragFromPage = false;
    this.columns.forEach((column) => {
      column.hideEmptyBottomSpace();
    });
  }
}
