import { Component, ElementRef, EventEmitter, Input, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Contact, FieldDefinition, MetaDataType } from 'shared-code-lib';
import { CustomProperty } from '../../InterFAX/Models/admin';
import { InterFAXService } from '../../services/interfax.service';
import { ApiResults } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-interfax-contact-modal',
  templateUrl: './interfax-contact-modal.component.html',
  styleUrls: ['./interfax-contact-modal.component.scss'],
})
export class InterfaxContactModalComponent implements OnInit {
  @ViewChild('spinnerElement', { static: true }) spinnerElement: ElementRef;

  @Input() skipSaving: boolean;
  @Input() contact: Contact;
  @Input() onSave: Function;
  @Output() closeModal = new EventEmitter();

  title: string;
  property: CustomProperty;

  errors = new Array<string>();

  fieldContactName: FieldDefinition;
  fieldContactCompany: FieldDefinition;
  fieldContactFaxNumber: FieldDefinition;
  fieldContactPhoneNumber: FieldDefinition;

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private interfaxService: InterFAXService
  ) {}

  ngOnInit(): void {
    this.createFields();

    this.title = this.translateService.instant(
      this.contact && !this.contact.faxNumber ? 'contact-property.add-contact' : 'contact-property.title'
    );

    if (!this.contact) {
      this.spinnerService.show(this.translateService.instant('Common.Loading'), this.spinnerElement.nativeElement);
      const id = this.sharedDataService.extraParameters ? this.sharedDataService.extraParameters.id : '';
      this.interfaxService.getContact(id, this.loaded, this.loaded);
    }
  }

  loaded = (c: Contact): void => {
    this.spinnerService.hide();
    this.contact = c;
  };

  validate = (): string[] => {
    const errors = [];

    if (!this.contact.faxNumber || !this.contact.faxNumber.trim()) {
      errors.push('contact-list.faxNumber-placeholder');
    }

    return errors;
  };

  save = (): void => {
    this.errors = this.validate();
    if (this.errors.length) return;

    if (this.onSave) this.onSave(this.contact);

    if (this.skipSaving) return;

    this.spinnerService.show(this.translateService.instant('Common.Saving'), this.spinnerElement.nativeElement);
    this.interfaxService.setContact(this.contact, this.saved, this.saveFailed);
  };

  saved = (r: ApiResults): void => {
    this.spinnerService.hide();

    if (r.success) {
      this.close();
      this.sharedDataService.actionHandler.reload.emit(true);
    } else {
      this.errors = r.errors;
    }
  };

  saveFailed = (err: Error): void => {
    this.spinnerService.hide();
    this.errors.push(err.message);
  };

  close = (): void => {
    this.closeModal.emit();
  };

  cancel = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  createFields = (): void => {
    this.fieldContactName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('contact-list.name'),
      placeholder: this.translateService.instant('contact-list.name-placeholder'),
      required: false,
    });

    this.fieldContactCompany = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('contact-list.company'),
      placeholder: this.translateService.instant('contact-list.company-placeholder'),
      required: false,
    });

    this.fieldContactFaxNumber = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('contact-list.faxNumber'),
      placeholder: this.translateService.instant('contact-list.faxNumber-placeholder'),
      required: true,
    });

    this.fieldContactPhoneNumber = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('contact-list.phoneNumber'),
      placeholder: this.translateService.instant('contact-list.phoneNumber-placeholder'),
      required: false,
    });
  };
}
