import { Component, OnInit } from '@angular/core';
import { HydraApiService } from '../../../services/hydra-api.service';
import { ApiResult } from '../../../services/models';
import { IQuestion } from 'shared-code-lib';

@Component({
  selector: 'app-questions',
  templateUrl: './questions.component.html',
  styleUrls: ['./questions.component.scss']
})
export class QuestionsComponent implements OnInit {
  constructor(private hydraApi: HydraApiService) { }

  ngOnInit(): void {
    this.hydraApi.getQuestions(this.onGetQuestionsSucceeded, this.onGetQuestionsFailed);
  }

  questions: Array<IQuestion>;

  onGetQuestionsSucceeded = (result: ApiResult) => {
    this.questions = new Array<IQuestion>();
    for (const question in result.object) {
      this.questions.push({ key: question, id: result.object[question], value: null });
    }
  };

  onAnswer(questionKey: string, event) {
    let answer = event.target.value === 'true' ? true : event.target.value === 'false' ? false : null;
    this.questions.filter(q => q.key === questionKey)[0].value = answer;
  }

  onGetQuestionsFailed = (error: any) => {
  };
}
