import { Injectable } from '@angular/core';

import { Subject } from 'rxjs';

import { Batch, Page } from '../capture-models';
import { CapturedDocument } from '../capture-models/document';

@Injectable({
  providedIn: 'root',
})
export class DocumentViewerService {
  private _batchSubject = new Subject<Batch>();
  private _documentSubject = new Subject<CapturedDocument>();
  private _pageSubject = new Subject<Page>();
  private _deletePageSubject = new Subject<number>();
  private _selectPageSubject = new Subject<number>();

  private _thumbnailScrollSubject = new Subject<number>();

  onChangeBatch = this._batchSubject.asObservable();
  onChangeDocument = this._documentSubject.asObservable();
  onChangePage = this._pageSubject.asObservable();
  onDeletePage = this._deletePageSubject.asObservable();
  onSelectPage = this._selectPageSubject.asObservable();
  onThumbnailScroll = this._thumbnailScrollSubject.asObservable();

  constructor() {}

  changeSelectedBatch(batch: Batch): void {
    this._batchSubject.next(<Batch>batch);
  }

  changeSelectedDocument(doc: CapturedDocument): void {
    this._documentSubject.next(<CapturedDocument>doc);
  }

  onChangeSelectedPage(page: Page): void {
    this._pageSubject.next(<Page>page);
  }

  deletePage(index: number): void {
    this._deletePageSubject.next(<number>index);
  }

  selectPage(index: number): void {
    this._selectPageSubject.next(<number>index);
  }

  thumbnailScrolled(pos: number) {
    this._thumbnailScrollSubject.next(pos);
  }
}
