import { Component, OnDestroy, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { Subscription, fromEvent } from 'rxjs';
import { Log } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { SpinnerStateService } from '../../../../Bamba.Web/ClientApp/src/app/blocks/services/spinner-state.service';
import { AuthService } from '../../services/auth/auth.service';
import { PrintToService } from '../../services/print-to.service';
import { SessionStorageService } from '../../services/session-storage.service';
import { Key } from '../../utils/key-enum';
import { AuthorizationResult } from '../login-base/login-base.component';

@Component({
  selector: 'app-password-expired',
  templateUrl: './password-expired.component.html',
  styleUrls: ['./password-expired.component.scss'],
})
export class PasswordExpiredComponent implements OnInit, OnDestroy {
  modalChangeUserPassword: NgxSmartModalComponent;
  newPassword = '';

  subscriptions = new Subscription();

  constructor(
    public ngxSmartModalService: NgxSmartModalService,
    protected router: Router,
    private authService: AuthService,
    private sessionStorageService: SessionStorageService,
    private spinnerStateService: SpinnerStateService,
    private printToService: PrintToService,
    private translateService: TranslateService,
    private toastr: ToastrService
  ) {}

  ngOnInit(): void {}

  ngAfterViewInit() {
    this.modalChangeUserPassword = this.ngxSmartModalService.getModal('changeUserPasswordModal');
    this.modalChangeUserPassword.open();
    this.listenOnEscapeKey();
  }

  listenOnEscapeKey = () => {
    this.subscriptions.add(
      fromEvent(document.documentElement, 'keydown').subscribe((event: KeyboardEvent) => {
        if (event.key !== Key.Escape) return;
        this.cancelChangingPassword();
      })
    );
  };

  closeChangePasswordModal = (newPassword = ''): void => {
    if (!newPassword) {
      this.cancelChangingPassword();
      return;
    }

    this.autoLoginWithNewPassword(newPassword);
  };

  cancelChangingPassword = () => {
    this.modalChangeUserPassword.close();
    this.authService.logout();
    this.router.navigate(['/login']);
  };

  autoLoginWithNewPassword = (newPassword: string) => {
    this.newPassword = newPassword;
    this.spinnerStateService.show(this.translateService.instant('Login.Sign-In-Message'), document.documentElement);

    this.authService.login(
      this.sessionStorageService.getUsername(),
      this.newPassword,
      this.sessionStorageService.getIsMobile(),
      this.loginSuccessCallBack,
      this.loginFailureCallBack
    );
  };

  loginSuccessCallBack = (ar: AuthorizationResult, username: any) => {
    if (!ar.succeeded) {
      this.loginFailure(ar.errorText || this.translateService.instant('Login.InvalidLoginData'));
      return;
    }

    this.modalChangeUserPassword.close();
    this.authService.loginPasswordSuccess(ar, username, this.newPassword, this.printToService);
  };

  loginFailureCallBack = (err) => {
    Log.error('login-password.loginFailureCallBack', err);

    this.loginFailure(this.translateService.instant('Login.InvalidLoginData'));
  };

  loginFailure = (errorMessage: string): void => {
    this.spinnerStateService.hide();
    this.toastr.error(errorMessage);
    this.authService.logout();
    this.router.navigate(['/login']);
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
