import { Component, ViewChild, forwardRef, TemplateRef } from '@angular/core';
import { ToolBarToolComponent } from '@progress/kendo-angular-toolbar';

@Component({
  selector: 'app-html-editor-toolbar',
  providers: [
    {
      provide: ToolBarToolComponent,
      useExisting: forwardRef(() => HtmlEditorToolbarComponent),
    },
  ],
  template: `
    <ng-template #toolbarTemplate>
      <ng-content></ng-content>
    </ng-template>
  `,
})
export class HtmlEditorToolbarComponent extends ToolBarToolComponent {
  @ViewChild('toolbarTemplate', { static: true })
  override toolbarTemplate: TemplateRef<unknown>;

  constructor() {
    super();
  }

  override canFocus() {
    return true;
  }

  override handleKey(): boolean {
    return false;
  }
}
