import { Component, ContentChild, EventEmitter, Input, Output, TemplateRef, ViewEncapsulation } from '@angular/core';
import { uniqueId } from 'lodash';
import { IRadioButtonOption, RadioButtonOptionValue, RadioButtonsLayout } from '../../models/radio-buttons-group';

@Component({
  selector: 'app-radio-buttons-group',
  templateUrl: './radio-buttons-group.component.html',
  styleUrls: ['./radio-buttons-group.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class RadioButtonsGroupComponent {
  @Output() valueChange = new EventEmitter();
  @Input() value: RadioButtonOptionValue;
  @Input() groupName = uniqueId('radio-button-group-');
  @Input() options: IRadioButtonOption<RadioButtonOptionValue>[] = [];
  @Input() layout: RadioButtonsLayout = RadioButtonsLayout.Vertical;
  @ContentChild('optionTemplate') optionTemplate: TemplateRef<any>;

  horizontalLayout = RadioButtonsLayout.Horizontal;

  onOptionClicked(option: IRadioButtonOption<RadioButtonOptionValue>) {
    if (option.disabled) return;
    if (this.value === option.value) return;

    this.onValueChange(option.value);
  }

  private onValueChange(value: RadioButtonOptionValue) {
    this.value = value;
    this.valueChange.emit(this.value);
  }

  trackByFn(_, option: IRadioButtonOption<RadioButtonOptionValue>) {
    return option.label + option.value;
  }
}
