export interface IScanSetting {
  name: string;
  value: string;
  scanSettingType: string;
  values: Array<string>;
  visible?: boolean;
}

export class ScanSetting implements IScanSetting {
  public values: Array<string>;
  public name: string;
  public value: string;
  public scanSettingType: string;
  public visible?: boolean;

  constructor(ss: IScanSetting) {
    this.name = ss.name;
    this.value = ss.value;
    this.scanSettingType = ss.scanSettingType;
    this.values = ss.values.map((v) => v);
    this.visible = typeof ss.visible === 'undefined' ? true : ss.visible;
  }

  clone(): IScanSetting {
    return new ScanSetting(this);
  }

  serializable(): IScanSetting {
    return {
      name: this.name,
      value: this.value,
      scanSettingType: this.scanSettingType,
      values: this.values,
      visible: this.visible,
    };
  }
}
