import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnInit,
  Output,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';

import { Log } from '../../../../Bamba.Web/ClientApp/src/app/blocks/core/log';
import { IFindMetaDataById } from '../../interop/MetaDataService';
import { IFieldOptions } from '../../models/field-definition';
import { TextComponent } from '../text/text.component';
import { SaveLookupsEvent } from './../../models/field-events';
import { LookupMapping, LookupMatch, LookupToBeSaved, MetaDataLookupDataSource } from './../../models/lookup-models';
import { MetaDataValidity } from './../../models/metadata';
import { DelayService } from './../../utils/delay.service';
import { Key } from './../../utils/key-enum';
import { LookupModalService } from './lookup-modal/lookup-modal.service';
@Component({
  selector: 'app-lookup',
  templateUrl: './lookup.component.html',
  styleUrls: ['./lookup.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class LookupComponent extends TextComponent implements OnInit, AfterViewInit {
  @ViewChild('input', { static: true }) input: ElementRef = undefined;

  displayAsList: boolean = false;

  @Input()
  set setValue(value: string) {
    if (value) {
      this.delay.execute(() => {
        this.input.nativeElement.value = value;
        const e: any = {};
        e.keyCode = e.key = Key.Tab;
        this.lookupValue(e);
      }, 50);
      return;
    }
  }

  @Input() findMetaDataService: IFindMetaDataById;
  @Output() setLookupValues = new EventEmitter<SaveLookupsEvent>();

  lookupFieldName: string;
  showModal: boolean;
  matches: Array<LookupMatch> = [];

  set loading(value: boolean) {
    if (!this.lookupModalService.visible) return;

    this.lookupModalService.loading = value;
  }

  private move = false;
  private forward = true;
  private fieldDataSource: MetaDataLookupDataSource;

  isMobileView: boolean;
  lookupModalKey = 'lookupModalKey';
  selectedRowIndex: number;
  autoSelectOneMatch: boolean = true;
  lastSearchText: string;

  constructor(
    public ngxSmartModalService: NgxSmartModalService,
    private toastr: ToastrService,
    private translate: TranslateService,
    private delay: DelayService,
    private lookupModalService: LookupModalService
  ) {
    super(translate);
  }

  ngOnInit() {
    this.fieldDataSource = this.field.datasource as MetaDataLookupDataSource;
    this.displayAsList = this.fieldDataSource.displayLookUpAsList ?? false;
  }

  openLookupFieldSearchModal() {
    this.input.nativeElement.focus();

    this.lookupModalService.show(
      this.value,
      this.matches,
      this.field.placeholder,
      this.lookupModalKey,
      this.findMetaDataService,
      this.selectValue,
      this.lookForMatches
    );
  }

  lookupValue(event?: KeyboardEvent) {
    this.move = false;
    this.forward = true;

    if (event) {
      if (event.key && event.key !== Key.Tab && event.key !== Key.Enter) return;

      if (event.preventDefault) event.preventDefault();
      if (event.stopPropagation) event.stopPropagation();

      if (event.key === Key.Tab) {
        this.move = true;

        if (event.shiftKey) {
          this.forward = false;
        }
      }
    }

    this.value = this.input.nativeElement.value;

    this.lookForMatches(this.value);
  }

  lookForMatches = (searchText: string): void => {
    this.loading = true;

    if (this.lookupModalService.visible && searchText === this.lastSearchText) {
      this.getMatchesSuccess(this.matches);
      return;
    }

    this.lastSearchText = searchText;
    this.fieldDataSource
      .getMatches(searchText)
      .then((matches: LookupMatch[]) => {
        this.getMatchesSuccess(matches);
      })
      .catch((err) => {
        this.loading = false;
        this.toastr.error(this.translate.instant('admin-metadata-lookup.loading-matching-values-error'));
        Log.error('LookupComponent.lookForMatches', err);
      });
  };

  getMatchesSuccess(matches: LookupMatch[]) {
    this.matches = matches;
    this.loading = false;

    if (this.lookupModalService.visible) this.lookupModalService.matches = matches;

    if (matches.length == 1) {
      if (!this.autoSelectOneMatch) return;
      this.selectValue(0);
      this.lookupModalService.close();
    } else if (this.matches.length > 1) {
      if (!this.lookupModalService.visible) this.openLookupFieldSearchModal();
    } else {
      this.toastr.error(this.translate.instant('admin-metadata-lookup.no-matches-found'));
    }
  }

  onBlur(event: any) {
    if (this.lookupModalService.visible || this.value === this.input.nativeElement.value) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }

    this.value = this.input.nativeElement.value;
    if (this.field?.hasValidation) this.setValueAsInvalid();
  }

  onClose() {
    if (this.field?.hasValidation) this.setValueAsInvalid();
  }

  setValueAsInvalid() {
    const lookupMapping = new LookupMapping({
      value: this.value,
      metaDataId: this.fieldDataSource.getId(),
      overwrite: true,
    });

    const lookupsArr = [new LookupToBeSaved(this.findMetaDataService, lookupMapping, MetaDataValidity.notValid)];

    this.setLookupValues.emit(new SaveLookupsEvent(lookupsArr, this.move, this.forward));
  }

  selectValue = (rowIndex: number): void => {
    this.selectedRowIndex = rowIndex;

    const values: LookupMatch = this.matches[this.selectedRowIndex];
    const lookupsArr = values.mappings.map(
      (mapping) => new LookupToBeSaved(this.findMetaDataService, mapping, MetaDataValidity.valid)
    );

    if (values.mappings.length) this.value = values.mappings[0].value;

    this.setLookupValues.emit(new SaveLookupsEvent(lookupsArr, this.move, this.forward));
  };

  setAutoSelect(autoSelect: boolean) {
    this.autoSelectOneMatch = autoSelect;
  }

  onSearchButtonClick = (): void => {
    const e: any = {};
    e.keyCode = e.key = Key.Enter;
    this.lookupValue(e);
  };

  selectListValue(value: IFieldOptions) {
    this.value = value.value.toString();
    const rowIndex = this.matches.findIndex((match) => match.mappings.find((map) => map.value == this.value));
    this.selectValue(rowIndex);
  }

  setLookupRowMatch(matches: Array<LookupMatch>) {
    this.matches = matches;
  }
}
