import { Component, OnInit, Output, ViewChild, EventEmitter, ElementRef } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';
import { Filename } from '../../../blocks/core/fileName';
import { ToastrService } from 'ngx-toastr';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResults } from '../../services/models';
import { ErrorsService } from '../../services/errors.service';
import { MetaDataCollection } from 'shared-code-lib';
import { IItemId } from '../../core/itemActionHandler';

export enum CSVImportType {
  Create = 0,
  Update = 1,
  Delete = 2,
}

@Component({
  selector: 'app-device-csv-import',
  templateUrl: './device-csv-import.component.html',
  styleUrls: ['./device-csv-import.component.scss'],
})
export class DeviceCSVImportComponent implements OnInit {
  @ViewChild(PerfectScrollbarDirective, { static: true }) directiveRef?: PerfectScrollbarDirective;
  @Output() closeModal = new EventEmitter();
  @ViewChild('csvImportInput', { static: true })
  csvImportInput: ElementRef;
  csvFile: any;
  importErrors = [];
  importExtensions = ['txt', 'csv'];
  selectedFileName = '';

  constructor(
    private translateService: TranslateService,
    public sharedDataService: SharedDataService,
    private spinner: SpinnerStateService,
    private hydraApi: HydraApiService,
    private toastr: ToastrService,
    private errorsService: ErrorsService,
    private sharedData: SharedDataService
  ) {}

  ngOnInit(): void {
    this.selectedFileName = `(${this.translateService.instant('csv.no-file-selected')})`;
  }

  handleFileSelect(files: any) {
    if (!files || !files.length) return;

    const file = files[0];

    this.importErrors = [];
    if (!Filename.extensionIsOneOf(file.name, this.importExtensions)) {
      this.importErrors.push('csv.only-csv-and-text');
      this.csvImportInput.nativeElement.value = '';
      return;
    }

    this.csvFile = file;
    this.selectedFileName = file.name;
  }

  close = (): void => {
    this.resetImportModal();
    this.closeModal.emit();
  };

  onImport() {
    if (this.sharedDataService.extraParameters.importType == CSVImportType.Create) {
      this.hydraApi.importDevicesWithCSV(
        this.csvFile,
        this.sharedData.extraParameters?.tenantId,
        this.deviceImportSucceeded,
        this.csvImportFailed
      );
    } else if (this.sharedDataService.extraParameters.importType == CSVImportType.Update) {
      this.hydraApi.updateDevicesWithCSV(this.csvFile, this.deviceImportSucceeded, this.csvImportFailed);
    } else if (this.sharedDataService.extraParameters.importType == CSVImportType.Delete) {
      this.hydraApi.deleteDevicesWithCSV(this.csvFile, this.deviceImportSucceeded, this.csvImportFailed);
    }

    this.resetImportModal();
    this.close();
    this.spinner.show(
      this.translateService.instant('device-import-csv.import-spinner-message'),
      document.documentElement
    );
  }

  deviceImportSucceeded = (result: ApiResults) => {
    this.spinner.hide();

    const items: IItemId[] = [];

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      items,
      new MetaDataCollection(),
      this.onDocumentConversionRequestSucceeded
    );

    if (result.success) {
      this.toastr.success(this.translateService.instant('device-import-csv.import-success-message'));
    } else {
      this.spinner.hide();
      this.errorsService.showErrorsModal(result.errors, 'device-import-csv.import-error-dialog-title');
    }
  };

  onDocumentConversionRequestSucceeded = (): void => {};

  csvImportFailed = (err: any) => {
    this.close();
    this.spinner.hide();
    this.toastr.error(this.translateService.instant(err.message));
  };

  resetImportModal = () => {
    this.csvFile = null;
    this.csvImportInput.nativeElement.value = '';
    this.importErrors = [];
  };
}
