import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class WidgetsService {
  private _reloadData = new Subject<string>();
  onReloadData = this._reloadData.asObservable();

  constructor() {}

  reloadData(relatedWidgets: Array<string>) {
    relatedWidgets.forEach((widget) => this._reloadData.next(widget));
  }
}
