import { Filter, IFilter } from './filter';

class FilterByCoverPage extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByCoverPage';
  }
}

class FilterByDocumentsCount extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByDocumentsCount';
  }
}

class FilterByAuditStatus extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByAuditStatus';
  }
}

class FilterByRecipients extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByRecipients';
  }
}

export class SentFaxesChartFilters {
  public static Create = (filter: IFilter): Filter | null => {
    if (filter.id == 'BambaAdministratorApplication-Upland.Bamba.Core.Widgets.Filters.FilterByCoverPage') {
      return new FilterByCoverPage(filter);
    }

    if (filter.id == 'BambaAdministratorApplication-Upland.Bamba.Core.Widgets.Filters.FilterByDocumentsCount') {
      return new FilterByDocumentsCount(filter);
    }

    if (filter.id == 'BambaAdministratorApplication-Upland.Bamba.Core.Widgets.Filters.FilterByStatus') {
      return new FilterByAuditStatus(filter);
    }

    if (filter.id == 'BambaAdministratorApplication-Upland.Bamba.Core.Widgets.Filters.FilterByRecipients') {
      return new FilterByRecipients(filter);
    }

    return null;
  };
}
