import { ChartType, LayoutPosition } from 'chart.js';
import { IColumn, IDefaultColumn } from 'shared-code-lib';
import { Action, IAction, IProduct, Product, SortBy } from '../services/models';
import { Filter, IFilter, IFilterValue } from './filter';
import { FilterFactory } from './filter-factory';

export enum WidgetWidth {
  Full = 0,
  Half = 1,
}

export enum WidgetType {
  SummaryCount = 0,
  ListView = 1,
  Graph = 2,
  FileDrop = 3,
  Meter = 4,
  QuickDrop = 5,
  Donut = 6,
  Activity = 7,
  Chart = 8,
}

export interface ITabItem {
  itemId: string;
  widgetId: string;
  primaryColumn: number;
  row: number;
  column: number;
  height: number;
}

export class TabItem implements ITabItem {
  private static _id = 0;

  public itemId: string;
  public widgetId: string;
  public primaryColumn: number;
  public row: number;
  public column: number;
  public height: number;

  public id: number;

  constructor(initializer: ITabItem) {
    this.itemId = initializer ? initializer.itemId : '';
    this.widgetId = initializer ? initializer.widgetId : '';
    this.primaryColumn = initializer ? initializer.primaryColumn : 0;
    this.row = initializer ? initializer.row : 0;
    this.column = initializer ? initializer.column : 0;
    this.height = initializer ? initializer.height : 0;

    this.id = TabItem._id++;
  }

  serializable(): ITabItem {
    return {
      itemId: this.itemId,
      widgetId: this.widgetId,
      primaryColumn: this.primaryColumn,
      row: this.row,
      column: this.column,
      height: Math.round(this.height),
    };
  }
}

export interface IHomePageTab {
  id: string;
  order: number;
  title: string;
  items: Array<ITabItem>;
}

export class HomePageTab implements IHomePageTab {
  public id: string;
  public order: number;
  public title: string;
  public items: Array<TabItem>;
  public isNew: boolean;
  public selected: boolean;

  constructor(initializer?: IHomePageTab) {
    this.id = initializer ? initializer.id : '';
    this.title = initializer ? initializer.title : '';
    this.items = initializer ? initializer.items.map((i) => new TabItem(i)) : new Array<TabItem>();
    this.order = initializer ? initializer.order : 0;
  }

  public serializable(): IHomePageTab {
    return {
      id: this.id,
      title: this.title,
      order: this.order,
      items: this.items.map((i) => i.serializable()),
    };
  }
}

export interface IWidget {
  id: string;
  title: string;
  defaultHeight: number;
  minHeight: number;
  width: WidgetWidth;
  fixedHeight: boolean;
  widgetType: WidgetType;
  icon: string;
  relatedWidgetTopic: string;
  relatedWidgetTopics: Array<string>;
  product: IProduct;
  actions: Array<IAction>;
  allowsMaximize: boolean;
  autoRefreshIntervalSeconds: number;
}

export class Widget implements IWidget {
  public id: string;
  public title: string;
  public defaultHeight: number;
  public minHeight: number;
  public width: WidgetWidth;
  public fixedHeight: boolean;
  public widgetType: WidgetType;
  public icon: string;
  public relatedWidgetTopic: string;
  public relatedWidgetTopics: Array<string> = [];
  public product: Product;
  public actions: Array<Action>;
  public allowsMaximize: boolean;
  public autoRefreshIntervalSeconds: number;

  constructor(initializer: IWidget) {
    this.id = initializer ? initializer.id : '';
    this.title = initializer ? initializer.title : '';
    this.defaultHeight = initializer ? initializer.defaultHeight : 250;
    this.minHeight = initializer ? initializer.minHeight : 250;
    this.width = initializer ? initializer.width : WidgetWidth.Full;
    this.fixedHeight = initializer ? initializer.fixedHeight : true;
    this.widgetType = initializer ? initializer.widgetType : WidgetType.SummaryCount;
    this.icon = initializer ? initializer.icon : '';
    this.relatedWidgetTopic = initializer ? initializer.relatedWidgetTopic : '';
    this.relatedWidgetTopics = initializer ? initializer.relatedWidgetTopics : [];
    this.allowsMaximize = initializer ? initializer.allowsMaximize : false;
    this.product = initializer && initializer.product ? new Product(initializer.product) : null;
    this.autoRefreshIntervalSeconds = initializer ? initializer.autoRefreshIntervalSeconds : null;
    this.actions =
      initializer && initializer.actions
        ? initializer.actions.map(
            (a) =>
              new Action(
                a.id,
                a.name,
                a.url,
                a.icon,
                a.iconSelected,
                a.selectionType,
                a.type,
                a.confirmationText,
                a.confirmationButtonText,
                a.leftNavRoute,
                a.order,
                a.settingsCategory,
                a.executeWhen
              )
          )
        : new Array<Action>();
  }

  static create(initializer: IWidget) {
    if (initializer.widgetType === WidgetType.FileDrop) return new FileDropWidget(initializer);
    if (initializer.widgetType === WidgetType.SummaryCount) return new SummaryCountWidget(initializer);
    if (initializer.widgetType === WidgetType.ListView) return new ListViewWidget(initializer);
    if (initializer.widgetType === WidgetType.Meter) return new MeterWidget(initializer);
    if (initializer.widgetType === WidgetType.QuickDrop) return new QuickDropWidget(initializer);
    if (initializer.widgetType === WidgetType.Donut) return new DonutWidget(initializer);
    if (initializer.widgetType === WidgetType.Activity) return new ActivityWidget(initializer);
    if (initializer.widgetType === WidgetType.Chart) return new ChartWidget(initializer);

    return new Widget(initializer);
  }
}

export enum WidgetSummaryStyle {
  Nominal = 0,
  Warning = 1,
  Error = 2,
}

export class WidgetSummary {
  text: string;
  count: number;
  route: string;
  style: WidgetSummaryStyle;
}

export class SummaryCountWidget extends Widget {
  constructor(initializer: any) {
    super(initializer);
  }
}

export class FileDropWidget extends Widget {
  public prompts: string[];

  constructor(initializer: any) {
    super(initializer);

    this.prompts = initializer.prompts;
  }
}

export class QuickDropWidget extends Widget {
  public route: string;
  public text: string;

  constructor(initializer: any) {
    super(initializer);

    this.route = initializer.route;
    this.text = initializer.text;
  }
}

export enum ListViewMode {
  Tabs = 0,
  HorizontalBarChart = 1,
  BreadCrumbs = 2,
  VerticalBarChart = 3,
  Donut = 4,
}

export interface IListViewChartData {}

export class ChartDataGroup {
  public label: string;
  public count: number;
  public filterValues: Array<IFilterValue>;
}

export interface IChartData {
  filterValues: Array<IFilterValue>;
}

export class ListViewChartData implements IChartData {
  public label: string;
  public count: number;
  public groups: Array<ChartDataGroup>;
  public filterValues: Array<IFilterValue>;
}

export class ListViewDonutChartData implements IListViewChartData {
  public centerCount: number;
  public centerLabel: string;
  public chunks: Array<DonutChunk>;
  public filterValues: Array<IFilterValue>;
}

export class ListViewBarChartData implements IListViewChartData {
  public data: Array<ListViewChartData>;
}

export class ListView {
  public id: string;
  public folderId: string;
  public displayName: string;
  public filterValues: Array<IFilterValue> = [];
  public columns: Array<IColumn>;
  public defaultColumns: Array<IDefaultColumn>;
  public defaultSortByColumn: SortBy;
  public showBreadcrumb: boolean;
}

export class ListViewWidget extends Widget {
  public views: Array<ListView> = [];
  public productId: string;
  public mode: ListViewMode;
  public filters: Array<Filter>;
  public hideSingleTabHeader: boolean;

  constructor(initializer: any) {
    super(initializer);

    if (!initializer.views) throw new Error('Invalid Widget Initializer');
    if (!initializer.productId) throw new Error('Invalid Widget Initializer');

    this.productId = initializer.productId;
    this.views = initializer.views;
    this.mode = initializer.mode;
    this.hideSingleTabHeader = initializer.hideSingleTabHeader;

    this.filters = initializer.filters.map((f) => FilterFactory.Create(f));
  }
}

interface IMeter {
  usageColor: string;
  remainingColor: string;
  label: string;
}

export class MeterWidgetData {
  position: number;
  positionUsedText: string;
  positionRemainingText: string;
  rangeMinimum: number;
  rangeMaximum: number;
  rangeMinimumText: string;
  rangeMaximumText: string;
}

export class MeterWidget extends Widget implements IMeter {
  usageColor: string;
  remainingColor: string;
  label: string;
  constructor(initializer: any) {
    super(initializer);

    if (!initializer.usageColor) throw new Error('Invalid Widget Initializer');
    if (!initializer.remainingColor) throw new Error('Invalid Widget Initializer');
    if (!initializer.label) throw new Error('Invalid Widget Initializer');

    this.usageColor = initializer.usageColor;
    this.remainingColor = initializer.remainingColor;
    this.label = initializer.label;
  }
}

export class ChartRequestData {
  filters: Array<IFilterValue>;
}

export class DonutChunk implements IChartData {
  label: string;
  count: number;
  public filterValues: Array<IFilterValue>;
}

export class DonutWidgetData {
  centerCount: number;
  chunks: Array<DonutChunk>;
}

interface IDonutWidget {
  centerLabel: string;
}

export class DonutWidget extends Widget implements IDonutWidget {
  public centerLabel: string;

  constructor(initializer: any) {
    super(initializer);

    if (!initializer.centerLabel) throw new Error('Invalid Widget Initializer');

    this.centerLabel = initializer.centerLabel;
  }
}

interface IActivityWidget {
  filters: Array<IFilter>;
  groupBy: Array<IFilter>;
}

export class ActivityWidget extends Widget implements IActivityWidget {
  public filters: Array<IFilterValue>;
  public groupBy: Array<IFilterValue>;

  constructor(initializer: any) {
    super(initializer);

    if (!initializer.filters) throw new Error('Invalid Widget Initializer');
    if (!initializer.groupBy) throw new Error('Invalid Widget Initializer');

    this.filters = initializer.filters.map((f) => FilterFactory.Create(f));
    this.groupBy = initializer.groupBy.map((f) => FilterFactory.Create(f));
  }
}

export class ChartWidget extends Widget {
  public filters: Array<Filter>;
  public chartType: ChartType;
  public legend: boolean;
  public legendPosition: LayoutPosition;

  constructor(initializer: any) {
    super(initializer);

    if (!initializer.filters) throw new Error('Invalid Widget Initializer');

    this.filters = initializer.filters.map((f) => FilterFactory.Create(f));
    this.chartType = initializer.chartType;
    this.legend = initializer.legend;
    this.legendPosition = initializer.legendPosition;
  }
}
