import { Subscription } from 'rxjs';
import { CoverPage } from '../models/cover-page';
import { Contact } from '../models/interfax/contact';
import { ContactList } from '../models/interfax/contactlist';

export enum ContactListSearchType {
  Auto = 0,
  Name = 1,
  FaxNumber = 2,
  Company = 3,
}
export enum ContactListIds {
  Any = '-1',
}

export interface IInterFAXService {
  searchContactLists(
    searchQuery: string,
    searchType: ContactListSearchType,
    contactListId: ContactListIds | string,
    successCallback: (c: Contact[]) => void,
    failureCallBack: (err: any) => void
  ): void;
  getContactLists(successCallBack: (cl: Array<ContactList>) => void, failureCallBack: (err: any) => void): Subscription;
  getAccountCoverpages(successCallBack: (coverPages: CoverPage[]) => void, failureCallBack: (err: any) => void);
  getUserCoverpages(
    username: string,
    successCallBack: (coverPages: CoverPage[]) => void,
    failureCallBack: (err: any) => void
  );
}
