import { Directive, OnInit, ElementRef, Input } from '@angular/core';

import { DelayService } from 'shared-code-lib';

declare const $: any;

@Directive({
  selector: '[appDndHasInput]',
})
export class DndHasInputDirective implements OnInit {
  @Input() appDndHasInput: any;

  constructor(private elementRef: ElementRef, private delay: DelayService) {}

  ngOnInit() {
    this.delay.execute(() => {
      const that = this;
      const dndElement = $(this.elementRef.nativeElement);
      const childTextInputs = dndElement.find('input[type=text]');

      this.appDndHasInput.sortable = false;

      dndElement.mousedown(function (event: Event) {
        const target = event.target as HTMLElement;
        if (target.classList.contains('icomoon-grip-small')) {
          that.appDndHasInput.sortable = true;
          return;
        }

        that.appDndHasInput.sortable = false;
      });

      childTextInputs.each(function () {
        const $this = $(this);
        $this.focus(function (event: Event) {
          that.appDndHasInput.sortable = false;
          if (!$this.is(':focus')) {
            $this.focus();
          }
        });

        $this.blur(function (event: Event) {
          that.appDndHasInput.sortable = true;
        });
      });
    }, 1000);
  }
}
