import { Log } from '../core/log';
import { Filter, IFilter } from './filter';

class FilterByOptions extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByOptionsComponent';
  }
}

class FilterByUsername extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByFaxUserUsername';
  }
}

class FilterByFaxNumber extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByFaxNumber';
  }
}

class ByInterFAXServices extends Filter {
  constructor(filter: IFilter) {
    super(filter);
  }

  public getComponent(): string {
    return 'FilterByInterFAXServices';
  }
}

export class FaxUsersFilters {
  public static Create = (filter: IFilter): Filter => {
    Log.enter('FaxUsersFilters.Create', filter);

    if (filter.id == 'InterFAX-Upland.Bamba.InterFAX.Administration.FaxUsers.Filtering.FilterByStatus') {
      return new FilterByOptions(filter);
    } else if (filter.id === 'InterFAX-Upland.Bamba.InterFAX.Administration.FaxUsers.Filtering.FilterByUsername') {
      return new FilterByUsername(filter);
    } else if (filter.id === 'InterFAX-Upland.Bamba.InterFAX.Administration.FaxUsers.Filtering.FilterByFaxNumber') {
      return new FilterByFaxNumber(filter);
    } else if (filter.id === 'InterFAX-Upland.Bamba.InterFAX.Administration.FaxUsers.Filtering.FilterByServices') {
      return new ByInterFAXServices(filter);
    }

    return null;
  };
}
