import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import {
  ColumnDisplayType,
  FieldDefinition,
  FixedDataSource,
  ICombinedColumn,
  IFieldOptions,
  MetaDataType,
  Role,
  TableItem,
} from 'shared-code-lib';
import { WorkflowAllowedAccessFilter } from '../../models/workflow-access';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResult, User } from '../../services/models';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-view-workflow-permissions-modal',
  templateUrl: './view-workflow-permissions-modal.component.html',
  styleUrls: ['./view-workflow-permissions-modal.component.scss'],
})
export class ViewWorkflowPermissionsComponent implements OnInit {
  @Output() closeModal = new EventEmitter();

  items: TableItem[] = [];
  columns: Array<ICombinedColumn>;

  filterTypeField: FieldDefinition;

  filterUserField: FieldDefinition;

  filterRoleField: FieldDefinition;

  selectedType: string = 'Users';
  selectedRole = '';
  selectedUser = '';

  constructor(
    private translate: TranslateService,
    private spinnerService: SpinnerStateService,
    private hydraApi: HydraApiService
  ) {}

  ngOnInit(): void {
    this.createFields();
    this.columns = this.getColumns();
    this.getWorkflowAccess();
  }

  createFields = () => {
    const options = new Array<IFieldOptions>();
    options.push({ value: 'Roles', name: this.translate.instant('view-workflow-permissions-modal.roles') });
    options.push({ value: 'Users', name: this.translate.instant('view-workflow-permissions-modal.users') });

    const datasource = new FixedDataSource(options);
    this.filterTypeField = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translate.instant('view-workflow-permissions-modal.type'),
      required: true,
      datasource: datasource,
    });

    const roleOptions = new Array<IFieldOptions>();

    roleOptions.push({ value: '', name: this.translate.instant('view-workflow-permissions-modal.all-roles') });

    this.filterRoleField = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translate.instant('view-workflow-permissions-modal.roles'),
      required: true,
      datasource: new RoleDataSource(this.hydraApi, roleOptions),
    });

    const userOptions = new Array<IFieldOptions>();

    userOptions.push({ value: '', name: this.translate.instant('view-workflow-permissions-modal.all-users') });

    this.filterUserField = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translate.instant('view-workflow-permissions-modal.users'),
      required: true,
      datasource: new UserDataSource(this.hydraApi, userOptions),
    });
  };

  close = (): void => this.closeModal.emit();

  private getSpinnerElement() {
    return document.querySelector('.WorkflowPermissions .nsm-content') as HTMLElement;
  }

  showSpinner = (): void => {
    this.spinnerService.show(
      this.translate.instant('view-workflow-permissions-modal.loading'),
      this.getSpinnerElement()
    );
  };

  onFilterTypeChanged = (value: string) => {
    this.selectedType = value;
    this.selectedRole = '';
    this.selectedUser = '';

    this.getWorkflowAccess();
  };

  getWorkflowAccess = () => {
    this.showSpinner();

    const allowedAccessFilter = new WorkflowAllowedAccessFilter();
    allowedAccessFilter.type = this.selectedType;
    allowedAccessFilter.roleId = this.selectedRole;
    allowedAccessFilter.userId = this.selectedUser;

    this.hydraApi.getWorkflowAllowedAccess(allowedAccessFilter, this.onWorkflowAccessLoaded, this.onFailed);
  };

  onWorkflowAccessLoaded = (result: ApiResult) => {
    this.spinnerService.hide();

    if (!result.success) {
      return;
    }

    this.items = this.createItems(result.object);
  };

  onFailed = (err) => {
    this.spinnerService.hide();
    console.log(err);
  };

  createItems = (data: Array<any>): Array<TableItem> => {
    const items = new Array<TableItem>();

    data.forEach((element) => {
      const tableItem = new TableItem(element, this.columns, this.translate);

      items.push(tableItem);
    });

    return items;
  };

  getColumns(): Array<ICombinedColumn> {
    const columns: Array<ICombinedColumn> = [];

    columns.push(this.createColumn('workflowName', ColumnDisplayType.Text, 50, false));
    columns.push(this.createColumn('allowedAction', ColumnDisplayType.Text, 50, false));
    columns.push(this.createColumn('roles', ColumnDisplayType.Text, 50, false));

    return columns;
  }

  createColumn(field: string, displayType: number, width: number, stretch: boolean) {
    return {
      id: 'column_' + field,
      width: width,
      stretch: stretch,
      displayType: displayType,
      headerImage: '',
      headerText: this.translate.instant(`view-workflow-permissions-modal.${field}`),
      itemProperty: field,
      columnName: field,
      sortable: false,
      sortByFieldName: '',
      invertBooleanValue: false,
    };
  }
}

class UserDataSource extends FixedDataSource {
  constructor(
    private hydraApiService: HydraApiService,
    private preOptions: Array<IFieldOptions> = []
  ) {
    super();
  }

  successCallBack: (items: IFieldOptions[]) => void;
  failureCallBack: (err: any) => void;

  getItems(
    startsWith: string,
    currentValue: string,
    successCallBack: (items: IFieldOptions[]) => void,
    failureCallBack: (err: any) => void
  ): void {
    this.successCallBack = successCallBack;
    this.failureCallBack = failureCallBack;

    this.hydraApiService.getUsers(this.usersLoaded, this.failed);
  }

  usersLoaded = (users: Array<User>): void => {
    const options = [...this.preOptions];

    users.forEach((u) => options.push({ name: u.name, value: u.id }));

    this.successCallBack(options);
  };

  failed = (err): void => {
    this.failureCallBack(err);
  };
}

export class RoleDataSource extends FixedDataSource {
  constructor(
    private hydraApiService: HydraApiService,
    private preOptions: Array<IFieldOptions> = []
  ) {
    super();
  }

  successCallBack: (items: IFieldOptions[]) => void;
  failureCallBack: (err: any) => void;

  getItems(
    startsWith: string,
    currentValue: string,
    successCallBack: (items: IFieldOptions[]) => void,
    failureCallBack: (err: any) => void
  ): void {
    this.successCallBack = successCallBack;
    this.failureCallBack = failureCallBack;

    this.hydraApiService.getRoles(this.rolesLoaded, this.failed);
  }

  rolesLoaded = (roles: Array<Role>): void => {
    const options = [...this.preOptions];

    roles.forEach((r) => options.push({ name: r.name, value: r.id }));

    this.successCallBack(options);
  };

  failed = (err): void => {
    this.failureCallBack(err);
  };
}
