import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { Router, NavigationStart } from '@angular/router';
import { filter, pairwise } from 'rxjs/operators';

@Injectable({
  providedIn: 'root',
})
export class BackButtonService {
  previousURL = '';
  isModuleLoading = false;

  onPreviousURLChanged = new BehaviorSubject('');
  moduleLoadingChanged = new BehaviorSubject(false);

  constructor(private router: Router) {}

  preventBackButton(cb?: () => void) {
    history.pushState(null, null, location.href);
    window.onpopstate = () => {
      history.go(1);

      if (cb) {
        cb();
      }
    };
  }

  removeBackButtonListener() {
    window.onpopstate = null;
  }

  setPreviousURL(url: string) {
    this.previousURL = url;
    this.onPreviousURLChanged.next(url);
  }

  setListenerForPreviousURLChanging() {
    this.router.events
      .pipe(
        filter((evt: any) => evt instanceof NavigationStart),
        pairwise()
      )
      .subscribe((events: NavigationStart[]) => {
        const previousURL = events[0].url;
        this.setPreviousURL(previousURL);
      });
  }

  setModuleLoading(isLoading: boolean) {
    this.isModuleLoading = isLoading;
    this.moduleLoadingChanged.next(isLoading);
  }
}
