import { Component, ElementRef, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { FieldDefinition, FixedDataSource, IFieldOptions, MetaDataCollection, MetaDataType } from 'shared-code-lib';
import { JiraIssue } from '../../models/jira-issue';
import { HydraApiService } from '../../services/hydra-api.service';
import { ApiResult } from '../../services/models';
import { SharedDataService } from '../../services/shared-data.service';
import { SpinnerStateService } from '../../services/spinner-state.service';

@Component({
  selector: 'app-add-database-resolved-ticket',
  templateUrl: './add-database-resolved-ticket.component.html',
  styleUrls: ['./add-database-resolved-ticket.component.scss'],
})
export class AddDatabaseResolvedTicketComponent implements OnInit {
  @Output() closeModal = new EventEmitter();
  @ViewChild('sqlFileInput', { static: true })
  fileInputRef: ElementRef;
  fileInput: HTMLInputElement;
  sqlFile: File;
  base64FileData: string;
  sqlFilename: string;

  componentNames: string = '';
  componentIds = [];

  jiraIdField: FieldDefinition;
  databaseField: FieldDefinition;
  changeTypeField: FieldDefinition;
  switchesField: FieldDefinition;
  jiraCommentField: FieldDefinition;

  jiraId: string;
  database: string;
  changeType: string;
  switches: string;
  jiraComment: string;

  jiraIssue: JiraIssue = null;
  errors = [];

  constructor(
    private translateService: TranslateService,
    private sharedDataService: SharedDataService,
    private spinnerService: SpinnerStateService,
    private hydraApi: HydraApiService
  ) {}

  ngOnInit(): void {
    this.fileInput = this.fileInputRef.nativeElement;

    this.componentIds = this.sharedDataService.extraParameters.items.map((i) => i.id);
    const names = this.sharedDataService.extraParameters.items.map((i) => i.name);
    this.componentNames = names.join(', ');

    this.createFields();
  }

  handleFileSelect = (evt: any): void => {
    if (this.fileInput.files.length == 0) return;
    this.readFile(this.fileInput.files[0]);
    this.sqlFile = this.fileInput.files[0];
  };

  readFile = (file: File): void => {
    const reader = new FileReader();
    reader.onload = (event: any) => {
      this.base64FileData = event.target.result.split(',')[1];
      this.sqlFilename = file.name;
    };
    reader.readAsDataURL(file);
  };

  databaseFieldDataSource = (): FixedDataSource => {
    const options = new Array<IFieldOptions>();

    options.push({ name: 'INTERFAX75', value: 'INTERFAX75' });
    options.push({ name: 'HS', value: 'HS' });
    options.push({ name: 'PIS', value: 'PIS' });
    options.push({ name: 'Logs', value: 'Logs' });
    options.push({ name: 'Archive', value: 'Archive' });

    return new FixedDataSource(options);
  };

  changeTypeFieldDataSource = (): FixedDataSource => {
    const options = new Array<IFieldOptions>();

    options.push({ name: 'Alter Existing Table', value: 'Alter Existing Table' });
    options.push({ name: 'Add New Table', value: 'Add New Table' });
    options.push({ name: 'Alter Existing Stored Procedure', value: 'Alter Existing Stored Procedure' });
    options.push({ name: 'Add New Stored Procedure', value: 'Add New Stored Procedure' });

    return new FixedDataSource(options);
  };

  switchesFieldDataSource = (): FixedDataSource => {
    const options = new Array<IFieldOptions>();

    options.push({ name: 'None (MAIN only)', value: 'None (MAIN only)' });
    options.push({ name: 'Replicate From Main to Switch', value: 'Replicate From Main to Switch' });
    options.push({ name: 'Independent', value: 'Independent' });

    return new FixedDataSource(options);
  };

  createFields = () => {
    this.jiraIdField = new FieldDefinition({
      type: MetaDataType.Text,
      placeholder: this.translateService.instant('add-resolved-ticket.jira-id-placeholder'),
      required: true,
    });

    this.databaseField = new FieldDefinition({
      type: MetaDataType.List,
      placeholder: this.translateService.instant('add-resolved-ticket.database'),
      datasource: this.databaseFieldDataSource(),
      required: true,
    });

    this.changeTypeField = new FieldDefinition({
      type: MetaDataType.List,
      placeholder: this.translateService.instant('add-resolved-ticket.changeType'),
      datasource: this.changeTypeFieldDataSource(),
      required: true,
    });

    this.switchesField = new FieldDefinition({
      type: MetaDataType.List,
      placeholder: this.translateService.instant('add-resolved-ticket.switches'),
      datasource: this.switchesFieldDataSource(),
      required: true,
    });

    this.jiraCommentField = new FieldDefinition({
      type: MetaDataType.LargeText,
      placeholder: this.translateService.instant('add-resolved-ticket.comment-placeholder'),
      required: false,
    });
  };

  verify = () => {
    this.errors = [];
    this.jiraIssue = null;
    this.showSpinner();
    this.hydraApi.getJiraIssue(this.jiraId, true, this.onGetJiraTicketSucceeded, this.onGetJiraTicketFailed, false);
  };

  addTicket = () => {
    this.errors = [];
    this.showSpinner();

    if (this.database == null)
      this.errors.push(this.translateService.instant('add-resolved-ticket.errors.database-mandatory'));
    if (this.changeType == null)
      this.errors.push(this.translateService.instant('add-resolved-ticket.errors.changeType-mandatory'));
    if (this.switches == null)
      this.errors.push(this.translateService.instant('add-resolved-ticket.errors.switches-mandatory'));
    if (!this.sqlFile)
      this.errors.push(this.translateService.instant('add-resolved-ticket.errors.sqlScript-mandatory'));

    if (this.errors.length) {
      this.spinnerService.hide();
      return false;
    }

    const args = new MetaDataCollection();

    args.set('isDatabaseTicket', 'true');
    args.set('jiraid', this.jiraIssue.id);
    args.set('database', this.database);
    args.set('changeType', this.changeType);
    args.set('switches', this.switches);
    args.set('sqlScript', this.base64FileData);
    args.set('sqlFilename', this.sqlFilename);
    args.set('comment', this.jiraComment);

    this.sharedDataService.actionHandler.invokeEx(
      this.sharedDataService.folderId,
      this.sharedDataService.action,
      this.componentIds,
      args,
      this.onAddTicketSucceeded,
      this.onAddTicketFailed
    );
    return false;
  };

  onGetJiraTicketSucceeded = (result: ApiResult) => {
    if (result.success) {
      this.jiraIssue = result.object;
      this.spinnerService.hide();
    } else {
      this.onGetJiraTicketFailed(result.errors);
    }
  };

  onGetJiraTicketFailed = (errors: any[]) => {
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  onAddTicketSucceeded = (): void => {
    this.spinnerService.hide();
    this.close();
  };

  onAddTicketFailed = (errors: any[]): void => {
    this.jiraIssue = null;
    this.spinnerService.hide();
    this.errors = errors.map((e) => e);
  };

  close = (): void => this.closeModal.emit();

  private getSpinnerElement(): HTMLElement {
    return document.querySelector('.add-database-resolved-ticket .nsm-content') as HTMLElement;
  }

  showSpinner = (): void => {
    this.spinnerService.show(this.translateService.instant('add-resolved-ticket.loading'), this.getSpinnerElement());
  };
}
